static NSString *ToNSString(const std::string &s)
{
    return [NSString stringWithUTF8String:s.c_str()];
}

static void NotifyMainRTaskAvailable()
{
    if (g_mainRNotifyPath.empty()) {
        return;
    }
    int fd = open(g_mainRNotifyPath.c_str(), O_WRONLY | O_NONBLOCK);
    if (fd < 0) {
        return;
    }
    const char byte = '1';
    (void)write(fd, &byte, 1);
    close(fd);
}

static void QueueLinearGLMMainRTask(const MainRLinearGLMTask &task)
{
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        g_pendingLinearGLMTasks.erase(
            std::remove_if(g_pendingLinearGLMTasks.begin(),
                           g_pendingLinearGLMTasks.end(),
                           [&](const MainRLinearGLMTask &pending) {
                               return pending.group == task.group;
                           }),
            g_pendingLinearGLMTasks.end());
        g_pendingLinearGLMTasks.push_back(task);
    }
    NotifyMainRTaskAvailable();
}

static void QueueModelTrellisMainRTask(const MainRModelTrellisTask &task)
{
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        g_pendingModelTrellisTasks.erase(
            std::remove_if(g_pendingModelTrellisTasks.begin(), g_pendingModelTrellisTasks.end(),
                           [&](const MainRModelTrellisTask &pending) { return pending.id == task.id; }),
            g_pendingModelTrellisTasks.end());
        g_pendingModelTrellisTasks.push_back(task);
    }
    NotifyMainRTaskAvailable();
}

static void QueueRegressionComparisonMainRTask(const MainRRegressionComparisonTask &task)
{
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        g_pendingRegressionComparisonTasks.push_back(task);
    }
    NotifyMainRTaskAvailable();
}

static void QueueGeneralizedGLMMainRTask(const rlispstat::core::GeneralizedGLMState &state)
{
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        g_pendingGeneralizedGLMTasks.erase(
            std::remove_if(g_pendingGeneralizedGLMTasks.begin(),
                           g_pendingGeneralizedGLMTasks.end(),
                           [&](const MainRGeneralizedGLMTask &task) {
                               return task.id == state.id;
                           }),
            g_pendingGeneralizedGLMTasks.end());
        g_pendingGeneralizedGLMTasks.push_back({
            state.id,
            state.group,
            state.response,
            state.family,
            state.link,
            state.scope,
            state.terms,
            state.termTypes,
            state.binaryRegression,
            state.responseCodingExplicit ? state.responseCoding.eventValue : "",
            state.responseCodingExplicit ? state.responseCoding.referenceValue : "",
            RowsForCapturedAnalysisScope(state.dataScope, state.dataScopeCaptured)
        });
    }
    NotifyMainRTaskAvailable();
}

