struct PlotThemeStyle {
    NSColor *background;
    NSColor *panel;
    NSColor *minorGrid;
    NSColor *majorGrid;
    NSColor *axis;
    NSColor *text;
    NSColor *mutedText;
    NSColor *geomFill;
    NSColor *geomStroke;
    NSColor *accent;
    NSColor *accent2;
    NSColor *markFill;
    NSColor *markStroke;
    NSColor *selectedMarkFill;
    NSColor *selectedMarkStroke;
    NSColor *auxiliary;
    NSColor *reference;
    NSColor *smooth;
    bool showMinorGrid;
    bool showPanelBorder;
    bool coordinatedMarks;
    bool hollowUnselectedMarks;
    bool crossUnselectedMarks;
    bool squareSelectedMarks;
    double selectedMarkScale;
    double selectedMarkStrokeWidth;
};

static NSColor *ColorFromPlotRGBA(const rlispstat::core::PlotRGBA &color)
{
    return [NSColor colorWithCalibratedRed:(CGFloat)color.r
                                     green:(CGFloat)color.g
                                      blue:(CGFloat)color.b
                                     alpha:(CGFloat)color.a];
}

static PlotThemeStyle PlotThemeStyleFromSpec(const rlispstat::core::PlotThemeStyleSpec &spec)
{
    return {
        ColorFromPlotRGBA(spec.background),
        ColorFromPlotRGBA(spec.panel),
        ColorFromPlotRGBA(spec.minorGrid),
        ColorFromPlotRGBA(spec.majorGrid),
        ColorFromPlotRGBA(spec.axis),
        ColorFromPlotRGBA(spec.text),
        ColorFromPlotRGBA(spec.mutedText),
        ColorFromPlotRGBA(spec.geomFill),
        ColorFromPlotRGBA(spec.geomStroke),
        ColorFromPlotRGBA(spec.accent),
        ColorFromPlotRGBA(spec.accent2),
        ColorFromPlotRGBA(spec.markFill),
        ColorFromPlotRGBA(spec.markStroke),
        ColorFromPlotRGBA(spec.selectedMarkFill),
        ColorFromPlotRGBA(spec.selectedMarkStroke),
        ColorFromPlotRGBA(spec.auxiliary),
        ColorFromPlotRGBA(spec.reference),
        ColorFromPlotRGBA(spec.smooth),
        spec.showMinorGrid,
        spec.showPanelBorder,
        spec.coordinatedMarks,
        spec.hollowUnselectedMarks,
        spec.crossUnselectedMarks,
        spec.squareSelectedMarks,
        spec.selectedMarkScale,
        spec.selectedMarkStrokeWidth
    };
}

static PlotThemeStyle CurrentPlotThemeStyle()
{
    extern thread_local std::optional<std::string> g_plotThemeNameOverride;
    return PlotThemeStyleFromSpec(
        rlispstat::core::PlotThemeStyleForName(
            g_plotThemeNameOverride.value_or(MacCommandDispatcher().plotTheme())));
}

thread_local std::optional<std::string> g_plotThemeNameOverride;

class PlotThemeOverrideScope {
public:
    explicit PlotThemeOverrideScope(NSString *theme)
        : previous_(g_plotThemeNameOverride)
    {
        if ([theme length]) g_plotThemeNameOverride = std::string([theme UTF8String]);
    }
    ~PlotThemeOverrideScope() { g_plotThemeNameOverride = previous_; }
private:
    std::optional<std::string> previous_;
};

static NSBezierPath *PlotThemeMarkPath(const PlotThemeStyle &theme, NSPoint center,
                                       CGFloat radius, bool selected)
{
    if (selected && theme.squareSelectedMarks) {
        return [NSBezierPath bezierPathWithRect:NSMakeRect(
            center.x - radius, center.y - radius, radius * 2.0, radius * 2.0)];
    }
    if (!selected && theme.crossUnselectedMarks) {
        radius *= 0.62;
        NSBezierPath *cross = [NSBezierPath bezierPath];
        [cross moveToPoint:NSMakePoint(center.x - radius, center.y)];
        [cross lineToPoint:NSMakePoint(center.x + radius, center.y)];
        [cross moveToPoint:NSMakePoint(center.x, center.y - radius)];
        [cross lineToPoint:NSMakePoint(center.x, center.y + radius)];
        return cross;
    }
    return [NSBezierPath bezierPathWithOvalInRect:NSMakeRect(
        center.x - radius, center.y - radius, radius * 2.0, radius * 2.0)];
}

