static NSColor *IndexedPaletteColor(size_t index, CGFloat alpha = 1.0)
{
    const PaletteColor *color = PaletteColorAtIndex(index);
    if (!color) {
        return [NSColor colorWithCalibratedWhite:0.50 alpha:alpha];
    }
    return [NSColor colorWithCalibratedRed:color->baseR green:color->baseG blue:color->baseB alpha:alpha];
}

static NSColor *IndexedPaletteTextColor(size_t index)
{
    const PaletteColor *color = rlispstat::core::PaletteColorAtIndex(index);
    return (color && color->selectedTextWhite) ? [NSColor whiteColor] : [NSColor blackColor];
}

