static NSColor *BarplotAutomaticColor(size_t index, CGFloat alpha = 1.0)
{
    PlotThemeStyle theme = CurrentPlotThemeStyle();
    if (theme.coordinatedMarks) {
        NSColor *base = index % 3 == 0 ? theme.geomFill : (index % 3 == 1 ? theme.auxiliary : theme.markFill);
        return [base colorWithAlphaComponent:(index % 3 == 1 ? alpha * 0.62 : alpha)];
    }
    return [NSColor colorWithCalibratedWhite:1.0 alpha:alpha];
}

static NSColor *BarplotAutomaticTextColor(size_t index)
{
    (void)index;
    PlotThemeStyle theme = CurrentPlotThemeStyle();
    if (theme.coordinatedMarks) return theme.text;
    return [NSColor colorWithCalibratedWhite:0.10 alpha:1.0];
}

using rlispstat::core::ParseHexRGB;

static NSColor *ColorForNameOrHex(const std::string &nameOrHex, CGFloat alpha = 1.0)
{
    return ColorFromPlotRGBA(rlispstat::core::PlotColorForNameOrHex(nameOrHex, (double)alpha));
}

static NSColor *BarplotDataSheetToneColor(const std::string &colorKey, bool selected, CGFloat alpha);

static NSColor *BarplotSegmentFillColor(const std::string &colorKey, size_t index, CGFloat alpha = 1.0)
{
    if (colorKey.empty()) {
        return BarplotAutomaticColor(index, alpha);
    }
    if (BarplotLevelIsMissing(colorKey)) {
        return [NSColor colorWithCalibratedWhite:0.78 alpha:alpha];
    }
    return ColorForNameOrHex(colorKey, alpha);
}

static NSColor *BarplotSegmentTextColor(const std::string &colorKey, size_t index, CGFloat alpha = 1.0)
{
    NSColor *fill = BarplotSegmentFillColor(colorKey, index, alpha);
    NSColor *rgb = [fill colorUsingColorSpace:[NSColorSpace genericRGBColorSpace]];
    if (!rgb) {
        return BarplotAutomaticTextColor(index);
    }
    CGFloat r = [rgb redComponent];
    CGFloat g = [rgb greenComponent];
    CGFloat b = [rgb blueComponent];
    CGFloat luminance = 0.2126 * r + 0.7152 * g + 0.0722 * b;
    CGFloat blended = (CGFloat)alpha * luminance + (CGFloat)(1.0 - alpha) * 1.0;
    if (blended < 0.52) {
        return [NSColor whiteColor];
    }
    return [NSColor colorWithCalibratedWhite:0.10 alpha:1.0];
}

static void DrawBarplotPatternLayer(NSRect geometry, const std::string &pattern, NSColor *strokeColor)
{
    if (!BarplotPatternIsKnown(pattern) || pattern == "none" || geometry.size.width <= 0.0 || geometry.size.height <= 0.0) {
        return;
    }
    NSGraphicsContext *ctx = [NSGraphicsContext currentContext];
    [ctx saveGraphicsState];
    NSBezierPath *clip = [NSBezierPath bezierPathWithRect:geometry];
    [clip addClip];
    [strokeColor setStroke];
    [strokeColor setFill];

    CGFloat x0 = geometry.origin.x;
    CGFloat y0 = geometry.origin.y;
    CGFloat x1 = geometry.origin.x + geometry.size.width;
    CGFloat y1 = geometry.origin.y + geometry.size.height;

    if (pattern == "dots") {
        CGFloat step = 6.0;
        CGFloat radius = 1.0;
        for (CGFloat y = y0 + 2.0; y <= y1; y += step) {
            for (CGFloat x = x0 + 2.0; x <= x1; x += step) {
                NSRect dot = NSMakeRect(x - radius, y - radius, radius * 2.0, radius * 2.0);
                NSBezierPath *circle = [NSBezierPath bezierPathWithOvalInRect:dot];
                [circle fill];
            }
        }
        [ctx restoreGraphicsState];
        return;
    }

    CGFloat spacing = 6.0;
    NSBezierPath *path = [NSBezierPath bezierPath];
    [path setLineWidth:1.2];

    auto drawDiagonalSlash = [&]() {
        for (CGFloat x = x0 - geometry.size.height; x <= x1; x += spacing) {
            [path moveToPoint:NSMakePoint(x, y1)];
            [path lineToPoint:NSMakePoint(x + geometry.size.height, y0)];
        }
    };
    auto drawDiagonalBackslash = [&]() {
        for (CGFloat x = x0; x <= x1 + geometry.size.height; x += spacing) {
            [path moveToPoint:NSMakePoint(x, y0)];
            [path lineToPoint:NSMakePoint(x - geometry.size.height, y1)];
        }
    };
    auto drawVertical = [&]() {
        for (CGFloat x = x0; x <= x1; x += spacing) {
            [path moveToPoint:NSMakePoint(x, y0)];
            [path lineToPoint:NSMakePoint(x, y1)];
        }
    };
    auto drawHorizontal = [&]() {
        for (CGFloat y = y0; y <= y1; y += spacing) {
            [path moveToPoint:NSMakePoint(x0, y)];
            [path lineToPoint:NSMakePoint(x1, y)];
        }
    };

    if (pattern == "diagonal_slash") {
        drawDiagonalSlash();
    } else if (pattern == "diagonal_backslash") {
        drawDiagonalBackslash();
    } else if (pattern == "vertical") {
        drawVertical();
    } else if (pattern == "horizontal") {
        drawHorizontal();
    } else if (pattern == "crosshatch") {
        drawDiagonalSlash();
        drawDiagonalBackslash();
    }
    [path stroke];
    [ctx restoreGraphicsState];
}

static void DrawBarplotSegmentBorder(NSRect geometry,
                                     const PlotModel *model,
                                     bool drawTopEdge = true,
                                     bool drawBottomEdge = true)
{
    if (geometry.size.width <= 0.0 || geometry.size.height <= 0.0) {
        return;
    }

    CGFloat stroke = (CGFloat)ClampBarplotSplitStrokeWidth(model ? model->barplotSplitStrokeWidth : 2.0);
    CGFloat half = stroke * 0.5;
    PlotThemeStyle theme = CurrentPlotThemeStyle();
    [(theme.coordinatedMarks ? theme.geomStroke : [NSColor colorWithCalibratedWhite:0.0 alpha:0.92]) setStroke];
    if (geometry.size.width > stroke && geometry.size.height > stroke) {
        CGFloat x0 = geometry.origin.x + half;
        CGFloat x1 = geometry.origin.x + geometry.size.width - half;
        CGFloat y0 = geometry.origin.y + half;
        CGFloat y1 = geometry.origin.y + geometry.size.height - half;
        NSBezierPath *path = [NSBezierPath bezierPath];
        [path setLineWidth:stroke];
        // Draw shared separators once to avoid doubled thick lines when partitions touch.
        [path moveToPoint:NSMakePoint(x0, y0)];
        [path lineToPoint:NSMakePoint(x0, y1)];
        [path moveToPoint:NSMakePoint(x1, y0)];
        [path lineToPoint:NSMakePoint(x1, y1)];
        if (drawTopEdge) {
            [path moveToPoint:NSMakePoint(x0, y1)];
            [path lineToPoint:NSMakePoint(x1, y1)];
        }
        if (drawBottomEdge) {
            [path moveToPoint:NSMakePoint(x0, y0)];
            [path lineToPoint:NSMakePoint(x1, y0)];
        }
        [path stroke];
    } else {
        NSFrameRect(geometry);
    }
}

static void DrawBarplotSegmentLayers(NSRect geometry,
                                     const PlotModel *model,
                                     const BarplotSegmentVisualStyle &style,
                                     size_t levelIndex,
                                     bool drawBorder,
                                     bool drawTopEdge = true,
                                     bool drawBottomEdge = true)
{
    if (geometry.size.width <= 0.0 || geometry.size.height <= 0.0) {
        return;
    }

    PlotThemeStyle theme = CurrentPlotThemeStyle();
    [(theme.coordinatedMarks ? theme.geomFill : [NSColor colorWithCalibratedWhite:1.0 alpha:1.0]) setFill];
    NSRectFillUsingOperation(geometry, NSCompositingOperationSourceOver);

    bool splitUsesBordersOnly = model && !model->barplotSplitVariable.empty();
    if (BarplotEncodingShowsPatterns(model) && !splitUsesBordersOnly) {
        DrawBarplotPatternLayer(geometry,
                                style.pattern,
                                theme.coordinatedMarks ? [theme.geomStroke colorWithAlphaComponent:0.42] :
                                    [NSColor colorWithCalibratedWhite:0.12 alpha:0.42]);
    }

    if (BarplotEncodingShowsColor(model)) {
        NSColor *fillColor = style.hasSegmentColorOverride
            ? BarplotDataSheetToneColor(style.colorKey, false, style.alpha)
            : BarplotSegmentFillColor(style.colorKey, levelIndex, style.alpha);
        [fillColor setFill];
        NSRectFillUsingOperation(geometry, NSCompositingOperationSourceOver);
    }

    if (drawBorder) {
        DrawBarplotSegmentBorder(geometry, model, drawTopEdge, drawBottomEdge);
    }
}

