static void PublishSpreadPlotMessage(const std::string &type,
                                     const std::string &group,
                                     const std::string &senderId = "",
                                     const std::string &modelId = "",
                                     const std::vector<int> &rowIds = std::vector<int>(),
                                     int selectionVersion = 0);
static void RequestColorSmoothRecomputeForGroupUnlocked(const std::string &group);
static void RedrawGroupViewsSynchronouslyOnMain(const std::string &group, bool forceDisplay);
static void UpdatePanelOnMain();

static bool ApplyColorToRows(const std::string &group,
                             const std::vector<int> &rows,
                             const std::string &colorName)
{
    if (!rlispstat::core::FindPaletteColor(colorName)) {
        return false;
    }
    std::vector<int> changedRows;
    changedRows.reserve(rows.size());
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        for (int row : rows) {
            if (row <= 0) continue;
            g_groupPointColors[group][row] = colorName;
            changedRows.push_back(row);
        }
        if (!changedRows.empty()) {
            RequestColorSmoothRecomputeForGroupUnlocked(group);
        }
    }
    if (!changedRows.empty()) {
        PublishSpreadPlotMessage("ROW_COLORS_CHANGED", group, "barplot", "", changedRows, 0);
        RedrawGroupViewsSynchronouslyOnMain(group, true);
        UpdatePanelOnMain();
    }
    return !changedRows.empty();
}

static NSColor *DataSheetSelectedFallbackColor();

static NSColor *BarplotDataSheetToneColor(const std::string &colorKey, bool selected, CGFloat alpha)
{
    PlotThemeStyle theme = CurrentPlotThemeStyle();
    if (colorKey.empty() || colorKey == "__default__") {
        // No explicit row colour: follow the data-sheet convention directly.
        // Theme mark colours (black in DataDesk/Beige) must not turn an entire
        // bar black merely because it contains selected cases.
        NSColor *base = selected ? DataSheetSelectedFallbackColor() : [NSColor whiteColor];
        return [base colorWithAlphaComponent:alpha];
    }
    if (theme.coordinatedMarks && selected && LowerCopy(colorKey) == "black") {
        return [theme.selectedMarkFill colorWithAlphaComponent:alpha];
    }
    if (LowerCopy(colorKey) == "white") {
        NSColor *base = selected ? DataSheetSelectedFallbackColor() : [NSColor whiteColor];
        return [base colorWithAlphaComponent:alpha];
    }
    auto palette = rlispstat::core::FindPaletteColor(colorKey);
    if (palette) {
        if (selected) {
            return [NSColor colorWithCalibratedRed:palette->selectedR
                                             green:palette->selectedG
                                              blue:palette->selectedB
                                             alpha:alpha];
        }
        return [NSColor colorWithCalibratedRed:palette->lightR
                                         green:palette->lightG
                                          blue:palette->lightB
                                         alpha:alpha];
    }
    return ColorForNameOrHex(colorKey, alpha);
}

static void DrawBarplotRowColorIdentityLayer(NSRect geometry,
                                             const std::vector<int> &rows,
                                             const std::map<int, std::string> &rowColors,
                                             CGFloat alpha)
{
    if (rows.empty() || geometry.size.width <= 0.0 || geometry.size.height <= 0.0) {
        return;
    }

    std::vector<rlispstat::core::BarplotCompositionSlice> slices =
        rlispstat::core::BarplotVerticalRowColorCompositionSlices(
            rlispstat::platform::macos::ToCoreRect(geometry),
            rows,
            rowColors,
            BarplotPaletteOrder(),
            false,
            true);
    for (const rlispstat::core::BarplotCompositionSlice &slice : slices) {
        [BarplotDataSheetToneColor(slice.colorKey, false, alpha) setFill];
        NSRectFillUsingOperation(rlispstat::platform::macos::ToNSRect(slice.rect),
                                 NSCompositingOperationSourceOver);
    }
}

static std::string SelectedColorForGroup(const std::string &group);

static void DrawBarplotSelectionLayer(NSRect geometry,
                                      const std::vector<int> &rows,
                                      const std::set<int> &selection,
                                      const std::map<int, std::string> &rowColors,
                                      const PlotModel *model)
{
    if (!model || model->barplotSelectionDisplay == "hide" || rows.empty() ||
        geometry.size.width <= 0.0 || geometry.size.height <= 0.0) {
        return;
    }

    rlispstat::core::BarplotSelectionSlicePlan plan =
        rlispstat::core::BuildBarplotSelectionSlicePlan(
            rlispstat::platform::macos::ToCoreRect(geometry),
            rows,
            selection,
            rowColors,
            BarplotPaletteOrder(),
            SelectedColorForGroup(model->group));
    if (plan.backgroundSlices.empty() && plan.slices.empty()) {
        return;
    }

    NSGraphicsContext *ctx = [NSGraphicsContext currentContext];
    [ctx saveGraphicsState];
    NSBezierPath *clip = [NSBezierPath bezierPathWithRect:geometry];
    [clip addClip];

    if (model && BarplotSelectionDisplayShowsOverlay(model->barplotSelectionDisplay)) {
        // Draw the unselected state first.  The data sheet uses the light
        // palette tone for unselected rows and the saturated tone for selected
        // rows; bars now follow that same convention instead of falling back
        // to white when cases are deselected.
        for (const rlispstat::core::BarplotCompositionSlice &slice : plan.backgroundSlices) {
            NSRect sliceRect = rlispstat::platform::macos::ToNSRect(slice.rect);
            [BarplotDataSheetToneColor(slice.colorKey, false, 0.96) setFill];
            NSRectFillUsingOperation(sliceRect, NSCompositingOperationSourceOver);
        }
        for (const rlispstat::core::BarplotCompositionSlice &slice : plan.slices) {
            NSRect sliceRect = rlispstat::platform::macos::ToNSRect(slice.rect);
            [BarplotDataSheetToneColor(slice.colorKey, true, 0.96) setFill];
            NSRectFillUsingOperation(sliceRect, NSCompositingOperationSourceOver);
            NSRect inner = NSInsetRect(sliceRect, 1.0, 1.0);
            if (inner.size.width > 0.0 && inner.size.height > 0.0) {
                PlotThemeStyle theme = CurrentPlotThemeStyle();
                [[(theme.coordinatedMarks ? theme.selectedMarkStroke : [NSColor whiteColor]) colorWithAlphaComponent:0.12] setFill];
                NSRectFillUsingOperation(inner, NSCompositingOperationSourceOver);
            }
        }
    }

    if (model && BarplotSelectionDisplayShowsOutline(model->barplotSelectionDisplay)) {
        CGFloat lineWidth = plan.selectedFraction >= 0.999 ? 2.2 : 1.6;
        [BarplotDataSheetToneColor(plan.dominantSelectedColorKey, true, 0.98) setStroke];
        for (const rlispstat::core::BarplotCompositionSlice &slice : plan.slices) {
            NSRect insetOutlineRect = NSInsetRect(rlispstat::platform::macos::ToNSRect(slice.rect), 0.5, 0.5);
            if (insetOutlineRect.size.width <= 0.0 || insetOutlineRect.size.height <= 0.0) {
                continue;
            }
            NSBezierPath *outline = [NSBezierPath bezierPathWithRect:insetOutlineRect];
            [outline setLineWidth:lineWidth];
            [outline stroke];
        }
        if (plan.selectedFraction >= 0.999) {
            NSRect innerOutlineRect = NSInsetRect(geometry, 2.4, 2.4);
            if (innerOutlineRect.size.width > 0.0 && innerOutlineRect.size.height > 0.0) {
                NSBezierPath *inner = [NSBezierPath bezierPathWithRect:innerOutlineRect];
                [inner setLineWidth:1.0];
                PlotThemeStyle theme = CurrentPlotThemeStyle();
                [(theme.coordinatedMarks ? theme.selectedMarkStroke : [NSColor colorWithCalibratedWhite:1.0 alpha:0.72]) setStroke];
                [inner stroke];
            }
        }
    }
    [ctx restoreGraphicsState];
}

static NSColor *MixedColorForNames(const std::string &a, const std::string &b, CGFloat alpha = 0.34)
{
    auto ca = rlispstat::core::FindPaletteColor(a);
    auto cb = rlispstat::core::FindPaletteColor(b);
    if (!ca || !cb) {
        return [NSColor colorWithCalibratedWhite:0.22 alpha:alpha];
    }
    return [NSColor colorWithCalibratedRed:(ca->baseR + cb->baseR) / 2.0
                                     green:(ca->baseG + cb->baseG) / 2.0
                                      blue:(ca->baseB + cb->baseB) / 2.0
                                     alpha:alpha];
}

