static void RedrawGroupViewsNow(const std::string &group, bool forceDisplay = false)
{
    std::vector<ScatterView *> scatterViews;
    std::vector<BoxplotView *> boxplotViews;
    std::vector<HistogramView *> histogramViews;
    std::vector<BarplotView *> barplotViews;
    std::vector<id<GLMPairwiseComparisonPlotRefreshing>> pairwiseComparisonPlotViews;
    std::vector<id<GLMPairwiseResultsRefreshing>> pairwiseResultsControllers;
    std::vector<Table1ReportView *> table1Views;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        for (ScatterView *view : g_views) {
            if (view.model && view.model->group == group) {
                scatterViews.push_back(view);
            }
        }
        for (BoxplotView *view : g_boxplotViews) {
            if (view.model && view.model->group == group) {
                boxplotViews.push_back(view);
            }
        }
        for (HistogramView *view : g_histogramViews) {
            if (view.model && view.model->group == group) {
                histogramViews.push_back(view);
            }
        }
        for (BarplotView *view : g_barplotViews) {
            if (view.model && view.model->group == group) {
                barplotViews.push_back(view);
            }
        }
        for (id<GLMPairwiseComparisonPlotRefreshing> view : g_pairwiseComparisonPlotViews) {
            const std::string &viewGroup = [view pairwisePlotGroup];
            if (viewGroup == group) {
                pairwiseComparisonPlotViews.push_back(view);
            }
        }
        for (id<GLMPairwiseResultsRefreshing> controller : g_pairwiseResultsControllers) {
            const std::string &controllerGroup = [controller pairwiseResultsGroup];
            if (controllerGroup == group) pairwiseResultsControllers.push_back(controller);
        }
        for (const Table1ViewEntry &entry : g_table1Views) {
            if (entry.group == group) {
                table1Views.push_back(static_cast<Table1ReportView *>(entry.view));
            }
        }
    }
    for (ScatterView *view : scatterViews) {
        [view setNeedsDisplay:YES];
        if (forceDisplay) [view displayIfNeeded];
    }
    for (BoxplotView *view : boxplotViews) {
        [view setNeedsDisplay:YES];
        if (forceDisplay) [view displayIfNeeded];
    }
    for (HistogramView *view : histogramViews) {
        [view setNeedsDisplay:YES];
        if (forceDisplay) [view displayIfNeeded];
    }
    for (BarplotView *view : barplotViews) {
        [view setNeedsDisplay:YES];
        if (forceDisplay) [view displayIfNeeded];
    }
    for (id<GLMPairwiseComparisonPlotRefreshing> view : pairwiseComparisonPlotViews) {
        [view refreshPairwisePlotSelection];
        if (forceDisplay) [view displayIfNeeded];
    }
    for (id<GLMPairwiseResultsRefreshing> controller : pairwiseResultsControllers) {
        [controller refreshPairwiseResultsSelection];
    }
    for (Table1ReportView *view : table1Views) {
        [view setNeedsDisplay:YES];
        if (forceDisplay) [view displayIfNeeded];
    }
}

static void RedrawGroupViewsOnMain(const std::string &group)
{
    std::string groupCopy = group;
    dispatch_async(dispatch_get_main_queue(), ^{
      RedrawGroupViewsNow(groupCopy, false);
    });
}

static void RedrawGroupViewsSynchronouslyOnMain(const std::string &group, bool forceDisplay = true)
{
    if ([NSThread isMainThread]) {
        RedrawGroupViewsNow(group, forceDisplay);
        return;
    }
    dispatch_sync(dispatch_get_main_queue(), ^{
      RedrawGroupViewsNow(group, forceDisplay);
    });
}

