static NSData *HighResolutionPNGDataForView(NSView *view)
{
    if (!view) return nil;
    NSRect bounds = [view bounds];
    if (bounds.size.width <= 0.0 || bounds.size.height <= 0.0) return nil;
    CGFloat scale = 300.0 / 72.0;
    NSInteger pixelsWide = std::max((NSInteger)1, (NSInteger)std::ceil(bounds.size.width * scale));
    NSInteger pixelsHigh = std::max((NSInteger)1, (NSInteger)std::ceil(bounds.size.height * scale));
    NSBitmapImageRep *rep = [[NSBitmapImageRep alloc]
        initWithBitmapDataPlanes:NULL
                      pixelsWide:pixelsWide
                      pixelsHigh:pixelsHigh
                   bitsPerSample:8
                 samplesPerPixel:4
                        hasAlpha:YES
                        isPlanar:NO
                  colorSpaceName:NSDeviceRGBColorSpace
                    bitmapFormat:0
                     bytesPerRow:0
                    bitsPerPixel:0];
    if (!rep) return nil;
    [rep setSize:bounds.size];
    NSGraphicsContext *context = [NSGraphicsContext graphicsContextWithBitmapImageRep:rep];
    if (!context) return nil;
    [NSGraphicsContext saveGraphicsState];
    [NSGraphicsContext setCurrentContext:context];
    [view displayRectIgnoringOpacity:bounds inContext:context];
    [NSGraphicsContext restoreGraphicsState];
    // PNG does not use the lossy compression-factor option.  Passing image
    // properties intended for other encoders can make AppKit return nil on
    // recent macOS releases, so use the native lossless defaults first.
    NSData *encoded = [rep representationUsingType:NSBitmapImageFileTypePNG properties:@{}];
    if (encoded) return encoded;
    // ImageIO is a reliable fallback for detached export views on recent
    // AppKit versions, where NSBitmapImageRep can occasionally decline to
    // create its representation even though it owns a valid CGImage.
    CGImageRef image = [rep CGImage];
    if (!image) return nil;
    NSMutableData *fallback = [NSMutableData data];
    CGImageDestinationRef destination = CGImageDestinationCreateWithData(
        (CFMutableDataRef)fallback, CFSTR("public.png"), 1, nullptr);
    if (!destination) return nil;
    CGImageDestinationAddImage(destination, image, nullptr);
    const BOOL finished = CGImageDestinationFinalize(destination);
    CFRelease(destination);
    return finished ? fallback : nil;
}

static BOOL SaveViewToPath(NSView *view, NSString *path, const std::string &format)
{
    if (!view || !path) return NO;
    NSData *data = nil;
    if (format == "PNG" || format == "PDF")
        data = VisualExportDataForView(view, ToNSString(format));
    if (!data) return NO;
    return [data writeToFile:path atomically:YES];
}

