    if (boxplot) return (NSView *)boxplot;
    HistogramView *histogram = HistogramViewForPlotUnlocked(plotId);
    if (histogram) return (NSView *)histogram;
    BarplotView *barplot = BarplotViewForPlotUnlocked(plotId);
    if (barplot) return (NSView *)barplot;
    return nil;
}

