static NSMenuItem *AddDataColumnSubmenuItem()
{
    return AddDataColumnSubmenuItemForGroup("");
}

static std::string AnalysisScopeRowsCommand(const std::string &group,
                                            const std::vector<int> &rows,
                                            const std::string &sourceKind,
                                            const std::string &description,
                                            const std::string &viewId = "",
                                            const std::string &elementId = "")
{
    std::ostringstream command;
    command << "SET_ANALYSIS_SCOPE_FROM_ROWS|" << group << "|" << rows.size();
    for (int row : rows) command << "|" << row;
    command << "|" << sourceKind << "|" << description
            << "|" << viewId << "|" << elementId;
    return command.str();
}

static std::optional<std::string> PromptForNamedSelectionAnalysisScope(
    std::size_t observationCount)
{
    std::string previousValue;
    while (true) {
        NSAlert *alert = [[NSAlert alloc] init];
        [alert setMessageText:@"Name the selected observations"];
        [alert setInformativeText:[NSString stringWithFormat:
            @"The current %lu selected observations will be saved as an immutable subset for subsequent analyses.",
            (unsigned long)observationCount]];
        [alert addButtonWithTitle:@"Use Selection"];
        [alert addButtonWithTitle:@"Cancel"];
        NSTextField *field = [[NSTextField alloc] initWithFrame:NSMakeRect(0, 0, 320, 24)];
        [field setStringValue:ToNSString(previousValue)];
        [field setPlaceholderString:@"For example: High mileage cars"];
        [field setAccessibilityLabel:@"Selection name"];
        [alert setAccessoryView:field];
        [[alert window] setInitialFirstResponder:field];
        NSModalResponse response = [alert runModal];
        previousValue = [[field stringValue] UTF8String];
        [field release];
        [alert release];
        if (response != NSAlertFirstButtonReturn) return std::nullopt;

        std::string error;
        if (rlispstat::core::ValidateAnalysisScopeSelectionName(previousValue, &error)) {
            return rlispstat::core::NamedSelectionAnalysisScopeDescription(previousValue);
        }
        NSAlert *errorAlert = [[NSAlert alloc] init];
        [errorAlert setMessageText:@"Name selected observations"];
        [errorAlert setInformativeText:ToNSString(error)];
        [errorAlert addButtonWithTitle:@"OK"];
        [errorAlert runModal];
        [errorAlert release];
    }
}

static void AddSavedSelectionItemsToScopeMenu(
    NSMenu *menu,
    const std::string &group,
    const std::vector<rlispstat::core::SavedSelection> &savedSelections,
    const rlispstat::core::AnalysisScope &activeScope)
{
    if (!menu || savedSelections.empty()) return;
    [menu addItem:[NSMenuItem separatorItem]];
    NSMenuItem *savedRoot = [[NSMenuItem alloc] initWithTitle:@"Saved selections"
                                                      action:nil keyEquivalent:@""];
    NSMenu *savedMenu = [[NSMenu alloc] initWithTitle:@"Saved selections"];
    for (const rlispstat::core::SavedSelection &selection : savedSelections) {
        NSString *title = [NSString stringWithFormat:@"%s (%lu)", selection.name.c_str(),
            (unsigned long)selection.originalRowIds.size()];
        NSMenuItem *selectionRoot = [[NSMenuItem alloc] initWithTitle:title
                                                              action:nil keyEquivalent:@""];
        NSMenu *selectionMenu = [[NSMenu alloc] initWithTitle:title];
        NSMenuItem *useItem = ApplicationMenuItem(
            @"Use as scope",
            ToNSString("USE_SAVED_ANALYSIS_SCOPE|" + group + "|" + selection.name),
            @"", 0);
        const std::optional<std::string> activeName =
            rlispstat::core::AnalysisScopeSelectionName(activeScope);
        [useItem setState:activeName.has_value() && *activeName == selection.name
            ? NSControlStateValueOn : NSControlStateValueOff];
        [selectionMenu addItem:useItem];
        NSMenuItem *addItem = ApplicationMenuItem(
            @"Add to active scope\u2026",
            ToNSString("ADD_SAVED_ANALYSIS_SCOPE|" + group + "|" + selection.name),
            @"", 0);
        [addItem setEnabled:activeScope.kind ==
            rlispstat::core::AnalysisScopeKind::ExplicitRowIds];
        [selectionMenu addItem:addItem];
        [selectionRoot setSubmenu:selectionMenu];
        [savedMenu addItem:selectionRoot];
    }
    [savedRoot setSubmenu:savedMenu];
    [menu addItem:savedRoot];
}

static NSMenuItem *AnalysisScopeSubmenuItemForPlot(PlotModel *model,
                                                   const std::vector<int> &contextRows = {},
                                                   const std::string &contextSourceKind = "",
                                                   const std::string &contextDescription = "",
                                                   const std::string &contextElementId = "")
{
    NSMenuItem *root = [[NSMenuItem alloc] initWithTitle:@"Analysis scope cases" action:nil keyEquivalent:@""];
    NSMenu *menu = [[NSMenu alloc] initWithTitle:@"Analysis scope cases"];
    if (!model) {
        [root setEnabled:NO];
        return root;
    }
    std::vector<int> selectedRows;
    std::size_t totalRows = model->dataScope.totalDatasetRows;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        (void)MacPlotCoordinator().activatePlot(model->id);
        const DataFrameModel *dataset = FindDataFrameUnlockedConst(model->group);
        if (dataset) totalRows = static_cast<std::size_t>(std::max(0, dataset->rows));
        auto selected = g_groupSelections.find(model->group);
        if (selected != g_groupSelections.end()) {
            selectedRows.assign(selected->second.begin(), selected->second.end());
        }
        if (contextSourceKind == "trellis_panel") {
            g_analysisScopePanelMenuContext.group = model->group;
            g_analysisScopePanelMenuContext.plotId = model->id;
            g_analysisScopePanelMenuContext.panelId = contextElementId;
            g_analysisScopePanelMenuContext.description = contextDescription;
            g_analysisScopePanelMenuContext.rows = contextRows;
        } else if (g_analysisScopePanelMenuContext.plotId != model->id) {
            g_analysisScopePanelMenuContext = {};
        }
    }
    UpdateAnalysisScopeStatusOnMain();
    const std::size_t selected = selectedRows.size();
    NSString *selectedTitle = [NSString stringWithFormat:@"Selected (%lu)", (unsigned long)selected];
    const std::string selectionSource =
        (model->kind == "scatter" || model->kind == "scatter_matrix" ||
         model->kind == "time_series" || model->kind == "dotplot")
        ? "scatterplot_selection" : "current_selection";
    NSMenuItem *selectionItem = PlotCommandMenuItem(
        selectedTitle,
        ToNSString(AnalysisScopeRowsCommand(
            model->group, selectedRows, selectionSource,
            "Selection snapshot from " + model->kind, model->id)));
    [selectionItem setEnabled:selected > 0];
    [menu addItem:selectionItem];

    if (!contextRows.empty()) {
        std::string contextNoun = "Subset";
        if (contextSourceKind == "trellis_panel") contextNoun = "Panel";
        else if (contextSourceKind == "boxplot_group") contextNoun = "Group";
        else if (contextSourceKind == "histogram_bin") contextNoun = "Bin";
        else if (contextSourceKind == "bar_segment") {
            contextNoun = contextDescription.rfind("Bar segment", 0) == 0 ? "Segment" : "Bar";
        }
        else if (contextSourceKind == "bar_category") contextNoun = "Bar";
        NSString *contextTitle = [NSString stringWithFormat:@"%s (%lu)",
            contextNoun.c_str(), (unsigned long)contextRows.size()];
        [menu addItem:PlotCommandMenuItem(contextTitle, ToNSString(AnalysisScopeRowsCommand(
            model->group, contextRows,
            contextSourceKind.empty() ? "other_explicit_subset" : contextSourceKind,
            contextDescription.empty() ? "Context subset" : contextDescription,
            model->id, contextElementId)))];
    }

    std::set<int> visible = VisibleRowsForModel(model);
    if (!visible.empty()) {
        const std::vector<int> rows(visible.begin(), visible.end());
        NSString *visibleTitle = [NSString stringWithFormat:@"Plot (%lu)", (unsigned long)rows.size()];
        [menu addItem:PlotCommandMenuItem(visibleTitle, ToNSString(AnalysisScopeRowsCommand(
            model->group, rows, "visible_observations",
            "Observations visible in plot", model->id)))];
    }
    NSMenuItem *allItem = PlotCommandMenuItem(
        [NSString stringWithFormat:@"All (%lu)", (unsigned long)totalRows],
        ToNSString("SET_ANALYSIS_SCOPE_ALL|" + model->group));
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        const auto scope = MacCommandDispatcher().applicationState().activeAnalysisScope(model->group);
        [allItem setState:scope.kind == rlispstat::core::AnalysisScopeKind::AllObservations
            ? NSControlStateValueOn : NSControlStateValueOff];
    }
    [menu addItem:allItem];
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        const auto active = MacCommandDispatcher().applicationState().activeAnalysisScope(model->group);
        const auto saved = MacCommandDispatcher().applicationState().savedSelections(model->group);
        AddSavedSelectionItemsToScopeMenu(menu, model->group, saved, active);
    }
    if (kShowExperimentalFeatures) {
        const bool canClone = !model->isDatasetSeed && !model->isGLMDiagnostic &&
            model->kind != "pca_biplot" && model->kind != "pca_scree" &&
            model->kind != "interaction_plot";
        [menu addItem:[NSMenuItem separatorItem]];
        NSMenuItem *openActive = PlotCommandMenuItem(
            @"Experimental — Open equivalent with active scope",
            @"OPEN_EQUIVALENT_WITH_ACTIVE_SCOPE");
        [openActive setEnabled:canClone];
        [menu addItem:openActive];
        NSMenuItem *openAll = PlotCommandMenuItem(
            @"Experimental — Open equivalent with all cases",
            @"OPEN_EQUIVALENT_WITH_ALL_ROWS");
        [openAll setEnabled:canClone];
        [menu addItem:openAll];
    }
    [root setSubmenu:menu];
    return root;
}

static void AddApplicationMenuOptions(NSMenu *menu, const std::vector<rlispstat::core::LinkedPlotCommandOption> &options)
{
    for (const rlispstat::core::LinkedPlotCommandOption &option : options) {
        [menu addItem:ApplicationMenuItem(ToNSString(option.title), ToNSString(option.command), @"", 0)];
    }
}

static NSEventModifierFlags ApplicationMenuOptionModifiers(const rlispstat::core::ApplicationMenuCommandOption &option)
{
    NSEventModifierFlags modifiers = 0;
    if (option.commandModifier) {
        modifiers |= NSEventModifierFlagCommand;
    }
    if (option.shiftModifier) {
        modifiers |= NSEventModifierFlagShift;
    }
    return modifiers;
}

static NSMenuItem *ApplicationMenuItemForOption(const rlispstat::core::ApplicationMenuCommandOption &option)
{
    std::string title = option.title;
    if (option.experimental) title += " (Experimental)";
    return ApplicationMenuItem(ToNSString(title),
                               ToNSString(option.command),
                               ToNSString(option.keyEquivalent),
                               ApplicationMenuOptionModifiers(option));
}

static void AddApplicationMenuOptions(NSMenu *menu, const std::vector<rlispstat::core::ApplicationMenuCommandOption> &options)
{
    for (const rlispstat::core::ApplicationMenuCommandOption &option : options) {
        if (option.experimental && !kShowExperimentalFeatures) continue;
        [menu addItem:ApplicationMenuItemForOption(option)];
    }
}

static void AddPlotApplicationMenuOptions(NSMenu *menu)
{
    for (const rlispstat::core::ApplicationMenuCommandOption &option : rlispstat::core::PlotCommandOptions()) {
        if (option.command == "PLOT_NEW_TRELLIS_SCATTERPLOT") {
            NSMenuItem *item = [[NSMenuItem alloc] initWithTitle:ToNSString(option.title) action:nil keyEquivalent:@""];
            NSMenu *submenu = [[NSMenu alloc] initWithTitle:ToNSString(option.title)];
            AddApplicationMenuOptions(submenu, rlispstat::core::TrellisPlotStartCommandOptions());
            [menu setSubmenu:submenu forItem:item];
            [menu addItem:item];
        } else {
            [menu addItem:ApplicationMenuItemForOption(option)];
        }
    }
}

static void AddApplicationMenuOptionGroups(NSMenu *menu, const std::vector<std::vector<rlispstat::core::ApplicationMenuCommandOption>> &groups)
{
    for (std::size_t groupIndex = 0; groupIndex < groups.size(); ++groupIndex) {
        if (groupIndex > 0) {
            [menu addItem:[NSMenuItem separatorItem]];
        }
        AddApplicationMenuOptions(menu, groups[groupIndex]);
    }
}

static void AddApplicationSubmenus(NSMenu *menu, const std::vector<rlispstat::core::ApplicationMenuCommandGroup> &groups)
{
    for (const rlispstat::core::ApplicationMenuCommandGroup &group : groups) {
        NSMenuItem *item = [[NSMenuItem alloc] initWithTitle:ToNSString(group.title) action:nil keyEquivalent:@""];
        NSMenu *submenu = [[NSMenu alloc] initWithTitle:ToNSString(group.title)];
        AddApplicationMenuOptions(submenu, group.options);
        [menu setSubmenu:submenu forItem:item];
        [menu addItem:item];
    }
}

static void AddModelTermTypeMenuItems(NSMenu *menu, id target, SEL action, const std::string &currentType)
{
    for (const rlispstat::core::LinkedPlotCommandOption &option : rlispstat::core::ModelTermTypeOptions()) {
        NSMenuItem *item = [[NSMenuItem alloc] initWithTitle:ToNSString(option.title)
                                                      action:action
                                               keyEquivalent:@""];
        [item setTarget:target];
        [item setRepresentedObject:ToNSString(option.value)];
        [item setState:currentType == option.value ? NSControlStateValueOn : NSControlStateValueOff];
        [menu addItem:item];
    }
}

static void AddModelDiagnosticPlotMenuItems(NSMenu *menu, id target, SEL action, bool includeExtended)
{
    for (const rlispstat::core::LinkedPlotCommandOption &option : rlispstat::core::ModelDiagnosticPlotOptions(includeExtended)) {
        NSMenuItem *item = [[NSMenuItem alloc] initWithTitle:ToNSString(option.title)
                                                      action:action
                                               keyEquivalent:@""];
        [item setTarget:target];
        [item setRepresentedObject:ToNSString(option.value)];
        [menu addItem:item];
    }
}

static void UpdateActiveDatasetMenuOnMain()
{
    dispatch_async(dispatch_get_main_queue(), ^{
      if (!g_activeDatasetMenu) {
          return;
      }
      [g_activeDatasetMenu removeAllItems];
      std::vector<std::string> groups;
      std::string active;
      {
          std::lock_guard<std::mutex> lock(g_mutex);
          active = ActiveDatasetGroupUnlocked();
          groups = DatasetGroupsUnlocked();
      }
      if (groups.empty()) {
          NSMenuItem *empty = [[NSMenuItem alloc] initWithTitle:ToNSString(rlispstat::core::NoRegisteredDatasetsTitle()) action:nil keyEquivalent:@""];
          [empty setEnabled:NO];
          [g_activeDatasetMenu addItem:empty];
          return;
      }
      for (const rlispstat::core::ApplicationMenuCommandOption &option : rlispstat::core::ActiveDatasetCommandOptions(groups)) {
          NSMenuItem *item = ApplicationMenuItemForOption(option);
          [item setState:(option.value == active) ? NSControlStateValueOn : NSControlStateValueOff];
          [g_activeDatasetMenu addItem:item];
      }
    });
    UpdateAnalysisScopeStatusOnMain();
}

static void UpdateAnalysisScopeStatusOnMain()
{
    dispatch_async(dispatch_get_main_queue(), ^{
      if (!g_analysisScopeStatusItem || !g_analysisScopeStatusMenu) return;
      std::string group;
      rlispstat::core::AnalysisScope scope;
      std::size_t selectedCount = 0;
      std::vector<int> plotRows;
      std::string plotId;
      std::vector<rlispstat::core::SavedSelection> savedSelections;
      AnalysisScopePanelMenuContext panelContext;
      bool available = false;
      {
          std::lock_guard<std::mutex> lock(g_mutex);
          group = ActiveDatasetGroupUnlocked();
          const DataFrameModel *dataset = FindDataFrameUnlockedConst(group);
          if (dataset) {
              scope = MacCommandDispatcher().applicationState().activeAnalysisScope(group);
              savedSelections = MacCommandDispatcher().applicationState().savedSelections(group);
              auto selected = g_groupSelections.find(group);
              selectedCount = selected == g_groupSelections.end() ? 0 : selected->second.size();
              auto activePlot = g_plots.find(g_activePlotId);
              if (activePlot != g_plots.end() && activePlot->second &&
                  activePlot->second->group == group && !activePlot->second->isDatasetSeed) {
                  plotId = activePlot->second->id;
                  const std::set<int> visible = VisibleRowsForModel(activePlot->second);
                  plotRows.assign(visible.begin(), visible.end());
                  if (g_analysisScopePanelMenuContext.group == group &&
                      g_analysisScopePanelMenuContext.plotId == plotId) {
                      panelContext = g_analysisScopePanelMenuContext;
                  }
              }
              available = true;
          }
      }
      [g_analysisScopeStatusMenu removeAllItems];
      [g_analysisScopeStatusItem setTitle:@"Analysis scope cases"];
      if (!available) {
          [g_analysisScopeStatusItem setAccessibilityLabel:@"Analysis scope cases: no dataset"];
          [g_analysisScopeStatusItem setEnabled:NO];
          if (g_makeSubsetMenu) [g_makeSubsetMenu removeAllItems];
          if (g_makeSubsetItem) [g_makeSubsetItem setEnabled:NO];
          return;
      }
      [g_analysisScopeStatusItem setEnabled:YES];
      const std::string full = rlispstat::core::AnalysisScopeSummary(
          scope, scope.totalDatasetRows);
      [g_analysisScopeStatusItem setAccessibilityLabel:ToNSString(full)];
      NSMenuItem *selected = ApplicationMenuItem(
          [NSString stringWithFormat:@"Selected (%lu)", (unsigned long)selectedCount],
          ToNSString("SET_ANALYSIS_SCOPE_FROM_SELECTION|" + group +
                     "|Current selection snapshot|global_scope_indicator"), @"", 0);
      [selected setEnabled:selectedCount > 0];
      [selected setState:scope.kind == rlispstat::core::AnalysisScopeKind::ExplicitRowIds &&
          (scope.sourceKind == rlispstat::core::AnalysisScopeSourceKind::CurrentSelection ||
           scope.sourceKind == rlispstat::core::AnalysisScopeSourceKind::ScatterplotSelection ||
           scope.sourceKind == rlispstat::core::AnalysisScopeSourceKind::DataTableRows)
          ? NSControlStateValueOn : NSControlStateValueOff];
      [g_analysisScopeStatusMenu addItem:selected];
      AddSavedSelectionItemsToScopeMenu(
          g_analysisScopeStatusMenu, group, savedSelections, scope);
      if (!panelContext.rows.empty()) {
          NSMenuItem *panel = ApplicationMenuItem(
              [NSString stringWithFormat:@"Panel (%lu)", (unsigned long)panelContext.rows.size()],
              ToNSString(AnalysisScopeRowsCommand(
                  group, panelContext.rows, "trellis_panel",
                  panelContext.description.empty() ? "Trellis panel" : panelContext.description,
                  panelContext.plotId, panelContext.panelId)), @"", 0);
          [panel setState:scope.kind == rlispstat::core::AnalysisScopeKind::ExplicitRowIds &&
              scope.sourceKind == rlispstat::core::AnalysisScopeSourceKind::TrellisPanel &&
              scope.sourceViewId.value_or("") == panelContext.plotId &&
              scope.sourceElementId.value_or("") == panelContext.panelId
              ? NSControlStateValueOn : NSControlStateValueOff];
          [g_analysisScopeStatusMenu addItem:panel];
      }
      if (!plotRows.empty()) {
          NSMenuItem *plot = ApplicationMenuItem(
              [NSString stringWithFormat:@"Plot (%lu)", (unsigned long)plotRows.size()],
              ToNSString(AnalysisScopeRowsCommand(
                  group, plotRows, "visible_observations", "Cases in plot", plotId)), @"", 0);
          [plot setState:scope.kind == rlispstat::core::AnalysisScopeKind::ExplicitRowIds &&
              scope.sourceKind == rlispstat::core::AnalysisScopeSourceKind::VisibleObservations &&
              scope.sourceViewId.value_or("") == plotId
              ? NSControlStateValueOn : NSControlStateValueOff];
          [g_analysisScopeStatusMenu addItem:plot];
      }
      NSMenuItem *all = ApplicationMenuItem(
          [NSString stringWithFormat:@"All (%lu)", (unsigned long)scope.totalDatasetRows],
          ToNSString("SET_ANALYSIS_SCOPE_ALL|" + group), @"", 0);
      [all setState:scope.kind == rlispstat::core::AnalysisScopeKind::AllObservations
          ? NSControlStateValueOn : NSControlStateValueOff];
      [all setEnabled:scope.kind != rlispstat::core::AnalysisScopeKind::AllObservations];
      [g_analysisScopeStatusMenu addItem:all];

      if (g_makeSubsetItem && g_makeSubsetMenu) {
          [g_makeSubsetMenu removeAllItems];
          NSMenuItem *current = ApplicationMenuItem(
              [NSString stringWithFormat:@"Current selection (%lu)\u2026",
                  (unsigned long)selectedCount],
              ToNSString("DATA_MAKE_SUBSET_FROM_SELECTION|" + group), @"", 0);
          [current setEnabled:selectedCount > 0];
          [g_makeSubsetMenu addItem:current];
          if (!savedSelections.empty()) {
              [g_makeSubsetMenu addItem:[NSMenuItem separatorItem]];
              for (const rlispstat::core::SavedSelection &saved : savedSelections) {
                  [g_makeSubsetMenu addItem:ApplicationMenuItem(
                      [NSString stringWithFormat:@"%s (%lu)\u2026", saved.name.c_str(),
                          (unsigned long)saved.originalRowIds.size()],
                      ToNSString("DATA_MAKE_SUBSET_FROM_SAVED_SELECTION|" +
                          group + "|" + saved.name), @"", 0)];
              }
          }
          [g_makeSubsetItem setEnabled:selectedCount > 0 || !savedSelections.empty()];
      }
    });
}

static NSRect NextWindowFrameOnMain(CGFloat width, CGFloat height)
{
    NSScreen *screen = [NSScreen mainScreen];
    NSRect visible = screen ? [screen visibleFrame] : NSMakeRect(0, 0, 1440, 900);
    auto frame = rlispstat::core::WindowPlacementNextFrame(
        g_windowState, width, height, visible.size.width, visible.size.height);
    return NSMakeRect(visible.origin.x + frame.x,
                      visible.origin.y + visible.size.height - frame.y - height,
                      frame.width, frame.height);
}

static void ResetWindowLayoutOnMain()
{
    dispatch_async(dispatch_get_main_queue(), ^{
      rlispstat::core::WindowPlacementReset(g_windowState);
    });
}

static void ShowWorkbenchMessageOnMain(NSString *title, NSString *message)
{
    dispatch_async(dispatch_get_main_queue(), ^{
      NSAlert *alert = [[NSAlert alloc] init];
      [alert setMessageText:title];
      [alert setInformativeText:message];
      [alert addButtonWithTitle:ToNSString(rlispstat::core::AlertOKButtonTitle())];
      [alert runModal];
    });
}

static NSString *const kWelcomeRecentDefaultsKey = @"LinkEDARecentDataFiles";

static NSArray<NSString *> *WelcomeRecentPaths()
{
    NSArray *stored = [[NSUserDefaults standardUserDefaults]
        stringArrayForKey:kWelcomeRecentDefaultsKey];
    return stored ?: @[];
}

static void SaveWelcomeRecentPaths(NSArray<NSString *> *paths)
{
    [[NSUserDefaults standardUserDefaults] setObject:paths forKey:kWelcomeRecentDefaultsKey];
}

static void NoteWelcomeRecentPathOnMain(const std::string &path)
{
    if (path.empty()) return;
    NSString *nativePath = [ToNSString(path) stringByStandardizingPath];
    dispatch_async(dispatch_get_main_queue(), ^{
      NSMutableArray<NSString *> *paths = [NSMutableArray arrayWithObject:nativePath];
      for (NSString *existing in WelcomeRecentPaths()) {
          if (![existing isEqualToString:nativePath] && [paths count] < 8) {
              [paths addObject:existing];
          }
      }
      SaveWelcomeRecentPaths(paths);
      if (g_welcomeController && [g_welcomeController respondsToSelector:@selector(refresh)]) {
          [g_welcomeController performSelector:@selector(refresh)];
      }
    });
}

static std::vector<rlispstat::core::WelcomeRecentItem> NativeWelcomeRecentItems()
{
    std::vector<rlispstat::core::WelcomeRecentItem> items;
    for (NSString *path in WelcomeRecentPaths()) {
        NSString *name = [path lastPathComponent];
        NSString *extension = [[path pathExtension] uppercaseString];
        const bool exists = [[NSFileManager defaultManager] fileExistsAtPath:path];
        items.push_back({[path UTF8String], [name UTF8String], [path UTF8String],
                         [extension UTF8String], exists});
    }
    return rlispstat::core::NormalizeWelcomeRecentItems(items, 8);
}

