- (void)refresh
{
    const auto model = rlispstat::core::DefaultWelcomeWindowModel(
        _version, !g_mainRNotifyPath.empty(), NativeWelcomeRecentItems());
    NSString *connection = ToNSString(model.capabilities.connectedToExistingRSession
        ? model.strings.connectedToR : model.strings.connectionUnavailable);
    [_connectionField setStringValue:[NSString stringWithFormat:@"●  %@", connection]];
    [_connectionField setTextColor:model.capabilities.connectedToExistingRSession
        ? [NSColor systemGreenColor] : [NSColor systemOrangeColor]];
    [_connectionField setAccessibilityLabel:connection];
    [_chooseButton setEnabled:model.capabilities.canChooseRDataFrame];
    [_firstExampleButton setEnabled:model.capabilities.canOpenExamples];
    [_secondExampleButton setEnabled:model.capabilities.canOpenExamples];
    for (NSView *view in [[_recentView subviews] copy]) [view removeFromSuperview];
    _firstRecentButton = nil;
    if (model.recentItems.empty()) {
        NSTextField *empty = WelcomeLabel(ToNSString(model.strings.noRecentItems),
            NSMakeRect(6, 104, 360, 22), 12, NSFontWeightRegular,
            [NSColor secondaryLabelColor]);
        [_recentView addSubview:empty];
    } else {
        CGFloat y = 112;
        int shown = 0;
        for (const auto &item : model.recentItems) {
            if (shown++ >= 5) break;
            NSString *title = item.typeLabel.empty()
                ? ToNSString(item.displayName)
                : [NSString stringWithFormat:@"%@  —  %@", ToNSString(item.displayName),
                   ToNSString(item.typeLabel)];
            if (!item.exists) title = [title stringByAppendingString:@"  (missing)"];
            NSButton *button = [NSButton buttonWithTitle:title target:self
                action:@selector(openRecent:)];
            [button setFrame:NSMakeRect(0, y, 425, 25)];
            [button setAlignment:NSTextAlignmentLeft];
            [button setBezelStyle:NSBezelStyleInline];
            [button setIdentifier:ToNSString(item.path)];
            [button setToolTip:ToNSString(item.path)];
            [button setAccessibilityLabel:title];
            NSMenu *menu = [[NSMenu alloc] initWithTitle:title];
            for (NSArray *entry in @[@[@"Open", @"openRecent:"],
                                      @[@"Show in Finder", @"revealRecent:"],
                                      @[@"Remove from Recent", @"removeRecent:"]]) {
                NSMenuItem *menuItem = [[NSMenuItem alloc] initWithTitle:entry[0]
                    action:NSSelectorFromString(entry[1]) keyEquivalent:@""];
                [menuItem setTarget:self];
                [menuItem setRepresentedObject:ToNSString(item.path)];
                [menu addItem:menuItem];
            }
            [menu addItem:[NSMenuItem separatorItem]];
            NSMenuItem *clear = [[NSMenuItem alloc] initWithTitle:@"Clear Recent Items"
                action:@selector(clearRecent:) keyEquivalent:@""];
            [clear setTarget:self];
            [menu addItem:clear];
            [button setMenu:menu];
            [_recentView addSubview:button];
            if (!_firstRecentButton) _firstRecentButton = button;
            y -= 26;
        }
    }
    [_chooseButton setNextKeyView:_openButton];
    [_openButton setNextKeyView:_firstRecentButton ?: _firstExampleButton];
    if (_firstRecentButton) [_firstRecentButton setNextKeyView:_firstExampleButton];
    [_firstExampleButton setNextKeyView:_documentationButton];
    [_documentationButton setNextKeyView:_aboutButton];
    [_aboutButton setNextKeyView:_chooseButton];
}

- (void)show
{
    [self refresh];
    [_window center];
    [NSApp activateIgnoringOtherApps:YES];
    [_window makeKeyAndOrderFront:nil];
    [_window makeFirstResponder:_chooseButton];
}

- (void)hide
{
    [_window orderOut:nil];
}

- (void)setOpeningStatus:(NSString *)status
{
    [_connectionField setStringValue:status];
    [_connectionField setTextColor:[NSColor systemBlueColor]];
    [_connectionField setAccessibilityLabel:status];
}

- (void)chooseRDataFrame:(id)sender
{
    (void)sender;
    if (g_mainRNotifyPath.empty()) return;
    [self setOpeningStatus:@"Reading data frames from R…"];
    QueueDataBrowseMainRTask({std::string([[[NSUUID UUID] UUIDString] UTF8String])});
}

- (void)openFile:(id)sender
{
    (void)sender;
    [self setOpeningStatus:@"Choose a data file…"];
    ShowImportChooserOnMain();
}

- (void)openRecent:(id)sender
{
    NSString *path = [sender isKindOfClass:[NSMenuItem class]]
        ? [sender representedObject] : [sender identifier];
    if (!path || ![[NSFileManager defaultManager] fileExistsAtPath:path]) {
        ShowWorkbenchMessageOnMain(@"Open Recent Data",
            @"The selected data file no longer exists. You can remove it from Recent.");
        return;
    }
    [self setOpeningStatus:@"Opening data…"];
    OpenWelcomeDataFileAtURLOnMain([NSURL fileURLWithPath:path]);
}

- (void)revealRecent:(id)sender
{
    NSString *path = [sender representedObject];
    [[NSWorkspace sharedWorkspace] activateFileViewerSelectingURLs:
        @[[NSURL fileURLWithPath:path]]];
}

- (void)removeRecent:(id)sender
{
    NSString *path = [sender representedObject];
    NSMutableArray *paths = [WelcomeRecentPaths() mutableCopy];
    [paths removeObject:path];
    SaveWelcomeRecentPaths(paths);
    [self refresh];
}

- (void)clearRecent:(id)sender
{
    (void)sender;
    SaveWelcomeRecentPaths(@[]);
    [self refresh];
}

- (void)openExample:(id)sender
{
    NSString *example = [sender identifier];
    if (!example) return;
    [self setOpeningStatus:[NSString stringWithFormat:@"Opening %@…", example]];
    NSString *fileName = nil;
    if ([example isEqualToString:@"mtcars"]) fileName = @"mtcars.csv";
    if ([example isEqualToString:@"Alien"]) fileName = @"Alien.csv";
    NSString *path = fileName && !g_applicationRootPath.empty()
        ? [[ToNSString(g_applicationRootPath) stringByAppendingPathComponent:@"examples"]
              stringByAppendingPathComponent:fileName]
        : nil;
    if (!path || ![[NSFileManager defaultManager] fileExistsAtPath:path]) {
        ShowWorkbenchMessageOnMain(@"Example datasets",
            @"The selected example dataset is not available. Reinstall LinkEDA and try again.");
        [self refresh];
        return;
    }
    OpenWelcomeDataFileAtURLOnMain([NSURL fileURLWithPath:path]);
}

- (void)openDocumentation:(id)sender
{
    (void)sender;
    [self setOpeningStatus:@"Opening documentation…"];
    OpenWelcomeDocumentationOnMain();
    [self refresh];
}

- (void)openAbout:(id)sender
{
    (void)sender;
    ShowAboutLinkEDAOnMain();
}

@end

static void ShowWelcomeOnMain()
{
    dispatch_async(dispatch_get_main_queue(), ^{
      // Welcome is the primary no-data surface. Utility palettes can remain
      // visible after an earlier interaction, but they must not obscure or be
      // mistaken for the launch window.
      if (g_panel) [g_panel orderOut:nil];
      if (g_palettePanel) [g_palettePanel orderOut:nil];
      if (!g_welcomeController) {
          g_welcomeController = [[WelcomeWindowController alloc]
              initWithVersion:g_applicationVersion.empty() ? "unknown" : g_applicationVersion];
      }
      [g_welcomeController show];
    });
}

static void CloseWelcomeOnMain()
{
    dispatch_async(dispatch_get_main_queue(), ^{
      if (g_welcomeController) [g_welcomeController hide];
    });
}

static void ShowAboutLinkEDAOnMain()
{
    dispatch_async(dispatch_get_main_queue(), ^{
      const auto &credits = rlispstat::core::DefaultApplicationCredits();
      const auto lines = rlispstat::core::AboutCreditLines(credits);
      NSString *information = [NSString stringWithFormat:@"%@\n%@\n%@\n\nVersion %@",
          ToNSString(lines[0]), ToNSString(lines[1]), ToNSString(lines[2]),
          ToNSString(g_applicationVersion.empty() ? "unknown" : g_applicationVersion)];
      NSAlert *alert = [[NSAlert alloc] init];
      [alert setMessageText:@"LinkEDA"];
      [alert setInformativeText:information];
      [alert setIcon:[NSApp applicationIconImage]];
      [alert addButtonWithTitle:@"OK"];
      [alert runModal];
    });
}

static void OpenWelcomeDocumentationOnMain()
{
    const auto &strings = rlispstat::core::DefaultWelcomeStrings();
    ShowWorkbenchMessageOnMain(ToNSString(strings.documentation),
        ToNSString(strings.documentationWorkInProgress));
}

static void ShowActiveDatasetOnMain()
{
    dispatch_async(dispatch_get_main_queue(), ^{
      std::string group;
      int rows = 0;
      size_t cols = 0;
      size_t selectedRows = 0;
      {
          std::lock_guard<std::mutex> lock(g_mutex);
          group = ActiveDatasetGroupUnlocked();
          if (!group.empty()) {
              const DataFrameModel *df = FindDataFrameUnlockedConst(group);
              if (df) {
                  rows = df->rows;
                  cols = df->columns.size();
              }
              auto selectionIt = g_groupSelections.find(group);
              if (selectionIt != g_groupSelections.end()) {
                  selectedRows = selectionIt->second.size();
              }
          }
      }
      if (group.empty()) {
          ShowWorkbenchMessageOnMain(ToNSString(NoActiveDatasetTitle()), ToNSString(ImportOrRegisterDatasetStatus()));
          return;
      }
      ShowWorkbenchMessageOnMain(ToNSString(ActiveDatasetTitle()),
                                 ToNSString(ActiveDatasetSummaryText(group, rows, cols, selectedRows)));
    });
}

static void ShowChooseLabelColumnDialogOnMain(const std::string &group)
{
    const ChooseLabelColumnDialogState dialogState = BuildChooseLabelColumnDialogState();
    std::string requestedGroup = group;
    dispatch_async(dispatch_get_main_queue(), ^{
      std::string activeGroup = requestedGroup;
      DataFrameModel df;
      std::string current;
      {
          std::lock_guard<std::mutex> lock(g_mutex);
          if (activeGroup.empty()) {
              activeGroup = ActiveDatasetGroupUnlocked();
          }
          const DataFrameModel *found = FindDataFrameUnlockedConst(activeGroup);
          if (found) {
              df = *found;
              current = CurrentLabelColumnForGroupUnlocked(activeGroup);
          }
      }
      if (activeGroup.empty() || df.columns.empty()) {
          ShowWorkbenchMessageOnMain(ToNSString(dialogState.statusTitle),
                                     ToNSString(ImportOrRegisterDatasetStatus()));
          return;
      }

      NSAlert *alert = [[NSAlert alloc] init];
      [alert setMessageText:ToNSString(dialogState.title)];
      [alert setInformativeText:ToNSString(dialogState.informativeText)];
      [alert addButtonWithTitle:ToNSString(dialogState.chooseButtonTitle)];
      [alert addButtonWithTitle:ToNSString(dialogState.cancelButtonTitle)];
      NSView *accessory = [[NSView alloc] initWithFrame:NSMakeRect(0, 0, 360, 72)];
      [accessory addSubview:GLMLabel(ToNSString(ChooseLabelColumnDatasetLabel(activeGroup)), NSMakeRect(0, 44, 340, 20), 12, NSFontWeightMedium)];
      NSPopUpButton *popup = [[NSPopUpButton alloc] initWithFrame:NSMakeRect(0, 8, 240, 28)];
      [popup addItemWithTitle:ToNSString(dialogState.noneOptionTitle)];
      for (const DataColumn &col : df.columns) {
          [popup addItemWithTitle:ToNSString(col.name)];
      }
      if (!current.empty()) {
          [popup selectItemWithTitle:ToNSString(current)];
      }
      [accessory addSubview:popup];
      [alert setAccessoryView:accessory];
      if ([alert runModal] != NSAlertFirstButtonReturn) {
          return;
      }

      std::string selected = [[popup titleOfSelectedItem] UTF8String];
      if (selected == dialogState.noneOptionTitle) {
          selected.clear();
      }
      std::string message;
      if (!SetGroupLabelColumn(activeGroup, selected, &message)) {
          ShowWorkbenchMessageOnMain(ToNSString(rlispstat::core::ChooseLabelColumnStatusTitle()), ToNSString(message));
      }
    });
}

static std::string UniqueNativeDatasetName(const std::string &path)
{
    std::string base = SafeDatasetNameForPath(path);
    std::lock_guard<std::mutex> lock(g_mutex);
    return MacCommandDispatcher().applicationState().datasets().uniqueDatasetName(base);
}

static bool RunRscriptTask(NSArray *args,
                           const std::string &launchFailedStatus,
                           const std::string &fallbackFailedStatus,
                           std::string *message)
{
    NSTask *task = [[NSTask alloc] init];
    NSString *rscript = ToNSString(g_rscriptPath.empty() ? "Rscript" : g_rscriptPath);
    if ([rscript isAbsolutePath]) {
        [task setLaunchPath:rscript];
        [task setArguments:args];
    } else {
        NSMutableArray *envArgs = [NSMutableArray arrayWithObject:rscript];
        [envArgs addObjectsFromArray:args];
        [task setLaunchPath:@"/usr/bin/env"];
        [task setArguments:envArgs];
    }
    NSPipe *stderrPipe = [NSPipe pipe];
    NSPipe *stdoutPipe = [NSPipe pipe];
    [task setStandardError:stderrPipe];
    [task setStandardOutput:stdoutPipe];

    @try {
        [task launch];
        [task waitUntilExit];
    } @catch (NSException *exception) {
        if (message) *message = launchFailedStatus;
        return false;
    }

    NSData *stderrData = [[stderrPipe fileHandleForReading] readDataToEndOfFile];
    NSString *stderrText = [[NSString alloc] initWithData:stderrData encoding:NSUTF8StringEncoding];
    NSData *stdoutData = [[stdoutPipe fileHandleForReading] readDataToEndOfFile];
    NSString *stdoutText = [[NSString alloc] initWithData:stdoutData encoding:NSUTF8StringEncoding];
    if ([task terminationStatus] != 0) {
        std::string err = stderrText ? [stderrText UTF8String] : "";
        if (err.empty() && stdoutText) err = [stdoutText UTF8String];
        if (err.empty()) err = fallbackFailedStatus;
        if (message) *message = err;
        return false;
    }
    return true;
}

static void RemoveTemporaryFiles(NSArray *paths)
{
    NSFileManager *manager = [NSFileManager defaultManager];
    for (NSString *path in paths) {
        if (path) {
            [manager removeItemAtPath:path error:nil];
        }
    }
}

static bool ImportDataFileIntoBackend(const std::string &path,
                                      std::string *message,
                                      std::string *importedGroup)
{
    std::string group = UniqueNativeDatasetName(path);
    NSString *uuid = [[NSUUID UUID] UUIDString];
    NSString *tmp = NSTemporaryDirectory();
    NSString *scriptPath = [tmp stringByAppendingPathComponent:[NSString stringWithFormat:@"rlispstat-import-%@.R", uuid]];
    NSString *payloadPath = [tmp stringByAppendingPathComponent:[NSString stringWithFormat:@"rlispstat-import-%@.payload", uuid]];
    std::string importScript = NativeImportRScript();
    NSString *script = [NSString stringWithUTF8String:importScript.c_str()];
    if (![script writeToFile:scriptPath atomically:YES encoding:NSUTF8StringEncoding error:nil]) {
        if (message) *message = NativeImportTemporaryScriptFailedStatus();
        return false;
    }

    if (!RunRscriptTask(@[scriptPath, ToNSString(path), ToNSString(group), payloadPath],
                        NativeImportRscriptLaunchFailedStatus(),
                        NativeImportRscriptFailedStatus(),
                        message)) {
        RemoveTemporaryFiles(@[scriptPath, payloadPath]);
        return false;
    }

    NSString *payload = [NSString stringWithContentsOfFile:payloadPath encoding:NSUTF8StringEncoding error:nil];
    RemoveTemporaryFiles(@[scriptPath, payloadPath]);
    if (!payload || [payload length] == 0) {
        if (message) *message = NativeImportPayloadMissingStatus();
        return false;
    }

    std::vector<std::string> lines = SplitLines(std::string([payload UTF8String]));
    std::string reply = AppendMainRTasks(HandleCommandLines(lines));
    if (reply.rfind("ERR ", 0) == 0) {
        if (message) *message = reply.substr(4);
        return false;
    }
    if (message) {
        {
            std::lock_guard<std::mutex> lock(g_mutex);
            const DataFrameModel *df = FindDataFrameUnlockedConst(group);
            if (df) {
                *message = NativeImportDatasetLoadedStatus(group, df->rows, df->columns.size());
            } else {
                *message = NativeImportDatasetLoadedStatus(group);
            }
        }
    }
    if (importedGroup) *importedGroup = group;
    return true;
}

static void SetNativeImportPanelExtensions(NSOpenPanel *panel,
                                           const std::vector<std::string> &extensions)
{
    if (!panel) return;
    if (@available(macOS 11.0, *)) {
        NSMutableArray<UTType *> *contentTypes = [NSMutableArray array];
        for (const std::string &extension : extensions) {
            UTType *type = [UTType typeWithFilenameExtension:ToNSString(LowerCopy(extension))];
            if (type && ![contentTypes containsObject:type]) [contentTypes addObject:type];
        }
        [panel setAllowedContentTypes:contentTypes];
    } else {
#pragma clang diagnostic push
#pragma clang diagnostic ignored "-Wdeprecated-declarations"
        NSMutableArray<NSString *> *fileTypes = [NSMutableArray array];
        for (const std::string &extension : extensions) {
            [fileTypes addObject:ToNSString(extension)];
        }
        [panel setAllowedFileTypes:fileTypes];
#pragma clang diagnostic pop
    }
}

@interface NativeImportFilterTarget : NSObject
{
    NSOpenPanel *_panel;
    std::vector<rlispstat::core::NativeImportFileFilter> _filters;
}
- (instancetype)initWithPanel:(NSOpenPanel *)panel
                       filters:(const std::vector<rlispstat::core::NativeImportFileFilter> &)filters;
- (void)filterChanged:(id)sender;
@end

@implementation NativeImportFilterTarget
- (instancetype)initWithPanel:(NSOpenPanel *)panel
                       filters:(const std::vector<rlispstat::core::NativeImportFileFilter> &)filters
{
    self = [super init];
    if (self) { _panel = panel; _filters = filters; }
    return self;
}
- (void)filterChanged:(id)sender
{
    const NSInteger index = [sender indexOfSelectedItem];
    if (index < 0 || (std::size_t)index >= _filters.size()) return;
    SetNativeImportPanelExtensions(_panel, _filters[(std::size_t)index].extensions);
}
@end

struct PreparedNativeImportFile {
    bool ok = false;
    std::string path;
    std::string sourcePath;
    std::string temporaryDirectory;
    std::string message;
};

static bool NativeImportURLNeedsStaging(NSURL *url)
{
    NSString *path = [url path];
    if ([path rangeOfString:@"/Library/CloudStorage/"].location != NSNotFound) return true;
    struct stat metadata;
    if (stat([path fileSystemRepresentation], &metadata) != 0) return false;
#ifdef SF_DATALESS
    if ((metadata.st_flags & SF_DATALESS) != 0) return true;
#endif
    return false;
}

static PreparedNativeImportFile PrepareNativeImportFile(NSURL *selectedURL)
{
    PreparedNativeImportFile prepared;
    if (!selectedURL || ![selectedURL isFileURL]) {
        prepared.message = "The selected item is not a readable file URL.";
        return prepared;
    }
    NSString *originalPath = [selectedURL path];
    prepared.path = [originalPath UTF8String];
    prepared.sourcePath = prepared.path;
    const BOOL scoped = [selectedURL startAccessingSecurityScopedResource];
    const bool stage = scoped || NativeImportURLNeedsStaging(selectedURL);
    if (!stage) {
        prepared.ok = true;
        return prepared;
    }

    NSString *directory = [NSTemporaryDirectory() stringByAppendingPathComponent:
        [NSString stringWithFormat:@"rlispstat-import-%@", [[NSUUID UUID] UUIDString]]];
    NSError *directoryError = nil;
    if (![[NSFileManager defaultManager] createDirectoryAtPath:directory
                                  withIntermediateDirectories:YES
                                                   attributes:nil
                                                        error:&directoryError]) {
        if (scoped) [selectedURL stopAccessingSecurityScopedResource];
        prepared.message = directoryError ? [[directoryError localizedDescription] UTF8String] :
            "Could not create a temporary directory for the selected file.";
        return prepared;
    }

    NSURL *destination = [NSURL fileURLWithPath:
        [directory stringByAppendingPathComponent:[selectedURL lastPathComponent]]];
    __block NSError *copyError = nil;
    NSError *coordinationError = nil;
    NSFileCoordinator *coordinator = [[NSFileCoordinator alloc] initWithFilePresenter:nil];
    [coordinator coordinateReadingItemAtURL:selectedURL options:0 error:&coordinationError
                                 byAccessor:^(NSURL *coordinatedURL) {
        if (![[NSFileManager defaultManager] copyItemAtURL:coordinatedURL
                                                    toURL:destination
                                                    error:&copyError]) return;
    }];
    if (scoped) [selectedURL stopAccessingSecurityScopedResource];
    NSError *error = coordinationError ?: copyError;
    if (error || ![[NSFileManager defaultManager] fileExistsAtPath:[destination path]]) {
        [[NSFileManager defaultManager] removeItemAtPath:directory error:nil];
        prepared.message = error ? [[error localizedDescription] UTF8String] :
            "The selected cloud file could not be made available for import.";
        return prepared;
    }
    prepared.ok = true;
    prepared.path = [[destination path] UTF8String];
    prepared.temporaryDirectory = [directory UTF8String];
    return prepared;
}

static void HideNativeImportAccessoryDisclosureButton(NSView *view)
{
    if (!view) return;
    if ([view isKindOfClass:[NSButton class]]) {
        NSButton *button = (NSButton *)view;
        NSString *title = [[button title] lowercaseString];
        NSString *action = [button action] ?
            [NSStringFromSelector([button action]) lowercaseString] : @"";
        if ([title isEqualToString:@"show options"] ||
            [title isEqualToString:@"hide options"] ||
            [action containsString:@"accessory"]) {
            [button setHidden:YES];
            return;
        }
    }
    for (NSView *subview in [view subviews]) {
        HideNativeImportAccessoryDisclosureButton(subview);
    }
}

static void OpenWelcomeDataFileAtURLOnMain(NSURL *selectedURL)
{
    if (!selectedURL) return;
    NSURL *urlCopy = [selectedURL copy];
    std::thread importer([urlCopy]() {
        PreparedNativeImportFile prepared = PrepareNativeImportFile(urlCopy);
        if (!prepared.ok) {
            ShowWorkbenchMessageOnMain(ToNSString(NativeImportFailedTitle()),
                                       ToNSString(prepared.message));
            return;
        }
        if (!g_mainRNotifyPath.empty()) {
            QueueImportDataMainRTask({prepared.path, prepared.sourcePath,
                !prepared.temporaryDirectory.empty()});
            return;
        }
        std::string message;
        std::string importedGroup;
        bool ok = ImportDataFileIntoBackend(prepared.path, &message, &importedGroup);
        if (!prepared.temporaryDirectory.empty()) {
            [[NSFileManager defaultManager]
                removeItemAtPath:ToNSString(prepared.temporaryDirectory) error:nil];
        }
        if (ok && !importedGroup.empty()) {
            NoteWelcomeRecentPathOnMain(prepared.sourcePath.empty()
                ? prepared.path : prepared.sourcePath);
            UpdateActiveDatasetMenuOnMain();
            ShowDataSheetOnMain(importedGroup);
            UpdatePanelOnMain();
            CloseWelcomeOnMain();
        }
        ShowWorkbenchMessageOnMain(
            ToNSString(ok ? NativeImportDialogTitle() : NativeImportFailedTitle()),
            ToNSString(message));
    });
    importer.detach();
}

static void ShowImportChooserOnMain()
{
    dispatch_async(dispatch_get_main_queue(), ^{
      NSOpenPanel *panel = [[NSOpenPanel alloc] init];
      [panel setTitle:ToNSString(NativeImportDialogTitle())];
      [panel setPrompt:@"Import"];
      [panel setCanChooseFiles:YES];
      [panel setCanChooseDirectories:NO];
      [panel setAllowsMultipleSelection:NO];
      const std::vector<rlispstat::core::NativeImportFileFilter> filters =
          rlispstat::core::NativeImportFileFilters();
      SetNativeImportPanelExtensions(panel, filters.front().extensions);
      NSView *accessory = [[NSView alloc] initWithFrame:NSMakeRect(0, 0, 410, 50)];
      NSTextField *filterLabel = [NSTextField labelWithString:@"Data format"];
      [filterLabel setFrame:NSMakeRect(0, 29, 360, 18)];
      NSPopUpButton *filterPopup = [[NSPopUpButton alloc]
          initWithFrame:NSMakeRect(0, 0, 360, 27) pullsDown:NO];
      for (const auto &filter : filters) [filterPopup addItemWithTitle:ToNSString(filter.title)];
      NativeImportFilterTarget *filterTarget = [[NativeImportFilterTarget alloc]
          initWithPanel:panel filters:filters];
      [filterPopup setTarget:filterTarget];
      [filterPopup setAction:@selector(filterChanged:)];
      [accessory addSubview:filterLabel];
      [accessory addSubview:filterPopup];
      [panel setAccessoryView:accessory];
      [panel setAccessoryViewDisclosed:YES];
      [NSApp activateIgnoringOtherApps:YES];
      [panel beginWithCompletionHandler:^(NSModalResponse result) {
        (void)filterTarget;
        if (result != NSModalResponseOK || [[panel URLs] count] == 0) {
            if (g_welcomeController) [g_welcomeController refresh];
            return;
        }
        OpenWelcomeDataFileAtURLOnMain([[panel URLs] objectAtIndex:0]);
      }];
      dispatch_async(dispatch_get_main_queue(), ^{
        HideNativeImportAccessoryDisclosureButton([panel contentView]);
      });
    });
}

static std::string UniqueNativeDatasetNameFromBase(const std::string &baseName)
{
