static bool QueueRDataReturnForGroup(const std::string &group,
                                     const std::string &mode,
                                     std::string *message)
{
    NativeREditSession session;
    DataFrameModel dataFrame;
    std::vector<int> rows;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        auto sessionIt = g_rEditSessionsByGroup.find(group);
        const DataFrameModel *registered = FindDataFrameUnlockedConst(group);
        if (sessionIt == g_rEditSessionsByGroup.end() || !registered) {
            if (message) *message = "The active dataset is not waiting to return data to R.";
            return false;
        }
        session = sessionIt->second;
        dataFrame = *registered;
        if (mode == "selected") {
            auto selected = g_groupSelections.find(group);
            if (selected != g_groupSelections.end()) {
                rows.assign(selected->second.begin(), selected->second.end());
            }
        }
        if (mode == "cancel") {
            g_rEditSessionsByGroup.erase(sessionIt);
        }
    }
    if (mode == "cancel") {
        QueueDataReturnMainRTask({session.requestId, group, "", mode, {}});
        if (message) *message = "Cancelled without returning data to R.";
        return true;
    }

    NSString *directory = [NSTemporaryDirectory() stringByAppendingPathComponent:
        [NSString stringWithFormat:@"rlispstat-return-%@", [[NSUUID UUID] UUIDString]]];
    NSError *directoryError = nil;
    if (![[NSFileManager defaultManager] createDirectoryAtPath:directory
                                  withIntermediateDirectories:YES
                                                   attributes:nil
                                                        error:&directoryError]) {
        if (message) *message = directoryError ? [[directoryError localizedDescription] UTF8String] :
            "Could not create a temporary return directory.";
        return false;
    }
    NSString *payloadPath = [directory stringByAppendingPathComponent:@"data.payload"];
    if (!WriteNativeDataFramePayloadForR(dataFrame, payloadPath, message)) {
        [[NSFileManager defaultManager] removeItemAtPath:directory error:nil];
        return false;
    }
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        auto current = g_rEditSessionsByGroup.find(group);
        if (current != g_rEditSessionsByGroup.end() &&
            current->second.requestId == session.requestId) {
            g_rEditSessionsByGroup.erase(current);
        }
    }
    QueueDataReturnMainRTask({session.requestId, group,
        std::string([payloadPath UTF8String]), mode, rows});
    if (message) {
        *message = mode == "selected"
            ? "Returning selected rows to R."
            : "Returning data to R.";
    }
    return true;
}

static bool QueueRDataAssignmentForGroup(const std::string &group,
                                         const std::string &objectName,
                                         const std::string &mode,
                                         bool replaceExisting,
                                         std::string *message)
{
    if (objectName.empty() || objectName.find_first_of("\r\n\t") != std::string::npos) {
        if (message) *message = "Enter a non-empty R object name without control characters.";
        return false;
    }
    DataFrameModel dataFrame;
    std::vector<int> rows;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        const DataFrameModel *registered = FindDataFrameUnlockedConst(group);
        if (!registered) {
            if (message) *message = "The active dataset is no longer available.";
            return false;
        }
        dataFrame = *registered;
        if (mode == "selected") {
            auto selected = g_groupSelections.find(group);
            if (selected != g_groupSelections.end()) {
                rows.assign(selected->second.begin(), selected->second.end());
            }
        }
    }

    NSString *directory = [NSTemporaryDirectory() stringByAppendingPathComponent:
        [NSString stringWithFormat:@"rlispstat-return-%@", [[NSUUID UUID] UUIDString]]];
    NSError *directoryError = nil;
    if (![[NSFileManager defaultManager] createDirectoryAtPath:directory
                                  withIntermediateDirectories:YES
                                                   attributes:nil
                                                        error:&directoryError]) {
        if (message) *message = directoryError ? [[directoryError localizedDescription] UTF8String] :
            "Could not create a temporary return directory.";
        return false;
    }
    NSString *payloadPath = [directory stringByAppendingPathComponent:@"data.payload"];
    if (!WriteNativeDataFramePayloadForR(dataFrame, payloadPath, message)) {
        [[NSFileManager defaultManager] removeItemAtPath:directory error:nil];
        return false;
    }
    QueueDataAssignMainRTask({
        std::string([[[NSUUID UUID] UUIDString] UTF8String]),
        group,
        std::string([payloadPath UTF8String]),
        objectName,
        mode,
        replaceExisting,
        rows
    });
    if (message) *message = "Waiting for the connected R session.";
    return true;
}

static void ShowRDataAssignmentDialogOnMain(const std::string &group,
                                            const std::string &mode)
{
    const std::string groupCopy = group;
    const std::string modeCopy = mode;
    dispatch_async(dispatch_get_main_queue(), ^{
      NSAlert *alert = [[NSAlert alloc] init];
      [alert setMessageText:modeCopy == "selected" ?
          @"Return selected rows to R" : @"Return data to R"];
      [alert setInformativeText:@"Choose the name of the object to create in the connected R session."];
      [alert addButtonWithTitle:@"Return"];
      [alert addButtonWithTitle:@"Cancel"];

      NSView *accessory = [[NSView alloc] initWithFrame:NSMakeRect(0, 0, 410, 76)];
      NSTextField *nameLabel = [NSTextField labelWithString:@"R object name:"];
      [nameLabel setFrame:NSMakeRect(0, 50, 110, 20)];
      [accessory addSubview:nameLabel];
      NSTextField *nameField = [[NSTextField alloc] initWithFrame:NSMakeRect(115, 45, 295, 26)];
      NSString *suffix = modeCopy == "selected" ? @"_selected" : @"_edited";
      [nameField setStringValue:[ToNSString(groupCopy) stringByAppendingString:suffix]];
      [accessory addSubview:nameField];
