      std::vector<std::string>categorical=rlispstat::core::ModelTrellisCategoricalVariables(data,candidateSpec);
      if(categorical.empty()){ShowWorkbenchMessageOnMain(@"Linear Model Trellis",@"The active dataset has no suitable categorical conditioning variable.");return;}

      NSAlert*alert=[[NSAlert alloc]init];[alert setMessageText:@"Linear Model Trellis"];[alert setInformativeText:@"Choose the dependent variable and one or two categorical variables that define the panel rows and columns. Predictors can be added after the trellis is created."];[alert addButtonWithTitle:@"Create"];[alert addButtonWithTitle:@"Cancel"];
      NSView*accessory=[[NSView alloc]initWithFrame:NSMakeRect(0,0,440,190)];[accessory addSubview:GLMLabel(ToNSString(DatasetDialogLabel(seed.group)),NSMakeRect(0,164,420,20),12,NSFontWeightMedium)];
      NSArray*labels=@[@"Dependent variable",@"Panel rows",@"Panel columns",@"Scope"];
      for(NSInteger i=0;i<4;i++)[accessory addSubview:GLMLabel(labels[i],NSMakeRect(0,126-i*32,126,22),12,NSFontWeightRegular)];
      NSPopUpButton*response=[[NSPopUpButton alloc]initWithFrame:NSMakeRect(132,122,190,28)];for(const auto&name:numeric)[response addItemWithTitle:ToNSString(name)];if(std::find(numeric.begin(),numeric.end(),seed.yLabel)!=numeric.end())[response selectItemWithTitle:ToNSString(seed.yLabel)];
      auto conditionPopup=^NSPopUpButton*(CGFloat y){NSPopUpButton*p=[[NSPopUpButton alloc]initWithFrame:NSMakeRect(132,y,190,28)];[p addItemWithTitle:@"None"];[[p lastItem]setRepresentedObject:@""];for(const auto&name:categorical){[p addItemWithTitle:ToNSString(name)];[[p lastItem]setRepresentedObject:ToNSString(name)];}return p;};
      NSPopUpButton*rows=conditionPopup(90);NSPopUpButton*columns=conditionPopup(58);[columns selectItemAtIndex:1];
      NSPopUpButton*scope=[[NSPopUpButton alloc]initWithFrame:NSMakeRect(132,26,190,28)];for(NSArray*entry in @[@[@"All data",@"all"],@[@"Selected rows",@"selected"],@[@"Unselected rows",@"unselected"]]){[scope addItemWithTitle:entry[0]];[[scope lastItem]setRepresentedObject:entry[1]];}
      for(NSView*v in @[response,rows,columns,scope])[accessory addSubview:v];NSTextField*hint=GLMLabel(@"Conditioning variables cannot be repeated or used as predictors.",NSMakeRect(0,0,430,18),11,NSFontWeightRegular);[hint setTextColor:[NSColor secondaryLabelColor]];[accessory addSubview:hint];[alert setAccessoryView:accessory];
      LinearModelTrellisDialogValidator*validator=[[LinearModelTrellisDialogValidator alloc]init];validator.responsePopup=response;validator.rowPopup=rows;validator.columnPopup=columns;validator.createButton=alert.buttons.firstObject;[response setTarget:validator];[response setAction:@selector(updateCreateButton:)];[rows setTarget:validator];[rows setAction:@selector(updateCreateButton:)];[columns setTarget:validator];[columns setAction:@selector(updateCreateButton:)];[validator updateCreateButton:nil];
      if([alert runModal]!=NSAlertFirstButtonReturn)return;

      ModelTrellisState state;state.id="model_trellis:"+seed.group+":"+std::to_string((long long)time(nullptr))+":"+std::to_string(std::rand()%1000000);state.sourceModelGroup=seed.group;state.specification.baseModel.group=seed.group;state.specification.baseModel.response=[[response titleOfSelectedItem]UTF8String];state.specification.baseModel.scope=[[[scope selectedItem]representedObject]UTF8String];state.specification.panelContent=ModelTrellisPanelContent::CompactSummary;
      NSString*row=[[[rows selectedItem]representedObject]description];NSString*column=[[[columns selectedItem]representedObject]description];std::string error;if(row.length&&!rlispstat::core::SetModelTrellisConditioningVariable(state.specification,ModelTrellisDimension::Rows,std::string([row UTF8String]),data,&error)){ShowWorkbenchMessageOnMain(@"Linear Model Trellis",ToNSString(error));return;}if(column.length&&!rlispstat::core::SetModelTrellisConditioningVariable(state.specification,ModelTrellisDimension::Columns,std::string([column UTF8String]),data,&error)){ShowWorkbenchMessageOnMain(@"Linear Model Trellis",ToNSString(error));return;}
      std::set<int>selection;{std::lock_guard<std::mutex>lock(g_mutex);CaptureActiveAnalysisScopeUnlocked(seed.group,state.dataScope,state.dataScopeCaptured);const std::vector<int>scopeRows=RowsForCapturedAnalysisScope(state.dataScope,state.dataScopeCaptured);if(state.dataScope.kind==rlispstat::core::AnalysisScopeKind::ExplicitRowIds){selection.insert(scopeRows.begin(),scopeRows.end());state.specification.baseModel.scope="selected";}else{auto selected=g_groupSelections.find(seed.group);if(selected!=g_groupSelections.end())selection=selected->second;}}state.panels=rlispstat::core::BuildModelTrellisPanels(state.specification,data,selection);state.status="Waiting for R panel fits...";const std::string id=state.id;{std::lock_guard<std::mutex>lock(g_mutex);g_modelTrellises[id]=std::move(state);}ShowModelTrellisOnMain(id);RequestModelTrellisFit(id);
    });
}

static void ShowNewLinkedScatterMatrixDialogOnMain(PlotModel *model)
{
    const ScatterMatrixCreationDialogState dialogState = BuildScatterMatrixCreationDialogState();
    if (!model) {
        ShowWorkbenchMessageOnMain(ToNSString(NoActiveDatasetTitle()), ToNSString(dialogState.noActiveDatasetStatus));
        return;
    }

    dispatch_async(dispatch_get_main_queue(), ^{
      PlotModel seed;
      {
          std::lock_guard<std::mutex> lock(g_mutex);
          seed = *model;
      }
      if (seed.variables.size() < 2) {
          ShowWorkbenchMessageOnMain(ToNSString(dialogState.title), ToNSString(dialogState.needsTwoNumericVariablesStatus));
          return;
      }

      NSAlert *alert = [[NSAlert alloc] init];
      [alert setMessageText:ToNSString(dialogState.title)];
      [alert setInformativeText:ToNSString(dialogState.informativeText)];
      [alert addButtonWithTitle:ToNSString(dialogState.createButtonTitle)];
      [alert addButtonWithTitle:ToNSString(dialogState.cancelButtonTitle)];

      CGFloat height = std::min<CGFloat>(260.0, 32.0 + seed.variables.size() * 24.0);
      NSView *accessory = [[NSView alloc] initWithFrame:NSMakeRect(0, 0, 380, height + 48)];
      NSTextField *dataset = GLMLabel(ToNSString(DatasetDialogLabel(seed.group)), NSMakeRect(0, height + 22, 360, 20), 12, NSFontWeightMedium);
      [accessory addSubview:dataset];

      NSScrollView *scroll = [[NSScrollView alloc] initWithFrame:NSMakeRect(0, 34, 240, height)];
      [scroll setHasVerticalScroller:YES];
      [scroll setBorderType:NSNoBorder];
      NSView *list = [[NSView alloc] initWithFrame:NSMakeRect(0, 0, 220, std::max<CGFloat>(height, seed.variables.size() * 24.0))];
      NSMutableArray<NSButton *> *buttons = [NSMutableArray array];
      size_t defaultCount = std::min<size_t>(4, seed.variables.size());
      for (size_t i = 0; i < seed.variables.size(); ++i) {
          CGFloat y = list.frame.size.height - 24.0 * (CGFloat)(i + 1);
          NSButton *check = [[NSButton alloc] initWithFrame:NSMakeRect(0, y, 210, 22)];
          [check setButtonType:NSButtonTypeSwitch];
          [check setTitle:ToNSString(seed.variables[i].name)];
          [check setState:i < defaultCount ? NSControlStateValueOn : NSControlStateValueOff];
          [list addSubview:check];
          [buttons addObject:check];
      }
      [scroll setDocumentView:list];
      [accessory addSubview:scroll];

      NSTextField *titleField = [[NSTextField alloc] initWithFrame:NSMakeRect(252, height - 4, 120, 24)];
      [titleField setStringValue:@""];
      [titleField setPlaceholderString:ToNSString(dialogState.optionalTitlePlaceholder)];
      [accessory addSubview:titleField];

      NSTextField *hint = GLMLabel(ToNSString(dialogState.hintText),
                                   NSMakeRect(0, 2, 372, 26), 11, NSFontWeightRegular);
      [hint setTextColor:[NSColor secondaryLabelColor]];
      [accessory addSubview:hint];
      [alert setAccessoryView:accessory];

      if ([alert runModal] != NSAlertFirstButtonReturn) {
          return;
      }

      std::vector<std::string> selected;
      for (NSUInteger i = 0; i < [buttons count] && i < seed.variables.size(); ++i) {
          if ([[buttons objectAtIndex:i] state] == NSControlStateValueOn) {
              selected.push_back(seed.variables[(size_t)i].name);
          }
      }
      if (selected.size() < 2) {
          ShowWorkbenchMessageOnMain(ToNSString(dialogState.title), ToNSString(dialogState.selectAtLeastTwoNumericVariablesStatus));
          return;
      }

      std::string title = [[titleField stringValue] UTF8String];
      if (title.empty()) {
          title = dialogState.defaultTitle;
      }

      PlotModel *created = new PlotModel(seed);
      created->kind = "scatter_matrix";
      created->isDatasetSeed = false;
      created->isGLMDiagnostic = false;
      created->id = "plot_" + std::to_string((long long)time(nullptr)) + "_" + std::to_string(std::rand() % 1000000);
      created->scatterMatrixVariables = selected;
      created->title = title;
      created->overlays.clear();
      created->nextOverlayId = 1;
      created->interactionMode = "select";
      created->selectionMode = "replace";
      RebuildScatterMatrixPoints(created);
      ComputeRanges(created);
      {
          std::lock_guard<std::mutex> lock(g_mutex);
          (void)AttachPlotModelUnlocked(created);
          EnsureGroupModelUnlocked(created->group, created);
      }
      AddPlotOnMain(created);
    });
}

