    NSMenuItem *helpItem = [[NSMenuItem alloc] initWithTitle:@"Help" action:nil keyEquivalent:@""];
    NSMenu *helpMenu = [[NSMenu alloc] initWithTitle:@"Help"];
    [helpMenu addItem:ApplicationMenuItem(@"Documentation", @"WELCOME_DOCUMENTATION", @"", 0)];
    [helpMenu addItem:ApplicationMenuItem(@"Welcome to LinkEDA", @"WELCOME_SHOW", @"", 0)];
    [mainMenu setSubmenu:helpMenu forItem:helpItem];
    [mainMenu addItem:helpItem];
    [NSApp setHelpMenu:helpMenu];

    [NSApp setMainMenu:mainMenu];
    RemoveNativeSingleWindowTabBarItem(viewMenu);
    g_menuBarInstalled = true;
    UpdateActiveDatasetMenuOnMain();
    UpdateAnalysisScopeStatusOnMain();
}

