static void ResetColorForGroupSelection(PlotModel *model)
{
    if (!model) {
        return;
    }
    std::set<int> selection;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        g_groupSelectedColors[model->group] = "black";
        auto it = g_groupSelections.find(model->group);
        if (it != g_groupSelections.end()) {
            selection = it->second;
        }
        auto colors = g_groupPointColors.find(model->group);
        if (colors != g_groupPointColors.end()) {
            for (int row : selection) {
                colors->second.erase(row);
            }
        }
        if (!selection.empty()) {
            RequestColorSmoothRecomputeForGroupUnlocked(model->group);
        }
    }
    PublishSpreadPlotMessage("ROW_COLORS_CHANGED", model->group, "palette", "", std::vector<int>(selection.begin(), selection.end()));
    RedrawGroupViewsSynchronouslyOnMain(model->group, true);
    UpdatePanelOnMain();
}

