static void MarkGeneralizedGLMsSelectionChanged(const std::string &group)
{
    std::lock_guard<std::mutex> lock(g_mutex);
    for (auto &entry : g_generalizedGLMs) {
        GeneralizedGLMState &state = entry.second;
        if (state.group == group && state.scope != "all" && !state.dataScopeCaptured) {
            state.modelVersion += 1;
            state.ok = false;
        }
    }
    for (auto &entry : g_generalizedComparisons) {
        GeneralizedComparisonState &state = entry.second;
        if (state.group != group || state.scope == "all" || state.dataScopeCaptured) {
            continue;
        }
        for (GeneralizedComparisonModel &model : state.models) {
            model.modelVersion += 1;
            model.isStale = true;
        }
    }
}

static GLMFitSummary FitMultipleLinearModelPortableMac(const PlotModel *model,
                                                       const std::string &dependent,
                                                       const std::vector<std::string> &terms,
                                                       const std::map<std::string, std::string> &termTypes,
                                                       const std::string &scope)
{
    if (!model) {
        return rlispstat::core::FitMultipleLinearModel(
            PlotModel{}, nullptr, {}, dependent, terms, termTypes, scope);
    }
    DataFrameModel dataframe;
    std::set<int> selected;
    bool hasDataframe = false;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        if (const DataFrameModel *found = FindDataFrameUnlockedConst(model->group)) {
            dataframe = *found;
            hasDataframe = true;
        }
        auto selection = g_groupSelections.find(model->group);
        if (selection != g_groupSelections.end()) selected = selection->second;
    }
    return rlispstat::core::FitMultipleLinearModel(
        *model, hasDataframe ? &dataframe : nullptr, selected,
        dependent, terms, termTypes, scope);
}

static SimpleFitSummary FitSimpleLinearModel(PlotModel *model, const std::string &scope)
{
    std::set<int> selected;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        auto it = g_groupSelections.find(model->group);
        if (it != g_groupSelections.end()) {
            selected = it->second;
        }
    }

    std::vector<rlispstat::core::ScatterplotPointValue> points;
    points.reserve(model->points.size());
    for (const DataPoint &p : model->points) {
        points.push_back(rlispstat::core::ScatterplotPointValue{p.row, p.x, p.y});
    }

    int totalRows = (int)model->points.size();
    if (!model->variables.empty()) {
        totalRows = (int)model->variables[0].values.size();
    }
    return rlispstat::core::FitSimpleLinearModel(points, selected, scope, totalRows);
}

