static bool BuildSeedPlotForGroupUnlocked(const std::string &group, PlotModel &seed)
{
    const DataFrameModel *found = FindDataFrameUnlockedConst(group);
    if (!found) {
        PlotModel *plot = FirstPlotForGroupUnlocked(group);
        if (plot) {
            seed = *plot;
            return true;
        }
        return false;
    }
    return rlispstat::core::BuildComparisonSeedPlot(*found, group, seed);
}

static bool BuildSeedPlotForGroup(const std::string &group, PlotModel &seed)
{
    std::lock_guard<std::mutex> lock(g_mutex);
    return BuildSeedPlotForGroupUnlocked(group, seed);
}

static CorrelationCellResult ComputeCorrelationCell(PlotModel *model, const std::vector<std::string> &variables,
                                                    const std::string &xName, const std::string &yName,
                                                    const std::string &missingMode,
                                                    const std::vector<int> &includedRows = {},
                                                    bool restrictRows = false)
{
    CorrelationCellResult cell;
    cell.xVariable = xName;
    cell.yVariable = yName;
    NumericVariable *xVar = FindVariable(model, xName);
    NumericVariable *yVar = FindVariable(model, yName);
    if (!xVar || !yVar) {
        cell.status = "missing_variable";
        return cell;
    }
    if (xName == yName) {
        cell.status = "diagonal";
        cell.rowsUsed = missingMode == "listwise"
            ? CompleteRowsForVariables(model, variables)
            : CompleteRowsForVariables(model, {xName});
        if (restrictRows) {
            cell.rowsUsed.erase(std::remove_if(cell.rowsUsed.begin(), cell.rowsUsed.end(),
                [&](int row) { return std::find(includedRows.begin(), includedRows.end(), row) == includedRows.end(); }),
                cell.rowsUsed.end());
        }
        cell.n = (int)cell.rowsUsed.size();
        return cell;
    }

    cell.rowsUsed = missingMode == "listwise"
        ? CompleteRowsForVariables(model, variables)
        : CompleteRowsForVariables(model, {xName, yName});
    if (restrictRows) {
        cell.rowsUsed.erase(std::remove_if(cell.rowsUsed.begin(), cell.rowsUsed.end(),
            [&](int row) { return std::find(includedRows.begin(), includedRows.end(), row) == includedRows.end(); }),
            cell.rowsUsed.end());
    }
    return rlispstat::core::ComputePearsonCorrelationForRows(
        xName, yName, xVar->values, yVar->values, cell.rowsUsed);
}

static void RefitCorrelationMatrixState(CorrelationMatrixState &state)
{
    state.cells.clear();
    if (state.multipleImputation && !state.precomputed) {
        DataFrameModel df;
        bool found = false;
        {
            std::lock_guard<std::mutex> lock(g_mutex);
            const DataFrameModel *current = FindDataFrameUnlockedConst(state.group);
            if (current) {
                df = *current;
                found = true;
            }
        }
        if (found && df.datasetType == "multiple_imputation") {
            state.imputationCount = std::max(1, df.imputationCount);
            state.poolingMethod = "Fisher z transformation plus Rubin's rules";
            state.note = "Multiple imputation correlation matrix: m = " +
                std::to_string(state.imputationCount) +
                "; Pearson r pooled on Fisher z scale with Rubin's rules.";
            for (const std::string &y : state.variables) {
                for (const std::string &x : state.variables) {
                    state.cells.push_back(rlispstat::core::ComputePooledCorrelationCell(df, state.variables, x, y, state.missingMode));
                }
            }
            state.modelVersion += 1;
            return;
        }
    }
    for (const std::string &y : state.variables) {
        for (const std::string &x : state.variables) {
            state.cells.push_back(ComputeCorrelationCell(
                &state.seed, state.variables, x, y, state.missingMode,
                RowsForCapturedAnalysisScope(state.dataScope, state.dataScopeCaptured),
                state.dataScopeCaptured &&
                    state.dataScope.kind == rlispstat::core::AnalysisScopeKind::ExplicitRowIds));
        }
    }
    state.modelVersion += 1;
}

using rlispstat::core::DendrogramRowCountForVariables;

static void RequestDimensionalityFitInMainR(DimensionalityState &state)
{
    MainRDimensionalityTask task;
    task.id = state.id;
    task.group = state.group;
    task.method = state.method;
    task.missingMode = state.missingMode;
    task.rotation = state.rotation;
    task.scope = state.scope;
    task.scale = state.scale;
    task.componentCount = state.componentCount;
    task.variables = state.variables;
    task.rows = RowsForCapturedAnalysisScope(state.dataScope, state.dataScopeCaptured);
    state.rFitPending = true;
    state.lastRFitSignature = rlispstat::core::DimensionalityFitSignature(
        state.method, state.missingMode, state.rotation, state.scope,
        state.scale, state.componentCount, state.variables);
    state.status = "Fitting factor analysis in the main R session...";
    QueueDimensionalityMainRTask(task);
}

static void RefitDimensionalityState(DimensionalityState &state)
{
    if (state.method != "pca" && state.method != "factor") state.method = "pca";
    if (state.missingMode != "listwise" && state.missingMode != "pairwise") state.missingMode = "listwise";
    if (!rlispstat::core::DimensionalityRotationIsValid(state.rotation)) state.rotation = "none";
    if (!rlispstat::core::DimensionalityScopeIsValid(state.scope)) state.scope = "all";

    if (state.method == "factor") {
        std::string signature = rlispstat::core::DimensionalityFitSignature(
            state.method, state.missingMode, state.rotation, state.scope,
            state.scale, state.componentCount, state.variables);
        if (state.rFitPending || (!state.components.empty() && state.lastRFitSignature == signature)) {
            return;
        }
        state.components.clear();
        state.loadings.clear();
        state.scores.clear();
        state.rowsUsed.clear();
        state.rowsExcluded.clear();
        RequestDimensionalityFitInMainR(state);
        state.modelVersion += 1;
        return;
    }
    state.rFitPending = false;
    state.lastRFitSignature.clear();
    state.components.clear();
    state.loadings.clear();
    state.scores.clear();
    state.rowsUsed.clear();
    state.rowsExcluded.clear();
    state.status = "Not fitted.";

    rlispstat::core::DimensionalityFitInput input;
    input.variables = state.variables;
    input.method = state.method;
    input.missingMode = state.missingMode;
    input.rotation = state.rotation;
    input.scope = state.scope;
    input.scale = state.scale;
    input.componentCount = state.componentCount;
    input.parallelIterations = 100;

    if (state.variables.size() >= 2) {
        std::vector<NumericVariable *> vars;
        size_t rowCount = DendrogramRowCountForVariables(&state.seed, state.variables, vars);
        if (rowCount == 0 || vars.size() != state.variables.size()) {
            state.status = "One or more variables are not available.";
            state.modelVersion += 1;
            return;
        }
        input.columns.reserve(vars.size());
        for (NumericVariable *var : vars) {
            input.columns.push_back(var->values);
        }
        const std::vector<int> capturedRows = RowsForCapturedAnalysisScope(
            state.dataScope, state.dataScopeCaptured);
        if (state.dataScopeCaptured &&
            state.dataScope.kind == rlispstat::core::AnalysisScopeKind::ExplicitRowIds) {
            input.scope = "selected";
            input.selectedRows = capturedRows;
        } else if (state.scope == "selected" || state.scope == "unselected") {
            std::unique_lock<std::mutex> lock(g_mutex, std::try_to_lock);
            if (lock.owns_lock()) {
                auto selectionIt = g_groupSelections.find(state.group);
                if (selectionIt != g_groupSelections.end()) {
                    input.selectedRows.assign(selectionIt->second.begin(), selectionIt->second.end());
                }
            }
        }
    }

    rlispstat::core::DimensionalityFitResult result = rlispstat::core::FitDimensionality(input);
    state.method = result.method;
    state.missingMode = result.missingMode;
    state.rotation = result.rotation;
    state.scope = result.scope;
    state.scale = result.scale;
    state.componentCount = result.componentCount;
    state.rowsUsed = result.rowsUsed;
    state.rowsExcluded = result.rowsExcluded;
    state.components = result.components;
    state.loadings = result.loadings;
    state.scores = result.scores;
    state.status = result.status;
    if (state.focusedComponent > state.componentCount ||
        state.focusedComponent > (int)state.components.size()) {
        state.focusedComponent = 0;
    }
    if (!state.focusedVariable.empty() &&
        std::find(state.variables.begin(), state.variables.end(), state.focusedVariable) == state.variables.end()) {
        state.focusedVariable.clear();
    }
    state.modelVersion += 1;
}

static bool RefreshDimensionalityBiplotPlot(PlotModel *plot)
{
    if (!plot || plot->kind != "pca_biplot") return false;
    auto it = g_dimensionalityModels.find(plot->dimensionalityModelId);
    if (it == g_dimensionalityModels.end()) return false;
    DimensionalityState &state = it->second;
    DimensionalityBiplotPlotState biplot = BuildDimensionalityBiplotPlotState(
        state.components,
        state.loadings,
        state.scores,
        state.method,
        plot->biplotXComponent,
        plot->biplotYComponent
    );
    if (!biplot.ok) return false;
    plot->biplotXComponent = biplot.xComponent;
    plot->biplotYComponent = biplot.yComponent;
    plot->title = biplot.title;
    plot->xLabel = biplot.xLabel;
    plot->yLabel = biplot.yLabel;
    plot->points.clear();
    plot->biplotLoadings.clear();
    plot->points.reserve(biplot.scores.size());
    for (const DimensionalityBiplotScorePoint &point : biplot.scores) {
        plot->points.push_back(DataPoint{point.x, point.y, point.rowId});
    }
    plot->biplotLoadings.reserve(biplot.loadings.size());
    for (const DimensionalityBiplotLoadingVector &loading : biplot.loadings) {
        BiplotLoading b;
        b.variable = loading.variable;
        b.x = loading.x;
        b.y = loading.y;
        plot->biplotLoadings.push_back(b);
    }
    plot->dataXmin = biplot.dataXmin;
    plot->dataXmax = biplot.dataXmax;
    plot->dataYmin = biplot.dataYmin;
    plot->dataYmax = biplot.dataYmax;
    plot->xmin = biplot.xmin;
    plot->xmax = biplot.xmax;
    plot->ymin = biplot.ymin;
    plot->ymax = biplot.ymax;
    return true;
}

static bool RefreshDimensionalityScreePlot(PlotModel *plot)
{
    if (!plot || plot->kind != "pca_scree") return false;
    auto it = g_dimensionalityModels.find(plot->dimensionalityModelId);
    if (it == g_dimensionalityModels.end()) return false;
    const DimensionalityState &state = it->second;
    DimensionalityScreePlotState scree = BuildDimensionalityScreePlotState(
        state.components,
        state.method,
        state.componentCount,
        state.rotation
    );
    if (!scree.ok) return false;
    plot->title = scree.title;
    plot->xLabel = scree.xLabel;
    plot->yLabel = scree.yLabel;
    plot->interactionMode = "none";
    plot->labelDisplayMode = "none";
    plot->overlays.clear();
    plot->points.clear();
    plot->screeParallelPoints.clear();
    plot->points.reserve(scree.observed.size());
    for (const DimensionalityScreePoint &point : scree.observed) {
        plot->points.push_back(DataPoint{point.x, point.y, point.rowId});
    }
    plot->screeParallelPoints.reserve(scree.parallel.size());
    for (const DimensionalityScreePoint &point : scree.parallel) {
        plot->screeParallelPoints.push_back(DataPoint{point.x, point.y, point.rowId});
    }
    plot->dataXmin = scree.xmin;
    plot->dataXmax = scree.xmax;
    plot->dataYmin = scree.ymin;
    plot->dataYmax = scree.ymax;
    plot->xmin = scree.xmin;
    plot->xmax = scree.xmax;
    plot->ymin = scree.ymin;
    plot->ymax = scree.ymax;
    return true;
}

static void RefreshOpenDimensionalityPlots(const std::string &modelId)
{
    std::vector<std::string> changed;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        for (auto &entry : g_plots) {
            PlotModel *plot = entry.second;
            if (!plot || plot->dimensionalityModelId != modelId) continue;
            bool ok = false;
            if (plot->kind == "pca_biplot") {
                ok = RefreshDimensionalityBiplotPlot(plot);
            } else if (plot->kind == "pca_scree") {
                ok = RefreshDimensionalityScreePlot(plot);
            }
            if (ok) {
                changed.push_back(plot->id);
            }
        }
    }
    for (const std::string &plotId : changed) {
        UpdateWindowTitleForPlotOnMain(plotId);
        RedrawPlotOnMain(plotId);
    }
}

static void RefitDendrogramState(DendrogramState &state)
{
    state.merges.clear();
    state.leafOrder.clear();
    state.caseRows.clear();

    rlispstat::core::DendrogramFitInput input;
    input.variables = state.variables;
    input.distance = state.distance;
    input.linkage = state.linkage;
    input.missingMode = state.missingMode;
    input.includedRows = RowsForCapturedAnalysisScope(state.dataScope, state.dataScopeCaptured);
    input.restrictRows = state.dataScopeCaptured &&
        state.dataScope.kind == rlispstat::core::AnalysisScopeKind::ExplicitRowIds;

    if (!state.variables.empty()) {
        std::vector<NumericVariable *> vars;
        size_t rowCount = DendrogramRowCountForVariables(&state.seed, state.variables, vars);
        if (rowCount == 0 || vars.empty()) {
            state.modelVersion += 1;
            return;
        }
        input.columns.reserve(vars.size());
        for (NumericVariable *var : vars) {
            input.columns.push_back(var->values);
        }
    }

    rlispstat::core::DendrogramFitResult result = rlispstat::core::FitDendrogram(input);
    state.distance = result.distance;
    state.linkage = result.linkage;
    state.missingMode = result.missingMode;
    state.caseRows = result.caseRows;
    state.leafOrder = result.leafOrder;
    state.merges = result.merges;
    state.modelVersion += 1;
}

static const CorrelationCellResult *CorrelationCellAt(const CorrelationMatrixState &state, int row, int col)
{
    return rlispstat::core::CorrelationCellAt(state.cells, state.variables.size(), row, col);
}

static void OpenCorrelationScatterplot(CorrelationMatrixState &state, int row, int col)
{
    if (row == col || row < 0 || col < 0 ||
        (size_t)row >= state.variables.size() || (size_t)col >= state.variables.size()) {
        return;
    }
    const std::string xName = state.variables[(size_t)col];
    const std::string yName = state.variables[(size_t)row];
    if (!FindVariable(&state.seed, xName) || !FindVariable(&state.seed, yName)) {
        return;
    }
    PlotModel *created = new PlotModel(state.seed);
    created->kind = "scatter";
    created->isDatasetSeed = false;
    created->isGLMDiagnostic = false;
    created->id = "plot_corr_" + state.group + "_" + std::to_string((long long)time(nullptr)) + "_" + std::to_string(row + 1) + "_" + std::to_string(col + 1);
    created->xLabel = xName;
    created->yLabel = yName;
    created->title = yName + " vs " + xName;
    if (state.multipleImputation) {
        created->title += " [active imputation]";
    }
    created->points.clear();
    RebuildPointsForCurrentVariables(created);
    ComputeRanges(created);
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        (void)AttachPlotModelUnlocked(created);
        MarkActiveDatasetGroupUnlocked(created->group);
    }
    AddPlotOnMain(created);
}

static void AppendRecordingEntry(const std::string &group,
                                 const std::string &plotId,
                                 const std::string &description,
                                 const std::string &internalCommand,
                                 const std::string &rCode,
                                 bool replayable)
{
    if (g_recordingReplaying) {
        return;
    }
    std::lock_guard<std::mutex> lock(g_recordingMutex);
    if (!g_recordingActive) {
        return;
    }
    RecordingEntry entry;
    entry.timestamp = std::time(nullptr);
    entry.group = group;
    entry.plotId = plotId;
    entry.description = description;
    entry.internalCommand = internalCommand;
    entry.rCode = rCode;
    entry.replayable = replayable;
    g_recordingEntries.push_back(entry);
}

static void RecordAPICommand(const std::vector<std::string> &lines,
                             const std::string &description,
                             const std::string &rCode,
                             bool replayable)
{
    if (lines.empty() || g_recordingReplaying) {
        return;
    }
    std::string group = lines.size() >= 2 ? lines[1] : "";
    AppendRecordingEntry(group, "",
                         description.empty() ? RecordingDescriptionForAPI(lines) : description,
                         RecordingInternalAPICommand(lines),
                         rCode.empty() ? RecordingDefaultRCodeForAPI(lines) : rCode,
                         replayable);
}

static void RecordDispatchCommand(PlotModel *model, const std::string &command)
{
    if (!RecordingDispatchCommandShouldRecord(command) || g_recordingReplaying) {
        return;
    }
    std::string group;
    std::string plotId;
    if (model) {
        group = model->group;
        plotId = model->id;
    } else {
        std::lock_guard<std::mutex> lock(g_mutex);
        group = ActiveDatasetGroupUnlocked();
    }
    AppendRecordingEntry(group, plotId,
                         RecordingDescriptionForDispatch(command, group),
                         RecordingInternalDispatchCommand(plotId, command),
                         RecordingRCodeForDispatch(command, group, plotId),
                         RecordingDispatchCommandReplayable(command));
}

static std::vector<RecordingEntry> RecordingSnapshot()
{
    std::lock_guard<std::mutex> lock(g_recordingMutex);
    return g_recordingEntries;
}

static std::string RenderRecordingReport()
{
    bool active = false;
    std::vector<RecordingEntry> entries;
    {
        std::lock_guard<std::mutex> lock(g_recordingMutex);
        active = g_recordingActive;
        entries = g_recordingEntries;
    }
    return rlispstat::core::RenderRecordingReport(entries, active);
}

static void ShowRecordingOnMain()
{
    std::string group;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        group = ActiveDatasetGroupUnlocked();
    }
    ShowTextReportOnMain("rlispstat_recording", group, RecordingReportTitle(), RenderRecordingReport());
}

static void CopyTextToPasteboardOnMain(NSString *text)
{
    NSPasteboard *pasteboard = [NSPasteboard generalPasteboard];
    [pasteboard clearContents];
    [pasteboard setString:text forType:NSPasteboardTypeString];
}

static void SaveRecordingRScriptOnMain()
{
    std::string script = rlispstat::core::RenderRecordingRScript(RecordingSnapshot());
    dispatch_async(dispatch_get_main_queue(), ^{
      NSSavePanel *panel = [NSSavePanel savePanel];
      [panel setTitle:ToNSString(RecordingSavePanelTitle())];
      [panel setNameFieldStringValue:ToNSString(RecordingSaveDefaultFilename())];
      [panel setAllowedFileTypes:@[ToNSString(rlispstat::core::RFileExtension())]];
      if ([panel runModal] != NSModalResponseOK) return;
      NSError *error = nil;
      BOOL ok = [ToNSString(script) writeToURL:[panel URL]
                                    atomically:YES
                                      encoding:NSUTF8StringEncoding
                                         error:&error];
      if (!ok) {
          ShowWorkbenchMessageOnMain(ToNSString(RecordingMessageTitle()),
                                     error ? [error localizedDescription] : ToNSString(RecordingSaveFailedStatus()));
      }
    });
}

static void ReplayRecordingOnMain()
{
    std::vector<RecordingEntry> entries = RecordingSnapshot();
    int replayed = 0;
    g_recordingReplaying = true;
    for (const RecordingEntry &entry : entries) {
        if (!entry.replayable) {
            continue;
        }
        std::vector<std::string> parts = SplitTabs(entry.internalCommand);
        if (parts.empty()) {
            continue;
        }
        if (parts[0] == "API") {
            std::vector<std::string> lines = DecodeRecordingAPICommand(entry.internalCommand);
            if (!lines.empty()) {
                HandleCommandLines(lines);
                ++replayed;
            }
        } else if (parts[0] == "DISPATCH" && parts.size() >= 3) {
            std::string plotId = DecodeCommandField(parts[1]);
            std::string command = DecodeCommandField(parts[2]);
            PlotModel *target = nullptr;
            {
                std::lock_guard<std::mutex> lock(g_mutex);
                auto it = g_plots.find(plotId);
                if (it != g_plots.end()) {
                    target = it->second;
                } else if (!entry.group.empty()) {
                    target = EnsureDatasetSeedPlotUnlocked(entry.group);
                } else {
                    target = ActiveDatasetSeedPlotUnlocked();
                }
            }
            DispatchCommand(target, command);
            ++replayed;
        }
    }
    g_recordingReplaying = false;
    ShowWorkbenchMessageOnMain(ToNSString(RecordingMessageTitle()), ToNSString(RecordingReplayedStatus(replayed)));
}

static bool HandleRecordingCommand(const std::string &command)
{
    if (command.rfind("RECORD_", 0) != 0) {
        return false;
    }
    if (command == "RECORD_START") {
        {
            std::lock_guard<std::mutex> lock(g_recordingMutex);
            g_recordingActive = true;
        }
        ShowWorkbenchMessageOnMain(ToNSString(RecordingMessageTitle()), ToNSString(RecordingStartedStatus()));
        return true;
    }
    if (command == "RECORD_STOP") {
        {
            std::lock_guard<std::mutex> lock(g_recordingMutex);
            g_recordingActive = false;
        }
        ShowWorkbenchMessageOnMain(ToNSString(RecordingMessageTitle()), ToNSString(RecordingStoppedStatus()));
        return true;
    }
    if (command == "RECORD_CLEAR") {
        {
            std::lock_guard<std::mutex> lock(g_recordingMutex);
            g_recordingEntries.clear();
        }
        ShowWorkbenchMessageOnMain(ToNSString(RecordingMessageTitle()), ToNSString(RecordingClearedStatus()));
        return true;
    }
    if (command == "RECORD_SHOW") {
        ShowRecordingOnMain();
        return true;
    }
    if (command == "RECORD_COPY_R") {
        CopyTextToPasteboardOnMain(ToNSString(rlispstat::core::RenderRecordingRScript(RecordingSnapshot())));
        ShowWorkbenchMessageOnMain(ToNSString(RecordingMessageTitle()), ToNSString(RecordingRScriptCopiedStatus()));
        return true;
    }
    if (command == "RECORD_COPY_INTERNAL") {
        CopyTextToPasteboardOnMain(ToNSString(rlispstat::core::RenderRecordingInternalCommands(RecordingSnapshot())));
        ShowWorkbenchMessageOnMain(ToNSString(RecordingMessageTitle()), ToNSString(RecordingInternalCommandsCopiedStatus()));
        return true;
    }
    if (command == "RECORD_SAVE_R") {
        SaveRecordingRScriptOnMain();
        return true;
    }
    if (command == "RECORD_REPLAY") {
        ReplayRecordingOnMain();
        return true;
    }
    return true;
}

using rlispstat::core::TempPath;

static bool WriteDataFrameCSV(const std::string &group, const std::string &path,
                              const std::vector<int> &includeRows, std::string *message)
{
    const DataFrameModel *found = FindDataFrameUnlockedConst(group);
    if (!found) {
        if (message) *message = rlispstat::core::NoRegisteredDatasetGroupStatus();
        return false;
    }
    const DataFrameModel &df = *found;
    std::ofstream out(path);
    if (!out) {
        if (message) *message = rlispstat::core::DatasetTemporaryDataWriteFailedStatus();
        return false;
    }
    return rlispstat::core::WriteDataFrameCSV(out, df, includeRows);
}

// The native window owns only the short-lived Rscript transport.  R performs
// the GLS/emmeans calculation and the portable core validates and parses its
// tabular reply.
static bool RunRBackedGLMPairwiseComparisons(const DataFrameModel &dataframe,
                                             PlotModel *model,
                                             const std::string &dependent,
                                             const std::vector<std::string> &terms,
                                             const std::map<std::string, std::string> &termTypes,
                                             const GLMFitSummary &fit,
                                             const rlispstat::core::GLMPairwiseComparisonRequest &request,
                                             rlispstat::core::GLMPairwiseComparisonResult *result,
                                             std::string *message)
{
    if (!model || !result) {
        if (message) *message = "The current model is unavailable.";
        return false;
    }
    const std::string csvPath = TempPath("rlispstat_glm_pairwise_data", ".csv");
    const std::string scriptPath = TempPath("rlispstat_glm_pairwise", ".R");
    {
        std::ofstream csv(csvPath);
        if (!csv || !rlispstat::core::WriteDataFrameCSV(csv, dataframe, fit.rowsUsed)) {
            if (message) *message = "Could not write the current fitted data for R.";
            unlink(csvPath.c_str());
            return false;
        }
    }
    {
        std::ofstream script(scriptPath);
        script << rlispstat::core::GLMPairwiseComparisonsRScript();
        if (!script) {
            if (message) *message = "Could not write the R script for pairwise comparisons.";
            unlink(csvPath.c_str());
            unlink(scriptPath.c_str());
            return false;
        }
    }
    const std::vector<std::string> variables = BaseVariablesFromModelTerms(model, dependent, terms);
    std::string command = ShellQuoteSingle(g_rscriptPath) + " --vanilla " +
        ShellQuoteSingle(scriptPath) + " " + ShellQuoteSingle(csvPath) + " " +
        ShellQuoteSingle(dependent) + " " + ShellQuoteSingle(request.term) + " " +
        ShellQuoteSingle(std::to_string(request.confidenceLevel)) + " " +
        ShellQuoteSingle(std::to_string(static_cast<long long>(terms.size())));
    for (const std::string &term : terms) command += " " + ShellQuoteSingle(term);
    command += " " + ShellQuoteSingle(std::to_string(static_cast<long long>(variables.size())));
    for (const std::string &variable : variables) command += " " + ShellQuoteSingle(variable);
    for (const std::string &variable : variables) {
        command += " " + ShellQuoteSingle(rlispstat::core::ModelTermDisplayType(model, variable, termTypes));
    }
    command += " " + ShellQuoteSingle(request.adjustment.empty() ? "auto" : request.adjustment);
    command += " 2>&1";
    FILE *pipe = popen(command.c_str(), "r");
    if (!pipe) {
        if (message) *message = "Could not run Rscript for pairwise comparisons.";
        unlink(csvPath.c_str());
        unlink(scriptPath.c_str());
        return false;
    }
    std::string output;
    char buffer[4096];
    while (fgets(buffer, sizeof(buffer), pipe)) output += buffer;
    const int rc = pclose(pipe);
    unlink(csvPath.c_str());
    unlink(scriptPath.c_str());
    const std::vector<std::string> lines = SplitLines(output);
    if (rc != 0 || !rlispstat::core::ParseGLMPairwiseComparisonsRResult(lines, *result)) {
        if (message) *message = output.empty() ? "R could not calculate pairwise comparisons." : output;
        return false;
    }
    return true;
}

static bool RunRBackedBinaryPairwiseComparisons(const DataFrameModel &dataframe,
                                                const GeneralizedGLMState &state,
                                                const std::string &term,
                                                rlispstat::core::GLMPairwiseComparisonResult *result,
                                                std::string *message)
{
    if (!result) return false;
    const std::string csvPath = TempPath("rlispstat_binary_pairwise_data", ".csv");
    const std::string scriptPath = TempPath("rlispstat_binary_pairwise", ".R");
    {
        std::ofstream csv(csvPath);
        if (!csv || !rlispstat::core::WriteDataFrameCSV(csv, dataframe, state.rowsUsed)) {
            if (message) *message = "Could not write the fitted binary-regression rows for R.";
            unlink(csvPath.c_str());
            return false;
        }
    }
    {
        std::ofstream script(scriptPath);
        script << rlispstat::core::BinaryPairwiseComparisonsRScript();
        if (!script) {
            if (message) *message = "Could not prepare the R pairwise-comparison script.";
            unlink(csvPath.c_str()); unlink(scriptPath.c_str());
            return false;
        }
    }
    const std::vector<std::string> variables = BaseVariablesFromModelTerms(
        const_cast<PlotModel *>(&state.seed), state.response, state.terms);
    std::string command = ShellQuoteSingle(g_rscriptPath) + " --vanilla " + ShellQuoteSingle(scriptPath) +
        " " + ShellQuoteSingle(csvPath) + " " + ShellQuoteSingle(state.response) +
        " " + ShellQuoteSingle(state.responseCoding.eventValue) + " " + ShellQuoteSingle(state.link) +
        " " + ShellQuoteSingle(term) + " " + ShellQuoteSingle("0.95") +
        " " + ShellQuoteSingle(std::to_string((long long)state.terms.size()));
    for (const std::string &modelTerm : state.terms) command += " " + ShellQuoteSingle(modelTerm);
    command += " " + ShellQuoteSingle(std::to_string((long long)variables.size()));
    for (const std::string &variable : variables) command += " " + ShellQuoteSingle(variable);
    for (const std::string &variable : variables) {
        command += " " + ShellQuoteSingle(rlispstat::core::ModelTermDisplayType(&state.seed, variable, state.termTypes));
    }
    command += " 2>&1";
    FILE *pipe = popen(command.c_str(), "r");
    if (!pipe) {
        if (message) *message = "Could not run Rscript for binary pairwise comparisons.";
        unlink(csvPath.c_str()); unlink(scriptPath.c_str());
        return false;
    }
    std::string output;
    char buffer[4096];
    while (fgets(buffer, sizeof(buffer), pipe)) output += buffer;
    int rc = pclose(pipe);
    unlink(csvPath.c_str()); unlink(scriptPath.c_str());
    result->term = term;
    if (rc != 0 || !rlispstat::core::ParseGLMPairwiseComparisonsRResult(SplitLines(output), *result)) {
        if (message) *message = output.empty() ? "R could not calculate binary pairwise comparisons." : output;
        return false;
    }
    return true;
}

static std::vector<int> RowsForGeneralizedScope(const GeneralizedGLMState &state)
{
    int rowCount = 0;
    const DataFrameModel *df = FindDataFrameUnlockedConst(state.group);
    if (df) rowCount = df->rows;
    const std::vector<int> capturedRows = RowsForCapturedAnalysisScope(
        state.dataScope, state.dataScopeCaptured);
    if (!capturedRows.empty() ||
        (state.dataScopeCaptured &&
         state.dataScope.kind == rlispstat::core::AnalysisScopeKind::ExplicitRowIds)) {
        return capturedRows;
    }
    std::set<int> selected;
    auto selIt = g_groupSelections.find(state.group);
    if (selIt != g_groupSelections.end()) selected = selIt->second;
    return rlispstat::core::RowsForScope(rowCount, selected, state.scope);
}

static bool RefitGeneralizedGLMState(GeneralizedGLMState &state)
{
    state.rows.clear();
    state.diagnostics.clear();
    state.rowsUsed.clear();
    state.rowsExcluded.clear();
    state.ok = false;
    if (state.response.empty()) {
        state.status = rlispstat::core::GLMChooseResponseVariableStatus();
        return false;
    }
    if (!IsValidGeneralizedFamily(state.family)) {
        state.status = rlispstat::core::GLMInvalidFamilyStatus();
        return false;
    }
    if (!IsValidGeneralizedLink(state.family, state.link)) {
        state.status = rlispstat::core::GLMInvalidLinkForFamilyStatus();
        return false;
    }

    std::string csvPath = TempPath("rlispstat_gglm_data", ".csv");
    std::string scriptPath = TempPath("rlispstat_gglm_fit", ".R");
    std::string message;
    std::vector<int> includeRows = RowsForGeneralizedScope(state);
    if (state.scope != "all" && includeRows.empty()) {
        state.status = rlispstat::core::GLMNoRowsForScopeStatus();
        return false;
    }
    if (!WriteDataFrameCSV(state.group, csvPath, includeRows, &message)) {
        state.status = message;
        return false;
    }
    {
        std::ofstream script(scriptPath);
        script << GeneralizedGLMRScript();
    }

    std::string command = ShellQuoteSingle(g_rscriptPath) + " --vanilla " + ShellQuoteSingle(scriptPath) + " " +
        ShellQuoteSingle(csvPath) + " " + ShellQuoteSingle(state.response) + " " + ShellQuoteSingle(state.family) + " " +
        ShellQuoteSingle(state.link) + " " + ShellQuoteSingle(std::to_string((long long)state.terms.size()));
    for (const std::string &term : state.terms) {
        command += " " + ShellQuoteSingle(term);
    }
    for (const std::string &term : state.terms) {
        command += " " + ShellQuoteSingle(rlispstat::core::ModelTermDisplayType(&state.seed, term, state.termTypes));
    }
    command += " 2>&1";

    FILE *pipe = popen(command.c_str(), "r");
    if (!pipe) {
        state.status = GeneralizedGLMRscriptLaunchFailedStatus();
        unlink(csvPath.c_str());
        unlink(scriptPath.c_str());
        return false;
    }
    std::string output;
    char buffer[4096];
    while (fgets(buffer, sizeof(buffer), pipe)) {
        output += buffer;
    }
    int rc = pclose(pipe);
    unlink(csvPath.c_str());
    unlink(scriptPath.c_str());
    std::vector<std::string> lines = SplitLines(output);
    if (lines.empty() || lines[0] != "OK" || rc != 0) {
        state.status = output.empty() ? rlispstat::core::GeneralizedGLMFitFailedStatus() : output;
        return false;
    }
    for (size_t i = 1; i < lines.size(); ++i) {
        std::vector<std::string> parts = SplitTabs(lines[i]);
        if (parts.empty()) continue;
        if (parts[0] == "FIT" && parts.size() >= 11) {
            state.n = std::atoi(parts[1].c_str());
            state.excluded = std::atoi(parts[2].c_str());
            state.nullDeviance = parts[3] == "NA" ? NAN : std::strtod(parts[3].c_str(), nullptr);
            state.residualDeviance = parts[4] == "NA" ? NAN : std::strtod(parts[4].c_str(), nullptr);
            state.dfResidual = std::atoi(parts[5].c_str());
            state.aic = parts[6] == "NA" ? NAN : std::strtod(parts[6].c_str(), nullptr);
            state.bic = parts[7] == "NA" ? NAN : std::strtod(parts[7].c_str(), nullptr);
            state.dispersion = parts[8] == "NA" ? NAN : std::strtod(parts[8].c_str(), nullptr);
            state.logLik = parts[9] == "NA" ? NAN : std::strtod(parts[9].c_str(), nullptr);
            state.statisticName = parts[10];
        } else if (parts[0] == "ROW" && parts.size() >= 13) {
            GeneralizedGLMRow row;
            row.rowType = parts[1];
            row.term = parts[2];
            row.displayLabel = parts[3];
            row.sourceTerm = parts[4];
            row.factorLevel = parts[5];
            row.referenceLevel = parts[6];
            row.termType = parts[7];
            row.estimate = parts[8] == "NA" ? NAN : std::strtod(parts[8].c_str(), nullptr);
            row.stdError = parts[9] == "NA" ? NAN : std::strtod(parts[9].c_str(), nullptr);
            row.statisticName = parts[10];
            row.statistic = parts[11] == "NA" ? NAN : std::strtod(parts[11].c_str(), nullptr);
            row.pValue = parts[12] == "NA" ? NAN : std::strtod(parts[12].c_str(), nullptr);
            state.rows.push_back(row);
        } else if (parts[0] == "DIAG" && parts.size() >= 9) {
            GeneralizedGLMDiagnosticRow diag;
            diag.row = std::atoi(parts[1].c_str());
            diag.observed = parts[2] == "NA" ? NAN : std::strtod(parts[2].c_str(), nullptr);
            diag.fitted = parts[3] == "NA" ? NAN : std::strtod(parts[3].c_str(), nullptr);
            diag.devianceResidual = parts[4] == "NA" ? NAN : std::strtod(parts[4].c_str(), nullptr);
            diag.pearsonResidual = parts[5] == "NA" ? NAN : std::strtod(parts[5].c_str(), nullptr);
            diag.workingResidual = parts[6] == "NA" ? NAN : std::strtod(parts[6].c_str(), nullptr);
            diag.leverage = parts[7] == "NA" ? NAN : std::strtod(parts[7].c_str(), nullptr);
            diag.cooksDistance = parts[8] == "NA" ? NAN : std::strtod(parts[8].c_str(), nullptr);
            if (diag.row > 0) {
                state.diagnostics.push_back(diag);
                state.rowsUsed.push_back(diag.row);
            }
        }
    }
    std::set<int> used(state.rowsUsed.begin(), state.rowsUsed.end());
    std::vector<int> candidateRows = includeRows;
    if (candidateRows.empty()) {
        const DataFrameModel *df = FindDataFrameUnlockedConst(state.group);
        int totalRows = df ? df->rows : state.n + state.excluded;
        for (int row = 1; row <= totalRows; ++row) candidateRows.push_back(row);
    }
    for (int row : candidateRows) {
        if (used.find(row) == used.end()) state.rowsExcluded.push_back(row);
    }
    state.ok = true;
    state.fitVersion += 1;
    state.diagnosticsVersion += 1;
    state.status = "GLM fitted on " + std::to_string(state.n) + " rows.";
    return true;
}

static void RequestGeneralizedGLMFitInMainR(GeneralizedGLMState &state)
{
    if (state.precomputed) {
        return;
    }
    if (state.response.empty()) {
        state.rFitPending = false;
        state.ok = false;
        state.status = rlispstat::core::GLMChooseResponseVariableStatus();
        return;
    }
    if (state.terms.empty() && !state.binaryRegression) {
        state.rFitPending = false;
        state.ok = false;
        state.status = rlispstat::core::GLMAddPredictorBeforeTableStatus();
        return;
    }
    std::string signature = rlispstat::core::GeneralizedGLMFitSignature(state);
    if (state.rFitPending && state.lastRFitSignature == signature) {
        return;
    }
    state.rFitPending = true;
    state.lastRFitSignature = signature;
    state.status = "Fitting generalized linear model in the main R session...";
    QueueGeneralizedGLMMainRTask(state);
}

static bool AddHierarchicalGeneralizedComparisonTerm(GeneralizedComparisonState &state,
                                                     GeneralizedComparisonModel &model,
                                                     const std::string &term)
{
    bool changed = false;
    std::string response = model.response.empty() ? state.response : model.response;
    for (const std::string &candidate : HierarchicalTermsForModelTerm(&state.seed, response, term)) {
        rlispstat::core::AddGeneralizedComparisonTermRow(state, candidate);
        if (!rlispstat::core::GeneralizedModelIncludesTerm(model, candidate)) {
            model.includedTerms.push_back(candidate);
            changed = true;
        }
    }
    return changed;
}

static void ApplyGeneralizedComparisonTermTypes(GeneralizedComparisonState &state, GeneralizedGLMState &fit)
{
    for (const std::string &term : fit.terms) {
         std::string type = rlispstat::core::ModelTermDisplayType(&state.seed, term, state.termTypes);
         rlispstat::core::SetVariableMetaType(fit.seed.variableMeta, term, type);
    }
}

static std::vector<int> GeneralizedComparisonCommonRows(const GeneralizedComparisonState &state)
{
    const DataFrameModel *dataframe = FindDataFrameUnlockedConst(state.group);
    if (!dataframe) return {};
    std::set<int> selected;
    const std::vector<int> capturedRows = RowsForCapturedAnalysisScope(
        state.dataScope, state.dataScopeCaptured);
    if (state.dataScopeCaptured &&
        state.dataScope.kind == rlispstat::core::AnalysisScopeKind::ExplicitRowIds) {
        selected.insert(capturedRows.begin(), capturedRows.end());
    } else {
        auto selection = g_groupSelections.find(state.group);
        if (selection != g_groupSelections.end()) selected = selection->second;
    }
    std::vector<int> candidates = rlispstat::core::RowsForScope(dataframe->rows, selected, state.scope);
    // RowsForScope deliberately represents "all" with an empty vector because
    // most CSV writers interpret an empty filter as every row.  Here we must
    // inspect the candidates one by one to form a complete-case intersection,
    // so expand that sentinel to the actual row numbers first.
    if (state.scope == "all") {
        candidates.reserve(static_cast<std::size_t>(std::max(0, dataframe->rows)));
        for (int row = 1; row <= dataframe->rows; ++row) candidates.push_back(row);
    }
    std::vector<std::string> variables;
    if (!state.response.empty()) variables.push_back(state.response);
    for (const GeneralizedComparisonModel &model : state.models) {
        for (const std::string &variable : BaseVariablesFromModelTerms(
                 const_cast<PlotModel *>(&state.seed), state.response, model.includedTerms)) {
            if (std::find(variables.begin(), variables.end(), variable) == variables.end()) variables.push_back(variable);
        }
    }
    std::vector<int> common;
    for (int row : candidates) {
        bool complete = true;
        for (const std::string &variable : variables) {
            const DataColumn *column = FindDataColumnInDataFrame(*dataframe, variable);
            if (!column || row <= 0 || static_cast<std::size_t>(row) > column->values.size() ||
                DataCellIsMissing(column->values[static_cast<std::size_t>(row - 1)])) {
                complete = false;
                break;
            }
        }
        if (complete) common.push_back(row);
    }
    return common;
}

static bool RefitBinaryComparisonModelInR(GeneralizedComparisonState &state,
                                          GeneralizedComparisonModel &model)
{
    GeneralizedGLMState fit;
    fit.id = model.id;
    fit.group = state.group;
    fit.response = state.response;
    fit.terms = model.includedTerms;
    fit.termTypes = state.termTypes;
    fit.family = "binomial";
    fit.binaryRegression = true;
    fit.binaryLink = state.binaryLink;
    fit.link = rlispstat::core::BinaryLinkId(state.binaryLink);
    fit.responseCoding = state.responseCoding;
    fit.responseCodingExplicit = true;
    fit.scope = state.scope;
    fit.dataScope = state.dataScope;
    fit.dataScopeCaptured = state.dataScopeCaptured;
    fit.seed = state.seed;
    fit.hasSeed = true;
    fit.modelVersion = model.modelVersion + 1;
    if (state.response.empty() || !state.responseCoding.ok || state.commonRows.empty()) {
        fit.status = state.response.empty() ? "Select a binary response variable before fitting the models."
                                            : "No common complete rows are available for the model comparison.";
        model.fit = fit;
        model.isStale = false;
        return false;
    }
    const std::string csvPath = TempPath("rlispstat_binary_comparison", ".csv");
    const std::string scriptPath = TempPath("rlispstat_binary_comparison", ".R");
    std::string message;
    if (!WriteDataFrameCSV(state.group, csvPath, state.commonRows, &message)) {
        fit.status = message;
        model.fit = fit;
        return false;
    }
    {
        std::ofstream script(scriptPath);
        script << R"RBINCMP(
args <- commandArgs(TRUE)
csv <- args[[1L]]; response <- args[[2L]]; link <- args[[3L]]; event <- args[[4L]]; reference <- args[[5L]]
n_terms <- as.integer(args[[6L]]); cursor <- 7L
terms <- if (n_terms > 0L) args[seq.int(cursor, cursor + n_terms - 1L)] else character(); cursor <- cursor + n_terms
types <- if (n_terms > 0L) args[seq.int(cursor, cursor + n_terms - 1L)] else character()
names(types) <- terms
dat <- utils::read.csv(csv, check.names = FALSE, stringsAsFactors = FALSE, na.strings = "NA")
model <- LinkEDA::ls_new_binary_regression(
  dat, response, terms, link = link, event = event, reference = reference,
  native = FALSE, name = "binary_comparison_fit", term_types = as.list(types)
)
record <- LinkEDA::ls_binary_regression_state(model)
writeLines(LinkEDA:::.rls_native_generalized_state_payload(record), useBytes = TRUE)
)RBINCMP";
    }
    std::string command = ShellQuoteSingle(g_rscriptPath) + " --vanilla " + ShellQuoteSingle(scriptPath) +
        " " + ShellQuoteSingle(csvPath) + " " + ShellQuoteSingle(state.response) +
        " " + ShellQuoteSingle(fit.link) + " " + ShellQuoteSingle(state.responseCoding.eventValue) +
        " " + ShellQuoteSingle(state.responseCoding.referenceValue) +
        " " + ShellQuoteSingle(std::to_string((long long)model.includedTerms.size()));
    for (const std::string &term : model.includedTerms) command += " " + ShellQuoteSingle(term);
    for (const std::string &term : model.includedTerms) {
        command += " " + ShellQuoteSingle(rlispstat::core::ModelTermDisplayType(&state.seed, term, state.termTypes));
    }
    command += " 2>&1";
    FILE *pipe = popen(command.c_str(), "r");
    std::string output;
    if (pipe) {
        char buffer[4096];
        while (fgets(buffer, sizeof(buffer), pipe)) output += buffer;
    }
    int rc = pipe ? pclose(pipe) : -1;
    unlink(csvPath.c_str());
    unlink(scriptPath.c_str());
    std::vector<std::string> lines = SplitLines(output);
    std::size_t cursor = 0;
    if (rc != 0 || !ReadGeneralizedStatePayload(lines, cursor, fit)) {
        fit.ok = false;
        fit.status = output.empty() ? "R could not fit the binary comparison model." : output;
        model.fit = fit;
        model.isStale = false;
        return false;
    }
    for (GeneralizedGLMDiagnosticRow &diagnostic : fit.diagnostics) {
        if (diagnostic.row > 0 && static_cast<std::size_t>(diagnostic.row) <= state.commonRows.size()) {
            diagnostic.row = state.commonRows[static_cast<std::size_t>(diagnostic.row - 1)];
        }
    }
    fit.rowsUsed = state.commonRows;
    fit.rowsExcluded.clear();
    fit.fitVersion = fit.modelVersion;
    fit.diagnosticsVersion = fit.fitVersion;
    fit.status = "Binary regression fitted in R on " + std::to_string(fit.n) + " common rows.";
    model.fit = fit;
    model.response = fit.response;
    model.family = fit.family;
    model.link = fit.link;
    model.fitVersion = fit.fitVersion;
    model.modelVersion = fit.modelVersion;
    model.isStale = false;
    return fit.ok;
}

static void RefitGeneralizedComparisonModel(GeneralizedComparisonState &state, GeneralizedComparisonModel &model)
{
    if (state.binaryComparison) {
        RefitBinaryComparisonModelInR(state, model);
        return;
    }
    GeneralizedGLMState fit;
    fit.id = model.id;
    fit.group = state.group;
    fit.response = model.response.empty() ? state.response : model.response;
    fit.terms = model.includedTerms;
    fit.family = model.family.empty() ? state.family : model.family;
    fit.link = model.link.empty() ? DefaultGeneralizedLink(fit.family) : model.link;
    if (!IsValidGeneralizedLink(fit.family, fit.link)) {
        fit.link = DefaultGeneralizedLink(fit.family);
    }
    fit.scope = state.scope;
    fit.dataScope = state.dataScope;
    fit.dataScopeCaptured = state.dataScopeCaptured;
    fit.seed = state.seed;
    fit.hasSeed = true;
    fit.modelVersion = model.modelVersion + 1;
    ApplyGeneralizedComparisonTermTypes(state, fit);
    RefitGeneralizedGLMState(fit);
    model.fit = fit;
    model.response = fit.response;
    model.family = fit.family;
    model.link = fit.link;
    model.fitVersion = fit.fitVersion;
    model.modelVersion = fit.modelVersion;
    model.isStale = false;
}

static void RefitGeneralizedComparisonModels(GeneralizedComparisonState &state, bool forceAll = false)
{
    if (state.binaryComparison) state.commonRows = GeneralizedComparisonCommonRows(state);
    bool refittedAnyModel = false;
    for (GeneralizedComparisonModel &model : state.models) {
        if (forceAll || model.isStale || model.fitVersion == 0) {
            RefitGeneralizedComparisonModel(state, model);
            refittedAnyModel = true;
        }
    }
    if (state.binaryComparison && refittedAnyModel) {
        for (std::size_t index = 1; index < state.models.size(); ++index) {
            GeneralizedComparisonModel &current = state.models[index];
            current.comparisonOk = false;
            current.comparisonCalculatedInR = false;
            CalculateBinaryLikelihoodRatioInR(state.models[index - 1].fit, current.fit, current);
        }
    }
    RefreshGeneralizedTermRowsFromFits(state);
}

static bool FindGeneralizedComparisonModelById(const std::string &modelId,
                                               GeneralizedComparisonState **stateOut = nullptr,
                                               GeneralizedComparisonModel **modelOut = nullptr)
{
    for (auto &entry : g_generalizedComparisons) {
        GeneralizedComparisonState &state = entry.second;
        for (GeneralizedComparisonModel &model : state.models) {
            if (model.id == modelId) {
                if (stateOut) *stateOut = &state;
                if (modelOut) *modelOut = &model;
                return true;
            }
        }
    }
    return false;
}


static bool AddHierarchicalRegressionComparisonTerm(RegressionComparisonState &state,
                                                     RegressionComparisonModel &model,
                                                     const std::string &term)
{
    bool changed = false;
    std::string response = model.response.empty() ? state.response : model.response;
    for (const std::string &candidate : HierarchicalTermsForModelTerm(&state.seed, response, term)) {
        rlispstat::core::AddRegressionTermRow(state, candidate);
        if (!rlispstat::core::ModelIncludesTerm(model, candidate)) {
            model.includedTerms.push_back(candidate);
            changed = true;
        }
    }
    return changed;
}

static void RequestRegressionComparisonFitInMainR(RegressionComparisonState &state)
{
    std::string signature = rlispstat::core::RegressionComparisonFitSignature(state);
    if (state.rFitPending && state.lastRFitSignature == signature) {
        return;
    }
    state.rFitPending = true;
    state.lastRFitSignature = signature;
    MainRRegressionComparisonTask task;
    task.id = state.id;
    task.group = state.group;
    task.response = state.response;
    task.scope = state.scope == "compare_selected_all" ? "all" : state.scope;
    task.autoRefit = state.autoRefit;
    task.termRows = state.termRows;
    task.termTypes = state.termTypes;
    task.rows = RowsForCapturedAnalysisScope(state.dataScope, state.dataScopeCaptured);
    task.models.reserve(state.models.size());
    for (const RegressionComparisonModel &model : state.models) {
        task.models.push_back({
            model.id,
            model.label,
            model.response.empty() ? state.response : model.response,
            model.includedTerms
        });
    }
    QueueRegressionComparisonMainRTask(task);
}


static void RefitRegressionComparisonModel(RegressionComparisonState &state, RegressionComparisonModel &model)
{
    if (state.precomputed) {
        model.isStale = false;
        return;
    }
    model.isStale = true;
    std::string response = model.response.empty() ? state.response : model.response;
    std::string fitScope = state.scope == "compare_selected_all" ? "all" : state.scope;
    GLMFitSummary provisional = FitMultipleLinearModelPortableMac(&state.seed, response, model.includedTerms,
                                                                  state.termTypes, fitScope);
    if (provisional.ok) {
        rlispstat::core::PopulateMissingStandardizedBetas(provisional, state.seed, response);
        model.fit = provisional;
        model.response = response;
        model.fitVersion += 1;
        RefreshRegressionTermRowsFromFits(state);
        rlispstat::core::PruneRegressionComparisonRowsForCurrentTypes(state);
    }
    RequestRegressionComparisonFitInMainR(state);
}


static void RefitRegressionComparisonModels(RegressionComparisonState &state, bool forceAll = false)
{
    if (state.precomputed) {
        RefreshRegressionTermRowsFromFits(state);
        rlispstat::core::PruneRegressionComparisonRowsForCurrentTypes(state);
        return;
    }
    bool needsRefit = forceAll;
    for (RegressionComparisonModel &model : state.models) {
        if (forceAll) {
            model.isStale = true;
        }
        if (model.isStale || model.fitVersion == 0) {
            needsRefit = true;
        }
    }
    if (needsRefit) {
        RequestRegressionComparisonFitInMainR(state);
    } else {
        RefreshRegressionTermRowsFromFits(state);
        rlispstat::core::PruneRegressionComparisonRowsForCurrentTypes(state);
    }
}

static void EnsureRegressionComparisonFactorLevelRowsLegacy(RegressionComparisonState &state,
                                                            const std::string &term)
{
    const NumericVariable *variable = FindNumericVariable(state.seed, term);
    if (!variable) {
        return;
    }
    std::vector<double> numericLevels;
    for (double value : variable->values) {
        if (!std::isfinite(value)) continue;
        bool seen = false;
        for (double existing : numericLevels) {
            if (std::fabs(existing - value) <= 1.0e-9) {
                seen = true;
                break;
            }
        }
        if (!seen) numericLevels.push_back(value);
    }
    std::sort(numericLevels.begin(), numericLevels.end());
    if (numericLevels.empty()) {
        return;
    }
    std::vector<std::string> rebuilt;
    for (const std::string &row : state.termRows) {
        if (row == term || rlispstat::core::ModelTermBaseForDisplayRow(row) != term || row.find('=') == std::string::npos) {
            if (std::find(rebuilt.begin(), rebuilt.end(), row) == rebuilt.end()) rebuilt.push_back(row);
        }
        if (row == term) {
            for (double level : numericLevels) {
                std::string levelText = rlispstat::core::FactorLevelTermValue(level);
                if (levelText.empty()) continue;
                std::string levelTerm = term + "=" + levelText;
                if (std::find(rebuilt.begin(), rebuilt.end(), levelTerm) == rebuilt.end()) {
                    rebuilt.push_back(levelTerm);
                }
            }
        }
    }
    state.termRows = rebuilt;
}

static bool ApplyRegressionComparisonTermTypeLegacy(RegressionComparisonState &state,
                                                    const std::string &term,
                                                    const std::string &type)
{
    state.termTypes[term] = type;
    if (type == "factor") {
        EnsureRegressionComparisonFactorLevelRowsLegacy(state, term);
    }

    std::string fitScope = state.scope == "compare_selected_all" ? "all" : state.scope;
    bool affected = false;
    bool provisionalOk = false;
    for (RegressionComparisonModel &model : state.models) {
        if (!rlispstat::core::ModelIncludesTerm(model, term)) {
            continue;
        }
        affected = true;
        std::string response = model.response.empty() ? state.response : model.response;
        GLMFitSummary candidate = FitMultipleLinearModelPortableMac(&state.seed, response, model.includedTerms,
                                                                    state.termTypes, fitScope);
        if (candidate.ok) {
            rlispstat::core::PopulateMissingStandardizedBetas(candidate, state.seed, response);
            model.fit = candidate;
            model.fitVersion += 1;
            provisionalOk = true;
        }
        model.modelVersion += 1;
        model.isStale = true;
    }

    if (provisionalOk) {
        RefreshRegressionTermRowsFromFits(state);
    }
    if (type == "factor") {
        EnsureRegressionComparisonFactorLevelRowsLegacy(state, term);
    }
    rlispstat::core::PruneRegressionComparisonRowsForCurrentTypes(state);
    if (affected && state.autoRefit) {
        RequestRegressionComparisonFitInMainR(state);
    }
    return affected;
}

using rlispstat::core::PopulateMissingStandardizedBetas;
using rlispstat::core::DefaultGeneralizedFamilyForResponse;
using rlispstat::core::RenameVariableInTermList;

using rlispstat::core::RegressionAdjacentModelTest;
using rlispstat::core::GeneralizedAdjacentModelTest;

static bool FindRegressionComparisonModelById(const std::string &modelId,
                                              RegressionComparisonState **stateOut = nullptr,
                                              RegressionComparisonModel **modelOut = nullptr)
{
    for (auto &entry : g_regressionComparisons) {
        RegressionComparisonState &state = entry.second;
        for (RegressionComparisonModel &model : state.models) {
            if (model.id == modelId) {
                if (stateOut) *stateOut = &state;
                if (modelOut) *modelOut = &model;
                return true;
            }
        }
    }
    return false;
}

static void PopulateDiagnosticPlotFromFit(PlotModel *diag, const GLMFitSummary &fit,
                                          int fitVersion, int diagnosticsVersion)
{
    rlispstat::core::DiagnosticPlotData data =
        rlispstat::core::BuildLinearDiagnosticPlotData(diag->glmDiagnosticKind,
                                                       fit.diagnostics,
                                                       fitVersion,
                                                       diagnosticsVersion);
    diag->kind = data.kind;
    diag->title = data.title;
    diag->xLabel = data.xLabel;
    diag->yLabel = data.yLabel;
    diag->points.clear();
    diag->rocStepPoints.clear();
    diag->rocThresholds.clear();
    diag->points.reserve(data.points.size());
    for (const rlispstat::core::DiagnosticPlotPoint &point : data.points) {
        diag->points.push_back(DataPoint{point.x, point.y, point.row});
    }
    diag->displayedFitVersion = data.fitVersion;
    diag->displayedDiagnosticsVersion = data.diagnosticsVersion;
    ComputeRanges(diag);
}

static void RefreshRegressionComparisonDiagnosticsForModelNow(const std::string &modelId)
{
    for (const auto &entry : g_plots) {
        PlotModel *plot = entry.second;
        if (plot && plot->isGLMDiagnostic && plot->glmModelId == modelId) {
            UpdateGLMDiagnosticPlot(plot);
        }
    }
    for (ScatterView *view : g_views) {
        if (view.model && view.model->isGLMDiagnostic && view.model->glmModelId == modelId) {
            [view setNeedsDisplay:YES];
            [view displayIfNeeded];
        }
    }
}

static bool PopulateGeneralizedDiagnosticPlot(PlotModel *diag, GeneralizedGLMState &state, std::string *message = nullptr)
{
    if (!diag || !state.ok || state.diagnostics.empty()) {
        if (message) *message = rlispstat::core::GLMNoDiagnosticRowsStatus();
        return false;
    }
    rlispstat::core::DiagnosticPlotData data =
        rlispstat::core::BuildGeneralizedDiagnosticPlotData(diag->glmDiagnosticKind,
                                                            state.residualType,
                                                            state.diagnostics,
                                                            state.fitVersion,
                                                            state.diagnosticsVersion);
    if (!data.ok) {
        if (message) *message = data.message;
        return false;
    }
    diag->glmDiagnosticKind = data.diagnosticKind;
    diag->points.clear();
    diag->histogramPoints.clear();
    diag->histogramBins.clear();
    diag->histogramShowCounts = true;
    diag->histogramShowDensity = false;
    diag->kind = data.kind;
    diag->title = data.title;
    diag->xLabel = data.xLabel;
    diag->yLabel = data.yLabel;

    if (data.kind == "histogram") {
        diag->histogramPoints.reserve(data.points.size());
        for (const rlispstat::core::DiagnosticPlotPoint &point : data.points) {
            diag->histogramPoints.push_back(HistogramPoint{point.x, point.row, 0});
        }
        RebinHistogramByRule(diag, "sturges");
    } else {
        diag->points.reserve(data.points.size());
        for (const rlispstat::core::DiagnosticPlotPoint &point : data.points) {
            diag->points.push_back(DataPoint{point.x, point.y, point.row});
        }
        if (data.diagnosticKind == "roc_curve") {
            diag->rocStepPoints.reserve(data.visualPoints.size());
            for (const rlispstat::core::DiagnosticPlotPoint &point : data.visualPoints) {
                diag->rocStepPoints.push_back(DataPoint{point.x, point.y, 0});
            }
            diag->rocThresholds.reserve(data.rocThresholds.size());
            for (const rlispstat::core::DiagnosticROCThreshold &threshold : data.rocThresholds) {
                rlispstat::core::ROCThresholdLink link;
                link.point = DataPoint{threshold.falsePositiveRate, threshold.truePositiveRate, 0};
                link.threshold = threshold.threshold;
                link.truePositive = threshold.truePositive;
                link.falsePositive = threshold.falsePositive;
                link.trueNegative = threshold.trueNegative;
                link.falseNegative = threshold.falseNegative;
                link.crossingRows = threshold.crossingRows;
                link.falsePositiveRows = threshold.falsePositiveRows;
                link.falseNegativeRows = threshold.falseNegativeRows;
                diag->rocThresholds.push_back(std::move(link));
            }
        }
    }
    ComputeRanges(diag);
    diag->displayedFitVersion = data.fitVersion;
    diag->displayedDiagnosticsVersion = data.diagnosticsVersion;
    return true;
}

using GLMNumericSummary = rlispstat::core::NumericSummary;

using GLMPostEstimate = rlispstat::core::LinearFunctionEstimate;
using GLMInteractionReport = rlispstat::core::GLMInteractionReport;

using rlispstat::core::GLMRowIncluded;
using rlispstat::core::GLMLevelIndex;
using rlispstat::core::GLMRowsUsedSet;

static GLMNumericSummary GLMNumericSummaryForVariable(PlotModel *model, const std::string &variable,
                                                       const GLMFitSummary &fit)
{
    if (!model) return rlispstat::core::SummarizeFiniteValues({});
    return rlispstat::core::GLMNumericSummaryForVariable(
        FindDataColumnForModel(model, variable),
        model->variables,
        variable,
        GLMRowsUsedSet(fit));
}

static std::vector<std::string> GLMFactorLevelsForVariable(PlotModel *model, const std::string &variable,
                                                           const GLMFitSummary &fit)
{
    std::vector<std::string> levels;
    std::set<std::string> seen;
    if (!model) return levels;
    const std::set<int> rows = GLMRowsUsedSet(fit);
    if (const DataColumn *col = FindDataColumnForModel(model, variable)) {
        for (size_t i = 0; i < col->values.size(); ++i) {
            if (!GLMRowIncluded(rows, (int)i + 1)) continue;
            const std::string &value = col->values[i];
            if (DataCellIsMissing(value)) continue;
            if (seen.insert(value).second) levels.push_back(value);
        }
    } else if (NumericVariable *var = FindVariable(model, variable)) {
        for (size_t i = 0; i < var->values.size(); ++i) {
            if (!GLMRowIncluded(rows, (int)i + 1)) continue;
            double value = var->values[i];
            if (!std::isfinite(value)) continue;
            std::string label = FormatFactorLabel(value);
            if (seen.insert(label).second) levels.push_back(label);
        }
    }
    return levels;
}

static rlispstat::core::ScenarioDesignInput GLMScenarioDesignInputForModel(
    PlotModel *model,
    const std::vector<std::string> &terms,
    const std::map<std::string, std::string> &termTypes,
    const GLMFitSummary &fit,
    const std::map<std::string, double> &numericValues,
    const std::map<std::string, std::string> &factorValues)
{
    rlispstat::core::ScenarioDesignInput input;
    input.terms = terms;
    input.termTypes = termTypes;
    input.numericValues = numericValues;
    input.factorValues = factorValues;
    input.expectedSize = fit.beta.size();
    for (const std::string &variable : BaseVariablesFromModelTerms(model, "", terms)) {
        rlispstat::core::ScenarioVariableInfo info;
        info.type = rlispstat::core::GLMBaseVariableType(model, variable, termTypes);
        if (info.type == "factor") {
            info.factorLevels = GLMFactorLevelsForVariable(model, variable, fit);
        } else {
            GLMNumericSummary summary = GLMNumericSummaryForVariable(model, variable, fit);
            info.numericDefault = summary.ok ? summary.mean : 0.0;
        }
        input.variables[variable] = info;
    }
    return input;
}

static bool GLMScenarioAt(PlotModel *model,
                          const std::vector<std::string> &terms,
                          const std::map<std::string, std::string> &termTypes,
                          const GLMFitSummary &fit,
                          std::map<std::string, double> numericValues,
                          std::map<std::string, std::string> factorValues,
                          std::vector<double> &out)
{
    rlispstat::core::ScenarioDesignInput input = GLMScenarioDesignInputForModel(
        model, terms, termTypes, fit, numericValues, factorValues);
    return rlispstat::core::BuildScenarioDesignVector(input, out);
}

static GLMPostEstimate GLMEstimateLinearFunction(const GLMFitSummary &fit,
                                                 const std::vector<double> &contrast,
                                                 const std::string &label,
                                                 double confidenceLevel)
{
    return rlispstat::core::EstimateLinearFunction(fit.beta, fit.covariance, contrast, label, confidenceLevel);
}

static GLMPostEstimate GLMPredictionEstimate(PlotModel *model,
                                             const std::vector<std::string> &terms,
                                             const std::map<std::string, std::string> &termTypes,
                                             const GLMFitSummary &fit,
                                             const std::map<std::string, double> &numericValues,
                                             const std::map<std::string, std::string> &factorValues,
                                             const std::string &label,
                                             double confidenceLevel)
{
    std::vector<double> design;
    if (!GLMScenarioAt(model, terms, termTypes, fit, numericValues, factorValues, design)) {
        GLMPostEstimate missing;
        missing.label = label;
        return missing;
    }
    return GLMEstimateLinearFunction(fit, design, label, confidenceLevel);
}

static bool GLMDifferenceContrast(PlotModel *model,
                                  const std::vector<std::string> &terms,
                                  const std::map<std::string, std::string> &termTypes,
                                  const GLMFitSummary &fit,
                                  const std::map<std::string, double> &numericA,
                                  const std::map<std::string, std::string> &factorA,
                                  const std::map<std::string, double> &numericB,
                                  const std::map<std::string, std::string> &factorB,
                                  std::vector<double> &contrast)
{
    std::vector<double> a;
    std::vector<double> b;
    if (!GLMScenarioAt(model, terms, termTypes, fit, numericA, factorA, a)) return false;
    if (!GLMScenarioAt(model, terms, termTypes, fit, numericB, factorB, b)) return false;
    contrast = SubtractVectors(a, b);
    return !contrast.empty();
}

static void GLMAddContinuousByCategoricalReport(PlotModel *model,
                                                const std::vector<std::string> &terms,
                                                const std::map<std::string, std::string> &termTypes,
                                                const GLMFitSummary &fit,
                                                const std::string &x,
                                                const std::string &g,
                                                double confidenceLevel,
                                                GLMInteractionReport &report)
{
    GLMNumericSummary xSummary = GLMNumericSummaryForVariable(model, x, fit);
    std::vector<std::string> levels = GLMFactorLevelsForVariable(model, g, fit);
    if (!xSummary.ok || levels.empty()) {
        report.message = "The interaction could not be interpreted because one component has no fitted values.";
        return;
    }
    std::vector<GLMPostEstimate> slopes;
    std::vector<std::vector<double>> slopeContrasts;
    for (const std::string &level : levels) {
        std::map<std::string, double> low{{x, xSummary.mean}};
        std::map<std::string, double> high{{x, xSummary.mean + 1.0}};
        std::map<std::string, std::string> factor{{g, level}};
        std::vector<double> contrast;
        if (!GLMDifferenceContrast(model, terms, termTypes, fit, high, factor, low, factor, contrast)) continue;
        slopeContrasts.push_back(contrast);
        slopes.push_back(GLMEstimateLinearFunction(fit, contrast, "Slope of " + x + " when " + g + " = " + level, confidenceLevel));
    }
    report.sections.push_back(std::make_pair("Simple slopes", slopes));

    std::vector<GLMPostEstimate> comparisons;
    for (size_t i = 0; i < slopeContrasts.size(); ++i) {
        for (size_t j = i + 1; j < slopeContrasts.size(); ++j) {
            std::vector<double> contrast = SubtractVectors(slopeContrasts[i], slopeContrasts[j]);
            if (contrast.empty()) continue;
            comparisons.push_back(GLMEstimateLinearFunction(fit, contrast, levels[i] + " - " + levels[j] + " slope difference", confidenceLevel));
        }
    }
    ApplyHolmAdjustedPValues(comparisons);
    report.sections.push_back(std::make_pair("Pairwise slope comparisons (Holm)", comparisons));

    std::vector<GLMPostEstimate> predictions;
    std::vector<std::pair<std::string, double>> xValues;
    if (std::isfinite(xSummary.sd) && xSummary.sd > 0.0) {
        xValues.push_back(std::make_pair("M - SD", xSummary.mean - xSummary.sd));
        xValues.push_back(std::make_pair("M", xSummary.mean));
        xValues.push_back(std::make_pair("M + SD", xSummary.mean + xSummary.sd));
    } else {
        xValues.push_back(std::make_pair("M", xSummary.mean));
    }
    for (const std::string &level : levels) {
        for (const auto &xValue : xValues) {
            predictions.push_back(GLMPredictionEstimate(model, terms, termTypes, fit,
                                                        {{x, xValue.second}}, {{g, level}},
                                                        g + " = " + level + ", " + x + " = " + xValue.first,
                                                        confidenceLevel));
        }
    }
    report.sections.push_back(std::make_pair("Predicted means", predictions));
}

static void GLMAddCategoricalByCategoricalReport(PlotModel *model,
                                                 const std::vector<std::string> &terms,
                                                 const std::map<std::string, std::string> &termTypes,
                                                 const GLMFitSummary &fit,
                                                 const std::string &a,
                                                 const std::string &b,
                                                 double confidenceLevel,
                                                 GLMInteractionReport &report)
{
    std::vector<std::string> aLevels = GLMFactorLevelsForVariable(model, a, fit);
    std::vector<std::string> bLevels = GLMFactorLevelsForVariable(model, b, fit);
    if (aLevels.empty() || bLevels.empty()) {
        report.message = "The interaction could not be interpreted because one factor has no fitted levels.";
        return;
    }
    std::vector<GLMPostEstimate> predictions;
    for (const std::string &aLevel : aLevels) {
        for (const std::string &bLevel : bLevels) {
            predictions.push_back(GLMPredictionEstimate(model, terms, termTypes, fit, {}, {{a, aLevel}, {b, bLevel}},
                                                        a + " = " + aLevel + ", " + b + " = " + bLevel,
                                                        confidenceLevel));
        }
    }
    report.sections.push_back(std::make_pair("Adjusted predictions", predictions));

    std::vector<GLMPostEstimate> effectsA;
    for (const std::string &bLevel : bLevels) {
        for (size_t i = 0; i < aLevels.size(); ++i) {
            for (size_t j = i + 1; j < aLevels.size(); ++j) {
                std::vector<double> contrast;
                if (!GLMDifferenceContrast(model, terms, termTypes, fit, {}, {{a, aLevels[i]}, {b, bLevel}},
                                           {}, {{a, aLevels[j]}, {b, bLevel}}, contrast)) continue;
                effectsA.push_back(GLMEstimateLinearFunction(fit, contrast,
                                                              aLevels[i] + " - " + aLevels[j] + " within " + b + " = " + bLevel,
                                                              confidenceLevel));
            }
        }
    }
    ApplyHolmAdjustedPValues(effectsA);
    report.sections.push_back(std::make_pair("Simple effects of " + a + " (Holm)", effectsA));

    std::vector<GLMPostEstimate> effectsB;
    for (const std::string &aLevel : aLevels) {
        for (size_t i = 0; i < bLevels.size(); ++i) {
            for (size_t j = i + 1; j < bLevels.size(); ++j) {
                std::vector<double> contrast;
                if (!GLMDifferenceContrast(model, terms, termTypes, fit, {}, {{a, aLevel}, {b, bLevels[i]}},
                                           {}, {{a, aLevel}, {b, bLevels[j]}}, contrast)) continue;
                effectsB.push_back(GLMEstimateLinearFunction(fit, contrast,
                                                              bLevels[i] + " - " + bLevels[j] + " within " + a + " = " + aLevel,
                                                              confidenceLevel));
            }
        }
    }
    ApplyHolmAdjustedPValues(effectsB);
    report.sections.push_back(std::make_pair("Simple effects of " + b + " (Holm)", effectsB));
}

static void GLMAddContinuousByContinuousReport(PlotModel *model,
                                               const std::vector<std::string> &terms,
                                               const std::map<std::string, std::string> &termTypes,
                                               const GLMFitSummary &fit,
                                               const std::string &x,
                                               const std::string &z,
                                               double confidenceLevel,
                                               GLMInteractionReport &report)
{
    GLMNumericSummary xSummary = GLMNumericSummaryForVariable(model, x, fit);
    GLMNumericSummary zSummary = GLMNumericSummaryForVariable(model, z, fit);
    if (!xSummary.ok || !zSummary.ok) {
        report.message = "The interaction could not be interpreted because one component has no fitted values.";
        return;
    }
    std::vector<std::pair<std::string, double>> zValues;
    if (std::isfinite(zSummary.sd) && zSummary.sd > 0.0) {
        zValues.push_back(std::make_pair("M - SD", zSummary.mean - zSummary.sd));
        zValues.push_back(std::make_pair("M", zSummary.mean));
        zValues.push_back(std::make_pair("M + SD", zSummary.mean + zSummary.sd));
    } else {
        zValues.push_back(std::make_pair("M", zSummary.mean));
    }
    std::vector<GLMPostEstimate> slopesX;
    for (const auto &zValue : zValues) {
        std::vector<double> contrast;
        if (!GLMDifferenceContrast(model, terms, termTypes, fit,
                                   {{x, xSummary.mean + 1.0}, {z, zValue.second}}, {},
                                   {{x, xSummary.mean}, {z, zValue.second}}, {}, contrast)) continue;
        slopesX.push_back(GLMEstimateLinearFunction(fit, contrast,
                                                    "Slope of " + x + " when " + z + " = " + zValue.first,
                                                    confidenceLevel));
    }
    report.sections.push_back(std::make_pair("Conditional slopes of " + x, slopesX));

    std::vector<std::pair<std::string, double>> xValues;
    if (std::isfinite(xSummary.sd) && xSummary.sd > 0.0) {
        xValues.push_back(std::make_pair("M - SD", xSummary.mean - xSummary.sd));
        xValues.push_back(std::make_pair("M", xSummary.mean));
        xValues.push_back(std::make_pair("M + SD", xSummary.mean + xSummary.sd));
    } else {
        xValues.push_back(std::make_pair("M", xSummary.mean));
    }
    std::vector<GLMPostEstimate> slopesZ;
    for (const auto &xValue : xValues) {
        std::vector<double> contrast;
        if (!GLMDifferenceContrast(model, terms, termTypes, fit,
                                   {{x, xValue.second}, {z, zSummary.mean + 1.0}}, {},
                                   {{x, xValue.second}, {z, zSummary.mean}}, {}, contrast)) continue;
        slopesZ.push_back(GLMEstimateLinearFunction(fit, contrast,
                                                    "Slope of " + z + " when " + x + " = " + xValue.first,
                                                    confidenceLevel));
    }
    report.sections.push_back(std::make_pair("Conditional slopes of " + z, slopesZ));

    std::vector<GLMPostEstimate> predictions;
    for (const auto &xValue : xValues) {
        for (const auto &zValue : zValues) {
            predictions.push_back(GLMPredictionEstimate(model, terms, termTypes, fit,
                                                        {{x, xValue.second}, {z, zValue.second}}, {},
                                                        x + " = " + xValue.first + ", " + z + " = " + zValue.first,
                                                        confidenceLevel));
        }
    }
    report.sections.push_back(std::make_pair("Predicted means", predictions));
}

static GLMInteractionReport BuildGLMInteractionReportPortableMac(
    const PlotModel *model,
    const std::string &term,
    const std::vector<std::string> &terms,
    const std::map<std::string, std::string> &termTypes,
    const GLMFitSummary &fit)
{
    if (!model) {
        return rlispstat::core::BuildGLMInteractionReport(
            PlotModel{}, nullptr, term, terms, termTypes, fit);
    }
    DataFrameModel dataframe;
    bool hasDataframe = false;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        if (const DataFrameModel *found = FindDataFrameUnlockedConst(model->group)) {
            dataframe = *found;
            hasDataframe = true;
        }
    }
    return rlispstat::core::BuildGLMInteractionReport(
        *model, hasDataframe ? &dataframe : nullptr, term, terms, termTypes, fit);
}

@interface GLMInteractionReportView : NSView
@property(nonatomic, copy) NSString *body;
- (instancetype)initWithBody:(NSString *)body frame:(NSRect)frame;
@end

@implementation GLMInteractionReportView

- (NSString *)snapshotTabDelimitedText
{
    return _body ?: @"";
}

- (NSMenu *)menuForEvent:(NSEvent *)event
{
    (void)event;
    return SnapshotAlbumMenu(nil, @"Interaction Report");
}

- (instancetype)initWithBody:(NSString *)body frame:(NSRect)frame
{
    self = [super initWithFrame:frame];
    if (self) {
        _body = [body copy];
        [self setWantsLayer:YES];
    }
    return self;
}

- (BOOL)isFlipped
{
    return YES;
}

- (void)drawRect:(NSRect)dirtyRect
{
    (void)dirtyRect;
    [[NSColor whiteColor] setFill];
    NSRectFill([self bounds]);
    NSString *text = _body ?: @"";
    NSDictionary *attrs = @{
        NSFontAttributeName: [NSFont monospacedSystemFontOfSize:12 weight:NSFontWeightRegular],
        NSForegroundColorAttributeName: [NSColor colorWithCalibratedWhite:0.12 alpha:1.0]
    };
    __block CGFloat y = 14.0;
    [text enumerateSubstringsInRange:NSMakeRange(0, [text length])
                              options:NSStringEnumerationByLines
                           usingBlock:^(NSString *line, NSRange substringRange, NSRange enclosingRange, BOOL *stop) {
        (void)substringRange;
        (void)enclosingRange;
        (void)stop;
        [line drawAtPoint:NSMakePoint(16.0, y) withAttributes:attrs];
        y += 18.0;
    }];
}
@end

static NSTextField *InteractionReportLineLabel(NSString *text,
                                               NSRect frame,
                                               CGFloat fontSize,
                                               NSFontWeight weight,
                                               NSTextAlignment alignment)
{
    NSTextField *field = [[NSTextField alloc] initWithFrame:frame];
    [field setEditable:NO];
    [field setSelectable:YES];
    [field setBordered:NO];
    [field setBezeled:NO];
    [field setDrawsBackground:NO];
    [field setStringValue:text ?: @""];
    [field setFont:[NSFont systemFontOfSize:fontSize weight:weight]];
    [field setAlignment:alignment];
    [field setTextColor:[NSColor colorWithCalibratedWhite:0.15 alpha:1.0]];
    [field setToolTip:text ?: @""];
    [[field cell] setLineBreakMode:NSLineBreakByTruncatingTail];
    return field;
}

// Result tables must reserve space for the rendered value, especially for
// confidence intervals.  Character-count and fixed-width approximations are
// not reliable for proportional system fonts or large/negative estimates.
static CGFloat NativeResultTextWidth(NSString *text, CGFloat fontSize, NSFontWeight weight)
{
    if (!text || [text length] == 0) return 0.0;
    NSFont *font = [NSFont systemFontOfSize:fontSize weight:weight];
    const NSSize size = [text sizeWithAttributes:@{NSFontAttributeName: font}];
    return std::ceil(size.width);
}

static std::vector<CGFloat> NativeResultColumnWidths(
    NSArray<NSString *> *headers,
    NSArray<NSArray<NSString *> *> *rows,
    const std::vector<CGFloat> &minimums,
    CGFloat fontSize = 11.0,
    CGFloat horizontalPadding = 10.0)
{
    std::vector<CGFloat> widths((std::size_t)[headers count], 0.0);
    for (NSUInteger column = 0; column < [headers count]; ++column) {
        const CGFloat minimum = column < minimums.size() ? minimums[column] : 48.0;
        widths[column] = std::max(minimum,
            NativeResultTextWidth(headers[column], fontSize, NSFontWeightSemibold) + horizontalPadding);
        for (NSArray<NSString *> *row in rows) {
            if (column >= [row count]) continue;
            widths[column] = std::max(widths[column],
                NativeResultTextWidth(row[column], fontSize, NSFontWeightRegular) + horizontalPadding);
        }
    }
    return widths;
}

static CGFloat SizeNativeResultTableColumnsToContents(NSTableView *table,
                                                       CGFloat minimumDocumentWidth)
{
    if (!table) return minimumDocumentWidth;
    id<NSTableViewDataSource> source = [table dataSource];
    const NSInteger rowCount = [table numberOfRows];
    CGFloat naturalWidth = 0.0;
    for (NSTableColumn *column in [table tableColumns]) {
        CGFloat width = std::max([column width],
            NativeResultTextWidth([[column headerCell] stringValue], 12.0, NSFontWeightSemibold) + 14.0);
        if ([source respondsToSelector:@selector(tableView:objectValueForTableColumn:row:)]) {
            for (NSInteger row = 0; row < rowCount; ++row) {
                id value = [source tableView:table objectValueForTableColumn:column row:row];
                NSString *text = value ? [value description] : @"";
                width = std::max(width,
                    NativeResultTextWidth(text, 12.0, NSFontWeightRegular) + 14.0);
            }
        }
        // Long labels may scroll inside the table; numeric and interval values
        // normally remain well below this guard and are therefore never clipped.
        width = std::min(width, (CGFloat)420.0);
        [column setWidth:width];
        naturalWidth += width;
    }
    naturalWidth += std::max((CGFloat)0.0,
        (CGFloat)[[table tableColumns] count] * [table intercellSpacing].width);
    const CGFloat documentWidth = std::max(minimumDocumentWidth, naturalWidth);
    [table setFrameSize:NSMakeSize(documentWidth, NSHeight([table frame]))];
    return documentWidth;
}

static NSBox *InteractionReportRule(CGFloat x, CGFloat y, CGFloat width)
{
    NSBox *rule = [[NSBox alloc] initWithFrame:NSMakeRect(x, y, width, 1.0)];
    [rule setBoxType:NSBoxSeparator];
    return rule;
}

static NSString *SafeNSStringFromUTF8(const std::string &text)
{
    NSString *s = [[NSString alloc] initWithBytes:text.data()
                                           length:text.size()
                                         encoding:NSUTF8StringEncoding];
    if (s) return s;
    return ToNSString(text);
}

@protocol GLMPairwiseResultsCopying <NSObject>
- (NSString *)pairwiseCopyTextForRows:(NSIndexSet *)rows;
- (NSString *)pairwiseSnapshotText;
- (NSMenu *)pairwiseTableMenuForTableView:(NSTableView *)table event:(NSEvent *)event;
@end

@interface GLMPairwiseResultsTableView : NSTableView
@property(nonatomic, assign) id<GLMPairwiseResultsCopying> pairwiseCopyDelegate;
@end

@implementation GLMPairwiseResultsTableView
- (void)drawBackgroundInClipRect:(NSRect)clipRect
{
    [WorkbenchSurfaceColor() setFill];
    NSRectFill(clipRect);
}

- (void)drawRow:(NSInteger)row clipRect:(NSRect)clipRect
{
    if ([[self selectedRowIndexes] containsIndex:(NSUInteger)row]) {
        [[NSColor colorWithCalibratedWhite:0.93 alpha:1.0] setFill];
        NSRectFill([self rectOfRow:row]);
    }
    [super drawRow:row clipRect:clipRect];
}

- (void)copy:(id)sender
{
    (void)sender;
    NSString *text = [_pairwiseCopyDelegate pairwiseCopyTextForRows:[self selectedRowIndexes]];
    if (!text || [text length] == 0) return;
    NSPasteboard *pasteboard = [NSPasteboard generalPasteboard];
    [pasteboard clearContents];
    [pasteboard setString:text forType:NSPasteboardTypeString];
}

- (BOOL)validateUserInterfaceItem:(id<NSValidatedUserInterfaceItem>)item
{
    if ([item action] == @selector(copy:)) return [self numberOfSelectedRows] > 0;
    return [super validateUserInterfaceItem:item];
}

- (NSString *)snapshotTabDelimitedText
{
    return [_pairwiseCopyDelegate pairwiseSnapshotText] ?: @"";
}

- (NSMenu *)menuForEvent:(NSEvent *)event
{
    const NSPoint point = [self convertPoint:[event locationInWindow] fromView:nil];
    const NSInteger row = [self rowAtPoint:point];
    if (row >= 0 && ![[self selectedRowIndexes] containsIndex:(NSUInteger)row]) {
        [self selectRowIndexes:[NSIndexSet indexSetWithIndex:(NSUInteger)row] byExtendingSelection:NO];
    }
    return [_pairwiseCopyDelegate pairwiseTableMenuForTableView:self event:event];
}
@end

@interface GLMPairwiseResultsHeaderView : NSTableHeaderView
@end

@implementation GLMPairwiseResultsHeaderView
- (void)drawRect:(NSRect)dirtyRect
{
    (void)dirtyRect;
    [WorkbenchSurfaceColor() setFill];
    NSRectFill([self bounds]);
    NSTableView *table = [self tableView];
    if (!table) return;
    NSColor *textColor = [NSColor colorWithCalibratedWhite:0.15 alpha:1.0];
    for (NSInteger columnIndex = 0; columnIndex < (NSInteger)[[table tableColumns] count]; ++columnIndex) {
        NSTableColumn *column = [[table tableColumns] objectAtIndex:(NSUInteger)columnIndex];
        NSMutableParagraphStyle *style = [[NSMutableParagraphStyle alloc] init];
        [style setAlignment:columnIndex == 0 ? NSTextAlignmentLeft : NSTextAlignmentRight];
        NSDictionary *attrs = @{
            NSFontAttributeName: [NSFont systemFontOfSize:12.0 weight:NSFontWeightSemibold],
            NSForegroundColorAttributeName: textColor,
            NSParagraphStyleAttributeName: style
        };
        NSRect rect = NSInsetRect([self headerRectOfColumn:columnIndex], 2.0, 2.0);
        [[[column headerCell] stringValue] drawInRect:rect withAttributes:attrs];
    }
    [[NSColor colorWithCalibratedWhite:0.86 alpha:1.0] setStroke];
    NSBezierPath *rule = [NSBezierPath bezierPath];
    [rule moveToPoint:NSMakePoint(0.0, NSMaxY([self bounds]) - 0.5)];
    [rule lineToPoint:NSMakePoint(NSWidth([self bounds]), NSMaxY([self bounds]) - 0.5)];
    [rule stroke];
}
@end

static NSString *PairwiseNumberText(double value, int digits)
{
    return SafeNSStringFromUTF8(rlispstat::core::FormatDoubleOrDash(value, digits));
}

static NSString *PairwisePValueText(double value)
{
    std::string text = rlispstat::core::FormatPValue(value);
    if (text.size() > 1 && text[0] == '0' && text[1] == '.') text.erase(0, 1);
    if (text.size() > 2 && text[0] == '-' && text[1] == '0' && text[2] == '.') text.erase(1, 1);
    return SafeNSStringFromUTF8(text);
}

struct GLMPairwiseComparisonPlotLink {
    std::string group;
    std::string response;
    std::string factor;
    std::string method;
    bool gamesHowell = false;
    bool binaryRegression = false;
    bool binaryOddsRatio = false;
    bool pairedMeanDifferences = false;
    double confidenceLevel = 0.95;
    int casesAnalysed = 0;
    int casesExcluded = 0;
    std::vector<std::string> levels;
    std::vector<std::set<int>> rowsByComparison;
    std::map<std::string, std::set<int>> rowsByLevel;
    struct Observation { int row = 0; std::string level; double response = NAN; };
    std::vector<Observation> observations;
};

