    [select setEnabled:hasRows];
    [menu addItem:select];
    NSMenuItem *clear = [[NSMenuItem alloc] initWithTitle:@"Clear selection"
                                                    action:@selector(clearPairwiseSelection:)
                                             keyEquivalent:@""];
    [clear setTarget:self];
    [clear setEnabled:!_plotLink.group.empty() && SelectionCount(_plotLink.group) > 0];
    [menu addItem:clear];
    [menu addItem:[NSMenuItem separatorItem]];
    NSMenuItem *forestPlot = [[NSMenuItem alloc] initWithTitle:@"Show pairwise differences plot"
                                                       action:@selector(openPairwiseForestPlot:)
                                                keyEquivalent:@""];
    [forestPlot setTarget:self];
    [forestPlot setEnabled:!_rows.empty()];
    [menu addItem:forestPlot];
    NSMenuItem *boxplot = [[NSMenuItem alloc] initWithTitle:@"Show boxplot of observed data"
                                                     action:@selector(openPairwiseBoxplot:)
                                              keyEquivalent:@""];
    [boxplot setTarget:self];
    [boxplot setEnabled:!_plotLink.observations.empty()];
    [menu addItem:boxplot];
    [menu addItem:[NSMenuItem separatorItem]];
    NSMenuItem *exportRoot = [[NSMenuItem alloc] initWithTitle:@"Export" action:nil keyEquivalent:@""];
    NSMenu *exportMenu = [[NSMenu alloc] initWithTitle:@"Export"];
    AddStandardTableVisualExportItems(exportMenu, _table,
        [@"Pairwise comparisons — " stringByAppendingString:ToNSString(_term)],
        @"pairwise-comparisons", [self pairwiseCopyTextForRows:[self allRows]]);
    [exportMenu addItem:[NSMenuItem separatorItem]];
    NSMenuItem *copySelected = [[NSMenuItem alloc] initWithTitle:@"Copy selected rows"
                                                            action:@selector(copy:)
                                                     keyEquivalent:@""];
    [copySelected setTarget:_table];
    [copySelected setEnabled:hasRows];
    [exportMenu addItem:copySelected];
    NSMenuItem *copyAll = [[NSMenuItem alloc] initWithTitle:@"Copy table with headers"
                                                     action:@selector(copyWholeTable:)
                                              keyEquivalent:@""];
    [copyAll setTarget:self];
    [exportMenu addItem:copyAll];
    [exportMenu addItem:[NSMenuItem separatorItem]];
    NSMenuItem *csv = [[NSMenuItem alloc] initWithTitle:@"Export table as CSV…"
                                                  action:@selector(exportCSV:)
                                           keyEquivalent:@""];
    [csv setTarget:self];
    [exportMenu addItem:csv];
    NSMenuItem *pdfDisplayed = [[NSMenuItem alloc] initWithTitle:@"Export table as PDF — As displayed…"
                                                           action:@selector(exportPDFAsDisplayed:)
                                                    keyEquivalent:@""];
    [pdfDisplayed setTarget:self];
    [exportMenu addItem:pdfDisplayed];
    NSMenuItem *pdfAPA = [[NSMenuItem alloc] initWithTitle:@"Export table as PDF — APA 7…"
                                                     action:@selector(exportPDFAPA:)
                                              keyEquivalent:@""];
    [pdfAPA setTarget:self];
    [exportMenu addItem:pdfAPA];
    [exportRoot setSubmenu:exportMenu];
    [menu addItem:exportRoot];
    AddSnapshotAlbumContextItems(menu);
    return menu;
}

- (NSIndexSet *)allRows
{
    return _rows.empty() ? [NSIndexSet indexSet] :
        [NSIndexSet indexSetWithIndexesInRange:NSMakeRange(0, _rows.size())];
}

- (void)copyWholeTable:(id)sender
{
    (void)sender;
    NSString *text = [self pairwiseCopyTextForRows:[self allRows]];
    NSPasteboard *pasteboard = [NSPasteboard generalPasteboard];
    [pasteboard clearContents];
    [pasteboard setString:text forType:NSPasteboardTypeString];
}

- (const std::string &)pairwiseResultsGroup
{
    return _plotLink.group;
}

- (void)activateComparisonAtIndex:(NSInteger)index
{
    if (index < 0 || static_cast<std::size_t>(index) >= _plotLink.rowsByComparison.size() || _plotLink.group.empty()) return;
    const std::set<int> &rows = _plotLink.rowsByComparison[static_cast<std::size_t>(index)];
    if (rows.empty()) return;
    int selectionVersion = 0;
    bool changed = false;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        changed = SetGroupSelectionUnlocked(_plotLink.group, rows, &selectionVersion);
    }
    if (changed) {
        PublishSpreadPlotMessage("ROW_SELECTION_CHANGED", _plotLink.group, "glm-pairwise", "",
                                 std::vector<int>(rows.begin(), rows.end()), selectionVersion);
    }
    [self refreshPairwiseResultsSelection];
}

- (void)selectComparison:(id)sender
{
    (void)sender;
    [self activateComparisonAtIndex:[_table selectedRow]];
}

- (void)clearPairwiseSelection:(id)sender
{
    (void)sender;
    if (_plotLink.group.empty()) return;
    int selectionVersion = 0;
    bool changed = false;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        changed = ClearGroupSelectionUnlocked(_plotLink.group, &selectionVersion);
    }
    if (changed) {
        PublishSpreadPlotMessage("ROW_SELECTION_CHANGED", _plotLink.group, "glm-pairwise", "", {}, selectionVersion);
    }
    [self refreshPairwiseResultsSelection];
}

- (void)openPairwiseForestPlot:(id)sender
{
    (void)sender;
    if (_rows.empty()) return;
    ShowGLMPairwiseComparisonPlotOnMain(_term, _rows, _plotLink);
}

- (void)openPairwiseBoxplot:(id)sender
{
    (void)sender;
    if (_plotLink.observations.empty()) return;
    ShowGLMPairwiseObservedBoxplotOnMain(_plotLink);
}

- (void)tableViewSelectionDidChange:(NSNotification *)notification
{
    if ([notification object] != _table || _synchronizingSelection) return;
    const NSInteger row = [_table selectedRow];
    if (row >= 0) [self activateComparisonAtIndex:row];
}

- (void)refreshPairwiseResultsSelection
{
    std::set<int> selection;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        auto it = g_groupSelections.find(_plotLink.group);
        if (it != g_groupSelections.end()) selection = it->second;
    }
    NSInteger active = -1;
    for (std::size_t index = 0; index < _plotLink.rowsByComparison.size(); ++index) {
        if (!_plotLink.rowsByComparison[index].empty() && _plotLink.rowsByComparison[index] == selection) {
            active = static_cast<NSInteger>(index);
            break;
        }
    }
    _synchronizingSelection = YES;
    [_table selectRowIndexes:(active >= 0 ? [NSIndexSet indexSetWithIndex:(NSUInteger)active] : [NSIndexSet indexSet])
         byExtendingSelection:NO];
    _synchronizingSelection = NO;
}

- (NSString *)csvText
{
    NSMutableArray<NSString *> *lines = [NSMutableArray array];
    NSMutableArray<NSString *> *headers = [NSMutableArray array];
    for (NSTableColumn *column in [_table tableColumns]) [headers addObject:[[column headerCell] stringValue]];
    auto csvRow = ^NSString *(NSArray<NSString *> *cells) {
        NSMutableArray<NSString *> *escaped = [NSMutableArray array];
        for (NSString *cell in cells) {
            NSString *value = [cell stringByReplacingOccurrencesOfString:@"\"" withString:@"\"\""];
            if ([value rangeOfCharacterFromSet:[NSCharacterSet characterSetWithCharactersInString:@",\"\n\r"]].location != NSNotFound) {
                value = [NSString stringWithFormat:@"\"%@\"", value];
            }
            [escaped addObject:value];
        }
        return [escaped componentsJoinedByString:@","];
    };
    [lines addObject:csvRow(headers)];
    for (NSUInteger row = 0; row < _rows.size(); ++row) {
        NSMutableArray<NSString *> *cells = [NSMutableArray array];
        for (NSTableColumn *column in [_table tableColumns]) {
            [cells addObject:[self tableView:_table objectValueForTableColumn:column row:(NSInteger)row]];
        }
        [lines addObject:csvRow(cells)];
    }
    return [lines componentsJoinedByString:@"\n"];
}

- (void)exportCSV:(id)sender
{
    (void)sender;
    NSSavePanel *panel = [NSSavePanel savePanel];
    [panel setAllowedFileTypes:@[@"csv"]];
    [panel setNameFieldStringValue:@"pairwise-comparisons.csv"];
    if ([panel runModal] != NSModalResponseOK) return;
    [[self csvText] writeToURL:[panel URL] atomically:YES encoding:NSUTF8StringEncoding error:nil];
}

- (void)exportPDFAsDisplayed:(id)sender
{
    (void)sender;
    ExportGLMPairwiseComparisonTablePDF(_rows, _plotLink, false);
}

- (void)exportPDFAPA:(id)sender
{
    (void)sender;
    ExportGLMPairwiseComparisonTablePDF(_rows, _plotLink, true);
}

- (NSInteger)numberOfRowsInTableView:(NSTableView *)tableView
{
    (void)tableView;
    return static_cast<NSInteger>(_rows.size());
}

- (id)tableView:(NSTableView *)tableView objectValueForTableColumn:(NSTableColumn *)column row:(NSInteger)row
{
    (void)tableView;
    if (row < 0 || static_cast<std::size_t>(row) >= _rows.size()) return @"";
    const rlispstat::core::LinearFunctionEstimate &value = _rows[static_cast<std::size_t>(row)];
    NSString *identifier = [column identifier];
    if ([identifier isEqualToString:@"comparison"]) {
        return [SafeNSStringFromUTF8(value.label) stringByReplacingOccurrencesOfString:@" - " withString:@" − "];
    }
    if ([identifier isEqualToString:@"estimate"]) return PairwiseNumberText(value.estimate, 4);
    if ([identifier isEqualToString:@"se"]) return PairwiseNumberText(value.stdError, 4);
    if ([identifier isEqualToString:@"df"]) return PairwiseNumberText(value.degreesOfFreedom, 1);
    if ([identifier isEqualToString:@"t"]) return PairwiseNumberText(value.statistic, 3);
    if ([identifier isEqualToString:@"p"]) return PairwisePValueText(value.adjustedPValue);
    if ([identifier isEqualToString:@"lower"]) return PairwiseNumberText(value.ciLower, 4);
    if ([identifier isEqualToString:@"upper"]) return PairwiseNumberText(value.ciUpper, 4);
    return @"";
}

- (NSString *)pairwiseCopyTextForRows:(NSIndexSet *)rows
{
    if (!rows || [rows count] == 0) return @"";
    NSMutableArray<NSString *> *lines = [NSMutableArray array];
    NSMutableArray<NSString *> *headers = [NSMutableArray array];
    for (NSTableColumn *column in [_table tableColumns]) {
        [headers addObject:[[column headerCell] stringValue]];
    }
    [lines addObject:[headers componentsJoinedByString:@"\t"]];
    NSUInteger index = [rows firstIndex];
    while (index != NSNotFound) {
        NSMutableArray<NSString *> *cells = [NSMutableArray array];
        for (NSTableColumn *column in [_table tableColumns]) {
            [cells addObject:[self tableView:_table objectValueForTableColumn:column row:(NSInteger)index]];
        }
        [lines addObject:[cells componentsJoinedByString:@"\t"]];
        index = [rows indexGreaterThanIndex:index];
    }
    return [lines componentsJoinedByString:@"\n"];
}

- (NSString *)pairwiseSnapshotText
{
    return [self pairwiseCopyTextForRows:[self allRows]];
}
@end

static void DrawPairwisePDFText(const NSString *text, NSRect rect, NSDictionary *attributes)
{
    if (!text || NSIsEmptyRect(rect)) return;
    [text drawInRect:rect withAttributes:attributes];
}

static std::string PairwisePDFFileStem(const GLMPairwiseComparisonPlotLink &link, bool apa)
{
    std::string stem = "pairwise_" + link.response + "_by_" + link.factor + (apa ? "_APA7" : "_table");
    for (char &ch : stem) if (!std::isalnum(static_cast<unsigned char>(ch)) && ch != '_' && ch != '-') ch = '_';
    return stem;
}

static void ExportGLMPairwiseComparisonTablePDF(
    const std::vector<rlispstat::core::LinearFunctionEstimate> &rows,
    const GLMPairwiseComparisonPlotLink &link,
    bool apaStyle)
{
    NSString *tableNumber = @"1";
    NSString *title = SafeNSStringFromUTF8(apaStyle
        ? ("Pairwise Comparisons of " + link.response + " Across " + link.factor + " Groups")
        : ("Pairwise comparisons of " + link.response + " by " + link.factor));
    if (apaStyle) {
        NSAlert *alert = [[NSAlert alloc] init];
        [alert setMessageText:@"APA 7 table details"];
        [alert setInformativeText:@"Enter the table number and title to print above the APA 7 table."];
        NSTextField *numberField = [NSTextField textFieldWithString:tableNumber];
        NSTextField *titleField = [NSTextField textFieldWithString:title];
        [numberField setPlaceholderString:@"1"];
        [titleField setPlaceholderString:@"Pairwise comparisons"];
        NSStackView *accessory = [[NSStackView alloc] initWithFrame:NSMakeRect(0, 0, 420, 104)];
        [accessory setOrientation:NSUserInterfaceLayoutOrientationVertical];
        [accessory setAlignment:NSLayoutAttributeLeading];
        [accessory setSpacing:5.0];
        [accessory addArrangedSubview:[NSTextField labelWithString:@"Table number"]];
        [accessory addArrangedSubview:numberField];
        [accessory addArrangedSubview:[NSTextField labelWithString:@"Table title"]];
        [accessory addArrangedSubview:titleField];
        [[numberField widthAnchor] constraintEqualToConstant:420.0].active = YES;
        [[titleField widthAnchor] constraintEqualToConstant:420.0].active = YES;
        [numberField setNextKeyView:titleField];
        [alert setAccessoryView:accessory];
        [alert addButtonWithTitle:@"Continue"];
        [alert addButtonWithTitle:@"Cancel"];
        [[alert window] setInitialFirstResponder:numberField];
        if ([alert runModal] != NSAlertFirstButtonReturn) return;
        if ([[numberField stringValue] length] > 0) tableNumber = [numberField stringValue];
        if ([[titleField stringValue] length] > 0) title = [titleField stringValue];
    }
    NSSavePanel *panel = [NSSavePanel savePanel];
    [panel setAllowedFileTypes:@[@"pdf"]];
    [panel setNameFieldStringValue:[NSString stringWithFormat:@"%@.pdf", SafeNSStringFromUTF8(PairwisePDFFileStem(link, apaStyle))]];
    if ([panel runModal] != NSModalResponseOK) return;

    const CGFloat pageWidth = apaStyle ? 595.0 : 842.0;
    const CGFloat pageHeight = apaStyle ? 842.0 : 595.0;
    CGRect mediaBox = CGRectMake(0.0, 0.0, pageWidth, pageHeight);
    CGContextRef context = CGPDFContextCreateWithURL((__bridge CFURLRef)[panel URL], &mediaBox, nullptr);
    if (!context) return;
    const CGFloat margin = 42.0;
    NSString *estimateHeader = link.binaryRegression
        ? (link.binaryOddsRatio ? @"OR" : @"Probability difference")
        : @"Estimate";
    NSString *statisticHeader = link.binaryRegression ? @"z" : @"t";
    const NSArray<NSString *> *headers = apaStyle
        ? @[ @"Comparison", estimateHeader, @"SE", @"df", statisticHeader, @"p", @"95% CI" ]
        : @[ @"Comparison", estimateHeader, @"SE", @"df", statisticHeader, @"Adjusted p", @"Lower 95%", @"Upper 95%" ];
    const std::vector<CGFloat> widths = apaStyle
        ? std::vector<CGFloat>{145, 62, 48, 45, 45, 50, 108}
        : std::vector<CGFloat>{184, 76, 60, 54, 54, 78, 82, 82};
    NSDictionary *titleAttrs = @{ NSFontAttributeName: [NSFont systemFontOfSize:(apaStyle ? 13.0 : 16.0) weight:NSFontWeightSemibold], NSForegroundColorAttributeName: [NSColor blackColor] };
    NSDictionary *bodyAttrs = @{ NSFontAttributeName: [NSFont systemFontOfSize:10.0], NSForegroundColorAttributeName: [NSColor blackColor] };
    NSDictionary *headerAttrs = @{ NSFontAttributeName: [NSFont systemFontOfSize:10.0 weight:NSFontWeightSemibold], NSForegroundColorAttributeName: [NSColor blackColor] };
    NSDictionary *noteAttrs = @{ NSFontAttributeName: [NSFont systemFontOfSize:9.5], NSForegroundColorAttributeName: [NSColor blackColor] };
    NSInteger page = 0;
    CGFloat y = 0.0;
    auto endPage = [&]() {
        if (page <= 0) return;
        DrawPairwisePDFText([NSString stringWithFormat:@"Page %ld", (long)page],
                            NSMakeRect(pageWidth - margin - 55.0, pageHeight - margin + 7.0, 55.0, 12.0), noteAttrs);
        [NSGraphicsContext setCurrentContext:nil];
        CGContextRestoreGState(context);
        CGContextEndPage(context);
    };
    auto beginPage = [&](bool firstPage) {
        if (page > 0) {
            endPage();
        }
        ++page;
        CGContextBeginPage(context, nullptr);
        CGContextSaveGState(context);
        CGContextTranslateCTM(context, 0.0, pageHeight);
        CGContextScaleCTM(context, 1.0, -1.0);
        [NSGraphicsContext setCurrentContext:[NSGraphicsContext graphicsContextWithCGContext:context flipped:YES]];
        y = margin;
        if (apaStyle && firstPage) {
            DrawPairwisePDFText([NSString stringWithFormat:@"Table %@", tableNumber], NSMakeRect(margin, y, pageWidth - 2 * margin, 18), headerAttrs);
            y += 20.0;
        }
        DrawPairwisePDFText(firstPage ? title : [NSString stringWithFormat:@"%@ (continued)", title], NSMakeRect(margin, y, pageWidth - 2 * margin, 22), titleAttrs);
        y += 28.0;
        if (firstPage && !apaStyle) {
            NSString *method = link.binaryRegression ? SafeNSStringFromUTF8(link.method) :
                (link.gamesHowell ? @"Method: Games–Howell pairwise comparisons" : @"Model: Heteroscedastic generalized least squares; pairwise comparisons of estimated marginal means (Tukey adjustment)");
            DrawPairwisePDFText(method, NSMakeRect(margin, y, pageWidth - 2 * margin, 15), bodyAttrs); y += 16.0;
            DrawPairwisePDFText([NSString stringWithFormat:@"Confidence level: %.0f%%    Cases analysed: %d    Cases excluded: %d", link.confidenceLevel * 100.0, link.casesAnalysed, link.casesExcluded], NSMakeRect(margin, y, pageWidth - 2 * margin, 15), bodyAttrs); y += 22.0;
        }
        NSBezierPath *topRule = [NSBezierPath bezierPath]; [topRule moveToPoint:NSMakePoint(margin, y)]; [topRule lineToPoint:NSMakePoint(pageWidth - margin, y)]; [topRule setLineWidth:1.0]; [[NSColor blackColor] setStroke]; [topRule stroke];
        y += 4.0;
        CGFloat x = margin;
        for (NSUInteger index = 0; index < [headers count]; ++index) {
            NSMutableParagraphStyle *style = [[NSMutableParagraphStyle alloc] init]; [style setAlignment:index == 0 ? NSTextAlignmentLeft : NSTextAlignmentRight];
            NSMutableDictionary *attrs = [headerAttrs mutableCopy]; attrs[NSParagraphStyleAttributeName] = style;
            DrawPairwisePDFText(headers[index], NSMakeRect(x, y, widths[index] - 3.0, 16.0), attrs); x += widths[index];
        }
        y += 18.0;
        NSBezierPath *headerRule = [NSBezierPath bezierPath]; [headerRule moveToPoint:NSMakePoint(margin, y)]; [headerRule lineToPoint:NSMakePoint(pageWidth - margin, y)]; [headerRule setLineWidth:0.8]; [headerRule stroke]; y += 4.0;
    };
    beginPage(true);
    for (const rlispstat::core::LinearFunctionEstimate &row : rows) {
        NSString *comparison = [SafeNSStringFromUTF8(row.label) stringByReplacingOccurrencesOfString:@" - " withString:@" − "];
        const CGFloat comparisonHeight = std::max((CGFloat)18.0, [comparison boundingRectWithSize:NSMakeSize(widths[0] - 3.0, 100.0) options:NSStringDrawingUsesLineFragmentOrigin attributes:bodyAttrs].size.height + 3.0);
        const CGFloat rowHeight = std::max((CGFloat)20.0, comparisonHeight);
        if (y + rowHeight > pageHeight - margin - 70.0) beginPage(false);
        NSArray<NSString *> *cells = apaStyle
            ? @[ comparison, PairwiseNumberText(row.estimate, 4), PairwiseNumberText(row.stdError, 4), PairwiseNumberText(row.degreesOfFreedom, 1), PairwiseNumberText(row.statistic, 3), PairwisePValueText(row.adjustedPValue), [NSString stringWithFormat:@"[%@, %@]", PairwiseNumberText(row.ciLower, 4), PairwiseNumberText(row.ciUpper, 4)] ]
            : @[ comparison, PairwiseNumberText(row.estimate, 4), PairwiseNumberText(row.stdError, 4), PairwiseNumberText(row.degreesOfFreedom, 1), PairwiseNumberText(row.statistic, 3), PairwisePValueText(row.adjustedPValue), PairwiseNumberText(row.ciLower, 4), PairwiseNumberText(row.ciUpper, 4) ];
        CGFloat x = margin;
        for (NSUInteger index = 0; index < [cells count]; ++index) {
            NSMutableParagraphStyle *style = [[NSMutableParagraphStyle alloc] init]; [style setAlignment:index == 0 ? NSTextAlignmentLeft : NSTextAlignmentRight];
            NSMutableDictionary *attrs = [bodyAttrs mutableCopy]; attrs[NSParagraphStyleAttributeName] = style;
            DrawPairwisePDFText(cells[index], NSMakeRect(x, y, widths[index] - 3.0, rowHeight), attrs); x += widths[index];
        }
        y += rowHeight;
    }
    const NSString *note = link.binaryRegression
        ? [NSString stringWithFormat:@"Note. The binary model and Tukey-adjusted comparisons were calculated in R using stats::glm and emmeans. %@ The confidence level was %.0f%%. The analysis included %d observations%@.", link.binaryOddsRatio ? @"Odds ratios are reported." : @"Probability differences are reported; odds ratios are not applicable to probit.", link.confidenceLevel * 100.0, link.casesAnalysed, link.casesExcluded > 0 ? [NSString stringWithFormat:@"; %d observations were excluded", link.casesExcluded] : @""]
        : (link.gamesHowell
            ? [NSString stringWithFormat:@"Note. Pairwise comparisons were calculated using the Games–Howell procedure. The confidence level was %.0f%%. Adjusted p values are reported. The analysis included %d observations%@.", link.confidenceLevel * 100.0, link.casesAnalysed, link.casesExcluded > 0 ? [NSString stringWithFormat:@"; %d observations were excluded", link.casesExcluded] : @""]
            : [NSString stringWithFormat:@"Note. Estimated marginal means were obtained from a heteroscedastic generalized least-squares model with separate residual variances for the levels of %@. Pairwise p values were adjusted using the Tukey method. The confidence level was %.0f%%. The analysis included %d observations%@.", SafeNSStringFromUTF8(link.factor), link.confidenceLevel * 100.0, link.casesAnalysed, link.casesExcluded > 0 ? [NSString stringWithFormat:@"; %d observations were excluded", link.casesExcluded] : @""]);
    const CGFloat noteHeight = [note boundingRectWithSize:NSMakeSize(pageWidth - 2 * margin, 100.0) options:NSStringDrawingUsesLineFragmentOrigin attributes:noteAttrs].size.height + 4.0;
    if (y + noteHeight + 20.0 > pageHeight - margin) beginPage(false);
    NSBezierPath *bottomRule = [NSBezierPath bezierPath]; [bottomRule moveToPoint:NSMakePoint(margin, y)]; [bottomRule lineToPoint:NSMakePoint(pageWidth - margin, y)]; [bottomRule setLineWidth:1.0]; [[NSColor blackColor] setStroke]; [bottomRule stroke]; y += 8.0;
    DrawPairwisePDFText(note, NSMakeRect(margin, y, pageWidth - 2 * margin, noteHeight), noteAttrs);
    endPage();
    CGContextRelease(context);
}

static void ExportBinaryRegressionAsDisplayedPDF(const GeneralizedGLMState &state,
                                                 bool showModelDetails)
{
    NSString *title = [NSString stringWithFormat:@"Binary Regression Predicting %@", SafeNSStringFromUTF8(state.response)];
    BOOL landscape = YES;
    NSSavePanel *panel = [NSSavePanel savePanel];
    [panel setAllowedFileTypes:@[@"pdf"]];
    [panel setNameFieldStringValue:[NSString stringWithFormat:@"binary_regression_%@.pdf",
                                    SafeNSStringFromUTF8(state.response)]];
    if ([panel runModal] != NSModalResponseOK) return;

    const CGFloat pageWidth = landscape ? 842.0 : 595.0;
    const CGFloat pageHeight = landscape ? 595.0 : 842.0;
    CGRect mediaBox = CGRectMake(0, 0, pageWidth, pageHeight);
    CGContextRef context = CGPDFContextCreateWithURL((__bridge CFURLRef)[panel URL], &mediaBox, nullptr);
    if (!context) return;
    const CGFloat margin = 42.0;
    NSDictionary *titleAttrs = @{NSFontAttributeName:[NSFont systemFontOfSize:14 weight:NSFontWeightSemibold], NSForegroundColorAttributeName:[NSColor blackColor]};
    NSDictionary *sectionAttrs = @{NSFontAttributeName:[NSFont systemFontOfSize:10.5 weight:NSFontWeightSemibold], NSForegroundColorAttributeName:[NSColor blackColor]};
    NSDictionary *bodyAttrs = @{NSFontAttributeName:[NSFont systemFontOfSize:9.2], NSForegroundColorAttributeName:[NSColor blackColor]};
    NSDictionary *noteAttrs = @{NSFontAttributeName:[NSFont systemFontOfSize:8.8], NSForegroundColorAttributeName:[NSColor blackColor]};
    NSInteger page = 0;
    CGFloat y = margin;
    auto endPage = [&]() {
        if (page == 0) return;
        DrawPairwisePDFText([NSString stringWithFormat:@"Page %ld", (long)page], NSMakeRect(pageWidth - margin - 50, pageHeight - margin + 6, 50, 12), noteAttrs);
        [NSGraphicsContext setCurrentContext:nil];
        CGContextRestoreGState(context);
        CGContextEndPage(context);
    };
    auto beginPage = [&](NSString *continued) {
        if (page > 0) endPage();
        ++page;
        CGContextBeginPage(context, nullptr);
        CGContextSaveGState(context);
        CGContextTranslateCTM(context, 0, pageHeight);
        CGContextScaleCTM(context, 1, -1);
        [NSGraphicsContext setCurrentContext:[NSGraphicsContext graphicsContextWithCGContext:context flipped:YES]];
        y = margin;
        DrawPairwisePDFText(continued ?: title, NSMakeRect(margin, y, pageWidth - 2 * margin, 22), titleAttrs);
        y += 28;
        NSString *coding = [NSString stringWithFormat:@"Response: %@    Event: %@ (%d)    Reference: %@ (%d)    Link: %@    N = %d",
            SafeNSStringFromUTF8(state.response), SafeNSStringFromUTF8(state.responseCoding.eventLabel), state.responseCoding.eventCount,
            SafeNSStringFromUTF8(state.responseCoding.referenceLabel), state.responseCoding.referenceCount,
            SafeNSStringFromUTF8(state.link), state.n];
        DrawPairwisePDFText(coding, NSMakeRect(margin, y, pageWidth - 2 * margin, 16), bodyAttrs); y += 19;
    };
    auto rule = [&]() {
        NSBezierPath *path = [NSBezierPath bezierPath];
        [path moveToPoint:NSMakePoint(margin, y)]; [path lineToPoint:NSMakePoint(pageWidth - margin, y)];
        [path setLineWidth:0.8]; [[NSColor blackColor] setStroke]; [path stroke]; y += 4;
    };
    beginPage(nil);
    DrawPairwisePDFText(@"Global fit", NSMakeRect(margin, y, 120, 16), sectionAttrs); y += 18;
    NSString *fit = [NSString stringWithFormat:@"LR χ²(%d) = %@, p = %@; Nagelkerke pseudo-R² = %@",
        state.dfModel, SafeNSStringFromUTF8(FormatModelNumberOrDash(state.globalLR)), PairwisePValueText(state.globalP),
        SafeNSStringFromUTF8(FormatModelNumberOrDash(state.nagelkerkeR2))];
    DrawPairwisePDFText(fit, NSMakeRect(margin, y, pageWidth - 2 * margin, 18), bodyAttrs); y += 24;

    if (showModelDetails) {
        DrawPairwisePDFText(@"Model details", NSMakeRect(margin, y, 180, 16), sectionAttrs); y += 18;
        NSArray<NSString *> *details = @[
            [NSString stringWithFormat:@"Log likelihood: %@", SafeNSStringFromUTF8(FormatModelNumberOrDash(state.logLik))],
            [NSString stringWithFormat:@"Residual deviance: %@", SafeNSStringFromUTF8(FormatModelNumberOrDash(state.residualDeviance))],
            [NSString stringWithFormat:@"Null deviance: %@", SafeNSStringFromUTF8(FormatModelNumberOrDash(state.nullDeviance))],
            [NSString stringWithFormat:@"df residual: %d", state.dfResidual],
            [NSString stringWithFormat:@"AIC: %@", SafeNSStringFromUTF8(FormatModelNumberOrDash(state.aic))],
            [NSString stringWithFormat:@"BIC: %@", SafeNSStringFromUTF8(FormatModelNumberOrDash(state.bic))],
            [NSString stringWithFormat:@"McFadden R²: %@", SafeNSStringFromUTF8(FormatModelNumberOrDash(state.mcfaddenR2))],
            [NSString stringWithFormat:@"Cox–Snell R²: %@", SafeNSStringFromUTF8(FormatModelNumberOrDash(state.coxSnellR2))],
            [NSString stringWithFormat:@"Apparent AUC: %@¹", SafeNSStringFromUTF8(FormatModelNumberOrDash(state.auc))],
            [NSString stringWithFormat:@"Converged: %@", state.converged ? @"yes" : @"no"],
            [NSString stringWithFormat:@"Iterations: %d", state.iterations],
            [NSString stringWithFormat:@"Rank: %d/%d", state.rank, state.parameterCount]
        ];
        const CGFloat detailWidth = (pageWidth - 2 * margin) / 4.0;
        for (NSUInteger index = 0; index < details.count; ++index) {
            const NSUInteger row = index / 4;
            const NSUInteger column = index % 4;
            DrawPairwisePDFText(details[index], NSMakeRect(margin + column * detailWidth,
                y + row * 17.0, detailWidth - 5.0, 16), bodyAttrs);
        }
        y += 54.0;
        DrawPairwisePDFText(@"¹ Calculated on the observations used to fit the model; not out-of-sample validation.",
            NSMakeRect(margin, y, pageWidth - 2 * margin, 16), noteAttrs);
        y += 22.0;
    }

    DrawPairwisePDFText(@"Terms and coefficients", NSMakeRect(margin, y, 180, 16), sectionAttrs); y += 18; rule();
    NSArray<NSString *> *coefHeaders = @[@"Variable / level", @"b", @"SE", @"z", @"Wald p", @"LR χ²", @"df", @"LR p", @"OR / 95% CI"];
    const CGFloat available = pageWidth - 2 * margin;
    const CGFloat labelWidth = available * 0.22;
    const CGFloat effectWidth = available * 0.24;
    const CGFloat numericWidth = (available - labelWidth - effectWidth) / 7.0;
    CGFloat x = margin;
    for (NSUInteger index = 0; index < coefHeaders.count; ++index) {
        CGFloat width = index == 0 ? labelWidth : (index == 8 ? effectWidth : numericWidth);
        DrawPairwisePDFText(coefHeaders[index], NSMakeRect(x, y, width - 2, 15), sectionAttrs); x += width;
    }
    y += 17; rule();
    for (const auto &row : state.rows) {
        if (y + 18 > pageHeight - margin - 55) {
            beginPage([title stringByAppendingString:@" (continued)"]);
            DrawPairwisePDFText(@"Terms and coefficients (continued)", NSMakeRect(margin, y, 240, 16), sectionAttrs); y += 18; rule();
            x = margin;
            for (NSUInteger index = 0; index < coefHeaders.count; ++index) {
                CGFloat width = index == 0 ? labelWidth : (index == 8 ? effectWidth : numericWidth);
                DrawPairwisePDFText(coefHeaders[index], NSMakeRect(x, y, width - 2, 15), sectionAttrs); x += width;
            }
            y += 17; rule();
        }
        const bool parent = row.rowType == "factor_parent" || row.rowType == "term_parent";
        const bool structural = parent || row.rowType == "reference";
        const bool intercept = row.term == "(Intercept)" || row.sourceTerm == "(Intercept)";
        const bool showTermTest = !intercept && (parent ||
            (!row.sourceTerm.empty() && row.term == row.sourceTerm));
        const std::string source = row.sourceTerm.empty() ? row.term : row.sourceTerm;
        const rlispstat::core::BinaryTermTestRow *test = nullptr;
        if (showTermTest) for (const auto &candidate : state.termTests) {
            if (candidate.term == source) { test = &candidate; break; }
        }
        NSString *dash = @"—";
        std::string displayLabel = row.displayLabel.empty() ? row.term : row.displayLabel;
        if (row.rowType == "reference" && displayLabel.find("reference") == std::string::npos) displayLabel += " (reference)";
        NSMutableArray<NSString *> *cells = [NSMutableArray arrayWithObject:SafeNSStringFromUTF8(displayLabel)];
        for (double value : {row.estimate, row.stdError, row.statistic}) [cells addObject:structural ? dash : SafeNSStringFromUTF8(FormatModelNumberOrDash(value))];
        [cells addObject:structural ? dash : PairwisePValueText(row.pValue)];
        [cells addObject:test ? SafeNSStringFromUTF8(FormatModelNumberOrDash(test->statistic)) : dash];
        [cells addObject:test ? [NSString stringWithFormat:@"%d", test->df] : dash];
        [cells addObject:test ? PairwisePValueText(test->pValue) : dash];
        NSString *effect = dash;
        if (!structural) effect = state.binaryLink == rlispstat::core::BinaryLink::Logit
            ? [NSString stringWithFormat:@"%@ [%@, %@]", SafeNSStringFromUTF8(FormatModelNumberOrDash(row.oddsRatio)), SafeNSStringFromUTF8(FormatModelNumberOrDash(row.oddsRatioLower)), SafeNSStringFromUTF8(FormatModelNumberOrDash(row.oddsRatioUpper))]
            : [NSString stringWithFormat:@"[%@, %@]", SafeNSStringFromUTF8(FormatModelNumberOrDash(row.ciLower)), SafeNSStringFromUTF8(FormatModelNumberOrDash(row.ciUpper))];
        [cells addObject:effect];
        x = margin;
        for (NSUInteger index = 0; index < cells.count; ++index) {
            CGFloat width = index == 0 ? labelWidth : (index == 8 ? effectWidth : numericWidth);
            DrawPairwisePDFText(cells[index], NSMakeRect(x, y, width - 2, 16), bodyAttrs); x += width;
        }
        y += 17;
    }
    y += 3; rule();
    NSString *note = state.binaryLink == rlispstat::core::BinaryLink::Logit
        ? [NSString stringWithFormat:@"Note. The model used a binomial distribution with a logit link. The event modelled was %@; %@ was the reference outcome. OR = odds ratio. Confidence intervals are 95%% Wald intervals. Calculations were performed in R using stats::glm.", SafeNSStringFromUTF8(state.responseCoding.eventLabel), SafeNSStringFromUTF8(state.responseCoding.referenceLabel)]
        : [NSString stringWithFormat:@"Note. The model used a binomial distribution with a probit link. The event modelled was %@; %@ was the reference outcome. Coefficients and confidence intervals are reported on the probit scale. Confidence intervals are 95%% Wald intervals. Calculations were performed in R using stats::glm.", SafeNSStringFromUTF8(state.responseCoding.eventLabel), SafeNSStringFromUTF8(state.responseCoding.referenceLabel)];
    CGFloat noteHeight = [note boundingRectWithSize:NSMakeSize(pageWidth - 2 * margin, 90) options:NSStringDrawingUsesLineFragmentOrigin attributes:noteAttrs].size.height + 4;
    if (y + noteHeight > pageHeight - margin) beginPage([title stringByAppendingString:@" (continued)"]);
    DrawPairwisePDFText(note, NSMakeRect(margin, y, pageWidth - 2 * margin, noteHeight), noteAttrs); y += noteHeight + 6;
    for (const std::string &warning : state.warnings) {
        DrawPairwisePDFText(SafeNSStringFromUTF8("Warning. " + warning), NSMakeRect(margin, y, pageWidth - 2 * margin, 18), noteAttrs); y += 18;
    }
    endPage();
    CGPDFContextClose(context);
    CGContextRelease(context);
}

static void ExportBinaryRegressionPDF(const GeneralizedGLMState &state, bool apaStyle,
                                      bool showModelDetails = false)
{
    if (apaStyle) rlispstat::platform::macos::ShowBinaryRegressionAPAExportPanel(state);
    else ExportBinaryRegressionAsDisplayedPDF(state, showModelDetails);
}

static void ExportBinaryComparisonPDFNative(const GeneralizedComparisonState &state, bool apaStyle)
{
    NSString *tableNumber = @"1";
    NSString *title = [NSString stringWithFormat:@"Comparison of Binary Regression Models Predicting %@", SafeNSStringFromUTF8(state.response)];
    if (apaStyle) {
        NSAlert *alert = [[NSAlert alloc] init];
        [alert setMessageText:@"APA 7 table details"];
        [alert setInformativeText:@"Enter the table number and title."];
        NSTextField *numberField = [NSTextField textFieldWithString:tableNumber];
        NSTextField *titleField = [NSTextField textFieldWithString:title];
        NSStackView *accessory = [[NSStackView alloc] initWithFrame:NSMakeRect(0, 0, 420, 104)];
        [accessory setOrientation:NSUserInterfaceLayoutOrientationVertical]; [accessory setSpacing:5];
        for (NSView *view in @[[NSTextField labelWithString:@"Table number"], numberField,
                               [NSTextField labelWithString:@"Table title"], titleField]) [accessory addArrangedSubview:view];
        [[numberField widthAnchor] constraintEqualToConstant:420].active = YES;
        [[titleField widthAnchor] constraintEqualToConstant:420].active = YES;
        [alert setAccessoryView:accessory]; [alert addButtonWithTitle:@"Continue"]; [alert addButtonWithTitle:@"Cancel"];
        if ([alert runModal] != NSAlertFirstButtonReturn) return;
        if ([[numberField stringValue] length]) tableNumber = [numberField stringValue];
        if ([[titleField stringValue] length]) title = [titleField stringValue];
    }
    NSSavePanel *panel = [NSSavePanel savePanel];
    [panel setAllowedFileTypes:@[@"pdf"]];
    [panel setNameFieldStringValue:apaStyle ? @"binary_model_comparison_APA7.pdf" : @"binary_model_comparison.pdf"];
    if ([panel runModal] != NSModalResponseOK) return;
    const CGFloat pageWidth = 842, pageHeight = 595, margin = 38;
    CGRect mediaBox = CGRectMake(0, 0, pageWidth, pageHeight);
    CGContextRef context = CGPDFContextCreateWithURL((__bridge CFURLRef)[panel URL], &mediaBox, nullptr);
    if (!context) return;
    CGContextBeginPage(context, nullptr); CGContextSaveGState(context);
    CGContextTranslateCTM(context, 0, pageHeight); CGContextScaleCTM(context, 1, -1);
    [NSGraphicsContext setCurrentContext:[NSGraphicsContext graphicsContextWithCGContext:context flipped:YES]];
    NSDictionary *titleAttrs = @{NSFontAttributeName:[NSFont systemFontOfSize:14 weight:NSFontWeightSemibold], NSForegroundColorAttributeName:[NSColor blackColor]};
    NSDictionary *headerAttrs = @{NSFontAttributeName:[NSFont systemFontOfSize:9 weight:NSFontWeightSemibold], NSForegroundColorAttributeName:[NSColor blackColor]};
    NSDictionary *bodyAttrs = @{NSFontAttributeName:[NSFont systemFontOfSize:8.8], NSForegroundColorAttributeName:[NSColor blackColor]};
    CGFloat y = margin;
    if (apaStyle) { DrawPairwisePDFText([NSString stringWithFormat:@"Table %@", tableNumber], NSMakeRect(margin, y, 200, 16), headerAttrs); y += 19; }
    DrawPairwisePDFText(title, NSMakeRect(margin, y, pageWidth - 2 * margin, 22), titleAttrs); y += 28;
    NSString *coding = [NSString stringWithFormat:@"Response: %@    Event: %@    Reference: %@    Link: %@    Common rows: %lu",
        SafeNSStringFromUTF8(state.response), SafeNSStringFromUTF8(state.responseCoding.eventLabel),
        SafeNSStringFromUTF8(state.responseCoding.referenceLabel), SafeNSStringFromUTF8(state.link), (unsigned long)state.commonRows.size()];
    DrawPairwisePDFText(coding, NSMakeRect(margin, y, pageWidth - 2 * margin, 16), bodyAttrs); y += 22;
    NSArray<NSString *> *headers = @[@"Reduced model", @"Full model", @"LR χ²", @"df", @"p", @"ΔDeviance"];
    std::vector<CGFloat> widths = {170, 170, 100, 55, 90, 110};
    NSBezierPath *path = [NSBezierPath bezierPath]; [path moveToPoint:NSMakePoint(margin, y)]; [path lineToPoint:NSMakePoint(pageWidth-margin, y)]; [[NSColor blackColor] setStroke]; [path stroke]; y += 4;
    CGFloat x = margin;
    for (NSUInteger i = 0; i < headers.count; ++i) { DrawPairwisePDFText(headers[i], NSMakeRect(x, y, widths[i]-2, 16), headerAttrs); x += widths[i]; }
    y += 18; path = [NSBezierPath bezierPath]; [path moveToPoint:NSMakePoint(margin, y)]; [path lineToPoint:NSMakePoint(pageWidth-margin, y)]; [path stroke]; y += 4;
    for (std::size_t index = 1; index < state.models.size(); ++index) {
        const auto &reduced = state.models[index - 1];
        const auto &full = state.models[index];
        NSArray<NSString *> *cells = @[SafeNSStringFromUTF8(reduced.label), SafeNSStringFromUTF8(full.label),
            full.comparisonOk ? PairwiseNumberText(full.comparisonStatistic, 3) : @"—",
            full.comparisonOk ? [NSString stringWithFormat:@"%d", full.comparisonDf] : @"—",
            full.comparisonOk ? PairwisePValueText(full.comparisonP) : @"—",
            full.comparisonOk ? PairwiseNumberText(full.comparisonDelta, 3) : @"—"];
        x=margin; for(NSUInteger i=0;i<cells.count;++i){DrawPairwisePDFText(cells[i],NSMakeRect(x,y,widths[i]-2,18),bodyAttrs);x+=widths[i];} y+=19;
    }
    path=[NSBezierPath bezierPath];[path moveToPoint:NSMakePoint(margin,y)];[path lineToPoint:NSMakePoint(pageWidth-margin,y)];[path stroke];y+=8;
    if (!apaStyle && state.showInformationCriteria) {
        y += 8;
        DrawPairwisePDFText(@"Information criteria", NSMakeRect(margin, y, 200, 16), headerAttrs); y += 19;
        NSArray<NSString *> *icHeaders = @[@"Model", @"AIC", @"BIC", @"ΔAIC", @"ΔBIC"];
        std::vector<CGFloat> icWidths = {200, 100, 100, 100, 100};
        double minAIC = INFINITY, minBIC = INFINITY;
        for (const auto &candidate : state.models) {
            if (candidate.fit.ok && std::isfinite(candidate.fit.aic)) minAIC = std::min(minAIC, candidate.fit.aic);
            if (candidate.fit.ok && std::isfinite(candidate.fit.bic)) minBIC = std::min(minBIC, candidate.fit.bic);
        }
        x = margin;
        for (NSUInteger i = 0; i < icHeaders.count; ++i) { DrawPairwisePDFText(icHeaders[i], NSMakeRect(x, y, icWidths[i]-2, 16), headerAttrs); x += icWidths[i]; }
        y += 18;
        for (const auto &candidate : state.models) {
            NSArray<NSString *> *cells = @[SafeNSStringFromUTF8(candidate.label), PairwiseNumberText(candidate.fit.aic, 2),
                PairwiseNumberText(candidate.fit.bic, 2), PairwiseNumberText(candidate.fit.aic - minAIC, 2),
                PairwiseNumberText(candidate.fit.bic - minBIC, 2)];
            x = margin;
            for (NSUInteger i = 0; i < cells.count; ++i) { DrawPairwisePDFText(cells[i], NSMakeRect(x, y, icWidths[i]-2, 18), bodyAttrs); x += icWidths[i]; }
            y += 19;
        }
    }
    NSString *note=[NSString stringWithFormat:@"Note. All models were fitted in R using stats::glm with a binomial distribution and %@ link on the same analysis rows. Likelihood-ratio tests compare each model with the preceding model when the models are nested.",SafeNSStringFromUTF8(state.link)];
    DrawPairwisePDFText(note,NSMakeRect(margin,y,pageWidth-2*margin,40),bodyAttrs);
    [NSGraphicsContext setCurrentContext:nil]; CGContextRestoreGState(context); CGContextEndPage(context); CGContextRelease(context);
}

@implementation GLMPairwiseComparisonPlotView

- (NSString *)snapshotTabDelimitedText
{
    std::ostringstream text;
    text << (_pairedMeanDifferences ? "Paired mean differences" : "Pairwise differences")
         << " — " << _term
         << "\nComparison\tEstimate\tCI lower\tCI upper\tp";
    for (const rlispstat::core::LinearFunctionEstimate &row : _rows) {
        text << '\n' << row.label << '\t' << row.estimate << '\t'
             << row.ciLower << '\t' << row.ciUpper << '\t' << row.adjustedPValue;
    }
    return ToNSString(text.str());
}

- (BOOL)isFlipped
{
    return YES;
}

- (instancetype)initWithTerm:(const std::string &)term
                        rows:(const std::vector<rlispstat::core::LinearFunctionEstimate> &)rows
                    plotLink:(const GLMPairwiseComparisonPlotLink &)plotLink
{
    const CGFloat height = std::max((CGFloat)220.0, 100.0 + (CGFloat)rows.size() * 32.0);
    self = [super initWithFrame:NSMakeRect(0.0, 0.0, 820.0, height)];
    if (!self) return nil;
    _term = term;
    _group = plotLink.group;
    _rows = rows;
    _rowsByComparison = plotLink.rowsByComparison;
    _gamesHowell = plotLink.gamesHowell;
    _binaryRegression = plotLink.binaryRegression;
    _binaryOddsRatio = plotLink.binaryOddsRatio;
    _pairedMeanDifferences = plotLink.pairedMeanDifferences;
    [self setWantsLayer:YES];
    [self setAutoresizingMask:NSViewWidthSizable];
    return self;
}

- (const std::string &)pairwisePlotGroup
{
    return _group;
}

- (void)refreshPairwisePlotSelection
{
    [self setNeedsDisplay:YES];
}

- (NSInteger)comparisonAtPoint:(NSPoint)point
{
    const CGFloat top = 38.0;
    const CGFloat rowHeight = 32.0;
    NSInteger row = (NSInteger)std::floor((point.y - top) / rowHeight);
    return row >= 0 && (std::size_t)row < _rows.size() ? row : -1;
}

- (void)mouseDown:(NSEvent *)event
{
    const NSInteger row = [self comparisonAtPoint:[self convertPoint:[event locationInWindow] fromView:nil]];
    if (row < 0 || (std::size_t)row >= _rowsByComparison.size() ||
        _rowsByComparison[(std::size_t)row].empty() || _group.empty()) return;
    const NSEventModifierFlags flags = [event modifierFlags];
    const std::string mode = rlispstat::core::EffectiveSelectionModeName(
        (flags & NSEventModifierFlagOption) != 0,
        (flags & NSEventModifierFlagCommand) != 0,
        (flags & NSEventModifierFlagControl) != 0,
        (flags & NSEventModifierFlagShift) != 0,
        "replace");
    int selectionVersion = 0;
    if (MergeSelection(_group, _rowsByComparison[(std::size_t)row], mode, &selectionVersion)) {
        const std::set<int> &selected = _rowsByComparison[(std::size_t)row];
        PublishSpreadPlotMessage("ROW_SELECTION_CHANGED", _group,
                                 _pairedMeanDifferences ? "compare-means" : "glm-pairwise", "",
                                 std::vector<int>(selected.begin(), selected.end()), selectionVersion);
    }
    [self setNeedsDisplay:YES];
}

- (void)selectForestComparison:(id)sender
{
    const NSInteger row = [[sender representedObject] integerValue];
    if (row < 0 || static_cast<std::size_t>(row) >= _rowsByComparison.size()) return;
    const std::set<int> &rows = _rowsByComparison[static_cast<std::size_t>(row)];
    if (rows.empty()) return;
    int selectionVersion = 0;
    bool changed = false;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        changed = SetGroupSelectionUnlocked(_group, rows, &selectionVersion);
    }
    if (changed) {
        PublishSpreadPlotMessage("ROW_SELECTION_CHANGED", _group,
                                 _pairedMeanDifferences ? "compare-means" : "glm-pairwise", "",
                                 std::vector<int>(rows.begin(), rows.end()), selectionVersion);
    }
}

- (void)copyForestPlot:(id)sender
{
    NSString *format = [sender representedObject] ?: @"PDF";
    NSPasteboard *pasteboard = [NSPasteboard generalPasteboard];
    [pasteboard clearContents];
    if ([format isEqualToString:@"SVG"]) {
        const std::string source = ComposeSvgExportForView(self, [self forestSvgDocument]);
        NSData *data = [NSData dataWithBytes:source.data() length:source.size()];
        [pasteboard setData:data forType:@"public.svg-image"];
        [pasteboard setString:ToNSString(source) forType:NSPasteboardTypeString];
    } else if ([format isEqualToString:@"PNG"]) {
        [pasteboard setData:VisualExportDataForView(self, @"PNG") forType:NSPasteboardTypePNG];
    } else {
        [pasteboard setData:VisualExportDataForView(self, @"PDF") forType:NSPasteboardTypePDF];
    }
}

- (void)saveForestPlot:(id)sender
{
    NSString *format = [sender representedObject];
    NSSavePanel *panel = [NSSavePanel savePanel];
    NSString *extension = [format lowercaseString];
    [panel setAllowedFileTypes:@[extension]];
    [panel setNameFieldStringValue:[NSString stringWithFormat:@"%@.%@",
        _pairedMeanDifferences ? @"paired-mean-differences" : @"pairwise-differences", extension]];
    if ([panel runModal] != NSModalResponseOK) return;
    if ([format isEqualToString:@"SVG"]) {
        const std::string source = ComposeSvgExportForView(self, [self forestSvgDocument]);
        NSData *data = [NSData dataWithBytes:source.data() length:source.size()];
        [data writeToURL:[panel URL] atomically:YES];
    } else {
        SaveViewToPath(self, [panel URL].path, format ? [format UTF8String] : "PDF");
    }
}

- (std::string)forestSvgDocument
{
    const NSRect bounds = [self bounds];
    rlispstat::core::SvgWriter svg({bounds.size.width, bounds.size.height, 2.0});
    const auto style = rlispstat::core::PlotThemeStyleForName(MacCommandDispatcher().plotTheme());
    auto hex = [](const rlispstat::core::PlotRGBA &color) {
        char buffer[16];
        std::snprintf(buffer, sizeof(buffer), "#%02X%02X%02X",
            (int)std::llround(std::max(0.0, std::min(1.0, color.r)) * 255.0),
            (int)std::llround(std::max(0.0, std::min(1.0, color.g)) * 255.0),
            (int)std::llround(std::max(0.0, std::min(1.0, color.b)) * 255.0));
        return std::string(buffer);
    };
    svg.rectangle(0, 0, bounds.size.width, bounds.size.height,
                  {hex(style.background), "none", 0, 1, {}});
    if (_rows.empty()) return svg.finish();
    const CGFloat labelWidth = 220.0;
    const CGFloat top = 38.0;
    const CGFloat rowHeight = 32.0;
    const NSRect plotRect = NSMakeRect(labelWidth + 14.0, top,
        std::max((CGFloat)80.0, bounds.size.width - labelWidth - 42.0),
        std::max((CGFloat)24.0, (CGFloat)_rows.size() * rowHeight));
    svg.rectangle(plotRect.origin.x, plotRect.origin.y, plotRect.size.width, plotRect.size.height,
                  {hex(style.panel), "none", 0, 1, {}});
    double minimum = _binaryOddsRatio ? 1.0 : 0.0;
    double maximum = minimum;
    for (const auto &row : _rows) {
        minimum = std::min(minimum, std::min(row.estimate, row.ciLower));
        maximum = std::max(maximum, std::max(row.estimate, row.ciUpper));
    }
    if (!std::isfinite(minimum) || !std::isfinite(maximum) || maximum <= minimum) {
        minimum = -1.0; maximum = 1.0;
    }
    const double padding = std::max(0.1, (maximum - minimum) * 0.08);
    minimum -= padding; maximum += padding;
    auto xForValue = [&](double value) {
        return plotRect.origin.x + (value - minimum) / (maximum - minimum) * plotRect.size.width;
    };
    rlispstat::core::SvgTextStyle titleText{hex(style.text), "Arial, Helvetica, sans-serif", 15, 600, false, "start"};
    rlispstat::core::SvgTextStyle labelText{hex(style.text), "Arial, Helvetica, sans-serif", 12, 500, false, "start"};
    rlispstat::core::SvgTextStyle tickText{hex(style.mutedText), "Arial, Helvetica, sans-serif", 10, 400, false, "middle"};
    svg.text(14, 25, (_pairedMeanDifferences ? "Paired mean differences — " : "Pairwise differences — ") + _term, titleText);
    for (int tick = 0; tick <= 5; ++tick) {
        const double x = plotRect.origin.x + plotRect.size.width * tick / 5.0;
        svg.line(x, plotRect.origin.y, x, NSMaxY(plotRect),
                 {"none", hex(style.majorGrid), 1, 1, {}});
        const double value = minimum + (maximum - minimum) * tick / 5.0;
        std::ostringstream label; label << std::setprecision(3) << value;
        svg.text(x, NSMaxY(plotRect) + 17, label.str(), tickText);
    }
    svg.line(plotRect.origin.x, NSMaxY(plotRect), NSMaxX(plotRect), NSMaxY(plotRect),
             {"none", hex(style.axis), 1.2, 1, {}});
    const double reference = _binaryOddsRatio ? 1.0 : 0.0;
    svg.line(xForValue(reference), plotRect.origin.y, xForValue(reference), NSMaxY(plotRect),
             {"none", hex(style.axis), 1.2, 1, {4, 3}});
    svg.beginClipRect(plotRect.origin.x, plotRect.origin.y, plotRect.size.width, plotRect.size.height);
    for (std::size_t index = 0; index < _rows.size(); ++index) {
        const auto &row = _rows[index];
        const double y = top + rowHeight * index + rowHeight / 2.0;
        svg.line(xForValue(row.ciLower), y, xForValue(row.ciUpper), y,
                 {"none", hex(style.geomStroke), 1.4, 1, {}});
        svg.line(xForValue(row.ciLower), y - 4, xForValue(row.ciLower), y + 4,
                 {"none", hex(style.geomStroke), 1.4, 1, {}});
        svg.line(xForValue(row.ciUpper), y - 4, xForValue(row.ciUpper), y + 4,
                 {"none", hex(style.geomStroke), 1.4, 1, {}});
        svg.ellipse(xForValue(row.estimate), y, 4, 4,
                    {hex(style.geomFill), hex(style.geomStroke), 1, 1, {}});
    }
    svg.endClip();
    for (std::size_t index = 0; index < _rows.size(); ++index) {
        std::string label = _rows[index].label;
        std::size_t found = 0;
        while ((found = label.find(" - ", found)) != std::string::npos) {
            label.replace(found, 3, " − "); found += 3;
        }
        svg.text(14, top + rowHeight * index + rowHeight / 2.0 + 4, label, labelText);
    }
    return svg.finish();
}

- (void)copyForestComparisonValues:(id)sender
{
    const NSInteger row = [[sender representedObject] integerValue];
    if (row < 0 || static_cast<std::size_t>(row) >= _rows.size()) return;
    const rlispstat::core::LinearFunctionEstimate &value = _rows[static_cast<std::size_t>(row)];
    NSString *text = [NSString stringWithFormat:@"%@\nEstimate: %@\n95%% CI: [%@, %@]\n%@: %@",
        [SafeNSStringFromUTF8(value.label) stringByReplacingOccurrencesOfString:@" - " withString:@" − "],
        PairwiseNumberText(value.estimate, 4), PairwiseNumberText(value.ciLower, 4),
        PairwiseNumberText(value.ciUpper, 4), _pairedMeanDifferences ? @"p" : @"Adjusted p",
        PairwisePValueText(value.adjustedPValue)];
    NSPasteboard *pasteboard = [NSPasteboard generalPasteboard];
    [pasteboard clearContents];
    [pasteboard setString:text forType:NSPasteboardTypeString];
}

- (void)clearForestSelection:(id)sender
{
    (void)sender;
    int selectionVersion = 0;
    bool changed = false;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        changed = ClearGroupSelectionUnlocked(_group, &selectionVersion);
    }
    if (changed) PublishSpreadPlotMessage("ROW_SELECTION_CHANGED", _group,
        _pairedMeanDifferences ? "compare-means" : "glm-pairwise", "", {}, selectionVersion);
}

- (void)rightMouseDown:(NSEvent *)event
{
    const NSInteger row = [self comparisonAtPoint:[self convertPoint:[event locationInWindow] fromView:nil]];
    NSMenu *menu = [[NSMenu alloc] initWithTitle:_pairedMeanDifferences ? @"Paired comparison" : @"Pairwise comparison"];
    const BOOL hasComparison = row >= 0;
    NSMenuItem *select = [[NSMenuItem alloc] initWithTitle:_pairedMeanDifferences ? @"Select paired observations" : @"Select comparison" action:@selector(selectForestComparison:) keyEquivalent:@""];
    [select setRepresentedObject:@(row)]; [select setTarget:self]; [select setEnabled:hasComparison]; [menu addItem:select];
    NSMenuItem *selectRows = [[NSMenuItem alloc] initWithTitle:_pairedMeanDifferences ? @"Select observations used by this pair" : @"Select observations from both levels" action:@selector(selectForestComparison:) keyEquivalent:@""];
    [selectRows setRepresentedObject:@(row)]; [selectRows setTarget:self]; [selectRows setEnabled:hasComparison]; [menu addItem:selectRows];
    NSMenuItem *clear = [[NSMenuItem alloc] initWithTitle:@"Clear selection" action:@selector(clearForestSelection:) keyEquivalent:@""];
    [clear setTarget:self]; [clear setEnabled:SelectionCount(_group) > 0]; [menu addItem:clear];
    [menu addItem:[NSMenuItem separatorItem]];
    NSMenuItem *exportRoot = [[NSMenuItem alloc] initWithTitle:@"Export" action:nil keyEquivalent:@""];
    NSMenu *exportMenu = [[NSMenu alloc] initWithTitle:@"Export"];
    WindowNotesContainer *notes = WindowNotesContainerForView(self);
    if (notes) {
        NSMenuItem *includeNotes = PlotCommandMenuItem(@"Include Notes", @"NOTES_INCLUDE_EXPORT");
        [includeNotes setEnabled:[notes hasNotes]];
        [includeNotes setState:[notes includeNotes] ? NSControlStateValueOn : NSControlStateValueOff];
        [exportMenu addItem:includeNotes];
        [exportMenu addItem:[NSMenuItem separatorItem]];
    }
    const auto actions = rlispstat::core::BuildExportMenuActions(
        rlispstat::core::StandardVisualExportCapabilities(rlispstat::core::ExportPlatform::MacOS),
        rlispstat::core::ExportPlatform::MacOS);
    for (const auto &action : actions) {
        if (action.separatorBefore) [exportMenu addItem:[NSMenuItem separatorItem]];
        const bool copy = action.identifier.rfind("copy_", 0) == 0;
        NSString *format = action.capability == rlispstat::core::ExportCapability::CopySvg ||
            action.capability == rlispstat::core::ExportCapability::SaveSvg ? @"SVG" :
            (action.capability == rlispstat::core::ExportCapability::CopyPng ||
             action.capability == rlispstat::core::ExportCapability::SavePng ? @"PNG" : @"PDF");
        NSMenuItem *item = [[NSMenuItem alloc] initWithTitle:ToNSString(action.title)
            action:(copy ? @selector(copyForestPlot:) : @selector(saveForestPlot:)) keyEquivalent:@""];
        [item setRepresentedObject:format]; [item setTarget:self]; [exportMenu addItem:item];
    }
    [exportMenu addItem:[NSMenuItem separatorItem]];
    NSMenuItem *copyValues = [[NSMenuItem alloc] initWithTitle:@"Copy comparison values" action:@selector(copyForestComparisonValues:) keyEquivalent:@""];
    [copyValues setRepresentedObject:@(row)]; [copyValues setTarget:self]; [copyValues setEnabled:hasComparison]; [exportMenu addItem:copyValues];
    [exportRoot setSubmenu:exportMenu]; [menu addItem:exportRoot];
    [menu addItem:[NSMenuItem separatorItem]];
    AddPlotThemeSubmenu(menu);
    AddSnapshotAlbumContextItems(menu);
    [NSMenu popUpContextMenu:menu withEvent:event forView:self];
}

- (void)drawRect:(NSRect)dirtyRect
{
    (void)dirtyRect;
    PlotThemeStyle theme = CurrentPlotThemeStyle();
    [theme.background setFill];
    NSRectFill([self bounds]);
    if (_rows.empty()) return;

    NSDictionary *labelAttributes = @{
        NSFontAttributeName: [NSFont systemFontOfSize:12.0 weight:NSFontWeightMedium],
        NSForegroundColorAttributeName: theme.text
    };
    CGFloat widestLabel = 0.0;
    for (const rlispstat::core::LinearFunctionEstimate &row : _rows) {
        NSSize labelSize = [SafeNSStringFromUTF8(row.label) sizeWithAttributes:labelAttributes];
        widestLabel = std::max(widestLabel, labelSize.width);
    }
    const CGFloat labelWidth = std::min((CGFloat)300.0, std::max((CGFloat)150.0, widestLabel + 22.0));
    const CGFloat top = 38.0;
    const CGFloat rowHeight = 32.0;
    const NSRect plotRect = NSMakeRect(labelWidth + 14.0, top,
                                       std::max((CGFloat)80.0, NSWidth([self bounds]) - labelWidth - 42.0),
                                       std::max((CGFloat)24.0, (CGFloat)_rows.size() * rowHeight));
    [theme.panel setFill];
    NSRectFill(plotRect);

    const double referenceValue = _binaryOddsRatio ? 1.0 : 0.0;
    double minimum = referenceValue;
    double maximum = referenceValue;
    for (const rlispstat::core::LinearFunctionEstimate &row : _rows) {
        minimum = std::min(minimum, std::min(row.estimate, row.ciLower));
        maximum = std::max(maximum, std::max(row.estimate, row.ciUpper));
    }
    if (!std::isfinite(minimum) || !std::isfinite(maximum) || maximum <= minimum) {
        minimum = -1.0;
        maximum = 1.0;
    }
    const double padding = std::max(0.1, (maximum - minimum) * 0.08);
    minimum -= padding;
    maximum += padding;
    const auto xForValue = [&](double value) {
        return plotRect.origin.x + (CGFloat)((value - minimum) / (maximum - minimum) * plotRect.size.width);
    };

    NSDictionary *titleAttributes = @{
        NSFontAttributeName: [NSFont systemFontOfSize:15.0 weight:NSFontWeightSemibold],
        NSForegroundColorAttributeName: theme.text
    };
    NSDictionary *tickAttributes = @{
        NSFontAttributeName: [NSFont systemFontOfSize:10.0],
        NSForegroundColorAttributeName: theme.mutedText
    };
    [SafeNSStringFromUTF8((_pairedMeanDifferences ? "Paired mean differences — " : "Pairwise differences — ") + _term)
        drawAtPoint:NSMakePoint(14.0, 14.0) withAttributes:titleAttributes];

    NSBezierPath *grid = [NSBezierPath bezierPath];
    for (int tick = 0; tick <= 5; ++tick) {
        const CGFloat x = plotRect.origin.x + plotRect.size.width * tick / 5.0;
        [grid moveToPoint:NSMakePoint(x, plotRect.origin.y)];
        [grid lineToPoint:NSMakePoint(x, NSMaxY(plotRect))];
        const double value = minimum + (maximum - minimum) * tick / 5.0;
        NSString *text = [NSString stringWithFormat:@"%.3g", value];
        NSSize size = [text sizeWithAttributes:tickAttributes];
        [text drawAtPoint:NSMakePoint(x - size.width / 2.0, NSMaxY(plotRect) + 7.0) withAttributes:tickAttributes];
    }
    [theme.majorGrid setStroke];
    [grid setLineWidth:1.0];
    [grid stroke];
    NSBezierPath *axis = [NSBezierPath bezierPath];
    [axis moveToPoint:NSMakePoint(plotRect.origin.x, NSMaxY(plotRect))];
    [axis lineToPoint:NSMakePoint(NSMaxX(plotRect), NSMaxY(plotRect))];
    [theme.axis setStroke];
    [axis setLineWidth:1.2];
    [axis stroke];

    const CGFloat zeroX = xForValue(referenceValue);
    if (zeroX >= plotRect.origin.x && zeroX <= NSMaxX(plotRect)) {
        NSBezierPath *zero = [NSBezierPath bezierPath];
        [zero moveToPoint:NSMakePoint(zeroX, plotRect.origin.y)];
        [zero lineToPoint:NSMakePoint(zeroX, NSMaxY(plotRect))];
        CGFloat dashes[] = {4.0, 3.0};
        [zero setLineDash:dashes count:2 phase:0.0];
        [(theme.coordinatedMarks ? theme.reference : theme.axis) setStroke];
        [zero setLineWidth:1.2];
        [zero stroke];
    }

    std::set<int> selection;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        auto it = g_groupSelections.find(_group);
        if (it != g_groupSelections.end()) selection = it->second;
    }
    for (std::size_t index = 0; index < _rows.size(); ++index) {
        const rlispstat::core::LinearFunctionEstimate &row = _rows[index];
        const CGFloat y = top + rowHeight * index + rowHeight / 2.0;
        const bool selected = index < _rowsByComparison.size() && !_rowsByComparison[index].empty() &&
            _rowsByComparison[index] == selection;
        if (selected) {
            [(theme.coordinatedMarks ? [theme.selectedMarkFill colorWithAlphaComponent:0.12] :
                [NSColor colorWithCalibratedWhite:0.93 alpha:1.0]) setFill];
            NSRectFill(NSMakeRect(0.0, top + rowHeight * index, NSWidth([self bounds]), rowHeight));
        }
        NSString *label = [SafeNSStringFromUTF8(row.label) stringByReplacingOccurrencesOfString:@" - " withString:@" − "];
        [label drawInRect:NSMakeRect(14.0, y - 8.0, labelWidth - 12.0, 17.0) withAttributes:labelAttributes];
        const CGFloat low = xForValue(row.ciLower);
        const CGFloat high = xForValue(row.ciUpper);
        NSColor *color = selected && theme.coordinatedMarks ? theme.selectedMarkFill :
            (selected ? theme.accent : theme.geomStroke);
        [color setStroke];
        NSBezierPath *interval = [NSBezierPath bezierPath];
        [interval moveToPoint:NSMakePoint(low, y)];
        [interval lineToPoint:NSMakePoint(high, y)];
        [interval moveToPoint:NSMakePoint(low, y - 4.0)];
        [interval lineToPoint:NSMakePoint(low, y + 4.0)];
        [interval moveToPoint:NSMakePoint(high, y - 4.0)];
        [interval lineToPoint:NSMakePoint(high, y + 4.0)];
        [interval setLineWidth:selected ? 2.2 : 1.4];
        [interval stroke];
        [(selected && theme.coordinatedMarks ? theme.selectedMarkFill :
            (selected ? theme.accent : theme.geomFill)) setFill];
        const CGFloat radius = selected ? 5.0 : 4.0;
        [[NSBezierPath bezierPathWithOvalInRect:NSMakeRect(xForValue(row.estimate) - radius, y - radius, radius * 2.0, radius * 2.0)] fill];
    }
    [(_pairedMeanDifferences
        ? @"Mean difference (first variable − second variable)"
        : (_binaryRegression
        ? (_binaryOddsRatio ? @"Odds ratio (first level / second level)" : @"Probability difference (first level − second level)")
        : (_gamesHowell ? @"Mean difference (first level − second level)" : @"Estimated marginal mean difference (first level − second level)")))
        drawAtPoint:NSMakePoint(plotRect.origin.x, NSMaxY(plotRect) + 25.0)
                                               withAttributes:tickAttributes];
    [(_pairedMeanDifferences
        ? @"Click a pair to select its complete observations. Command-click combines selections."
        : @"Click a comparison to select observations from both levels. Command-click combines selections.")
        drawAtPoint:NSMakePoint(14.0, NSMaxY(plotRect) + 44.0) withAttributes:tickAttributes];
}
@end

@implementation GLMPairwiseObservedBoxplotView
- (BOOL)isFlipped
{
    return YES;
}

- (instancetype)initWithPlotLink:(const GLMPairwiseComparisonPlotLink &)plotLink
{
    self = [super initWithFrame:NSMakeRect(0.0, 0.0, 460.0, 260.0)];
    if (!self) return nil;
    _plotLink = plotLink;
    [self setAutoresizingMask:NSViewWidthSizable | NSViewHeightSizable];
    return self;
}

- (const std::string &)pairwisePlotGroup
{
    return _plotLink.group;
}

- (void)refreshPairwisePlotSelection
{
    [self setNeedsDisplay:YES];
}

- (NSInteger)levelAtPoint:(NSPoint)point
{
    const CGFloat left = 54.0, right = 18.0;
    const CGFloat width = NSWidth([self bounds]) - left - right;
    if (_plotLink.levels.empty() || point.x < left || point.x > left + width) return -1;
    const CGFloat slot = width / _plotLink.levels.size();
    const NSInteger level = static_cast<NSInteger>((point.x - left) / slot);
    return level >= 0 && static_cast<std::size_t>(level) < _plotLink.levels.size() ? level : -1;
}

- (void)selectLevel:(id)sender
{
    const NSInteger index = [[sender representedObject] integerValue];
    if (index < 0 || static_cast<std::size_t>(index) >= _plotLink.levels.size()) return;
    const std::set<int> &rows = _plotLink.rowsByLevel[_plotLink.levels[static_cast<std::size_t>(index)]];
    if (rows.empty()) return;
    const NSEventModifierFlags flags = [[NSApp currentEvent] modifierFlags];
    const std::string mode = rlispstat::core::EffectiveSelectionModeName(
        (flags & NSEventModifierFlagOption) != 0, (flags & NSEventModifierFlagCommand) != 0,
        (flags & NSEventModifierFlagControl) != 0, (flags & NSEventModifierFlagShift) != 0, "replace");
    int selectionVersion = 0;
    bool changed = false;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        changed = (mode == "replace")
            ? SetGroupSelectionUnlocked(_plotLink.group, rows, &selectionVersion)
            : MergeGroupSelectionUnlocked(_plotLink.group, rows, mode, &selectionVersion);
    }
    if (changed) PublishSpreadPlotMessage("ROW_SELECTION_CHANGED", _plotLink.group, "glm-pairwise", "",
                                           std::vector<int>(rows.begin(), rows.end()), selectionVersion);
}

- (void)clearBoxplotSelection:(id)sender
{
    (void)sender;
    int selectionVersion = 0;
    bool changed = false;
    { std::lock_guard<std::mutex> lock(g_mutex); changed = ClearGroupSelectionUnlocked(_plotLink.group, &selectionVersion); }
    if (changed) PublishSpreadPlotMessage("ROW_SELECTION_CHANGED", _plotLink.group, "glm-pairwise", "", {}, selectionVersion);
}

- (void)copyBoxplot:(id)sender
{
    (void)sender;
    NSPasteboard *pasteboard = [NSPasteboard generalPasteboard];
    [pasteboard clearContents];
    [pasteboard setData:VisualExportDataForView(self, @"PDF") forType:NSPasteboardTypePDF];
}

- (void)saveBoxplot:(id)sender
{
    NSString *format = [sender representedObject];
    NSString *extension = [format isEqualToString:@"PNG"] ? @"png" : @"pdf";
    NSSavePanel *panel = [NSSavePanel savePanel];
    [panel setAllowedFileTypes:@[extension]];
    [panel setNameFieldStringValue:[NSString stringWithFormat:@"distribution-by-%@.%@", SafeNSStringFromUTF8(_plotLink.factor), extension]];
    if ([panel runModal] == NSModalResponseOK) SaveViewToPath(self, [panel URL].path, format ? [format UTF8String] : "PDF");
}

- (void)mouseDown:(NSEvent *)event
{
    const NSInteger level = [self levelAtPoint:[self convertPoint:[event locationInWindow] fromView:nil]];
    if (level < 0) return;
    NSMenuItem *item = [[NSMenuItem alloc] init];
    [item setRepresentedObject:@(level)];
    [self selectLevel:item];
}

- (void)rightMouseDown:(NSEvent *)event
{
    // This legacy view is no longer instantiated. Observed pairwise data are
    // opened as the standard linked BoxplotView, whose Export submenu is built
    // by AddStandardPlotExportItems and includes SVG/PDF/PNG consistently.
    [super rightMouseDown:event];
}

- (void)drawRect:(NSRect)dirtyRect
{
    (void)dirtyRect;
    PlotThemeStyle theme = CurrentPlotThemeStyle();
    [theme.background setFill]; NSRectFill([self bounds]);
    if (_plotLink.levels.empty() || _plotLink.observations.empty()) return;
    const CGFloat left = 54.0, right = 18.0, top = 38.0, bottom = 50.0;
    const NSRect plot = NSMakeRect(left, top, std::max((CGFloat)80.0, NSWidth([self bounds]) - left - right),
                                   std::max((CGFloat)80.0, NSHeight([self bounds]) - top - bottom));
    [theme.panel setFill]; NSRectFill(plot);
    double ymin = INFINITY, ymax = -INFINITY;
    std::map<std::string, std::vector<double>> values;
    for (const auto &observation : _plotLink.observations) {
        values[observation.level].push_back(observation.response);
        ymin = std::min(ymin, observation.response); ymax = std::max(ymax, observation.response);
    }
    if (!(ymax > ymin)) { ymin -= 1.0; ymax += 1.0; }
    const double pad = (ymax - ymin) * 0.07; ymin -= pad; ymax += pad;
    const auto yFor = [&](double value) { return plot.origin.y + (CGFloat)((ymax - value) / (ymax - ymin) * plot.size.height); };
    NSDictionary *titleAttrs = @{ NSFontAttributeName: [NSFont systemFontOfSize:13 weight:NSFontWeightSemibold], NSForegroundColorAttributeName: theme.text };
    NSDictionary *labelAttrs = @{ NSFontAttributeName: [NSFont systemFontOfSize:10], NSForegroundColorAttributeName: theme.mutedText };
    [SafeNSStringFromUTF8("Distribution of " + _plotLink.response + " by " + _plotLink.factor) drawAtPoint:NSMakePoint(14, 14) withAttributes:titleAttrs];
    for (int tick = 0; tick <= 4; ++tick) {
        const double value = ymin + (ymax - ymin) * tick / 4.0;
        const CGFloat y = yFor(value);
        NSBezierPath *line = [NSBezierPath bezierPath]; [line moveToPoint:NSMakePoint(NSMinX(plot), y)]; [line lineToPoint:NSMakePoint(NSMaxX(plot), y)];
        [theme.majorGrid setStroke]; [line setLineWidth:0.8]; [line stroke];
        NSString *label = [NSString stringWithFormat:@"%.3g", value]; NSSize size = [label sizeWithAttributes:labelAttrs];
        [label drawAtPoint:NSMakePoint(left - size.width - 6.0, y - size.height / 2.0) withAttributes:labelAttrs];
    }
    std::set<int> selection;
    { std::lock_guard<std::mutex> lock(g_mutex); auto it = g_groupSelections.find(_plotLink.group); if (it != g_groupSelections.end()) selection = it->second; }
    const CGFloat slot = plot.size.width / _plotLink.levels.size();
    for (std::size_t index = 0; index < _plotLink.levels.size(); ++index) {
        const std::string &level = _plotLink.levels[index];
        std::vector<double> sorted = values[level];
        if (sorted.empty()) continue;
        std::sort(sorted.begin(), sorted.end());
        const double q1 = BoxplotQuantileSorted(sorted, 0.25), med = BoxplotQuantileSorted(sorted, 0.5), q3 = BoxplotQuantileSorted(sorted, 0.75);
        const double fenceLow = q1 - 1.5 * (q3 - q1), fenceHigh = q3 + 1.5 * (q3 - q1);
        double low = sorted.front(), high = sorted.back();
        for (double value : sorted) if (value >= fenceLow) { low = value; break; }
        for (auto it = sorted.rbegin(); it != sorted.rend(); ++it) if (*it <= fenceHigh) { high = *it; break; }
        const CGFloat cx = plot.origin.x + slot * ((CGFloat)index + 0.5), width = std::min((CGFloat)64.0, slot * 0.52);
        const std::set<int> &levelRows = _plotLink.rowsByLevel[level];
        const bool active = !levelRows.empty() && std::any_of(levelRows.begin(), levelRows.end(), [&](int row) { return selection.count(row) != 0; });
        const CGFloat alpha = selection.empty() || active ? 0.36 : 0.12;
        [[theme.geomFill colorWithAlphaComponent:alpha] setFill];
        NSRect box = NSMakeRect(cx - width / 2.0, yFor(q3), width, std::max((CGFloat)1.0, yFor(q1) - yFor(q3))); NSRectFill(box);
        [(active ? theme.accent : theme.geomStroke) setStroke]; NSFrameRectWithWidth(box, active ? 2.0 : 1.0);
        NSBezierPath *whisker = [NSBezierPath bezierPath];
        [whisker moveToPoint:NSMakePoint(cx, yFor(high))]; [whisker lineToPoint:NSMakePoint(cx, yFor(q3))];
        [whisker moveToPoint:NSMakePoint(cx, yFor(q1))]; [whisker lineToPoint:NSMakePoint(cx, yFor(low))];
        [whisker moveToPoint:NSMakePoint(cx - width * .25, yFor(high))]; [whisker lineToPoint:NSMakePoint(cx + width * .25, yFor(high))];
        [whisker moveToPoint:NSMakePoint(cx - width * .25, yFor(low))]; [whisker lineToPoint:NSMakePoint(cx + width * .25, yFor(low))];
        [whisker setLineWidth:active ? 1.8 : 1.2]; [whisker stroke];
        NSBezierPath *median = [NSBezierPath bezierPath]; [median moveToPoint:NSMakePoint(cx - width / 2.0, yFor(med))]; [median lineToPoint:NSMakePoint(cx + width / 2.0, yFor(med))]; [theme.accent setStroke]; [median setLineWidth:1.8]; [median stroke];
        for (const auto &observation : _plotLink.observations) if (observation.level == level) {
            const CGFloat jitter = ((observation.row * 37) % 17 - 8) * 0.55;
            const bool rowSelected = selection.count(observation.row) != 0;
            [(rowSelected ? theme.accent : theme.geomStroke) setFill];
            [[NSBezierPath bezierPathWithOvalInRect:NSMakeRect(cx + jitter - (rowSelected ? 3.0 : 2.0), yFor(observation.response) - (rowSelected ? 3.0 : 2.0), rowSelected ? 6.0 : 4.0, rowSelected ? 6.0 : 4.0)] fill];
        }
        for (double value : sorted) if (value < low || value > high) {
            [theme.accent2 setStroke]; [[NSBezierPath bezierPathWithOvalInRect:NSMakeRect(cx - 3.0, yFor(value) - 3.0, 6.0, 6.0)] stroke];
        }
        NSString *category = SafeNSStringFromUTF8(level); NSSize categorySize = [category sizeWithAttributes:labelAttrs];
        [category drawAtPoint:NSMakePoint(cx - categorySize.width / 2.0, NSMaxY(plot) + 8.0) withAttributes:labelAttrs];
    }
    [SafeNSStringFromUTF8(_plotLink.response) drawAtPoint:NSMakePoint(5.0, top + 4.0) withAttributes:labelAttrs];
}
@end

static void ShowGLMPairwiseObservedBoxplotOnMain(const GLMPairwiseComparisonPlotLink &plotLink)
{
    const GLMPairwiseComparisonPlotLink linkCopy = plotLink;
    dispatch_async(dispatch_get_main_queue(), ^{
        if (linkCopy.observations.empty()) return;
        PlotModel *created = new PlotModel();
        created->kind = "boxplot";
        created->id = "boxplot_pairwise_" + std::to_string((long long)time(nullptr)) +
            "_" + std::to_string(std::rand() % 1000000);
        created->group = linkCopy.group;
        created->xLabel = linkCopy.factor;
        created->yLabel = linkCopy.response;
        created->title = "Distribution of " + linkCopy.response + " by " + linkCopy.factor;
        created->interactionMode = "select";
        created->selectionMode = "replace";
        created->boxplotCategories = linkCopy.levels;
        created->boxplotDefinedCategories = created->boxplotCategories;
        for (const GLMPairwiseComparisonPlotLink::Observation &observation : linkCopy.observations) {
            if (observation.row > 0 && std::isfinite(observation.response)) {
                created->boxplotPoints.push_back(
                    BoxplotPoint{observation.response, observation.level, observation.row});
            }
        }
        if (created->boxplotPoints.empty()) {
            delete created;
            return;
        }
        EnsureParallelBoxplotState(created);
        {
            std::lock_guard<std::mutex> lock(g_mutex);
            for (const auto &entry : g_plots) {
                PlotModel *source = entry.second;
                if (source && source->group == linkCopy.group) {
                    created->variables = source->variables;
                    created->variableMeta = source->variableMeta;
                    break;
                }
            }
            if (!AttachPlotModelUnlocked(created)) {
                delete created;
                return;
            }
        }
        AddPlotOnMain(created);
    });
}

static void ShowGLMPairwiseComparisonPlotOnMain(
    const std::string &term,
    const std::vector<rlispstat::core::LinearFunctionEstimate> &rows,
    const GLMPairwiseComparisonPlotLink &plotLink)
{
    const std::string termCopy = term;
    const std::vector<rlispstat::core::LinearFunctionEstimate> rowsCopy = rows;
    const GLMPairwiseComparisonPlotLink linkCopy = plotLink;
    dispatch_async(dispatch_get_main_queue(), ^{
        static NSMutableArray *retainedPairwisePlotWindows = nil;
        if (!retainedPairwisePlotWindows) retainedPairwisePlotWindows = [[NSMutableArray alloc] init];
        const CGFloat visibleHeight = std::min((CGFloat)620.0,
            std::max((CGFloat)260.0, 110.0 + (CGFloat)rowsCopy.size() * 32.0));
        NSWindow *window = [[NSWindow alloc] initWithContentRect:NextWindowFrameOnMain(820.0, visibleHeight)
                                                       styleMask:(NSWindowStyleMaskTitled | NSWindowStyleMaskClosable | NSWindowStyleMaskResizable)
                                                         backing:NSBackingStoreBuffered
                                                           defer:NO];
        [window setTitle:SafeNSStringFromUTF8(
            (linkCopy.pairedMeanDifferences ? "Paired mean differences — " : "Pairwise comparison plot — ") + termCopy)];
        [window setReleasedWhenClosed:NO];
        [window setContentMinSize:NSMakeSize(620.0, 260.0)];
        [window setContentMaxSize:NSMakeSize(1280.0, 760.0)];
        GLMPairwiseComparisonPlotView *plot = [[GLMPairwiseComparisonPlotView alloc]
            initWithTerm:termCopy rows:rowsCopy plotLink:linkCopy];
        NSScrollView *scroll = [[NSScrollView alloc] initWithFrame:[[window contentView] bounds]];
        [scroll setAutoresizingMask:NSViewWidthSizable | NSViewHeightSizable];
        [scroll setBorderType:NSNoBorder];
        [scroll setDrawsBackground:NO];
        [scroll setHasVerticalScroller:YES];
        [scroll setAutohidesScrollers:YES];
        [scroll setDocumentView:plot];
        [window setContentView:scroll];
        [retainedPairwisePlotWindows addObject:window];
        {
            std::lock_guard<std::mutex> lock(g_mutex);
            g_pairwiseComparisonPlotViews.push_back(plot);
        }
        [[NSNotificationCenter defaultCenter] addObserverForName:NSWindowWillCloseNotification
                                                          object:window
                                                           queue:[NSOperationQueue mainQueue]
                                                      usingBlock:^(NSNotification *note) {
            {
                std::lock_guard<std::mutex> lock(g_mutex);
                g_pairwiseComparisonPlotViews.erase(
                    std::remove(g_pairwiseComparisonPlotViews.begin(), g_pairwiseComparisonPlotViews.end(), plot),
                    g_pairwiseComparisonPlotViews.end());
            }
            [retainedPairwisePlotWindows removeObject:window];
            (void)note;
        }];
        [NSApp activateIgnoringOtherApps:YES];
        EnableNotesForWindow(window, "", @"this comparison graph");
        [window makeKeyAndOrderFront:nil];
        [window makeFirstResponder:plot];
    });
}

static GLMPairwiseComparisonPlotLink BuildGLMPairwiseComparisonPlotLink(
    const std::string &group,
    const DataFrameModel &dataframe,
    const std::string &response,
    const std::string &term,
    const std::vector<int> &rowsUsed,
    const rlispstat::core::GLMPairwiseComparisonResult &result)
{
    GLMPairwiseComparisonPlotLink link;
    link.group = group;
    link.response = response;
    link.factor = term;
    link.method = result.method;
    link.gamesHowell = result.adjustment == "Games-Howell";
    link.casesAnalysed = static_cast<int>(rowsUsed.size());
    link.casesExcluded = std::max(0, dataframe.rows - link.casesAnalysed);
    link.levels = result.levels;
    link.rowsByComparison.resize(result.comparisons.size());
    const DataColumn *factorColumn = FindDataColumnInDataFrame(dataframe, term);
    const DataColumn *responseColumn = FindDataColumnInDataFrame(dataframe, response);
    if (!factorColumn || !responseColumn) return link;

    // Model and ApplicationState case identifiers are 1-based.  Preserve that
    // identity instead of treating them as indices into DataColumn::values.
    for (int caseId : rowsUsed) {
        if (caseId <= 0) continue;
        const std::size_t index = static_cast<std::size_t>(caseId - 1);
        if (index >= factorColumn->values.size() || index >= responseColumn->values.size()) continue;
        const std::string &level = factorColumn->values[index];
        double value = NAN;
        if (DataCellIsMissing(level) || !ParseDataCellDouble(responseColumn->values[index], value) || !std::isfinite(value)) continue;
        link.rowsByLevel[level].insert(caseId);
        link.observations.push_back({caseId, level, value});
    }

    for (std::size_t comparisonIndex = 0; comparisonIndex < result.comparisons.size(); ++comparisonIndex) {
        const rlispstat::core::LinearFunctionEstimate &comparison = result.comparisons[comparisonIndex];
        auto first = link.rowsByLevel.find(comparison.firstLevel);
        auto second = link.rowsByLevel.find(comparison.secondLevel);
        if (first != link.rowsByLevel.end()) {
            link.rowsByComparison[comparisonIndex].insert(first->second.begin(), first->second.end());
        }
        if (second != link.rowsByLevel.end()) {
            link.rowsByComparison[comparisonIndex].insert(second->second.begin(), second->second.end());
        }
    }
    return link;
}

