static void ShowGLMInteractionReportWindowOnMain(const std::string &title, const std::string &body)
{
    std::string titleCopy = title;
    std::string bodyCopy = body;
    dispatch_async(dispatch_get_main_queue(), ^{
        static NSMutableArray *retainedInteractionWindows = nil;
        if (!retainedInteractionWindows) {
            retainedInteractionWindows = [[NSMutableArray alloc] init];
        }
        NSRect frame = NSMakeRect(180, 180, 760, 520);
        NSWindow *window = [[NSWindow alloc] initWithContentRect:frame
                                                       styleMask:(NSWindowStyleMaskTitled | NSWindowStyleMaskClosable | NSWindowStyleMaskResizable)
                                                         backing:NSBackingStoreBuffered
                                                           defer:NO];
        [window setTitle:SafeNSStringFromUTF8(titleCopy)];
        [window setReleasedWhenClosed:NO];
        NSView *content = [window contentView];
        [content setWantsLayer:YES];
        [[content layer] setBackgroundColor:[[NSColor whiteColor] CGColor]];

        NSString *bodyString = SafeNSStringFromUTF8(bodyCopy);
        if (!bodyString || [bodyString length] == 0) {
            bodyString = ToNSString(rlispstat::core::GLMNoInteractionReportTextStatus());
        }
        NSArray<NSString *> *lines = [bodyString componentsSeparatedByCharactersInSet:[NSCharacterSet newlineCharacterSet]];
        CGFloat documentWidth = 940.0;
        CGFloat documentHeight = 560.0;

        NSScrollView *scroll = [[NSScrollView alloc] initWithFrame:[content bounds]];
        [scroll setAutoresizingMask:NSViewWidthSizable | NSViewHeightSizable];
        [scroll setBorderType:NSNoBorder];
        [scroll setDrawsBackground:YES];
        [scroll setBackgroundColor:[NSColor whiteColor]];
        [scroll setHasVerticalScroller:YES];
        [scroll setHasHorizontalScroller:YES];

        GLMInteractionReportView *reportView =
            [[GLMInteractionReportView alloc] initWithBody:bodyString
                                                     frame:NSMakeRect(0, 0, documentWidth, documentHeight)];
        CGFloat y = 16.0;
        auto addLabel = [&](NSString *text,
                            CGFloat x,
                            CGFloat width,
                            CGFloat height,
                            CGFloat fontSize,
                            NSFontWeight weight,
                            NSTextAlignment alignment) {
            NSTextField *label = InteractionReportLineLabel(text,
                                                            NSMakeRect(x, y, width, height),
                                                            fontSize,
                                                            weight,
                                                            alignment);
            [reportView addSubview:label];
        };
        auto addMetadata = [&](NSString *line) {
            NSRange colon = [line rangeOfString:@":"];
            if (colon.location == NSNotFound) {
                addLabel(line, 16.0, documentWidth - 32.0, 22.0, 12.0, NSFontWeightRegular, NSTextAlignmentLeft);
                y += 22.0;
                return;
            }
            NSString *key = [line substringToIndex:colon.location + 1];
            NSString *value = [[line substringFromIndex:colon.location + 1]
                stringByTrimmingCharactersInSet:[NSCharacterSet whitespaceCharacterSet]];
            addLabel(key, 16.0, 150.0, 20.0, 12.0, NSFontWeightSemibold, NSTextAlignmentLeft);
            addLabel(value, 170.0, documentWidth - 186.0, 20.0, 12.0, NSFontWeightRegular, NSTextAlignmentLeft);
            y += 22.0;
        };
        CGFloat colX[8] = { 16.0, 398.0, 478.0, 548.0, 608.0, 668.0, 748.0, 833.0 };
        CGFloat colW[8] = { 360.0, 70.0, 60.0, 50.0, 50.0, 70.0, 75.0, 75.0 };
        for (NSString *line in lines) {
            if ([line length] == 0) {
                y += 8.0;
                continue;
            }
            if ([line hasPrefix:ToNSString(rlispstat::core::GLMReportInteractionTermPrefix())]) {
                NSString *term = [[line substringFromIndex:[ToNSString(rlispstat::core::GLMReportInteractionTermPrefix()) length]]
                    stringByTrimmingCharactersInSet:[NSCharacterSet whitespaceCharacterSet]];
                addLabel(term, 16.0, documentWidth - 32.0, 24.0, 16.0, NSFontWeightSemibold, NSTextAlignmentLeft);
                y += 30.0;
                continue;
            }
            if ([line hasPrefix:ToNSString(rlispstat::core::GLMReportTypePrefix())] ||
                [line hasPrefix:ToNSString(rlispstat::core::GLMReportConfidenceLevelPrefix())] ||
                [line hasPrefix:ToNSString(rlispstat::core::GLMReportMultipleComparisonsPrefix())]) {
                addMetadata(line);
                continue;
            }
            if ([line hasPrefix:ToNSString(rlispstat::core::GLMReportNotePrefix())]) {
                y += 8.0;
                addLabel(line, 16.0, documentWidth - 32.0, 36.0, 11.0, NSFontWeightRegular, NSTextAlignmentLeft);
                y += 42.0;
                continue;
            }
            NSArray<NSString *> *parts = [line componentsSeparatedByString:@"\t"];
            if ([parts count] > 1) {
                BOOL header = [[parts firstObject] isEqualToString:ToNSString(rlispstat::core::GLMReportEffectHeader())];
                for (NSInteger i = 0; i < 8; ++i) {
                    NSString *cell = i < (NSInteger)[parts count] ? parts[(NSUInteger)i] : @"";
                    NSTextAlignment alignment = i == 0 ? NSTextAlignmentLeft : NSTextAlignmentRight;
                    NSFontWeight weight = header ? NSFontWeightSemibold : NSFontWeightRegular;
                    addLabel(cell, colX[i], colW[i], 18.0, 11.5, weight, alignment);
                }
                y += 20.0;
                if (header) {
                    [reportView addSubview:InteractionReportRule(16.0, y - 1.0, documentWidth - 32.0)];
                    y += 6.0;
                }
                continue;
            }
            y += 8.0;
            addLabel(line, 16.0, documentWidth - 32.0, 20.0, 12.5, NSFontWeightSemibold, NSTextAlignmentLeft);
            y += 22.0;
        }
        documentHeight = std::max((CGFloat)560.0, y + 24.0);
        [reportView setFrameSize:NSMakeSize(documentWidth, documentHeight)];
        [scroll setDocumentView:reportView];
        [[scroll contentView] scrollToPoint:NSMakePoint(0.0, 0.0)];
        [scroll reflectScrolledClipView:[scroll contentView]];
        [content addSubview:scroll];
        [retainedInteractionWindows addObject:window];
        [[NSNotificationCenter defaultCenter] addObserverForName:NSWindowWillCloseNotification
                                                          object:window
                                                           queue:[NSOperationQueue mainQueue]
                                                      usingBlock:^(NSNotification *note) {
            [retainedInteractionWindows removeObject:[note object]];
        }];
        [window center];
        EnableNotesForWindow(window, "", @"this interaction report");
        [window makeKeyAndOrderFront:nil];
    });
}

static bool GLMNumericValueForRow(PlotModel *model, const std::string &variable, int row, double &out)
{
    if (!model || row <= 0) return false;
    size_t index = (size_t)row - 1;
    if (NumericVariable *var = FindVariable(model, variable)) {
        if (index >= var->values.size()) return false;
        out = var->values[index];
        return std::isfinite(out);
    }
    if (const DataColumn *col = FindDataColumnForModel(model, variable)) {
        if (index >= col->values.size()) return false;
        return ParseDataCellDouble(col->values[index], out) && std::isfinite(out);
    }
    return false;
}

static std::string GLMFactorValueForRow(PlotModel *model, const std::string &variable, int row)
{
    if (!model || row <= 0) return "";
    size_t index = (size_t)row - 1;
    if (const DataColumn *col = FindDataColumnForModel(model, variable)) {
        if (index >= col->values.size() || DataCellIsMissing(col->values[index])) return "";
        return col->values[index];
    }
    if (NumericVariable *var = FindVariable(model, variable)) {
        if (index >= var->values.size() || !std::isfinite(var->values[index])) return "";
        return FormatFactorLabel(var->values[index]);
    }
    return "";
}

static void GLMAddObservedInteractionPoints(PlotModel *plot, PlotModel *seed,
                                            const GLMFitSummary &fit,
                                            const std::string &dependent,
                                            const std::string &x,
                                            const std::string &moderator,
                                            const std::string &xType,
                                            const std::string &moderatorType,
                                            const std::vector<std::string> &xLevels,
                                            const std::vector<std::string> &moderatorLevels)
{
    if (!plot || !seed) return;
    std::map<std::string, size_t> xIndex = GLMLevelIndex(xLevels);
    std::map<std::string, size_t> moderatorIndex = GLMLevelIndex(moderatorLevels);
    for (int row : fit.rowsUsed) {
        double y = NAN;
        if (!GLMNumericValueForRow(seed, dependent, row, y)) continue;
        double px = NAN;
        if (xType == "factor") {
            std::string level = GLMFactorValueForRow(seed, x, row);
            auto it = xIndex.find(level);
            if (it == xIndex.end()) continue;
            px = (double)it->second + 1.0;
            if (moderatorType == "factor" && !moderatorLevels.empty()) {
                std::string modLevel = GLMFactorValueForRow(seed, moderator, row);
                auto modIt = moderatorIndex.find(modLevel);
                if (modIt != moderatorIndex.end()) {
                    double centered = (double)modIt->second - ((double)moderatorLevels.size() - 1.0) / 2.0;
                    px += centered * 0.10;
                }
            }
        } else {
            if (!GLMNumericValueForRow(seed, x, row, px)) continue;
        }
        if (std::isfinite(px) && std::isfinite(y)) plot->points.push_back(DataPoint{px, y, row});
    }
}

static bool PopulateGLMInteractionPlot(PlotModel *plot,
                                       PlotModel *seed,
                                       const std::string &dependent,
                                       const std::string &term,
                                       const std::vector<std::string> &terms,
                                       const std::map<std::string, std::string> &termTypes,
                                       const GLMFitSummary &fit,
                                       std::string *message = nullptr)
{
    if (!plot || !seed) {
        if (message) *message = rlispstat::core::GLMNoActiveInteractionDataStatus();
        return false;
    }
    if (!fit.ok) {
        if (message) *message = fit.warning.empty() ? rlispstat::core::GLMInteractionModelNotFittedStatus() : fit.warning;
        return false;
    }
    std::vector<std::string> parts = SplitInteractionTerm(term);
    if (parts.size() != 2) {
        if (message) *message = rlispstat::core::GLMInteractionTwoWayOnlyStatus();
        return false;
    }
    std::string a = BaseVariableForTermComponent(parts[0]);
    std::string b = BaseVariableForTermComponent(parts[1]);
    std::string aType = rlispstat::core::GLMBaseVariableType(seed, a, termTypes);
    std::string bType = rlispstat::core::GLMBaseVariableType(seed, b, termTypes);

    std::string x = a;
    std::string moderator = b;
    std::string xType = aType;
    std::string moderatorType = bType;
    if (aType == "factor" && bType == "numeric") {
        x = b;
        moderator = a;
        xType = bType;
        moderatorType = aType;
    }
    if (aType == "factor" && bType == "factor") {
        x = a;
        moderator = b;
        xType = "factor";
        moderatorType = "factor";
    }

    plot->kind = "glm_interaction";
    plot->isDatasetSeed = false;
    plot->isGLMDiagnostic = false;
    plot->isGLMInteractionPlot = true;
    plot->glmModelId = "glm:" + seed->group;
    plot->glmInteractionTerm = term;
    plot->group = seed->group;
    plot->xLabel = x;
    plot->yLabel = "Predicted " + dependent;
    plot->title = "Interaction: " + term;
    plot->points.clear();
    plot->interactionPlotLines.clear();
    plot->interactionXTicks.clear();
    plot->overlays.clear();

    const double confidenceLevel = 0.95;
    std::vector<std::string> xLevels;
    std::vector<std::string> moderatorLevels;
    if (xType == "factor") {
        xLevels = GLMFactorLevelsForVariable(seed, x, fit);
        for (size_t i = 0; i < xLevels.size(); ++i) {
            plot->interactionXTicks.push_back(std::make_pair((double)i + 1.0, xLevels[i]));
        }
    }
    if (moderatorType == "factor") {
        moderatorLevels = GLMFactorLevelsForVariable(seed, moderator, fit);
    }

    GLMAddObservedInteractionPoints(plot, seed, fit, dependent, x, moderator, xType, moderatorType, xLevels, moderatorLevels);

    if (xType == "numeric" && moderatorType == "factor") {
        GLMNumericSummary xSummary = GLMNumericSummaryForVariable(seed, x, fit);
        if (!xSummary.ok || moderatorLevels.empty()) {
            if (message) *message = rlispstat::core::GLMInteractionNoFittedValuesStatus();
            return false;
        }
        double left = xSummary.min;
        double right = xSummary.max;
        if (!(right > left)) {
            left = xSummary.mean - 1.0;
            right = xSummary.mean + 1.0;
        }
        for (size_t levelIndex = 0; levelIndex < moderatorLevels.size(); ++levelIndex) {
            InteractionPlotLine line;
            line.label = moderator + " = " + moderatorLevels[levelIndex];
            line.colorKey = PaletteColorNameAtIndex(levelIndex);
            for (int i = 0; i <= 40; ++i) {
                double value = left + (right - left) * (double)i / 40.0;
                GLMPostEstimate predicted = GLMPredictionEstimate(seed, terms, termTypes, fit,
                                                                  {{x, value}}, {{moderator, moderatorLevels[levelIndex]}},
                                                                  line.label, confidenceLevel);
                GLMAddInteractionLinePoint(plot, line, value, predicted.estimate);
            }
            plot->interactionPlotLines.push_back(line);
        }
    } else if (xType == "numeric" && moderatorType == "numeric") {
        GLMNumericSummary xSummary = GLMNumericSummaryForVariable(seed, x, fit);
        GLMNumericSummary modSummary = GLMNumericSummaryForVariable(seed, moderator, fit);
        if (!xSummary.ok || !modSummary.ok) {
            if (message) *message = rlispstat::core::GLMInteractionNoFittedValuesStatus();
            return false;
        }
        double left = xSummary.min;
        double right = xSummary.max;
        if (!(right > left)) {
            left = xSummary.mean - 1.0;
            right = xSummary.mean + 1.0;
        }
        std::vector<std::pair<std::string, double>> moderatorValues;
        if (std::isfinite(modSummary.sd) && modSummary.sd > 0.0) {
            moderatorValues.push_back(std::make_pair(moderator + " = M - SD", modSummary.mean - modSummary.sd));
            moderatorValues.push_back(std::make_pair(moderator + " = M", modSummary.mean));
            moderatorValues.push_back(std::make_pair(moderator + " = M + SD", modSummary.mean + modSummary.sd));
        } else {
            moderatorValues.push_back(std::make_pair(moderator + " = M", modSummary.mean));
        }
        for (size_t i = 0; i < moderatorValues.size(); ++i) {
            InteractionPlotLine line;
            line.label = moderatorValues[i].first;
            line.colorKey = PaletteColorNameAtIndex(i);
            for (int step = 0; step <= 40; ++step) {
                double value = left + (right - left) * (double)step / 40.0;
                GLMPostEstimate predicted = GLMPredictionEstimate(seed, terms, termTypes, fit,
                                                                  {{x, value}, {moderator, moderatorValues[i].second}},
                                                                  {}, line.label, confidenceLevel);
                GLMAddInteractionLinePoint(plot, line, value, predicted.estimate);
            }
            plot->interactionPlotLines.push_back(line);
        }
    } else if (xType == "factor" && moderatorType == "factor") {
        if (xLevels.empty() || moderatorLevels.empty()) {
            if (message) *message = rlispstat::core::GLMInteractionFactorNoLevelsStatus();
            return false;
        }
        for (size_t levelIndex = 0; levelIndex < moderatorLevels.size(); ++levelIndex) {
            InteractionPlotLine line;
            line.label = moderator + " = " + moderatorLevels[levelIndex];
            line.colorKey = PaletteColorNameAtIndex(levelIndex);
            for (size_t xIndex = 0; xIndex < xLevels.size(); ++xIndex) {
                GLMPostEstimate predicted = GLMPredictionEstimate(seed, terms, termTypes, fit,
                                                                  {}, {{x, xLevels[xIndex]}, {moderator, moderatorLevels[levelIndex]}},
                                                                  line.label, confidenceLevel);
                GLMAddInteractionLinePoint(plot, line, (double)xIndex + 1.0, predicted.estimate);
            }
            plot->interactionPlotLines.push_back(line);
        }
    } else {
        if (message) *message = rlispstat::core::GLMInteractionTypeNotAvailableStatus();
        return false;
    }

    if (plot->points.empty() || plot->interactionPlotLines.empty()) {
        if (message) *message = rlispstat::core::GLMInteractionNoFiniteValuesStatus();
        return false;
    }
    ComputeRanges(plot);
    return true;
}

static void StoreGLMFitForGroup(const std::string &group, const GLMFitSummary &fit);

static GLMFitSummary PendingLinearGLMFitSummary(const std::string &message)
{
    GLMFitSummary fit;
    fit.ok = false;
    fit.warning = message;
    return fit;
}

static bool UpdateGLMInteractionPlot(PlotModel *plot)
{
    if (!plot || !plot->isGLMInteractionPlot || plot->glmInteractionTerm.empty()) return false;
    PlotModel seed;
    if (!BuildSeedPlotForGroup(plot->group, seed)) return false;
    std::string dependent;
    std::vector<std::string> terms;
    std::map<std::string, std::string> termTypes;
    std::string scope;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        GroupModelState &state = EnsureGroupModelUnlocked(plot->group, &seed);
        dependent = state.dependent.empty() ? seed.yLabel : state.dependent;
        terms = state.terms;
        termTypes = state.termTypes;
        scope = state.scope == "compare_selected_all" ? "all" : state.scope;
    }
    GLMFitSummary fit = FitMultipleLinearModelPortableMac(&seed, dependent, terms, termTypes, scope);
    if (!fit.ok) return false;
    StoreGLMFitForGroup(plot->group, fit);
    std::string message;
    bool ok = PopulateGLMInteractionPlot(plot, &seed, dependent, plot->glmInteractionTerm, terms, termTypes, fit, &message);
    if (ok) {
        std::lock_guard<std::mutex> lock(g_mutex);
        auto it = g_groupModels.find(plot->group);
        if (it != g_groupModels.end()) {
            plot->displayedFitVersion = it->second.fitVersion;
            plot->displayedDiagnosticsVersion = it->second.diagnosticsVersion;
        }
    }
    return ok;
}

static std::string OpenGLMInteractionPlotForTerm(PlotModel *seed,
                                                 const std::string &term,
                                                 bool reportErrors = true)
{
    if (!seed || term.empty()) {
        if (reportErrors) ShowWorkbenchMessageOnMain(ToNSString(rlispstat::core::GLMInteractionPlotWindowTitle()), ToNSString(rlispstat::core::GLMNoInteractionTermStatus()));
        return "";
    }
    std::string dependent;
    std::vector<std::string> terms;
    std::map<std::string, std::string> termTypes;
    std::string scope;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        GroupModelState &state = EnsureGroupModelUnlocked(seed->group, seed);
        dependent = state.dependent.empty() ? seed->yLabel : state.dependent;
        terms = state.terms;
        termTypes = state.termTypes;
        scope = state.scope == "compare_selected_all" ? "all" : state.scope;
    }
    GLMFitSummary fit = FitMultipleLinearModelPortableMac(seed, dependent, terms, termTypes, scope);
    if (!fit.ok) {
        if (reportErrors) ShowWorkbenchMessageOnMain(ToNSString(rlispstat::core::GLMInteractionPlotWindowTitle()), ToNSString(fit.warning));
        return "";
    }
    StoreGLMFitForGroup(seed->group, fit);
    PlotModel *plot = new PlotModel(*seed);
    plot->id = "glm_interaction_" + seed->group + "_" + std::to_string((long long)time(nullptr)) + "_" + std::to_string(std::rand() % 1000000);
    std::string message;
    if (!PopulateGLMInteractionPlot(plot, seed, dependent, term, terms, termTypes, fit, &message)) {
        delete plot;
        if (reportErrors) ShowWorkbenchMessageOnMain(ToNSString(rlispstat::core::GLMInteractionPlotWindowTitle()), ToNSString(message));
        return "";
    }
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        auto it = g_groupModels.find(plot->group);
        if (it != g_groupModels.end()) {
            plot->displayedFitVersion = it->second.fitVersion;
            plot->displayedDiagnosticsVersion = it->second.diagnosticsVersion;
        }
    }
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        (void)AttachPlotModelUnlocked(plot);
    }
    PublishSpreadPlotMessage("DIAGNOSTIC_PLOT_OPENED", plot->group, plot->id, "glm:" + plot->group);
    AddPlotOnMain(plot);
    return plot->id;
}

static void StoreGLMFitForGroup(const std::string &group, const GLMFitSummary &fit)
{
    std::lock_guard<std::mutex> lock(g_mutex);
    GroupModelState &state = EnsureGroupModelUnlocked(group, FirstPlotForGroupUnlocked(group));
    if (fit.ok) {
        if (state.isStale || state.fitVersion == 0) {
            state.fitVersion += 1;
        }
        state.diagnosticsVersion += 1;
        state.diagnostics = fit.diagnostics;
        state.rowsUsed = fit.rowsUsed;
        state.rowsExcluded = fit.rowsExcluded;
        state.isStale = false;
        state.rFitPending = false;
    }
}

static bool UpdateGLMDiagnosticPlot(PlotModel *diag)
{
    if (!diag || !diag->isGLMDiagnostic) {
        return false;
    }
    RegressionComparisonState *comparison = nullptr;
    RegressionComparisonModel *comparisonModel = nullptr;
    if (FindRegressionComparisonModelById(diag->glmModelId, &comparison, &comparisonModel)) {
        if (comparisonModel->isStale || comparisonModel->fitVersion == 0) {
            RefitRegressionComparisonModel(*comparison, *comparisonModel);
        }
        if (!comparisonModel->fit.ok) {
            return false;
        }
        PopulateDiagnosticPlotFromFit(diag, comparisonModel->fit, comparisonModel->fitVersion, comparisonModel->fitVersion);
        return true;
    }
    GeneralizedComparisonState *generalizedComparison = nullptr;
    GeneralizedComparisonModel *generalizedComparisonModel = nullptr;
    if (FindGeneralizedComparisonModelById(diag->glmModelId, &generalizedComparison, &generalizedComparisonModel)) {
        if (generalizedComparisonModel->isStale || generalizedComparisonModel->fitVersion == 0) {
            RefitGeneralizedComparisonModel(*generalizedComparison, *generalizedComparisonModel);
        }
        if (!generalizedComparisonModel->fit.ok) {
            return false;
        }
        std::string message;
        return PopulateGeneralizedDiagnosticPlot(diag, generalizedComparisonModel->fit, &message);
    }
    auto generalizedIt = g_generalizedGLMs.find(diag->glmModelId);
    if (generalizedIt != g_generalizedGLMs.end()) {
        GeneralizedGLMState &state = generalizedIt->second;
        if (!state.ok || state.fitVersion < state.modelVersion) {
            RefitGeneralizedGLMState(state);
        }
        std::string message;
        return PopulateGeneralizedDiagnosticPlot(diag, state, &message);
    }
    PlotModel *seed = nullptr;
    std::string dependent;
    std::vector<std::string> terms;
    std::map<std::string, std::string> termTypes;
    std::string scope = "all";
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        seed = FirstPlotForGroupUnlocked(diag->group);
        if (!seed) {
            return false;
        }
        GroupModelState &state = EnsureGroupModelUnlocked(diag->group, seed);
        dependent = state.dependent.empty() ? seed->yLabel : state.dependent;
        terms = state.terms;
        termTypes = state.termTypes;
        scope = state.scope;
    }
    std::string fitScope = scope == "compare_selected_all" ? "all" : scope;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        auto stateIt = g_groupModels.find(diag->group);
        auto fitIt = g_precomputedLinearModelFits.find(diag->group);
        if (stateIt != g_groupModels.end() && fitIt != g_precomputedLinearModelFits.end() &&
            !stateIt->second.isStale && fitIt->second.ok) {
            PopulateDiagnosticPlotFromFit(diag, fitIt->second, stateIt->second.fitVersion,
                                          stateIt->second.diagnosticsVersion);
            return true;
        }
    }
    GLMFitSummary fit = FitMultipleLinearModelPortableMac(seed, dependent, terms, termTypes, fitScope);
    if (!fit.ok) {
        return false;
    }
    StoreGLMFitForGroup(diag->group, fit);
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        GroupModelState &state = EnsureGroupModelUnlocked(diag->group, seed);
        PopulateDiagnosticPlotFromFit(diag, fit, state.fitVersion, state.diagnosticsVersion);
    }
    return true;
}

static void RefreshGLMDiagnosticPlotsNow(const std::string &group, bool force = false)
{
    std::vector<PlotModel *> diagnostics;
    std::vector<PlotModel *> interactionPlots;
    bool shouldRefit = false;
    int fitVersion = 0;
    int diagnosticsVersion = 0;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        auto stateIt = g_groupModels.find(group);
        if (stateIt != g_groupModels.end()) {
            shouldRefit = stateIt->second.isStale;
            fitVersion = stateIt->second.fitVersion;
            diagnosticsVersion = stateIt->second.diagnosticsVersion;
        }
        for (const auto &entry : g_plots) {
            PlotModel *plot = entry.second;
            if (plot && plot->group == group && plot->isGLMDiagnostic) {
                diagnostics.push_back(plot);
            } else if (plot && plot->group == group && plot->isGLMInteractionPlot) {
                interactionPlots.push_back(plot);
            }
        }
    }
    if (diagnostics.empty() && interactionPlots.empty()) {
        return;
    }
    for (PlotModel *diag : diagnostics) {
        if (force || shouldRefit || diag->displayedFitVersion == 0 ||
            diag->displayedFitVersion != fitVersion ||
            diag->displayedDiagnosticsVersion != diagnosticsVersion) {
            UpdateGLMDiagnosticPlot(diag);
        }
    }
    for (PlotModel *plot : interactionPlots) {
        if (force || shouldRefit || plot->displayedFitVersion == 0 ||
            plot->displayedFitVersion != fitVersion) {
            UpdateGLMInteractionPlot(plot);
        }
    }
    std::lock_guard<std::mutex> lock(g_mutex);
	    for (ScatterView *view : g_views) {
	        if (view.model && view.model->group == group &&
                (view.model->isGLMDiagnostic || view.model->isGLMInteractionPlot)) {
	            [view setNeedsDisplay:YES];
	        }
	    }
	    for (HistogramView *view : g_histogramViews) {
	        if (view.model && view.model->group == group && view.model->isGLMDiagnostic) {
	            [view setNeedsDisplay:YES];
	        }
	    }
	}

static void RefreshGLMDiagnosticPlotsOnMain(const std::string &group)
{
    std::string groupCopy = group;
    dispatch_async(dispatch_get_main_queue(), ^{
      RefreshGLMDiagnosticPlotsNow(groupCopy, false);
    });
}

static void RefreshGLMDiagnosticPlotsSynchronouslyOnMain(const std::string &group, bool force = true)
{
    if ([NSThread isMainThread]) {
        RefreshGLMDiagnosticPlotsNow(group, force);
        return;
    }
    dispatch_sync(dispatch_get_main_queue(), ^{
      RefreshGLMDiagnosticPlotsNow(group, force);
    });
}

static std::string GLMDiagnosticStateSummary(const std::string &group)
{
    std::lock_guard<std::mutex> lock(g_mutex);
    PlotModel *seed = FirstPlotForGroupUnlocked(group);
    GroupModelState &state = EnsureGroupModelUnlocked(group, seed);
    int validPredictors = 0;
    if (seed) {
        for (const std::string &term : state.terms) {
            if (FindVariable(seed, term)) ++validPredictors;
        }
    }
    return rlispstat::core::GLMDiagnosticStateSummaryText(
        group,
        state.dependent.empty() && seed ? seed->yLabel : state.dependent,
        state.terms,
        validPredictors,
        state.modelVersion,
        state.fitVersion,
        state.isStale,
        seed != nullptr,
        state.rowsUsed.size(),
        state.rowsExcluded.size());
}

static std::string OpenModelDiagnosticPlot(PlotModel *seed, const std::string &kind, bool reportErrors = true)
{
    if (!seed) {
        if (reportErrors) {
            ShowWorkbenchMessageOnMain(ToNSString(rlispstat::core::GLMDiagnosticPlotWindowTitle()), ToNSString(rlispstat::core::GLMNoActiveDiagnosticStatus()));
        }
        return "";
    }
    std::string normalizedKind = NormalizeLinearDiagnosticKind(kind);
    if (!LinearDiagnosticKindIsImplemented(normalizedKind)) {
        if (reportErrors) {
            ShowWorkbenchMessageOnMain(ToNSString(rlispstat::core::GLMDiagnosticPlotWindowTitle()), ToNSString(rlispstat::core::GLMCurrentLinearDiagnosticUnavailableStatus(kind)));
        }
        return "";
    }
    PlotModel *diag = new PlotModel();
    diag->id = "diag_" + normalizedKind + "_" + seed->id + "_" + std::to_string((long long)time(nullptr));
    diag->group = seed->group;
    diag->isGLMDiagnostic = true;
    diag->glmModelId = "glm:" + seed->group;
    diag->glmDiagnosticKind = normalizedKind;
    diag->interactionMode = "select";
    diag->selectionMode = "replace";
    if (!UpdateGLMDiagnosticPlot(diag)) {
        std::string group = diag->group;
        delete diag;
        if (reportErrors) {
            ShowWorkbenchMessageOnMain(ToNSString(rlispstat::core::GLMDiagnosticPlotWindowTitle()), ToNSString(rlispstat::core::GLMCurrentDiagnosticFitFailedStatus(GLMDiagnosticStateSummary(group))));
        }
        return "";
    }
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        (void)AttachPlotModelUnlocked(diag);
    }
    PublishSpreadPlotMessage("DIAGNOSTIC_PLOT_OPENED", diag->group, diag->id, diag->glmModelId);
    AddPlotOnMain(diag);
    return diag->id;
}

static std::string OpenRegressionComparisonDiagnosticPlot(const std::string &comparisonId, int modelIndex,
                                                          const std::string &kind, bool reportErrors)
{
    auto it = g_regressionComparisons.find(comparisonId);
    if (it == g_regressionComparisons.end()) {
        if (reportErrors) ShowWorkbenchMessageOnMain(ToNSString(rlispstat::core::GLMDiagnosticPlotWindowTitle()), ToNSString(rlispstat::core::GLMRegressionComparisonNotAvailableStatus()));
        return "";
    }
    RegressionComparisonState &state = it->second;
    if (modelIndex < 0 || (size_t)modelIndex >= state.models.size()) {
        if (reportErrors) ShowWorkbenchMessageOnMain(ToNSString(rlispstat::core::GLMDiagnosticPlotWindowTitle()), ToNSString(rlispstat::core::GLMChooseValidModelColumnStatus()));
        return "";
    }
    std::string normalizedKind = NormalizeLinearDiagnosticKind(kind);
    if (!LinearDiagnosticKindIsImplemented(normalizedKind)) {
        if (reportErrors) ShowWorkbenchMessageOnMain(ToNSString(rlispstat::core::GLMDiagnosticPlotWindowTitle()), ToNSString(rlispstat::core::GLMSelectedLinearDiagnosticUnavailableStatus(kind)));
        return "";
    }
    RegressionComparisonModel &model = state.models[(size_t)modelIndex];
    if (model.isStale || model.fitVersion == 0) {
        RefitRegressionComparisonModel(state, model);
    }
    if (!model.fit.ok) {
        if (reportErrors) ShowWorkbenchMessageOnMain(ToNSString(rlispstat::core::GLMDiagnosticPlotWindowTitle()), ToNSString(rlispstat::core::GLMSelectedDiagnosticFitFailedStatus(model.fit.warning)));
        return "";
    }
    PlotModel *diag = new PlotModel();
    diag->id = "diag_" + normalizedKind + "_" + model.id + "_" + std::to_string((long long)time(nullptr));
    diag->group = state.group;
    diag->isGLMDiagnostic = true;
    diag->glmModelId = model.id;
    diag->glmDiagnosticKind = normalizedKind;
    diag->interactionMode = "select";
    diag->selectionMode = "replace";
    diag->variables = state.seed.variables;
    diag->variableMeta = state.seed.variableMeta;
    PopulateDiagnosticPlotFromFit(diag, model.fit, model.fitVersion, model.fitVersion);
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        (void)AttachPlotModelUnlocked(diag);
    }
    PublishSpreadPlotMessage("DIAGNOSTIC_PLOT_OPENED", diag->group, diag->id, diag->glmModelId);
    AddPlotOnMain(diag);
    return diag->id;
}

static std::string OpenGeneralizedGLMDiagnosticPlot(const std::string &modelId,
                                                     const std::string &kind,
                                                     bool reportErrors)
{
    auto it = g_generalizedGLMs.find(modelId);
    if (it == g_generalizedGLMs.end()) {
        if (reportErrors) ShowWorkbenchMessageOnMain(ToNSString(rlispstat::core::GLMDiagnosticPlotWindowTitle()), ToNSString(rlispstat::core::GLMGeneralizedLinearModelNotAvailableStatus()));
        return "";
    }
    GeneralizedGLMState &state = it->second;
    if (!state.ok || state.fitVersion < state.modelVersion) {
        RefitGeneralizedGLMState(state);
    }
    if (!state.ok) {
        if (reportErrors) ShowWorkbenchMessageOnMain(ToNSString(rlispstat::core::GLMDiagnosticPlotWindowTitle()), ToNSString(rlispstat::core::GLMCurrentGeneralizedDiagnosticFitFailedStatus(state.status)));
        return "";
    }

    std::string normalizedKind = NormalizeGeneralizedDiagnosticKind(kind);
    PlotModel *diag = new PlotModel(state.seed);
    diag->id = "diag_gglm_" + normalizedKind + "_" + state.id + "_" + std::to_string((long long)time(nullptr));
    diag->group = state.group;
    diag->isDatasetSeed = false;
    diag->isGLMDiagnostic = true;
    diag->glmModelId = state.id;
    diag->glmDiagnosticKind = normalizedKind;
    diag->interactionMode = "select";
    diag->selectionMode = "replace";

    std::string message;
    if (!PopulateGeneralizedDiagnosticPlot(diag, state, &message)) {
        delete diag;
        if (reportErrors) ShowWorkbenchMessageOnMain(ToNSString(rlispstat::core::GLMDiagnosticPlotWindowTitle()), ToNSString(message));
        return "";
    }
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        (void)AttachPlotModelUnlocked(diag);
    }
    PublishSpreadPlotMessage("DIAGNOSTIC_PLOT_OPENED", diag->group, diag->id, diag->glmModelId);
    AddPlotOnMain(diag);
    return diag->id;
}

static std::string OpenGeneralizedComparisonDiagnosticPlot(const std::string &comparisonId, int modelIndex,
                                                           const std::string &kind, bool reportErrors)
{
    auto it = g_generalizedComparisons.find(comparisonId);
    if (it == g_generalizedComparisons.end()) {
        if (reportErrors) ShowWorkbenchMessageOnMain(ToNSString(rlispstat::core::GLMDiagnosticPlotWindowTitle()), ToNSString(rlispstat::core::GLMGeneralizedModelComparisonNotAvailableStatus()));
        return "";
    }
    GeneralizedComparisonState &state = it->second;
    if (modelIndex < 0 || (size_t)modelIndex >= state.models.size()) {
        if (reportErrors) ShowWorkbenchMessageOnMain(ToNSString(rlispstat::core::GLMDiagnosticPlotWindowTitle()), ToNSString(rlispstat::core::GLMChooseValidModelColumnStatus()));
        return "";
    }
    GeneralizedComparisonModel &model = state.models[(size_t)modelIndex];
    if (model.isStale || model.fitVersion == 0) {
        RefitGeneralizedComparisonModel(state, model);
    }
    if (!model.fit.ok) {
        if (reportErrors) ShowWorkbenchMessageOnMain(ToNSString(rlispstat::core::GLMDiagnosticPlotWindowTitle()), ToNSString(rlispstat::core::GLMSelectedGeneralizedDiagnosticFitFailedStatus(model.fit.status)));
        return "";
    }

    std::string normalizedKind = NormalizeGeneralizedDiagnosticKind(kind);
    PlotModel *diag = new PlotModel(state.seed);
    diag->id = "diag_gglmcmp_" + normalizedKind + "_" + model.id + "_" + std::to_string((long long)time(nullptr));
    diag->group = state.group;
    diag->isDatasetSeed = false;
    diag->isGLMDiagnostic = true;
    diag->glmModelId = model.id;
    diag->glmDiagnosticKind = normalizedKind;
    diag->interactionMode = "select";
    diag->selectionMode = "replace";

    std::string message;
    if (!PopulateGeneralizedDiagnosticPlot(diag, model.fit, &message)) {
        delete diag;
        if (reportErrors) ShowWorkbenchMessageOnMain(ToNSString(rlispstat::core::GLMDiagnosticPlotWindowTitle()), ToNSString(message));
        return "";
    }
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        (void)AttachPlotModelUnlocked(diag);
    }
    PublishSpreadPlotMessage("DIAGNOSTIC_PLOT_OPENED", diag->group, diag->id, diag->glmModelId);
    AddPlotOnMain(diag);
    return diag->id;
}

static std::string OpenBinaryComparisonFitMeasurePlot(const std::string &comparisonId,
                                                      const std::string &measure,
                                                      bool reportErrors)
{
    auto it = g_generalizedComparisons.find(comparisonId);
    if (it == g_generalizedComparisons.end() || !it->second.binaryComparison) return "";
    GeneralizedComparisonState &state = it->second;
    PlotModel *plot = new PlotModel(state.seed);
    plot->id = "binary_comparison_" + measure + "_" + comparisonId + "_" + std::to_string((long long)time(nullptr));
    plot->group = state.group;
    plot->kind = "scatter";
    plot->isDatasetSeed = false;
    plot->title = (measure == "bic" ? "BIC" : "AIC") + std::string(" by binary model");
    plot->xLabel = "Model";
    plot->yLabel = measure == "bic" ? "BIC" : "AIC";
    plot->interactionMode = "inspect";
    plot->selectionMode = "replace";
    for (std::size_t index = 0; index < state.models.size(); ++index) {
        const GeneralizedComparisonModel &model = state.models[index];
        const double value = measure == "bic" ? model.fit.bic : model.fit.aic;
        if (!std::isfinite(value)) continue;
        plot->points.push_back(DataPoint{(double)index + 1.0, value, 0});
        plot->interactionXTicks.push_back(std::make_pair((double)index + 1.0, model.label));
    }
    if (plot->points.empty()) {
        delete plot;
        if (reportErrors) ShowWorkbenchMessageOnMain(@"Binary Model Comparison", @"The selected fit measure is unavailable for these models.");
        return "";
    }
    ComputeRanges(plot);
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        if (!AttachPlotModelUnlocked(plot)) { delete plot; return ""; }
    }
    AddPlotOnMain(plot);
    return plot->id;
}

static std::string OpenBinaryComparisonROCPlot(const std::string &comparisonId, bool reportErrors)
{
    auto it = g_generalizedComparisons.find(comparisonId);
    if (it == g_generalizedComparisons.end() || !it->second.binaryComparison) return "";
    GeneralizedComparisonState &state = it->second;
    if (state.models.size() < 2) return "";
    const GeneralizedGLMState &base = state.models.front().fit;
    for (const GeneralizedComparisonModel &model : state.models) {
        if (model.fit.rowsUsed != base.rowsUsed || model.fit.response != base.response ||
            model.fit.responseCoding.eventValue != base.responseCoding.eventValue) {
            if (reportErrors) ShowWorkbenchMessageOnMain(@"Binary Model Comparison", @"Comparative ROC curves require the same response, event, and analysis rows for every model.");
            return "";
        }
    }
    static const char *colors[] = {"#0072B2", "#D55E00", "#009E73", "#CC79A7", "#E69F00", "#56B4E9", "#000000"};
    PlotModel *plot = new PlotModel(state.seed);
    plot->id = "binary_comparison_roc_" + comparisonId + "_" + std::to_string((long long)time(nullptr));
    plot->group = state.group;
    plot->kind = "glm_interaction";
    plot->isDatasetSeed = false;
    plot->title = "ROC curves — binary models";
    plot->xLabel = "False positive rate";
    plot->yLabel = "True positive rate";
    plot->interactionMode = "select";
    plot->selectionMode = "replace";
    for (std::size_t index = 0; index < state.models.size(); ++index) {
        const GeneralizedComparisonModel &model = state.models[index];
        rlispstat::core::DiagnosticPlotData roc = rlispstat::core::BuildGeneralizedDiagnosticPlotData(
            "roc_curve", model.fit.residualType, model.fit.diagnostics,
            model.fit.fitVersion, model.fit.diagnosticsVersion);
        if (!roc.ok) continue;
        InteractionPlotLine line;
        std::ostringstream label;
        label << model.label;
        if (std::isfinite(model.fit.auc)) label << " (AUC " << std::fixed << std::setprecision(3) << model.fit.auc << ")";
        line.label = label.str();
        line.colorKey = colors[index % (sizeof(colors) / sizeof(colors[0]))];
        line.points.push_back(DataPoint{0.0, 0.0, 0});
        for (const rlispstat::core::DiagnosticPlotPoint &point : roc.points) {
            DataPoint plotted{point.x, point.y, point.row};
            line.points.push_back(plotted);
            plot->points.push_back(plotted);
        }
        plot->interactionPlotLines.push_back(std::move(line));
    }
    InteractionPlotLine chance;
    chance.label = "Chance";
    chance.colorKey = "#777777";
    chance.points = {DataPoint{0.0, 0.0, 0}, DataPoint{1.0, 1.0, 0}};
    plot->interactionPlotLines.push_back(std::move(chance));
    if (plot->points.empty()) {
        delete plot;
        if (reportErrors) ShowWorkbenchMessageOnMain(@"Binary Model Comparison", @"ROC curves are unavailable for the selected models.");
        return "";
    }
    ComputeRanges(plot);
    plot->dataXmin = plot->xmin = 0.0; plot->dataXmax = plot->xmax = 1.0;
    plot->dataYmin = plot->ymin = 0.0; plot->dataYmax = plot->ymax = 1.0;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        if (!AttachPlotModelUnlocked(plot)) { delete plot; return ""; }
    }
    AddPlotOnMain(plot);
    return plot->id;
}

static bool DispatchModelMutationOnMac(const std::vector<std::string> &command,
                                       const std::string &group)
{
    int before = -1;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        auto model = g_groupModels.find(group);
        if (model != g_groupModels.end()) before = model->second.modelVersion;
    }
    if (MacCommandDispatcher().dispatch(command) != "OK") return false;
    std::lock_guard<std::mutex> lock(g_mutex);
    auto model = g_groupModels.find(group);
    return model != g_groupModels.end() && model->second.modelVersion != before;
}

static void ApplyVariableAction(const std::string &group, const std::string &variable, const std::string &action)
{
    const std::string command = action == "dependent" ? "MODEL_SET_Y" : "MODEL_ADD_TERM";
    if (DispatchModelMutationOnMac({command, group, variable}, group)) {
        PublishSpreadPlotMessage(action == "dependent" ? "GLM_DEPENDENT_CHANGED" : "GLM_PREDICTOR_ADDED",
                                 group, "glm:" + group, "glm:" + group);
        RecordAPICommand({command, group, variable});
    }
}

static void RemoveModelTerm(const std::string &group, const std::string &term)
{
    if (DispatchModelMutationOnMac({"MODEL_REMOVE_TERM", group, term}, group)) {
        PublishSpreadPlotMessage("GLM_PREDICTOR_REMOVED", group, "glm:" + group, "glm:" + group);
        RefreshGLMDiagnosticPlotsSynchronouslyOnMain(group, true);
        RecordAPICommand({"MODEL_REMOVE_TERM", group, term});
    }
}

static void ClearVariableModelRole(const std::string &group, const std::string &variable)
{
    if (DispatchModelMutationOnMac({"MODEL_CLEAR_ROLE", group, variable}, group)) {
        PublishSpreadPlotMessage("GLM_ROLE_CLEARED", group, "glm:" + group, "glm:" + group);
        RefreshGLMDiagnosticPlotsSynchronouslyOnMain(group, true);
        RecordAPICommand({"MODEL_CLEAR_ROLE", group, variable});
    }
}

static DataColumn *FindDataColumnUnlocked(const std::string &group, const std::string &variable)
{
    DataFrameModel *df = FindDataFrameUnlocked(group);
    return df ? FindDataColumnInDataFrame(*df, variable) : nullptr;
}

static const DataColumn *FindDataColumnUnlockedConst(const std::string &group, const std::string &variable)
{
    const DataFrameModel *df = FindDataFrameUnlockedConst(group);
    return df ? FindDataColumnInDataFrame(*df, variable) : nullptr;
}

static void SyncDataColumnToGroupSeedsUnlocked(const std::string &group, const DataColumn &col)
{
    for (auto &entry : g_plots) {
        PlotModel *plot = entry.second;
        if (plot && plot->group == group) {
            SyncPlotVariableFromColumn(plot, col);
        }
    }
    for (auto &entry : g_correlationMatrices) {
        if (entry.second.group == group) SyncPlotVariableFromColumn(&entry.second.seed, col);
    }
    for (auto &entry : g_dendrograms) {
        if (entry.second.group == group) SyncPlotVariableFromColumn(&entry.second.seed, col);
    }
    for (auto &entry : g_dimensionalityModels) {
        if (entry.second.group == group) SyncPlotVariableFromColumn(&entry.second.seed, col);
    }
    for (auto &entry : g_regressionComparisons) {
        if (entry.second.group == group) SyncPlotVariableFromColumn(&entry.second.seed, col);
    }
    for (auto &entry : g_generalizedComparisons) {
        if (entry.second.group == group) SyncPlotVariableFromColumn(&entry.second.seed, col);
    }
    for (auto &entry : g_generalizedGLMs) {
        if (entry.second.group == group) SyncPlotVariableFromColumn(&entry.second.seed, col);
    }
}

static bool RebuildPlotForDataFrame(PlotModel *plot, const DataFrameModel &df)
{
    if (!plot) return false;
    if (plot->isGLMDiagnostic || plot->kind == "pca_biplot" || plot->kind == "pca_scree" ||
        plot->kind == "interaction_plot") {
        return false;
    }
    SyncPlotVariablesFromDataFrame(plot, df);
    if (plot->isDatasetSeed) {
        rlispstat::core::RefreshDatasetSeedPlotAfterVariableSync(*plot);
        return true;
    }
    if (plot->kind == "scatter") {
        if (FindVariable(plot, plot->xLabel) && FindVariable(plot, plot->yLabel)) {
            RebuildPointsForCurrentVariables(plot);
        } else {
            plot->points.clear();
        }
        ComputeScatterRangesIncludingAllImputations(plot, df);
        return true;
    }
    if (plot->kind == "time_series") {
        std::string ignored;
        return rlispstat::core::RebuildTimeSeriesFromDataFrame(*plot, df, &ignored);
    }
    if (plot->kind == "trellis_scatterplot") {
        std::string ignored;
        return rlispstat::core::RebuildTrellisScatterplotFromDataFrame(*plot, df, &ignored);
    }
    if (plot->kind == "scatter_matrix") {
        RebuildScatterMatrixPoints(plot);
        ComputeRanges(plot);
        return true;
    }
    if (plot->kind == "boxplot") {
        if (BoxplotUsesVariableAxes(plot)) {
            std::string ignored;
            RebuildParallelBoxplotPoints(plot, &ignored);
        } else {
            RebuildGroupedBoxplotPointsFromDataFrame(plot, df);
        }
        return true;
    }
    if (plot->kind == "histogram") {
        RebuildHistogramPointsFromCurrentVariable(plot);
        return true;
    }
    if (plot->kind == "barplot") {
        return rlispstat::core::RefreshBarplotFromDataFrame(*plot, df);
    }
    return false;
}

static bool OpenEquivalentPlotWithScopeOnMain(
    PlotModel *source,
    const rlispstat::core::AnalysisScope &scope,
    std::string *message = nullptr)
{
    if (!source || source->isDatasetSeed || source->isGLMDiagnostic ||
        source->kind == "pca_biplot" || source->kind == "pca_scree" ||
        source->kind == "interaction_plot") {
        if (message) *message = "This view cannot yet be cloned with another analysis scope.";
        return false;
    }

    DataFrameModel dataframe;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        const DataFrameModel *found = FindDataFrameUnlockedConst(source->group);
        if (!found) {
            if (message) *message = "The source dataset is no longer available.";
            return false;
        }
        dataframe = *found;
    }

    PlotModel *created = new PlotModel(*source);
    created->id = source->kind + "_scope_" +
        std::to_string(static_cast<long long>(time(nullptr))) + "_" +
        std::to_string(std::rand() % 1000000);
    created->isDatasetSeed = false;
    created->dataScope = scope;
    created->dataScopeCaptured = true;
    if (!RebuildPlotForDataFrame(created, dataframe)) {
        delete created;
        if (message) *message = "This plot specification cannot be rebuilt for another scope.";
        return false;
    }
    ApplyCapturedAnalysisScopeToPlotUnlocked(*created);

    bool requestSmooth = false;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        if (!AttachPlotModelUnlocked(created)) {
            delete created;
            if (message) *message = "The equivalent plot could not be attached.";
            return false;
        }
        requestSmooth = RequestSmoothRecomputeForPlotUnlocked(created);
    }
    AddPlotOnMain(created);
    if (requestSmooth) NotifyMainRTaskAvailable();
    return true;
}

static std::vector<std::string> RebuildPlotsForDataFrameUnlocked(const std::string &group, const DataFrameModel &df)
{
    std::vector<std::string> changed;
    for (auto &entry : g_plots) {
        PlotModel *plot = entry.second;
        if (!plot || plot->group != group) continue;
        if (RebuildPlotForDataFrame(plot, df)) {
            // Rebuild functions deliberately reconstruct their complete portable
            // geometry from the dataset.  Restore the immutable row snapshot
            // captured when this window was created before exposing it again.
            ApplyCapturedAnalysisScopeToPlotUnlocked(*plot);
            changed.push_back(plot->id);
        }
    }
    for (auto &entry : g_correlationMatrices) {
        CorrelationMatrixState &state = entry.second;
        if (state.group == group) {
            SyncPlotVariablesFromDataFrame(&state.seed, df);
        }
    }
    for (auto &entry : g_dendrograms) {
        DendrogramState &state = entry.second;
        if (state.group == group) {
            SyncPlotVariablesFromDataFrame(&state.seed, df);
            RefitDendrogramState(state);
        }
    }
    for (auto &entry : g_dimensionalityModels) {
        DimensionalityState &state = entry.second;
        if (state.group == group) {
            SyncPlotVariablesFromDataFrame(&state.seed, df);
            if (state.variables.size() >= 2) {
                RefitDimensionalityState(state);
            }
        }
    }
    for (auto &entry : g_regressionComparisons) {
        if (entry.second.group == group) {
            SyncPlotVariablesFromDataFrame(&entry.second.seed, df);
        }
    }
    for (auto &entry : g_generalizedComparisons) {
        if (entry.second.group == group) {
            SyncPlotVariablesFromDataFrame(&entry.second.seed, df);
        }
    }
    for (auto &entry : g_generalizedGLMs) {
        if (entry.second.group == group) {
            SyncPlotVariablesFromDataFrame(&entry.second.seed, df);
        }
    }
    return changed;
}

static void SynchronizeVariableTypeChangeOnMac(const std::string &group, const std::string &variable,
                                               const rlispstat::core::VariableTypeChangeEffects &effects)
{
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        DataColumn *column = FindDataColumnUnlocked(group, variable);
        if (column) SyncDataColumnToGroupSeedsUnlocked(group, *column);
    }
    for (const std::string &id : effects.correlationIds) {
        std::lock_guard<std::mutex> lock(g_mutex);
        auto it = g_correlationMatrices.find(id);
        if (it != g_correlationMatrices.end()) RefitCorrelationMatrixState(it->second);
    }
    for (const std::string &id : effects.dendrogramIds) {
        std::lock_guard<std::mutex> lock(g_mutex);
        auto it = g_dendrograms.find(id);
        if (it != g_dendrograms.end()) RefitDendrogramState(it->second);
    }
    for (const std::string &id : effects.dimensionalityIds) {
        std::lock_guard<std::mutex> lock(g_mutex);
        auto it = g_dimensionalityModels.find(id);
        if (it != g_dimensionalityModels.end()) RefitDimensionalityState(it->second);
    }
    for (const std::string &modelId : effects.generalizedGlmIdsToRefit) {
        auto it = g_generalizedGLMs.find(modelId);
        if (it != g_generalizedGLMs.end()) {
            RequestGeneralizedGLMFitInMainR(it->second);
        }
    }
    RefreshDataDeskWindowsOnMain(group);
    RefreshRegressionComparisonWindowsOnMain(group, false);
    RefreshGLMDiagnosticPlotsSynchronouslyOnMain(group, true);
    RedrawGroupViewsSynchronouslyOnMain(group, true);
    UpdatePanelOnMain();
}

static bool SetVariableAnalysisType(const std::string &group, const std::string &variable,
                                    const std::string &type, std::string *message)
{
    rlispstat::core::VariableTypeChangeEffects effects;
    bool changed = false;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        changed = MacCommandDispatcher().applicationState().setVariableType(
            group, variable, type, effects, message);
    }
    if (!changed) return false;
    SynchronizeVariableTypeChangeOnMac(group, variable, effects);
    const std::string normalizedType = NormalizeVariableType(type);
    RecordAPICommand({"SET_VARIABLE_TYPE", group, variable, normalizedType});
    return true;
}

static std::string VariableInformationText(const std::string &group, const std::string &variable)
{
    std::lock_guard<std::mutex> lock(g_mutex);
    const DataFrameModel *df = FindDataFrameUnlockedConst(group);
    if (!df) return rlispstat::core::VariableNotFoundInDatasetStatus(variable, group);
    return rlispstat::core::VariableInformationText(*df, variable);
}

static bool AddDerivedDataColumnForGroup(const std::string &group, const std::string &source,
                                         const std::string &kind, std::string *message)
{
    if (group.empty()) {
        if (message) *message = rlispstat::core::NoActiveDatasetStatus();
        return false;
    }

    std::vector<std::string> plotsToRedraw;
    std::string createdName;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        DataFrameModel *registered = FindDataFrameUnlocked(group);
        if (!registered) {
            if (message) *message = DatasetNotRegisteredStatus(group);
            return false;
        }
        DataFrameModel &df = *registered;
        std::set<int> selectedRows;
        std::map<int, std::string> rowColors;
        auto selectionIt = g_groupSelections.find(group);
        if (selectionIt != g_groupSelections.end()) {
            selectedRows = selectionIt->second;
        }
        auto colorIt = g_groupPointColors.find(group);
        if (colorIt != g_groupPointColors.end()) {
            rowColors = colorIt->second;
        }
        if (!rlispstat::core::AddDerivedDataColumn(df,
                                                   source,
                                                   kind,
                                                   selectedRows,
                                                   rowColors,
                                                   &createdName,
                                                   message)) {
            return false;
        }
        plotsToRedraw = RebuildPlotsForDataFrameUnlocked(group, df);
    }
    for (const std::string &plotId : plotsToRedraw) {
        RedrawPlotOnMain(plotId);
    }
    RefreshDataDeskWindowsOnMain(group);
    RedrawGroupViewsSynchronouslyOnMain(group, true);
    UpdatePanelOnMain();
    if (message) *message = rlispstat::core::DerivedDataColumnAddedStatus(createdName, group);
    return true;
}

static bool AddDerivedDataColumnFromPlot(PlotModel *model, const std::string &kind, std::string *message)
{
    std::string group;
    std::string source = "dataset";
    if (model) {
        group = model->group;
        source = rlispstat::core::PlotDerivedColumnSourceLabel(model->title,
                                                               model->yLabel,
                                                               model->xLabel);
    } else {
        std::lock_guard<std::mutex> lock(g_mutex);
        group = ActiveDatasetGroupUnlocked();
    }
    return AddDerivedDataColumnForGroup(group, source, kind, message);
}

static void RenameVariableReferencesUnlocked(const std::string &group, const std::string &oldName, const std::string &newName)
{
    for (auto &entry : g_plots) {
        PlotModel *plot = entry.second;
        if (!plot || plot->group != group) continue;
        if (plot->xLabel == oldName) plot->xLabel = newName;
        if (plot->yLabel == oldName) plot->yLabel = newName;
        RenameVariableInTermList(plot->scatterMatrixVariables, oldName, newName);
        RenameVariableInTermList(plot->boxplotVariables, oldName, newName);
        RenameVariableInTermList(plot->barplotXVariables, oldName, newName);
        if (plot->barplotSplitVariable == oldName) plot->barplotSplitVariable = newName;
        if (plot->glmInteractionTerm == oldName) plot->glmInteractionTerm = newName;
    }
    MacCommandDispatcher().applicationState().applyVariableRename(group, oldName, newName);
}

static bool RenameDataColumn(const std::string &group, const std::string &oldName,
                             const std::string &newName, std::string *message)
{
    std::vector<std::string> plotsToRedraw;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        DataFrameModel *registered = FindDataFrameUnlocked(group);
        if (!registered) {
            if (message) *message = DatasetNotRegisteredStatus(group);
            return false;
        }
        DataFrameModel &df = *registered;
        if (oldName == newName) {
            if (message) *message = rlispstat::core::DatasetVariableNameUnchangedStatus();
            return true;
        }
        if (!rlispstat::core::RenameDataFrameColumn(df, oldName, newName, message)) {
            return false;
        }
        RenameVariableReferencesUnlocked(group, oldName, newName);
        plotsToRedraw = RebuildPlotsForDataFrameUnlocked(group, df);
    }
    for (const std::string &plotId : plotsToRedraw) {
        RedrawPlotOnMain(plotId);
    }
    RefreshDataDeskWindowsOnMain(group);
    RefreshRegressionComparisonWindowsOnMain(group, false);
    RefreshGeneralizedComparisonWindowsOnMain(group, false);
    RefreshGLMDiagnosticPlotsSynchronouslyOnMain(group, true);
    RedrawGroupViewsSynchronouslyOnMain(group, true);
    UpdatePanelOnMain();
    if (message) *message = rlispstat::core::VariableRenamedStatus(oldName, newName);
    return true;
}

static bool SetDataFrameCellValueForGroup(const std::string &group,
                                          const std::string &variable,
                                          std::size_t row,
                                          const std::string &value,
                                          std::string *message)
{
    std::vector<std::string> plotsToRedraw;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        DataFrameModel *registered = FindDataFrameUnlocked(group);
        if (!registered) {
            if (message) *message = DatasetNotRegisteredStatus(group);
            return false;
        }
        if (!rlispstat::core::SetDataFrameCellValue(*registered, variable, row, value, message)) {
            return false;
        }
        plotsToRedraw = RebuildPlotsForDataFrameUnlocked(group, *registered);
    }
    for (const std::string &plotId : plotsToRedraw) RedrawPlotOnMain(plotId);
    RefreshDataDeskWindowsOnMain(group);
    RefreshRegressionComparisonWindowsOnMain(group, false);
    RefreshGeneralizedComparisonWindowsOnMain(group, false);
    RefreshGLMDiagnosticPlotsSynchronouslyOnMain(group, true);
    RedrawGroupViewsSynchronouslyOnMain(group, true);
    UpdatePanelOnMain();
    return true;
}

static bool SetVariableDescription(const std::string &group, const std::string &variable,
                                   const std::string &description, std::string *message)
{
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        DataColumn *col = FindDataColumnUnlocked(group, variable);
        if (!col) {
            if (message) *message = rlispstat::core::VariableNotFoundStatus(variable);
            return false;
        }
        rlispstat::core::SetDataColumnDescription(*col, description);
    }
    RefreshDataDeskWindowsOnMain(group);
    if (message) *message = rlispstat::core::VariableDescriptionChangedStatus(variable);
    return true;
}

static bool SetVariableDecimals(const std::string &group, const std::string &variable,
                                int decimals, std::string *message)
{
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        DataColumn *col = FindDataColumnUnlocked(group, variable);
        if (!col) {
            if (message) *message = rlispstat::core::VariableNotFoundStatus(variable);
            return false;
        }
        if (!rlispstat::core::SetDataColumnDecimals(*col, decimals, message)) {
            return false;
        }
    }
    RefreshDataDeskWindowsOnMain(group);
    if (message) *message = rlispstat::core::VariableDecimalsChangedStatus(variable, decimals);
    return true;
}

@interface VariablesWindowController : NSObject <NSTableViewDataSource, NSTableViewDelegate>
{
    std::string _group;
    NSWindow *_window;
    NSTableView *_table;
    NSTextField *_statusField;
    NSTextField *_decimalEditorField;
    NSStepper *_decimalEditorStepper;
    NSButton *_decimalAutomaticButton;
}
- (instancetype)initWithGroup:(const std::string &)group;
- (void)show;
- (void)refresh;
- (void)variableCellClicked:(id)sender;
- (void)makeDependent:(id)sender;
- (void)addPredictor:(id)sender;
- (void)removePredictor:(id)sender;
- (void)clearRole:(id)sender;
- (void)setVariableTypeFromMenu:(id)sender;
- (void)decimalStepperChanged:(id)sender;
- (void)decimalAutomaticChanged:(id)sender;
@end

@implementation VariablesWindowController
- (instancetype)initWithGroup:(const std::string &)group
{
    self = [super init];
    if (self) {
        _group = group;
        _window = [[NSWindow alloc]
            initWithContentRect:NSMakeRect(110, 190, 760, 520)
                      styleMask:(NSWindowStyleMaskTitled | NSWindowStyleMaskClosable |
                                 NSWindowStyleMaskResizable | NSWindowStyleMaskMiniaturizable)
                        backing:NSBackingStoreBuffered
                          defer:NO];
        [_window setTitle:ToNSString(VariableViewWindowTitle(group))];
        [_window setMinSize:NSMakeSize(620, 420)];
        NSView *content = [_window contentView];
        [content setWantsLayer:YES];
        [[content layer] setBackgroundColor:[WorkbenchBackgroundColor() CGColor]];

        NSTextField *title = GLMLabel(ToNSString(VariableViewTitle()), NSMakeRect(18, 480, 220, 26), 18, NSFontWeightSemibold);
        [content addSubview:title];
        NSTextField *hint = GLMLabel(ToNSString(VariableViewInstructionText()), NSMakeRect(18, 456, 700, 22), 12, NSFontWeightRegular);
        [hint setTextColor:[NSColor colorWithCalibratedWhite:0.38 alpha:1.0]];
        [content addSubview:hint];

        NSScrollView *scroll = [[NSScrollView alloc] initWithFrame:NSMakeRect(18, 54, 724, 394)];
        [scroll setBorderType:NSBezelBorder];
        [scroll setHasVerticalScroller:YES];
        [scroll setAutoresizingMask:NSViewWidthSizable | NSViewHeightSizable];
        _table = [[NSTableView alloc] initWithFrame:[[scroll contentView] bounds]];
        [_table setDelegate:self];
        [_table setDataSource:self];
        [_table setUsesAlternatingRowBackgroundColors:NO];
        [_table setBackgroundColor:WorkbenchSurfaceColor()];
        [_table setRowHeight:28.0];
        [_table setTarget:self];
        [_table setAction:@selector(variableCellClicked:)];
        [_table setDoubleAction:@selector(doubleClickVariable:)];

        NSTableColumn *nameColumn = [[NSTableColumn alloc] initWithIdentifier:@"name"];
        [[nameColumn headerCell] setStringValue:ToNSString(rlispstat::core::FormatNameColumnHeader())];
        [nameColumn setWidth:150];
        [nameColumn setEditable:YES];
        [_table addTableColumn:nameColumn];
        NSTableColumn *typeColumn = [[NSTableColumn alloc] initWithIdentifier:@"type"];
        [[typeColumn headerCell] setStringValue:ToNSString(rlispstat::core::FormatTypeColumnHeader())];
        [typeColumn setWidth:90];
        [typeColumn setEditable:NO];
        [_table addTableColumn:typeColumn];
        NSTableColumn *decimalsColumn = [[NSTableColumn alloc] initWithIdentifier:@"decimals"];
        [[decimalsColumn headerCell] setStringValue:ToNSString(rlispstat::core::FormatDecimalsColumnHeader())];
        [decimalsColumn setWidth:76];
        [decimalsColumn setEditable:NO];
        [_table addTableColumn:decimalsColumn];
        NSTableColumn *roleColumn = [[NSTableColumn alloc] initWithIdentifier:@"role"];
        [[roleColumn headerCell] setStringValue:ToNSString(rlispstat::core::FormatRoleColumnHeader())];
        [roleColumn setWidth:110];
        [roleColumn setEditable:NO];
        [_table addTableColumn:roleColumn];
        NSTableColumn *descriptionColumn = [[NSTableColumn alloc] initWithIdentifier:@"description"];
        [[descriptionColumn headerCell] setStringValue:ToNSString(rlispstat::core::FormatDescriptionColumnHeader())];
        [descriptionColumn setWidth:280];
        [descriptionColumn setEditable:YES];
        [_table addTableColumn:descriptionColumn];
        [scroll setDocumentView:_table];
        [content addSubview:scroll];

        const rlispstat::core::VariableViewContextMenuTitles menuTitles = rlispstat::core::DefaultVariableViewContextMenuTitles();
        std::vector<rlispstat::core::LinkedPlotCommandOption> roleOptions = rlispstat::core::VariableViewRoleOptions();
        NSMenu *menu = [[NSMenu alloc] initWithTitle:ToNSString(menuTitles.root)];
        NSMenuItem *roleItem = [[NSMenuItem alloc] initWithTitle:ToNSString(menuTitles.role) action:nil keyEquivalent:@""];
        NSMenu *roleMenu = [[NSMenu alloc] initWithTitle:ToNSString(menuTitles.role)];
        [roleMenu addItem:[[NSMenuItem alloc] initWithTitle:ToNSString(roleOptions[0].title) action:@selector(makeDependent:) keyEquivalent:@""]];
        [roleMenu addItem:[[NSMenuItem alloc] initWithTitle:ToNSString(roleOptions[1].title) action:@selector(addPredictor:) keyEquivalent:@""]];
        [roleMenu addItem:[[NSMenuItem alloc] initWithTitle:ToNSString(roleOptions[2].title) action:@selector(clearRole:) keyEquivalent:@""]];
        [menu setSubmenu:roleMenu forItem:roleItem];
        [menu addItem:roleItem];
        NSMenuItem *typeItem = [[NSMenuItem alloc] initWithTitle:ToNSString(menuTitles.type) action:nil keyEquivalent:@""];
        NSMenu *typeMenu = [[NSMenu alloc] initWithTitle:ToNSString(menuTitles.type)];
        for (const rlispstat::core::LinkedPlotCommandOption &option : rlispstat::core::VariableViewTypeOptions()) {
            NSMenuItem *item = [[NSMenuItem alloc] initWithTitle:ToNSString(option.title)
                                                          action:@selector(setVariableTypeFromMenu:)
                                                   keyEquivalent:@""];
            [item setRepresentedObject:ToNSString(option.value)];
            [typeMenu addItem:item];
        }
        [menu setSubmenu:typeMenu forItem:typeItem];
        [menu addItem:typeItem];
        [menu addItem:[NSMenuItem separatorItem]];
        [menu addItem:[[NSMenuItem alloc] initWithTitle:ToNSString(menuTitles.editDescription) action:@selector(editSelectedVariableDescription:) keyEquivalent:@""]];
        [menu addItem:[[NSMenuItem alloc] initWithTitle:ToNSString(menuTitles.showVariableInformation) action:@selector(showSelectedVariableInformation:) keyEquivalent:@""]];
        for (NSMenuItem *item in [menu itemArray]) {
            if ([item action]) {
                [item setTarget:self];
            }
            if ([item submenu]) {
                for (NSMenuItem *child in [[item submenu] itemArray]) {
                    if ([child action]) {
                        [child setTarget:self];
                    }
                }
            }
        }
        [_table setMenu:menu];

        _statusField = GLMLabel(@"", NSMakeRect(18, 18, 724, 22), 12, NSFontWeightRegular);
        [_statusField setAutoresizingMask:NSViewWidthSizable | NSViewMaxYMargin];
        [content addSubview:_statusField];
        [self refresh];
    }
    return self;
}

- (PlotModel *)plot
{
    std::lock_guard<std::mutex> lock(g_mutex);
    return EnsureDatasetSeedPlotUnlocked(_group);
}

- (std::vector<VariableViewRow>)variables
{
    std::lock_guard<std::mutex> lock(g_mutex);
    std::vector<VariableViewRow> vars;
    const DataFrameModel *df = FindDataFrameUnlockedConst(_group);
    if (df) {
        return VariableViewRowsForDataFrame(*df);
    }
    PlotModel *plot = FirstPlotForGroupUnlocked(_group);
    if (!plot) return vars;
    if (!plot->variableMeta.empty()) {
        for (const VariableMeta &var : plot->variableMeta) {
            vars.push_back(VariableViewRow{var.name, var.type, "", -1});
        }
        return vars;
    }
    for (const NumericVariable &var : plot->variables) {
        vars.push_back(VariableViewRow{var.name, "numeric", "", -1});
    }
    return vars;
}

- (NSInteger)numberOfRowsInTableView:(NSTableView *)tableView
{
    return (NSInteger)[self variables].size();
}

- (id)tableView:(NSTableView *)tableView objectValueForTableColumn:(NSTableColumn *)tableColumn row:(NSInteger)row
{
    std::vector<VariableViewRow> vars = [self variables];
    if (row < 0 || (size_t)row >= vars.size()) {
        return @"";
    }
    NSString *identifier = [tableColumn identifier];
    if ([identifier isEqualToString:@"name"]) {
        return ToNSString(vars[(size_t)row].name);
    }
    if ([identifier isEqualToString:@"type"]) {
        return ToNSString(rlispstat::core::VariableTypeDisplayName(vars[(size_t)row].type));
    }
    if ([identifier isEqualToString:@"decimals"]) {
        if (vars[(size_t)row].type != "numeric") {
            return @"";
        }
        int decimals = vars[(size_t)row].decimals;
        return decimals < 0 ? ToNSString(rlispstat::core::FormatAutoLabel()) : [NSString stringWithFormat:@"%d", decimals];
    }
    if ([identifier isEqualToString:@"description"]) {
        return ToNSString(vars[(size_t)row].description);
    }
    std::lock_guard<std::mutex> lock(g_mutex);
    PlotModel *plot = EnsureDatasetSeedPlotUnlocked(_group);
    return ToNSString(rlispstat::core::VariableRoleDisplayName(VariableRoleForPlot(plot, vars[(size_t)row].name)));
}

- (void)tableView:(NSTableView *)tableView setObjectValue:(id)object forTableColumn:(NSTableColumn *)tableColumn row:(NSInteger)row
{
    (void)tableView;
    std::vector<VariableViewRow> vars = [self variables];
    if (row < 0 || (size_t)row >= vars.size()) return;
    std::string variable = vars[(size_t)row].name;
    std::string value = object ? [[object description] UTF8String] : "";
    value = TrimCopy(value);
    NSString *identifier = [tableColumn identifier];
    std::string message;
    if ([identifier isEqualToString:@"name"]) {
        if (RenameDataColumn(_group, variable, value, &message)) {
            [_statusField setStringValue:ToNSString(message)];
        } else {
            [_statusField setStringValue:ToNSString(message)];
        }
    } else if ([identifier isEqualToString:@"type"]) {
        std::string normalized = NormalizeVariableType(value);
        if (SetVariableAnalysisType(_group, variable, normalized, &message)) {
            [_statusField setStringValue:ToNSString(message)];
        } else {
            [_statusField setStringValue:ToNSString(message)];
        }
    } else if ([identifier isEqualToString:@"decimals"]) {
        int decimals = -1;
        std::string lowered = LowerCopy(value);
        if (!value.empty() && lowered != "auto" && lowered != "automatic") {
            char *end = nullptr;
            long parsed = std::strtol(value.c_str(), &end, 10);
            while (end && *end && std::isspace((unsigned char)*end)) ++end;
            if (!end || *end != '\0') {
                [_statusField setStringValue:ToNSString(rlispstat::core::VariableDecimalsInvalidStatus(false))];
                [self refresh];
                return;
            }
            decimals = (int)parsed;
        }
        if (SetVariableDecimals(_group, variable, decimals, &message)) {
            [_statusField setStringValue:ToNSString(message)];
        } else {
            [_statusField setStringValue:ToNSString(message)];
        }
    } else if ([identifier isEqualToString:@"description"]) {
        if (SetVariableDescription(_group, variable, value, &message)) {
            [_statusField setStringValue:ToNSString(message)];
        } else {
            [_statusField setStringValue:ToNSString(message)];
        }
    }
    [self refresh];
}

- (std::string)selectedVariable
{
    NSInteger row = [_table selectedRow];
    std::vector<VariableViewRow> vars = [self variables];
    if (row < 0 || (size_t)row >= vars.size()) {
        return "";
    }
    return vars[(size_t)row].name;
}

- (std::string)variableAtRow:(NSInteger)row
{
    std::vector<VariableViewRow> vars = [self variables];
    if (row < 0 || (size_t)row >= vars.size()) {
        return "";
    }
    return vars[(size_t)row].name;
}

- (void)showRoleMenuForRow:(NSInteger)row column:(NSInteger)column
{
    std::string variable = [self variableAtRow:row];
    if (variable.empty()) return;
    [_table selectRowIndexes:[NSIndexSet indexSetWithIndex:(NSUInteger)row] byExtendingSelection:NO];
    std::string role;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        role = VariableRoleForPlot(EnsureDatasetSeedPlotUnlocked(_group), variable);
    }
    const rlispstat::core::VariableViewContextMenuTitles menuTitles = rlispstat::core::DefaultVariableViewContextMenuTitles();
    std::vector<rlispstat::core::LinkedPlotCommandOption> roleOptions = rlispstat::core::VariableViewRoleOptions();
    NSMenu *menu = [[NSMenu alloc] initWithTitle:ToNSString(menuTitles.role)];
    NSMenuItem *dependent = [[NSMenuItem alloc] initWithTitle:ToNSString(roleOptions[0].title) action:@selector(makeDependent:) keyEquivalent:@""];
    [dependent setTarget:self];
    [dependent setState:role == "Y" ? NSControlStateValueOn : NSControlStateValueOff];
    [menu addItem:dependent];
    NSMenuItem *predictor = [[NSMenuItem alloc] initWithTitle:ToNSString(roleOptions[1].title) action:@selector(addPredictor:) keyEquivalent:@""];
    [predictor setTarget:self];
    [predictor setState:role == "Predictor" ? NSControlStateValueOn : NSControlStateValueOff];
    [menu addItem:predictor];
    NSMenuItem *none = [[NSMenuItem alloc] initWithTitle:ToNSString(roleOptions[2].title) action:@selector(clearRole:) keyEquivalent:@""];
    [none setTarget:self];
    [none setState:(role != "Y" && role != "Predictor") ? NSControlStateValueOn : NSControlStateValueOff];
    [menu addItem:none];

    NSRect cellRect = NSIntersectionRect([_table rectOfRow:row], [_table rectOfColumn:column]);
    NSPoint point = NSMakePoint(NSMinX(cellRect) + 6.0, NSMaxY(cellRect));
    [menu popUpMenuPositioningItem:nil atLocation:point inView:_table];
}

- (void)showTypeMenuForRow:(NSInteger)row column:(NSInteger)column
{
    std::vector<VariableViewRow> vars = [self variables];
    if (row < 0 || (size_t)row >= vars.size()) return;
    std::string variable = vars[(size_t)row].name;
    std::string current = vars[(size_t)row].type;
    [_table selectRowIndexes:[NSIndexSet indexSetWithIndex:(NSUInteger)row] byExtendingSelection:NO];

    const rlispstat::core::VariableViewContextMenuTitles menuTitles = rlispstat::core::DefaultVariableViewContextMenuTitles();
    NSMenu *menu = [[NSMenu alloc] initWithTitle:ToNSString(menuTitles.type)];
    for (const rlispstat::core::LinkedPlotCommandOption &option : rlispstat::core::VariableViewTypeOptions()) {
        NSMenuItem *item = [[NSMenuItem alloc] initWithTitle:ToNSString(option.title)
                                                      action:@selector(setVariableTypeFromMenu:)
                                               keyEquivalent:@""];
        [item setTarget:self];
        [item setRepresentedObject:ToNSString(option.value)];
        [item setState:current == option.value ? NSControlStateValueOn : NSControlStateValueOff];
        [menu addItem:item];
    }

    NSRect cellRect = NSIntersectionRect([_table rectOfRow:row], [_table rectOfColumn:column]);
    NSPoint point = NSMakePoint(NSMinX(cellRect) + 6.0, NSMaxY(cellRect));
    [menu popUpMenuPositioningItem:nil atLocation:point inView:_table];
    [_statusField setStringValue:ToNSString(rlispstat::core::VariableTypeEditingStatus(variable))];
}

- (void)showDecimalsEditorForRow:(NSInteger)row column:(NSInteger)column
{
    (void)column;
    std::vector<VariableViewRow> vars = [self variables];
    if (row < 0 || (size_t)row >= vars.size()) return;
    const VariableViewRow &var = vars[(size_t)row];
    [_table selectRowIndexes:[NSIndexSet indexSetWithIndex:(NSUInteger)row] byExtendingSelection:NO];
    if (var.type != "numeric") {
        [_statusField setStringValue:ToNSString(rlispstat::core::VariableDecimalsUnavailableStatus(var.name, var.type))];
        return;
    }

    int current = var.decimals;
    int editorValue = current >= 0 ? current : 2;
    NSAlert *alert = [[NSAlert alloc] init];
    [alert setMessageText:ToNSString("Decimals for " + var.name)];
    [alert setInformativeText:ToNSString(rlispstat::core::VariableDecimalsInfoText())];
    [alert addButtonWithTitle:ToNSString(rlispstat::core::AlertApplyButtonTitle())];
    [alert addButtonWithTitle:ToNSString(rlispstat::core::AlertCancelButtonTitle())];

    NSView *accessory = [[NSView alloc] initWithFrame:NSMakeRect(0, 0, 280, 72)];
    _decimalAutomaticButton = [[NSButton alloc] initWithFrame:NSMakeRect(0, 48, 220, 20)];
    [_decimalAutomaticButton setButtonType:NSButtonTypeSwitch];
    [_decimalAutomaticButton setTitle:ToNSString(rlispstat::core::VariableDecimalsAutoButtonTitle())];
    [_decimalAutomaticButton setState:current < 0 ? NSControlStateValueOn : NSControlStateValueOff];
    [_decimalAutomaticButton setTarget:self];
    [_decimalAutomaticButton setAction:@selector(decimalAutomaticChanged:)];
    [accessory addSubview:_decimalAutomaticButton];

    NSTextField *label = GLMLabel(ToNSString(rlispstat::core::FormatFixedDecimalsLabel()), NSMakeRect(0, 15, 100, 20), 12, NSFontWeightRegular);
    [accessory addSubview:label];
    _decimalEditorField = [[NSTextField alloc] initWithFrame:NSMakeRect(108, 11, 56, 24)];
    [_decimalEditorField setStringValue:[NSString stringWithFormat:@"%d", editorValue]];
    [_decimalEditorField setAlignment:NSTextAlignmentRight];
    [accessory addSubview:_decimalEditorField];
    _decimalEditorStepper = [[NSStepper alloc] initWithFrame:NSMakeRect(170, 8, 22, 28)];
    [_decimalEditorStepper setMinValue:0.0];
    [_decimalEditorStepper setMaxValue:12.0];
    [_decimalEditorStepper setIncrement:1.0];
    [_decimalEditorStepper setDoubleValue:(double)editorValue];
    [_decimalEditorStepper setTarget:self];
    [_decimalEditorStepper setAction:@selector(decimalStepperChanged:)];
    [accessory addSubview:_decimalEditorStepper];
    [self decimalAutomaticChanged:_decimalAutomaticButton];

    [alert setAccessoryView:accessory];
    if ([alert runModal] == NSAlertFirstButtonReturn) {
        std::string message;
        int decimals = -1;
        if ([_decimalAutomaticButton state] != NSControlStateValueOn) {
            std::string text = TrimCopy(std::string([[_decimalEditorField stringValue] UTF8String]));
            char *end = nullptr;
            long parsed = std::strtol(text.c_str(), &end, 10);
            while (end && *end && std::isspace((unsigned char)*end)) ++end;
            if (text.empty() || !end || *end != '\0' || parsed < 0 || parsed > 12) {
                [_statusField setStringValue:ToNSString(rlispstat::core::VariableDecimalsInvalidStatus(true))];
                [self refresh];
                return;
            }
            decimals = (int)parsed;
        }
        if (SetVariableDecimals(_group, var.name, decimals, &message)) {
            [_statusField setStringValue:ToNSString(message)];
        } else {
            [_statusField setStringValue:ToNSString(message)];
        }
        [self refresh];
    }
    _decimalEditorField = nil;
    _decimalEditorStepper = nil;
    _decimalAutomaticButton = nil;
}

- (void)variableCellClicked:(id)sender
{
    (void)sender;
    NSInteger row = [_table clickedRow];
    NSInteger column = [_table clickedColumn];
    if (row < 0 || column < 0) return;
    NSTableColumn *tableColumn = [[_table tableColumns] objectAtIndex:(NSUInteger)column];
    NSString *identifier = [tableColumn identifier];
    if ([identifier isEqualToString:@"role"]) {
        [self showRoleMenuForRow:row column:column];
        return;
    }
    if ([identifier isEqualToString:@"type"]) {
        [self showTypeMenuForRow:row column:column];
        return;
    }
    if ([identifier isEqualToString:@"decimals"]) {
        [self showDecimalsEditorForRow:row column:column];
        return;
    }
    if ([tableColumn isEditable]) {
        [_table editColumn:column row:row withEvent:nil select:YES];
    }
}

- (void)doubleClickVariable:(id)sender
{
    std::string variable = [self selectedVariable];
    if (variable.empty()) {
        return;
    }
    bool hasDependent = false;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        GroupModelState &state = EnsureGroupModelUnlocked(_group, EnsureDatasetSeedPlotUnlocked(_group));
        hasDependent = !state.dependent.empty();
    }
    ApplyVariableAction(_group, variable, hasDependent ? "predictor" : "dependent");
}

- (void)makeDependent:(id)sender
{
    std::string variable = [self selectedVariable];
    if (!variable.empty()) {
        ApplyVariableAction(_group, variable, "dependent");
        [self refresh];
        [_statusField setStringValue:ToNSString(rlispstat::core::VariableRoleChangedStatus(variable, "dependent"))];
    }
}

- (void)addPredictor:(id)sender
{
    std::string variable = [self selectedVariable];
    if (!variable.empty()) {
        ApplyVariableAction(_group, variable, "predictor");
        [self refresh];
        [_statusField setStringValue:ToNSString(rlispstat::core::VariableRoleChangedStatus(variable, "predictor"))];
    }
}

- (void)removePredictor:(id)sender
{
    (void)sender;
    std::string variable = [self selectedVariable];
    if (!variable.empty()) {
        RemoveModelTerm(_group, variable);
        [self refresh];
        [_statusField setStringValue:ToNSString(rlispstat::core::VariableRoleChangedStatus(variable, "remove_predictor"))];
    }
}

- (void)clearRole:(id)sender
{
    (void)sender;
    std::string variable = [self selectedVariable];
    if (!variable.empty()) {
        ClearVariableModelRole(_group, variable);
        [self refresh];
        [_statusField setStringValue:ToNSString(rlispstat::core::VariableRoleChangedStatus(variable, "none"))];
    }
}

- (void)setSelectedVariableType:(const std::string &)type
{
    std::string variable = [self selectedVariable];
    if (variable.empty()) return;
    std::string message;
    if (!SetVariableAnalysisType(_group, variable, type, &message)) {
        [_statusField setStringValue:ToNSString(message)];
        return;
    }
    [_statusField setStringValue:ToNSString(rlispstat::core::VariableTypeChangedStatus(variable, type))];
    [self refresh];
}

- (void)setVariableTypeFromMenu:(id)sender
{
    NSString *typeString = [sender representedObject];
    std::string type = typeString ? NormalizeVariableType(std::string([typeString UTF8String])) : "";
    [self setSelectedVariableType:type];
}

- (void)treatSelectedVariableAsNumeric:(id)sender
{
    (void)sender;
    [self setSelectedVariableType:"numeric"];
}

- (void)treatSelectedVariableAsFactor:(id)sender
{
    (void)sender;
    [self setSelectedVariableType:"factor"];
}

- (void)treatSelectedVariableAsText:(id)sender
{
    (void)sender;
    [self setSelectedVariableType:"character"];
}

- (void)decimalStepperChanged:(id)sender
{
    (void)sender;
    if (!_decimalEditorStepper || !_decimalEditorField) return;
    long value = lrint([_decimalEditorStepper doubleValue]);
    [_decimalEditorField setStringValue:[NSString stringWithFormat:@"%ld", value]];
}

- (void)decimalAutomaticChanged:(id)sender
{
    (void)sender;
    BOOL automatic = _decimalAutomaticButton && [_decimalAutomaticButton state] == NSControlStateValueOn;
    [_decimalEditorField setEnabled:!automatic];
    [_decimalEditorStepper setEnabled:!automatic];
}

- (void)editSelectedVariableDescription:(id)sender
{
    (void)sender;
    std::string variable = [self selectedVariable];
    if (variable.empty()) return;
    std::string current;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        const DataColumn *col = FindDataColumnUnlockedConst(_group, variable);
        if (col) current = col->description;
    }
    NSAlert *alert = [[NSAlert alloc] init];
    [alert setMessageText:ToNSString(VariableDescriptionDialogTitle(variable))];
    [alert setInformativeText:ToNSString(VariableDescriptionDialogInformationText())];
    [alert addButtonWithTitle:ToNSString(rlispstat::core::AlertApplyButtonTitle())];
    [alert addButtonWithTitle:ToNSString(rlispstat::core::AlertCancelButtonTitle())];
    NSScrollView *scroll = [[NSScrollView alloc] initWithFrame:NSMakeRect(0, 0, 420, 110)];
    NSTextView *textView = [[NSTextView alloc] initWithFrame:NSMakeRect(0, 0, 420, 110)];
    [textView setString:ToNSString(current)];
    [scroll setDocumentView:textView];
    [scroll setHasVerticalScroller:YES];
    [alert setAccessoryView:scroll];
    if ([alert runModal] == NSAlertFirstButtonReturn) {
        std::string message;
        SetVariableDescription(_group, variable, std::string([[textView string] UTF8String]), &message);
        [_statusField setStringValue:ToNSString(message)];
        [self refresh];
    }
}

- (void)showSelectedVariableInformation:(id)sender
{
    (void)sender;
    std::string variable = [self selectedVariable];
    if (variable.empty()) return;
    ShowWorkbenchMessageOnMain(ToNSString(VariableInformationDialogTitle()), ToNSString(VariableInformationText(_group, variable)));
}

- (void)show
{
    [_window orderFront:nil];
    [NSApp activateIgnoringOtherApps:YES];
    [self refresh];
}

- (void)refresh
{
    [_table reloadData];
    std::lock_guard<std::mutex> lock(g_mutex);
    GroupModelState &state = EnsureGroupModelUnlocked(_group, EnsureDatasetSeedPlotUnlocked(_group));
    [_statusField setStringValue:ToNSString(rlispstat::core::VariableViewModelRoleSummary(state.dependent,
                                                                                          state.terms.size()))];
}
@end

@interface DataSheetRowView : NSTableRowView
@property(nonatomic, copy) NSString *groupName;
@property(nonatomic) NSInteger originalRow;
@end

@implementation DataSheetRowView
- (void)drawBackgroundInRect:(NSRect)dirtyRect
{
    (void)dirtyRect;
    DataSheetRowStyle style = DataSheetStyleForRow(std::string([self.groupName UTF8String]), (int)self.originalRow, [self isSelected]);
    if (style.customBackground) {
        [style.background setFill];
        NSRectFill([self bounds]);
    } else {
        [WorkbenchSurfaceColor() setFill];
        NSRectFill([self bounds]);
    }
}

- (void)drawSelectionInRect:(NSRect)dirtyRect
{
    DataSheetRowStyle style = DataSheetStyleForRow(std::string([self.groupName UTF8String]), (int)self.originalRow, [self isSelected]);
    if (style.customBackground) {
        [style.background setFill];
        NSRectFill([self bounds]);
    } else {
        [super drawSelectionInRect:dirtyRect];
    }
}
@end

static void ConfigureSharedDataSheetTable(NSTableView *table, bool readOnly)
{
    if (!table) return;
    [table setUsesAlternatingRowBackgroundColors:NO];
    [table setBackgroundColor:WorkbenchSurfaceColor()];
    [table setAllowsMultipleSelection:YES];
    [table setAllowsColumnSelection:!readOnly];
    [table setSelectionHighlightStyle:NSTableViewSelectionHighlightStyleNone];
    [table setRowHeight:24.0];
    [table setIntercellSpacing:NSMakeSize(0.0, 0.0)];
    [table setAllowsColumnResizing:YES];
    [table setAllowsColumnReordering:!readOnly];
    [table setAllowsTypeSelect:YES];
}

@class TrellisPanelTableAdapter;

@interface TrellisPanelTableView : NSTableView
@property(nonatomic, assign) ScatterView *trellisOwner;
@property(nonatomic, copy) NSString *panelLevelId;
@property(nonatomic, assign) TrellisPanelTableAdapter *panelAdapter;
@end

@interface TrellisPanelTableAdapter : NSObject <NSTableViewDataSource, NSTableViewDelegate>
{
    std::string _group;
    DataFrameModel _dataFrame;
    std::vector<int> _rows;
    std::vector<std::string> _variables;
    BOOL _updatingSelection;
}
@property(nonatomic, assign) ScatterView *owner;
@property(nonatomic, assign) TrellisPanelTableView *tableView;
- (instancetype)initWithGroup:(const std::string &)group owner:(ScatterView *)owner;
- (void)updateDataFrame:(const DataFrameModel &)dataFrame
                   rows:(const std::vector<int> &)rows
              variables:(const std::vector<std::string> &)variables;
- (NSInteger)originalRowAtVisualRow:(NSInteger)row;
- (const std::vector<int> &)originalRows;
- (void)syncSelection:(const std::set<int> &)selection;
@end

@implementation TrellisPanelTableView
- (NSMenu *)menuForEvent:(NSEvent *)event
{
    NSPoint point = [self convertPoint:[event locationInWindow] fromView:nil];
    NSInteger visualRow = [self rowAtPoint:point];
    NSInteger visualColumn = [self columnAtPoint:point];
    NSInteger originalRow = self.panelAdapter
        ? [self.panelAdapter originalRowAtVisualRow:visualRow] : -1;
    NSString *variable = visualColumn >= 0 && visualColumn < (NSInteger)[[self tableColumns] count]
        ? [[[self tableColumns] objectAtIndex:(NSUInteger)visualColumn] identifier] : nil;
    return [self.trellisOwner trellisDataTableContextMenuForPanel:self.panelLevelId
                                                      originalRow:originalRow
                                                        variable:variable];
}
@end

@implementation TrellisPanelTableAdapter
- (instancetype)initWithGroup:(const std::string &)group owner:(ScatterView *)owner
{
    self = [super init];
    if (self) {
        _group = group;
        _owner = owner;
        _updatingSelection = NO;
    }
    return self;
}

- (void)updateDataFrame:(const DataFrameModel &)dataFrame
                   rows:(const std::vector<int> &)rows
              variables:(const std::vector<std::string> &)variables
{
    _dataFrame = dataFrame;
    _rows = rows;
    _variables = variables;
    [self.tableView reloadData];
}

- (NSInteger)originalRowAtVisualRow:(NSInteger)row
{
    return row >= 0 && (std::size_t)row < _rows.size() ? _rows[(std::size_t)row] : -1;
}

- (const std::vector<int> &)originalRows
{
    return _rows;
}

- (NSInteger)numberOfRowsInTableView:(NSTableView *)tableView
{
    (void)tableView;
    return (NSInteger)_rows.size();
}

- (id)tableView:(NSTableView *)tableView
 objectValueForTableColumn:(NSTableColumn *)tableColumn
             row:(NSInteger)row
{
    (void)tableView;
    const NSInteger originalRow = [self originalRowAtVisualRow:row];
    if (originalRow <= 0) return @"";
    NSString *identifier = [tableColumn identifier];
    if ([identifier isEqualToString:@"_row"]) {
        return [NSString stringWithFormat:@"%ld", (long)originalRow];
    }
    const DataColumn *column = FindDataColumnInDataFrame(_dataFrame, [identifier UTF8String]);
    const std::size_t index = (std::size_t)originalRow - 1;
    return column && index < (std::size_t)std::max(0, _dataFrame.rows)
        ? ToNSString(DisplayValueForDataFrameCell(_dataFrame, *column, index)) : @"";
}

- (void)tableView:(NSTableView *)tableView
   willDisplayCell:(id)cell
    forTableColumn:(NSTableColumn *)tableColumn
               row:(NSInteger)row
{
    const NSInteger originalRow = [self originalRowAtVisualRow:row];
    if (originalRow <= 0) return;
    DataSheetRowStyle style = DataSheetStyleForRow(
        _group, (int)originalRow, [tableView isRowSelected:row]);
    bool imputed = false;
    NSString *identifier = [tableColumn identifier];
    if (![identifier isEqualToString:@"_row"]) {
        const DataColumn *column = FindDataColumnInDataFrame(_dataFrame, [identifier UTF8String]);
        imputed = column && DataFrameCellIsImputed(
            _dataFrame, *column, (std::size_t)originalRow - 1);
    }
    if (style.customBackground) {
        [cell setDrawsBackground:YES];
        [cell setBackgroundColor:style.background];
    } else if (imputed) {
        [cell setDrawsBackground:YES];
        [cell setBackgroundColor:[NSColor colorWithCalibratedRed:1.0 green:0.95 blue:0.72 alpha:1.0]];
    } else {
        [cell setDrawsBackground:NO];
    }
    if ([cell respondsToSelector:@selector(setTextColor:)]) {
        [cell setTextColor:style.textColor ? style.textColor : [NSColor blackColor]];
    }
}

- (NSTableRowView *)tableView:(NSTableView *)tableView rowViewForRow:(NSInteger)row
{
    (void)tableView;
    DataSheetRowView *rowView = [[DataSheetRowView alloc] init];
    rowView.groupName = ToNSString(_group);
    rowView.originalRow = [self originalRowAtVisualRow:row];
    return rowView;
}

- (NSString *)tableView:(NSTableView *)tableView
          toolTipForCell:(NSCell *)cell
                    rect:(NSRectPointer)rect
             tableColumn:(NSTableColumn *)tableColumn
                     row:(NSInteger)row
           mouseLocation:(NSPoint)mouseLocation
{
    (void)tableView; (void)cell; (void)rect; (void)mouseLocation;
    NSString *identifier = [tableColumn identifier];
    const NSInteger originalRow = [self originalRowAtVisualRow:row];
    if (originalRow <= 0 || [identifier isEqualToString:@"_row"]) return nil;
    const DataColumn *column = FindDataColumnInDataFrame(_dataFrame, [identifier UTF8String]);
    if (!column) return nil;
    const std::string tooltip = DataFrameImputationTooltipText(
        _dataFrame, *column, (std::size_t)originalRow - 1);
    return tooltip.empty() ? nil : ToNSString(tooltip);
}

- (void)tableViewSelectionDidChange:(NSNotification *)notification
{
    (void)notification;
    if (!_updatingSelection) [self.owner trellisDataTableSelectionChanged:self];
}

- (void)tableView:(NSTableView *)tableView
    sortDescriptorsDidChange:(NSArray<NSSortDescriptor *> *)oldDescriptors
{
    (void)oldDescriptors;
    if (self.owner.synchronizingTrellisTableScroll) return;
    NSSortDescriptor *descriptor = [[tableView sortDescriptors] firstObject];
    NSString *variable = [descriptor key];
    if (!descriptor || !variable || [variable isEqualToString:@"_row"]) return;
    [self.owner trellisDataTableSortVariable:variable ascending:[descriptor ascending]];
}

- (void)syncSelection:(const std::set<int> &)selection
{
    _updatingSelection = YES;
    NSMutableIndexSet *indexes = [NSMutableIndexSet indexSet];
    for (std::size_t index = 0; index < _rows.size(); ++index) {
        if (selection.find(_rows[index]) != selection.end()) [indexes addIndex:index];
    }
    [self.tableView selectRowIndexes:indexes byExtendingSelection:NO];
    _updatingSelection = NO;
}
@end

