@implementation DataSheetTableView
- (void)drawRect:(NSRect)dirtyRect
{
    [super drawRect:dirtyRect];
    NSIndexSet *selectedColumns = [self selectedColumnIndexes];
    for (NSUInteger index = [selectedColumns firstIndex]; index != NSNotFound;
         index = [selectedColumns indexGreaterThanIndex:index]) {
        if (index >= (NSUInteger)[[self tableColumns] count]) continue;
        NSTableColumn *column = [[self tableColumns] objectAtIndex:index];
        if ([[column identifier] isEqualToString:@"_row"]) continue;
        NSRect columnRect = NSIntersectionRect([self rectOfColumn:(NSInteger)index], dirtyRect);
        if (NSIsEmptyRect(columnRect)) continue;
        [[DataSheetSelectedColumnAccentColor() colorWithAlphaComponent:0.13] setFill];
        NSRectFillUsingOperation(columnRect, NSCompositingOperationSourceOver);
        [DataSheetSelectedColumnAccentColor() setFill];
        NSRectFill(NSMakeRect(NSMinX(columnRect), NSMinY(columnRect), 2.0, NSHeight(columnRect)));
        NSRectFill(NSMakeRect(NSMaxX(columnRect) - 2.0, NSMinY(columnRect), 2.0, NSHeight(columnRect)));
    }
}
@end

@interface DataSheetHeaderView : NSTableHeaderView
@property(nonatomic, assign) DataSheetWindowController *dataSheetController;
@end

@implementation DataSheetHeaderView
- (void)drawRect:(NSRect)dirtyRect
{
    NSTableView *table = [self tableView];
    NSIndexSet *selectedColumns = [table selectedColumnIndexes];
    [super drawRect:dirtyRect];
    for (NSUInteger index = [selectedColumns firstIndex]; index != NSNotFound;
         index = [selectedColumns indexGreaterThanIndex:index]) {
        if (index >= (NSUInteger)[[table tableColumns] count]) continue;
        NSTableColumn *column = [[table tableColumns] objectAtIndex:index];
        if ([[column identifier] isEqualToString:@"_row"]) continue;
        NSRect rect = NSIntersectionRect([self headerRectOfColumn:(NSInteger)index], dirtyRect);
        if (NSIsEmptyRect(rect)) continue;
        [[DataSheetSelectedColumnAccentColor() colorWithAlphaComponent:0.28] setFill];
        NSRectFillUsingOperation(rect, NSCompositingOperationSourceOver);
        [DataSheetSelectedColumnAccentColor() setFill];
        NSRectFill(NSMakeRect(NSMinX(rect), NSMinY(rect), NSWidth(rect), 3.0));
    }
}

- (void)mouseDown:(NSEvent *)event
{
    [super mouseDown:event];
    [self setNeedsDisplay:YES];
    [[self tableView] setNeedsDisplay:YES];
}

- (NSMenu *)menuForEvent:(NSEvent *)event
{
    NSPoint point = [self convertPoint:[event locationInWindow] fromView:nil];
    NSInteger column = [[self tableView] columnAtPoint:NSMakePoint(point.x, 0.0)];
    NSMenu *menu = column >= 0
        ? [self.dataSheetController dataSheetHeaderContextMenuForColumn:column] : nil;
    return SnapshotAlbumMenu(menu, @"Data Sheet");
}
@end

@implementation DataSheetWindowController
- (instancetype)initWithGroup:(const std::string &)group
{
    return [self initWithGroup:group visibleRows:{} title:""];
}

- (instancetype)initWithGroup:(const std::string &)group
                   visibleRows:(const std::vector<int> &)visibleRows
                         title:(const std::string &)title
{
    self = [super init];
    if (self) {
        _group = group;
        _usesVisibleRows = !title.empty();
        _visibleOriginalRows = visibleRows;
        _customTitle = title;
        _updatingSelection = false;
        NSRect frame = NextWindowFrameOnMain(760, 520);
        _window = [[NSWindow alloc]
            initWithContentRect:frame
                      styleMask:(NSWindowStyleMaskTitled | NSWindowStyleMaskClosable |
                                 NSWindowStyleMaskResizable | NSWindowStyleMaskMiniaturizable)
                        backing:NSBackingStoreBuffered
                          defer:NO];
        [_window setTitle:ToNSString(_customTitle.empty() ? DataFrameWindowTitle(group) : _customTitle)];
        [_window setMinSize:NSMakeSize(520, 360)];
        // Controllers remain in the dataset registries after their window is
        // closed so that it can be shown again.  Keep the native window alive
        // as well; otherwise a later linked-data refresh sends messages to a
        // released NSWindow (see the DataSheetWindowController::refresh crash).
        [_window setReleasedWhenClosed:NO];

        NSView *content = [_window contentView];
        [content setWantsLayer:YES];
        [[content layer] setBackgroundColor:[WorkbenchBackgroundColor() CGColor]];

        NSScrollView *scroll = [[NSScrollView alloc] initWithFrame:NSMakeRect(12, 42, 736, 466)];
        [scroll setAutoresizingMask:NSViewWidthSizable | NSViewHeightSizable];
        [scroll setBorderType:NSBezelBorder];
        [scroll setHasVerticalScroller:YES];
        [scroll setHasHorizontalScroller:YES];
        [scroll setDrawsBackground:YES];
        [scroll setBackgroundColor:WorkbenchSurfaceColor()];
        _table = [[DataSheetTableView alloc] initWithFrame:[[scroll contentView] bounds]];
        [_table setDelegate:self];
        [_table setDataSource:self];
        ConfigureSharedDataSheetTable(_table, false);
        NSRect headerFrame = [[_table headerView] frame];
        DataSheetHeaderView *headerView = [[DataSheetHeaderView alloc] initWithFrame:headerFrame];
        [headerView setDataSheetController:self];
        [_table setHeaderView:headerView];
        const rlispstat::core::DataSheetContextMenuTitles menuTitles = rlispstat::core::DefaultDataSheetContextMenuTitles();
        NSMenu *menu = [[NSMenu alloc] initWithTitle:ToNSString(menuTitles.root)];
        NSMenuItem *colorItem = [[NSMenuItem alloc] initWithTitle:ToNSString(menuTitles.colorSelectedRows) action:nil keyEquivalent:@""];
        NSMenu *colorMenu = [[NSMenu alloc] initWithTitle:ToNSString(menuTitles.colorSelectedRows)];
        for (const PaletteColor &color : rlispstat::core::PaletteColors()) {
            NSMenuItem *item = [[NSMenuItem alloc] initWithTitle:ToNSString(color.name) action:@selector(colorSelectedRows:) keyEquivalent:@""];
            [item setTarget:self];
            [item setRepresentedObject:ToNSString(color.name)];
            [colorMenu addItem:item];
        }
        [menu setSubmenu:colorMenu forItem:colorItem];
	        [menu addItem:colorItem];
	        [menu addItem:[[NSMenuItem alloc] initWithTitle:ToNSString(menuTitles.clearRowColor) action:@selector(clearSelectedRowColors:) keyEquivalent:@""]];
	        [menu addItem:[[NSMenuItem alloc] initWithTitle:ToNSString(menuTitles.clearAllRowColors) action:@selector(clearAllRowColors:) keyEquivalent:@""]];
	        [menu addItem:[NSMenuItem separatorItem]];
	        NSMenuItem *scopeItem = [[NSMenuItem alloc] initWithTitle:@"Analysis scope cases" action:nil keyEquivalent:@""];
	        _analysisScopeMenu = [[NSMenu alloc] initWithTitle:@"Analysis scope cases"];
	        [_analysisScopeMenu setDelegate:self];
	        [menu setSubmenu:_analysisScopeMenu forItem:scopeItem];
	        [menu addItem:scopeItem];
	        [menu addItem:[NSMenuItem separatorItem]];
	        [menu addItem:AddDataColumnSubmenuItemForGroup(_group)];
	        [menu addItem:PlotCommandMenuItem(ToNSString(menuTitles.variableView), ToNSString("OPEN_VARIABLES_WINDOW|" + _group))];
	        [menu addItem:[NSMenuItem separatorItem]];
	        [menu addItem:[[NSMenuItem alloc] initWithTitle:ToNSString(menuTitles.treatColumnAsNumeric) action:@selector(treatClickedColumnAsNumeric:) keyEquivalent:@""]];
	        [menu addItem:[[NSMenuItem alloc] initWithTitle:ToNSString(menuTitles.treatColumnAsFactor) action:@selector(treatClickedColumnAsFactor:) keyEquivalent:@""]];
	        [menu addItem:[[NSMenuItem alloc] initWithTitle:ToNSString(menuTitles.treatColumnAsText) action:@selector(treatClickedColumnAsText:) keyEquivalent:@""]];
	        [menu addItem:[[NSMenuItem alloc] initWithTitle:ToNSString(menuTitles.showVariableInformation) action:@selector(showClickedColumnInformation:) keyEquivalent:@""]];
	        for (NSMenuItem *item in [menu itemArray]) {
	            if ([item action] && ![item target]) {
	                [item setTarget:self];
	            }
	        }
	        [_table setMenu:menu];
        [scroll setDocumentView:_table];
        [content addSubview:scroll];

        _statusField = GLMLabel(@"", NSMakeRect(12, 12, 736, 22), 12, NSFontWeightRegular);
        [_statusField setAutoresizingMask:NSViewWidthSizable | NSViewMaxYMargin];
        [content addSubview:_statusField];
        [self refresh];
    }
    return self;
}

- (void)menuWillOpen:(NSMenu *)menu
{
    if (menu != _analysisScopeMenu) return;
    [_analysisScopeMenu removeAllItems];
    const std::size_t selectedCount = [self selectedRows].size();
    std::size_t totalRows = 0;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        const DataFrameModel *dataset = FindDataFrameUnlockedConst(_group);
        if (dataset) totalRows = static_cast<std::size_t>(std::max(0, dataset->rows));
    }
    NSMenuItem *selected = [[NSMenuItem alloc]
        initWithTitle:[NSString stringWithFormat:@"Selected (%lu)", (unsigned long)selectedCount]
        action:@selector(useSelectedRowsAsAnalysisScope:) keyEquivalent:@""];
    [selected setTarget:self];
    [selected setEnabled:selectedCount > 0];
    [_analysisScopeMenu addItem:selected];
    if (_usesVisibleRows) {
        NSMenuItem *visible = [[NSMenuItem alloc]
            initWithTitle:[NSString stringWithFormat:@"Visible (%lu)",
                (unsigned long)_visibleOriginalRows.size()]
            action:@selector(useVisibleRowsAsAnalysisScope:) keyEquivalent:@""];
        [visible setTarget:self];
        [visible setEnabled:!_visibleOriginalRows.empty()];
        [_analysisScopeMenu addItem:visible];
    }
    NSMenuItem *all = [[NSMenuItem alloc]
        initWithTitle:[NSString stringWithFormat:@"All (%lu)", (unsigned long)totalRows]
        action:@selector(useAllRowsAsAnalysisScope:) keyEquivalent:@""];
    [all setTarget:self];
    [_analysisScopeMenu addItem:all];
}

- (DataFrameModel)dataFrame
{
    std::lock_guard<std::mutex> lock(g_mutex);
    const DataFrameModel *df = FindDataFrameUnlockedConst(_group);
    return df ? *df : DataFrameModel();
}

- (NSInteger)dataFrameRowCount
{
    std::lock_guard<std::mutex> lock(g_mutex);
    const DataFrameModel *df = FindDataFrameUnlockedConst(_group);
    return df ? (NSInteger)df->rows : 0;
}

- (NSInteger)originalRowForVisualRow:(NSInteger)row
{
    if (row < 0) return -1;
    if (!_usesVisibleRows) return row + 1;
    return (std::size_t)row < _visibleOriginalRows.size()
        ? _visibleOriginalRows[(std::size_t)row] : -1;
}

- (std::string)displayValueForColumnName:(const std::string &)name row:(NSInteger)row
{
    if (row < 0) {
        return "";
    }
    std::lock_guard<std::mutex> lock(g_mutex);
    const DataFrameModel *found = FindDataFrameUnlockedConst(_group);
    if (!found) {
        return "";
    }
    const DataFrameModel &df = *found;
    for (const DataColumn &col : df.columns) {
        if (col.name == name) {
            return DisplayValueForDataFrameCell(df, col, (size_t)row);
        }
    }
    return "";
}

- (bool)isImputedCellForColumnName:(const std::string &)name row:(NSInteger)row
{
    if (row < 0) {
        return false;
    }
    std::lock_guard<std::mutex> lock(g_mutex);
    const DataFrameModel *found = FindDataFrameUnlockedConst(_group);
    if (!found) {
        return false;
    }
    const DataFrameModel &df = *found;
    for (const DataColumn &col : df.columns) {
        if (col.name == name) {
            return DataFrameCellIsImputed(df, col, (size_t)row);
        }
    }
    return false;
}

- (NSString *)imputationToolTipForColumnName:(const std::string &)name row:(NSInteger)row
{
    if (row < 0) {
        return nil;
    }
    std::string tooltip;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        const DataFrameModel *found = FindDataFrameUnlockedConst(_group);
        if (!found) {
            return nil;
        }
        const DataFrameModel &df = *found;
        for (const DataColumn &col : df.columns) {
            if (col.name == name) {
                tooltip = DataFrameImputationTooltipText(df, col, (size_t)row);
                break;
            }
        }
    }
    return tooltip.empty() ? nil : ToNSString(tooltip);
}

- (NSInteger)numberOfRowsInTableView:(NSTableView *)tableView
{
    (void)tableView;
    return _usesVisibleRows ? (NSInteger)_visibleOriginalRows.size() : [self dataFrameRowCount];
}

- (id)tableView:(NSTableView *)tableView objectValueForTableColumn:(NSTableColumn *)tableColumn row:(NSInteger)row
{
    (void)tableView;
    const NSInteger originalRow = [self originalRowForVisualRow:row];
    if (originalRow <= 0) return @"";
    NSString *identifier = [tableColumn identifier];
    if ([identifier isEqualToString:@"_row"]) {
        return [NSString stringWithFormat:@"%ld", (long)originalRow];
    }
    std::string name = [identifier UTF8String];
    return ToNSString([self displayValueForColumnName:name row:originalRow - 1]);
}

- (void)tableView:(NSTableView *)tableView
    setObjectValue:(id)object
    forTableColumn:(NSTableColumn *)tableColumn
               row:(NSInteger)row
{
    (void)tableView;
    NSString *identifier = [tableColumn identifier];
    const NSInteger originalRow = [self originalRowForVisualRow:row];
    if (originalRow <= 0 || [identifier isEqualToString:@"_row"]) return;
    const std::string value = object ? std::string([[object description] UTF8String]) : "";
    std::string message;
    if (!SetDataFrameCellValueForGroup(_group, std::string([identifier UTF8String]),
                                       static_cast<std::size_t>(originalRow - 1), value, &message)) {
        [_statusField setStringValue:ToNSString(message)];
        [self refresh];
        return;
    }
    [_statusField setStringValue:ToNSString(message)];
    const NSInteger column = [tableView columnWithIdentifier:identifier];
    if (column >= 0) {
        [tableView reloadDataForRowIndexes:[NSIndexSet indexSetWithIndex:(NSUInteger)row]
                            columnIndexes:[NSIndexSet indexSetWithIndex:(NSUInteger)column]];
    }
}

- (void)tableView:(NSTableView *)tableView willDisplayCell:(id)cell forTableColumn:(NSTableColumn *)tableColumn row:(NSInteger)row
{
    (void)tableView;
    const NSInteger originalRow = [self originalRowForVisualRow:row];
    DataSheetRowStyle style = DataSheetStyleForRow(_group, (int)originalRow, [_table isRowSelected:row]);
    bool imputedCell = false;
    NSString *identifier = [tableColumn identifier];
    const NSInteger visualColumn = [tableView columnWithIdentifier:identifier];
    const bool selectedColumn = visualColumn >= 0 &&
        [[tableView selectedColumnIndexes] containsIndex:(NSUInteger)visualColumn];
    if (![identifier isEqualToString:@"_row"]) {
        std::string name = [identifier UTF8String];
        imputedCell = [self isImputedCellForColumnName:name row:originalRow - 1];
    }
    if (style.customBackground) {
        [cell setDrawsBackground:YES];
        [cell setBackgroundColor:style.background];
    } else if (selectedColumn) {
        [cell setDrawsBackground:YES];
        [cell setBackgroundColor:DataSheetSelectedColumnFillColor()];
    } else if (imputedCell) {
        [cell setDrawsBackground:YES];
        [cell setBackgroundColor:[NSColor colorWithCalibratedRed:1.0 green:0.95 blue:0.72 alpha:1.0]];
    } else {
        [cell setDrawsBackground:NO];
    }
    if ([cell respondsToSelector:@selector(setTextColor:)]) {
        [cell setTextColor:style.textColor ? style.textColor : [NSColor blackColor]];
    }
}

- (NSTableRowView *)tableView:(NSTableView *)tableView rowViewForRow:(NSInteger)row
{
    (void)tableView;
    (void)row;
    return nil;
}

- (NSString *)tableView:(NSTableView *)tableView
       toolTipForCell:(NSCell *)cell
                 rect:(NSRectPointer)rect
          tableColumn:(NSTableColumn *)tableColumn
                  row:(NSInteger)row
        mouseLocation:(NSPoint)mouseLocation
{
    (void)tableView;
    (void)cell;
    (void)rect;
    (void)mouseLocation;
    NSString *identifier = [tableColumn identifier];
    if ([identifier isEqualToString:@"_row"]) {
        return nil;
    }
    std::string name = [identifier UTF8String];
    const NSInteger originalRow = [self originalRowForVisualRow:row];
    return [self imputationToolTipForColumnName:name row:originalRow - 1];
}

- (void)tableViewSelectionDidChange:(NSNotification *)notification
{
    (void)notification;
    [[_table headerView] setNeedsDisplay:YES];
    if (_updatingSelection) {
        return;
    }
    if ([[_table selectedColumnIndexes] count] > 0 &&
        [[_table selectedRowIndexes] count] == 0) {
        [_table setNeedsDisplay:YES];
        return;
    }
    std::set<int> rows;
    NSIndexSet *indexes = [_table selectedRowIndexes];
    for (NSUInteger idx = [indexes firstIndex]; idx != NSNotFound; idx = [indexes indexGreaterThanIndex:idx]) {
        const NSInteger originalRow = [self originalRowForVisualRow:(NSInteger)idx];
        if (originalRow > 0) rows.insert((int)originalRow);
    }
    bool changed = false;
    int selectionVersion = 0;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        changed = SetGroupSelectionUnlocked(_group, rows, &selectionVersion);
    }
    if (!changed) {
        return;
    }
    PublishSpreadPlotMessage("ROW_SELECTION_CHANGED", _group, "data-sheet", "", std::vector<int>(rows.begin(), rows.end()), selectionVersion);
}

- (std::vector<int>)selectedRows
{
    std::vector<int> rows;
    NSIndexSet *indexes = [_table selectedRowIndexes];
    for (NSUInteger idx = [indexes firstIndex]; idx != NSNotFound; idx = [indexes indexGreaterThanIndex:idx]) {
        const NSInteger originalRow = [self originalRowForVisualRow:(NSInteger)idx];
        if (originalRow > 0) rows.push_back((int)originalRow);
    }
    return rows;
}

- (void)colorSelectedRows:(id)sender
{
    NSString *color = [sender representedObject];
    std::vector<int> rows = [self selectedRows];
    if (rows.empty()) {
        [_statusField setStringValue:ToNSString(rlispstat::core::NoRowsSelectedStatus())];
        return;
    }
    std::string colorName = color ? [color UTF8String] : "";
    if (!rlispstat::core::FindPaletteColor(colorName)) {
        [_statusField setStringValue:ToNSString(rlispstat::core::UnknownColorStatus())];
        return;
    }
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        for (int row : rows) {
            g_groupPointColors[_group][row] = colorName;
        }
        if (!rows.empty()) {
            RequestColorSmoothRecomputeForGroupUnlocked(_group);
        }
    }
    PublishSpreadPlotMessage("ROW_COLORS_CHANGED", _group, "data-sheet", "", rows);
    RedrawGroupViewsSynchronouslyOnMain(_group, true);
    UpdatePanelOnMain();
}

- (void)clearSelectedRowColors:(id)sender
{
    (void)sender;
    std::vector<int> rows = [self selectedRows];
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        auto it = g_groupPointColors.find(_group);
        if (it != g_groupPointColors.end()) {
            for (int row : rows) {
                it->second.erase(row);
            }
        }
        if (!rows.empty()) {
            RequestColorSmoothRecomputeForGroupUnlocked(_group);
        }
    }
    PublishSpreadPlotMessage("ROW_COLORS_CHANGED", _group, "data-sheet", "", rows);
    RedrawGroupViewsSynchronouslyOnMain(_group, true);
    UpdatePanelOnMain();
}

- (void)useSelectedRowsAsAnalysisScope:(id)sender
{
    (void)sender;
    const std::vector<int> rows = [self selectedRows];
    if (rows.empty()) {
        [_statusField setStringValue:@"Select one or more rows first."];
        return;
    }
    const std::optional<std::string> description =
        PromptForNamedSelectionAnalysisScope(rows.size());
    if (!description.has_value()) return;
    std::string error;
    rlispstat::core::AnalysisScopeChangeEvent changeEvent;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        const DataFrameModel *dataset = FindDataFrameUnlockedConst(_group);
        if (!dataset) return;
        rlispstat::core::AnalysisScope scope = rlispstat::core::ExplicitAnalysisScope(
            _group, rows, rlispstat::core::AnalysisScopeSourceKind::DataTableRows,
            *description,
            static_cast<std::size_t>(std::max(0, dataset->rows)),
            std::string("data-sheet"));
        if (!MacCommandDispatcher().applicationState().setActiveAnalysisScope(scope, &changeEvent, &error)) {
            [_statusField setStringValue:ToNSString(error)];
            return;
        }
    }
    PublishSpreadPlotMessage(
        "ANALYSIS_SCOPE_CHANGED", _group, "data-sheet",
        changeEvent.currentScope.sourceDescription, {},
        static_cast<int>(changeEvent.version));
    RefreshDataDeskWindowsOnMain(_group);
    UpdatePanelOnMain();
}

- (void)useVisibleRowsAsAnalysisScope:(id)sender
{
    (void)sender;
    if (!_usesVisibleRows) return;
    std::string error;
    rlispstat::core::AnalysisScopeChangeEvent changeEvent;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        const DataFrameModel *dataset = FindDataFrameUnlockedConst(_group);
        if (!dataset) return;
        rlispstat::core::AnalysisScope scope = rlispstat::core::ExplicitAnalysisScope(
            _group, _visibleOriginalRows,
            rlispstat::core::AnalysisScopeSourceKind::VisibleObservations,
            "Rows visible in data sheet",
            static_cast<std::size_t>(std::max(0, dataset->rows)),
            std::string("data-sheet"));
        if (!MacCommandDispatcher().applicationState().setActiveAnalysisScope(scope, &changeEvent, &error)) {
            [_statusField setStringValue:ToNSString(error)];
            return;
        }
    }
    PublishSpreadPlotMessage(
        "ANALYSIS_SCOPE_CHANGED", _group, "data-sheet",
        changeEvent.currentScope.sourceDescription, {},
        static_cast<int>(changeEvent.version));
    RefreshDataDeskWindowsOnMain(_group);
    UpdatePanelOnMain();
}

- (void)useAllRowsAsAnalysisScope:(id)sender
