- (std::string)clickedColumnVariable
{
    if (!_headerContextVariable.empty()) {
        return _headerContextVariable;
    }
    NSInteger column = [_table clickedColumn];
    NSEvent *event = [NSApp currentEvent];
    if (event && column < 0) {
        NSPoint windowPoint = [event locationInWindow];
        NSPoint tablePoint = [_table convertPoint:windowPoint fromView:nil];
        column = [_table columnAtPoint:tablePoint];
        if (column < 0 && [_table headerView]) {
            NSPoint headerPoint = [[_table headerView] convertPoint:windowPoint fromView:nil];
            column = [_table columnAtPoint:NSMakePoint(headerPoint.x, 0)];
        }
    }
    if (column < 0 || column >= (NSInteger)[[_table tableColumns] count]) {
        return "";
    }
    NSTableColumn *tableColumn = [[_table tableColumns] objectAtIndex:(NSUInteger)column];
    NSString *identifier = [tableColumn identifier];
    if ([identifier isEqualToString:@"_row"]) {
        return "";
    }
    return std::string([identifier UTF8String]);
}

- (std::vector<std::string>)selectedColumnVariablesForAction
{
    if (!_headerContextVariable.empty()) {
        return {_headerContextVariable};
    }
    std::vector<std::string> selected;
    NSIndexSet *indexes = [_table selectedColumnIndexes];
    for (NSUInteger index = [indexes firstIndex]; index != NSNotFound;
         index = [indexes indexGreaterThanIndex:index]) {
        if (index >= (NSUInteger)[[_table tableColumns] count]) continue;
        NSString *identifier = [[[_table tableColumns] objectAtIndex:index] identifier];
        if (identifier && ![identifier isEqualToString:@"_row"]) {
            selected.push_back(std::string([identifier UTF8String]));
        }
    }
    const std::string clicked = [self clickedColumnVariable];
    if (!clicked.empty() &&
        std::find(selected.begin(), selected.end(), clicked) == selected.end()) {
        return {clicked};
    }
    return selected.empty() && !clicked.empty() ? std::vector<std::string>{clicked} : selected;
}

- (void)setClickedColumnType:(const std::string &)type
{
    const std::vector<std::string> variables = [self selectedColumnVariablesForAction];
    if (variables.empty()) {
        [_statusField setStringValue:ToNSString(DataSheetChooseDataColumnStatus())];
        return;
    }
    std::vector<std::string> failures;
    for (const std::string &variable : variables) {
        std::string message;
        if (!SetVariableAnalysisType(_group, variable, type, &message)) {
            failures.push_back(variable + ": " + message);
        }
    }
    if (!failures.empty()) {
        [_statusField setStringValue:ToNSString(failures.front())];
    } else if (variables.size() == 1) {
        [_statusField setStringValue:ToNSString(
            rlispstat::core::VariableTypeChangedStatus(variables.front(), type))];
    } else {
        [_statusField setStringValue:ToNSString(
            std::to_string(variables.size()) + " selected variables changed to " + type + ".")];
    }
    [self refresh];
    _headerContextVariable.clear();
}

- (void)setClickedColumnTypeFromMenu:(id)sender
{
    NSString *type = [sender representedObject];
    if (type) [self setClickedColumnType:NormalizeVariableType(std::string([type UTF8String]))];
}

