        [content addSubview:_badgeField];

        _methodPopup = [[NSPopUpButton alloc] initWithFrame:NSMakeRect(16, 488, 156, 26)];
        [_methodPopup addItemWithTitle:ToNSString(rlispstat::core::DimensionalityPCAMethodTitle())];
        [_methodPopup addItemWithTitle:ToNSString(rlispstat::core::DimensionalityFactorAnalysisMethodTitle())];
        [_methodPopup setTarget:self];
        [_methodPopup setAction:@selector(methodChanged:)];
        [content addSubview:_methodPopup];

        _missingPopup = [[NSPopUpButton alloc] initWithFrame:NSMakeRect(184, 488, 112, 26)];
        [_missingPopup addItemWithTitle:ToNSString(rlispstat::core::MissingDataListwiseMethodLabel())];
        [_missingPopup addItemWithTitle:ToNSString(rlispstat::core::MissingDataPairwiseMethodLabel())];
        [_missingPopup setTarget:self];
        [_missingPopup setAction:@selector(missingChanged:)];
        [content addSubview:_missingPopup];

        _componentsPopup = [[NSPopUpButton alloc] initWithFrame:NSMakeRect(308, 488, 116, 26)];
        [_componentsPopup setTarget:self];
        [_componentsPopup setAction:@selector(componentsChanged:)];
        [content addSubview:_componentsPopup];

        _rotationPopup = [[NSPopUpButton alloc] initWithFrame:NSMakeRect(438, 488, 118, 26)];
        [_rotationPopup addItemWithTitle:ToNSString(rlispstat::core::DimensionalityNoRotationTitle())];
        [_rotationPopup addItemWithTitle:ToNSString(rlispstat::core::DimensionalityVarimaxRotationTitle())];
        [_rotationPopup addItemWithTitle:ToNSString(rlispstat::core::DimensionalityQuartimaxRotationTitle())];
        [_rotationPopup setTarget:self];
        [_rotationPopup setAction:@selector(rotationChanged:)];
        [content addSubview:_rotationPopup];

        _scopeLabel = GLMLabel(ToNSString(rlispstat::core::GLMScopeFieldLabel()), NSMakeRect(570, 490, 46, 22), 12, NSFontWeightRegular);
        [content addSubview:_scopeLabel];
        _scopePopup = [[NSPopUpButton alloc] initWithFrame:NSMakeRect(616, 486, 138, 28)];
        [_scopePopup addItemWithTitle:ToNSString(rlispstat::core::ScopeAllDataTitle())];
        [_scopePopup addItemWithTitle:ToNSString(rlispstat::core::ScopeSelectedRowsTitle())];
        [_scopePopup addItemWithTitle:ToNSString(rlispstat::core::ScopeUnselectedRowsTitle())];
        [_scopePopup setTarget:self];
        [_scopePopup setAction:@selector(scopeChanged:)];
        [content addSubview:_scopePopup];

        _scaleButton = [[NSButton alloc] initWithFrame:NSMakeRect(16, 456, 120, 22)];
        [_scaleButton setButtonType:NSButtonTypeSwitch];
        [_scaleButton setTitle:ToNSString(rlispstat::core::DimensionalityStandardizeButtonTitle())];
        [_scaleButton setTarget:self];
        [_scaleButton setAction:@selector(scaleChanged:)];
        [content addSubview:_scaleButton];

        _selectedRowsField = GLMRightLabel(@"", NSMakeRect(590, 458, 164, 20), 12, NSFontWeightRegular);
        [content addSubview:_selectedRowsField];

        _scrollView = [[NSScrollView alloc] initWithFrame:NSMakeRect(12, 44, 756, 404)];
        [_scrollView setBorderType:NSNoBorder];
        [_scrollView setDrawsBackground:NO];
        [_scrollView setHasVerticalScroller:YES];
        [_scrollView setHasHorizontalScroller:YES];
        [_scrollView setAutohidesScrollers:YES];
        _reportView = [[DimensionalityView alloc] initWithController:self];
        [_scrollView setDocumentView:_reportView];
        [content addSubview:_scrollView];

        _statusField = GLMLabel(@"", NSMakeRect(16, 14, 740, 20), 12, NSFontWeightRegular);
        [content addSubview:_statusField];
    }
    return self;
}

- (DimensionalityState *)state
{
    auto it = g_dimensionalityModels.find(_modelId);
    return it == g_dimensionalityModels.end() ? nullptr : &it->second;
}

- (void)show
{
    EnableNotesForWindow(_window, _modelId, @"this dimensionality analysis");
    [_window makeKeyAndOrderFront:nil];
    [NSApp activateIgnoringOtherApps:YES];
    [self refresh];
}

- (void)refresh
{
    DimensionalityState *state = [self state];
    if (!state) return;
    BuildSeedPlotForGroup(state->group, state->seed);
    RefitDimensionalityState(*state);
    DimensionalityControlState controls = BuildDimensionalityControlState(
        state->method,
        state->missingMode,
        state->rotation,
        state->scope,
        state->scale,
        state->variables.size(),
        state->componentCount);
    state->componentCount = controls.componentCount;
    [_badgeField setStringValue:ToNSString(state->group)];
    [_methodPopup selectItemAtIndex:controls.methodIndex];
    [_missingPopup selectItemWithTitle:ToNSString(controls.missingMode)];
    [_rotationPopup selectItemAtIndex:controls.rotationIndex];
    [_scopePopup selectItemAtIndex:controls.scopeIndex];
    [_scaleButton setState:controls.scale ? NSControlStateValueOn : NSControlStateValueOff];
    [_componentsPopup removeAllItems];
    for (const std::string &label : controls.componentOptions) {
        [_componentsPopup addItemWithTitle:ToNSString(label)];
    }
    [_componentsPopup selectItemAtIndex:controls.componentIndex];

    NSSize reportSize = [_reportView preferredContentSize];
    NSScreen *screen = [_window screen] ?: [NSScreen mainScreen];
    NSRect visible = screen ? [screen visibleFrame] : NSMakeRect(0, 0, 1200, 800);
    DimensionalityWindowLayout windowLayout = BuildDimensionalityWindowLayout(
        reportSize.width, reportSize.height, visible.size.width, visible.size.height);
    CGFloat targetWidth = (CGFloat)windowLayout.targetWidth;
    CGFloat targetHeight = (CGFloat)windowLayout.targetHeight;
    [_window setContentMaxSize:NSMakeSize((CGFloat)windowLayout.maxWidth, (CGFloat)windowLayout.maxHeight)];
    NSSize current = [[_window contentView] frame].size;
    if (std::fabs(current.width - targetWidth) > 0.5 || std::fabs(current.height - targetHeight) > 0.5) {
        [_window setContentSize:NSMakeSize(targetWidth, targetHeight)];
    }
    [_titleField setFrame:rlispstat::platform::macos::ToNSRect(windowLayout.titleRect)];
    [_badgeField setFrame:rlispstat::platform::macos::ToNSRect(windowLayout.badgeRect)];
    [_methodPopup setFrame:rlispstat::platform::macos::ToNSRect(windowLayout.methodPopupRect)];
    [_missingPopup setFrame:rlispstat::platform::macos::ToNSRect(windowLayout.missingPopupRect)];
    [_componentsPopup setFrame:rlispstat::platform::macos::ToNSRect(windowLayout.componentsPopupRect)];
    [_rotationPopup setFrame:rlispstat::platform::macos::ToNSRect(windowLayout.rotationPopupRect)];
    [_scopeLabel setFrame:rlispstat::platform::macos::ToNSRect(windowLayout.scopeLabelRect)];
    [_scopePopup setFrame:rlispstat::platform::macos::ToNSRect(windowLayout.scopePopupRect)];
    [_scaleButton setFrame:rlispstat::platform::macos::ToNSRect(windowLayout.scaleButtonRect)];
    [_selectedRowsField setFrame:rlispstat::platform::macos::ToNSRect(windowLayout.selectedRowsRect)];
    [_scrollView setFrame:rlispstat::platform::macos::ToNSRect(windowLayout.scrollViewRect)];
    [_statusField setFrame:rlispstat::platform::macos::ToNSRect(windowLayout.statusRect)];
    NSSize visibleSize = [_scrollView contentSize];
    [_reportView setFrame:NSMakeRect(0, 0, std::max(reportSize.width, visibleSize.width), std::max(reportSize.height, visibleSize.height))];
    [_reportView setNeedsDisplay:YES];
    std::string status = state->status;
    if (state->dataScopeCaptured) {
        status += " · " + rlispstat::core::AnalysisScopeWindowSummary(
            state->dataScope, state->dataScope.totalDatasetRows);
    }
    [_statusField setStringValue:ToNSString(status)];
    [_selectedRowsField setStringValue:ToNSString(SelectedRowsStatus(SelectionCount(state->group),
                                                                      RowCountForGroup(state->group)))];
    RefreshOpenDimensionalityPlots(state->id);
}

