- (void)showAnalysisMenuAtPoint:(NSPoint)point inView:(NSView *)view
{
    DimensionalityState *state = [self state];
    if (!state) return;
    DimensionalityAnalysisMenuState menuState = BuildDimensionalityAnalysisMenuState(
        state->components.size(), state->componentCount, state->scores.size());
    NSMenu *menu = [[NSMenu alloc] initWithTitle:ToNSString(menuState.title)];
    NSMenuItem *scree = [[NSMenuItem alloc] initWithTitle:ToNSString(menuState.screePlotTitle)
                                                   action:@selector(openScreePlot:)
                                            keyEquivalent:@""];
    [scree setTarget:self];
    [scree setEnabled:menuState.canOpenScreePlot];
    [menu addItem:scree];
    NSMenuItem *biplot = [[NSMenuItem alloc] initWithTitle:ToNSString(menuState.biplotTitle)
                                                    action:@selector(openBiplot:)
                                             keyEquivalent:@""];
    [biplot setTarget:self];
    [biplot setEnabled:menuState.canOpenBiplot];
    [menu addItem:biplot];
    NSMenuItem *scores = [[NSMenuItem alloc] initWithTitle:ToNSString(menuState.saveScoresTitle)
                                                    action:@selector(saveScores:)
                                             keyEquivalent:@""];
    [scores setTarget:self];
    [scores setEnabled:menuState.canSaveScores];
    [menu addItem:scores];
    [menu addItem:[NSMenuItem separatorItem]];
    NSMenuItem *add = [[NSMenuItem alloc] initWithTitle:ToNSString(menuState.addVariableTitle)
                                                 action:@selector(addVariableFromContextMenu:)
                                          keyEquivalent:@""];
    [add setTarget:self];
    [menu addItem:add];
    AddSnapshotAlbumContextItems(menu);
    [menu popUpMenuPositioningItem:nil atLocation:point inView:view];
}

- (void)addVariableFromContextMenu:(id)sender
{
    (void)sender;
    DimensionalityReportLayout layout = [_reportView reportLayout];
    NSRect rect = rlispstat::platform::macos::ToNSRect(layout.addVariableRect);
    [self showAddVariableMenuAtPoint:NSMakePoint(NSMinX(rect) + 8.0, NSMaxY(rect)) inView:_reportView];
}

- (void)showAddVariableMenuAtPoint:(NSPoint)point inView:(NSView *)view
{
    DimensionalityState *state = [self state];
    if (!state) return;
    BuildSeedPlotForGroup(state->group, state->seed);
    NSMenu *menu = [[NSMenu alloc] initWithTitle:ToNSString(rlispstat::core::DimensionalityAddVariableMenuTitle())];
    std::vector<std::string> available = rlispstat::core::NumericVariableNames(&state->seed);
    DimensionalityAddVariableMenuState menuState = BuildDimensionalityAddVariableMenuState(
        state->variables, available);
    for (const std::string &name : menuState.variables) {
        NSMenuItem *item = [[NSMenuItem alloc] initWithTitle:ToNSString(name) action:@selector(addVariableFromMenu:) keyEquivalent:@""];
        [item setTarget:self];
        [item setRepresentedObject:ToNSString(name)];
        [menu addItem:item];
    }
    if ([[menu itemArray] count] == 0) {
        NSMenuItem *item = [[NSMenuItem alloc] initWithTitle:ToNSString(menuState.emptyTitle) action:nil keyEquivalent:@""];
        [item setEnabled:NO];
        [menu addItem:item];
    }
    [menu popUpMenuPositioningItem:nil atLocation:point inView:view];
}

- (void)addVariableFromMenu:(id)sender
{
    NSString *nameString = [sender representedObject];
    DimensionalityState *state = [self state];
    if (!nameString || !state) return;
    BuildSeedPlotForGroup(state->group, state->seed);
    std::string name = [nameString UTF8String];
    std::vector<std::string> available = rlispstat::core::NumericVariableNames(&state->seed);
    DimensionalityVariableUpdateResult result = DimensionalityVariablesAfterAdd(
        state->variables, name, available);
    if (!result.ok) {
        bool alreadyIncluded = std::find(state->variables.begin(), state->variables.end(), name) != state->variables.end();
        [_statusField setStringValue:ToNSString(alreadyIncluded
            ? DimensionalityVariableAlreadyIncludedStatus(name)
            : DimensionalityVariableUnavailableStatus(name))];
        return;
    }
    state->variables = result.variables;
    [self refresh];
    NSInteger index = (NSInteger)state->variables.size() - 1;
    DimensionalityReportLayout layout = [_reportView reportLayout];
    NSRect rect = rlispstat::platform::macos::ToNSRect(
        DimensionalityReportRectForVariableIndex(layout, static_cast<std::size_t>(index)));
    [_reportView scrollRectToVisible:NSInsetRect(rect, -6.0, -6.0)];
    [_statusField setStringValue:ToNSString(DimensionalityVariableAddedStatus(name))];
}

- (void)showVariableMenuForIndex:(NSInteger)index atPoint:(NSPoint)point inView:(NSView *)view
{
    DimensionalityState *state = [self state];
    if (!state || index < 0 || (size_t)index >= state->variables.size()) return;
    BuildSeedPlotForGroup(state->group, state->seed);
    std::vector<std::string> available = rlispstat::core::NumericVariableNames(&state->seed);
    DimensionalityVariableMenuState menuState = BuildDimensionalityVariableMenuState(
        state->variables, available, static_cast<std::size_t>(index));
    if (!menuState.ok) return;
    NSMenu *menu = [[NSMenu alloc] initWithTitle:ToNSString(rlispstat::core::DimensionalityVariableMenuTitle())];
    NSMenuItem *replace = [[NSMenuItem alloc] initWithTitle:ToNSString(rlispstat::core::DimensionalityReplaceVariableMenuTitle()) action:nil keyEquivalent:@""];
    NSMenu *replaceMenu = [[NSMenu alloc] initWithTitle:ToNSString(rlispstat::core::DimensionalityReplaceVariableMenuTitle())];
    for (const std::string &name : menuState.replacementVariables) {
        NSMenuItem *item = [[NSMenuItem alloc] initWithTitle:ToNSString(name) action:@selector(replaceVariableFromMenu:) keyEquivalent:@""];
        [item setTarget:self];
        [item setRepresentedObject:@[ @(index), ToNSString(name) ]];
        [replaceMenu addItem:item];
    }
    if ([[replaceMenu itemArray] count] == 0) {
        NSMenuItem *item = [[NSMenuItem alloc] initWithTitle:ToNSString(menuState.replacementEmptyTitle) action:nil keyEquivalent:@""];
        [item setEnabled:NO];
        [replaceMenu addItem:item];
    }
    [menu setSubmenu:replaceMenu forItem:replace];
    [menu addItem:replace];
    NSMenuItem *remove = [[NSMenuItem alloc] initWithTitle:ToNSString(menuState.removeTitle)
                                                    action:@selector(removeVariableFromMenu:) keyEquivalent:@""];
    [remove setTarget:self];
    [remove setRepresentedObject:@(index)];
    [remove setEnabled:menuState.canRemove];
    [menu addItem:remove];
    [menu addItem:[NSMenuItem separatorItem]];
    NSMenuItem *info = [[NSMenuItem alloc] initWithTitle:ToNSString(rlispstat::core::DimensionalityShowVariableInformationTitle()) action:@selector(showVariableInformation:) keyEquivalent:@""];
    [info setTarget:self];
    [info setRepresentedObject:@(index)];
    [menu addItem:info];
    AddSnapshotAlbumContextItems(menu);
    [menu popUpMenuPositioningItem:nil atLocation:point inView:view];
}

- (void)replaceVariableFromMenu:(id)sender
{
    NSArray *represented = [sender representedObject];
    DimensionalityState *state = [self state];
    if (!state || ![represented isKindOfClass:[NSArray class]] || [represented count] < 2) return;
    NSInteger index = [[represented objectAtIndex:0] integerValue];
    NSString *nameString = [represented objectAtIndex:1];
    if (index < 0 || (size_t)index >= state->variables.size() || !nameString) return;
    BuildSeedPlotForGroup(state->group, state->seed);
    std::string name = [nameString UTF8String];
    std::string oldName = state->variables[(size_t)index];
    std::vector<std::string> available = rlispstat::core::NumericVariableNames(&state->seed);
    DimensionalityVariableUpdateResult result = DimensionalityVariablesAfterReplace(
        state->variables, static_cast<std::size_t>(index), name, available);
    if (!result.ok) {
        [_statusField setStringValue:ToNSString(DimensionalityVariableUnavailableStatus(name))];
        return;
    }
    if (state->focusedVariable == oldName) {
        state->focusedVariable = name;
    }
    state->variables = result.variables;
    [self refresh];
    DimensionalityReportLayout layout = [_reportView reportLayout];
    NSRect rect = rlispstat::platform::macos::ToNSRect(
        DimensionalityReportRectForVariableIndex(layout, static_cast<std::size_t>(index)));
    [_reportView scrollRectToVisible:NSInsetRect(rect, -6.0, -6.0)];
    [_statusField setStringValue:ToNSString(DimensionalityVariableReplacedStatus(oldName, name))];
}

- (void)removeVariableFromMenu:(id)sender
{
    DimensionalityState *state = [self state];
    if (!state) return;
    NSInteger index = [[sender representedObject] integerValue];
    if (index < 0 || (size_t)index >= state->variables.size()) return;
    std::string name = state->variables[(size_t)index];
    DimensionalityVariableUpdateResult result = DimensionalityVariablesAfterRemove(
        state->variables, static_cast<std::size_t>(index));
    if (!result.ok) return;
    state->variables = result.variables;
    [self refresh];
    [_statusField setStringValue:ToNSString(DimensionalityVariableRemovedStatus(name))];
}

- (void)showVariableInformation:(id)sender
{
    DimensionalityState *state = [self state];
    if (!state) return;
    NSInteger index = [[sender representedObject] integerValue];
    if (index < 0 || (size_t)index >= state->variables.size()) return;
    ShowWorkbenchMessageOnMain(ToNSString(VariableInformationDialogTitle()), ToNSString(VariableInformationText(state->group, state->variables[(size_t)index])));
}

- (void)openScreePlot:(id)sender
{
    (void)sender;
    DimensionalityState *state = [self state];
    if (!state || state->components.empty()) return;
    PlotModel *plot = new PlotModel(state->seed);
    plot->kind = "pca_scree";
    plot->id = "scree_" + state->group + "_" + std::to_string((long long)time(nullptr));
    plot->dimensionalityModelId = state->id;
    if (!RefreshDimensionalityScreePlot(plot)) {
        delete plot;
        return;
    }
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        (void)AttachPlotModelUnlocked(plot);
        MarkActiveDatasetGroupUnlocked(plot->group);
    }
    AddPlotOnMain(plot);
}

- (void)openBiplot:(id)sender
{
    (void)sender;
    DimensionalityState *state = [self state];
    if (!state || state->componentCount < 2 || state->scores.empty()) {
        [_statusField setStringValue:ToNSString(DimensionalityBiplotRequiresTwoComponentsStatus())];
        return;
    }
    PlotModel *plot = new PlotModel(state->seed);
    plot->kind = "pca_biplot";
    plot->id = "biplot_" + state->group + "_" + std::to_string((long long)time(nullptr));
    plot->dimensionalityModelId = state->id;
    plot->biplotXComponent = 1;
    plot->biplotYComponent = 2;
    RefreshDimensionalityBiplotPlot(plot);
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        (void)AttachPlotModelUnlocked(plot);
        MarkActiveDatasetGroupUnlocked(plot->group);
    }
    AddPlotOnMain(plot);
}

- (void)saveScores:(id)sender
{
    (void)sender;
    DimensionalityState *state = [self state];
    if (!state || state->scores.empty()) {
        [_statusField setStringValue:ToNSString(DimensionalityNoScoresStatus())];
        return;
    }
    RefitDimensionalityState(*state);
    std::string group = state->group;
    std::vector<std::string> addedNames;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        DataFrameModel *found = FindDataFrameUnlocked(group);
        if (!found) {
            [_statusField setStringValue:ToNSString(DimensionalitySourceSheetUnavailableStatus())];
            return;
        }
        DataFrameModel &df = *found;
        std::vector<std::string> existing;
        existing.reserve(df.columns.size());
        for (const DataColumn &col : df.columns) existing.push_back(col.name);
        DimensionalityScoreExportPlan plan = BuildDimensionalityScoreExportPlan(
            state->scores,
            state->method,
            state->componentCount,
            static_cast<int>(state->components.size()),
            df.rows,
            existing
        );
        for (const DimensionalityScoreExportColumn &planned : plan.columns) {
            DataColumn col;
            col.name = planned.name;
            col.type = "numeric";
            col.values = planned.values;
            df.columns.push_back(col);
            addedNames.push_back(planned.name);
            const DataColumn &newCol = df.columns.back();
            SyncDataColumnToGroupSeedsUnlocked(group, newCol);
        }
    }
    RefreshDataDeskWindowsOnMain(group);
    RedrawGroupViewsSynchronouslyOnMain(group, true);
    UpdatePanelOnMain();
    [_statusField setStringValue:ToNSString(DimensionalityScoresSavedStatus(addedNames.size()))];
}

- (void)redrawDimensionalityFocusWithComponent:(NSInteger)component variable:(NSString *)variable scroll:(BOOL)scroll
{
    [_reportView setNeedsDisplay:YES];
    if (!scroll) return;
    DimensionalityReportState report = [_reportView reportState];
    DimensionalityReportLayout layout = rlispstat::core::BuildDimensionalityReportLayout(report);
    NSRect rect = rlispstat::platform::macos::ToNSRect(
        DimensionalityReportFocusRect(report, layout, (int)component, variable ? [variable UTF8String] : ""));
    if (!NSEqualRects(rect, NSZeroRect)) {
        [_reportView scrollRectToVisible:NSInsetRect(rect, -8.0, -6.0)];
    }
}

- (void)windowWillClose:(NSNotification *)notification
{
    (void)notification;
    g_dimensionalityControllers.erase(_modelId);
}
@end

static void RedrawDimensionalityFocusViewsOnMain(const std::string &modelId,
                                                 int component,
                                                 const std::string &variable,
                                                 bool scrollReport)
{
    std::string modelIdCopy = modelId;
    std::string variableCopy = variable;
    dispatch_async(dispatch_get_main_queue(), ^{
      auto controllerIt = g_dimensionalityControllers.find(modelIdCopy);
      if (controllerIt != g_dimensionalityControllers.end()) {
          [controllerIt->second redrawDimensionalityFocusWithComponent:component
                                                               variable:ToNSString(variableCopy)
                                                                 scroll:scrollReport];
      }
      std::vector<std::string> plotIds;
      {
          std::lock_guard<std::mutex> lock(g_mutex);
          for (const auto &entry : g_plots) {
              PlotModel *plot = entry.second;
              if (plot && plot->dimensionalityModelId == modelIdCopy) {
                  plotIds.push_back(plot->id);
              }
          }
      }
      for (const std::string &plotId : plotIds) {
          RedrawPlotOnMain(plotId);
      }
    });
}

static void SetDimensionalityFocusedComponentOnMain(const std::string &modelId, int component, bool scrollReport)
{
    SetDimensionalityFocusOnMain(modelId, component, "", scrollReport);
}

static void SetDimensionalityFocusedVariableOnMain(const std::string &modelId, const std::string &variable, bool scrollReport)
{
    SetDimensionalityFocusOnMain(modelId, 0, variable, scrollReport);
}

static void SetDimensionalityFocusOnMain(const std::string &modelId,
                                         int component,
                                         const std::string &variable,
                                         bool scrollReport)
{
    int normalizedComponent = std::max(0, component);
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        auto it = g_dimensionalityModels.find(modelId);
        if (it == g_dimensionalityModels.end()) return;
        it->second.focusedComponent = normalizedComponent;
        it->second.focusedVariable = variable;
    }
    RedrawDimensionalityFocusViewsOnMain(modelId, normalizedComponent, variable, scrollReport);
}

static void ClearDimensionalityFocusOnMain(const std::string &modelId)
{
    SetDimensionalityFocusOnMain(modelId, 0, "", false);
}

@class DendrogramView;

