{
    std::string _dendrogramId;
    NSWindow *_window;
    NSTextField *_titleField;
    NSTextField *_badgeField;
    NSTextField *_linkageLabel;
    NSPopUpButton *_linkagePopup;
    NSTextField *_missingLabel;
    NSPopUpButton *_missingPopup;
    NSTextField *_distanceLabel;
    NSButton *_variablesButton;
    NSScrollView *_scrollView;
    DendrogramView *_dendrogramView;
    NSTextField *_statusField;
}
- (instancetype)initWithDendrogramId:(const std::string &)dendrogramId;
- (DendrogramState *)state;
- (void)show;
- (void)refresh;
- (void)showVariablesMenu:(id)sender;
- (void)toggleVariableFromMenu:(id)sender;
@end

@interface DendrogramView : NSView {
    DendrogramPlotGeometry _geometry;
    BOOL _dragging;
    NSPoint _dragStart;
    NSPoint _dragCurrent;
}
@property(nonatomic, assign) DendrogramWindowController *controller;
- (instancetype)initWithController:(DendrogramWindowController *)controller;
- (NSSize)preferredContentSize;
- (BOOL)savePNGToPath:(NSString *)path;
- (BOOL)savePDFToPath:(NSString *)path;
- (BOOL)saveSVGToPath:(NSString *)path;
- (std::string)dendrogramSvgDocument;
@end

@implementation DendrogramView

- (NSString *)snapshotTabDelimitedText
{
    DendrogramState *state = [_controller state];
    if (!state) return @"";
    std::ostringstream text;
    text << "Dendrogram\nDistance\t" << state->distance
         << "\nLinkage\t" << state->linkage
         << "\nMissing-data handling\t" << state->missingMode
         << "\nVariables\t";
    for (std::size_t index = 0; index < state->variables.size(); ++index) {
        if (index) text << ", ";
        text << state->variables[index];
    }
    text << "\nCases\t" << state->caseRows.size();
    return ToNSString(text.str());
}

- (instancetype)initWithController:(DendrogramWindowController *)controller
{
    self = [super initWithFrame:NSMakeRect(0, 0, 760, 420)];
    if (self) {
        _controller = controller;
        [self setAutoresizingMask:NSViewNotSizable];
    }
    return self;
}

- (BOOL)isFlipped
{
    return YES;
}

- (BOOL)acceptsFirstResponder
{
    return YES;
}

- (NSSize)preferredContentSize
{
    DendrogramState *state = [_controller state];
    DendrogramSize size = DendrogramPreferredContentSize(state ? state->caseRows.size() : 0);
    return NSMakeSize((CGFloat)size.width, (CGFloat)size.height);
}

- (NSDictionary *)attrsWithSize:(CGFloat)size weight:(NSFontWeight)weight color:(NSColor *)color align:(NSTextAlignment)align
{
    NSMutableParagraphStyle *style = [[NSMutableParagraphStyle alloc] init];
    [style setAlignment:align];
    [style setLineBreakMode:NSLineBreakByTruncatingTail];
    return @{
        NSFontAttributeName: [NSFont systemFontOfSize:size weight:weight],
        NSForegroundColorAttributeName: color,
        NSParagraphStyleAttributeName: style
    };
}

- (void)publishSelection:(const std::set<int> &)rows event:(NSEvent *)event
{
    DendrogramState *state = [_controller state];
    if (!state) return;
    std::string mode = EffectiveSelectionMode(&state->seed, [event modifierFlags]);
    if (mode == "toggle") mode = "replace";
    int selectionVersion = 0;
    if (MergeSelection(state->group, rows, mode, &selectionVersion)) {
        PublishSpreadPlotMessage("ROW_SELECTION_CHANGED", state->group, state->id, "", std::vector<int>(rows.begin(), rows.end()), selectionVersion);
    }
    [self setNeedsDisplay:YES];
    [_controller refresh];
    UpdatePanelOnMain();
}

- (void)drawRect:(NSRect)dirtyRect
{
    (void)dirtyRect;
    _geometry = DendrogramPlotGeometry();
    PlotThemeStyle theme = CurrentPlotThemeStyle();
    [theme.background setFill];
    NSRectFill([self bounds]);

    DendrogramState *state = [_controller state];
    if (!state) return;

    NSDictionary *mutedAttrs = [self attrsWithSize:12 weight:NSFontWeightRegular color:theme.mutedText align:NSTextAlignmentLeft];
    NSDictionary *leafAttrs = [self attrsWithSize:11 weight:NSFontWeightRegular color:theme.text align:NSTextAlignmentCenter];

    NSInteger n = (NSInteger)state->caseRows.size();
    if (n == 0) {
        [ToNSString(rlispstat::core::NoCompleteCasesStatus()) drawInRect:NSMakeRect(20, 48, 520, 20) withAttributes:mutedAttrs];
        return;
    }

    NSRect bounds = [self bounds];
    _geometry = BuildDendrogramPlotGeometry(
        state->caseRows,
        state->merges,
        state->leafOrder,
        bounds.size.width,
        bounds.size.height);
    NSRect plotRect = rlispstat::platform::macos::ToNSRect(_geometry.plotRect);

    [theme.majorGrid setStroke];
    NSBezierPath *axes = [NSBezierPath bezierPath];
    [axes setLineWidth:1.0];
    [axes moveToPoint:NSMakePoint(plotRect.origin.x, plotRect.origin.y)];
    [axes lineToPoint:NSMakePoint(plotRect.origin.x, NSMaxY(plotRect))];
    [axes moveToPoint:NSMakePoint(plotRect.origin.x, NSMaxY(plotRect))];
    [axes lineToPoint:NSMakePoint(NSMaxX(plotRect), NSMaxY(plotRect))];
    [axes stroke];

    for (const DendrogramLeafGeometry &leaf : _geometry.leaves) {
        if (leaf.showLabel) {
            [ToNSString(leaf.label) drawInRect:rlispstat::platform::macos::ToNSRect(leaf.labelRect)
                                withAttributes:leafAttrs];
        }
    }

    [theme.axis setStroke];
    NSBezierPath *branches = [NSBezierPath bezierPath];
    [branches setLineWidth:1.8];
    for (const DendrogramBranchSegment &segment : _geometry.branches) {
        [branches moveToPoint:NSMakePoint(segment.start.x, segment.start.y)];
        [branches lineToPoint:NSMakePoint(segment.end.x, segment.end.y)];
    }
    [branches stroke];

    std::set<int> selection;
    std::map<int, std::string> rowColors;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        auto sit = g_groupSelections.find(state->group);
        if (sit != g_groupSelections.end()) selection = sit->second;
        auto cit = g_groupPointColors.find(state->group);
        if (cit != g_groupPointColors.end()) rowColors = cit->second;
    }
    BOOL hasSelection = !selection.empty();
    for (const DendrogramLeafGeometry &leaf : _geometry.leaves) {
        int row = leaf.rowId;
        NSPoint p = NSMakePoint(leaf.point.x, leaf.point.y);
        BOOL selected = selection.find(row) != selection.end();
        std::string rowColor;
        auto colorIt = rowColors.find(row);
        if (colorIt != rowColors.end()) rowColor = colorIt->second;
        if (selected) {
            NSColor *selectedColor = theme.coordinatedMarks && rowColor.empty()
                ? theme.selectedMarkFill : ColorForName(rowColor.empty() ? "black" : rowColor, 1.0);
            [[selectedColor colorWithAlphaComponent:0.22] setFill];
            [[NSBezierPath bezierPathWithOvalInRect:NSMakeRect(p.x - 7.0, p.y - 7.0, 14.0, 14.0)] fill];
            [selectedColor setFill];
            const CGFloat radius = theme.coordinatedMarks ? 4.0 * (CGFloat)theme.selectedMarkScale : 4.0;
            NSBezierPath *dot = rowColor.empty()
                ? PlotThemeMarkPath(theme, p, radius, true)
                : [NSBezierPath bezierPathWithOvalInRect:NSMakeRect(p.x - radius, p.y - radius,
                                                                    radius * 2.0, radius * 2.0)];
            [dot fill];
            [(theme.coordinatedMarks ? theme.selectedMarkStroke : [selectedColor colorWithAlphaComponent:0.90]) setStroke];
            [dot setLineWidth:theme.coordinatedMarks ? (CGFloat)theme.selectedMarkStrokeWidth : 0.9];
            [dot stroke];
        } else if (!rowColor.empty()) {
            [ColorForName(rowColor, hasSelection ? 0.36 : 0.78) setFill];
            NSBezierPath *dot = [NSBezierPath bezierPathWithOvalInRect:NSMakeRect(p.x - 3.4, p.y - 3.4, 6.8, 6.8)];
            [dot fill];
            [ColorForName(rowColor, hasSelection ? 0.26 : 0.58) setStroke];
            [dot setLineWidth:0.7];
            [dot stroke];
        } else {
            [(theme.coordinatedMarks
                ? (theme.hollowUnselectedMarks ? theme.panel : theme.markFill)
                : [NSColor colorWithCalibratedWhite:0.10 alpha:(hasSelection ? 0.24 : 0.74)]) setFill];
            NSBezierPath *dot = PlotThemeMarkPath(theme, p, 3.2, false);
            [dot fill];
            [(theme.coordinatedMarks ? theme.markStroke :
                [NSColor colorWithCalibratedWhite:0.02 alpha:(hasSelection ? 0.18 : 0.42)]) setStroke];
            [dot setLineWidth:theme.coordinatedMarks ? 1.0 : 0.6];
            [dot stroke];
        }
    }

    if (_dragging) {
        NSRect rr = rlispstat::platform::macos::ToNSRect(
            rlispstat::core::RectBetweenPoints(
                rlispstat::platform::macos::ToCorePoint(_dragStart),
                rlispstat::platform::macos::ToCorePoint(_dragCurrent)));
        [[NSColor colorWithCalibratedRed:0.125 green:0.445 blue:0.705 alpha:0.16] setFill];
        NSRectFillUsingOperation(rr, NSCompositingOperationSourceOver);
        [[NSColor colorWithCalibratedRed:0.050 green:0.310 blue:0.520 alpha:0.95] setStroke];
        NSFrameRect(rr);
    }

    NSDictionary *axisAttrs = [self attrsWithSize:11 weight:NSFontWeightRegular color:theme.mutedText align:NSTextAlignmentRight];
    [ToNSString("0") drawInRect:NSMakeRect(8, NSMaxY(plotRect) - 7.0, plotRect.origin.x - 14.0, 14.0) withAttributes:axisAttrs];
    [ToNSString(FormatDouble(_geometry.maxHeight, 3)) drawInRect:NSMakeRect(8, plotRect.origin.y - 7.0, plotRect.origin.x - 14.0, 14.0) withAttributes:axisAttrs];
}

- (void)mouseDown:(NSEvent *)event
{
    [[self window] makeFirstResponder:self];
    _dragging = YES;
    _dragStart = [self convertPoint:[event locationInWindow] fromView:nil];
    _dragCurrent = _dragStart;
    [self setNeedsDisplay:YES];

    while (_dragging) {
        NSEvent *trackingEvent = [[self window] nextEventMatchingMask:(NSEventMaskLeftMouseDragged | NSEventMaskLeftMouseUp)
                                                            untilDate:[NSDate distantFuture]
                                                               inMode:NSEventTrackingRunLoopMode
                                                              dequeue:YES];
        if (!trackingEvent) break;
        if ([trackingEvent type] == NSEventTypeLeftMouseDragged) {
            _dragCurrent = [self convertPoint:[trackingEvent locationInWindow] fromView:nil];
            [self setNeedsDisplay:YES];
        } else if ([trackingEvent type] == NSEventTypeLeftMouseUp) {
            [self finishSelectionWithEvent:trackingEvent];
            break;
        }
    }
}

- (void)mouseUp:(NSEvent *)event
{
    [self finishSelectionWithEvent:event];
}

- (void)finishSelectionWithEvent:(NSEvent *)event
{
    _dragCurrent = [self convertPoint:[event locationInWindow] fromView:nil];
    if (!_dragging) {
        [self setNeedsDisplay:YES];
        return;
    }
    _dragging = NO;
    rlispstat::core::Rect brush = rlispstat::core::RectBetweenPoints(
        rlispstat::platform::macos::ToCorePoint(_dragStart),
        rlispstat::platform::macos::ToCorePoint(_dragCurrent));
    std::set<int> rows;
    DendrogramSelectionGestureResult hit = DendrogramSelectionRowsForGesture(
        _geometry,
        brush,
        rlispstat::platform::macos::ToCorePoint(_dragCurrent));
    for (int row : hit.rows) {
        rows.insert(row);
    }
    if (!rows.empty()) {
        [self publishSelection:rows event:event];
    } else {
        DendrogramState *state = [_controller state];
        if (state) {
            int version = 0;
            if (MergeSelection(state->group, std::set<int>(), "replace", &version)) {
                PublishSpreadPlotMessage("ROW_SELECTION_CHANGED", state->group, state->id, "", std::vector<int>(), version);
            }
            [_controller refresh];
            UpdatePanelOnMain();
        } else {
            [self setNeedsDisplay:YES];
        }
    }
}

- (void)rightMouseDown:(NSEvent *)event
{
    NSMenu *menu = [self menuForEvent:event];
    [NSMenu popUpContextMenu:menu withEvent:event forView:self];
}

- (NSMenu *)menuForEvent:(NSEvent *)event
{
    (void)event;
    DendrogramState *state = [_controller state];
    std::string color = state ? SelectedColorForGroup(state->group) : "black";
    DendrogramContextMenuState menuState = BuildDendrogramContextMenuState(color);
    NSMenu *menu = [[NSMenu alloc] initWithTitle:ToNSString(menuState.title)];
    NSMenuItem *selectAll = [[NSMenuItem alloc] initWithTitle:ToNSString(menuState.selectAllTitle)
                                                       action:@selector(selectAllDisplayedCases:)
                                                keyEquivalent:@""];
    [selectAll setTarget:self];
    [menu addItem:selectAll];
    NSMenuItem *clear = [[NSMenuItem alloc] initWithTitle:ToNSString(menuState.clearSelectionTitle)
                                                   action:@selector(clearDendrogramSelection:)
                                            keyEquivalent:@""];
    [clear setTarget:self];
    [menu addItem:clear];
    NSMenuItem *invert = [[NSMenuItem alloc] initWithTitle:ToNSString(menuState.invertSelectionTitle)
                                                    action:@selector(invertDisplayedDendrogramSelection:)
                                             keyEquivalent:@""];
    [invert setTarget:self];
    [menu addItem:invert];
    [menu addItem:[NSMenuItem separatorItem]];
    NSMenuItem *colorItem = [[NSMenuItem alloc] initWithTitle:ToNSString(menuState.colorSelectedCasesTitle)
                                                       action:@selector(colorSelectedDendrogramCases:)
                                                keyEquivalent:@""];
    [colorItem setTarget:self];
    [menu addItem:colorItem];
    NSMenuItem *paletteItem = [[NSMenuItem alloc] initWithTitle:ToNSString(menuState.dataPointsColorTitle)
                                                         action:@selector(openDendrogramPalette:)
                                                  keyEquivalent:@""];
    [paletteItem setTarget:self];
    [menu addItem:paletteItem];
    NSMenuItem *resetItem = [[NSMenuItem alloc] initWithTitle:ToNSString(menuState.resetSelectedColorsTitle)
                                                       action:@selector(resetSelectedDendrogramColors:)
                                                keyEquivalent:@""];
    [resetItem setTarget:self];
    [menu addItem:resetItem];
    [menu addItem:[NSMenuItem separatorItem]];

    NSMenuItem *exportItem = [[NSMenuItem alloc] initWithTitle:ToNSString(menuState.exportTitle)
                                                        action:nil
                                                 keyEquivalent:@""];
    NSMenu *exportMenu = [[NSMenu alloc] initWithTitle:ToNSString(menuState.exportTitle)];
    WindowNotesContainer *notes = WindowNotesContainerForView(self);
    if (notes) {
        NSMenuItem *includeNotes = PlotCommandMenuItem(@"Include Notes", @"NOTES_INCLUDE_EXPORT");
        [includeNotes setEnabled:[notes hasNotes]];
        [includeNotes setState:[notes includeNotes] ? NSControlStateValueOn : NSControlStateValueOff];
        [exportMenu addItem:includeNotes];
        [exportMenu addItem:[NSMenuItem separatorItem]];
    }
    const auto exportActions = rlispstat::core::BuildExportMenuActions(
        rlispstat::core::StandardVisualExportCapabilities(rlispstat::core::ExportPlatform::MacOS),
        rlispstat::core::ExportPlatform::MacOS);
    for (const auto &action : exportActions) {
        if (action.separatorBefore) [exportMenu addItem:[NSMenuItem separatorItem]];
        SEL selector = nullptr;
        if (action.capability == rlispstat::core::ExportCapability::CopyPdf) selector = @selector(copyDendrogramPDF:);
        else if (action.capability == rlispstat::core::ExportCapability::CopySvg) selector = @selector(copyDendrogramSVG:);
        else if (action.capability == rlispstat::core::ExportCapability::CopyPng) selector = @selector(copyDendrogramPNG:);
        else if (action.capability == rlispstat::core::ExportCapability::SaveSvg) selector = @selector(saveDendrogramSVG:);
        else if (action.capability == rlispstat::core::ExportCapability::SavePdf) selector = @selector(saveDendrogramPDF:);
        else if (action.capability == rlispstat::core::ExportCapability::SavePng) selector = @selector(saveDendrogramPNG:);
        if (!selector) continue;
        NSMenuItem *item = [[NSMenuItem alloc] initWithTitle:ToNSString(action.title) action:selector keyEquivalent:@""];
        [item setTarget:self];
        [exportMenu addItem:item];
    }
    [menu setSubmenu:exportMenu forItem:exportItem];
    [menu addItem:exportItem];
    AddPlotThemeSubmenu(menu);
    AddSnapshotAlbumContextItems(menu);
    return menu;
}

- (void)showDendrogramSavePanelForFormat:(NSString *)format
{
    NSString *extension = [[format lowercaseString] copy];
    NSSavePanel *panel = [NSSavePanel savePanel];
    [panel setTitle:ToNSString(DendrogramExportPanelTitle(std::string([format UTF8String])))];
    [panel setNameFieldStringValue:ToNSString(DendrogramDefaultExportFilename(std::string([format UTF8String])))];
    [panel setAllowedFileTypes:@[extension]];
    if ([panel runModal] != NSModalResponseOK) return;
    BOOL ok = [format isEqualToString:@"SVG"] ? [self saveSVGToPath:[panel URL].path] :
        ([format isEqualToString:ToNSString(rlispstat::core::DendrogramPDFOptionIdentifier())]
            ? [self savePDFToPath:[panel URL].path]
            : [self savePNGToPath:[panel URL].path]);
    if (!ok) {
        ShowWorkbenchMessageOnMain(ToNSString(rlispstat::core::DendrogramExportWindowTitle()), ToNSString(DendrogramExportFailedMessage()));
    }
}

- (BOOL)copyDendrogramFormat:(NSString *)format
{
    NSPasteboard *pasteboard = [NSPasteboard generalPasteboard];
    [pasteboard clearContents];
    if ([format isEqualToString:ToNSString(rlispstat::core::DendrogramPDFOptionIdentifier())]) {
        NSData *data = VisualExportDataForView(self, @"PDF");
        return [pasteboard setData:data forType:NSPasteboardTypePDF];
    }
    if ([format isEqualToString:@"SVG"]) {
        const std::string source = ComposeSvgExportForView(self, [self dendrogramSvgDocument]);
        NSData *data = [NSData dataWithBytes:source.data() length:source.size()];
        BOOL ok = [pasteboard setData:data forType:@"public.svg-image"];
        [pasteboard setString:ToNSString(source) forType:NSPasteboardTypeString];
        return ok;
    }
    NSData *data = VisualExportDataForView(self, @"PNG");
    return data ? [pasteboard setData:data forType:NSPasteboardTypePNG] : NO;
}

- (void)saveDendrogramPNG:(id)sender
{
    (void)sender;
    [self showDendrogramSavePanelForFormat:ToNSString(rlispstat::core::DendrogramPNGOptionIdentifier())];
}

- (void)saveDendrogramPDF:(id)sender
{
    (void)sender;
    [self showDendrogramSavePanelForFormat:@"PDF"];
}

- (void)saveDendrogramSVG:(id)sender
{
    (void)sender;
    [self showDendrogramSavePanelForFormat:@"SVG"];
}

- (void)copyDendrogramPNG:(id)sender
