        ShowWorkbenchMessageOnMain(ToNSString(rlispstat::core::DendrogramCopyWindowTitle()), ToNSString(DendrogramCopyFailedMessage("PNG")));
    }
}

- (void)copyDendrogramPDF:(id)sender
{
    (void)sender;
