- (BOOL)savePNGToPath:(NSString *)path
{
    return SaveViewToPath(self, path, "PNG");
}

- (BOOL)savePDFToPath:(NSString *)path
{
    return SaveViewToPath(self, path, "PDF");
}

- (BOOL)saveSVGToPath:(NSString *)path
{
    const std::string source = ComposeSvgExportForView(self, [self dendrogramSvgDocument]);
    NSData *data = [NSData dataWithBytes:source.data() length:source.size()];
    return [data writeToFile:path atomically:YES];
}

- (std::string)dendrogramSvgDocument
{
    DendrogramState *state = [_controller state];
    const NSRect bounds = [self bounds];
    rlispstat::core::SvgWriter svg({bounds.size.width, bounds.size.height, 2.0});
    const auto style = rlispstat::core::PlotThemeStyleForName(MacCommandDispatcher().plotTheme());
    auto hex = [](const rlispstat::core::PlotRGBA &color) {
        char buffer[16];
        std::snprintf(buffer, sizeof(buffer), "#%02X%02X%02X",
            (int)std::llround(std::max(0.0, std::min(1.0, color.r)) * 255.0),
            (int)std::llround(std::max(0.0, std::min(1.0, color.g)) * 255.0),
            (int)std::llround(std::max(0.0, std::min(1.0, color.b)) * 255.0));
        return std::string(buffer);
    };
    svg.rectangle(0, 0, bounds.size.width, bounds.size.height, {hex(style.background), "none", 0, 1, {}});
    if (!state || state->caseRows.empty()) return svg.finish();
    const DendrogramPlotGeometry geometry = BuildDendrogramPlotGeometry(
        state->caseRows, state->merges, state->leafOrder, bounds.size.width, bounds.size.height);
    const rlispstat::core::Rect &plot = geometry.plotRect;
    svg.line(plot.x, plot.y, plot.x, plot.y + plot.height, {"none", hex(style.majorGrid), 1, 1, {}});
    svg.line(plot.x, plot.y + plot.height, plot.x + plot.width, plot.y + plot.height,
             {"none", hex(style.majorGrid), 1, 1, {}});
    svg.beginClipRect(plot.x, plot.y, plot.width, plot.height);
    for (const DendrogramBranchSegment &segment : geometry.branches) {
        svg.line(segment.start.x, segment.start.y, segment.end.x, segment.end.y,
                 {"none", hex(style.axis), 1.8, 1, {}});
    }
    for (const DendrogramLeafGeometry &leaf : geometry.leaves) {
        svg.ellipse(leaf.point.x, leaf.point.y, 3.2, 3.2,
                    {hex(style.geomFill), hex(style.geomStroke), 0.8, 1, {}});
    }
    svg.endClip();
    rlispstat::core::SvgTextStyle label{hex(style.text), "Arial, Helvetica, sans-serif", 11, 400, false, "middle"};
    for (const DendrogramLeafGeometry &leaf : geometry.leaves) {
        if (leaf.showLabel) svg.text(leaf.point.x, leaf.labelRect.y + 11.0, leaf.label, label);
    }
    rlispstat::core::SvgTextStyle axis{hex(style.mutedText), "Arial, Helvetica, sans-serif", 11, 400, false, "end"};
    svg.text(plot.x - 8, plot.y + plot.height + 4, "0", axis);
    svg.text(plot.x - 8, plot.y + 4, FormatDouble(geometry.maxHeight, 3), axis);
    return svg.finish();
}

- (void)keyDown:(NSEvent *)event
{
    NSString *chars = [[event charactersIgnoringModifiers] lowercaseString];
    if ([chars isEqualToString:@"i"]) {
        [self invertDisplayedDendrogramSelection:nil];
        return;
    }
    [super keyDown:event];
}

- (void)openDendrogramPalette:(id)sender
{
    (void)sender;
    DendrogramState *state = [_controller state];
    if (state) {
        std::lock_guard<std::mutex> lock(g_mutex);
        MarkActiveDatasetGroupUnlocked(state->group);
    }
    UpdateActiveDatasetMenuOnMain();
    ShowPaletteOnMain(true);
}

- (void)selectAllDisplayedCases:(id)sender
{
    (void)sender;
    DendrogramState *state = [_controller state];
    if (!state) return;
    std::set<int> rows(state->caseRows.begin(), state->caseRows.end());
    int version = 0;
    if (MergeSelection(state->group, rows, "replace", &version)) {
        PublishSpreadPlotMessage("ROW_SELECTION_CHANGED", state->group, state->id, "", std::vector<int>(rows.begin(), rows.end()), version);
    }
    [_controller refresh];
    UpdatePanelOnMain();
}

- (void)invertDisplayedDendrogramSelection:(id)sender
{
    (void)sender;
    DendrogramState *state = [_controller state];
    if (!state) return;
    std::set<int> current;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        auto it = g_groupSelections.find(state->group);
        if (it != g_groupSelections.end()) current = it->second;
    }
    std::set<int> inverted;
    for (int row : state->caseRows) {
        if (current.find(row) == current.end()) inverted.insert(row);
    }
    int version = 0;
    if (MergeSelection(state->group, inverted, "replace", &version)) {
        PublishSpreadPlotMessage("ROW_SELECTION_CHANGED", state->group, state->id, "", std::vector<int>(inverted.begin(), inverted.end()), version);
    }
    [_controller refresh];
    UpdatePanelOnMain();
}

- (void)clearDendrogramSelection:(id)sender
{
    (void)sender;
    DendrogramState *state = [_controller state];
    if (!state) return;
    std::set<int> rows;
    int version = 0;
    if (MergeSelection(state->group, rows, "replace", &version)) {
        PublishSpreadPlotMessage("ROW_SELECTION_CHANGED", state->group, state->id, "", std::vector<int>(), version);
    }
    [_controller refresh];
    UpdatePanelOnMain();
}

- (void)colorSelectedDendrogramCases:(id)sender
{
    (void)sender;
    DendrogramState *state = [_controller state];
    if (!state) return;
    std::vector<int> rows;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        auto it = g_groupSelections.find(state->group);
        if (it != g_groupSelections.end()) rows.assign(it->second.begin(), it->second.end());
    }
    ApplyColorToRows(state->group, rows, SelectedColorForGroup(state->group));
}

- (void)resetSelectedDendrogramColors:(id)sender
{
    (void)sender;
    DendrogramState *state = [_controller state];
    if (!state) return;
    std::vector<int> rows;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        auto sit = g_groupSelections.find(state->group);
        if (sit != g_groupSelections.end()) rows.assign(sit->second.begin(), sit->second.end());
        auto cit = g_groupPointColors.find(state->group);
        if (cit != g_groupPointColors.end()) {
            for (int row : rows) cit->second.erase(row);
        }
        if (!rows.empty()) {
            RequestColorSmoothRecomputeForGroupUnlocked(state->group);
        }
    }
    PublishSpreadPlotMessage("ROW_COLORS_CHANGED", state->group, state->id, "", rows);
    [_controller refresh];
    UpdatePanelOnMain();
}

@end

