}
- (instancetype)initWithModelId:(const std::string &)modelId;
- (GeneralizedGLMState *)state;
- (void)show;
- (void)refresh;
- (NSInteger)coefficientRowCount;
- (NSInteger)coefficientColumnCount;
- (NSInteger)binaryTermTestCount;
- (NSInteger)binaryWarningCount;
- (BOOL)showsModelDetails;
- (NSString *)coefficientValueForRow:(NSInteger)row column:(NSInteger)column;
- (void)coefficientCellClickedAtRow:(NSInteger)row column:(NSInteger)column;
- (NSMenu *)contextMenuForCoefficientRow:(NSInteger)row column:(NSInteger)column;
- (void)showAddTermMenuAtPoint:(NSPoint)point inView:(NSView *)view;
- (NSString *)formattedOutputForState:(GeneralizedGLMState *)state;
@end

struct GeneralizedGLMReportLayout {
    CGFloat width = 752.0;
    CGFloat margin = 14.0;
    CGFloat rowHeight = 22.0;
    CGFloat modelFitTitleY = 12.0;
    CGFloat modelFitRow1Y = 34.0;
    CGFloat modelFitRow2Y = 56.0;
    CGFloat ruleY = 84.0;
    CGFloat termsTitleY = 100.0;
    CGFloat headerY = 124.0;
    CGFloat coefRuleY = 146.0;
    CGFloat coefRowsY = 150.0;
    CGFloat bottomPadding = 18.0;
    CGFloat totalHeight = 220.0;
    NSInteger coefColumnCount = 6;
    NSInteger termTestCount = 0;
    NSInteger warningCount = 0;
    CGFloat specificationTitleY = 12.0;
    CGFloat specificationRowY = 34.0;
    CGFloat codingTitleY = 60.0;
    CGFloat codingRowY = 82.0;
    CGFloat pseudoTitleY = 180.0;
    CGFloat pseudoRowY = 202.0;
    CGFloat termTestsTitleY = 246.0;
    CGFloat termTestsHeaderY = 270.0;
    CGFloat termTestsRuleY = 292.0;
    CGFloat termTestsRowsY = 296.0;
    CGFloat warningsTitleY = 0.0;
    CGFloat diagnosticsTitleY = 0.0;
    CGFloat detailsTitleY = 0.0;
    CGFloat detailsRowsY = 0.0;
    CGFloat coefX[10] = { 2.0, 160.0, 246.0, 354.0, 462.0, 570.0, 0.0, 0.0, 0.0, 0.0 };
    CGFloat coefW[10] = { 150.0, 74.0, 92.0, 92.0, 92.0, 92.0, 0.0, 0.0, 0.0, 0.0 };

    NSInteger coefficientColumnAtX(CGFloat x) const
    {
        for (NSInteger col = 0; col < coefColumnCount; ++col) {
            if (x >= coefX[col] && x <= coefX[col] + coefW[col]) return col;
        }
        return -1;
    }

    NSRect coefficientCellRect(NSInteger row, NSInteger col) const
    {
        return NSMakeRect(margin + coefX[col], coefRowsY + row * rowHeight, coefW[col], rowHeight);
    }

    static GeneralizedGLMReportLayout Compute(NSInteger coefficientRows, CGFloat availableWidth,
                                              NSInteger coefficientColumns = 6,
                                              NSInteger binaryTermRows = 0,
                                              NSInteger binaryWarnings = 0,
                                              bool showBinaryDetails = false)
    {
        GeneralizedGLMReportLayout layout;
        layout.coefColumnCount = coefficientColumns;
        layout.termTestCount = binaryTermRows;
        layout.warningCount = binaryWarnings;
        if (coefficientColumns > 6) {
            layout.width = std::max((CGFloat)1120.0, availableWidth);
            const CGFloat binaryX[9] = { 2, 198, 286, 374, 446, 518, 608, 674, 748 };
            const CGFloat binaryW[9] = { 188, 80, 80, 64, 64, 82, 58, 66, 310 };
            for (NSInteger col = 0; col < coefficientColumns; ++col) {
                layout.coefX[col] = binaryX[col];
                layout.coefW[col] = binaryW[col];
            }
            layout.modelFitTitleY = 60.0;
            layout.modelFitRow1Y = 82.0;
            layout.modelFitRow2Y = 82.0;
            layout.ruleY = 110.0;
            layout.detailsTitleY = 126.0;
            layout.detailsRowsY = 150.0;
            layout.termsTitleY = showBinaryDetails ? 250.0 : 126.0;
            layout.headerY = layout.termsTitleY + 24.0;
            layout.coefRuleY = layout.headerY + 22.0;
            layout.coefRowsY = layout.coefRuleY + 4.0;
            layout.warningsTitleY = layout.coefRowsY + std::max((CGFloat)1.0, (CGFloat)coefficientRows) * layout.rowHeight + 14.0;
            layout.diagnosticsTitleY = layout.warningsTitleY;
            layout.totalHeight = layout.warningsTitleY +
                (binaryWarnings > 0 ? 28.0 + 18.0 * binaryWarnings : 0.0) + layout.bottomPadding;
            return layout;
        }
        layout.width = std::max((CGFloat)752.0, availableWidth);
        CGFloat extra = layout.width - 752.0;
        if (extra > 0.0) {
            layout.coefX[1] += extra * 0.18;
            layout.coefX[2] += extra * 0.30;
            layout.coefX[3] += extra * 0.42;
            layout.coefX[4] += extra * 0.54;
            layout.coefX[5] += extra * 0.66;
        }
        layout.modelFitRow2Y = layout.modelFitRow1Y;
        layout.ruleY = 62.0;
        layout.termsTitleY = 78.0;
        layout.headerY = 102.0;
        layout.coefRuleY = 124.0;
        layout.coefRowsY = 128.0;
        layout.totalHeight = layout.coefRowsY + std::max((CGFloat)1.0, (CGFloat)coefficientRows) * layout.rowHeight + layout.bottomPadding;
        return layout;
    }
};

@interface GeneralizedGLMReportView : NSView
@property(nonatomic, assign) GeneralizedGLMWindowController *glmController;
@property(nonatomic) NSInteger selectedRow;
@property(nonatomic) NSInteger selectedColumn;
- (NSSize)preferredContentSize;
@end

@implementation GeneralizedGLMReportView

- (NSString *)snapshotTabDelimitedText
{
    GeneralizedGLMState *state = [_glmController state];
    return state ? [_glmController formattedOutputForState:state] : @"";
}

- (instancetype)initWithFrame:(NSRect)frame
{
    self = [super initWithFrame:frame];
    if (self) {
        _selectedRow = -1;
        _selectedColumn = -1;
        [self setWantsLayer:YES];
    }
    return self;
}

- (BOOL)isFlipped
{
    return YES;
}

- (NSSize)preferredContentSize
{
    GeneralizedGLMReportLayout layout = GeneralizedGLMReportLayout::Compute(
        [_glmController coefficientRowCount], [self bounds].size.width,
        [_glmController coefficientColumnCount], [_glmController binaryTermTestCount],
        [_glmController binaryWarningCount], [_glmController showsModelDetails]);
    return NSMakeSize(layout.width, layout.totalHeight);
}

- (NSDictionary *)attrsWithSize:(CGFloat)size weight:(NSFontWeight)weight color:(NSColor *)color align:(NSTextAlignment)align
{
    NSMutableParagraphStyle *style = [[NSMutableParagraphStyle alloc] init];
    [style setAlignment:align];
    return @{
        NSFontAttributeName: [NSFont systemFontOfSize:size weight:weight],
        NSForegroundColorAttributeName: color,
        NSParagraphStyleAttributeName: style
    };
}

- (void)drawFitField:(NSString *)label value:(NSString *)value rect:(NSRect)rect
{
    NSDictionary *labelAttrs = [self attrsWithSize:12 weight:NSFontWeightSemibold color:[NSColor colorWithCalibratedWhite:0.16 alpha:1.0] align:NSTextAlignmentLeft];
    NSDictionary *valueAttrs = [self attrsWithSize:12 weight:NSFontWeightRegular color:[NSColor colorWithCalibratedWhite:0.16 alpha:1.0] align:NSTextAlignmentLeft];
    CGFloat labelWidth = std::min((CGFloat)92.0, rect.size.width * 0.52);
    [label drawInRect:NSMakeRect(rect.origin.x, rect.origin.y, labelWidth, rect.size.height) withAttributes:labelAttrs];
    [value drawInRect:NSMakeRect(rect.origin.x + labelWidth, rect.origin.y, rect.size.width - labelWidth, rect.size.height) withAttributes:valueAttrs];
}

- (void)drawRect:(NSRect)dirtyRect
{
    (void)dirtyRect;
    [WorkbenchSurfaceColor() setFill];
    NSRectFill([self bounds]);
    if (!_glmController) return;
    GeneralizedGLMState *state = [_glmController state];
    GeneralizedGLMReportLayout layout = GeneralizedGLMReportLayout::Compute(
        [_glmController coefficientRowCount], [self bounds].size.width,
        [_glmController coefficientColumnCount], [_glmController binaryTermTestCount],
        [_glmController binaryWarningCount], [_glmController showsModelDetails]);

    NSColor *textColor = [NSColor colorWithCalibratedWhite:0.15 alpha:1.0];
    NSColor *mutedColor = [NSColor colorWithCalibratedWhite:0.48 alpha:1.0];
    NSDictionary *sectionAttrs = [self attrsWithSize:12 weight:NSFontWeightSemibold color:textColor align:NSTextAlignmentLeft];
    NSDictionary *leftAttrs = [self attrsWithSize:12 weight:NSFontWeightRegular color:textColor align:NSTextAlignmentLeft];
    NSDictionary *mutedLeftAttrs = [self attrsWithSize:12 weight:NSFontWeightRegular color:mutedColor align:NSTextAlignmentLeft];
    NSDictionary *headerLeftAttrs = [self attrsWithSize:12 weight:NSFontWeightSemibold color:textColor align:NSTextAlignmentLeft];
    NSDictionary *headerRightAttrs = [self attrsWithSize:12 weight:NSFontWeightSemibold color:textColor align:NSTextAlignmentRight];
    NSDictionary *rightAttrs = [self attrsWithSize:12 weight:NSFontWeightRegular color:textColor align:NSTextAlignmentRight];
    NSDictionary *mutedRightAttrs = [self attrsWithSize:12 weight:NSFontWeightRegular color:mutedColor align:NSTextAlignmentRight];

    if (state && state->binaryRegression) {
        [ToNSString("Binary Regression — " + state->response)
            drawInRect:NSMakeRect(layout.margin, layout.specificationTitleY,
                                  layout.width - 2.0 * layout.margin, 20)
            withAttributes:sectionAttrs];
        std::string coding = "Event: " + state->responseCoding.eventLabel + " · Reference: " +
            state->responseCoding.referenceLabel + " · " +
            (state->binaryLink == rlispstat::core::BinaryLink::Probit ? "Probit" : "Logit") +
            " link · N = " + std::to_string(state->n);
        if (state->excluded > 0) coding += " · " + std::to_string(state->excluded) + " excluded";
        [ToNSString(coding) drawInRect:NSMakeRect(layout.margin, layout.specificationRowY, layout.width - 2.0 * layout.margin, 18) withAttributes:leftAttrs];
    }
    NSString *fitTitle = state && state->binaryRegression ? @"Global fit" : ToNSString(rlispstat::core::GLMModelFitSectionTitle());
    [fitTitle drawInRect:NSMakeRect(layout.margin, layout.modelFitTitleY, 160, 18) withAttributes:sectionAttrs];
    if (state && state->rFitPending && !state->ok) {
        [ToNSString(state->status) drawInRect:NSMakeRect(layout.margin, layout.modelFitRow1Y, layout.width - 2.0 * layout.margin, 38) withAttributes:mutedLeftAttrs];
        return;
    }
    if (state && state->ok) {
        CGFloat colW = (layout.width - 2.0 * layout.margin) / 4.0;
        if (state->binaryRegression) {
            std::string summary = "LR χ²(" + std::to_string(state->dfModel) + ") = " +
                FormatModelNumberOrDash(state->globalLR) + ", p " + FormatPValue(state->globalP) +
                " · Nagelkerke pseudo-R² = " + FormatModelNumberOrDash(state->nagelkerkeR2);
            [ToNSString(summary) drawInRect:NSMakeRect(layout.margin, layout.modelFitRow1Y,
                layout.width - 2.0 * layout.margin, 18) withAttributes:leftAttrs];
        } else {
            [self drawFitField:ToNSString(rlispstat::core::GLMFitNLabel()) value:ToNSString(std::to_string(state->n)) rect:NSMakeRect(layout.margin, layout.modelFitRow1Y, colW, 18)];
            [self drawFitField:ToNSString(rlispstat::core::GLMFitNullDevianceLabel()) value:ToNSString(FormatDoubleOrDash(state->nullDeviance, 3)) rect:NSMakeRect(layout.margin + colW, layout.modelFitRow1Y, colW, 18)];
            [self drawFitField:ToNSString(rlispstat::core::GLMFitResidualDevianceLabel()) value:ToNSString(FormatDoubleOrDash(state->residualDeviance, 3)) rect:NSMakeRect(layout.margin + colW * 2.0, layout.modelFitRow1Y, colW, 18)];
            [self drawFitField:ToNSString(rlispstat::core::GLMFitDfResidualLabel()) value:ToNSString(std::to_string(state->dfResidual)) rect:NSMakeRect(layout.margin + colW * 3.0, layout.modelFitRow1Y, colW, 18)];
        }
    } else if (state) {
        [ToNSString(state->status) drawInRect:NSMakeRect(layout.margin, layout.modelFitRow1Y, layout.width - 2.0 * layout.margin, 38) withAttributes:mutedLeftAttrs];
    }

    [[NSColor colorWithCalibratedWhite:0.86 alpha:1.0] setStroke];
    NSBezierPath *rule = [NSBezierPath bezierPath];
    [rule moveToPoint:NSMakePoint(layout.margin, layout.ruleY)];
    [rule lineToPoint:NSMakePoint(layout.width - layout.margin, layout.ruleY)];
    [rule stroke];

    if (state && state->binaryRegression && [_glmController showsModelDetails] && state->ok) {
        [@"Model details" drawInRect:NSMakeRect(layout.margin, layout.detailsTitleY, 180, 18)
                         withAttributes:sectionAttrs];
        const CGFloat detailWidth = (layout.width - 2.0 * layout.margin) / 4.0;
        const CGFloat y1 = layout.detailsRowsY;
        const CGFloat y2 = y1 + 22.0;
        const CGFloat y3 = y2 + 22.0;
        [self drawFitField:@"Log likelihood" value:ToNSString(FormatModelNumberOrDash(state->logLik)) rect:NSMakeRect(layout.margin, y1, detailWidth, 18)];
        [self drawFitField:@"Residual dev." value:ToNSString(FormatModelNumberOrDash(state->residualDeviance)) rect:NSMakeRect(layout.margin + detailWidth, y1, detailWidth, 18)];
        [self drawFitField:@"Null dev." value:ToNSString(FormatModelNumberOrDash(state->nullDeviance)) rect:NSMakeRect(layout.margin + detailWidth * 2.0, y1, detailWidth, 18)];
        [self drawFitField:@"df residual" value:ToNSString(std::to_string(state->dfResidual)) rect:NSMakeRect(layout.margin + detailWidth * 3.0, y1, detailWidth, 18)];
        [self drawFitField:@"AIC" value:ToNSString(FormatModelNumberOrDash(state->aic)) rect:NSMakeRect(layout.margin, y2, detailWidth, 18)];
        [self drawFitField:@"BIC" value:ToNSString(FormatModelNumberOrDash(state->bic)) rect:NSMakeRect(layout.margin + detailWidth, y2, detailWidth, 18)];
        [self drawFitField:@"McFadden R²" value:ToNSString(FormatModelNumberOrDash(state->mcfaddenR2)) rect:NSMakeRect(layout.margin + detailWidth * 2.0, y2, detailWidth, 18)];
        [self drawFitField:@"Cox–Snell R²" value:ToNSString(FormatModelNumberOrDash(state->coxSnellR2)) rect:NSMakeRect(layout.margin + detailWidth * 3.0, y2, detailWidth, 18)];
        [self drawFitField:@"Apparent AUC¹" value:ToNSString(FormatModelNumberOrDash(state->auc)) rect:NSMakeRect(layout.margin, y3, detailWidth, 18)];
        [self drawFitField:@"Converged" value:(state->converged ? @"yes" : @"no") rect:NSMakeRect(layout.margin + detailWidth, y3, detailWidth, 18)];
        [self drawFitField:@"Iterations" value:ToNSString(std::to_string(state->iterations)) rect:NSMakeRect(layout.margin + detailWidth * 2.0, y3, detailWidth, 18)];
        [self drawFitField:@"Rank" value:ToNSString(std::to_string(state->rank) + "/" + std::to_string(state->parameterCount)) rect:NSMakeRect(layout.margin + detailWidth * 3.0, y3, detailWidth, 18)];
        [@"¹ Calculated on the observations used to fit the model; not out-of-sample validation."
            drawInRect:NSMakeRect(layout.margin, y3 + 20.0, layout.width - 2.0 * layout.margin, 16)
            withAttributes:mutedLeftAttrs];
        NSBezierPath *detailsRule = [NSBezierPath bezierPath];
        [detailsRule moveToPoint:NSMakePoint(layout.margin, layout.termsTitleY - 16.0)];
        [detailsRule lineToPoint:NSMakePoint(layout.width - layout.margin, layout.termsTitleY - 16.0)];
        [detailsRule stroke];
    }

    NSString *coefficientTitle = state && state->binaryRegression ? @"Terms and coefficients" : ToNSString(rlispstat::core::GLMTermsSectionTitle());
    [coefficientTitle drawInRect:NSMakeRect(layout.margin, layout.termsTitleY, 160, 18) withAttributes:sectionAttrs];
    NSMutableArray<NSString *> *headers = [NSMutableArray array];
    if (state && state->binaryRegression) {
        NSString *effectHeader = state->binaryLink == rlispstat::core::BinaryLink::Logit
            ? @"OR / 95% CI for OR" : @"95% CI";
        [headers addObjectsFromArray:@[@"Variable / level", @"B", @"SE", @"z", @"p", @"LR χ²", @"df", @"p LR", effectHeader]];
    } else {
        [headers addObjectsFromArray:@[ToNSString(rlispstat::core::GLMCoefVariableHeader()), ToNSString(rlispstat::core::GLMCoefTypeHeader()), ToNSString(rlispstat::core::GLMCoefBHeader()), ToNSString(rlispstat::core::GLMCoefSEHeader()), state ? ToNSString(state->statisticName) : ToNSString(rlispstat::core::GLMCoefStatisticHeader()), ToNSString(rlispstat::core::GLMCoefPHeader())]];
    }
    for (NSInteger col = 0; col < layout.coefColumnCount; ++col) {
        NSRect headerRect = NSMakeRect(layout.margin + layout.coefX[col], layout.headerY, layout.coefW[col], 18);
        [headers[(NSUInteger)col] drawInRect:headerRect withAttributes:(col == 0 || (!state->binaryRegression && col == 1) ? headerLeftAttrs : headerRightAttrs)];
    }
    NSBezierPath *coefRule = [NSBezierPath bezierPath];
    [coefRule moveToPoint:NSMakePoint(layout.margin, layout.coefRuleY)];
    [coefRule lineToPoint:NSMakePoint(layout.width - layout.margin, layout.coefRuleY)];
    [coefRule stroke];

    NSInteger rows = [_glmController coefficientRowCount];
    NSInteger addRow = rows - 1;
    for (NSInteger row = 0; row < rows; ++row) {
        if (row == _selectedRow) {
            [[NSColor colorWithCalibratedWhite:0.93 alpha:1.0] setFill];
            NSRectFill(NSMakeRect(layout.margin - 2.0, layout.coefRowsY + row * layout.rowHeight, layout.width - 2.0 * layout.margin + 4.0, layout.rowHeight));
        }
        for (NSInteger col = 0; col < layout.coefColumnCount; ++col) {
            NSString *value = [_glmController coefficientValueForRow:row column:col];
            if (!value || [value length] == 0) continue;
            NSRect cell = NSInsetRect(layout.coefficientCellRect(row, col), 2.0, 3.0);
            NSDictionary *attrs = (row == addRow || [value isEqualToString:@"\U00002014"])
                ? (col == 0 || (!state->binaryRegression && col == 1) ? mutedLeftAttrs : mutedRightAttrs)
                : (col == 0 || (!state->binaryRegression && col == 1) ? leftAttrs : rightAttrs);
            [value drawInRect:cell withAttributes:attrs];
        }
    }
    if (state && state->binaryRegression) {
        CGFloat y = layout.warningsTitleY;
        if (!state->warnings.empty()) {
            [@"Warnings" drawInRect:NSMakeRect(layout.margin, y, 160, 18) withAttributes:sectionAttrs];
            y += 24.0;
            for (const std::string &warning : state->warnings) {
                [ToNSString("⚠ " + warning) drawInRect:NSMakeRect(layout.margin + 2.0, y, layout.width - 2.0 * layout.margin - 4.0, 18) withAttributes:mutedLeftAttrs];
                y += 18.0;
            }
        }
    }
}

- (NSInteger)rowAtPoint:(NSPoint)point
{
    GeneralizedGLMReportLayout layout = GeneralizedGLMReportLayout::Compute([_glmController coefficientRowCount], [self bounds].size.width,
        [_glmController coefficientColumnCount], [_glmController binaryTermTestCount], [_glmController binaryWarningCount], [_glmController showsModelDetails]);
    if (point.y < layout.coefRowsY) return -1;
    NSInteger row = (NSInteger)floor((point.y - layout.coefRowsY) / layout.rowHeight);
    return (row >= 0 && row < [_glmController coefficientRowCount]) ? row : -1;
}

- (NSMenu *)menuForEvent:(NSEvent *)event
{
    NSPoint point = [self convertPoint:[event locationInWindow] fromView:nil];
    GeneralizedGLMReportLayout layout = GeneralizedGLMReportLayout::Compute([_glmController coefficientRowCount], [self bounds].size.width,
        [_glmController coefficientColumnCount], [_glmController binaryTermTestCount], [_glmController binaryWarningCount], [_glmController showsModelDetails]);
    NSInteger row = [self rowAtPoint:point];
    NSInteger column = layout.coefficientColumnAtX(point.x - layout.margin);
    _selectedRow = row;
    _selectedColumn = column;
    [self setNeedsDisplay:YES];
    return SnapshotAlbumMenu([_glmController contextMenuForCoefficientRow:row column:column],
                             @"Generalized Linear Model");
}

- (void)mouseDown:(NSEvent *)event
{
    [[self window] makeFirstResponder:self];
    NSPoint point = [self convertPoint:[event locationInWindow] fromView:nil];
    GeneralizedGLMReportLayout layout = GeneralizedGLMReportLayout::Compute([_glmController coefficientRowCount], [self bounds].size.width,
        [_glmController coefficientColumnCount], [_glmController binaryTermTestCount], [_glmController binaryWarningCount], [_glmController showsModelDetails]);
    NSInteger row = [self rowAtPoint:point];
    NSInteger column = layout.coefficientColumnAtX(point.x - layout.margin);
    _selectedRow = row;
    _selectedColumn = column;
    [self setNeedsDisplay:YES];
    [_glmController coefficientCellClickedAtRow:row column:column];
}
@end

