- (GeneralizedGLMState *)state
{
    auto it = g_generalizedGLMs.find(_modelId);
    if (it == g_generalizedGLMs.end()) return nullptr;
    return &it->second;
}

- (void)show
{
    [self activateDatasetForCommands];
    EnableNotesForWindow(_window, _modelId, @"this model result");
    [_window makeKeyAndOrderFront:nil];
    [NSApp activateIgnoringOtherApps:YES];
    [self refresh];
}

- (void)activateDatasetForCommands
{
    GeneralizedGLMState *state = [self state];
    if (!state) return;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        MarkActiveDatasetGroupUnlocked(state->group);
        EnsureDatasetSeedPlotUnlocked(state->group);
    }
    UpdateActiveDatasetMenuOnMain();
}

- (void)windowDidBecomeKey:(NSNotification *)notification
{
    (void)notification;
    [self activateDatasetForCommands];
}

- (void)populateLinkPopupForFamily:(const std::string &)family selected:(const std::string &)selected
{
    [_linkPopup removeAllItems];
    GeneralizedGLMState *state = [self state];
    if (state && state->binaryRegression) {
        [_linkPopup addItemWithTitle:@"Logit"];
        [_linkPopup addItemWithTitle:@"Probit"];
        [_linkPopup selectItemWithTitle:ToNSString(rlispstat::core::BinaryLinkLabel(state->binaryLink))];
        return;
    }
    for (const std::string &link : GeneralizedLinksForFamily(family)) {
        [_linkPopup addItemWithTitle:ToNSString(link)];
    }
    [_linkPopup selectItemWithTitle:ToNSString(selected)];
}

- (NSString *)formattedOutputForState:(GeneralizedGLMState *)state
{
    return state ? ToNSString(rlispstat::core::GeneralizedGLMFormattedOutputText(*state, _showModelDetails)) : @"";
}

- (NSInteger)coefficientRowCount
{
    GeneralizedGLMState *state = [self state];
    if (!state) return 1;
    if (state->rFitPending && !state->ok) return 0;
    if (state->ok) return (NSInteger)state->rows.size() + 1;
    return (NSInteger)state->terms.size() + 2;
}

- (NSInteger)coefficientColumnCount
{
    GeneralizedGLMState *state = [self state];
    if (!state || !state->binaryRegression) return 6;
    return 9;
}

- (NSInteger)binaryTermTestCount
{
    GeneralizedGLMState *state = [self state];
    return state && state->binaryRegression ? (NSInteger)state->termTests.size() : 0;
}

- (NSInteger)binaryWarningCount
{
    GeneralizedGLMState *state = [self state];
    return state && state->binaryRegression ? (NSInteger)state->warnings.size() : 0;
}

- (BOOL)showsModelDetails
{
    GeneralizedGLMState *state = [self state];
    return state && state->binaryRegression && _showModelDetails;
}

- (NSString *)coefficientColumnIdentifier:(NSInteger)column
{
    static NSString *ids[] = { @"term", @"type", @"estimate", @"stderr", @"stat", @"p" };
    GeneralizedGLMState *state = [self state];
    if (state && state->binaryRegression) {
        static NSString *binaryIds[] = { @"term", @"estimate", @"stderr", @"stat", @"p",
            @"lr", @"lr_df", @"lr_p", @"effect_ci" };
        return (column >= 0 && column < [self coefficientColumnCount]) ? binaryIds[column] : @"";
    }
    return (column >= 0 && column < 6) ? ids[column] : @"";
}

- (BOOL)isAddTermRow:(NSInteger)row
{
    return row == [self coefficientRowCount] - 1;
}

- (std::string)sourceTermForCoefficientRow:(NSInteger)row
{
    GeneralizedGLMState *state = [self state];
    if (!state || row <= 0 || [self isAddTermRow:row]) return "";
    if (state->ok && row < (NSInteger)state->rows.size()) {
        const GeneralizedGLMRow &coef = state->rows[(size_t)row];
        if (!coef.sourceTerm.empty() && coef.sourceTerm != "NA" && coef.sourceTerm != "(Intercept)") {
            return coef.sourceTerm;
        }
        std::string candidate = coef.term;
        size_t eq = candidate.find('=');
        if (eq != std::string::npos) candidate = candidate.substr(0, eq);
        auto it = std::find(state->terms.begin(), state->terms.end(), candidate);
        if (it != state->terms.end()) return candidate;
        std::string label = coef.displayLabel;
        label.erase(label.begin(), std::find_if(label.begin(), label.end(), [](unsigned char ch) { return !std::isspace(ch); }));
        it = std::find(state->terms.begin(), state->terms.end(), label);
        if (it != state->terms.end()) return label;
        return "";
    }
    NSInteger termRow = row - 1;
    if (termRow >= 0 && (size_t)termRow < state->terms.size()) return state->terms[(size_t)termRow];
    return "";
}

- (NSString *)coefficientValueForRow:(NSInteger)row column:(NSInteger)column
{
    NSString *identifier = [self coefficientColumnIdentifier:column];
    GeneralizedGLMState *state = [self state];
    if (!state || row < 0) return @"";
    if ([self isAddTermRow:row]) {
        return [identifier isEqualToString:@"term"] ? @"+ Add term" : @"";
    }

    bool hasCoef = state->ok && row >= 0 && row < (NSInteger)state->rows.size();
    if (hasCoef) {
        const GeneralizedGLMRow &coef = state->rows[(size_t)row];
        bool parentRow = coef.rowType == "factor_parent" || coef.rowType == "term_parent";
        bool referenceRow = coef.rowType == "reference";
        bool interceptRow = coef.term == "(Intercept)" || coef.sourceTerm == "(Intercept)";
        bool showTermTest = !interceptRow && (parentRow ||
            (!coef.sourceTerm.empty() && coef.term == coef.sourceTerm));
        const rlispstat::core::BinaryTermTestRow *termTest = nullptr;
        if (showTermTest) {
            const std::string &source = coef.sourceTerm.empty() ? coef.term : coef.sourceTerm;
            for (const auto &candidate : state->termTests) {
                if (candidate.term == source) { termTest = &candidate; break; }
            }
        }
        if ([identifier isEqualToString:@"term"]) {
            std::string displayLabel = coef.displayLabel.empty() ? coef.term : coef.displayLabel;
            if (referenceRow && displayLabel.find("reference") == std::string::npos) displayLabel += " (reference)";
            return ToNSString(displayLabel);
        }
        if ([identifier isEqualToString:@"type"]) {
            if (coef.term == "(Intercept)" || coef.sourceTerm == "(Intercept)") return @"-";
            if (coef.rowType == "reference" || coef.rowType == "factor_level" ||
                (rlispstat::core::ModelTermTypeIsInteraction(coef.termType) && coef.rowType == "coefficient" &&
                 !coef.sourceTerm.empty() && coef.sourceTerm != coef.term)) return @"";
            return coef.termType.empty() ? @"-" : ToNSString(rlispstat::core::ModelTermTypeDisplayName(coef.termType));
        }
        if ([identifier isEqualToString:@"estimate"]) {
            return (parentRow || referenceRow) ? @"\U00002014" : ToNSString(state->binaryRegression
                ? FormatModelNumberOrDash(coef.estimate) : FormatDoubleOrDash(coef.estimate, 4));
        }
        if ([identifier isEqualToString:@"stderr"]) {
            return (parentRow || referenceRow) ? @"\U00002014" : ToNSString(state->binaryRegression
                ? FormatModelNumberOrDash(coef.stdError) : FormatDoubleOrDash(coef.stdError, 4));
        }
        if ([identifier isEqualToString:@"stat"]) {
            return (parentRow || referenceRow) ? @"\U00002014" : ToNSString(state->binaryRegression
                ? FormatModelNumberOrDash(coef.statistic) : FormatDoubleOrDash(coef.statistic, 3));
        }
        if ([identifier isEqualToString:@"p"]) {
            return (parentRow || referenceRow) ? @"\U00002014" : ToNSString(FormatPValue(coef.pValue));
        }
        if ([identifier isEqualToString:@"lr"]) {
            return termTest ? ToNSString(FormatModelNumberOrDash(termTest->statistic)) : @"\U00002014";
        }
        if ([identifier isEqualToString:@"lr_df"]) {
            return termTest ? ToNSString(std::to_string(termTest->df)) : @"\U00002014";
        }
        if ([identifier isEqualToString:@"lr_p"]) {
            return termTest ? ToNSString(FormatPValue(termTest->pValue)) : @"\U00002014";
        }
        if ([identifier isEqualToString:@"effect_ci"]) {
            if (parentRow || referenceRow) return @"\U00002014";
            if (state->binaryLink == rlispstat::core::BinaryLink::Logit) {
                return ToNSString(FormatModelNumberOrDash(coef.oddsRatio) + " [" +
                    FormatModelNumberOrDash(coef.oddsRatioLower) + ", " +
                    FormatModelNumberOrDash(coef.oddsRatioUpper) + "]");
            }
            return ToNSString("[" + FormatModelNumberOrDash(coef.ciLower) + ", " +
                FormatModelNumberOrDash(coef.ciUpper) + "]");
        }
        return @"";
    }

    if (row == 0) {
        if ([identifier isEqualToString:@"term"]) return @"(Intercept)";
        if ([identifier isEqualToString:@"type"]) return @"-";
        return @"\U00002014";
    }
    NSInteger termRow = row - 1;
    if (termRow >= 0 && (size_t)termRow < state->terms.size()) {
        const std::string &term = state->terms[(size_t)termRow];
        if ([identifier isEqualToString:@"term"]) return ToNSString(term);
        if ([identifier isEqualToString:@"type"]) return ToNSString(rlispstat::core::ModelTermTypeDisplayName(rlispstat::core::ModelTermDisplayType(&state->seed, term, state->termTypes)));
        return @"\U00002014";
    }
    return @"";
}

- (void)refresh
{
    GeneralizedGLMState *state = [self state];
    if (!state) return;
    _refreshing = YES;
    [_window setTitle:ToNSString(state->title.empty() ? "Generalized Linear Model" : state->title)];
    [_titleField setStringValue:ToNSString(state->title.empty() ? "Generalized Linear Model" : state->title)];
    [_badgeField setStringValue:ToNSString(state->multipleImputation && state->imputationCount > 0
        ? "m = " + std::to_string(state->imputationCount)
        : state->group)];
    [_responsePopup removeAllItems];
    if (state->binaryRegression) {
        for (const std::string &name : VariableNamesForModel(&state->seed)) {
            const DataColumn *column = FindDataColumnForModel(&state->seed, name);
            if (column && rlispstat::core::InspectBinaryResponse(*column).ok) {
                [_responsePopup addItemWithTitle:ToNSString(name)];
            }
        }
    } else {
        for (const std::string &name : rlispstat::core::NumericVariableNames(&state->seed)) {
            [_responsePopup addItemWithTitle:ToNSString(name)];
        }
    }
    [_responsePopup selectItemWithTitle:ToNSString(state->response)];
	    if (state->binaryRegression) {
	        [_familyLabel setStringValue:@"Event"];
	        [_linkLabel setStringValue:@"Link"];
	        [_familyPopup removeAllItems];
	        [_familyPopup addItemWithTitle:ToNSString(state->responseCoding.referenceLabel)];
	        [_familyPopup addItemWithTitle:ToNSString(state->responseCoding.eventLabel)];
	        [_familyPopup selectItemWithTitle:ToNSString(state->responseCoding.eventLabel)];
	        [_familyLabel setFrame:NSMakeRect(244, NSMinY([_familyLabel frame]), 42, 22)];
	        [_familyPopup setFrame:NSMakeRect(286, NSMinY([_familyPopup frame]), 82, 24)];
	        [_binaryReferenceField setStringValue:ToNSString("Reference: " + state->responseCoding.referenceLabel)];
	        [_binaryReferenceField setHidden:NO];
	        [_binaryReferenceField setFrame:NSMakeRect(376, NSMinY([_binaryReferenceField frame]), 100, 22)];
	        [_linkLabel setFrame:NSMakeRect(480, NSMinY([_linkLabel frame]), 36, 22)];
	        [_linkPopup setFrame:NSMakeRect(516, NSMinY([_linkPopup frame]), 80, 24)];
	    } else {
	        [_familyLabel setStringValue:ToNSString(rlispstat::core::GLMFamilyFieldLabel())];
	        [_familyPopup removeAllItems];
	        for (NSString *family in @[@"gaussian", @"binomial", @"poisson", @"Gamma", @"inverse.gaussian", @"quasibinomial", @"quasipoisson"]) [_familyPopup addItemWithTitle:family];
	        [_familyPopup selectItemWithTitle:ToNSString(state->family)];
	        [_binaryReferenceField setHidden:YES];
	        [_familyLabel setFrame:NSMakeRect(244, NSMinY([_familyLabel frame]), 48, 22)];
	        [_familyPopup setFrame:NSMakeRect(292, NSMinY([_familyPopup frame]), 132, 24)];
	        [_linkLabel setFrame:NSMakeRect(440, NSMinY([_linkLabel frame]), 36, 22)];
	        [_linkPopup setFrame:NSMakeRect(476, NSMinY([_linkPopup frame]), 118, 24)];
	    }
	    [self populateLinkPopupForFamily:state->family selected:state->link];
	    [_scopePopup selectItemWithTitle:(state->scope == "selected" ? ToNSString(rlispstat::core::ScopeSelectedRowsTitle()) : (state->scope == "unselected" ? ToNSString(rlispstat::core::ScopeUnselectedRowsTitle()) : ToNSString(rlispstat::core::ScopeAllDataTitle())))];
	    [_autoRefitButton setState:state->autoRefit ? NSControlStateValueOn : NSControlStateValueOff];
	    [_residualPopup selectItemWithTitle:(state->residualType == "pearson" ? ToNSString(rlispstat::core::GLMPearsonResidualTitle()) : (state->residualType == "working" ? ToNSString(rlispstat::core::GLMWorkingResidualTitle()) : ToNSString(rlispstat::core::GLMDevianceResidualTitle())))];
    [_responsePopup setEnabled:!state->precomputed];
    [_familyPopup setEnabled:!state->precomputed];
    [_linkPopup setEnabled:!state->precomputed];
	    [_scopePopup setEnabled:(!state->dataScopeCaptured &&
	        (!state->precomputed || state->multipleImputation))];
    [_autoRefitButton setEnabled:!state->precomputed];
	    if (!state->precomputed && state->autoRefit && (!state->ok || state->fitVersion < state->modelVersion)) {
	        RequestGeneralizedGLMFitInMainR(*state);
	    }
    bool keepCurrentReportWhilePending = state->rFitPending && state->ok;
    NSSize contentSize = [[_window contentView] frame].size;
    [_reportScrollView setFrame:NSMakeRect(14, 44, std::max((CGFloat)220.0, contentSize.width - 28.0),
                                             std::max((CGFloat)120.0, contentSize.height - 156.0))];
    if (!keepCurrentReportWhilePending) {
        NSSize wanted = [_reportView preferredContentSize];
        if (!_hasSizedToContent && state->ok) {
            NSRect visible = [[_window screen] visibleFrame];
            CGFloat targetWidth = std::min(std::max((CGFloat)780.0, wanted.width + 28.0), visible.size.width - 60.0);
            CGFloat targetHeight = std::min(std::max((CGFloat)540.0, wanted.height + 156.0), visible.size.height - 60.0);
            [_window setContentSize:NSMakeSize(targetWidth, targetHeight)];
            _hasSizedToContent = YES;
            contentSize = [[_window contentView] frame].size;
            [_reportScrollView setFrame:NSMakeRect(14, 44, std::max((CGFloat)220.0, contentSize.width - 28.0),
                                                     std::max((CGFloat)120.0, contentSize.height - 156.0))];
        }
        [_reportView setFrame:NSMakeRect(0, 0, std::max(wanted.width, [_reportScrollView contentSize].width), wanted.height)];
        [_reportView setNeedsDisplay:YES];
    }
    size_t selected = SelectionCount(state->group);
    size_t total = state->seed.points.size();
    if (state->precomputed && !state->note.empty()) {
        [_statusField setStringValue:ToNSString(GLMStatusMessage(state->note))];
    } else {
        std::string status = GeneralizedGLMWindowStatus(state->status, selected, total,
                                                        state->family, state->link);
        if (state->binaryRegression) {
            status = state->ok
                ? "Status: fitted on " + std::to_string(state->n) + " rows; " + std::to_string(state->excluded) +
                    " excluded. Event: " + state->responseCoding.eventLabel + "; reference: " + state->responseCoding.referenceLabel + "."
                : "Status: " + state->status;
        }
        [_statusField setStringValue:ToNSString(status)];
    }
    if (state->dataScopeCaptured) {
        NSString *status = [_statusField stringValue] ?: @"";
        [_statusField setStringValue:[status stringByAppendingFormat:@" · %@",
            ToNSString(rlispstat::core::AnalysisScopeWindowSummary(
                state->dataScope, state->dataScope.totalDatasetRows))]];
    }
    _refreshing = NO;
}

- (void)markChangedAndRefresh
{
    GeneralizedGLMState *state = [self state];
    if (!state) return;
    if (state->precomputed) {
        [_statusField setStringValue:ToNSString(GLMPooledTableChangeInRStatus())];
        [self refresh];
        return;
    }
    state->modelVersion += 1;
    if (state->response.empty()) {
        state->rFitPending = false;
        state->ok = false;
        state->status = rlispstat::core::GLMChooseResponseVariableStatus();
    } else if (state->terms.empty() && !state->binaryRegression) {
        state->rFitPending = false;
        state->ok = false;
        state->status = rlispstat::core::GLMAddPredictorBeforeTableStatus();
    }
	    if (state->autoRefit) {
	        RequestGeneralizedGLMFitInMainR(*state);
	    }
    [self refresh];
}

- (void)responseChanged:(id)sender
{
    (void)sender;
    if (_refreshing) return;
    GeneralizedGLMState *state = [self state];
    if (!state) return;
    state->response = std::string([[[_responsePopup selectedItem] title] UTF8String]);
    state->terms.erase(std::remove(state->terms.begin(), state->terms.end(), state->response), state->terms.end());
    if (state->binaryRegression) {
        const DataColumn *column = FindDataColumnForModel(&state->seed, state->response);
        state->responseCoding = column ? rlispstat::core::InspectBinaryResponse(*column)
                                       : rlispstat::core::BinaryResponseCoding{};
        state->responseCodingExplicit = false;
    }
    [self markChangedAndRefresh];
}

- (void)familyChanged:(id)sender
{
    (void)sender;
    if (_refreshing) return;
    GeneralizedGLMState *state = [self state];
    if (!state) return;
    if (state->binaryRegression) {
        std::string selected = std::string([[[_familyPopup selectedItem] title] UTF8String]);
        if (selected == state->responseCoding.referenceLabel) {
            std::swap(state->responseCoding.eventValue, state->responseCoding.referenceValue);
            std::swap(state->responseCoding.eventLabel, state->responseCoding.referenceLabel);
            std::swap(state->responseCoding.eventCount, state->responseCoding.referenceCount);
        }
        state->responseCodingExplicit = true;
        [self markChangedAndRefresh];
        return;
    }
    state->family = std::string([[[_familyPopup selectedItem] title] UTF8String]);
    if (!IsValidGeneralizedLink(state->family, state->link)) {
        state->link = DefaultGeneralizedLink(state->family);
    }
    [self markChangedAndRefresh];
}

- (void)linkChanged:(id)sender
{
    (void)sender;
    if (_refreshing) return;
    GeneralizedGLMState *state = [self state];
    if (!state) return;
    std::string candidate = std::string([[[_linkPopup selectedItem] title] UTF8String]);
    if (state->binaryRegression) {
        rlispstat::core::BinaryLink parsed;
        if (rlispstat::core::ParseBinaryLink(candidate, parsed)) {
            state->binaryLink = parsed;
            state->link = rlispstat::core::BinaryLinkId(parsed);
            [self markChangedAndRefresh];
        }
        return;
    }
    if (IsValidGeneralizedLink(state->family, candidate)) {
        state->link = candidate;
        [self markChangedAndRefresh];
    }
}

- (void)scopeChanged:(id)sender
{
    (void)sender;
    if (_refreshing) return;
    GeneralizedGLMState *state = [self state];
    if (!state) return;
    NSString *title = [[_scopePopup selectedItem] title];
    state->scope = [title isEqualToString:@"Selected"] ? "selected" : ([title isEqualToString:@"Unselected"] ? "unselected" : "all");
    [self markChangedAndRefresh];
}

- (void)autoRefitChanged:(id)sender
{
    (void)sender;
    GeneralizedGLMState *state = [self state];
    if (!state) return;
    state->autoRefit = [_autoRefitButton state] == NSControlStateValueOn;
    if (state->autoRefit) [self markChangedAndRefresh];
}

- (void)residualTypeChanged:(id)sender
{
    (void)sender;
    if (_refreshing) return;
    GeneralizedGLMState *state = [self state];
    if (!state) return;
    NSString *title = [[_residualPopup selectedItem] title];
    state->residualType = [title isEqualToString:ToNSString(rlispstat::core::GLMPearsonResidualTitle())] ? "pearson" : ([title isEqualToString:ToNSString(rlispstat::core::GLMWorkingResidualTitle())] ? "working" : "deviance");
    RefreshGLMDiagnosticPlotsSynchronouslyOnMain(state->group, true);
    [self refresh];
}

- (NSMenuItem *)modelMenuItem:(NSString *)title action:(SEL)action represented:(NSString *)represented
{
    NSMenuItem *item = [[NSMenuItem alloc] initWithTitle:title action:action keyEquivalent:@""];
    [item setTarget:self];
    if (represented) [item setRepresentedObject:represented];
    return item;
}

- (NSMenuItem *)binaryExportMenuItem
{
    NSMenuItem *root = [[NSMenuItem alloc] initWithTitle:@"Export" action:nil keyEquivalent:@""];
    NSMenu *exportMenu = [[NSMenu alloc] initWithTitle:@"Export"];
    GeneralizedGLMState *state = [self state];
    if (state) {
        AddStandardTableVisualExportItems(exportMenu, _reportView,
            state->binaryRegression ? @"Binary Regression" : @"General Linear Model",
            ToNSString(state->binaryRegression ? "binary-regression" : "general-linear-model"),
            [self formattedOutputForState:state]);
        [exportMenu addItem:[NSMenuItem separatorItem]];
    }
    [exportMenu addItem:[self modelMenuItem:@"Copy table with headers" action:@selector(copyModelTable:) represented:nil]];
    [exportMenu addItem:[self modelMenuItem:@"Copy R syntax" action:@selector(copyBinaryRSyntax:) represented:nil]];
    [exportMenu addItem:[NSMenuItem separatorItem]];

    NSMenuItem *csvRoot = [[NSMenuItem alloc] initWithTitle:@"CSV" action:nil keyEquivalent:@""];
    NSMenu *csvMenu = [[NSMenu alloc] initWithTitle:@"CSV"];
    [csvMenu addItem:[self modelMenuItem:@"Terms and coefficients…" action:@selector(exportBinaryCSV:) represented:@"coefficients"]];
    [csvMenu addItem:[self modelMenuItem:@"Likelihood-ratio tests…" action:@selector(exportBinaryCSV:) represented:@"term_tests"]];
    [csvMenu addItem:[self modelMenuItem:@"Model details…" action:@selector(exportBinaryCSV:) represented:@"model_fit"]];
    [exportMenu setSubmenu:csvMenu forItem:csvRoot];
    [exportMenu addItem:csvRoot];

    NSMenuItem *pdfRoot = [[NSMenuItem alloc] initWithTitle:@"PDF" action:nil keyEquivalent:@""];
    NSMenu *pdfMenu = [[NSMenu alloc] initWithTitle:@"PDF"];
    [pdfMenu addItem:[self modelMenuItem:@"As displayed…" action:@selector(exportModelTableAsPDF:) represented:nil]];
    [pdfMenu addItem:[self modelMenuItem:@"APA 7…" action:@selector(exportBinaryPDFAPA:) represented:nil]];
    [exportMenu setSubmenu:pdfMenu forItem:pdfRoot];
    [exportMenu addItem:pdfRoot];
    [root setSubmenu:exportMenu];
    return root;
}

- (void)copyMenuValue:(id)sender
{
    NSString *value = [sender representedObject];
    if (!value) value = @"";
    NSPasteboard *pasteboard = [NSPasteboard generalPasteboard];
    [pasteboard clearContents];
    [pasteboard setString:value forType:NSPasteboardTypeString];
    [_statusField setStringValue:ToNSString(GLMValueCopiedStatus())];
}

- (void)showCoefficientDetails:(id)sender
{
    (void)sender;
    GeneralizedGLMState *state = [self state];
    if (!state || _selectedCoefRow < 0 || [self isAddTermRow:_selectedCoefRow]) return;
    if (!state->ok || _selectedCoefRow >= (NSInteger)state->rows.size()) {
        [_statusField setStringValue:ToNSString(GLMStatusMessage(state->status))];
        return;
    }
    const GeneralizedGLMRow &coef = state->rows[(size_t)_selectedCoefRow];
    [_statusField setStringValue:ToNSString(GeneralizedCoefficientDetailsStatus(coef, state->statisticName))];
}

- (void)showModelDetails:(id)sender
{
    (void)sender;
    GeneralizedGLMState *state = [self state];
    if (!state || !state->binaryRegression) return;
    _showModelDetails = !_showModelDetails;
    [self refresh];
    [_statusField setStringValue:_showModelDetails
        ? @"Status: model details shown in the results table."
        : @"Status: model details hidden."];
}

- (NSMenu *)statisticContextMenuForTableRow:(NSInteger)row column:(NSInteger)column
{
    const auto titles = rlispstat::core::DefaultModelContextMenuTitles();
    NSMenu *menu = [[NSMenu alloc] initWithTitle:ToNSString(titles.statistic)];
    NSMenuItem *copy = [[NSMenuItem alloc] initWithTitle:ToNSString(titles.copyValue) action:@selector(copyMenuValue:) keyEquivalent:@""];
    [copy setTarget:self];
    [copy setRepresentedObject:[self coefficientValueForRow:row column:column]];
    [menu addItem:copy];
    NSMenuItem *details = [[NSMenuItem alloc] initWithTitle:ToNSString(titles.showCoefficientDetails) action:@selector(showCoefficientDetails:) keyEquivalent:@""];
    [details setTarget:self];
    [menu addItem:details];
    [menu addItem:[NSMenuItem separatorItem]];
    AddModelDiagnosticPlotMenuItems(menu, self, @selector(openDiagnosticFromMenu:), false);
    [menu addItem:[NSMenuItem separatorItem]];
    GeneralizedGLMState *state = [self state];
    if (state && state->binaryRegression) {
        [menu addItem:[self binaryExportMenuItem]];
    } else {
        [menu addItem:[self modelMenuItem:ToNSString(titles.copyModelTable) action:@selector(copyModelTable:) represented:nil]];
    }
    return menu;
}

- (NSMenu *)predictorContextMenuForTableRow:(NSInteger)row
{
    const auto titles = rlispstat::core::DefaultModelContextMenuTitles();
    NSMenu *menu = [[NSMenu alloc] initWithTitle:ToNSString(titles.predictor)];
    GeneralizedGLMState *state = [self state];
    std::string baseTerm = [self sourceTermForCoefficientRow:row];
    NSString *representedTerm = baseTerm.empty() ? nil : ToNSString(baseTerm);
    if (state && state->binaryRegression && state->ok && !baseTerm.empty() &&
        !IsInteractionTerm(baseTerm) &&
        rlispstat::core::ModelTermDisplayType(&state->seed, baseTerm, state->termTypes) == "factor") {
        NSMenuItem *pairwise = [[NSMenuItem alloc] initWithTitle:@"Pairwise comparisons…"
                                                         action:@selector(openBinaryPairwiseComparisons:)
                                                  keyEquivalent:@""];
        [pairwise setTarget:self];
        [pairwise setRepresentedObject:ToNSString(baseTerm)];
        [menu addItem:pairwise];
        [menu addItem:[NSMenuItem separatorItem]];
    }
    NSMenuItem *details = [[NSMenuItem alloc] initWithTitle:ToNSString(titles.showCoefficientDetails) action:@selector(showCoefficientDetails:) keyEquivalent:@""];
    [details setTarget:self];
    [menu addItem:details];
    [menu addItem:[[NSMenuItem alloc] initWithTitle:ToNSString(titles.changeVariable) action:@selector(changeSelectedModelRow:) keyEquivalent:@""]];
    [menu addItem:[[NSMenuItem alloc] initWithTitle:ToNSString(titles.changeType) action:@selector(changeSelectedType:) keyEquivalent:@""]];
    NSMenuItem *remove = [[NSMenuItem alloc] initWithTitle:ToNSString(titles.removePredictor) action:@selector(removeSelectedTerm:) keyEquivalent:@""];
    if (representedTerm) [remove setRepresentedObject:representedTerm];
    [menu addItem:remove];
    [menu addItem:[[NSMenuItem alloc] initWithTitle:ToNSString(titles.showVariableInformation) action:@selector(showSelectedTermInformation:) keyEquivalent:@""]];
    [menu addItem:[NSMenuItem separatorItem]];
    if (!state || !AddInteractionMenuItems(menu, self, @selector(addTermFromMenu:), &state->seed, state->response, state->terms, baseTerm)) {
        NSMenuItem *disabled = [[NSMenuItem alloc] initWithTitle:ToNSString(titles.noAvailableInteractions) action:nil keyEquivalent:@""];
        [disabled setEnabled:NO];
        [menu addItem:disabled];
    }
    [menu addItem:[NSMenuItem separatorItem]];
    AddModelDiagnosticPlotMenuItems(menu, self, @selector(openDiagnosticFromMenu:), false);
    if (state && state->binaryRegression) {
        [menu addItem:[NSMenuItem separatorItem]];
        [menu addItem:[self binaryExportMenuItem]];
    }
    for (NSMenuItem *item in [menu itemArray]) {
        if ([item action] && ![item target]) [item setTarget:self];
    }
    return menu;
}

- (void)openBinaryPairwiseComparisons:(id)sender
{
    GeneralizedGLMState *state = [self state];
    NSString *represented = [sender representedObject];
    if (!state || !state->binaryRegression || !represented) return;
    const std::string term([represented UTF8String]);
    DataFrameModel dataframe;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        const DataFrameModel *current = FindDataFrameUnlockedConst(state->group);
        if (!current) {
            [_statusField setStringValue:@"Status: dataset is no longer available."];
            return;
        }
        dataframe = *current;
    }
    rlispstat::core::GLMPairwiseComparisonResult result;
    result.term = term;
    const DataColumn *factor = FindDataColumnInDataFrame(dataframe, term);
    if (factor) {
        std::set<std::string> seen;
        for (int row : state->rowsUsed) {
            if (row <= 0 || static_cast<std::size_t>(row) > factor->values.size()) continue;
            const std::string &value = factor->values[static_cast<std::size_t>(row - 1)];
            if (!DataCellIsMissing(value) && seen.insert(value).second) result.levels.push_back(value);
        }
        rlispstat::core::SortFactorLevelsLikeR(result.levels);
    }
    std::string message;
    if (!RunRBackedBinaryPairwiseComparisons(dataframe, *state, term, &result, &message)) {
        [_statusField setStringValue:ToNSString(GLMStatusMessage(message))];
        return;
    }
    GLMPairwiseComparisonPlotLink link = BuildGLMPairwiseComparisonPlotLink(
        state->group, dataframe, state->response, term, state->rowsUsed, result);
    link.method = result.method;
    link.levels = result.levels;
    link.binaryRegression = true;
    link.binaryOddsRatio = state->binaryLink == rlispstat::core::BinaryLink::Logit;
    link.rowsByComparison.assign(result.comparisons.size(), {});
    link.observations.clear();
    link.rowsByLevel.clear();
    const DataColumn *response = FindDataColumnInDataFrame(dataframe, state->response);
    if (factor && response) {
        for (int row : state->rowsUsed) {
            if (row <= 0) continue;
            std::size_t index = static_cast<std::size_t>(row - 1);
            if (index >= factor->values.size() || index >= response->values.size()) continue;
            const std::string &level = factor->values[index];
            const std::string &observed = response->values[index];
            if (DataCellIsMissing(level) || DataCellIsMissing(observed)) continue;
            double binary = observed == state->responseCoding.eventValue ? 1.0 : 0.0;
            link.rowsByLevel[level].insert(row);
            link.observations.push_back({row, level, binary});
        }
        for (std::size_t index = 0; index < result.comparisons.size(); ++index) {
            const auto &comparison = result.comparisons[index];
            for (const std::string &level : {comparison.firstLevel, comparison.secondLevel}) {
                auto found = link.rowsByLevel.find(level);
                if (found != link.rowsByLevel.end()) link.rowsByComparison[index].insert(found->second.begin(), found->second.end());
            }
        }
    }
    ShowGLMPairwiseResultsWindowOnMain(term, result, link);
    [_statusField setStringValue:ToNSString("Pairwise comparisons calculated in R for " + term + ".")];
}

