- (NSMenu *)modelActionContextMenu
{
    GeneralizedGLMState *state = [self state];
    const auto titles = rlispstat::core::DefaultModelContextMenuTitles();
    NSMenu *menu = [[NSMenu alloc] initWithTitle:ToNSString(titles.model)];
    [menu addItem:[self modelMenuItem:ToNSString(titles.refitModel) action:@selector(refitModel:) represented:nil]];
    [menu addItem:[self modelMenuItem:ToNSString(rlispstat::core::AutoRefitMenuTitle(state && state->autoRefit))
                                action:@selector(toggleAutoRefitFromMenu:) represented:nil]];
    [menu addItem:[NSMenuItem separatorItem]];
    NSMenuItem *diagnosticsItem = [[NSMenuItem alloc] initWithTitle:ToNSString(titles.openDiagnostics) action:nil keyEquivalent:@""];
    NSMenu *diagMenu = [[NSMenu alloc] initWithTitle:ToNSString(titles.openDiagnostics)];
    AddModelDiagnosticPlotMenuItems(diagMenu, self, @selector(openDiagnosticFromMenu:), true);
    if (state && state->binaryRegression) {
        for (NSArray *spec in @[@[@"ROC curve", @"roc_curve"], @[@"Observed vs fitted probability", @"calibration_plot"]]) {
            NSMenuItem *item = [[NSMenuItem alloc] initWithTitle:spec[0] action:@selector(openDiagnosticFromMenu:) keyEquivalent:@""];
            [item setTarget:self];
            [item setRepresentedObject:spec[1]];
            [diagMenu addItem:item];
        }
    }
    [menu setSubmenu:diagMenu forItem:diagnosticsItem];
    [menu addItem:diagnosticsItem];
    if (state && state->binaryRegression) {
        [menu addItem:[self modelMenuItem:(_showModelDetails ? @"Hide model details" : @"Show model details")
                                    action:@selector(showModelDetails:) represented:nil]];
    }
    [menu addItem:[NSMenuItem separatorItem]];
    if (state && state->binaryRegression) {
        [menu addItem:[self binaryExportMenuItem]];
    } else {
        [menu addItem:[self modelMenuItem:ToNSString(titles.copyModelTable) action:@selector(copyModelTable:) represented:nil]];
        [menu addItem:[self modelMenuItem:ToNSString(titles.exportModelTablePdf) action:@selector(exportModelTableAsPDF:) represented:nil]];
    }
    [menu addItem:[self modelMenuItem:ToNSString(titles.rowsUsedExcluded) action:@selector(showRowsUsedExcluded:) represented:nil]];
    return menu;
}

- (NSMenu *)contextMenuForCoefficientRow:(NSInteger)row column:(NSInteger)column
{
    _selectedCoefRow = row;
    _selectedCoefColumn = column;
    if (row < 0) return [self modelActionContextMenu];
    if ([self isAddTermRow:row]) return [self addTermContextMenu];
    if (column >= 0 && column < [self coefficientColumnCount]) {
        NSString *identifier = [self coefficientColumnIdentifier:column];
        if (![identifier isEqualToString:@"term"] && ![identifier isEqualToString:@"type"]) {
            return [self statisticContextMenuForTableRow:row column:column];
        }
    }
    if (row > 0) return [self predictorContextMenuForTableRow:row];
    return [self statisticContextMenuForTableRow:row column:column];
}

- (void)showStatisticMenuForTableRow:(NSInteger)row column:(NSInteger)column
{
    NSMenu *menu = [self statisticContextMenuForTableRow:row column:column];
    GeneralizedGLMReportLayout layout = GeneralizedGLMReportLayout::Compute([self coefficientRowCount], [_reportView bounds].size.width,
        [self coefficientColumnCount], [self binaryTermTestCount], [self binaryWarningCount], [self showsModelDetails]);
    NSRect rowRect = NSMakeRect(0, layout.coefRowsY + row * layout.rowHeight, [_reportView bounds].size.width, layout.rowHeight);
    [menu popUpMenuPositioningItem:nil atLocation:NSMakePoint(NSMidX(rowRect), NSMaxY(rowRect)) inView:_reportView];
}

- (void)coefficientCellClickedAtRow:(NSInteger)row column:(NSInteger)column
{
    if (row < 0) return;
    _selectedCoefRow = row;
    _selectedCoefColumn = column;
    GeneralizedGLMState *state = [self state];
    if (state && state->precomputed) {
        NSString *identifier = [self coefficientColumnIdentifier:column];
        if ([self isAddTermRow:row] ||
            [identifier isEqualToString:@"term"] ||
            [identifier isEqualToString:@"type"]) {
            [_statusField setStringValue:ToNSString(GLMPooledTableChangeInRStatus())];
            return;
        }
    }
    if ([self isAddTermRow:row]) {
        GeneralizedGLMReportLayout layout = GeneralizedGLMReportLayout::Compute([self coefficientRowCount], [_reportView bounds].size.width,
            [self coefficientColumnCount], [self binaryTermTestCount], [self binaryWarningCount], [self showsModelDetails]);
        [self showAddTermMenuAtPoint:NSMakePoint(layout.margin + 10.0, layout.coefRowsY + row * layout.rowHeight + layout.rowHeight) inView:_reportView];
        return;
    }
    if (column < 0) return;
    NSString *identifier = [self coefficientColumnIdentifier:column];
    if ([identifier isEqualToString:@"term"] && row > 0) {
        [self replaceTermAtTableRow:row];
    } else if ([identifier isEqualToString:@"type"] && row > 0) {
        [self showTypeMenuForTableRow:row];
    } else if (![identifier isEqualToString:@"term"] && ![identifier isEqualToString:@"type"]) {
        [self showStatisticMenuForTableRow:row column:column];
    }
}

