                                action:@selector(toggleAutoRefitFromMenu:) represented:nil]];
    [menu addItem:[NSMenuItem separatorItem]];
    NSMenuItem *diagnosticsItem = [[NSMenuItem alloc] initWithTitle:ToNSString(titles.openDiagnostics) action:nil keyEquivalent:@""];
    NSMenu *diagMenu = [[NSMenu alloc] initWithTitle:ToNSString(titles.openDiagnostics)];
    AddModelDiagnosticPlotMenuItems(diagMenu, self, @selector(openDiagnosticFromMenu:), true);
    if (state->binaryRegression) {
        for (NSArray *spec in @[@[@"ROC curve", @"roc_curve"], @[@"Observed vs fitted probability", @"calibration_plot"]]) {
            NSMenuItem *item = [[NSMenuItem alloc] initWithTitle:spec[0] action:@selector(openDiagnosticFromMenu:) keyEquivalent:@""];
            [item setTarget:self];
            [item setRepresentedObject:spec[1]];
            [diagMenu addItem:item];
        }
    }
    [menu setSubmenu:diagMenu forItem:diagnosticsItem];
    [menu addItem:diagnosticsItem];
    if (state->binaryRegression) {
        [menu addItem:[self modelMenuItem:(_showModelDetails ? @"Hide model details" : @"Show model details")
                                    action:@selector(showModelDetails:) represented:nil]];
    }
    [menu addItem:[NSMenuItem separatorItem]];
    if (state->binaryRegression) {
