- (NSString *)binaryCSVForTable:(NSString *)table
{
    GeneralizedGLMState *state = [self state];
    if (!state || !state->binaryRegression) return @"";
    const bool termTests = table && [table isEqualToString:@"term_tests"];
    const bool modelFit = table && [table isEqualToString:@"model_fit"];
    return ToNSString(modelFit ? rlispstat::core::BinaryRegressionModelFitCSV(*state)
        : (termTests ? rlispstat::core::BinaryRegressionTermTestsCSV(*state)
                     : rlispstat::core::BinaryRegressionCoefficientCSV(*state)));
}

- (void)copyBinaryRSyntax:(id)sender
{
    (void)sender;
    GeneralizedGLMState *state = [self state];
    if (!state || !state->binaryRegression) return;
    auto rString = [](const std::string &value) {
        std::string out = "\"";
        for (char ch : value) { if (ch == '\\' || ch == '"') out.push_back('\\'); out.push_back(ch); }
        return out + "\"";
    };
    std::string terms = "character()";
    if (!state->terms.empty()) {
        terms = "c(";
        for (std::size_t i = 0; i < state->terms.size(); ++i) { if (i) terms += ", "; terms += rString(state->terms[i]); }
        terms += ")";
    }
    std::string syntax = "LinkEDA::ls_new_binary_regression(data = " + rString(state->group) +
        ", response = " + rString(state->response) + ", terms = " + terms + ", link = " + rString(state->link) +
        ", event = " + rString(state->responseCoding.eventValue) + ", reference = " + rString(state->responseCoding.referenceValue) + ")";
    NSPasteboard *pasteboard = [NSPasteboard generalPasteboard];
    [pasteboard clearContents]; [pasteboard setString:ToNSString(syntax) forType:NSPasteboardTypeString];
    [_statusField setStringValue:@"Status: R syntax copied."];
}

- (void)exportBinaryCSV:(id)sender
{
    GeneralizedGLMState *state = [self state];
    if (!state || !state->binaryRegression) return;
    NSString *table = [sender representedObject] ?: @"coefficients";
    NSSavePanel *panel = [NSSavePanel savePanel];
    [panel setAllowedFileTypes:@[@"csv"]];
    [panel setNameFieldStringValue:ToNSString(state->id + "_" + std::string([table UTF8String]) + ".csv")];
    if ([panel runModal] != NSModalResponseOK) return;
    NSError *error = nil;
    if (![[self binaryCSVForTable:table] writeToURL:[panel URL] atomically:YES encoding:NSUTF8StringEncoding error:&error]) {
        ShowWorkbenchMessageOnMain(@"Export table", error ? [error localizedDescription] : @"The CSV file could not be written.");
    }
}

- (void)copyModelTable:(id)sender
{
    (void)sender;
    GeneralizedGLMState *state = [self state];
    if (!state) return;
    NSPasteboard *pasteboard = [NSPasteboard generalPasteboard];
    [pasteboard clearContents];
    [pasteboard setString:[self formattedOutputForState:state] forType:NSPasteboardTypeString];
    [_statusField setStringValue:ToNSString(GLMModelTableCopiedStatus())];
}

- (void)exportModelTableAsPDF:(id)sender
{
    (void)sender;
    GeneralizedGLMState *state = [self state];
    if (!state) return;
    if (state->binaryRegression) {
        ExportBinaryRegressionPDF(*state, false, _showModelDetails);
        return;
    }
    NSSavePanel *panel = [NSSavePanel savePanel];
    [panel setAllowedFileTypes:@[@"pdf"]];
    [panel setNameFieldStringValue:ToNSString(state->id + ".pdf")];
    if ([panel runModal] != NSModalResponseOK) return;
    GeneralizedGLMReportLayout layout = GeneralizedGLMReportLayout::Compute([self coefficientRowCount], 760.0,
        [self coefficientColumnCount], [self binaryTermTestCount], [self binaryWarningCount], [self showsModelDetails]);
    CGFloat reportHeight = layout.totalHeight;
    CGFloat pageWidth = layout.width + 40.0;
    CGFloat pageHeight = reportHeight + 128.0;
    NSView *view = [[NSView alloc] initWithFrame:NSMakeRect(0, 0, pageWidth, pageHeight)];
    [view setWantsLayer:YES];
    [[view layer] setBackgroundColor:[[NSColor whiteColor] CGColor]];
    NSTextField *title = GLMLabel(state->binaryRegression ? @"Binary Regression" : ToNSString(rlispstat::core::GLMWindowTitle()), NSMakeRect(30, pageHeight - 46, 320, 24), 17, NSFontWeightSemibold);
    [view addSubview:title];
    std::string subtitle = state->group + "   Response: " + (state->response.empty() ? "\u2014" : state->response) +
        "   Family: " + state->family + "   Link: " + state->link;
    if (state->binaryRegression) subtitle += "   Event: " + state->responseCoding.eventLabel +
        "   Reference: " + state->responseCoding.referenceLabel;
    NSTextField *meta = GLMLabel(ToNSString(subtitle), NSMakeRect(30, pageHeight - 72, pageWidth - 60, 20), 12, NSFontWeightRegular);
    [view addSubview:meta];
    GeneralizedGLMReportView *report = [[GeneralizedGLMReportView alloc] initWithFrame:NSMakeRect(20, 24, layout.width, reportHeight)];
    [report setGlmController:self];
    [view addSubview:report];
    NSData *pdf = VisualExportDataForViewWithNotes(view, @"PDF", ActiveWindowNotesContainer());
    if ([pdf writeToURL:[panel URL] atomically:YES]) {
        [_statusField setStringValue:ToNSString(GLMModelTableExportedStatus())];
    } else {
        [_statusField setStringValue:ToNSString(GLMPDFWriteFailedStatus())];
    }
}

