- (void)showAddTermMenuAtPoint:(NSPoint)point inView:(NSView *)view
{
    GeneralizedGLMState *state = [self state];
    if (!state) return;
    NSMenu *menu = [[NSMenu alloc] initWithTitle:ToNSString(rlispstat::core::GLMAddTermTitle())];
	    for (const std::string &name : VariableNamesForModel(&state->seed)) {
	        if (name == state->response) continue;
	        if (std::find(state->terms.begin(), state->terms.end(), name) != state->terms.end()) continue;
	        std::string display = name + " (" + rlispstat::core::ModelTermDisplayType(&state->seed, name, state->termTypes) + ")";
	        NSMenuItem *item = [[NSMenuItem alloc] initWithTitle:ToNSString(display) action:@selector(addTermFromMenu:) keyEquivalent:@""];
        [item setTarget:self];
        [item setRepresentedObject:ToNSString(name)];
        [menu addItem:item];
    }
    if ([menu numberOfItems] > 0) {
        [menu addItem:[NSMenuItem separatorItem]];
    }
    if (!AddInteractionMenuItems(menu, self, @selector(addTermFromMenu:), &state->seed, state->response, state->terms)) {
        NSInteger last = [menu numberOfItems] - 1;
        if (last >= 0 && [[menu itemAtIndex:last] isSeparatorItem]) {
            [menu removeItemAtIndex:last];
        }
    }
    if ([[menu itemArray] count] == 0) {
        NSMenuItem *item = [[NSMenuItem alloc] initWithTitle:ToNSString(rlispstat::core::MixedModelNoAvailablePredictorsLabel()) action:nil keyEquivalent:@""];
        [item setEnabled:NO];
        [menu addItem:item];
    }
    [menu popUpMenuPositioningItem:nil atLocation:point inView:view];
}

- (void)addTermFromMenu:(id)sender
{
    NSString *title = [sender representedObject];
    if (!title) return;
    GeneralizedGLMState *state = [self state];
    if (!state) return;
    std::string name = std::string([title UTF8String]);
    if (name != state->response &&
        AddHierarchicalTermsToVector(&state->seed, state->response, state->terms, name)) {
        [self markChangedAndRefresh];
    }
}

- (void)removeLastTerm:(id)sender
{
    [self removeSelectedTerm:sender];
}

- (void)removeSelectedTerm:(id)sender
{
    GeneralizedGLMState *state = [self state];
    if (!state || state->terms.empty()) return;
    if (state->precomputed) {
        [_statusField setStringValue:ToNSString(GLMPooledTableChangeInRStatus())];
        return;
    }
    std::string term;
    if (sender && [sender respondsToSelector:@selector(representedObject)]) {
        id represented = [sender representedObject];
        if ([represented isKindOfClass:[NSString class]] && [(NSString *)represented length] > 0) {
            term = [(NSString *)represented UTF8String];
        }
    }
    if (term.empty()) term = [self lastTerm];
    if (term.empty()) return;
    state->terms.erase(std::remove_if(state->terms.begin(), state->terms.end(),
                                      [&](const std::string &candidate) {
                                          return ModelTermShouldBeRemoved(candidate, term);
                                      }),
                       state->terms.end());
    for (auto it = state->termTypes.begin(); it != state->termTypes.end(); ) {
        if (ModelTermShouldBeRemoved(it->first, term)) {
            it = state->termTypes.erase(it);
        } else {
            ++it;
        }
    }
    _selectedCoefRow = -1;
    _selectedCoefColumn = -1;
    [self markChangedAndRefresh];
}

- (void)windowWillClose:(NSNotification *)notification
{
    (void)notification;
    g_generalizedGLMControllers.erase(_modelId);
}

