static ModelTrellisState *FindModelTrellisUnlocked(const std::string &identifier)
{
    auto found = g_modelTrellises.find(identifier);
    return found == g_modelTrellises.end() ? nullptr : &found->second;
}

static bool RebuildModelTrellisPanelsUnlocked(ModelTrellisState &state)
{
    const DataFrameModel *data = FindDataFrameUnlockedConst(state.specification.baseModel.group);
    if (!data) return false;
    std::set<int> selection;
    const std::vector<int> capturedRows = RowsForCapturedAnalysisScope(
        state.dataScope, state.dataScopeCaptured);
    if (state.dataScopeCaptured &&
        state.dataScope.kind == rlispstat::core::AnalysisScopeKind::ExplicitRowIds) {
        selection.insert(capturedRows.begin(), capturedRows.end());
        state.specification.baseModel.scope = "selected";
    } else {
        auto selected = g_groupSelections.find(state.specification.baseModel.group);
        if (selected != g_groupSelections.end()) selection = selected->second;
    }
    state.panels = rlispstat::core::BuildModelTrellisPanels(
        state.specification, *data, selection);
    ++state.specificationGeneration;
    state.fittedGeneration = 0;
    state.fitPending = false;
    state.status = "Waiting for R panel fits...";
    return true;
}

static void RequestModelTrellisFit(const std::string &identifier)
{
    MainRModelTrellisTask task;
    bool ready = false;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        ModelTrellisState *state = FindModelTrellisUnlocked(identifier);
        if (!state || state->fitPending) return;
        state->fitPending = true;
        state->status = "Fitting panel models in R...";
        const auto &spec = state->specification;
        task.id = state->id;
        task.generation = state->specificationGeneration;
        task.group = spec.baseModel.group;
        task.response = spec.baseModel.response;
        task.scope = spec.baseModel.scope;
        task.confidenceLevel = spec.baseModel.confidenceLevel;
        task.pAdjustment = rlispstat::core::ModelTrellisPAdjustmentId(spec.pAdjustment);
        task.baseTerms = spec.baseModel.terms;
        task.effectiveTerms = rlispstat::core::EffectiveModelTrellisTerms(spec, &task.omittedTerms);
        task.termTypes = spec.baseModel.termTypes;
        for (const ModelTrellisPanelResult &panel : state->panels) {
            task.panels.push_back({panel.panelId,
                panel.key.rowLevelId.value_or(""), panel.rowLevelLabel,
                panel.key.columnLevelId.value_or(""), panel.columnLevelLabel,
                panel.candidateOriginalRows});
        }
        ready = true;
    }
    if (ready) QueueModelTrellisMainRTask(task);
}

static NSDictionary *ModelTrellisTextAttributes(CGFloat size, NSFontWeight weight,
                                                  NSTextAlignment alignment = NSTextAlignmentLeft,
                                                  NSColor *color = nil)
{
    NSMutableParagraphStyle *style = [[NSMutableParagraphStyle alloc] init];
    [style setAlignment:alignment];
    return @{NSFontAttributeName: [NSFont systemFontOfSize:size weight:weight],
             NSForegroundColorAttributeName: color ? color : [NSColor colorWithCalibratedWhite:0.16 alpha:1.0],
             NSParagraphStyleAttributeName: style};
}

static NSString *ModelTrellisNumber(double value, int digits = 3)
{
    return std::isfinite(value) ? ToNSString(FormatDouble(value, digits)) : @"\U00002014";
}

static NSString *ModelTrellisP(double value)
{
    return std::isfinite(value) ? ToNSString(FormatPValue(value)) : @"\U00002014";
}

static const ModelTrellisCoefficientResult *ModelTrellisDisplayedCoefficient(
    const ModelTrellisState &state, const ModelTrellisPanelResult &panel)
{
    const std::string coefficient = state.specification.displayedCoefficientId.value_or("");
    if (!coefficient.empty()) for (const auto &row : panel.coefficients) if (row.coefficientId == coefficient) return &row;
    const std::string term = state.specification.displayedTermId.value_or("");
    for (const auto &row : panel.coefficients) if (row.sourceTermId == term && row.estimable) return &row;
    return nullptr;
}

static const rlispstat::core::ModelTrellisTermTestResult *ModelTrellisDisplayedTermTest(
    const ModelTrellisState &state, const ModelTrellisPanelResult &panel)
{
    const std::string term = state.specification.displayedTermId.value_or("");
    for (const auto &test : panel.termTests) if (test.termId == term) return &test;
    return nullptr;
}

static void DrawModelTrellisCell(NSString *text, NSRect rect, BOOL numeric, BOOL bold = NO)
{
    [text drawInRect:NSInsetRect(rect, 3.0, 2.0)
      withAttributes:ModelTrellisTextAttributes(11.0, bold ? NSFontWeightSemibold : NSFontWeightRegular,
                                               numeric ? NSTextAlignmentRight : NSTextAlignmentLeft)];
}

static NSArray<NSString *> *ModelTrellisSelectedCoefficientHeaders()
{
    return @[@"Term", @"B", @"SE", @"95% CI", @"t", @"p", @"p adj."];
}

static NSArray<NSString *> *ModelTrellisSelectedCoefficientValues(
    const ModelTrellisCoefficientResult &coefficient)
{
    NSString *interval = [NSString stringWithFormat:@"[%@, %@]",
        ModelTrellisNumber(coefficient.confidenceLower),
        ModelTrellisNumber(coefficient.confidenceUpper)];
    return @[ToNSString(coefficient.label), ModelTrellisNumber(coefficient.estimate),
        ModelTrellisNumber(coefficient.standardError), interval,
        ModelTrellisNumber(coefficient.statistic), ModelTrellisP(coefficient.pValue),
        ModelTrellisP(coefficient.adjustedPValue)];
}

static std::vector<CGFloat> ModelTrellisSelectedCoefficientColumnWidths(
    const ModelTrellisState &state)
{
    NSMutableArray<NSArray<NSString *> *> *rows = [NSMutableArray array];
    for (const ModelTrellisPanelResult &panel : state.panels) {
        const ModelTrellisCoefficientResult *coefficient =
            ModelTrellisDisplayedCoefficient(state, panel);
        if (coefficient) [rows addObject:ModelTrellisSelectedCoefficientValues(*coefficient)];
    }
    return NativeResultColumnWidths(ModelTrellisSelectedCoefficientHeaders(), rows,
        {77.0, 43.0, 43.0, 92.0, 42.0, 46.0, 54.0});
}

static CGFloat ModelTrellisPanelWidth(const ModelTrellisState &state)
{
    CGFloat tableWidth = 352.0;
    if (state.specification.panelContent == ModelTrellisPanelContent::SelectedResult) {
        const std::vector<CGFloat> selected =
            ModelTrellisSelectedCoefficientColumnWidths(state);
        tableWidth = std::max((CGFloat)356.0,
            std::accumulate(selected.begin(), selected.end(), (CGFloat)0.0));
    } else if (state.specification.panelContent == ModelTrellisPanelContent::Coefficients) {
        tableWidth = 390.0;
    } else if (state.specification.panelContent == ModelTrellisPanelContent::TermTests) {
        tableWidth = 356.0;
    }
    // The row-conditioning strip lives in one gutter after the last column.  It
    // must not be subtracted from every panel or repeated in every column step.
    return std::max((CGFloat)380.0, tableWidth + 22.0);
}

static CGFloat ModelTrellisRowStripWidth(const ModelTrellisState &state)
{
    return state.specification.rowConditioningVariable ? 86.0 : 0.0;
}

static NSArray<NSString *> *ModelTrellisAPAHeaders()
{
    return @[@"Row", @"Column", @"N", @"Estimate", @"SE", @"95% CI",
        @"t/F", @"df", @"p", @"p adj.", @"R\u00b2"];
}

static NSArray<NSString *> *ModelTrellisAPAValues(const ModelTrellisState &state,
                                                   const ModelTrellisPanelResult &panel)
{
    const ModelTrellisCoefficientResult *coefficient =
        ModelTrellisDisplayedCoefficient(state, panel);
    const auto *test = ModelTrellisDisplayedTermTest(state, panel);
    const std::string term = state.specification.displayedTermId.value_or("");
    const auto type = state.specification.baseModel.termTypes.find(term);
    const bool global = test && (!coefficient || test->df1 > 1.0 ||
        IsInteractionTerm(term) || (type != state.specification.baseModel.termTypes.end() &&
        type->second == "factor"));
    NSString *interval = coefficient ? [NSString stringWithFormat:@"[%@, %@]",
        ModelTrellisNumber(coefficient->confidenceLower),
        ModelTrellisNumber(coefficient->confidenceUpper)] : @"";
    NSString *degreesOfFreedom = global
        ? [NSString stringWithFormat:@"%@, %@", ModelTrellisNumber(test->df1),
            ModelTrellisNumber(test->df2)]
        : [NSString stringWithFormat:@"%d", panel.modelResult.dfResidual];
    return @[ToNSString(panel.rowLevelLabel), ToNSString(panel.columnLevelLabel),
        [NSString stringWithFormat:@"%d", panel.modelResult.n],
        global ? @"" : (coefficient ? ModelTrellisNumber(coefficient->estimate) : @""),
        global ? @"" : (coefficient ? ModelTrellisNumber(coefficient->standardError) : @""),
        interval,
        global ? ModelTrellisNumber(test->statistic) :
            (coefficient ? ModelTrellisNumber(coefficient->statistic) : @""),
        degreesOfFreedom,
        global ? ModelTrellisP(test->pValue) :
            (coefficient ? ModelTrellisP(coefficient->pValue) : @""),
        global ? ModelTrellisP(test->adjustedPValue) :
            (coefficient ? ModelTrellisP(coefficient->adjustedPValue) : @""),
        ModelTrellisNumber(panel.modelResult.r2)];
}

static std::vector<CGFloat> ModelTrellisAPAColumnWidths(const ModelTrellisState &state)
{
    NSMutableArray<NSArray<NSString *> *> *rows = [NSMutableArray array];
    for (const ModelTrellisPanelResult &panel : state.panels) {
        [rows addObject:ModelTrellisAPAValues(state, panel)];
    }
    return NativeResultColumnWidths(ModelTrellisAPAHeaders(), rows,
        {58.0, 65.0, 35.0, 64.0, 55.0, 112.0, 55.0, 62.0, 50.0, 58.0, 48.0});
}

@implementation ModelTrellisContentView
- (NSString *)snapshotTabDelimitedText
{
    std::lock_guard<std::mutex> lock(g_mutex);
    ModelTrellisState *state = FindModelTrellisUnlocked(_modelTrellisId);
    return state ? ToNSString(SnapshotCSVToTabDelimited(
        rlispstat::core::ModelTrellisAllResultsCSV(*state))) : @"";
}
- (BOOL)isFlipped { return YES; }

- (void)drawRect:(NSRect)dirtyRect
{
    (void)dirtyRect;
    ModelTrellisState state;
    std::set<int> selection;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        ModelTrellisState *found = FindModelTrellisUnlocked(_modelTrellisId);
        if (!found) return;
        state = *found;
        auto selected = g_groupSelections.find(state.specification.baseModel.group);
        if (selected != g_groupSelections.end()) selection = selected->second;
    }
    [WorkbenchSurfaceColor() setFill];
    NSRectFill([self bounds]);
    _panelRects.clear();
    const CGFloat margin = 18.0, titleY = 14.0;
    std::string conditioned;
    if (state.specification.rowConditioningVariable) conditioned = state.specification.rowConditioningVariable->variableId;
    if (state.specification.columnConditioningVariable) {
        if (!conditioned.empty()) conditioned += " and ";
        conditioned += state.specification.columnConditioningVariable->variableId;
    }
    const std::string internalTitle = state.specification.baseModel.response + " model" +
        (conditioned.empty() ? "" : ", conditioned by " + conditioned);
    [ToNSString(internalTitle) drawAtPoint:NSMakePoint(margin, titleY)
                            withAttributes:ModelTrellisTextAttributes(17.0, NSFontWeightSemibold)];
    const std::string subtitle = std::string(conditioned.empty() ? "Separate panel fit" : "Separate panel fits") +
        " \u00b7 Base model: " + rlispstat::core::ModelTrellisFormulaText(state.specification.baseModel);
    [ToNSString(subtitle) drawAtPoint:NSMakePoint(margin, 42.0)
                        withAttributes:ModelTrellisTextAttributes(12.0, NSFontWeightRegular,
                            NSTextAlignmentLeft, [NSColor secondaryLabelColor])];

    const rlispstat::core::ModelTrellisLayout layout = rlispstat::core::BuildModelTrellisLayout(state);
    const CGFloat panelWidth = ModelTrellisPanelWidth(state);
    const std::vector<CGFloat> selectedCoefficientWidths =
        ModelTrellisSelectedCoefficientColumnWidths(state);
    CGFloat panelHeight = 168.0;
    if (state.specification.panelContent == ModelTrellisPanelContent::Coefficients) {
        std::size_t count = 1; for (const auto &p : state.panels) count = std::max(count, p.coefficients.size());
        panelHeight = 82.0 + 21.0 * count;
    } else if (state.specification.panelContent == ModelTrellisPanelContent::TermTests) {
        std::size_t count = 1; for (const auto &p : state.panels) count = std::max(count, p.termTests.size());
        panelHeight = 82.0 + 21.0 * count;
    }
    const CGFloat rowStripWidth = ModelTrellisRowStripWidth(state);
    const CGFloat top = 88.0;
    for (std::size_t i = 0; i < state.panels.size(); ++i) {
        const auto &panel = state.panels[i];
        auto placement = std::find_if(layout.panels.begin(), layout.panels.end(), [&](const auto &x) { return x.panelId == panel.panelId; });
        if (placement == layout.panels.end()) continue;
        const CGFloat x = margin + placement->column * panelWidth;
        const CGFloat y = top + placement->row * panelHeight;
        NSRect panelRect = NSMakeRect(x, y, panelWidth - 12.0, panelHeight - 12.0);
        _panelRects.push_back({panel.panelId, panelRect});
        bool selectedPanel = false; int selectedCount = 0;
        for (int row : panel.originalRowIndices) if (selection.count(row)) { selectedPanel = true; ++selectedCount; }
        [(selectedPanel ? [NSColor colorWithCalibratedWhite:0.92 alpha:1.0] : WorkbenchSurfaceColor()) setFill];
        NSRectFill(panelRect);
        [[NSColor separatorColor] setStroke];
        NSBezierPath *border = [NSBezierPath bezierPath];
        [border moveToPoint:NSMakePoint(NSMinX(panelRect), NSMinY(panelRect))];
        [border lineToPoint:NSMakePoint(NSMaxX(panelRect), NSMinY(panelRect))];
        [border stroke];
        if (state.specification.columnConditioningVariable && placement->row == 0) {
            NSString *strip = ToNSString(state.specification.columnConditioningVariable->variableId + " = " + panel.columnLevelLabel);
            NSRect stripRect = NSMakeRect(NSMinX(panelRect), y - 25.0, NSWidth(panelRect), 20.0);
            [strip drawInRect:stripRect withAttributes:ModelTrellisTextAttributes(12.0, NSFontWeightSemibold, NSTextAlignmentCenter)];
        }
        if (state.specification.rowConditioningVariable && placement->column + 1 == layout.columns) {
            NSString *strip = ToNSString(state.specification.rowConditioningVariable->variableId + " = " + panel.rowLevelLabel);
            const CGFloat stripHeight = 40.0;
            NSRect stripRect = NSMakeRect(NSMaxX(panelRect) + 7.0,
                NSMidY(panelRect) - stripHeight * 0.5, rowStripWidth - 10.0, stripHeight);
            [strip drawInRect:stripRect withAttributes:ModelTrellisTextAttributes(12.0, NSFontWeightSemibold, NSTextAlignmentCenter)];
        }
        const bool waitingForR = state.fitPending &&
            state.fittedGeneration < state.specificationGeneration;
        if (waitingForR) {
            NSString *candidateSummary = [NSString stringWithFormat:@"%lu candidate rows%@",
                (unsigned long)panel.candidateOriginalRows.size(),
                selectedPanel ? [NSString stringWithFormat:@" \u00b7 %d selected", selectedCount] : @""];
            [candidateSummary drawInRect:NSMakeRect(NSMinX(panelRect) + 6, NSMinY(panelRect) + 7,
                                                    NSWidth(panelRect) - 12, 18)
                           withAttributes:ModelTrellisTextAttributes(11.0, NSFontWeightMedium)];
            [@"Fitting model in R\u2026" drawInRect:NSMakeRect(NSMinX(panelRect) + 8,
                                                              NSMinY(panelRect) + 38,
                                                              NSWidth(panelRect) - 16, 22)
                                      withAttributes:ModelTrellisTextAttributes(
                                          12.0, NSFontWeightSemibold,
                                          NSTextAlignmentLeft, [NSColor secondaryLabelColor])];
            continue;
        }
        NSString *summary = [NSString stringWithFormat:@"N = %d \u00b7 R\u00b2 = %@ \u00b7 Adjusted R\u00b2 = %@%@",
            panel.modelResult.n, ModelTrellisNumber(panel.modelResult.r2), ModelTrellisNumber(panel.modelResult.adjR2),
            selectedPanel ? [NSString stringWithFormat:@" \u00b7 %d selected", selectedCount] : @""];
        [summary drawInRect:NSMakeRect(NSMinX(panelRect) + 6, NSMinY(panelRect) + 7, NSWidth(panelRect) - 12, 18)
              withAttributes:ModelTrellisTextAttributes(11.0, NSFontWeightMedium)];
        if (!panel.hasObservations || !panel.modelResult.ok) {
            NSString *message = !panel.hasObservations ? @"No observations" : @"Model not estimable";
            [message drawInRect:NSMakeRect(NSMinX(panelRect) + 8, NSMinY(panelRect) + 38, NSWidth(panelRect) - 16, 22)
                 withAttributes:ModelTrellisTextAttributes(12.0, NSFontWeightSemibold)];
            if (!panel.warnings.empty()) [ToNSString(panel.warnings.front()) drawInRect:NSMakeRect(NSMinX(panelRect) + 8, NSMinY(panelRect) + 61, NSWidth(panelRect) - 16, 48)
                withAttributes:ModelTrellisTextAttributes(10.5, NSFontWeightRegular, NSTextAlignmentLeft, [NSColor secondaryLabelColor])];
            continue;
        }
        CGFloat tableY = NSMinY(panelRect) + 31.0;
        auto drawRule = [&](CGFloat yLine) { [[NSColor separatorColor] setStroke]; NSBezierPath *p = [NSBezierPath bezierPath]; [p moveToPoint:NSMakePoint(NSMinX(panelRect)+4,yLine)]; [p lineToPoint:NSMakePoint(NSMaxX(panelRect)-4,yLine)]; [p stroke]; };
        if (state.specification.panelContent == ModelTrellisPanelContent::CompactSummary ||
            state.specification.panelContent == ModelTrellisPanelContent::ModelFit) {
            NSArray *labels = @[@"Statistic", @"Value", @"df", @"p", @"p adj."];
            CGFloat widths[5] = {120, 62, 54, 54, 62}; CGFloat cx = NSMinX(panelRect)+5;
            for (int c=0;c<5;++c){ DrawModelTrellisCell(labels[c], NSMakeRect(cx,tableY,widths[c],20), c>0, YES); cx+=widths[c]; }
            drawRule(tableY+20); tableY+=23;
            NSArray *values = @[@"Global model", ModelTrellisNumber(panel.modelResult.globalF),
                [NSString stringWithFormat:@"%d, %d",panel.modelResult.dfModel,panel.modelResult.dfResidual],
                ModelTrellisP(panel.modelResult.globalP), ModelTrellisP(panel.adjustedGlobalPValue)];
            cx=NSMinX(panelRect)+5; for(int c=0;c<5;++c){DrawModelTrellisCell(values[c],NSMakeRect(cx,tableY,widths[c],20),c>0);cx+=widths[c];}
            tableY+=22;
            DrawModelTrellisCell(@"Residual s", NSMakeRect(NSMinX(panelRect)+5,tableY,120,20), NO);
            DrawModelTrellisCell(ModelTrellisNumber(panel.modelResult.sigma), NSMakeRect(NSMinX(panelRect)+125,tableY,62,20), YES);
        } else if (state.specification.panelContent == ModelTrellisPanelContent::SelectedResult) {
            const auto *test = ModelTrellisDisplayedTermTest(state, panel);
            const auto *coef = ModelTrellisDisplayedCoefficient(state, panel);
            const std::string displayedTerm=state.specification.displayedTermId.value_or("");auto displayedType=state.specification.baseModel.termTypes.find(displayedTerm);const bool global = test && (!coef || test->df1 > 1.0 || IsInteractionTerm(displayedTerm) || (displayedType!=state.specification.baseModel.termTypes.end()&&displayedType->second=="factor"));
            if (global) {
                NSArray *headers=@[@"Term",@"F",@"df1",@"df2",@"p",@"p adj."]; CGFloat w[6]={112,50,42,42,52,58}; CGFloat cx=NSMinX(panelRect)+5;
                for(int c=0;c<6;++c){DrawModelTrellisCell(headers[c],NSMakeRect(cx,tableY,w[c],20),c>0,YES);cx+=w[c];} drawRule(tableY+20); tableY+=23;
                NSArray *vals=@[ToNSString(test->label),ModelTrellisNumber(test->statistic),ModelTrellisNumber(test->df1),ModelTrellisNumber(test->df2),ModelTrellisP(test->pValue),ModelTrellisP(test->adjustedPValue)];
                cx=NSMinX(panelRect)+5;for(int c=0;c<6;++c){DrawModelTrellisCell(vals[c],NSMakeRect(cx,tableY,w[c],20),c>0);cx+=w[c];}
            } else if (coef) {
                NSArray *headers=ModelTrellisSelectedCoefficientHeaders(); CGFloat cx=NSMinX(panelRect)+5;
                for(int c=0;c<7;++c){const CGFloat width=selectedCoefficientWidths[(std::size_t)c];DrawModelTrellisCell(headers[c],NSMakeRect(cx,tableY,width,20),c>0,YES);cx+=width;} drawRule(tableY+20); tableY+=23;
                NSArray *vals=ModelTrellisSelectedCoefficientValues(*coef);
                cx=NSMinX(panelRect)+5;for(int c=0;c<7;++c){const CGFloat width=selectedCoefficientWidths[(std::size_t)c];DrawModelTrellisCell(vals[c],NSMakeRect(cx,tableY,width,20),c>0);cx+=width;}
            } else {
                DrawModelTrellisCell(@"Selected result is not estimable in this panel.", NSMakeRect(NSMinX(panelRect)+6,tableY,NSWidth(panelRect)-12,22), NO);
            }
        } else if (state.specification.panelContent == ModelTrellisPanelContent::Coefficients) {
            NSArray *headers=@[@"Variable",@"B",@"SE",@"t",@"p",@"p adj."]; CGFloat w[6]={118,52,52,52,54,62}; CGFloat cx=NSMinX(panelRect)+5;
            for(int c=0;c<6;++c){DrawModelTrellisCell(headers[c],NSMakeRect(cx,tableY,w[c],20),c>0,YES);cx+=w[c];} drawRule(tableY+20); tableY+=22;
            for(const auto &row:panel.coefficients){cx=NSMinX(panelRect)+5; NSArray *vals=@[ToNSString(row.label),ModelTrellisNumber(row.estimate),ModelTrellisNumber(row.standardError),ModelTrellisNumber(row.statistic),ModelTrellisP(row.pValue),ModelTrellisP(row.adjustedPValue)];for(int c=0;c<6;++c){DrawModelTrellisCell(vals[c],NSMakeRect(cx,tableY,w[c],20),c>0);cx+=w[c];}tableY+=21;}
        } else {
            NSArray *headers=@[@"Term",@"F",@"df1",@"df2",@"p",@"p adj."]; CGFloat w[6]={112,50,42,42,52,58}; CGFloat cx=NSMinX(panelRect)+5;
            for(int c=0;c<6;++c){DrawModelTrellisCell(headers[c],NSMakeRect(cx,tableY,w[c],20),c>0,YES);cx+=w[c];} drawRule(tableY+20); tableY+=22;
            for(const auto &test:panel.termTests){cx=NSMinX(panelRect)+5;NSArray *vals=@[ToNSString(test.label),ModelTrellisNumber(test.statistic),ModelTrellisNumber(test.df1),ModelTrellisNumber(test.df2),ModelTrellisP(test.pValue),ModelTrellisP(test.adjustedPValue)];for(int c=0;c<6;++c){DrawModelTrellisCell(vals[c],NSMakeRect(cx,tableY,w[c],20),c>0);cx+=w[c];}tableY+=21;}
        }
        if (!panel.warnings.empty()) [@"\u26a0" drawAtPoint:NSMakePoint(NSMaxX(panelRect)-22,NSMinY(panelRect)+6) withAttributes:ModelTrellisTextAttributes(12,NSFontWeightRegular)];
    }
    const CGFloat noteY = top + layout.rows * panelHeight + 8.0;
    [ToNSString(rlispstat::core::ModelTrellisMethodologicalNote()) drawInRect:NSMakeRect(margin,noteY,NSWidth([self bounds])-2*margin,36)
        withAttributes:ModelTrellisTextAttributes(10.5,NSFontWeightRegular,NSTextAlignmentLeft,[NSColor secondaryLabelColor])];
    int validPanels=0;
    for(const auto&p:state.panels){const auto*c=ModelTrellisDisplayedCoefficient(state,p);const auto*t=ModelTrellisDisplayedTermTest(state,p);if((c&&c->estimable)||(t&&t->estimable))++validPanels;}
    std::string adjustmentNote;
    if(state.specification.pAdjustment!=ModelTrellisPAdjustment::None&&validPanels>0)adjustmentNote=" Adjusted p values use "+rlispstat::core::ModelTrellisPAdjustmentLabel(state.specification.pAdjustment)+"'s method across "+std::to_string(validPanels)+" estimable panels for the same displayed hypothesis.";
    std::vector<std::string> omittedTerms;const auto effectiveTerms=rlispstat::core::EffectiveModelTrellisTerms(state.specification,&omittedTerms);
    std::string formulaNote=omittedTerms.empty()?"":(" Conditioning variables are constant within panels and are omitted from the panel model formula. Effective formula: "+rlispstat::core::ModelTrellisFormulaText(state.specification.baseModel,&effectiveTerms)+".");
    std::string status = state.status + "  " + rlispstat::core::ModelTrellisCopyNote()+formulaNote+adjustmentNote;
    [ToNSString(status) drawInRect:NSMakeRect(margin,noteY+38,NSWidth([self bounds])-2*margin,42)
        withAttributes:ModelTrellisTextAttributes(10.5,NSFontWeightRegular,NSTextAlignmentLeft,[NSColor secondaryLabelColor])];
}

- (std::string)panelAtPoint:(NSPoint)point
{
    for (const auto &entry : _panelRects) if (NSPointInRect(point, entry.second)) return entry.first;
    return "";
}
- (void)mouseDown:(NSEvent *)event
{
    const std::string panel = [self panelAtPoint:[self convertPoint:[event locationInWindow] fromView:nil]];
    if (!panel.empty()) [_controller selectPanel:panel additive:(([event modifierFlags] & NSEventModifierFlagCommand) != 0)];
}
- (NSMenu *)menuForEvent:(NSEvent *)event
{
    return [_controller contextMenuForPanel:[self panelAtPoint:[self convertPoint:[event locationInWindow] fromView:nil]]];
}
@end


