@implementation ModelTrellisWindowController
- (instancetype)initWithModelTrellisId:(const std::string &)identifier
{
    if ((self = [super init])) {
        _modelTrellisId=identifier;
        _window=[[NSWindow alloc]initWithContentRect:NSMakeRect(120,100,980,700) styleMask:(NSWindowStyleMaskTitled|NSWindowStyleMaskClosable|NSWindowStyleMaskMiniaturizable|NSWindowStyleMaskResizable) backing:NSBackingStoreBuffered defer:NO];
        [_window setTitle:@"Linear Model Trellis"];[_window setMinSize:NSMakeSize(650,420)];[_window setDelegate:self];
        NSView *root=[_window contentView];NSRect bounds=[root bounds];
        _addPredictorButton=[[NSButton alloc]initWithFrame:NSMakeRect(12,NSHeight(bounds)-34,132,26)];[_addPredictorButton setTitle:@"+ Add predictor\u2026"];[_addPredictorButton setBezelStyle:NSBezelStyleRounded];[_addPredictorButton setTarget:self];[_addPredictorButton setAction:@selector(showAddPredictorMenu:)];[_addPredictorButton setAutoresizingMask:NSViewMaxXMargin|NSViewMinYMargin];[root addSubview:_addPredictorButton];
        _formulaField=GLMLabel(@"",NSMakeRect(158,NSHeight(bounds)-31,NSWidth(bounds)-172,20),11,NSFontWeightRegular);[_formulaField setTextColor:[NSColor secondaryLabelColor]];[_formulaField setLineBreakMode:NSLineBreakByTruncatingMiddle];[_formulaField setAutoresizingMask:NSViewWidthSizable|NSViewMinYMargin];[root addSubview:_formulaField];
        _scrollView=[[NSScrollView alloc]initWithFrame:NSMakeRect(0,0,NSWidth(bounds),NSHeight(bounds)-42)];[_scrollView setAutoresizingMask:NSViewWidthSizable|NSViewHeightSizable];[_scrollView setHasVerticalScroller:YES];[_scrollView setHasHorizontalScroller:YES];
        _contentView=[[ModelTrellisContentView alloc]initWithFrame:NSMakeRect(0,0,980,700)];[_contentView setController:self];[_contentView setModelTrellisId:identifier];[_scrollView setDocumentView:_contentView];[[_window contentView]addSubview:_scrollView];[self refresh];
    }return self;
}
- (void)show{EnableNotesForWindow(_window,_modelTrellisId,@"this Model Trellis");[_window makeKeyAndOrderFront:nil];[self refresh];}
- (void)refresh
{
    ModelTrellisState state;{std::lock_guard<std::mutex>lock(g_mutex);ModelTrellisState*p=FindModelTrellisUnlocked(_modelTrellisId);if(!p)return;state=*p;}
    std::string formula = rlispstat::core::ModelTrellisFormulaText(state.specification.baseModel);
    if (state.dataScopeCaptured) {
        formula += " · " + rlispstat::core::AnalysisScopeWindowSummary(
            state.dataScope, state.dataScope.totalDatasetRows);
    }
    [_formulaField setStringValue:ToNSString(formula)];
    DataFrameModel data;BOOL hasData=NO;{std::lock_guard<std::mutex>lock(g_mutex);const DataFrameModel*d=FindDataFrameUnlockedConst(state.specification.baseModel.group);if(d){data=*d;hasData=YES;}}
    [_addPredictorButton setEnabled:hasData&&!rlispstat::core::ModelTrellisIndependentVariables(data,state.specification).empty()];
    auto layout=rlispstat::core::BuildModelTrellisLayout(state);CGFloat ph=168;
    if(state.specification.panelContent==ModelTrellisPanelContent::Coefficients){size_t n=1;for(const auto&p:state.panels)n=std::max(n,p.coefficients.size());ph=82+21*n;}
    if(state.specification.panelContent==ModelTrellisPanelContent::TermTests){size_t n=1;for(const auto&p:state.panels)n=std::max(n,p.termTests.size());ph=82+21*n;}
    const CGFloat panelWidth=ModelTrellisPanelWidth(state);
    const CGFloat rowStripWidth=ModelTrellisRowStripWidth(state);
    [_contentView setFrame:NSMakeRect(0,0,std::max(640.0,36.0+layout.columns*panelWidth+rowStripWidth),std::max(390.0,185.0+layout.rows*ph))];[_contentView setNeedsDisplay:YES];
}
- (ModelTrellisPanelResult*)clickedPanel:(ModelTrellisState*)s{if(!s)return nullptr;for(auto&p:s->panels)if(p.panelId==_clickedPanelId)return&p;return nullptr;}
- (void)selectPanel:(const std::string&)panelId additive:(BOOL)additive
{
    std::string group;std::set<int>rows;int version=0;bool changed=false;{std::lock_guard<std::mutex>lock(g_mutex);ModelTrellisState*s=FindModelTrellisUnlocked(_modelTrellisId);if(!s)return;group=s->specification.baseModel.group;for(const auto&p:s->panels)if(p.panelId==panelId)rows.insert(p.originalRowIndices.begin(),p.originalRowIndices.end());if(additive){auto old=g_groupSelections.find(group);if(old!=g_groupSelections.end())rows.insert(old->second.begin(),old->second.end());}changed=SetGroupSelectionUnlocked(group,rows,&version);}if(changed)NotifyPortableSelectionChanged(group,rows,version,true);[self refresh];
}
- (void)selectClickedPanel:(id)sender{(void)sender;[self selectPanel:_clickedPanelId additive:NO];}
- (void)clearSelection:(id)sender{(void)sender;std::string group;int version=0;bool changed=false;{std::lock_guard<std::mutex>lock(g_mutex);ModelTrellisState*s=FindModelTrellisUnlocked(_modelTrellisId);if(!s)return;group=s->specification.baseModel.group;changed=SetGroupSelectionUnlocked(group,{},&version);}if(changed)NotifyPortableSelectionChanged(group,{},version,true);[self refresh];}
- (void)windowDidResize:(NSNotification*)n{(void)n;[_contentView setNeedsDisplay:YES];}
- (void)windowWillClose:(NSNotification*)n{(void)n;std::lock_guard<std::mutex>lock(g_mutex);g_modelTrellisControllers.erase(_modelTrellisId);g_modelTrellises.erase(_modelTrellisId);}
- (NSMenu*)contextMenuForPanel:(const std::string&)panelId{return [self buildContextMenuForPanel:panelId];}
@end

