@implementation ModelTrellisWindowController (Actions)
static void ModelTrellisSetSavePanelExtension(NSSavePanel *panel, NSString *extension)
{
    if (@available(macOS 11.0, *)) {
        UTType *type=[UTType typeWithFilenameExtension:extension];if(type)[panel setAllowedContentTypes:@[type]];
    } else {
#pragma clang diagnostic push
#pragma clang diagnostic ignored "-Wdeprecated-declarations"
        [panel setAllowedFileTypes:@[extension]];
#pragma clang diagnostic pop
    }
}
- (void)panelContentChanged:(id)sender
{ {std::lock_guard<std::mutex>lock(g_mutex);auto*s=FindModelTrellisUnlocked(_modelTrellisId);if(!s)return;s->specification.panelContent=(ModelTrellisPanelContent)[sender tag];}[self refresh]; }
- (void)displayedResultChanged:(id)sender
{
    std::string value=[(NSString*)[sender representedObject] UTF8String];{std::lock_guard<std::mutex>lock(g_mutex);auto*s=FindModelTrellisUnlocked(_modelTrellisId);if(!s)return;
      if(value.rfind("term|",0)==0){s->specification.displayedTermId=value.substr(5);s->specification.displayedCoefficientId.reset();}
      else if(value.rfind("coef|",0)==0){s->specification.displayedCoefficientId=value.substr(5);s->specification.displayedTermId.reset();}
      else{s->specification.displayedTermId.reset();s->specification.displayedCoefficientId.reset();}s->specification.panelContent=ModelTrellisPanelContent::SelectedResult;}[self refresh];
}
