    ModelTrellisState state;DataFrameModel data;BOOL found=NO;{std::lock_guard<std::mutex>lock(g_mutex);auto*s=FindModelTrellisUnlocked(_modelTrellisId);if(!s)return nil;state=*s;const DataFrameModel*d=FindDataFrameUnlockedConst(state.specification.baseModel.group);if(d){data=*d;found=YES;}}
    NSMenu*menu=[[NSMenu alloc]initWithTitle:@"Add predictor"];
    if(found)for(const auto&name:rlispstat::core::ModelTrellisIndependentVariables(data,state.specification)){NSMenuItem*item=[[NSMenuItem alloc]initWithTitle:ToNSString(name) action:@selector(addIndependentVariable:) keyEquivalent:@""];[item setTarget:self];[item setRepresentedObject:ToNSString(name)];[menu addItem:item];}
    if([menu numberOfItems]==0){NSMenuItem*none=[[NSMenuItem alloc]initWithTitle:@"No available predictors" action:nil keyEquivalent:@""];[none setEnabled:NO];[menu addItem:none];}
    return menu;
