    {std::lock_guard<std::mutex>lock(g_mutex);auto*s=FindModelTrellisUnlocked(_modelTrellisId);if(!s)return;const DataFrameModel*d=FindDataFrameUnlockedConst(s->specification.baseModel.group);if(!d)return;
