{const std::vector<CGFloat>w=ModelTrellisAPAColumnWidths(state);const CGFloat tableWidth=std::accumulate(w.begin(),w.end(),(CGFloat)0.0);if((self=[super initWithFrame:NSMakeRect(0,0,std::max((CGFloat)780.0,tableWidth+68.0),190+state.panels.size()*24)])){_state=state;_number=[number copy];_title=[title copy];}return self;}
