    [[NSString stringWithFormat:@"Table %@",_number.length?_number:@"1"]drawAtPoint:NSMakePoint(34,y)withAttributes:ModelTrellisTextAttributes(12,NSFontWeightBold)];y+=22;
    NSMutableDictionary*a=[ModelTrellisTextAttributes(12,NSFontWeightRegular)mutableCopy];a[NSFontAttributeName]=[[NSFontManager sharedFontManager]convertFont:[NSFont systemFontOfSize:12]toHaveTrait:NSItalicFontMask];[(_title.length?_title:@"Separate panel linear models")drawAtPoint:NSMakePoint(34,y)withAttributes:a];y+=28;
    NSArray*h=ModelTrellisAPAHeaders();const std::vector<CGFloat>w=ModelTrellisAPAColumnWidths(_state);const CGFloat tableRight=34.0+std::accumulate(w.begin(),w.end(),(CGFloat)0.0);
    [[NSColor blackColor]setStroke];NSBezierPath*r=[NSBezierPath bezierPath];[r moveToPoint:NSMakePoint(34,y)];[r lineToPoint:NSMakePoint(tableRight,y)];[r stroke];y+=4;CGFloat x=34;for(int c=0;c<11;c++){DrawModelTrellisCell(h[c],NSMakeRect(x,y,w[(std::size_t)c],20),c>1,YES);x+=w[(std::size_t)c];}y+=22;r=[NSBezierPath bezierPath];[r moveToPoint:NSMakePoint(34,y)];[r lineToPoint:NSMakePoint(tableRight,y)];[r stroke];y+=3;
    for(const auto&p:_state.panels){NSArray*v=ModelTrellisAPAValues(_state,p);x=34;for(int j=0;j<11;j++){DrawModelTrellisCell(v[j],NSMakeRect(x,y,w[(std::size_t)j],20),j>1);x+=w[(std::size_t)j];}y+=24;}
    r=[NSBezierPath bezierPath];[r moveToPoint:NSMakePoint(34,y)];[r lineToPoint:NSMakePoint(tableRight,y)];[r stroke];y+=10;NSString*note=ToNSString("Note. "+rlispstat::core::ModelTrellisMethodologicalNote()+" p_adj values use "+rlispstat::core::ModelTrellisPAdjustmentLabel(_state.specification.pAdjustment)+"'s method across estimable panels for the same result.");[note drawInRect:NSMakeRect(34,y,tableRight-34.0,48)withAttributes:ModelTrellisTextAttributes(10,NSFontWeightRegular)];
}
