@implementation ModelTrellisWindowController (Menu)
- (NSMenuItem*)root:(NSString*)title submenu:(NSMenu*)submenu{NSMenuItem*i=[[NSMenuItem alloc]initWithTitle:title action:nil keyEquivalent:@""];[i setSubmenu:submenu];return i;}
- (NSMenu*)buildContextMenuForPanel:(const std::string&)panelId
{
    _clickedPanelId=panelId;ModelTrellisState s;DataFrameModel data;BOOL hasData=NO;{std::lock_guard<std::mutex>lock(g_mutex);auto*p=FindModelTrellisUnlocked(_modelTrellisId);if(!p)return nil;s=*p;const auto*d=FindDataFrameUnlockedConst(s.specification.baseModel.group);if(d){data=*d;hasData=YES;}}
    NSMenu*m=[[NSMenu alloc]initWithTitle:@"Linear Model Trellis"];NSMenu*content=[[NSMenu alloc]initWithTitle:@"Panel content"];NSArray*ct=@[@"Compact summary",@"Selected result",@"Coefficients",@"Term tests",@"Model fit"];
    for(NSInteger i=0;i<5;i++){NSMenuItem*x=[[NSMenuItem alloc]initWithTitle:ct[i] action:@selector(panelContentChanged:) keyEquivalent:@""];[x setTarget:self];[x setTag:i];[x setState:(NSInteger)s.specification.panelContent==i?NSControlStateValueOn:NSControlStateValueOff];[content addItem:x];}[m addItem:[self root:@"Panel content" submenu:content]];
    NSMenu*terms=[[NSMenu alloc]initWithTitle:@"Model terms"];[terms addItem:[self root:@"Add predictor" submenu:[self addPredictorMenu]]];if(!s.specification.baseModel.terms.empty()){NSMenu*remove=[[NSMenu alloc]initWithTitle:@"Remove predictor"];for(const auto&term:s.specification.baseModel.terms){NSMenuItem*x=[[NSMenuItem alloc]initWithTitle:ToNSString(term) action:@selector(removeIndependentTerm:) keyEquivalent:@""];[x setTarget:self];[x setRepresentedObject:ToNSString(term)];[remove addItem:x];}[terms addItem:[self root:@"Remove predictor" submenu:remove]];}[m addItem:[self root:@"Model terms" submenu:terms]];
