static NSDictionary *MeanComparisonAttributes(CGFloat size, NSFontWeight weight,
                                               NSTextAlignment alignment, BOOL italic)
{
    NSFont *font = [NSFont systemFontOfSize:size weight:weight];
    if (italic) font = [[NSFontManager sharedFontManager] convertFont:font toHaveTrait:NSItalicFontMask];
    NSMutableParagraphStyle *style = [[NSMutableParagraphStyle alloc] init];
    [style setAlignment:alignment];
    return @{NSFontAttributeName: font,
             NSForegroundColorAttributeName: [NSColor colorWithCalibratedWhite:0.16 alpha:1.0],
             NSParagraphStyleAttributeName: style};
}

static BOOL MeanComparisonIsDescriptiveTable(const MeanComparisonTable &table)
{
    return table.tableId == "group_descriptives";
}

static CGFloat MeanComparisonVisiblePreferredHeight(const MeanComparisonState &state,
                                                     BOOL descriptivesOnly)
{
    CGFloat height = 112.0;
    for (const MeanComparisonTable &table : state.tables) {
        const BOOL descriptive = MeanComparisonIsDescriptiveTable(table);
        if ((descriptivesOnly && !descriptive) || (!descriptivesOnly && descriptive)) continue;
        height += (table.title.empty() ? 0.0 : 24.0) + 30.0 + 25.0 * table.rows.size();
        height += 18.0 * (table.notes.size() + table.warnings.size()) + 18.0;
    }
    return std::min<CGFloat>(820.0, std::max<CGFloat>(260.0, height));
}

static CGFloat MeanComparisonPageAdvance(CGFloat y, CGFloat need, CGFloat pageHeight)
{
    if (pageHeight <= 0.0) return y;
    const CGFloat pageTop = std::floor(y / pageHeight) * pageHeight;
    if (y + need <= pageTop + pageHeight - 8.0) return y;
    return pageTop + pageHeight + 8.0;
}

static CGFloat MeanComparisonTableHeaderHeight(const MeanComparisonTable &table)
{
    return (table.title.empty() ? 0.0 : 24.0) + 29.0;
}

struct MeanComparisonDrawWidths {
    CGFloat stub = 148.0;
    std::vector<CGFloat> columns;
};

static MeanComparisonDrawWidths MeanComparisonWidthsForDrawing(
    const MeanComparisonTable &table, CGFloat availableWidth)
{
    MeanComparisonDrawWidths result;
    result.stub = (CGFloat)rlispstat::core::MeanComparisonPreferredStubWidth(table);
    const std::vector<double> preferred = rlispstat::core::MeanComparisonPreferredColumnWidths(table);
    result.columns.assign(preferred.begin(), preferred.end());
    CGFloat natural = result.stub;
    size_t visible = 0;
    for (size_t c = 0; c < table.columns.size(); ++c) {
        if (!table.columns[c].visible) continue;
        natural += result.columns[c]; ++visible;
    }
    if (natural <= 0.0 || availableWidth <= 0.0) return result;
    if (availableWidth < natural) {
        // Shrink flexible label/scalar columns first.  A confidence interval is
        // already measured from its complete rendered text and must not become
        // the sacrificial column merely because a window or PDF page is narrow.
        std::vector<CGFloat> floors(result.columns.size(), 0.0);
        CGFloat shrinkable = std::max((CGFloat)0.0, result.stub - 92.0);
        for (size_t c = 0; c < table.columns.size(); ++c) {
            if (!table.columns[c].visible) continue;
            if (table.columns[c].format == MeanComparisonCellFormat::ConfidenceInterval) {
                floors[c] = result.columns[c];
            } else if (table.columns[c].format == MeanComparisonCellFormat::Text) {
                floors[c] = std::min(result.columns[c], (CGFloat)64.0);
            } else {
                floors[c] = std::min(result.columns[c], (CGFloat)46.0);
            }
            shrinkable += std::max((CGFloat)0.0, result.columns[c] - floors[c]);
        }
        const CGFloat shortage = natural - availableWidth;
        const CGFloat fraction = shrinkable > 0.0
            ? std::min((CGFloat)1.0, shortage / shrinkable) : 0.0;
        result.stub -= fraction * std::max((CGFloat)0.0, result.stub - 92.0);
        for (size_t c = 0; c < result.columns.size(); ++c) {
            result.columns[c] -= fraction *
                std::max((CGFloat)0.0, result.columns[c] - floors[c]);
        }
    } else if (visible > 0) {
        const CGFloat extra = (availableWidth - natural) / (CGFloat)visible;
        for (size_t c = 0; c < table.columns.size(); ++c) {
            if (table.columns[c].visible) result.columns[c] += extra;
        }
    }
    return result;
}

static CGFloat DrawMeanComparisonTableHeader(const MeanComparisonTable &table, CGFloat y,
                                             CGFloat width, CGFloat margin, BOOL apa,
                                             BOOL continuation)
{
    if (!table.title.empty()) {
        NSString *title = ToNSString(table.title);
        if (continuation) title = [title stringByAppendingString:@" (continued)"];
        [title drawInRect:NSMakeRect(margin, y, width - 2 * margin, 18)
           withAttributes:MeanComparisonAttributes(12, NSFontWeightSemibold, NSTextAlignmentLeft, NO)];
        y += 24.0;
    }
    const MeanComparisonDrawWidths widths = MeanComparisonWidthsForDrawing(table, width - 2 * margin);
    if (apa) {
        [[NSColor colorWithCalibratedWhite:0.25 alpha:1.0] setStroke];
        NSBezierPath *top = [NSBezierPath bezierPath];
        [top moveToPoint:NSMakePoint(margin, y - 3.0)];
        [top lineToPoint:NSMakePoint(width - margin, y - 3.0)];
        [top stroke];
    }
    [ToNSString(table.stubTitle) drawInRect:NSMakeRect(margin, y, widths.stub - 6.0, 19)
                             withAttributes:MeanComparisonAttributes(11, NSFontWeightSemibold, NSTextAlignmentLeft, NO)];
    CGFloat x = margin + widths.stub;
    for (size_t c = 0; c < table.columns.size(); ++c) {
        if (!table.columns[c].visible) continue;
        [ToNSString(table.columns[c].title) drawInRect:NSMakeRect(x, y, widths.columns[c] - 7.0, 19)
                                        withAttributes:MeanComparisonAttributes(11, NSFontWeightSemibold,
                                            table.columns[c].format == MeanComparisonCellFormat::Text ? NSTextAlignmentLeft : NSTextAlignmentRight,
                                            apa && (table.columns[c].title == "M" || table.columns[c].title == "SD" ||
                                                    table.columns[c].title == "SE" || table.columns[c].title == "t" ||
                                                    table.columns[c].title == "F" || table.columns[c].title == "p"))];
        x += widths.columns[c];
    }
    [[NSColor colorWithCalibratedWhite:0.80 alpha:1.0] setStroke];
    NSBezierPath *headerRule = [NSBezierPath bezierPath];
    [headerRule moveToPoint:NSMakePoint(margin, y + 23.0)];
    [headerRule lineToPoint:NSMakePoint(width - margin, y + 23.0)];
    [headerRule stroke];
    return y + 29.0;
}

@implementation MeanComparisonReportView

- (NSString *)snapshotTabDelimitedText
{
    MeanComparisonState *state = [_controller state];
    return state ? ToNSString(SnapshotCSVToTabDelimited(
        rlispstat::core::MeanComparisonAllTablesCSV(*state))) : @"";
}

- (instancetype)initWithController:(MeanComparisonWindowController *)controller
{
    self = [super initWithFrame:NSMakeRect(0, 0, 800, 320)];
    if (!self) return nil;
    _controller = controller;
    _includeDescriptives = YES;
    _onlyTable = -1;
    [self setWantsLayer:YES];
    return self;
}

- (BOOL)isFlipped { return YES; }

- (void)configureExportAPA:(BOOL)apa displayed:(BOOL)displayed number:(NSString *)number
                     title:(NSString *)title includeDescriptives:(BOOL)includeDescriptives
                 onlyTable:(NSInteger)onlyTable
{
    _exportAPA = apa;
    _exportDisplayed = displayed;
    _tableNumber = number;
    _exportTitle = title;
    _includeDescriptives = includeDescriptives;
    _onlyTable = onlyTable;
}

- (void)configurePrintPageHeight:(CGFloat)pageHeight
{
    _printPageHeight = std::max<CGFloat>(0.0, pageHeight);
}

- (BOOL)tableIncludedAtIndex:(NSInteger)index
{
    MeanComparisonState *state = [_controller state];
    if (index < 0 || (size_t)index >= state->tables.size()) return NO;
    if (_onlyTable >= 0 && index != _onlyTable) return NO;
    const BOOL descriptive = MeanComparisonIsDescriptiveTable(state->tables[(size_t)index]);
    if ([_controller descriptivesOnly]) return descriptive;
    if (descriptive) {
        if (_exportAPA) return _includeDescriptives;
        return [_controller descriptivesVisible];
    }
    return YES;
}

- (CGFloat)preferredHeight
{
    MeanComparisonState *state = [_controller state];
    CGFloat height = (_exportAPA ? 68.0 : (_exportDisplayed ? 54.0 : 8.0));
    for (NSInteger t = 0; t < (NSInteger)state->tables.size(); ++t) {
        if (![self tableIncludedAtIndex:t]) continue;
        const MeanComparisonTable &table = state->tables[(size_t)t];
        const CGFloat headerHeight = MeanComparisonTableHeaderHeight(table);
        height = MeanComparisonPageAdvance(height, headerHeight + (table.rows.empty() ? 0.0 : 24.0), _printPageHeight);
        height += headerHeight;
        for (size_t r = 0; r < table.rows.size(); ++r) {
            const CGFloat advanced = MeanComparisonPageAdvance(height, 24.0, _printPageHeight);
            if (advanced != height) height = advanced + headerHeight;
            height += 24.0;
        }
        height += 8.0;
        for (size_t n = 0; n < table.notes.size() + table.warnings.size(); ++n) {
            height = MeanComparisonPageAdvance(height, 18.0, _printPageHeight) + 18.0;
        }
        height += 10.0;
    }
    return std::max<CGFloat>(140.0, height);
}

- (BOOL)knowsPageRange:(NSRangePointer)range
{
    if (_printPageHeight <= 0.0) return [super knowsPageRange:range];
    range->location = 1;
    range->length = (NSUInteger)std::max<CGFloat>(1.0, std::ceil(NSHeight([self bounds]) / _printPageHeight));
    return YES;
}

- (NSRect)rectForPage:(NSInteger)page
{
    if (_printPageHeight <= 0.0) return [super rectForPage:page];
    return NSMakeRect(0.0, (page - 1) * _printPageHeight, NSWidth([self bounds]), _printPageHeight);
}

- (BOOL)hitAtPoint:(NSPoint)point table:(NSInteger *)tableIndex row:(NSInteger *)rowIndex
{
    MeanComparisonState *state = [_controller state];
    CGFloat y = (_exportAPA ? 68.0 : (_exportDisplayed ? 54.0 : 8.0));
    for (NSInteger t = 0; t < (NSInteger)state->tables.size(); ++t) {
        if (![self tableIncludedAtIndex:t]) continue;
        const MeanComparisonTable &table = state->tables[(size_t)t];
        if (!table.title.empty()) y += 24.0;
        y += 29.0;
        for (NSInteger r = 0; r < (NSInteger)table.rows.size(); ++r) {
            if (point.y >= y && point.y < y + 24.0) {
                if (tableIndex) *tableIndex = t;
                if (rowIndex) *rowIndex = r;
                return YES;
            }
            y += 24.0;
        }
        y += 12.0 + 18.0 * (table.notes.size() + table.warnings.size());
    }
    return NO;
}

- (void)drawRect:(NSRect)dirtyRect
{
    (void)dirtyRect;
    [[NSColor whiteColor] setFill];
    NSRectFill([self bounds]);
    MeanComparisonState *state = [_controller state];
    const CGFloat width = NSWidth([self bounds]);
    const CGFloat margin = 14.0;
    CGFloat y = 8.0;
    if ([_controller refitPending] && !_exportAPA && !_exportDisplayed) {
        [@"Calculating in R…" drawInRect:NSMakeRect(margin, y + 18.0, width - 2 * margin, 22)
                           withAttributes:MeanComparisonAttributes(12, NSFontWeightRegular, NSTextAlignmentLeft, NO)];
        return;
    }
    if (_exportAPA) {
        NSString *number = [_tableNumber length] ? [@"Table " stringByAppendingString:_tableNumber] : @"Table 1";
        [number drawInRect:NSMakeRect(margin, y, width - 2 * margin, 18)
           withAttributes:MeanComparisonAttributes(12, NSFontWeightBold, NSTextAlignmentLeft, NO)];
        y += 22.0;
        [(_exportTitle ?: ToNSString(state->title)) drawInRect:NSMakeRect(margin, y, width - 2 * margin, 22)
                                               withAttributes:MeanComparisonAttributes(13, NSFontWeightRegular, NSTextAlignmentLeft, YES)];
        y += 34.0;
    } else if (_exportDisplayed) {
        [ToNSString(state->title) drawInRect:NSMakeRect(margin, y, width - 2 * margin, 22)
                              withAttributes:MeanComparisonAttributes(15, NSFontWeightSemibold, NSTextAlignmentLeft, NO)];
        y += 24.0;
        [ToNSString(state->subtitle) drawInRect:NSMakeRect(margin, y, width - 2 * margin, 18)
                                 withAttributes:MeanComparisonAttributes(11, NSFontWeightRegular, NSTextAlignmentLeft, NO)];
        y += 30.0;
    }

    for (NSInteger t = 0; t < (NSInteger)state->tables.size(); ++t) {
        if (![self tableIncludedAtIndex:t]) continue;
        const MeanComparisonTable &table = state->tables[(size_t)t];
        const CGFloat headerHeight = MeanComparisonTableHeaderHeight(table);
        y = MeanComparisonPageAdvance(y, headerHeight + (table.rows.empty() ? 0.0 : 24.0), _printPageHeight);
        y = DrawMeanComparisonTableHeader(table, y, width, margin, _exportAPA, NO);
        const MeanComparisonDrawWidths widths = MeanComparisonWidthsForDrawing(table, width - 2 * margin);
        for (NSInteger r = 0; r < (NSInteger)table.rows.size(); ++r) {
            const CGFloat advanced = MeanComparisonPageAdvance(y, 24.0, _printPageHeight);
            if (advanced != y) y = DrawMeanComparisonTableHeader(table, advanced, width, margin, _exportAPA, YES);
            if (!_exportAPA && !_exportDisplayed && [_controller selectedTable] == t && [_controller selectedRow] == r) {
                [[NSColor colorWithCalibratedWhite:0.91 alpha:1.0] setFill];
                NSRectFill(NSMakeRect(margin - 3.0, y - 2.0, width - 2 * margin + 6.0, 23.0));
            }
            const MeanComparisonRow &row = table.rows[(size_t)r];
            [ToNSString(row.label) drawInRect:NSMakeRect(margin, y, widths.stub - 6.0, 18)
                               withAttributes:MeanComparisonAttributes(11, NSFontWeightRegular, NSTextAlignmentLeft, NO)];
            CGFloat x = margin + widths.stub;
            for (size_t c = 0; c < table.columns.size(); ++c) {
                if (!table.columns[c].visible) continue;
                const std::string value = c < row.cells.size()
                    ? rlispstat::core::MeanComparisonCellText(row.cells[c], table.columns[c].format) : "";
                [ToNSString(value) drawInRect:NSMakeRect(x, y, widths.columns[c] - 7.0, 18)
                               withAttributes:MeanComparisonAttributes(11, NSFontWeightRegular,
                                   table.columns[c].format == MeanComparisonCellFormat::Text ? NSTextAlignmentLeft : NSTextAlignmentRight, NO)];
                x += widths.columns[c];
            }
            y += 24.0;
        }
        if (_exportAPA) {
            [[NSColor colorWithCalibratedWhite:0.25 alpha:1.0] setStroke];
            NSBezierPath *bottom = [NSBezierPath bezierPath];
            [bottom moveToPoint:NSMakePoint(margin, y - 4.0)]; [bottom lineToPoint:NSMakePoint(width - margin, y - 4.0)]; [bottom stroke];
        }
        y += 8.0;
        for (const std::string &note : table.notes) {
            y = MeanComparisonPageAdvance(y, 18.0, _printPageHeight);
            NSString *text = _exportAPA ? [@"Note. " stringByAppendingString:ToNSString(note)] : ToNSString(note);
            [text drawInRect:NSMakeRect(margin, y, width - 2 * margin, 17)
              withAttributes:MeanComparisonAttributes(10, NSFontWeightRegular, NSTextAlignmentLeft, _exportAPA)];
            y += 18.0;
        }
        for (const std::string &warning : table.warnings) {
            y = MeanComparisonPageAdvance(y, 18.0, _printPageHeight);
            [ToNSString(warning) drawInRect:NSMakeRect(margin, y, width - 2 * margin, 17)
                              withAttributes:MeanComparisonAttributes(10, NSFontWeightRegular, NSTextAlignmentLeft, NO)];
            y += 18.0;
        }
        y += 10.0;
    }
}

- (void)mouseDown:(NSEvent *)event
{
    NSPoint point = [self convertPoint:[event locationInWindow] fromView:nil];
    NSInteger table = -1, row = -1;
    if ([self hitAtPoint:point table:&table row:&row]) [_controller setSelectedTable:table row:row activate:YES];
    [self setNeedsDisplay:YES];
}

- (void)keyDown:(NSEvent *)event
{
    MeanComparisonState *state = [_controller state];
    NSString *characters = [event charactersIgnoringModifiers];
    const unichar key = [characters length] ? [characters characterAtIndex:0] : 0;
    const BOOL moveDown = key == NSDownArrowFunctionKey;
    const BOOL moveUp = key == NSUpArrowFunctionKey;
    if (!moveDown && !moveUp) {
        if ([characters isEqualToString:@"\r"] || [characters isEqualToString:@" "]) {
            [_controller setSelectedTable:[_controller selectedTable] row:[_controller selectedRow] activate:YES];
            return;
        }
        [super keyDown:event];
        return;
    }
    NSInteger table = [_controller selectedTable];
    NSInteger row = [_controller selectedRow];
    if (table < 0 || row < 0) {
        for (NSInteger t = 0; t < (NSInteger)state->tables.size(); ++t) {
            if ([self tableIncludedAtIndex:t] && !state->tables[(size_t)t].rows.empty()) {
                table = t; row = 0; break;
            }
        }
    } else if (moveDown) {
        if ((size_t)(row + 1) < state->tables[(size_t)table].rows.size()) {
            ++row;
        } else {
            for (NSInteger t = table + 1; t < (NSInteger)state->tables.size(); ++t) {
                if ([self tableIncludedAtIndex:t] && !state->tables[(size_t)t].rows.empty()) {
                    table = t; row = 0; break;
                }
            }
        }
    } else if (row > 0) {
        --row;
    } else {
        for (NSInteger t = table - 1; t >= 0; --t) {
            if ([self tableIncludedAtIndex:t] && !state->tables[(size_t)t].rows.empty()) {
                table = t; row = (NSInteger)state->tables[(size_t)t].rows.size() - 1; break;
            }
        }
    }
    [_controller setSelectedTable:table row:row activate:NO];
    [self setNeedsDisplay:YES];
}

- (NSMenu *)menuForEvent:(NSEvent *)event
{
    NSPoint point = [self convertPoint:[event locationInWindow] fromView:nil];
    NSInteger table = -1, row = -1;
    [self hitAtPoint:point table:&table row:&row];
    [_controller setSelectedTable:table row:row activate:NO];
    [self setNeedsDisplay:YES];
    return [_controller contextMenuForTable:table row:row];
}
@end

static std::vector<std::string> MeanComparisonNumericVariables(const DataFrameModel &dataframe)
{
    std::vector<std::string> names;
    for (const DataColumn &column : dataframe.columns) {
        if ((column.type == "numeric" || column.type == "ordinal") &&
            !DataColumnLooksLikeId(column)) names.push_back(column.name);
    }
    return names;
}

static bool MeanComparisonHasOrdinalResponse(const MeanComparisonState &state,
                                             const DataFrameModel &dataframe)
{
    auto ordinal = [&](const std::string &name) {
        const DataColumn *column = FindDataColumnInDataFrame(dataframe, name);
        return column && column->type == "ordinal";
    };
    if (state.analysisType == "paired_samples_t_test") {
        for (const PairedVariableSpecification &pair : state.specification.pairs) {
            if (ordinal(pair.firstVariableId) || ordinal(pair.secondVariableId)) return true;
        }
        return false;
    }
    for (const std::string &variable : state.specification.dependentVariableIds) {
        if (ordinal(variable)) return true;
    }
    return false;
}

static std::vector<std::string> MeanComparisonEffectiveLevels(const DataColumn &column)
{
    std::vector<std::string> levels;
    for (const std::string &raw : column.values) {
        if (raw.empty() || raw == "NA" || raw == "NaN") continue;
        if (std::find(levels.begin(), levels.end(), raw) == levels.end()) levels.push_back(raw);
    }
    rlispstat::core::SortFactorLevelsLikeR(levels);
    return levels;
}

static bool MeanComparisonGroupingCandidate(const DataColumn &column, bool independent)
{
    if (DataColumnLooksLikeId(column)) return false;
    const std::vector<std::string> levels = MeanComparisonEffectiveLevels(column);
    if (independent) return levels.size() == 2;
    if (levels.size() < 2) return false;
    if (column.type != "numeric") return true;
    return levels.size() <= std::max<std::size_t>(12, (std::size_t)std::ceil(std::sqrt((double)column.values.size())));
}

static std::string MeanComparisonTaskType(const MeanComparisonState &state)
{
    if (state.analysisType == "one_sample_t_test") return "one_sample_t";
    if (state.analysisType == "independent_samples_t_test") return "independent_t";
    if (state.analysisType == "paired_samples_t_test") return "paired_t";
    return "oneway_anova";
}

static MainRCompareMeansTask MeanComparisonTaskForState(const MeanComparisonState &state)
{
    MainRCompareMeansTask task;
    task.id = state.id; task.group = state.datasetId; task.testType = MeanComparisonTaskType(state);
    task.responses = state.specification.dependentVariableIds;
    for (const PairedVariableSpecification &pair : state.specification.pairs) {
        task.pairs.push_back({pair.firstVariableId, pair.secondVariableId});
    }
    task.groupVar = state.specification.groupingVariableId.value_or("");
    task.testValue = state.specification.testValue;
    task.alternative = state.specification.alternative == rlispstat::core::AlternativeHypothesis::Greater ? "greater" :
        (state.specification.alternative == rlispstat::core::AlternativeHypothesis::Less ? "less" : "two.sided");
    task.confidenceLevel = state.specification.confidenceLevel;
    switch (state.specification.method) {
        case rlispstat::core::MeanComparisonMethod::OneSampleT:
        case rlispstat::core::MeanComparisonMethod::StudentT: task.method = "student"; break;
        case rlispstat::core::MeanComparisonMethod::WilcoxonSignedRank: task.method = "wilcoxon"; break;
        case rlispstat::core::MeanComparisonMethod::MannWhitney: task.method = "mann_whitney"; break;
        case rlispstat::core::MeanComparisonMethod::ClassicalAnova: task.method = "classical"; break;
        case rlispstat::core::MeanComparisonMethod::KruskalWallis: task.method = "kruskal_wallis"; break;
        default: task.method = "welch"; break;
    }
    task.pAdjustment = state.specification.pAdjustment == rlispstat::core::MultipleTestingAdjustment::Bonferroni ? "bonferroni" :
        (state.specification.pAdjustment == rlispstat::core::MultipleTestingAdjustment::None ? "none" : "holm");
    task.groupOrder = state.specification.groupOrderIds;
    task.scope = ScopeForCapturedAnalysisScope(state.dataScope, state.dataScopeCaptured, "all");
    task.rows = RowsForCapturedAnalysisScope(state.dataScope, state.dataScopeCaptured);
    return task;
}

static bool MeanComparisonUsesGroupingVariable(const MeanComparisonState &state)
{
    return state.analysisType == "independent_samples_t_test" ||
        state.analysisType == "one_way_anova";
}

static std::string MeanComparisonVisibleSubtitle(const MeanComparisonState &state,
                                                  bool descriptivesOnly)
{
    std::string subtitle = !descriptivesOnly && MeanComparisonUsesGroupingVariable(state)
        ? rlispstat::core::MeanComparisonSubtitleWithoutGroupingVariable(
              state.subtitle, state.groupVariable)
        : state.subtitle;
    if (state.dataScopeCaptured) {
        subtitle += (subtitle.empty() ? "" : " · ") +
            rlispstat::core::AnalysisScopeWindowSummary(
                state.dataScope, state.dataScope.totalDatasetRows);
    }
    return subtitle;
}

@implementation MeanComparisonWindowController

- (instancetype)initWithState:(const MeanComparisonState &)state
{
    return [self initWithState:state descriptivesOnly:NO];
}

- (instancetype)initWithState:(const MeanComparisonState &)state descriptivesOnly:(BOOL)descriptivesOnly
{
    self = [super init];
    if (!self) return nil;
    _state = state;
    _descriptivesOnly = descriptivesOnly;
    _showDescriptives = descriptivesOnly;
    _sizedForResults = !state.tables.empty();
    _selectedTable = -1; _selectedRow = -1;
    const CGFloat width = (CGFloat)rlispstat::core::MeanComparisonPreferredWidth(state);
    const BOOL inlineGroupingVariable = !descriptivesOnly && MeanComparisonUsesGroupingVariable(state);
    const CGFloat height = MeanComparisonVisiblePreferredHeight(state, descriptivesOnly) +
        (inlineGroupingVariable ? 32.0 : 0.0);
    _window = [[NSWindow alloc] initWithContentRect:NSMakeRect(0, 0, width, height)
                                          styleMask:(NSWindowStyleMaskTitled | NSWindowStyleMaskClosable |
                                                     NSWindowStyleMaskMiniaturizable | NSWindowStyleMaskResizable)
                                            backing:NSBackingStoreBuffered defer:NO];
    [_window setTitle:descriptivesOnly ? [@"Descriptives — " stringByAppendingString:ToNSString(state.title)] : ToNSString(state.title)];
    [_window setDelegate:self];
    [_window setMinSize:NSMakeSize(560, 260)];
    NSView *content = [_window contentView];
    NSTextField *title = GLMLabel(descriptivesOnly ? [@"Descriptives — " stringByAppendingString:ToNSString(state.title)] : ToNSString(state.title), NSMakeRect(14, height - 40, width - 150, 24), 16, NSFontWeightSemibold);
    [title setAutoresizingMask:NSViewWidthSizable | NSViewMinYMargin];
    NSTextField *dataset = GLMRightLabel(ToNSString(state.datasetId), NSMakeRect(width - 150, height - 38, 136, 20), 11, NSFontWeightRegular);
    [dataset setAutoresizingMask:NSViewMinXMargin | NSViewMinYMargin];
    _subtitleField = GLMLabel(ToNSString(MeanComparisonVisibleSubtitle(state, descriptivesOnly)), NSMakeRect(14, height - 64, width - 28, 19), 11, NSFontWeightRegular);
    [_subtitleField setTextColor:[NSColor colorWithCalibratedWhite:0.42 alpha:1.0]];
    [_subtitleField setAutoresizingMask:NSViewWidthSizable | NSViewMinYMargin];
    [content addSubview:title]; [content addSubview:dataset]; [content addSubview:_subtitleField];
    const BOOL inlineTestValue = !descriptivesOnly && state.analysisType == "one_sample_t_test";
    const CGFloat headerSpace = inlineGroupingVariable ? 132.0 : (inlineTestValue ? 126.0 : 100.0);
    if (inlineGroupingVariable) {
        _groupVariableLabel = GLMLabel(@"Grouping variable", NSMakeRect(14, height - 93, 112, 20), 11, NSFontWeightSemibold);
        [_groupVariableLabel setAutoresizingMask:NSViewMinYMargin];
        [content addSubview:_groupVariableLabel];
        _groupVariablePopup = [[NSPopUpButton alloc] initWithFrame:NSMakeRect(126, height - 97, 190, 27) pullsDown:NO];
        [_groupVariablePopup setTarget:self];
        [_groupVariablePopup setAction:@selector(setGroupingVariable:)];
        [_groupVariablePopup setAutoresizingMask:NSViewMinYMargin];
        [content addSubview:_groupVariablePopup];
        [self refreshGroupingVariableControl];
    }
    if (inlineTestValue) {
        NSTextField *label = GLMLabel(@"Test value", NSMakeRect(14, height - 91, 72, 20), 11, NSFontWeightRegular);
        [label setAutoresizingMask:NSViewMinYMargin]; [content addSubview:label];
        _testValueField = [[NSTextField alloc] initWithFrame:NSMakeRect(86, height - 94, 112, 24)];
        [_testValueField setStringValue:ToNSString(rlispstat::core::FormatModelNumberOrDash(state.testValue))];
        [_testValueField setDelegate:self]; [_testValueField setTarget:self]; [_testValueField setAction:@selector(commitTestValue:)];
        [_testValueField setAutoresizingMask:NSViewMinYMargin]; [content addSubview:_testValueField];
    }
    _scrollView = [[NSScrollView alloc] initWithFrame:NSMakeRect(0, 30, width, height - headerSpace)];
    [_scrollView setHasVerticalScroller:YES]; [_scrollView setHasHorizontalScroller:YES];
    [_scrollView setAutohidesScrollers:YES];
    [_scrollView setBorderType:NSNoBorder]; [_scrollView setAutoresizingMask:NSViewWidthSizable | NSViewHeightSizable];
    _reportView = [[MeanComparisonReportView alloc] initWithController:self];
    const CGFloat docWidth = std::max<CGFloat>(width, (CGFloat)rlispstat::core::MeanComparisonPreferredWidth(state));
    [_reportView setFrame:NSMakeRect(0, 0, docWidth, [_reportView preferredHeight])];
    // The document keeps its content-derived width; the scroll view, not the
    // table columns, adapts when the window is narrowed.
    [_reportView setAutoresizingMask:NSViewHeightSizable];
    [_scrollView setDocumentView:_reportView]; [content addSubview:_scrollView];
    [_window setInitialFirstResponder:_reportView];
    NSString *status = descriptivesOnly ? @"Right-click for export options." :
        (inlineGroupingVariable ? @"Change the grouping variable above, or right-click a row for more options." :
                                  @"Right-click a row to edit the analysis or export results.");
    _statusField = GLMLabel(status, NSMakeRect(14, 6, width - 28, 18), 10, NSFontWeightRegular);
    [_statusField setTextColor:[NSColor colorWithCalibratedWhite:0.42 alpha:1.0]];
    [_statusField setAutoresizingMask:NSViewWidthSizable | NSViewMaxYMargin]; [content addSubview:_statusField];
    [_window center];
    return self;
}

- (MeanComparisonState *)state { return &_state; }
- (NSInteger)selectedTable { return _selectedTable; }
- (NSInteger)selectedRow { return _selectedRow; }
- (BOOL)descriptivesVisible { return _showDescriptives; }
- (BOOL)descriptivesOnly { return _descriptivesOnly; }
- (BOOL)refitPending { return _refitPending; }

- (void)refreshGroupingVariableControl
{
    if (!_groupVariablePopup) return;
    [_groupVariablePopup removeAllItems];
    DataFrameModel dataframe = [self dataframeSnapshot];
    const bool independent = _state.analysisType == "independent_samples_t_test";
    bool currentAdded = false;
    for (const DataColumn &column : dataframe.columns) {
        if (!MeanComparisonGroupingCandidate(column, independent)) continue;
        if (std::find(_state.specification.dependentVariableIds.begin(),
                      _state.specification.dependentVariableIds.end(), column.name) !=
            _state.specification.dependentVariableIds.end()) continue;
        [_groupVariablePopup addItemWithTitle:ToNSString(column.name)];
        if (column.name == _state.groupVariable) currentAdded = true;
    }
    if (!currentAdded && !_state.groupVariable.empty()) {
        [_groupVariablePopup insertItemWithTitle:ToNSString(_state.groupVariable) atIndex:0];
    }
    if ([[_groupVariablePopup itemArray] count] == 0) {
        [_groupVariablePopup addItemWithTitle:@"No available grouping variables"];
        [_groupVariablePopup setEnabled:NO];
        return;
    }
    [_groupVariablePopup selectItemWithTitle:ToNSString(_state.groupVariable)];
    [_groupVariablePopup setEnabled:!_refitPending];
}

- (void)updateState:(const MeanComparisonState &)state
{
    const BOOL shouldFitWindow = !_sizedForResults && !state.tables.empty();
    const NSPoint scrollOrigin = [[_scrollView contentView] bounds].origin;
    if (_selectedTable >= 0 && (size_t)_selectedTable < _state.tables.size()) {
        _selectedTableId = _state.tables[(size_t)_selectedTable].tableId;
        if (_selectedRow >= 0 && (size_t)_selectedRow < _state.tables[(size_t)_selectedTable].rows.size()) {
            _selectedRowId = _state.tables[(size_t)_selectedTable].rows[(size_t)_selectedRow].rowId;
        }
    }
    const rlispstat::core::AnalysisScope capturedScope = _state.dataScope;
    const bool hadCapturedScope = _state.dataScopeCaptured;
    _state = state;
    if (!_state.dataScopeCaptured && hadCapturedScope) {
        _state.dataScope = capturedScope;
        _state.dataScopeCaptured = true;
    }
    _refitPending = NO; _selectedTable = -1; _selectedRow = -1;
    if (shouldFitWindow) {
        const CGFloat desiredWidth = (CGFloat)rlispstat::core::MeanComparisonPreferredWidth(_state);
        const CGFloat desiredHeight = MeanComparisonVisiblePreferredHeight(_state, _descriptivesOnly) +
            ((!_descriptivesOnly && MeanComparisonUsesGroupingVariable(_state)) ? 32.0 : 0.0);
        [_window setContentSize:NSMakeSize(desiredWidth, desiredHeight)];
        _sizedForResults = YES;
    }
    for (size_t t = 0; t < _state.tables.size(); ++t) {
        if (_state.tables[t].tableId != _selectedTableId) continue;
        _selectedTable = (NSInteger)t;
        for (size_t r = 0; r < _state.tables[t].rows.size(); ++r) {
            if (_state.tables[t].rows[r].rowId == _selectedRowId) { _selectedRow = (NSInteger)r; break; }
        }
        break;
    }
    [_subtitleField setStringValue:ToNSString(MeanComparisonVisibleSubtitle(_state, _descriptivesOnly))];
    [self refreshGroupingVariableControl];
    if (_testValueField && ![_testValueField currentEditor]) {
        [_testValueField setStringValue:ToNSString(rlispstat::core::FormatModelNumberOrDash(_state.testValue))];
    }
    const CGFloat docWidth = std::max<CGFloat>(NSWidth([_scrollView contentView].bounds),
        (CGFloat)rlispstat::core::MeanComparisonPreferredWidth(_state));
    [_reportView setFrame:NSMakeRect(0, 0, docWidth, [_reportView preferredHeight])];
    [[_scrollView contentView] scrollToPoint:scrollOrigin]; [_scrollView reflectScrolledClipView:[_scrollView contentView]];
    [_reportView setNeedsDisplay:YES]; [_statusField setStringValue:@"Results updated."];
    if (_descriptivesController) [_descriptivesController updateState:_state];
}

- (void)showInlineError:(NSString *)message
{
    _refitPending = NO; [_statusField setStringValue:message ?: @"The analysis could not be recalculated."];
    [self refreshGroupingVariableControl];
    [_reportView setNeedsDisplay:YES];
}

- (void)queueRefit
{
    MainRCompareMeansTask task = MeanComparisonTaskForState(_state);
    _refitPending = YES; [_statusField setStringValue:@"Calculating in R…"];
    [_groupVariablePopup setEnabled:NO];
    [_reportView setNeedsDisplay:YES];
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        g_pendingCompareMeansTasks.push_back(std::move(task));
    }
    NotifyMainRTaskAvailable();
}

- (void)setSelectedTable:(NSInteger)table row:(NSInteger)row activate:(BOOL)activate
{
    _selectedTable = table; _selectedRow = row;
    if (!activate || table < 0 || row < 0 || (size_t)table >= _state.tables.size() ||
        (size_t)row >= _state.tables[(size_t)table].rows.size()) return;
    const MeanComparisonRow &selected = _state.tables[(size_t)table].rows[(size_t)row];
    const std::vector<int> linkedRows = rlispstat::core::MeanComparisonLinkedRows(selected);
    if (linkedRows.empty() || _state.datasetId.empty()) return;
    std::set<int> rows(linkedRows.begin(), linkedRows.end());
    int version = 0; bool changed = false;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        changed = SetGroupSelectionUnlocked(_state.datasetId, rows, &version);
    }
    if (changed) PublishSpreadPlotMessage("ROW_SELECTION_CHANGED", _state.datasetId, "compare-means", "",
                                          linkedRows, version);
}

- (const MeanComparisonTable *)currentTable
{
    return _selectedTable >= 0 && (size_t)_selectedTable < _state.tables.size()
        ? &_state.tables[(size_t)_selectedTable] : nullptr;
}

- (const MeanComparisonRow *)currentRow
{
    const MeanComparisonTable *table = [self currentTable];
    return table && _selectedRow >= 0 && (size_t)_selectedRow < table->rows.size()
        ? &table->rows[(size_t)_selectedRow] : nullptr;
}

- (void)copySelected:(id)sender
{
    (void)sender; const MeanComparisonTable *table = [self currentTable];
    if (!table || _selectedRow < 0) return;
    NSPasteboard *pasteboard = [NSPasteboard generalPasteboard]; [pasteboard clearContents];
    [pasteboard setString:ToNSString(rlispstat::core::MeanComparisonTableText(*table, true, (size_t)_selectedRow)) forType:NSPasteboardTypeString];
}

- (void)copyTable:(id)sender
{
    (void)sender; const MeanComparisonTable *table = [self currentTable]; if (!table) return;
    NSPasteboard *pasteboard = [NSPasteboard generalPasteboard]; [pasteboard clearContents];
    [pasteboard setString:ToNSString(rlispstat::core::MeanComparisonTableText(*table)) forType:NSPasteboardTypeString];
}

- (void)saveText:(const std::string &)text name:(NSString *)name title:(NSString *)title
{
    NSSavePanel *panel = [NSSavePanel savePanel]; [panel setNameFieldStringValue:name]; [panel setTitle:title];
    if ([panel runModal] == NSModalResponseOK) {
        NSError *error = nil; BOOL ok = [ToNSString(text) writeToURL:[panel URL] atomically:YES encoding:NSUTF8StringEncoding error:&error];
        [_statusField setStringValue:ok ? @"Export completed." : @"The file could not be written."];
    }
}

- (void)exportCSV:(id)sender
{
    BOOL all = [[[sender representedObject] description] isEqualToString:@"all"];
    const MeanComparisonTable *table = [self currentTable];
    if (!all && !table) return;
    std::string csv = all ? rlispstat::core::MeanComparisonAllTablesCSV(_state) : rlispstat::core::MeanComparisonTableCSV(*table);
    if (_state.dataScopeCaptured) {
        auto csvCell = [](std::string value) {
            std::size_t position = 0;
            while ((position = value.find('"', position)) != std::string::npos) {
                value.insert(position, 1, '"');
                position += 2;
            }
            return "\"" + value + "\"";
        };
        const std::size_t scopeN = rlispstat::core::AnalysisScopeRowCount(
            _state.dataScope, _state.dataScope.totalDatasetRows);
        std::ostringstream metadata;
        metadata << "Scope_Kind," << csvCell(rlispstat::core::AnalysisScopeKindId(_state.dataScope.kind)) << "\n"
                 << "Scope_Description," << csvCell(_state.dataScope.sourceDescription) << "\n"
                 << "Scope_N," << scopeN << "\n"
                 << "Dataset_N," << _state.dataScope.totalDatasetRows << "\n\n";
        csv = metadata.str() + csv;
    }
    NSString *suffix = all ? @"_all.csv" : @".csv";
    [self saveText:csv name:[ToNSString(_state.id) stringByAppendingString:suffix] title:@"Export CSV"];
}

- (void)writePDFAPA:(BOOL)apa all:(BOOL)all
{
    NSString *number = @""; NSString *title = ToNSString(_state.title); NSString *orientation = @"Automatic"; BOOL includeDesc = YES;
    if (apa) {
        NSAlert *alert = [[NSAlert alloc] init]; [alert setMessageText:@"PDF — APA 7 style"];
        [alert setInformativeText:@"Choose the table label and page layout."]; [alert addButtonWithTitle:@"Continue"]; [alert addButtonWithTitle:@"Cancel"];
        NSView *accessory = [[NSView alloc] initWithFrame:NSMakeRect(0, 0, 430, 142)];
        NSTextField *numberField = [[NSTextField alloc] initWithFrame:NSMakeRect(125, 108, 290, 24)]; [numberField setStringValue:@"1"];
        NSTextField *titleField = [[NSTextField alloc] initWithFrame:NSMakeRect(125, 74, 290, 24)]; [titleField setStringValue:title];
        NSPopUpButton *orientationPopup = [[NSPopUpButton alloc] initWithFrame:NSMakeRect(125, 40, 190, 25) pullsDown:NO];
        [orientationPopup addItemsWithTitles:@[@"Automatic", @"Portrait", @"Landscape"]];
        NSButton *include = [[NSButton alloc] initWithFrame:NSMakeRect(125, 7, 290, 24)]; [include setButtonType:NSButtonTypeSwitch];
        [include setTitle:@"Include group descriptives"]; [include setState:NSControlStateValueOn];
        [accessory addSubview:GLMLabel(@"Table number", NSMakeRect(0, 110, 115, 20), 12, NSFontWeightRegular)]; [accessory addSubview:numberField];
        [accessory addSubview:GLMLabel(@"Table title", NSMakeRect(0, 76, 115, 20), 12, NSFontWeightRegular)]; [accessory addSubview:titleField];
        [accessory addSubview:GLMLabel(@"Orientation", NSMakeRect(0, 42, 115, 20), 12, NSFontWeightRegular)]; [accessory addSubview:orientationPopup];
        if (_state.tables.size() > 1) [accessory addSubview:include];
        [alert setAccessoryView:accessory]; if ([alert runModal] != NSAlertFirstButtonReturn) return;
        number = [numberField stringValue]; title = [titleField stringValue]; orientation = [[orientationPopup selectedItem] title];
        includeDesc = [include state] == NSControlStateValueOn;
    }
    NSSavePanel *panel = [NSSavePanel savePanel];
    [panel setTitle:apa ? @"Export PDF — APA 7 style" : @"Export PDF — As displayed"];
    [panel setNameFieldStringValue:[ToNSString(_state.id) stringByAppendingString:(apa ? @"_APA7.pdf" : @".pdf")]];
    if ([panel runModal] != NSModalResponseOK) return;
    CGFloat preferred = (CGFloat)rlispstat::core::MeanComparisonPreferredWidth(_state);
    const BOOL landscape = [orientation isEqualToString:@"Landscape"] ||
        ([orientation isEqualToString:@"Automatic"] && preferred > 720.0);
    NSPrintInfo *printInfo = [[NSPrintInfo sharedPrintInfo] copy];
    [printInfo setOrientation:(landscape ? NSPaperOrientationLandscape : NSPaperOrientationPortrait)];
    [printInfo setTopMargin:36.0]; [printInfo setBottomMargin:36.0];
    [printInfo setLeftMargin:36.0]; [printInfo setRightMargin:36.0];
    const NSSize paper = [printInfo paperSize];
    const CGFloat paperShort = std::min(paper.width, paper.height);
    const CGFloat paperLong = std::max(paper.width, paper.height);
    const CGFloat pdfWidth = (landscape ? paperLong : paperShort) - 72.0;
    const CGFloat pdfPageHeight = (landscape ? paperShort : paperLong) - 72.0;
    MeanComparisonReportView *printView = [[MeanComparisonReportView alloc] initWithController:self];
    [printView configureExportAPA:apa displayed:!apa number:number title:title includeDescriptives:includeDesc
                        onlyTable:(all ? -1 : _selectedTable)];
    [printView configurePrintPageHeight:pdfPageHeight];
    [printView setFrame:NSMakeRect(0, 0, pdfWidth, [printView preferredHeight])];
    [printInfo setHorizontalPagination:NSPrintingPaginationModeClip];
    [printInfo setVerticalPagination:NSPrintingPaginationModeClip];
    [[printInfo dictionary] setObject:NSPrintSaveJob forKey:NSPrintJobDisposition];
    [[printInfo dictionary] setObject:[panel URL] forKey:NSPrintJobSavingURL];
    NSPrintOperation *operation = [NSPrintOperation printOperationWithView:printView printInfo:printInfo];
    [operation setShowsPrintPanel:NO]; [operation setShowsProgressPanel:NO];
    BOOL ok = [operation runOperation];
    [_statusField setStringValue:ok ? @"PDF exported." : @"The PDF could not be written."];
}

- (void)exportPDFAPA:(id)sender { [self writePDFAPA:YES all:[[[sender representedObject] description] isEqualToString:@"all"]]; }
- (void)exportPDFDisplayed:(id)sender { [self writePDFAPA:NO all:[[[sender representedObject] description] isEqualToString:@"all"]]; }

- (void)openBoxplot:(id)sender
{
    (void)sender; const MeanComparisonRow *row = [self currentRow];
    if (!row || row->variable.empty() || _state.groupVariable.empty()) return;
    OpenTable1BoxplotOnMain(_state.datasetId, row->variable, _state.groupVariable);
}

- (void)openMeanComparisonPlot:(id)sender
{
    NSString *kindValue = [sender representedObject];
    const MeanComparisonRow *row = [self currentRow];
    if (!kindValue || !row || row->variable.empty()) return;
    const std::string kind([kindValue UTF8String]);
    if (kind == "histogram") {
        OpenTable1HistogramOnMain(_state.datasetId, row->variable);
    } else if (kind == "boxplot") {
        OpenTable1BoxplotOnMain(_state.datasetId, row->variable, "");
    } else if (kind == "grouped_boxplot") {
        if (_state.groupVariable.empty()) return;
        OpenTable1BoxplotOnMain(_state.datasetId, row->variable, _state.groupVariable);
    } else if (kind == "paired_forest_plot") {
        const std::vector<rlispstat::core::MeanComparisonPairedForestRow> forestRows =
            rlispstat::core::MeanComparisonPairedForestRows(_state);
        std::vector<rlispstat::core::LinearFunctionEstimate> estimates;
        GLMPairwiseComparisonPlotLink link;
        link.group = _state.datasetId;
        link.response = "Paired differences";
        link.factor = "Variable pair";
        link.method = _state.method;
        link.confidenceLevel = _state.confidenceLevel;
        link.pairedMeanDifferences = true;
        std::set<int> allRows;
        for (const rlispstat::core::MeanComparisonPairedForestRow &source : forestRows) {
            if (source.firstVariable != row->variable ||
                source.secondVariable != row->secondVariable) continue;
            rlispstat::core::LinearFunctionEstimate estimate;
            estimate.label = source.label;
            estimate.comparisonId = source.firstVariable + "\x1f" + source.secondVariable;
            estimate.firstLevel = source.firstVariable;
            estimate.secondLevel = source.secondVariable;
            estimate.estimate = source.estimate;
            estimate.stdError = source.standardError;
            estimate.statistic = source.statistic;
            estimate.degreesOfFreedom = source.degreesOfFreedom;
            estimate.pValue = source.pValue;
            estimate.adjustedPValue = source.adjustedPValue;
            estimate.ciLower = source.confidenceLower;
            estimate.ciUpper = source.confidenceUpper;
            estimates.push_back(std::move(estimate));
            std::set<int> pairRows(source.originalRowIndices.begin(), source.originalRowIndices.end());
            link.rowsByComparison.push_back(pairRows);
            allRows.insert(pairRows.begin(), pairRows.end());
            break;
        }
        if (estimates.empty()) {
            [_statusField setStringValue:@"No complete paired estimates are available for the forest plot."];
            return;
        }
        DataFrameModel dataframe = [self dataframeSnapshot];
        link.casesAnalysed = static_cast<int>(allRows.size());
        link.casesExcluded = std::max(0, dataframe.rows - link.casesAnalysed);
        ShowGLMPairwiseComparisonPlotOnMain(row->label, estimates, link);
    } else if (kind == "paired_scatterplot") {
        if (row->secondVariable.empty() || row->secondVariable == row->variable) return;
        OpenMeanComparisonPairedScatterplotOnMain(
            _state.datasetId, row->variable, row->secondVariable);
    } else if (kind == "paired_difference_histogram") {
        if (row->secondVariable.empty() || row->secondVariable == row->variable) return;
        OpenMeanComparisonDifferenceHistogramOnMain(
            _state.datasetId, row->variable, row->secondVariable);
    }
}

- (void)openPairwise:(id)sender
{
    (void)sender; const MeanComparisonTable *table = [self currentTable]; const MeanComparisonRow *row = [self currentRow];
    if (!table || table->tableId != "omnibus" || !row || row->variable.empty()) return;
    DataFrameModel dataframe; PlotModel seed;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        const DataFrameModel *found = FindDataFrameUnlockedConst(_state.datasetId);
        if (!found) { [_statusField setStringValue:@"Dataset is no longer available."]; return; }
        dataframe = *found;
    }
    if (!BuildSeedPlotForGroup(_state.datasetId, seed)) { [_statusField setStringValue:@"Dataset model is unavailable."]; return; }
    GLMFitSummary fit; fit.ok = true; fit.beta = {0.0}; fit.covariance = {{1.0}}; fit.rowsUsed = row->originalRowIndices;
    std::vector<std::string> terms{_state.groupVariable}; std::map<std::string, std::string> types{{_state.groupVariable, "factor"}};
    rlispstat::core::GLMPairwiseComparisonRequest request; request.term = _state.groupVariable;
    request.confidenceLevel = _state.confidenceLevel;
    request.adjustment = _state.method.find("Classical") != std::string::npos ? "classical-tukey" : "games-howell";
    rlispstat::core::GLMPairwiseComparisonResult result; std::string message;
    if (!RunRBackedGLMPairwiseComparisons(dataframe, &seed, row->variable, terms, types, fit, request, &result, &message)) {
        [_statusField setStringValue:ToNSString(message)]; return;
    }
    GLMPairwiseComparisonPlotLink link = BuildGLMPairwiseComparisonPlotLink(
        _state.datasetId, dataframe, row->variable, _state.groupVariable, row->originalRowIndices, result);
    ShowGLMPairwiseResultsWindowOnMain(row->variable + " by " + _state.groupVariable, result, link);
    [_statusField setStringValue:@"Pairwise comparisons calculated in R."];
}

- (DataFrameModel)dataframeSnapshot
{
    std::lock_guard<std::mutex> lock(g_mutex);
    const DataFrameModel *dataframe = FindDataFrameUnlockedConst(_state.datasetId);
    return dataframe ? *dataframe : DataFrameModel();
}

- (void)addDependentVariable:(id)sender
{
    NSString *name = [sender representedObject]; if (!name) return;
    std::string variable([name UTF8String]);
    auto &variables = _state.specification.dependentVariableIds;
    if (std::find(variables.begin(), variables.end(), variable) != variables.end()) return;
    variables.push_back(variable); [self queueRefit];
}

- (void)removeDependentVariable:(id)sender
{
    if (_state.specification.dependentVariableIds.size() <= 1) return;
    NSString *name = [sender representedObject]; if (!name) return;
    const std::string variable([name UTF8String]); auto &variables = _state.specification.dependentVariableIds;
    variables.erase(std::remove(variables.begin(), variables.end(), variable), variables.end());
    if (_state.specification.groupingVariableId && *_state.specification.groupingVariableId == variable) {
        _state.specification.groupingVariableId.reset();
    }
    [self queueRefit];
}

- (void)setGroupingVariable:(id)sender
{
    NSString *name = [sender isKindOfClass:[NSPopUpButton class]]
        ? [(NSPopUpButton *)sender titleOfSelectedItem]
        : [sender representedObject];
    if (!name || [name isEqualToString:@"No available grouping variables"]) return;
    const std::string group([name UTF8String]);
    if (_state.specification.groupingVariableId &&
        *_state.specification.groupingVariableId == group) return;
    _state.specification.groupingVariableId = group; _state.groupVariable = group;
    DataFrameModel dataframe = [self dataframeSnapshot];
    const DataColumn *column = FindDataColumnInDataFrame(dataframe, group);
    _state.specification.groupOrderIds = column ? MeanComparisonEffectiveLevels(*column) : std::vector<std::string>();
    [self queueRefit];
}

- (void)setMethod:(id)sender
{
    NSString *name = [sender representedObject]; if (!name) return;
    const std::string method([name UTF8String]);
    if (method == "wilcoxon") _state.specification.method = rlispstat::core::MeanComparisonMethod::WilcoxonSignedRank;
    else if (method == "mann_whitney") _state.specification.method = rlispstat::core::MeanComparisonMethod::MannWhitney;
    else if (method == "kruskal_wallis") _state.specification.method = rlispstat::core::MeanComparisonMethod::KruskalWallis;
    else if (method == "student") _state.specification.method =
        _state.analysisType == "one_sample_t_test" || _state.analysisType == "paired_samples_t_test"
            ? rlispstat::core::MeanComparisonMethod::OneSampleT
            : rlispstat::core::MeanComparisonMethod::StudentT;
    else if (method == "classical") _state.specification.method = rlispstat::core::MeanComparisonMethod::ClassicalAnova;
    else _state.specification.method = _state.analysisType == "one_way_anova"
        ? rlispstat::core::MeanComparisonMethod::WelchAnova : rlispstat::core::MeanComparisonMethod::WelchT;
    [self queueRefit];
}

- (void)setAlternative:(id)sender
{
    NSString *name = [sender representedObject]; if (!name) return;
    const std::string value([name UTF8String]); _state.alternative = value;
    _state.specification.alternative = value == "greater" ? rlispstat::core::AlternativeHypothesis::Greater :
        (value == "less" ? rlispstat::core::AlternativeHypothesis::Less : rlispstat::core::AlternativeHypothesis::TwoSided);
    [self queueRefit];
}

- (void)setConfidenceLevel:(id)sender
{
    NSNumber *number = [sender representedObject]; if (!number) return;
    _state.confidenceLevel = [number doubleValue]; _state.specification.confidenceLevel = _state.confidenceLevel;
    [self queueRefit];
}

- (void)setPAdjustment:(id)sender
{
    NSString *name = [sender representedObject]; if (!name) return;
    _state.specification.pAdjustment = rlispstat::core::MeanComparisonAdjustmentFromName(std::string([name UTF8String]));
    [self queueRefit];
}

- (void)setGroupOrder:(id)sender
{
    NSArray *values = [sender representedObject]; if (![values isKindOfClass:[NSArray class]]) return;
    std::vector<std::string> order;
    for (NSString *value in values) order.push_back(std::string([value UTF8String]));
    _state.specification.groupOrderIds = std::move(order); [self queueRefit];
}

- (void)addPair:(id)sender
{
    NSArray *values = [sender representedObject];
    if (![values isKindOfClass:[NSArray class]] || [values count] != 2) return;
    const std::string first([values[0] UTF8String]), second([values[1] UTF8String]);
    if (first == second) return;
    for (const PairedVariableSpecification &pair : _state.specification.pairs) {
        if (pair.firstVariableId == first && pair.secondVariableId == second) return;
    }
    _state.specification.pairs.push_back({"pair:" + first + "\x1f" + second, first, second}); [self queueRefit];
}

- (void)removePair:(id)sender
{
    if (_state.specification.pairs.size() <= 1) return;
    NSString *pairId = [sender representedObject]; if (!pairId) return;
    const std::string id([pairId UTF8String]); auto &pairs = _state.specification.pairs;
    pairs.erase(std::remove_if(pairs.begin(), pairs.end(), [&](const PairedVariableSpecification &pair) {
        return pair.pairId == id;
    }), pairs.end()); [self queueRefit];
}

- (void)reversePair:(id)sender
{
    NSString *pairId = [sender representedObject]; if (!pairId) return;
    const std::string id([pairId UTF8String]);
    for (PairedVariableSpecification &pair : _state.specification.pairs) {
        if (pair.pairId != id) continue;
        std::swap(pair.firstVariableId, pair.secondVariableId);
        pair.pairId = "pair:" + pair.firstVariableId + "\x1f" + pair.secondVariableId;
        [self queueRefit]; return;
    }
}

- (void)toggleDescriptives:(id)sender
{
    (void)sender; _showDescriptives = !_showDescriptives;
    [_reportView setFrameSize:NSMakeSize(NSWidth([_reportView frame]), [_reportView preferredHeight])];
    [_reportView setNeedsDisplay:YES];
}

- (void)openDescriptivesWindow:(id)sender
{
    (void)sender;
    if (!_descriptivesController) {
        _descriptivesController = [[MeanComparisonWindowController alloc] initWithState:_state descriptivesOnly:YES];
    } else [_descriptivesController updateState:_state];
    [_descriptivesController show];
}

- (void)editTestValue:(id)sender
{
    (void)sender; if (_testValueField) { [[_window contentView] window].initialFirstResponder = _testValueField; [_window makeFirstResponder:_testValueField]; }
}

- (void)commitTestValue:(id)sender
{
    NSTextField *field = (NSTextField *)sender; const char *raw = [[field stringValue] UTF8String];
    char *end = nullptr; const double value = raw ? std::strtod(raw, &end) : NAN;
    if (!raw || !*raw || !end || *end != '\0' || !std::isfinite(value)) {
        [field setStringValue:ToNSString(rlispstat::core::FormatModelNumberOrDash(_state.specification.testValue))];
        [self showInlineError:@"Test value must be numeric and finite."]; return;
    }
    if (value == _state.specification.testValue) return;
    _state.specification.testValue = value; _state.testValue = value; [self queueRefit];
}

- (void)controlTextDidEndEditing:(NSNotification *)notification
{
    if ([notification object] == _testValueField) [self commitTestValue:_testValueField];
}

- (BOOL)control:(NSControl *)control textView:(NSTextView *)textView
 doCommandBySelector:(SEL)commandSelector
{
    (void)textView;
    if (control == _testValueField && commandSelector == @selector(cancelOperation:)) {
        [_testValueField setStringValue:ToNSString(rlispstat::core::FormatModelNumberOrDash(
            _state.specification.testValue))];
        [_window makeFirstResponder:_reportView];
        return YES;
    }
    return NO;
}

- (NSMenuItem *)exportItem:(NSString *)title action:(SEL)action all:(BOOL)all
{
    NSMenuItem *item = [[NSMenuItem alloc] initWithTitle:title action:action keyEquivalent:@""];
    [item setTarget:self]; [item setRepresentedObject:(all ? @"all" : @"current")]; return item;
}

- (NSMenu *)contextMenuForTable:(NSInteger)tableIndex row:(NSInteger)rowIndex
{
    NSMenu *menu = [[NSMenu alloc] initWithTitle:@"Test"];
    const MeanComparisonTable *table = [self currentTable];
    const MeanComparisonRow *row = [self currentRow];
    auto addOption = [&](NSMenu *target, NSString *title, SEL action, id represented, BOOL checked, BOOL enabled) {
        NSMenuItem *item = [[NSMenuItem alloc] initWithTitle:title action:action keyEquivalent:@""];
        [item setTarget:self]; [item setRepresentedObject:represented]; [item setState:checked ? NSControlStateValueOn : NSControlStateValueOff];
        [item setEnabled:enabled && !_refitPending]; [target addItem:item]; return item;
    };
    auto addSubmenu = [&](NSMenu *target, NSString *title) {
        NSMenuItem *root = [[NSMenuItem alloc] initWithTitle:title action:nil keyEquivalent:@""];
        NSMenu *submenu = [[NSMenu alloc] initWithTitle:title]; [root setSubmenu:submenu]; [target addItem:root]; return submenu;
    };

    DataFrameModel dataframe = [self dataframeSnapshot];
    const std::vector<std::string> numeric = MeanComparisonNumericVariables(dataframe);
    if (!_descriptivesOnly) {
        if (_state.analysisType != "paired_samples_t_test") {
            NSMenu *dependent = addSubmenu(menu, @"Dependent variables");
            NSMenu *add = addSubmenu(dependent, @"Add");
            for (const std::string &variable : numeric) {
                const bool included = std::find(_state.specification.dependentVariableIds.begin(),
                    _state.specification.dependentVariableIds.end(), variable) != _state.specification.dependentVariableIds.end();
                const bool grouping = _state.specification.groupingVariableId && *_state.specification.groupingVariableId == variable;
                if (!included && !grouping) addOption(add, ToNSString(variable), @selector(addDependentVariable:), ToNSString(variable), NO, YES);
            }
            NSMenu *remove = addSubmenu(dependent, @"Remove");
            for (const std::string &variable : _state.specification.dependentVariableIds) {
                addOption(remove, ToNSString(variable), @selector(removeDependentVariable:), ToNSString(variable), NO,
                          _state.specification.dependentVariableIds.size() > 1);
            }
            if (row && !row->variable.empty()) {
                addOption(menu, [@"Remove " stringByAppendingString:ToNSString(row->variable)],
                          @selector(removeDependentVariable:), ToNSString(row->variable), NO,
                          _state.specification.dependentVariableIds.size() > 1);
            }
        } else {
            NSMenu *pairs = addSubmenu(menu, @"Pairs");
            NSMenu *addPair = addSubmenu(pairs, @"Add pair");
            for (const std::string &first : numeric) {
                NSMenu *seconds = addSubmenu(addPair, ToNSString(first));
                for (const std::string &second : numeric) {
                    if (first == second) continue;
                    bool duplicate = false;
                    for (const PairedVariableSpecification &pair : _state.specification.pairs) {
                        if (pair.firstVariableId == first && pair.secondVariableId == second) { duplicate = true; break; }
                    }
                    if (!duplicate) addOption(seconds, ToNSString(second), @selector(addPair:),
                                               @[ToNSString(first), ToNSString(second)], NO, YES);
                }
            }
            NSMenu *removePair = addSubmenu(pairs, @"Remove pair");
            for (const PairedVariableSpecification &pair : _state.specification.pairs) {
                addOption(removePair, ToNSString(pair.firstVariableId + " \u2212 " + pair.secondVariableId),
                          @selector(removePair:), ToNSString(pair.pairId), NO, _state.specification.pairs.size() > 1);
            }
            if (row && !row->rowId.empty()) {
                addOption(menu, [@"Reverse " stringByAppendingString:ToNSString(row->label)], @selector(reversePair:),
                          ToNSString(row->rowId), NO, YES);
                addOption(menu, [@"Remove " stringByAppendingString:ToNSString(row->label)], @selector(removePair:),
                          ToNSString(row->rowId), NO, _state.specification.pairs.size() > 1);
            }
        }

        if (_state.analysisType == "independent_samples_t_test" || _state.analysisType == "one_way_anova") {
            NSMenu *groups = addSubmenu(menu, @"Grouping variable");
            const bool independent = _state.analysisType == "independent_samples_t_test";
            for (const DataColumn &column : dataframe.columns) {
                if (!MeanComparisonGroupingCandidate(column, independent)) continue;
                if (std::find(_state.specification.dependentVariableIds.begin(), _state.specification.dependentVariableIds.end(), column.name) !=
                    _state.specification.dependentVariableIds.end()) continue;
                const bool selected = _state.specification.groupingVariableId && *_state.specification.groupingVariableId == column.name;
                addOption(groups, ToNSString(column.name), @selector(setGroupingVariable:), ToNSString(column.name), selected, YES);
            }
            NSMenu *orders = addSubmenu(menu, @"Group order");
            std::vector<std::string> defined;
            if (_state.specification.groupingVariableId) {
                const DataColumn *column = FindDataColumnInDataFrame(dataframe, *_state.specification.groupingVariableId);
                if (column) defined = MeanComparisonEffectiveLevels(*column);
            }
            auto arrayFor = [](const std::vector<std::string> &values) {
                NSMutableArray *array = [NSMutableArray array]; for (const std::string &value : values) [array addObject:ToNSString(value)]; return array;
            };
            if (independent && defined.size() == 2) {
                addOption(orders, ToNSString(defined[0] + " \u2212 " + defined[1]), @selector(setGroupOrder:), arrayFor(defined),
                          _state.specification.groupOrderIds == defined, YES);
                std::reverse(defined.begin(), defined.end());
                addOption(orders, ToNSString(defined[0] + " \u2212 " + defined[1]), @selector(setGroupOrder:), arrayFor(defined),
                          _state.specification.groupOrderIds == defined, YES);
            } else if (!independent && !defined.empty()) {
                addOption(orders, @"As defined", @selector(setGroupOrder:), arrayFor(defined), _state.specification.groupOrderIds == defined, YES);
                std::vector<std::string> ascending = defined; std::sort(ascending.begin(), ascending.end());
                addOption(orders, @"Label ascending", @selector(setGroupOrder:), arrayFor(ascending), _state.specification.groupOrderIds == ascending, YES);
                std::reverse(ascending.begin(), ascending.end());
                addOption(orders, @"Label descending", @selector(setGroupOrder:), arrayFor(ascending), _state.specification.groupOrderIds == ascending, YES);
                if (row && !row->variable.empty() && _state.specification.groupingVariableId) {
                    std::map<std::string, double> meansFromR;
                    for (const MeanComparisonTable &candidate : _state.tables) {
                        if (!MeanComparisonIsDescriptiveTable(candidate)) continue;
                        size_t meanColumn = candidate.columns.size();
                        for (size_t c = 0; c < candidate.columns.size(); ++c) {
                            if (candidate.columns[c].key == "mean") { meanColumn = c; break; }
                        }
                        if (meanColumn >= candidate.columns.size()) continue;
                        for (const MeanComparisonRow &descriptive : candidate.rows) {
                            if (descriptive.variable != row->variable || descriptive.group.empty() ||
                                meanColumn >= descriptive.cells.size() || !descriptive.cells[meanColumn].numericValue) continue;
                            meansFromR[descriptive.group] = *descriptive.cells[meanColumn].numericValue;
                        }
                    }
                    if (!meansFromR.empty()) {
                        std::vector<std::string> byMean = defined;
                        std::stable_sort(byMean.begin(), byMean.end(), [&](const std::string &a, const std::string &b) {
                            const auto left = meansFromR.find(a), right = meansFromR.find(b);
                            return left != meansFromR.end() && right != meansFromR.end() ? left->second < right->second : a < b;
                        });
                        addOption(orders, @"Mean ascending", @selector(setGroupOrder:), arrayFor(byMean), _state.specification.groupOrderIds == byMean, YES);
                        std::reverse(byMean.begin(), byMean.end());
                        addOption(orders, @"Mean descending", @selector(setGroupOrder:), arrayFor(byMean), _state.specification.groupOrderIds == byMean, YES);
                    }
                }
            }
            NSMenu *methods = addSubmenu(menu, @"Method");
            const bool ordinalResponse = MeanComparisonHasOrdinalResponse(_state, dataframe);
            if (independent) {
                addOption(methods, @"Welch", @selector(setMethod:), @"welch", _state.specification.method == rlispstat::core::MeanComparisonMethod::WelchT, YES);
                addOption(methods, @"Student — equal variances", @selector(setMethod:), @"student", _state.specification.method == rlispstat::core::MeanComparisonMethod::StudentT, YES);
                if (ordinalResponse) addOption(methods, @"Mann–Whitney U", @selector(setMethod:), @"mann_whitney",
                    _state.specification.method == rlispstat::core::MeanComparisonMethod::MannWhitney, YES);
            } else {
                addOption(methods, @"Welch one-way ANOVA", @selector(setMethod:), @"welch", _state.specification.method == rlispstat::core::MeanComparisonMethod::WelchAnova, YES);
                addOption(methods, @"Classical one-way ANOVA", @selector(setMethod:), @"classical", _state.specification.method == rlispstat::core::MeanComparisonMethod::ClassicalAnova, YES);
                if (ordinalResponse) addOption(methods, @"Kruskal–Wallis", @selector(setMethod:), @"kruskal_wallis",
                    _state.specification.method == rlispstat::core::MeanComparisonMethod::KruskalWallis, YES);
            }
        }

        if (_state.analysisType == "one_sample_t_test" || _state.analysisType == "paired_samples_t_test") {
            NSMenu *methods = addSubmenu(menu, @"Method");
            const bool oneSample = _state.analysisType == "one_sample_t_test";
            addOption(methods, oneSample ? @"One-sample t test" : @"Paired t test",
                      @selector(setMethod:), @"student",
                      _state.specification.method == rlispstat::core::MeanComparisonMethod::OneSampleT, YES);
            if (MeanComparisonHasOrdinalResponse(_state, dataframe)) {
                addOption(methods, oneSample ? @"Wilcoxon signed-rank" : @"Paired Wilcoxon signed-rank",
                          @selector(setMethod:), @"wilcoxon",
                          _state.specification.method == rlispstat::core::MeanComparisonMethod::WilcoxonSignedRank, YES);
            }
        }

        if (_state.analysisType == "one_sample_t_test") addOption(menu, @"Edit test value", @selector(editTestValue:), nil, NO, YES);
        if (_state.analysisType != "one_way_anova") {
            NSMenu *alternatives = addSubmenu(menu, @"Alternative");
            addOption(alternatives, @"Two-sided", @selector(setAlternative:), @"two.sided", _state.specification.alternative == rlispstat::core::AlternativeHypothesis::TwoSided, YES);
            addOption(alternatives, @"Greater", @selector(setAlternative:), @"greater", _state.specification.alternative == rlispstat::core::AlternativeHypothesis::Greater, YES);
            addOption(alternatives, @"Less", @selector(setAlternative:), @"less", _state.specification.alternative == rlispstat::core::AlternativeHypothesis::Less, YES);
        }
        NSMenu *confidence = addSubmenu(menu, @"Confidence level");
        for (NSNumber *level in @[@0.90, @0.95, @0.99]) {
            addOption(confidence, [NSString stringWithFormat:@"%.0f%%", [level doubleValue] * 100.0], @selector(setConfidenceLevel:), level,
                      std::fabs(_state.specification.confidenceLevel - [level doubleValue]) < 1e-9, YES);
        }
        NSMenu *adjustments = addSubmenu(menu, @"P-value adjustment");
        addOption(adjustments, @"None", @selector(setPAdjustment:), @"none", _state.specification.pAdjustment == rlispstat::core::MultipleTestingAdjustment::None, YES);
        addOption(adjustments, @"Holm", @selector(setPAdjustment:), @"holm", _state.specification.pAdjustment == rlispstat::core::MultipleTestingAdjustment::Holm, YES);
        addOption(adjustments, @"Bonferroni", @selector(setPAdjustment:), @"bonferroni", _state.specification.pAdjustment == rlispstat::core::MultipleTestingAdjustment::Bonferroni, YES);

        if (table && table->tableId == "omnibus" && rowIndex >= 0) {
            addOption(menu, @"Pairwise comparisons", @selector(openPairwise:), nil, NO, YES);
        }
        const bool hasSelectedVariable = row && !row->variable.empty();
        const bool hasPairedVariables = hasSelectedVariable && !row->secondVariable.empty() &&
            row->secondVariable != row->variable;
        for (const rlispstat::core::MeanComparisonPlotMenuOption &option :
             rlispstat::core::MeanComparisonPlotMenuOptions(
                 _state.analysisType, hasSelectedVariable, hasPairedVariables)) {
            addOption(menu, ToNSString(option.title), @selector(openMeanComparisonPlot:),
                      ToNSString(option.plotKind), NO, YES);
        }
        addOption(menu, _showDescriptives ? @"Hide descriptives" : @"Show descriptives", @selector(toggleDescriptives:), nil, NO, YES);
        addOption(menu, @"Open descriptives window", @selector(openDescriptivesWindow:), nil, NO, YES);
        [menu addItem:[NSMenuItem separatorItem]];
    }
    NSMenuItem *root = [[NSMenuItem alloc] initWithTitle:@"Export" action:nil keyEquivalent:@""];
    NSMenu *exportMenu = [[NSMenu alloc] initWithTitle:@"Export"];
    if (table) {
        AddStandardTableVisualExportItems(exportMenu, _reportView,
            ToNSString(_state.title), ToNSString(_state.id),
            ToNSString(rlispstat::core::MeanComparisonTableText(*table)));
        [exportMenu addItem:[NSMenuItem separatorItem]];
    }
    NSMenuItem *copySelected = [[NSMenuItem alloc] initWithTitle:@"Copy selected rows" action:@selector(copySelected:) keyEquivalent:@""];
    [copySelected setTarget:self]; [copySelected setEnabled:rowIndex >= 0]; [exportMenu addItem:copySelected];
    NSMenuItem *copyTable = [[NSMenuItem alloc] initWithTitle:@"Copy table with headers" action:@selector(copyTable:) keyEquivalent:@""];
    [copyTable setTarget:self]; [copyTable setEnabled:table != nullptr]; [exportMenu addItem:copyTable]; [exportMenu addItem:[NSMenuItem separatorItem]];
    [exportMenu addItem:[self exportItem:@"CSV…" action:@selector(exportCSV:) all:NO]];
    [exportMenu addItem:[self exportItem:@"PDF — APA 7 style…" action:@selector(exportPDFAPA:) all:NO]];
    [exportMenu addItem:[self exportItem:@"PDF — As displayed…" action:@selector(exportPDFDisplayed:) all:NO]];
    if (!_descriptivesOnly && _state.tables.size() > 1) {
        [exportMenu addItem:[NSMenuItem separatorItem]];
        [exportMenu addItem:[self exportItem:@"All result tables — CSV…" action:@selector(exportCSV:) all:YES]];
        [exportMenu addItem:[self exportItem:@"All result tables — APA 7 style…" action:@selector(exportPDFAPA:) all:YES]];
        [exportMenu addItem:[self exportItem:@"All result tables — As displayed…" action:@selector(exportPDFDisplayed:) all:YES]];
    }
    [root setSubmenu:exportMenu]; [menu addItem:root];
    AddSnapshotAlbumContextItems(menu); return menu;
}

- (void)show { EnableNotesForWindow(_window, _state.id, @"this comparison result"); [NSApp activateIgnoringOtherApps:YES]; [_window makeKeyAndOrderFront:nil]; }
- (void)windowWillClose:(NSNotification *)notification
{
    (void)notification;
    if (!_descriptivesOnly) {
        std::lock_guard<std::mutex> lock(g_mutex); g_meanComparisonControllers.erase(_state.id);
    }
}
@end

static void ShowMeanComparisonStateOnMain(const MeanComparisonState &state)
{
    const MeanComparisonState copy = state;
    dispatch_async(dispatch_get_main_queue(), ^{
        MeanComparisonWindowController *controller = nil;
        {
            std::lock_guard<std::mutex> lock(g_mutex);
            auto it = g_meanComparisonControllers.find(copy.id);
            if (it != g_meanComparisonControllers.end()) controller = it->second;
        }
        if (!controller) {
            controller = [[MeanComparisonWindowController alloc] initWithState:copy];
            std::lock_guard<std::mutex> lock(g_mutex); g_meanComparisonControllers[copy.id] = controller;
        } else [controller updateState:copy];
        [controller show];
    });
}

static void ShowMeanComparisonErrorOnMain(const std::string &id, const std::string &message)
{
    const std::string copyId = id, copyMessage = message;
    dispatch_async(dispatch_get_main_queue(), ^{
        MeanComparisonWindowController *controller = nil;
        {
            std::lock_guard<std::mutex> lock(g_mutex);
            auto it = g_meanComparisonControllers.find(copyId);
            if (it != g_meanComparisonControllers.end()) controller = it->second;
        }
        if (controller) [controller showInlineError:ToNSString(copyMessage)];
    });
}

