- (void)copyTable:(id)sender
{
    (void)sender;
    NSPasteboard *pasteboard = [NSPasteboard generalPasteboard];
    [pasteboard clearContents];
    [pasteboard setString:ToNSString([self tableText]) forType:NSPasteboardTypeString];
    [_statusField setStringValue:ToNSString(rlispstat::core::Table1CopiedStatus())];
}

- (std::string)csvText
{
    return rlispstat::core::Table1CSVText(_state);
}

- (std::string)markdownText
{
    return rlispstat::core::Table1MarkdownText(_state);
}

- (void)writeString:(const std::string &)text defaultName:(NSString *)name title:(NSString *)title
{
    NSSavePanel *panel = [NSSavePanel savePanel];
    [panel setNameFieldStringValue:name];
    [panel setTitle:title];
    if ([panel runModal] == NSModalResponseOK) {
        NSError *error = nil;
        BOOL ok = [ToNSString(text) writeToURL:[panel URL] atomically:YES encoding:NSUTF8StringEncoding error:&error];
        [_statusField setStringValue:ok ? ToNSString(rlispstat::core::Table1ExportedStatus()) : ToNSString(rlispstat::core::Table1ExportFailedStatus())];
    }
}

- (void)exportCSV:(id)sender
{
    (void)sender;
    [self writeString:[self csvText] defaultName:ToNSString(_state.id + ".csv") title:ToNSString(rlispstat::core::Table1ExportCSVDialogTitle())];
}

- (void)exportMarkdown:(id)sender
{
    (void)sender;
    [self writeString:[self markdownText] defaultName:ToNSString(_state.id + ".md") title:ToNSString(rlispstat::core::Table1ExportMarkdownDialogTitle())];
}

- (void)exportPDF:(id)sender
{
    (void)sender;
    NSSavePanel *panel = [NSSavePanel savePanel];
    [panel setNameFieldStringValue:ToNSString(_state.id + ".pdf")];
    [panel setTitle:ToNSString(rlispstat::core::Table1ExportPDFPanelTitle())];
    if ([panel runModal] == NSModalResponseOK) {
        [_reportView setExportHeadingWithNumber:@"" title:ToNSString(_state.title)];
        CGFloat exportHeight = [_reportView preferredHeight];
        NSRect oldFrame = [_reportView frame];
        [_reportView setFrame:NSMakeRect(0, 0, NSWidth(oldFrame), exportHeight)];
        NSData *data = VisualExportDataForView(_reportView, @"PDF");
        [_reportView clearExportHeading];
        [_reportView setFrame:oldFrame];
        BOOL ok = [data writeToURL:[panel URL] atomically:YES];
        [_statusField setStringValue:ok ? ToNSString(rlispstat::core::Table1ExportedPDFStatus()) : ToNSString(rlispstat::core::Table1ExportPDFFailedStatus())];
    }
}

- (void)exportPDFAPA:(id)sender
{
    (void)sender;
    NSAlert *alert = [[NSAlert alloc] init];
    [alert setMessageText:@"PDF — APA 7 style"];
    [alert setInformativeText:@"Enter the table number and title."];
    [alert addButtonWithTitle:@"Continue"];
    [alert addButtonWithTitle:@"Cancel"];
    NSView *accessory = [[NSView alloc] initWithFrame:NSMakeRect(0, 0, 420, 82)];
    NSTextField *numberLabel = GLMLabel(@"Table number", NSMakeRect(0, 52, 110, 22), 12, NSFontWeightRegular);
    NSTextField *numberField = [[NSTextField alloc] initWithFrame:NSMakeRect(120, 49, 285, 24)];
    [numberField setStringValue:@"1"];
    NSTextField *titleLabel = GLMLabel(@"Title", NSMakeRect(0, 12, 110, 22), 12, NSFontWeightRegular);
    NSTextField *titleField = [[NSTextField alloc] initWithFrame:NSMakeRect(120, 9, 285, 24)];
    [titleField setStringValue:ToNSString(_state.title)];
    [accessory addSubview:numberLabel]; [accessory addSubview:numberField];
    [accessory addSubview:titleLabel]; [accessory addSubview:titleField];
    [alert setAccessoryView:accessory];
    if ([alert runModal] != NSAlertFirstButtonReturn) return;

    NSSavePanel *panel = [NSSavePanel savePanel];
    [panel setNameFieldStringValue:ToNSString(_state.id + "_APA7.pdf")];
    [panel setTitle:@"Export PDF — APA 7 style"];
    if ([panel runModal] != NSModalResponseOK) return;
    [_reportView setExportHeadingWithNumber:[numberField stringValue] title:[titleField stringValue]];
    CGFloat exportHeight = [_reportView preferredHeight];
    NSRect oldFrame = [_reportView frame];
    [_reportView setFrame:NSMakeRect(0, 0, NSWidth(oldFrame), exportHeight)];
    NSData *data = [_reportView dataWithPDFInsideRect:[_reportView bounds]];
    [_reportView clearExportHeading];
    [_reportView setFrame:oldFrame];
    BOOL ok = [data writeToURL:[panel URL] atomically:YES];
    [_statusField setStringValue:ok ? @"Exported APA 7 style PDF." : @"Could not export APA 7 style PDF."];
}

- (void)openHistogram:(id)sender
