{
    (void)sender;
    if (_selectedRow < 0 || (size_t)_selectedRow >= _state.rows.size()) return;
    std::string variable = _state.rows[(size_t)_selectedRow].variable;
    if (variable.empty()) return;
    OpenTable1BarplotOnMain(_state.datasetId, variable, _state.groupVariable);
}

