- (void)rebuildFromBackendData
{
    DataFrameModel df;
    bool found = false;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        const DataFrameModel *current = FindDataFrameUnlockedConst(_state.datasetId);
        if (current) {
            df = *current;
            found = true;
        }
    }
    if (!found) {
        [_statusField setStringValue:ToNSString(rlispstat::core::DatasetNotAvailableForRecomputeStatus())];
        return;
    }
    Table1DisplayState rebuilt = rlispstat::core::Table1StateForDataFrame(
        df, _state.id, _state.variables, _state.groupVariable, _state.variableTypes,
        _state.dataScopeCaptured ? &_state.dataScope : nullptr);
    [self updateState:rebuilt];
}

- (void)typeMenuSelected:(id)sender
{
    NSArray *payload = [sender representedObject];
    if (![payload isKindOfClass:[NSArray class]] || [payload count] < 2) return;
    std::string variable = std::string([[payload objectAtIndex:0] UTF8String]);
    std::string type = std::string([[payload objectAtIndex:1] UTF8String]);
    _state.variableTypes[variable] = type;
    std::string message;
    std::string backendType = type == "categorical" ? "factor" : (type == "ordinal" ? "numeric" : type);
    SetVariableAnalysisType(_state.datasetId, variable, backendType, &message);
    [self rebuildFromBackendData];
    [_statusField setStringValue:ToNSString(rlispstat::core::VariableTypeChangedStatus(variable, type))];
}

- (void)addVariableFromMenu:(id)sender
{
    NSString *title = [sender representedObject];
    if (!title) return;
    std::string variable = std::string([title UTF8String]);
    if (std::find(_state.variables.begin(), _state.variables.end(), variable) == _state.variables.end()) {
        _state.variables.push_back(variable);
        [self rebuildFromBackendData];
    }
}

- (void)replaceVariableFromMenu:(id)sender
{
    NSString *title = [sender representedObject];
    if (!title || _selectedRow < 0 || (size_t)_selectedRow >= _state.rows.size()) return;
    std::string oldVariable = _state.rows[(size_t)_selectedRow].variable;
    std::string newVariable = std::string([title UTF8String]);
    if (oldVariable.empty() || newVariable.empty()) return;
    for (std::string &variable : _state.variables) {
        if (variable == oldVariable) {
            variable = newVariable;
            break;
        }
    }
    [self rebuildFromBackendData];
}

- (void)removeSelectedVariable:(id)sender
{
    (void)sender;
    if (_selectedRow < 0 || (size_t)_selectedRow >= _state.rows.size()) return;
    std::string variable = _state.rows[(size_t)_selectedRow].variable;
    if (variable.empty()) return;
    _state.variables.erase(std::remove(_state.variables.begin(), _state.variables.end(), variable), _state.variables.end());
    [self rebuildFromBackendData];
}

- (void)setGroupFromMenu:(id)sender
{
    NSString *title = [sender representedObject];
    if (!title) return;
    _state.groupVariable = std::string([title UTF8String]);
    _state.variables.erase(std::remove(_state.variables.begin(), _state.variables.end(), _state.groupVariable), _state.variables.end());
    [self rebuildFromBackendData];
}

- (void)clearGroup:(id)sender
{
    (void)sender;
    _state.groupVariable.clear();
    [self rebuildFromBackendData];
}

- (void)toggleLink:(id)sender
{
    (void)sender;
    _state.linkEnabled = [_linkCheckbox state] == NSControlStateValueOn;
    std::lock_guard<std::mutex> lock(g_mutex);
    if (_state.linkEnabled && !_state.sourcePlotId.empty()) {
        g_linkedTables[_state.sourcePlotId].insert(_tableId);
        g_linkedTableSources[_tableId] = _state.sourcePlotId;
    } else if (!_state.sourcePlotId.empty()) {
        auto it = g_linkedTableSources.find(_tableId);
        if (it != g_linkedTableSources.end()) {
            std::string plotId = it->second;
            g_linkedTables[plotId].erase(_tableId);
            if (g_linkedTables[plotId].empty()) g_linkedTables.erase(plotId);
            g_linkedTableSources.erase(it);
        }
    }
}

- (void)refreshFromSource:(id)sender
{
    (void)sender;
    if (!_state.linkEnabled || _state.sourcePlotId.empty()) return;
    NotifyBarplotLinkedTablesChanged(_state.sourcePlotId);
}

- (void)rebuildNestedContingencyFromSelection
{
    DataFrameModel df;
    bool found = false;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        const DataFrameModel *current = FindDataFrameUnlockedConst(_state.datasetId);
        if (current) {
            df = *current;
            found = true;
        }
    }
    if (!found) {
        [_statusField setStringValue:ToNSString(rlispstat::core::DatasetNotAvailableForRecomputeStatus())];
        return;
    }
    Table1DisplayState rebuilt = rlispstat::core::NestedContingencyTableStateForDataFrame(
        df, _state.id, _state.variables, _state.groupVariable, _state.nestedDisplayMode,
        _state.dataScopeCaptured ? &_state.dataScope : nullptr);
    rebuilt.datasetId = _state.datasetId;
    rebuilt.linkEnabled = _state.linkEnabled;
    rebuilt.sourcePlotId = _state.sourcePlotId;
    [self updateState:rebuilt];
}

- (void)propagateNestedContingencyToBarplot
{
    std::string plotId;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        auto it = g_linkedTableSources.find(_tableId);
        if (it == g_linkedTableSources.end() || !_state.linkEnabled) return;
        plotId = it->second;
    }
    PlotModel *barplotModel = nil;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        BarplotView *view = BarplotViewForPlotUnlocked(plotId);
        if (view) barplotModel = view.model;
    }
    if (!barplotModel || barplotModel->kind != "barplot") {
        [self rebuildNestedContingencyFromSelection];
        return;
    }
    barplotModel->barplotXVariables = _state.variables;
    barplotModel->barplotSplitVariable = _state.groupVariable;
    std::string message;
    if (!RebuildBarplotFromModelVariables(barplotModel, &message)) {
        [_statusField setStringValue:ToNSString(message)];
        return;
    }
    UpdateWindowTitleOnMain(barplotModel);
    RedrawPlotOnMain(barplotModel->id);
    NotifyBarplotLinkedTablesChanged(plotId);
}

- (void)changeSplitVariableFromMenu:(id)sender
{
    NSString *title = [sender representedObject];
    if (!title) return;
    _state.groupVariable = std::string([title UTF8String]);
    if (_state.linkEnabled && !_state.sourcePlotId.empty()) {
        [self propagateNestedContingencyToBarplot];
    } else {
        [self rebuildNestedContingencyFromSelection];
    }
}

- (void)addRowVariableFromMenu:(id)sender
{
    NSString *title = [sender representedObject];
    if (!title) return;
    std::string variable = std::string([title UTF8String]);
    if (std::find(_state.variables.begin(), _state.variables.end(), variable) == _state.variables.end()) {
        _state.variables.push_back(variable);
        if (_state.linkEnabled && !_state.sourcePlotId.empty()) {
            [self propagateNestedContingencyToBarplot];
        } else {
            [self rebuildNestedContingencyFromSelection];
        }
    }
}

- (void)replaceRowVariableFromMenu:(id)sender
{
    NSString *title = [sender representedObject];
    if (!title || _selectedRow < 0 || (size_t)_selectedRow >= _state.rows.size()) return;
    std::string oldVariable = _state.rows[(size_t)_selectedRow].variable;
    std::string newVariable = std::string([title UTF8String]);
    if (oldVariable.empty() || newVariable.empty()) return;
    for (std::string &variable : _state.variables) {
        if (variable == oldVariable) {
            variable = newVariable;
            break;
        }
    }
    if (_state.linkEnabled && !_state.sourcePlotId.empty()) {
        [self propagateNestedContingencyToBarplot];
    } else {
        [self rebuildNestedContingencyFromSelection];
    }
}

- (void)removeRowVariableFromMenu:(id)sender
{
    (void)sender;
    std::string variable;
    if (_selectedRow >= 0 && (size_t)_selectedRow < _state.rows.size()) {
        variable = _state.rows[(size_t)_selectedRow].variable;
    }
    if (variable.empty() && !_state.variables.empty()) {
        variable = _state.variables.back();
    }
    if (variable.empty()) return;
    _state.variables.erase(std::remove(_state.variables.begin(), _state.variables.end(), variable), _state.variables.end());
    if (_state.variables.empty()) return;
    if (_state.linkEnabled && !_state.sourcePlotId.empty()) {
        [self propagateNestedContingencyToBarplot];
    } else {
        [self rebuildNestedContingencyFromSelection];
    }
}

- (void)setNestedDisplayModeFromMenu:(id)sender
{
    NSString *mode = [sender representedObject];
    if (!mode) return;
    _state.nestedDisplayMode = std::string([mode UTF8String]);
    [self rebuildNestedContingencyFromSelection];
}

- (NSMenu *)contextMenuForRow:(NSInteger)row
{
    if (_state.tableType == "compare_means") {
        NSMenu *menu = [[NSMenu alloc] initWithTitle:@"Test"];
        NSMenuItem *exportItem = [[NSMenuItem alloc] initWithTitle:@"Export" action:nil keyEquivalent:@""];
        NSMenu *exportMenu = [[NSMenu alloc] initWithTitle:@"Export"];
        AddStandardTableVisualExportItems(exportMenu, _reportView, ToNSString(_state.title),
            ToNSString(_state.id), ToNSString([self tableText]));
        [exportMenu addItem:[NSMenuItem separatorItem]];
        NSMenuItem *copy = [[NSMenuItem alloc] initWithTitle:@"Copy table with headers" action:@selector(copyTable:) keyEquivalent:@""];
        [copy setTarget:self]; [exportMenu addItem:copy];
        [exportMenu addItem:[NSMenuItem separatorItem]];
        NSMenuItem *csv = [[NSMenuItem alloc] initWithTitle:@"CSV…" action:@selector(exportCSV:) keyEquivalent:@""];
        [csv setTarget:self]; [exportMenu addItem:csv];
        NSMenuItem *apa = [[NSMenuItem alloc] initWithTitle:@"PDF — APA 7 style…" action:@selector(exportPDFAPA:) keyEquivalent:@""];
        [apa setTarget:self]; [exportMenu addItem:apa];
        NSMenuItem *displayed = [[NSMenuItem alloc] initWithTitle:@"PDF — As displayed…" action:@selector(exportPDF:) keyEquivalent:@""];
        [displayed setTarget:self]; [exportMenu addItem:displayed];
        [menu setSubmenu:exportMenu forItem:exportItem];
        [menu addItem:exportItem];
        AddSnapshotAlbumContextItems(menu);
        return menu;
    }
    if (_state.tableType == "nested_contingency") {
        NSMenu *menu = [[NSMenu alloc] initWithTitle:@"Nested Contingency Table"];
        NSMenuItem *refreshItem = [[NSMenuItem alloc] initWithTitle:@"Refresh from Bar Chart" action:@selector(refreshFromSource:) keyEquivalent:@""];
        [refreshItem setTarget:self];
        [refreshItem setEnabled:_state.linkEnabled && !_state.sourcePlotId.empty()];
        [menu addItem:refreshItem];
        [menu addItem:[NSMenuItem separatorItem]];

        DataFrameModel df;
        bool found = false;
        {
            std::lock_guard<std::mutex> lock(g_mutex);
            const DataFrameModel *current = FindDataFrameUnlockedConst(_state.datasetId);
            if (current) {
                df = *current;
                found = true;
            }
        }

        NSMenuItem *rowVarItem = [[NSMenuItem alloc] initWithTitle:@"Row Variables" action:nil keyEquivalent:@""];
        NSMenu *rowVarMenu = [[NSMenu alloc] initWithTitle:@"Row Variables"];
        NSMenuItem *addRow = [[NSMenuItem alloc] initWithTitle:@"Add Row Variable" action:nil keyEquivalent:@""];
        NSMenu *addRowMenu = [[NSMenu alloc] initWithTitle:@"Add Row Variable"];
        if (found) {
            for (const DataColumn &col : df.columns) {
                if (DataColumnLooksLikeId(col)) continue;
                if (std::find(_state.variables.begin(), _state.variables.end(), col.name) != _state.variables.end()) continue;
                if (col.name == _state.groupVariable) continue;
                NSMenuItem *item = [[NSMenuItem alloc] initWithTitle:ToNSString(col.name) action:@selector(addRowVariableFromMenu:) keyEquivalent:@""];
                [item setTarget:self];
                [item setRepresentedObject:ToNSString(col.name)];
                [addRowMenu addItem:item];
            }
        }
        if ([addRowMenu numberOfItems] == 0) {
            [addRowMenu addItem:[[NSMenuItem alloc] initWithTitle:@"(no available variables)" action:nil keyEquivalent:@""]];
        }
        [rowVarMenu setSubmenu:addRowMenu forItem:addRow];
        [rowVarMenu addItem:addRow];

        std::string selectedVariable;
        if (row >= 0 && (size_t)row < _state.rows.size()) {
            selectedVariable = _state.rows[(size_t)row].variable;
        }
        if (!selectedVariable.empty()) {
            NSMenuItem *replaceRow = [[NSMenuItem alloc] initWithTitle:@"Replace Row Variable" action:nil keyEquivalent:@""];
            NSMenu *replaceRowMenu = [[NSMenu alloc] initWithTitle:@"Replace Row Variable"];
            if (found) {
                for (const DataColumn &col : df.columns) {
                    if (DataColumnLooksLikeId(col)) continue;
                    if (col.name == selectedVariable) continue;
                    if (col.name == _state.groupVariable) continue;
                    NSMenuItem *item = [[NSMenuItem alloc] initWithTitle:ToNSString(col.name) action:@selector(replaceRowVariableFromMenu:) keyEquivalent:@""];
                    [item setTarget:self];
                    [item setRepresentedObject:ToNSString(col.name)];
                    [replaceRowMenu addItem:item];
                }
            }
            if ([replaceRowMenu numberOfItems] == 0) {
                [replaceRowMenu addItem:[[NSMenuItem alloc] initWithTitle:@"(no available variables)" action:nil keyEquivalent:@""]];
            }
            [rowVarMenu setSubmenu:replaceRowMenu forItem:replaceRow];
            [rowVarMenu addItem:replaceRow];

            if (_state.variables.size() > 1) {
                NSMenuItem *removeRow = [[NSMenuItem alloc] initWithTitle:ToNSString("Remove \u201c" + selectedVariable + "\u201d") action:@selector(removeRowVariableFromMenu:) keyEquivalent:@""];
                [removeRow setTarget:self];
                [rowVarMenu addItem:removeRow];
            }
        }

        [menu setSubmenu:rowVarMenu forItem:rowVarItem];
        [menu addItem:rowVarItem];

        NSMenuItem *colVarItem = [[NSMenuItem alloc] initWithTitle:@"Column (Split) Variable" action:nil keyEquivalent:@""];
        NSMenu *colVarMenu = [[NSMenu alloc] initWithTitle:@"Column (Split) Variable"];
        NSMenuItem *changeCol = [[NSMenuItem alloc] initWithTitle:@"Change Column Variable" action:nil keyEquivalent:@""];
        NSMenu *changeColMenu = [[NSMenu alloc] initWithTitle:@"Change Column Variable"];
        if (found) {
            bool addNoneOption = true;
            for (const DataColumn &col : df.columns) {
                if (DataColumnLooksLikeId(col)) continue;
                if (std::find(_state.variables.begin(), _state.variables.end(), col.name) != _state.variables.end()) continue;
                addNoneOption = false;
                NSMenuItem *item = [[NSMenuItem alloc] initWithTitle:ToNSString(col.name) action:@selector(changeSplitVariableFromMenu:) keyEquivalent:@""];
                [item setTarget:self];
                [item setRepresentedObject:ToNSString(col.name)];
                if (col.name == _state.groupVariable) [item setState:NSControlStateValueOn];
                [changeColMenu addItem:item];
            }
            if (addNoneOption) {
                [changeColMenu addItem:[[NSMenuItem alloc] initWithTitle:@"(no available variables)" action:nil keyEquivalent:@""]];
            }
        }
        [colVarMenu setSubmenu:changeColMenu forItem:changeCol];
        [colVarMenu addItem:changeCol];

        if (!_state.groupVariable.empty()) {
            NSMenuItem *clearCol = [[NSMenuItem alloc] initWithTitle:@"No Column Split" action:@selector(changeSplitVariableFromMenu:) keyEquivalent:@""];
            [clearCol setTarget:self];
            [clearCol setRepresentedObject:ToNSString(std::string(""))];
            [colVarMenu addItem:clearCol];
        }

        [menu setSubmenu:colVarMenu forItem:colVarItem];
        [menu addItem:colVarItem];

        [menu addItem:[NSMenuItem separatorItem]];
        NSMenuItem *displayItem = [[NSMenuItem alloc] initWithTitle:@"Cell contents" action:nil keyEquivalent:@""];
        NSMenu *displayMenu = [[NSMenu alloc] initWithTitle:@"Cell contents"];
        {
            struct { NSString *title; NSString *mode; } modes[] = {
                {@"Counts and Percentages", @"count_percent"},
                {@"Counts Only", @"count"},
                {@"Percentages Only", @"percent"},
            };
            for (size_t mi = 0; mi < sizeof(modes) / sizeof(modes[0]); ++mi) {
                NSMenuItem *item = [[NSMenuItem alloc] initWithTitle:modes[mi].title action:@selector(setNestedDisplayModeFromMenu:) keyEquivalent:@""];
                [item setTarget:self];
                [item setRepresentedObject:modes[mi].mode];
                if (_state.nestedDisplayMode == std::string([modes[mi].mode UTF8String])) {
                    [item setState:NSControlStateValueOn];
                }
                [displayMenu addItem:item];
            }
        }
        [menu setSubmenu:displayMenu forItem:displayItem];
        [menu addItem:displayItem];
        [menu addItem:[NSMenuItem separatorItem]];
        NSMenuItem *exportItem = [[NSMenuItem alloc] initWithTitle:@"Export" action:nil keyEquivalent:@""];
        NSMenu *exportMenu = [[NSMenu alloc] initWithTitle:@"Export"];
        AddStandardTableVisualExportItems(exportMenu, _reportView, ToNSString(_state.title),
            ToNSString(_state.id), ToNSString([self tableText]));
        [exportMenu addItem:[NSMenuItem separatorItem]];
        NSMenuItem *copy = [[NSMenuItem alloc] initWithTitle:@"Copy table with headers" action:@selector(copyTable:) keyEquivalent:@""];
        [copy setTarget:self];
        [exportMenu addItem:copy];
        [exportMenu addItem:[NSMenuItem separatorItem]];
        NSMenuItem *csv = [[NSMenuItem alloc] initWithTitle:@"CSV\u2026" action:@selector(exportCSV:) keyEquivalent:@""];
        [csv setTarget:self];
        [exportMenu addItem:csv];
        NSMenuItem *apa = [[NSMenuItem alloc] initWithTitle:@"PDF — APA 7 style…" action:@selector(exportPDFAPA:) keyEquivalent:@""];
        [apa setTarget:self]; [exportMenu addItem:apa];
        NSMenuItem *pdf = [[NSMenuItem alloc] initWithTitle:@"PDF — As displayed…" action:@selector(exportPDF:) keyEquivalent:@""];
        [pdf setTarget:self]; [exportMenu addItem:pdf];
        [menu setSubmenu:exportMenu forItem:exportItem];
        [menu addItem:exportItem];
        AddSnapshotAlbumContextItems(menu);
        return menu;
    }

    const auto titles = rlispstat::core::DefaultTable1ContextMenuTitles();
    NSMenu *menu = [[NSMenu alloc] initWithTitle:ToNSString(titles.root)];
    NSMenuItem *exportItem = [[NSMenuItem alloc] initWithTitle:ToNSString(titles.exportMenu) action:nil keyEquivalent:@""];
    NSMenu *exportMenu = [[NSMenu alloc] initWithTitle:ToNSString(titles.exportMenu)];
    AddStandardTableVisualExportItems(exportMenu, _reportView, ToNSString(_state.title),
        ToNSString(_state.id), ToNSString([self tableText]));
    [exportMenu addItem:[NSMenuItem separatorItem]];
    NSMenuItem *copy = [[NSMenuItem alloc] initWithTitle:ToNSString(titles.copyTable) action:@selector(copyTable:) keyEquivalent:@""];
    [copy setTarget:self];
    [exportMenu addItem:copy];
    [exportMenu addItem:[NSMenuItem separatorItem]];
    NSMenuItem *csv = [[NSMenuItem alloc] initWithTitle:ToNSString(titles.exportCSV) action:@selector(exportCSV:) keyEquivalent:@""];
    [csv setTarget:self];
    [exportMenu addItem:csv];
    NSMenuItem *markdown = [[NSMenuItem alloc] initWithTitle:ToNSString(titles.exportMarkdown) action:@selector(exportMarkdown:) keyEquivalent:@""];
    [markdown setTarget:self];
    [exportMenu addItem:markdown];
    NSMenuItem *apa = [[NSMenuItem alloc] initWithTitle:@"PDF — APA 7 style…" action:@selector(exportPDFAPA:) keyEquivalent:@""];
    [apa setTarget:self]; [exportMenu addItem:apa];
    NSMenuItem *pdf = [[NSMenuItem alloc] initWithTitle:@"PDF — As displayed…" action:@selector(exportPDF:) keyEquivalent:@""];
    [pdf setTarget:self]; [exportMenu addItem:pdf];
    [menu setSubmenu:exportMenu forItem:exportItem];
    [menu addItem:exportItem];
    [menu addItem:[NSMenuItem separatorItem]];

    NSMenuItem *add = [[NSMenuItem alloc] initWithTitle:ToNSString(titles.addVariable) action:nil keyEquivalent:@""];
    NSMenu *addMenu = [[NSMenu alloc] initWithTitle:ToNSString(titles.addVariable)];
    DataFrameModel df;
    bool found = false;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        const DataFrameModel *current = FindDataFrameUnlockedConst(_state.datasetId);
        if (current) {
            df = *current;
            found = true;
        }
    }
    if (found) {
        for (const DataColumn &col : df.columns) {
            if (DataColumnLooksLikeId(col) || col.name == _state.groupVariable) continue;
            if (std::find(_state.variables.begin(), _state.variables.end(), col.name) != _state.variables.end()) continue;
            NSMenuItem *item = [[NSMenuItem alloc] initWithTitle:ToNSString(col.name) action:@selector(addVariableFromMenu:) keyEquivalent:@""];
            [item setTarget:self];
            [item setRepresentedObject:ToNSString(col.name)];
            [addMenu addItem:item];
        }
    }
    if ([addMenu numberOfItems] == 0) [addMenu addItem:[[NSMenuItem alloc] initWithTitle:ToNSString(titles.noAvailableVariables) action:nil keyEquivalent:@""]];
    [menu setSubmenu:addMenu forItem:add];
    [menu addItem:add];

    std::string variable;
    if (row >= 0 && (size_t)row < _state.rows.size()) variable = _state.rows[(size_t)row].variable;
    if (!variable.empty()) {
        NSMenuItem *change = [[NSMenuItem alloc] initWithTitle:ToNSString(titles.changeVariable) action:nil keyEquivalent:@""];
        NSMenu *changeMenu = [[NSMenu alloc] initWithTitle:ToNSString(titles.changeVariable)];
        if (found) {
            for (const DataColumn &col : df.columns) {
                if (DataColumnLooksLikeId(col) || col.name == _state.groupVariable || col.name == variable) continue;
                NSMenuItem *item = [[NSMenuItem alloc] initWithTitle:ToNSString(col.name) action:@selector(replaceVariableFromMenu:) keyEquivalent:@""];
                [item setTarget:self];
                [item setRepresentedObject:ToNSString(col.name)];
                [changeMenu addItem:item];
            }
        }
        if ([changeMenu numberOfItems] == 0) [changeMenu addItem:[[NSMenuItem alloc] initWithTitle:ToNSString(titles.noAvailableVariables) action:nil keyEquivalent:@""]];
        [menu setSubmenu:changeMenu forItem:change];
        [menu addItem:change];
        NSMenuItem *remove = [[NSMenuItem alloc] initWithTitle:ToNSString(rlispstat::core::Table1RemoveVariableTitle(variable)) action:@selector(removeSelectedVariable:) keyEquivalent:@""];
        [remove setTarget:self];
        [menu addItem:remove];
        [menu addItem:[NSMenuItem separatorItem]];
        for (const char *type : {"numeric", "categorical", "ordinal"}) {
            NSMenuItem *item = [[NSMenuItem alloc] initWithTitle:ToNSString(rlispstat::core::Table1TypeMenuTitle(type)) action:@selector(typeMenuSelected:) keyEquivalent:@""];
            [item setTarget:self];
            [item setRepresentedObject:@[ToNSString(variable), ToNSString(std::string(type))]];
            if (_state.variableTypes[variable] == type) [item setState:NSControlStateValueOn];
            [menu addItem:item];
        }
        [menu addItem:[[NSMenuItem alloc] initWithTitle:ToNSString(titles.showVariableInformation) action:nil keyEquivalent:@""]];
        [menu addItem:[NSMenuItem separatorItem]];
        NSMenuItem *hist = [[NSMenuItem alloc] initWithTitle:ToNSString(rlispstat::core::Table1HistogramMenuTitle(variable)) action:@selector(openHistogram:) keyEquivalent:@""];
        [hist setTarget:self];
        [menu addItem:hist];
        NSMenuItem *bar = [[NSMenuItem alloc] initWithTitle:ToNSString(rlispstat::core::Table1BarChartMenuTitle(variable)) action:@selector(openBarplot:) keyEquivalent:@""];
        [bar setTarget:self];
        [menu addItem:bar];
        NSMenuItem *box = [[NSMenuItem alloc] initWithTitle:ToNSString(rlispstat::core::Table1BoxplotMenuTitle(variable, _state.groupVariable)) action:@selector(openBoxplot:) keyEquivalent:@""];
        [box setTarget:self];
        [menu addItem:box];
    }

    NSMenuItem *group = [[NSMenuItem alloc] initWithTitle:ToNSString(titles.groupingVariable) action:nil keyEquivalent:@""];
    NSMenu *groupMenu = [[NSMenu alloc] initWithTitle:ToNSString(titles.groupingVariable)];
    NSMenuItem *clear = [[NSMenuItem alloc] initWithTitle:ToNSString(titles.clearGroupingVariable) action:@selector(clearGroup:) keyEquivalent:@""];
    [clear setTarget:self];
    [groupMenu addItem:clear];
    [groupMenu addItem:[NSMenuItem separatorItem]];
    if (found) {
        for (const DataColumn &col : df.columns) {
            if (DataColumnLooksLikeId(col)) continue;
            NSMenuItem *item = [[NSMenuItem alloc] initWithTitle:ToNSString(col.name) action:@selector(setGroupFromMenu:) keyEquivalent:@""];
            [item setTarget:self];
            [item setRepresentedObject:ToNSString(col.name)];
            if (col.name == _state.groupVariable) [item setState:NSControlStateValueOn];
            [groupMenu addItem:item];
        }
    }
    [menu setSubmenu:groupMenu forItem:group];
    [menu addItem:[NSMenuItem separatorItem]];
    [menu addItem:group];
    return menu;
}

- (void)show
{
    EnableNotesForWindow(_window, _tableId, @"this statistical table");
    [_window makeKeyAndOrderFront:nil];
    [NSApp activateIgnoringOtherApps:YES];
}

- (BOOL)isVisible
{
    return [_window isVisible];
}

- (NSWindow *)getWindow
{
    return _window;
}

- (void)windowWillClose:(NSNotification *)notification
{
    (void)notification;
    g_table1Controllers.erase(_tableId);
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        auto it = g_linkedTableSources.find(_tableId);
        if (it != g_linkedTableSources.end()) {
            std::string plotId = it->second;
            g_linkedTables[plotId].erase(_tableId);
            if (g_linkedTables[plotId].empty()) g_linkedTables.erase(plotId);
            g_linkedTableSources.erase(it);
        }
    }
}

@end

static std::map<std::string, NativeMixedModelState> &g_nativeMixedModels =
    MacCommandDispatcher().applicationState().nativeMixedModels();

static bool RunNativeMixedModelReport(const NativeMixedModelState &state, std::string *report, std::string *message);

struct MixedModelHitRegion {
    NSRect rect;
    std::string action;
    std::string value;
};

@protocol MixedModelReportActionTarget <NSObject>
- (void)mixedModelAction:(NSString *)action value:(NSString *)value atPoint:(NSPoint)point inView:(NSView *)view;
- (NSMenu *)mixedModelContextMenuForAction:(NSString *)action value:(NSString *)value;
@end

@interface MixedModelReportView : NSView {
    MixedModelReportState _state;
    std::vector<MixedModelHitRegion> _hitRegions;
    id<MixedModelReportActionTarget> _controller;
    NSPopUpButton *_dependentPopup;
}
- (instancetype)initWithFrame:(NSRect)frameRect state:(const MixedModelReportState &)state;
- (void)updateState:(const MixedModelReportState &)state;
- (CGFloat)contentHeightForWidth:(CGFloat)width;
- (NSString *)rawText;
- (void)setController:(id<MixedModelReportActionTarget>)controller;
- (void)configureResponseCandidates:(const std::vector<std::string> &)candidates
                           selected:(const std::string &)selected
                             target:(id)target
                             action:(SEL)action;
@end

@implementation MixedModelReportView
- (NSString *)snapshotTabDelimitedText { return [self rawText]; }
- (BOOL)isFlipped { return YES; }

- (instancetype)initWithFrame:(NSRect)frameRect state:(const MixedModelReportState &)state
{
    self = [super initWithFrame:frameRect];
    if (self) {
        _state = state;
        [self setWantsLayer:YES];
        // Use the same native response selector as the General Linear Model.
        // Keeping this as a real control also gives us the standard keyboard,
        // accessibility and menu behaviour instead of imitating a popup in
        // drawRect:.
        _dependentPopup = [[NSPopUpButton alloc] initWithFrame:NSMakeRect(140.0, 35.0, 148.0, 28.0)];
        [self addSubview:_dependentPopup];
    }
    return self;
}

- (void)setController:(id<MixedModelReportActionTarget>)controller
{
    _controller = controller;
}

- (void)configureResponseCandidates:(const std::vector<std::string> &)candidates
                           selected:(const std::string &)selected
                             target:(id)target
                             action:(SEL)action
{
    [_dependentPopup removeAllItems];
    for (const std::string &candidate : candidates) {
        [_dependentPopup addItemWithTitle:ToNSString(candidate)];
    }
    if (!selected.empty()) [_dependentPopup selectItemWithTitle:ToNSString(selected)];
    [_dependentPopup setTarget:target];
    [_dependentPopup setAction:action];
    [_dependentPopup setEnabled:[_dependentPopup numberOfItems] > 0];
}

- (NSString *)rawText { return ToNSString(_state.rawText); }

- (NSDictionary *)attrsWithSize:(CGFloat)size weight:(NSFontWeight)weight color:(NSColor *)color
{
    return @{ NSFontAttributeName: [NSFont systemFontOfSize:size weight:weight],
              NSForegroundColorAttributeName: color };
}

- (CGFloat)contentHeightForWidth:(CGFloat)width
{
    CGFloat h = 12.0 + 24.0; // title
    h += 28.0;               // controls
    h += 24.0;               // formula and selected-row status

    const std::vector<std::pair<std::string, std::string>> fitItems = MixedModelFitSummaryItems(_state);
    const size_t fitColumns = width >= 700.0 ? 4 : (width >= 540.0 ? 3 : 2);
    const size_t fitRows = fitItems.empty() ? 1 : (fitItems.size() + fitColumns - 1) / fitColumns;
    h += 20.0 + (CGFloat)fitRows * 20.0 + 10.0;

    for (const char *title : {"Fixed effects", "Random effects", "Warnings"}) {
        const MixedModelReportSection *section = FindMixedModelReportSection(_state, title);
        if (!section) continue;
        h += 20.0 + (CGFloat)std::max<size_t>(1, section->rows.size()) * 20.0;
        if (section->title == "Fixed effects" || section->title == "Random effects") h += 20.0;
        h += 6.0;
    }
    h += 24.0; // status
    return std::max((CGFloat)380.0, h + 10.0);
}

- (void)updateState:(const MixedModelReportState &)state
{
    _state = state;
    CGFloat h = [self contentHeightForWidth:[self bounds].size.width];
    [self setFrameSize:NSMakeSize([self bounds].size.width, h)];
    [self setNeedsDisplay:YES];
}

- (void)drawText:(NSString *)text rect:(NSRect)rect attrs:(NSDictionary *)attrs right:(BOOL)right
{
    NSMutableParagraphStyle *style = [[NSMutableParagraphStyle alloc] init];
    [style setAlignment:right ? NSTextAlignmentRight : NSTextAlignmentLeft];
    NSMutableDictionary *drawAttrs = [attrs mutableCopy];
    [drawAttrs setObject:style forKey:NSParagraphStyleAttributeName];
    [text drawInRect:rect withAttributes:drawAttrs];
}

- (void)addHitRect:(NSRect)rect action:(const std::string &)action value:(const std::string &)value
{
    MixedModelHitRegion hit;
    hit.rect = rect;
    hit.action = action;
    hit.value = value;
    _hitRegions.push_back(hit);
}

- (NSInteger)hitIndexAtPoint:(NSPoint)point
{
    for (NSInteger i = (NSInteger)_hitRegions.size() - 1; i >= 0; --i) {
        if (NSPointInRect(point, _hitRegions[(size_t)i].rect)) return i;
    }
    return -1;
}

- (BOOL)rowLooksLikeFixedEffect:(const std::string &)value
{
    if (value.empty() || value == "(Intercept)") return NO;
    auto it = g_nativeMixedModels.find(_state.id);
    if (it == g_nativeMixedModels.end()) return YES;
    for (const std::string &term : it->second.fixedEffects) {
        if (value == term || value.find(term) == 0 || value.find("factor(" + term + ")") == 0) return YES;
    }
    return NO;
}

- (void)drawRect:(NSRect)dirtyRect
{
    (void)dirtyRect;
    _hitRegions.clear();
    [WorkbenchSurfaceColor() setFill];
    NSRectFill([self bounds]);
    CGFloat width = [self bounds].size.width;
    CGFloat margin = 14.0;
    CGFloat avail = std::max((CGFloat)160.0, width - 2.0 * margin);
    CGFloat y = 12.0;
    NSDictionary *titleAttrs = [self attrsWithSize:16 weight:NSFontWeightSemibold color:[NSColor colorWithCalibratedWhite:0.12 alpha:1.0]];
    NSDictionary *labelAttrs = [self attrsWithSize:12 weight:NSFontWeightRegular color:[NSColor colorWithCalibratedWhite:0.16 alpha:1.0]];
    NSDictionary *smallAttrs = [self attrsWithSize:11 weight:NSFontWeightRegular color:[NSColor colorWithCalibratedWhite:0.34 alpha:1.0]];
    NSDictionary *sectionAttrs = [self attrsWithSize:12 weight:NSFontWeightSemibold color:[NSColor colorWithCalibratedWhite:0.18 alpha:1.0]];
    NSDictionary *headerAttrs = [self attrsWithSize:12 weight:NSFontWeightSemibold color:[NSColor colorWithCalibratedWhite:0.20 alpha:1.0]];
    NSDictionary *cellAttrs = [self attrsWithSize:12 weight:NSFontWeightRegular color:[NSColor colorWithCalibratedWhite:0.14 alpha:1.0]];
    NSDictionary *warnAttrs = [self attrsWithSize:12 weight:NSFontWeightRegular color:[NSColor colorWithCalibratedRed:0.56 green:0.14 blue:0.10 alpha:1.0]];

    [self drawText:ToNSString(_state.title) rect:NSMakeRect(margin, y, avail * 0.62, 22) attrs:titleAttrs right:NO];
    const std::string badge = !_state.dataset.empty() ? _state.dataset : _state.group;
    [self drawText:ToNSString(badge) rect:NSMakeRect(margin + avail * 0.62, y + 2, avail * 0.38, 18) attrs:smallAttrs right:YES];
    y += 26.0;

    [self drawText:@"Response variable" rect:NSMakeRect(margin, y + 2.0, 126.0, 18.0) attrs:labelAttrs right:NO];
    [_dependentPopup setFrame:NSMakeRect(margin + 126.0, y - 3.0, 148.0, 28.0)];
    CGFloat controlX = margin + 290.0;

    std::string scopeValue = _state.scope.empty() ? "all" : _state.scope;
    std::string scopeDisplay = scopeValue == "all" ? "All data" : (scopeValue == "selected" ? "Selected rows" : scopeValue);
    [self drawText:@"Scope:" rect:NSMakeRect(controlX, y + 2.0, 43.0, 18.0) attrs:labelAttrs right:NO];
    controlX += 45.0;
    CGFloat scopeW = std::min((CGFloat)116.0, std::max((CGFloat)94.0, avail * 0.15));
    NSRect scopeRect = NSMakeRect(controlX, y, scopeW, 22.0);
    [[NSColor colorWithCalibratedWhite:0.975 alpha:1.0] setFill];
    [[NSBezierPath bezierPathWithRoundedRect:scopeRect xRadius:5.0 yRadius:5.0] fill];
    [[NSColor colorWithCalibratedWhite:0.86 alpha:1.0] setStroke];
    NSBezierPath *scopeBorder = [NSBezierPath bezierPathWithRoundedRect:NSInsetRect(scopeRect, 0.5, 0.5) xRadius:5.0 yRadius:5.0];
    [scopeBorder setLineWidth:0.7];
    [scopeBorder stroke];
    [self drawText:ToNSString(scopeDisplay) rect:NSInsetRect(scopeRect, 8.0, 3.0) attrs:smallAttrs right:NO];
    controlX = NSMaxX(scopeRect) + 20.0;
    if (!_state.estimation.empty()) {
        [self drawText:ToNSString("Estimation: " + _state.estimation) rect:NSMakeRect(controlX, y + 2.0, 150.0, 18.0) attrs:labelAttrs right:NO];
    } else if (!_state.family.empty()) {
        std::string familyText = "Family: " + _state.family;
        if (!_state.link.empty()) familyText += "/" + _state.link;
        [self drawText:ToNSString(familyText) rect:NSMakeRect(controlX, y + 2.0, 180.0, 18.0) attrs:labelAttrs right:NO];
    }
    y += 28.0;

    std::string formula = _state.formula;
    formula.erase(std::remove(formula.begin(), formula.end(), '`'), formula.end());
    if (!formula.empty()) {
        [self drawText:ToNSString("Formula: " + formula) rect:NSMakeRect(margin, y, avail * 0.68, 18.0) attrs:smallAttrs right:NO];
    }
    const size_t totalRows = RowCountForGroup(_state.group);
    if (totalRows > 0) {
        [self drawText:ToNSString(SelectedRowsStatus(SelectionCount(_state.group), totalRows))
                   rect:NSMakeRect(margin + avail * 0.68, y, avail * 0.32, 18.0)
                  attrs:smallAttrs
                  right:YES];
    }
    y += 24.0;

    [self drawText:@"Global fit" rect:NSMakeRect(margin, y, avail, 18.0) attrs:sectionAttrs right:NO];
    y += 20.0;
    const std::vector<std::pair<std::string, std::string>> fitItems = MixedModelFitSummaryItems(_state);
    const size_t fitColumns = width >= 700.0 ? 4 : (width >= 540.0 ? 3 : 2);
    CGFloat fitW = avail / (CGFloat)fitColumns;
    for (size_t i = 0; i < fitItems.size(); ++i) {
        const size_t row = i / fitColumns;
        const size_t col = i % fitColumns;
        NSString *label = ToNSString(fitItems[i].first + " ");
        CGFloat labelW = std::min(fitW * 0.62, [label sizeWithAttributes:sectionAttrs].width + 2.0);
        CGFloat itemX = margin + (CGFloat)col * fitW;
        CGFloat itemY = y + (CGFloat)row * 20.0;
        [self drawText:label rect:NSMakeRect(itemX, itemY, labelW, 18.0) attrs:sectionAttrs right:NO];
        [self drawText:ToNSString(fitItems[i].second) rect:NSMakeRect(itemX + labelW, itemY, fitW - labelW - 8.0, 18.0) attrs:labelAttrs right:NO];
    }
    const size_t fitRows = fitItems.empty() ? 1 : (fitItems.size() + fitColumns - 1) / fitColumns;
    y += (CGFloat)fitRows * 20.0 + 2.0;
    [[NSColor colorWithCalibratedWhite:0.88 alpha:1.0] setStroke];
    NSBezierPath *fitRule = [NSBezierPath bezierPath];
    [fitRule moveToPoint:NSMakePoint(margin, y)];
    [fitRule lineToPoint:NSMakePoint(margin + avail, y)];
    [fitRule setLineWidth:0.7];
    [fitRule stroke];
    y += 10.0;

    for (const char *sectionTitle : {"Fixed effects", "Random effects", "Warnings"}) {
        const MixedModelReportSection *sectionPtr = FindMixedModelReportSection(_state, sectionTitle);
        if (!sectionPtr) continue;
        const MixedModelReportSection &section = *sectionPtr;
        [self drawText:ToNSString(section.title) rect:NSMakeRect(margin, y, avail, 18) attrs:sectionAttrs right:NO];
        y += 20.0;
        size_t colCount = 1;
        for (const auto &row : section.rows) colCount = std::max(colCount, row.size());
        std::vector<CGFloat> colX(colCount, margin), colW(colCount, avail);
        BOOL twoColumnLayout = (colCount == 2);
        if (colCount > 1) {
            std::vector<CGFloat> fractions;
            if (section.title == "Fixed effects") {
                fractions = colCount == 7
                    ? std::vector<CGFloat>{0.29, 0.14, 0.12, 0.12, 0.10, 0.10, 0.13}
                    : std::vector<CGFloat>{0.32, 0.15, 0.13, 0.13, 0.12, 0.15};
            } else if (section.title == "Random effects" && colCount == 5) {
                fractions = {0.24, 0.24, 0.18, 0.18, 0.16};
            } else if (twoColumnLayout) {
                fractions = {0.50, 0.50};
            }
            if (fractions.size() == colCount) {
                CGFloat nextX = margin;
                for (size_t c = 0; c < colCount; ++c) {
                    colX[c] = nextX;
                    colW[c] = avail * fractions[c];
                    nextX += colW[c];
                }
            } else {
                CGFloat firstW = std::min((CGFloat)180.0, avail * 0.30);
                CGFloat restW = (avail - firstW) / (CGFloat)(colCount - 1);
                colX[0] = margin; colW[0] = firstW;
                for (size_t c = 1; c < colCount; ++c) {
                    colX[c] = margin + firstW + restW * (CGFloat)(c - 1);
                    colW[c] = restW;
                }
            }
        }
        for (size_t r = 0; r < section.rows.size(); ++r) {
            const std::vector<std::string> &row = section.rows[r];
            BOOL header = r == 0 && section.title != "Warnings";
            NSDictionary *attrs = section.title == "Warnings" ? warnAttrs : (header ? headerAttrs : cellAttrs);
            CGFloat rowY = y;
            for (size_t c = 0; c < row.size(); ++c) {
                [self drawText:ToNSString(row[c])
                           rect:NSMakeRect(colX[c], y, colW[c] - 8.0, 18)
                          attrs:attrs
                          right:((section.title == "Fixed effects" && c >= 2) ||
                                 (section.title == "Random effects" && c >= 2))];
            }
            if (!header && !row.empty()) {
                if (section.title == "Fixed effects" && [self rowLooksLikeFixedEffect:row[0]]) {
                    [self addHitRect:NSMakeRect(colX[0], rowY - 1.0, colW[0] - 4.0, 21.0) action:"fixed" value:row[0]];
                } else if (section.title == "Random effects" && row[0] != "Residual") {
                    [self addHitRect:NSMakeRect(colX[0], rowY - 1.0, colW[0] - 4.0, 21.0) action:"random" value:row[0]];
                }
            }
            y += 20.0;
            if (header) {
                [[NSColor colorWithCalibratedWhite:0.88 alpha:1.0] setStroke];
                NSBezierPath *rule = [NSBezierPath bezierPath];
                [rule moveToPoint:NSMakePoint(margin, y - 3.0)];
                [rule lineToPoint:NSMakePoint(margin + avail, y - 3.0)];
                [rule setLineWidth:0.7];
                [rule stroke];
            }
        }
        if (section.title == "Fixed effects") {
            NSRect addRect = NSMakeRect(margin, y, std::min((CGFloat)180.0, avail), 20.0);
            [self drawText:ToNSString(rlispstat::core::MixedModelAddFixedEffectDrawLabel()) rect:addRect attrs:labelAttrs right:NO];
            [self addHitRect:NSInsetRect(addRect, -3.0, -2.0) action:"add_fixed" value:""];
            y += 20.0;
        } else if (section.title == "Random effects") {
            NSRect addRect = NSMakeRect(margin, y, std::min((CGFloat)190.0, avail), 20.0);
            [self drawText:ToNSString(rlispstat::core::MixedModelAddRandomEffectDrawLabel()) rect:addRect attrs:labelAttrs right:NO];
            [self addHitRect:NSInsetRect(addRect, -3.0, -2.0) action:"add_random" value:""];
            y += 20.0;
        }
        y += 6.0;
    }

    [self drawText:ToNSString(MixedModelReportStatusLine(_state))
               rect:NSMakeRect(margin, y, avail, 22.0)
              attrs:smallAttrs
              right:NO];
}

- (NSMenu *)menuForEvent:(NSEvent *)event
{
    NSPoint point = [self convertPoint:[event locationInWindow] fromView:nil];
    NSInteger hit = [self hitIndexAtPoint:point];
    if (hit >= 0 && _controller && [_controller respondsToSelector:@selector(mixedModelContextMenuForAction:value:)]) {
        const MixedModelHitRegion &region = _hitRegions[(size_t)hit];
        NSMenu *menu = [_controller mixedModelContextMenuForAction:ToNSString(region.action) value:ToNSString(region.value)];
        if (menu) return SnapshotAlbumMenu(menu, @"Mixed Model");
    }
    NSMenu *menu = [[NSMenu alloc] initWithTitle:ToNSString(rlispstat::core::MixedModelWindowTitle())];
    NSMenuItem *exportRoot = [[NSMenuItem alloc] initWithTitle:@"Export" action:nil keyEquivalent:@""];
    NSMenu *exportMenu = [[NSMenu alloc] initWithTitle:@"Export"];
    AddStandardTableVisualExportItems(exportMenu, self, ToNSString(_state.title),
        ToNSString(_state.id.empty() ? "mixed-model" : _state.id), [self rawText]);
    [exportMenu addItem:[NSMenuItem separatorItem]];
    NSMenuItem *copy = [[NSMenuItem alloc] initWithTitle:ToNSString(rlispstat::core::MixedModelCopyTableTitle()) action:@selector(copyReport:) keyEquivalent:@""];
    [copy setTarget:self];
    [exportMenu addItem:copy];
    [exportRoot setSubmenu:exportMenu];
    [menu addItem:exportRoot];
    AddSnapshotAlbumContextItems(menu);
    return menu;
}

- (void)copyReport:(id)sender
{
    (void)sender;
    NSPasteboard *pasteboard = [NSPasteboard generalPasteboard];
    [pasteboard clearContents];
    [pasteboard setString:[self rawText] forType:NSPasteboardTypeString];
}

- (void)mouseDown:(NSEvent *)event
{
    NSPoint point = [self convertPoint:[event locationInWindow] fromView:nil];
    NSInteger hit = [self hitIndexAtPoint:point];
    if (hit >= 0 && _controller && [_controller respondsToSelector:@selector(mixedModelAction:value:atPoint:inView:)]) {
        const MixedModelHitRegion &region = _hitRegions[(size_t)hit];
        [_controller mixedModelAction:ToNSString(region.action)
                                value:ToNSString(region.value)
                              atPoint:point
                               inView:self];
        return;
    }
    [super mouseDown:event];
}
@end

@interface MixedModelWindowController : NSObject <NSWindowDelegate, MixedModelReportActionTarget> {
    NSWindow *_window;
    NSScrollView *_scrollView;
    MixedModelReportView *_reportView;
    MixedModelReportState _state;
    BOOL _hasSizedToContent;
}
- (instancetype)initWithState:(const MixedModelReportState &)state;
- (void)updateState:(const MixedModelReportState &)state;
- (void)show;
- (void)sizeToReportIfReady;
- (void)mixedModelAction:(NSString *)action value:(NSString *)value atPoint:(NSPoint)point inView:(NSView *)view;
- (NSMenu *)mixedModelContextMenuForAction:(NSString *)action value:(NSString *)value;
- (void)mixedDependentChanged:(id)sender;
- (void)applyMixedResponse:(NSString *)name;
@end

@implementation MixedModelWindowController
- (instancetype)initWithState:(const MixedModelReportState &)state
{
    self = [super init];
    if (self) {
        _state = state;
        _hasSizedToContent = NO;
        _window = [[NSWindow alloc]
            initWithContentRect:NSMakeRect(220, 170, 720, 440)
                      styleMask:(NSWindowStyleMaskTitled | NSWindowStyleMaskClosable |
                                 NSWindowStyleMaskMiniaturizable | NSWindowStyleMaskResizable)
                        backing:NSBackingStoreBuffered
                          defer:NO];
        [_window setTitle:ToNSString(_state.title)];
        [_window setMinSize:NSMakeSize(720, 380)];
        [_window setDelegate:self];
        NSView *content = [_window contentView];
        [content setWantsLayer:YES];
        [[content layer] setBackgroundColor:[WorkbenchSurfaceColor() CGColor]];
        _scrollView = [[NSScrollView alloc] initWithFrame:[content bounds]];
        [_scrollView setAutoresizingMask:NSViewWidthSizable | NSViewHeightSizable];
        [_scrollView setBorderType:NSNoBorder];
        [_scrollView setDrawsBackground:NO];
        [_scrollView setHasVerticalScroller:YES];
        [_scrollView setAutohidesScrollers:YES];
        [content addSubview:_scrollView];
        _reportView = [[MixedModelReportView alloc] initWithFrame:NSMakeRect(0, 0, 720, 440) state:_state];
        [_reportView setController:self];
        [_reportView configureResponseCandidates:[self responseCandidates]
                                         selected:_state.response
                                           target:self
                                           action:@selector(mixedDependentChanged:)];
        [_reportView updateState:_state];
        [_scrollView setDocumentView:_reportView];
        [self sizeToReportIfReady];
    }
    return self;
}

- (void)updateState:(const MixedModelReportState &)state
{
    _state = state;
    [_window setTitle:ToNSString(_state.title)];
    [_reportView configureResponseCandidates:[self responseCandidates]
                                     selected:_state.response
                                       target:self
                                       action:@selector(mixedDependentChanged:)];
    [_reportView updateState:_state];
    [self sizeToReportIfReady];
}

- (void)sizeToReportIfReady
{
    if (_hasSizedToContent || MixedModelFitSummaryItems(_state).empty()) return;
    const CGFloat width = std::max((CGFloat)720.0, [[_window contentView] bounds].size.width);
    const CGFloat reportHeight = [_reportView contentHeightForWidth:width];
    const CGFloat height = std::min((CGFloat)620.0, std::max((CGFloat)380.0, reportHeight));
    [_window setContentSize:NSMakeSize(width, height)];
    [_reportView setFrameSize:NSMakeSize(width, reportHeight)];
    _hasSizedToContent = YES;
}

- (void)show
{
    EnableNotesForWindow(_window, _state.id, @"this mixed model result");
    [_window orderFront:nil];
    [NSApp activateIgnoringOtherApps:YES];
}

- (NativeMixedModelState *)nativeState
{
    auto it = g_nativeMixedModels.find(_state.id);
    return it == g_nativeMixedModels.end() ? nullptr : &it->second;
}

- (DataFrameModel)dataFrame
{
    std::lock_guard<std::mutex> lock(g_mutex);
    const DataFrameModel *df = FindDataFrameUnlockedConst(_state.group);
    return df ? *df : DataFrameModel();
}

- (BOOL)isRandomGroup:(const std::string &)name state:(const NativeMixedModelState *)state
{
    if (!state) return NO;
    for (const NativeMixedRandomSpec &spec : state->randomEffects) {
        if (spec.group == name) return YES;
    }
    return NO;
}

- (std::string)fixedTermForDisplayValue:(const std::string &)value
{
    NativeMixedModelState *state = [self nativeState];
    if (!state) return value;
    std::string normalized = value;
    normalized.erase(std::remove(normalized.begin(), normalized.end(), '`'), normalized.end());
    for (const std::string &term : state->fixedEffects) {
        if (normalized == term || normalized.find(term) == 0 || normalized.find("factor(" + term + ")") == 0) {
            return term;
        }
    }
    return value;
}

- (std::vector<std::string>)responseCandidates
{
    std::vector<std::string> out;
    NativeMixedModelState *state = [self nativeState];
    DataFrameModel df = [self dataFrame];
    bool generalized = state && state->modelType == "generalized_linear_mixed_model";
    for (const DataColumn &col : df.columns) {
        if (DataColumnLooksLikeId(col) || DataColumnAllMissing(col)) continue;
        if ([self isRandomGroup:col.name state:state]) continue;
        if (generalized) {
            if (col.type == "numeric" || DataColumnLooksBinaryNumeric(col)) out.push_back(col.name);
        } else if (col.type == "numeric") {
            out.push_back(col.name);
        }
    }
    return out;
}

- (std::vector<std::string>)fixedEffectCandidatesAllowing:(const std::string &)current
{
    std::vector<std::string> out;
    NativeMixedModelState *state = [self nativeState];
    DataFrameModel df = [self dataFrame];
    for (const DataColumn &col : df.columns) {
        if (DataColumnLooksLikeId(col) || DataColumnAllMissing(col) || DataColumnObservedLevelCount(col) < 2) continue;
        if (state && col.name == state->response) continue;
        if ([self isRandomGroup:col.name state:state]) continue;
        if (state && col.name != current &&
            std::find(state->fixedEffects.begin(), state->fixedEffects.end(), col.name) != state->fixedEffects.end()) {
            continue;
        }
        out.push_back(col.name);
    }
    return out;
}

- (std::vector<std::string>)randomGroupCandidatesAllowing:(const std::string &)current
{
    std::vector<std::string> out;
    NativeMixedModelState *state = [self nativeState];
    DataFrameModel df = [self dataFrame];
    for (const DataColumn &col : df.columns) {
        if (state && col.name == state->response) continue;
        if (!DataColumnLooksGroupingCandidate(col, df.rows)) continue;
        if (state && col.name != current && [self isRandomGroup:col.name state:state]) continue;
        out.push_back(col.name);
    }
    return out;
}

- (NSMenuItem *)mixedMenuItem:(NSString *)title action:(SEL)action represented:(id)represented
{
    NSMenuItem *item = [[NSMenuItem alloc] initWithTitle:title action:action keyEquivalent:@""];
    [item setTarget:self];
    if (represented) [item setRepresentedObject:represented];
    return item;
}

- (void)addDisabledItem:(NSString *)title toMenu:(NSMenu *)menu
{
    NSMenuItem *item = [[NSMenuItem alloc] initWithTitle:title action:nil keyEquivalent:@""];
    [item setEnabled:NO];
    [menu addItem:item];
}

- (void)refitAndRefresh
{
    NativeMixedModelState *state = [self nativeState];
    if (!state) {
        ShowWorkbenchMessageOnMain(ToNSString(rlispstat::core::MixedModelWindowTitle()), ToNSString(rlispstat::core::MixedModelNoNativeStateStatus()));
        return;
    }
    std::string report;
    std::string message;
    if (!RunNativeMixedModelReport(*state, &report, &message)) {
        ShowWorkbenchMessageOnMain(ToNSString(rlispstat::core::MixedModelWindowTitle()), ToNSString(message));
        return;
    }
    state->reportText = report;
    MixedModelReportState parsed = ParseMixedModelReport(state->id, state->group, state->modelType, report);
    [self updateState:parsed];
}

- (NSMenu *)responseMenu
{
    NSMenu *menu = [[NSMenu alloc] initWithTitle:ToNSString(rlispstat::core::MixedModelResponseMenuTitle())];
    NativeMixedModelState *state = [self nativeState];
    std::vector<std::string> candidates = [self responseCandidates];
    for (const std::string &name : candidates) {
        NSMenuItem *item = [self mixedMenuItem:ToNSString(name) action:@selector(setMixedResponseFromMenu:) represented:ToNSString(name)];
        if (state && name == state->response) [item setState:NSControlStateValueOn];
        [menu addItem:item];
    }
    if ([menu numberOfItems] == 0) [self addDisabledItem:ToNSString(rlispstat::core::MixedModelNoAvailableResponseVariablesLabel()) toMenu:menu];
    return menu;
}

- (NSMenu *)addFixedEffectMenu
{
    NSMenu *menu = [[NSMenu alloc] initWithTitle:ToNSString(rlispstat::core::MixedModelAddFixedEffectTitle())];
    std::vector<std::string> candidates = [self fixedEffectCandidatesAllowing:""];
    for (const std::string &name : candidates) {
        [menu addItem:[self mixedMenuItem:ToNSString(name) action:@selector(addMixedFixedEffectFromMenu:) represented:ToNSString(name)]];
    }
    if ([menu numberOfItems] == 0) [self addDisabledItem:ToNSString(rlispstat::core::MixedModelNoAvailableFixedEffectsLabel()) toMenu:menu];
    return menu;
}

- (NSMenu *)fixedEffectMenuForValue:(NSString *)value
{
    std::string rawValue = value ? std::string([value UTF8String]) : std::string();
    std::string term = [self fixedTermForDisplayValue:rawValue];
    NSMenu *menu = [[NSMenu alloc] initWithTitle:ToNSString(rlispstat::core::MixedModelFixedEffectTitle())];
    NSMenuItem *change = [[NSMenuItem alloc] initWithTitle:ToNSString(rlispstat::core::MixedModelChangeFixedEffectTitle()) action:nil keyEquivalent:@""];
    NSMenu *changeMenu = [[NSMenu alloc] initWithTitle:ToNSString(rlispstat::core::MixedModelChangeFixedEffectMenuTitle())];
    for (const std::string &name : [self fixedEffectCandidatesAllowing:term]) {
        if (name == term) continue;
        [changeMenu addItem:[self mixedMenuItem:ToNSString(name)
                                         action:@selector(replaceMixedFixedEffectFromMenu:)
                                    represented:@[ToNSString(term), ToNSString(name)]]];
    }
    if ([changeMenu numberOfItems] == 0) [self addDisabledItem:ToNSString(rlispstat::core::MixedModelNoAvailableReplacementsLabel()) toMenu:changeMenu];
    [menu setSubmenu:changeMenu forItem:change];
    [menu addItem:change];
    [menu addItem:[self mixedMenuItem:ToNSString("Remove " + term) action:@selector(removeMixedFixedEffectFromMenu:) represented:ToNSString(term)]];
    return menu;
}

- (NSMenu *)addRandomEffectMenu
{
    NSMenu *menu = [[NSMenu alloc] initWithTitle:ToNSString(rlispstat::core::MixedModelAddRandomEffectTitle())];
    for (const std::string &name : [self randomGroupCandidatesAllowing:""]) {
        [menu addItem:[self mixedMenuItem:ToNSString(name) action:@selector(addMixedRandomEffectFromMenu:) represented:ToNSString(name)]];
    }
    if ([menu numberOfItems] == 0) [self addDisabledItem:ToNSString(rlispstat::core::MixedModelNoAvailableGroupingVariablesLabel()) toMenu:menu];
    return menu;
}

- (NativeMixedRandomSpec *)randomSpecForGroup:(const std::string &)group
{
    NativeMixedModelState *state = [self nativeState];
    if (!state) return nullptr;
    for (NativeMixedRandomSpec &spec : state->randomEffects) {
        if (spec.group == group) return &spec;
    }
    return nullptr;
}

- (NSMenu *)randomEffectMenuForValue:(NSString *)value
{
    std::string group = value ? std::string([value UTF8String]) : "";
    NSMenu *menu = [[NSMenu alloc] initWithTitle:ToNSString(rlispstat::core::MixedModelRandomEffectTitle())];
    NSMenuItem *change = [[NSMenuItem alloc] initWithTitle:ToNSString(rlispstat::core::MixedModelChangeGroupingVariableTitle()) action:nil keyEquivalent:@""];
    NSMenu *changeMenu = [[NSMenu alloc] initWithTitle:ToNSString(rlispstat::core::MixedModelChangeGroupingVariableMenuTitle())];
    for (const std::string &name : [self randomGroupCandidatesAllowing:group]) {
        if (name == group) continue;
        [changeMenu addItem:[self mixedMenuItem:ToNSString(name)
                                         action:@selector(replaceMixedRandomGroupFromMenu:)
                                    represented:@[ToNSString(group), ToNSString(name)]]];
    }
    if ([changeMenu numberOfItems] == 0) [self addDisabledItem:ToNSString(rlispstat::core::MixedModelNoAvailableReplacementsLabel()) toMenu:changeMenu];
    [menu setSubmenu:changeMenu forItem:change];
    [menu addItem:change];

    NativeMixedRandomSpec *spec = [self randomSpecForGroup:group];
    NSMenuItem *slope = [[NSMenuItem alloc] initWithTitle:ToNSString(rlispstat::core::MixedModelAddRandomSlopeTitle()) action:nil keyEquivalent:@""];
    NSMenu *slopeMenu = [[NSMenu alloc] initWithTitle:ToNSString(rlispstat::core::MixedModelAddRandomSlopeTitle())];
    if (spec) {
        for (const std::string &name : [self fixedEffectCandidatesAllowing:""]) {
            if (name == group) continue;
            if (std::find(spec->terms.begin(), spec->terms.end(), name) != spec->terms.end()) continue;
            [slopeMenu addItem:[self mixedMenuItem:ToNSString(name)
                                            action:@selector(addMixedRandomSlopeFromMenu:)
                                       represented:@[ToNSString(group), ToNSString(name)]]];
        }
    }
    if ([slopeMenu numberOfItems] == 0) [self addDisabledItem:ToNSString(rlispstat::core::MixedModelNoAvailableRandomSlopesLabel()) toMenu:slopeMenu];
    [menu setSubmenu:slopeMenu forItem:slope];
    [menu addItem:slope];

    if (spec) {
        NSMenuItem *removeSlope = [[NSMenuItem alloc] initWithTitle:ToNSString(rlispstat::core::MixedModelRemoveRandomSlopeTitle()) action:nil keyEquivalent:@""];
        NSMenu *removeSlopeMenu = [[NSMenu alloc] initWithTitle:ToNSString(rlispstat::core::MixedModelRemoveRandomSlopeMenuTitle())];
        for (const std::string &term : spec->terms) {
            if (term == "1") continue;
            [removeSlopeMenu addItem:[self mixedMenuItem:ToNSString(term)
                                                  action:@selector(removeMixedRandomSlopeFromMenu:)
                                             represented:@[ToNSString(group), ToNSString(term)]]];
        }
        if ([removeSlopeMenu numberOfItems] == 0) [self addDisabledItem:ToNSString(rlispstat::core::MixedModelNoRandomSlopesToRemoveLabel()) toMenu:removeSlopeMenu];
        [menu setSubmenu:removeSlopeMenu forItem:removeSlope];
        [menu addItem:removeSlope];
    }

    [menu addItem:[NSMenuItem separatorItem]];
    [menu addItem:[self mixedMenuItem:ToNSString("Remove random effect for " + group)
                                action:@selector(removeMixedRandomEffectFromMenu:)
                           represented:ToNSString(group)]];
    return menu;
}

- (NSMenu *)mixedModelContextMenuForAction:(NSString *)action value:(NSString *)value
{
    if ([action isEqualToString:@"response"]) return [self responseMenu];
    if ([action isEqualToString:@"add_fixed"]) return [self addFixedEffectMenu];
    if ([action isEqualToString:@"fixed"]) return [self fixedEffectMenuForValue:value];
    if ([action isEqualToString:@"add_random"]) return [self addRandomEffectMenu];
    if ([action isEqualToString:@"random"]) return [self randomEffectMenuForValue:value];
    return nil;
}

- (void)mixedModelAction:(NSString *)action value:(NSString *)value atPoint:(NSPoint)point inView:(NSView *)view
{
    NSMenu *menu = [self mixedModelContextMenuForAction:action value:value];
    if (menu) {
        AddSnapshotAlbumContextItems(menu);
        [menu popUpMenuPositioningItem:nil atLocation:point inView:view];
    }
}

- (void)setMixedResponseFromMenu:(id)sender
{
    NSString *name = [sender representedObject];
    [self applyMixedResponse:name];
}

- (void)mixedDependentChanged:(id)sender
{
    NSString *name = [sender isKindOfClass:[NSPopUpButton class]]
        ? [(NSPopUpButton *)sender titleOfSelectedItem]
        : nil;
    [self applyMixedResponse:name];
}

- (void)applyMixedResponse:(NSString *)name
{
    NativeMixedModelState *state = [self nativeState];
    if (!name || !state) return;
    state->response = std::string([name UTF8String]);
    state->fixedEffects.erase(std::remove(state->fixedEffects.begin(), state->fixedEffects.end(), state->response), state->fixedEffects.end());
    for (NativeMixedRandomSpec &spec : state->randomEffects) {
        spec.terms.erase(std::remove(spec.terms.begin(), spec.terms.end(), state->response), spec.terms.end());
        if (spec.terms.empty()) spec.terms.push_back("1");
    }
    [self refitAndRefresh];
}

- (void)addMixedFixedEffectFromMenu:(id)sender
{
    NSString *name = [sender representedObject];
    NativeMixedModelState *state = [self nativeState];
    if (!name || !state) return;
    std::string term = std::string([name UTF8String]);
    if (term == state->response) return;
    if (std::find(state->fixedEffects.begin(), state->fixedEffects.end(), term) == state->fixedEffects.end()) {
        state->fixedEffects.push_back(term);
        [self refitAndRefresh];
    }
}

- (void)replaceMixedFixedEffectFromMenu:(id)sender
{
    NSArray *payload = [sender representedObject];
    if (![payload isKindOfClass:[NSArray class]] || [payload count] < 2) return;
    NSString *oldName = [payload objectAtIndex:0];
    NSString *newName = [payload objectAtIndex:1];
    NativeMixedModelState *state = [self nativeState];
    if (!oldName || !newName || !state) return;
    std::string oldTerm = std::string([oldName UTF8String]);
    std::string newTerm = std::string([newName UTF8String]);
    for (std::string &term : state->fixedEffects) {
        if (term == oldTerm) {
            term = newTerm;
            break;
        }
    }
    std::vector<std::string> uniqueTerms;
    for (const std::string &term : state->fixedEffects) {
        if (std::find(uniqueTerms.begin(), uniqueTerms.end(), term) == uniqueTerms.end()) uniqueTerms.push_back(term);
    }
    state->fixedEffects = uniqueTerms;
    [self refitAndRefresh];
}

- (void)removeMixedFixedEffectFromMenu:(id)sender
{
    NSString *name = [sender representedObject];
    NativeMixedModelState *state = [self nativeState];
    if (!name || !state) return;
    std::string term = std::string([name UTF8String]);
    state->fixedEffects.erase(std::remove(state->fixedEffects.begin(), state->fixedEffects.end(), term), state->fixedEffects.end());
    [self refitAndRefresh];
}

- (void)addMixedRandomEffectFromMenu:(id)sender
{
    NSString *name = [sender representedObject];
    NativeMixedModelState *state = [self nativeState];
    if (!name || !state) return;
    NativeMixedRandomSpec spec;
    spec.group = std::string([name UTF8String]);
    spec.terms.push_back("1");
    spec.covariance = "|";
    state->randomEffects.push_back(spec);
    [self refitAndRefresh];
}

- (void)replaceMixedRandomGroupFromMenu:(id)sender
{
    NSArray *payload = [sender representedObject];
    if (![payload isKindOfClass:[NSArray class]] || [payload count] < 2) return;
    NSString *oldName = [payload objectAtIndex:0];
    NSString *newName = [payload objectAtIndex:1];
    NativeMixedModelState *state = [self nativeState];
    if (!oldName || !newName || !state) return;
    std::string oldGroup = std::string([oldName UTF8String]);
    std::string newGroup = std::string([newName UTF8String]);
    for (NativeMixedRandomSpec &spec : state->randomEffects) {
        if (spec.group == oldGroup) {
            spec.group = newGroup;
            break;
        }
    }
    [self refitAndRefresh];
}

- (void)removeMixedRandomEffectFromMenu:(id)sender
{
    NSString *name = [sender representedObject];
    NativeMixedModelState *state = [self nativeState];
    if (!name || !state) return;
    if (state->randomEffects.size() <= 1) {
        ShowWorkbenchMessageOnMain(ToNSString(rlispstat::core::MixedModelWindowTitle()), ToNSString(rlispstat::core::MixedModelRequiresRandomEffectStatus()));
        return;
    }
    std::string group = std::string([name UTF8String]);
    state->randomEffects.erase(std::remove_if(state->randomEffects.begin(), state->randomEffects.end(),
        [&](const NativeMixedRandomSpec &spec) { return spec.group == group; }), state->randomEffects.end());
    [self refitAndRefresh];
}

- (void)addMixedRandomSlopeFromMenu:(id)sender
{
    NSArray *payload = [sender representedObject];
    if (![payload isKindOfClass:[NSArray class]] || [payload count] < 2) return;
    NSString *groupName = [payload objectAtIndex:0];
    NSString *termName = [payload objectAtIndex:1];
    if (!groupName || !termName) return;
    NativeMixedRandomSpec *spec = [self randomSpecForGroup:std::string([groupName UTF8String])];
    if (!spec) return;
    std::string term = std::string([termName UTF8String]);
    if (std::find(spec->terms.begin(), spec->terms.end(), term) == spec->terms.end()) {
        spec->terms.push_back(term);
        [self refitAndRefresh];
    }
}

- (void)removeMixedRandomSlopeFromMenu:(id)sender
{
    NSArray *payload = [sender representedObject];
    if (![payload isKindOfClass:[NSArray class]] || [payload count] < 2) return;
    NSString *groupName = [payload objectAtIndex:0];
    NSString *termName = [payload objectAtIndex:1];
    if (!groupName || !termName) return;
    NativeMixedRandomSpec *spec = [self randomSpecForGroup:std::string([groupName UTF8String])];
    if (!spec) return;
    std::string term = std::string([termName UTF8String]);
    spec->terms.erase(std::remove(spec->terms.begin(), spec->terms.end(), term), spec->terms.end());
    if (spec->terms.empty()) spec->terms.push_back("1");
    [self refitAndRefresh];
}

- (void)windowWillClose:(NSNotification *)notification
{
    (void)notification;
    g_mixedModelControllers.erase(_state.id);
}
@end

static void ShowTable1StateOnMain(const Table1DisplayState &state)
{
    Table1DisplayState stateCopy = state;
    if (!stateCopy.dataScopeCaptured && !stateCopy.datasetId.empty()) {
        std::lock_guard<std::mutex> lock(g_mutex);
        auto existing = g_table1Controllers.find(stateCopy.id);
        if (existing != g_table1Controllers.end() && [existing->second state]->dataScopeCaptured) {
            stateCopy.dataScope = [existing->second state]->dataScope;
            stateCopy.dataScopeCaptured = true;
        } else {
            CaptureActiveAnalysisScopeUnlocked(
                stateCopy.datasetId, stateCopy.dataScope, stateCopy.dataScopeCaptured);
        }
    }
    void (^showBlock)(void) = ^{
      Table1WindowController *controller = nil;
      {
          std::lock_guard<std::mutex> lock(g_mutex);
          auto it = g_table1Controllers.find(stateCopy.id);
          if (it != g_table1Controllers.end()) {
              controller = it->second;
          }
      }
      if (!controller) {
          controller = [[Table1WindowController alloc] initWithState:stateCopy];
          std::lock_guard<std::mutex> lock(g_mutex);
          g_table1Controllers[stateCopy.id] = controller;
      } else {
          [controller updateState:stateCopy];
      }
      [controller show];
    };
    if ([NSThread isMainThread]) {
        showBlock();
    } else {
        dispatch_sync(dispatch_get_main_queue(), showBlock);
    }
}

