static void ShowCompareMeansOnMain(PlotModel *model, const std::string &testType, const std::string &var1,
                                   const std::string &var2, const std::string &groupVar)
{
    model = ActiveDatasetCommandModel(model);
    NSString *title = ToNSString(CompareMeansTitle(testType));
    if (!model) {
        ShowWorkbenchMessageOnMain(title, ToNSString(NoActiveDatasetImportOrRegisterStatus()));
        return;
    }
    bool found = false;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        const DataFrameModel *current = FindDataFrameUnlockedConst(model->group);
        if (current) {
            found = true;
        }
    }
    if (!found) {
        ShowWorkbenchMessageOnMain(title, ToNSString(ActiveDatasetUnavailableStatus()));
        return;
    }
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        g_pendingCompareMeansTasks.push_back({model->group, testType, var1, var2, groupVar});
    }
    NotifyMainRTaskAvailable();
}

static void ShowEditableCompareMeansOnMain(PlotModel *model, const std::string &testType)
{
    model = ActiveDatasetCommandModel(model);
    if (!model) {
        ShowWorkbenchMessageOnMain(ToNSString(CompareMeansTitle(testType)),
                                   ToNSString(NoActiveDatasetImportOrRegisterStatus()));
        return;
    }
    DataFrameModel df;
    bool foundDataset = false;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        const DataFrameModel *current = FindDataFrameUnlockedConst(model->group);
        if (current) { df = *current; foundDataset = true; }
    }
    if (!foundDataset) {
        ShowWorkbenchMessageOnMain(ToNSString(CompareMeansTitle(testType)),
                                   ToNSString(ActiveDatasetUnavailableStatus()));
        return;
    }

    MeanComparisonState state;
    state.id = "cm_batch_" + std::to_string((long long)time(nullptr)) + "_" + std::to_string((long long)arc4random_uniform(1000000));
    state.datasetId = df.group; state.title = CompareMeansTitle(testType); state.confidenceLevel = 0.95;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        CaptureActiveAnalysisScopeUnlocked(state.datasetId, state.dataScope, state.dataScopeCaptured);
    }
    state.alternative = "two.sided"; state.specification.confidenceLevel = 0.95;
    state.specification.pAdjustment = rlispstat::core::MultipleTestingAdjustment::Holm;
    const std::vector<std::string> numeric = MeanComparisonNumericVariables(df);
    if (testType == "one_sample_t") {
        state.analysisType = "one_sample_t_test"; state.specification.kind = rlispstat::core::MeanComparisonKind::OneSample;
        state.specification.method = rlispstat::core::MeanComparisonMethod::OneSampleT;
        if (!numeric.empty()) state.specification.dependentVariableIds.push_back(numeric.front());
        state.subtitle = "Test value: 0 · Alternative: two-sided · Confidence level: 95%";
    } else if (testType == "paired_t") {
        state.analysisType = "paired_samples_t_test"; state.specification.kind = rlispstat::core::MeanComparisonKind::PairedSamples;
        state.specification.method = rlispstat::core::MeanComparisonMethod::OneSampleT;
        if (numeric.size() >= 2) state.specification.pairs.push_back({"pair:" + numeric[0] + "\x1f" + numeric[1], numeric[0], numeric[1]});
        state.subtitle = "Differences: first variable − second variable · Alternative: two-sided · Confidence level: 95%";
    } else {
        const bool independent = testType == "independent_t";
        state.analysisType = independent ? "independent_samples_t_test" : "one_way_anova";
        state.specification.kind = independent ? rlispstat::core::MeanComparisonKind::IndependentSamples : rlispstat::core::MeanComparisonKind::OneWayAnova;
        state.specification.method = independent ? rlispstat::core::MeanComparisonMethod::WelchT : rlispstat::core::MeanComparisonMethod::WelchAnova;
        if (!numeric.empty()) state.specification.dependentVariableIds.push_back(numeric.front());
        for (const DataColumn &column : df.columns) {
            if (!MeanComparisonGroupingCandidate(column, independent)) continue;
            if (!numeric.empty() && column.name == numeric.front()) continue;
            state.specification.groupingVariableId = column.name; state.groupVariable = column.name;
            state.specification.groupOrderIds = MeanComparisonEffectiveLevels(column); break;
        }
        state.method = independent ? "Welch" : "Welch one-way ANOVA";
        state.subtitle = state.groupVariable.empty() ? "Choose a grouping variable from the context menu."
            : "Grouping variable: " + state.groupVariable + " · " + state.method;
    }
    ShowMeanComparisonStateOnMain(state);
    const bool ready = (state.analysisType == "paired_samples_t_test" ? !state.specification.pairs.empty() : !state.specification.dependentVariableIds.empty()) &&
        ((state.analysisType != "independent_samples_t_test" && state.analysisType != "one_way_anova") || state.specification.groupingVariableId.has_value());
    if (ready) {
        MainRCompareMeansTask task = MeanComparisonTaskForState(state);
        {
            std::lock_guard<std::mutex> lock(g_mutex); g_pendingCompareMeansTasks.push_back(std::move(task));
        }
        NotifyMainRTaskAvailable();
    }
}

static void ShowNewTable1OnMain(PlotModel *model)
{
    model = ActiveDatasetCommandModel(model);
    if (!model) {
        ShowWorkbenchMessageOnMain(ToNSString(rlispstat::core::Table1WindowTitle()), ToNSString(NoActiveDatasetImportOrRegisterStatus()));
        return;
    }
    DataFrameModel df;
    bool found = false;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        const DataFrameModel *current = FindDataFrameUnlockedConst(model->group);
        if (current) {
            df = *current;
            found = true;
        }
    }
    if (!found) {
        ShowWorkbenchMessageOnMain(ToNSString(rlispstat::core::Table1WindowTitle()), ToNSString(ActiveDatasetUnavailableStatus()));
        return;
    }
    if (df.datasetType == "multiple_imputation") {
        std::thread worker([df]() {
            std::string message;
            bool ok = RunRBackedMultipleImputationAnalysis(
                df, "table1",
                "table1_" + df.group + "_" + std::to_string((long long)time(nullptr)),
                std::vector<std::string>(), "", "", std::vector<std::string>(), "all", &message);
            if (!ok) ShowWorkbenchMessageOnMain(ToNSString(rlispstat::core::Table1WindowTitle()), ToNSString(message));
        });
        worker.detach();
        return;
    }
    std::string id = "table1_" + df.group + "_" + std::to_string((long long)time(nullptr));
    rlispstat::core::AnalysisScope dataScope;
    bool dataScopeCaptured = false;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        CaptureActiveAnalysisScopeUnlocked(df.group, dataScope, dataScopeCaptured);
    }
    ShowTable1StateOnMain(rlispstat::core::Table1StateForDataFrame(
        df, id, std::vector<std::string>(), "", std::map<std::string, std::string>(),
        dataScopeCaptured ? &dataScope : nullptr));
}

static const DataColumn *Table1FindColumn(const DataFrameModel &df, const std::string &name)
{
    return FindDataColumnInDataFrame(df, name);
}

static bool DataFrameForContextModel(PlotModel *model, DataFrameModel &df)
{
    model = ActiveDatasetCommandModel(model);
    if (!model) {
        return false;
    }
    std::lock_guard<std::mutex> lock(g_mutex);
    const DataFrameModel *found = FindDataFrameUnlockedConst(model->group);
    if (!found) {
        return false;
    }
    df = *found;
    return true;
}

static void ShowTable1ForVariablesOnMain(PlotModel *model,
                                         const std::vector<std::string> &variables,
                                         const std::string &groupVariable,
                                         const std::string &title)
{
    DataFrameModel df;
    if (!DataFrameForContextModel(model, df)) {
        ShowWorkbenchMessageOnMain(ToNSString(rlispstat::core::DescriptiveStatisticsWindowTitle()), ToNSString(rlispstat::core::DatasetForPlotNotAvailableStatus()));
        return;
    }
    if (df.datasetType == "multiple_imputation") {
        std::vector<std::string> vars = variables;
        std::string grouping = groupVariable;
        std::thread worker([df, vars, grouping]() {
            std::string message;
            bool ok = RunRBackedMultipleImputationAnalysis(
                df, "table1",
                "context_table_" + df.group + "_" + std::to_string((long long)time(nullptr)),
                vars, grouping, "", std::vector<std::string>(), "all", &message);
            if (!ok) ShowWorkbenchMessageOnMain(ToNSString(rlispstat::core::DescriptiveStatisticsWindowTitle()), ToNSString(message));
        });
        worker.detach();
        return;
    }
    std::vector<std::string> kept;
    for (const std::string &name : variables) {
        if (name.empty() || name == groupVariable || !Table1FindColumn(df, name)) continue;
        if (std::find(kept.begin(), kept.end(), name) == kept.end()) {
            kept.push_back(name);
        }
    }
    std::string grouping = groupVariable;
    if (!grouping.empty() && !Table1FindColumn(df, grouping)) {
        grouping.clear();
    }
    if (kept.empty()) {
        ShowWorkbenchMessageOnMain(ToNSString(rlispstat::core::DescriptiveStatisticsWindowTitle()), ToNSString(rlispstat::core::NoVariablesToSummarizeStatus()));
        return;
    }
    std::string id = "context_table_" + df.group + "_" + std::to_string((long long)time(nullptr));
    rlispstat::core::AnalysisScope dataScope;
    bool dataScopeCaptured = false;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        CaptureActiveAnalysisScopeUnlocked(df.group, dataScope, dataScopeCaptured);
    }
    Table1DisplayState state = rlispstat::core::Table1StateForDataFrame(
        df, id, kept, grouping, std::map<std::string, std::string>(),
        dataScopeCaptured ? &dataScope : nullptr);
    if (!title.empty()) {
        state.title = title;
    }
    ShowTable1StateOnMain(state);
}

static void ShowFrequencyTableForVariableOnMain(PlotModel *model, const std::string &variable)
{
    DataFrameModel df;
    if (!DataFrameForContextModel(model, df)) {
        ShowWorkbenchMessageOnMain(ToNSString(rlispstat::core::FrequencyTableWindowTitle()), ToNSString(rlispstat::core::DatasetForPlotNotAvailableStatus()));
        return;
    }
    if (df.datasetType == "multiple_imputation") {
        std::vector<std::string> vars = {variable};
        std::thread worker([df, vars]() {
            std::string message;
            bool ok = RunRBackedMultipleImputationAnalysis(
                df, "table1",
                "freq_table_" + df.group + "_" + std::to_string((long long)time(nullptr)),
                vars, "", "", std::vector<std::string>(), "all", &message);
            if (!ok) ShowWorkbenchMessageOnMain(ToNSString(rlispstat::core::FrequencyTableWindowTitle()), ToNSString(message));
        });
        worker.detach();
        return;
    }
    const DataColumn *col = Table1FindColumn(df, variable);
    if (!col) {
        ShowWorkbenchMessageOnMain(ToNSString(rlispstat::core::FrequencyTableWindowTitle()), ToNSString(rlispstat::core::VariableForPlotNotAvailableStatus()));
        return;
    }
    std::vector<std::string> levels;
    std::map<std::string, int> counts;
    int missing = 0;
    rlispstat::core::AnalysisScope dataScope;
    bool dataScopeCaptured = false;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        CaptureActiveAnalysisScopeUnlocked(df.group, dataScope, dataScopeCaptured);
    }
    std::set<int> includedRows;
    if (dataScopeCaptured && dataScope.kind == rlispstat::core::AnalysisScopeKind::ExplicitRowIds) {
        const std::vector<int> rows = RowsForCapturedAnalysisScope(dataScope, true);
        includedRows.insert(rows.begin(), rows.end());
    }
    for (size_t i = 0; i < col->values.size(); ++i) {
        if (dataScopeCaptured && dataScope.kind == rlispstat::core::AnalysisScopeKind::ExplicitRowIds &&
            !includedRows.count(static_cast<int>(i) + 1)) continue;
        std::string value = DisplayValueForCell(*col, i);
        if (DataCellIsMissing(value)) {
            ++missing;
            continue;
        }
        if (counts.find(value) == counts.end()) {
            levels.push_back(value);
        }
        counts[value]++;
    }
    int valid = 0;
    for (const auto &entry : counts) valid += entry.second;
    Table1DisplayState state;
    state.id = "frequency_" + df.group + "_" + variable + "_" + std::to_string((long long)time(nullptr));
    state.datasetId = df.group;
    state.title = "Frequency table: " + variable;
    state.nativeGenerated = true;
    state.dataScope = dataScope;
    state.dataScopeCaptured = dataScopeCaptured;
    state.columns = {"n", "%"};

    Table1DisplayRow validRow;
    validRow.rowType = "n";
    validRow.label = "Valid N";
    validRow.values = {std::to_string(valid), FormatPercent(valid > 0 ? 1.0 : NAN, 1)};
    state.rows.push_back(validRow);

    for (const std::string &level : levels) {
        int n = counts[level];
        Table1DisplayRow row;
        row.rowType = "frequency_level";
        row.variable = variable;
        row.level = level;
        row.label = level;
        row.values = {std::to_string(n), FormatPercent(valid > 0 ? (double)n / (double)valid : NAN, 1)};
        state.rows.push_back(row);
    }
    Table1DisplayRow missingRow;
    missingRow.rowType = "missing";
    missingRow.variable = variable;
    missingRow.label = "Missing";
    const int scopedN = dataScopeCaptured && dataScope.kind == rlispstat::core::AnalysisScopeKind::ExplicitRowIds
        ? static_cast<int>(includedRows.size()) : df.rows;
    missingRow.values = {std::to_string(missing), FormatPercent(scopedN > 0 ? (double)missing / (double)scopedN : NAN, 1)};
    state.rows.push_back(missingRow);
    state.footnotes.push_back("Percentages for levels use valid, non-missing cases as denominator.");
    ShowTable1StateOnMain(state);
}

static void ShowContingencyTableResultOnMain(const DataFrameModel &df,
                                             const std::vector<std::string> &rowVariables,
                                             const std::string &columnVariable,
                                             const std::string &sourcePlotId)
{
    if (rowVariables.empty() || columnVariable.empty()) return;
    if (df.datasetType == "multiple_imputation") {
        ShowWorkbenchMessageOnMain(@"Contingency Table",
                                   @"Contingency tables are not supported for multiple-imputation datasets.");
        return;
    }
    std::string id = "contingency_" + df.group + "_" + std::to_string((long long)time(nullptr));
    rlispstat::core::AnalysisScope dataScope;
    bool dataScopeCaptured = false;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        CaptureActiveAnalysisScopeUnlocked(df.group, dataScope, dataScopeCaptured);
    }
    Table1DisplayState state = rlispstat::core::NestedContingencyTableStateForDataFrame(
        df, id, rowVariables, columnVariable, "count_percent",
        dataScopeCaptured ? &dataScope : nullptr);
    state.datasetId = df.group;
    state.linkEnabled = true;
    state.sourcePlotId = sourcePlotId;
    std::string rowLabel;
    for (const std::string &variable : rowVariables) {
        if (!rowLabel.empty()) rowLabel += " \u00d7 ";
        rowLabel += variable;
    }
    state.title = "Contingency Table \u2014 " + rowLabel + " by " + columnVariable;
    const std::string tableId = state.id;
    ShowTable1StateOnMain(state);
    if (!sourcePlotId.empty()) {
        dispatch_async(dispatch_get_main_queue(), ^{
            std::lock_guard<std::mutex> lock(g_mutex);
            g_linkedTables[sourcePlotId].insert(tableId);
            g_linkedTableSources[tableId] = sourcePlotId;
        });
    }
}

static void ShowContingencyTableDialogOnMain(PlotModel *model,
                                             const std::string &preferredRow,
                                             const std::string &preferredColumn)
{
    model = ActiveDatasetCommandModel(model);
    DataFrameModel df;
    if (!DataFrameForContextModel(model, df)) {
        ShowWorkbenchMessageOnMain(@"Contingency Table", ToNSString(ActiveDatasetUnavailableStatus()));
        return;
    }
    std::vector<std::string> variables;
    for (const DataColumn &column : df.columns) {
        if (!DataColumnLooksLikeId(column)) variables.push_back(column.name);
    }
    if (variables.size() < 2) {
        ShowWorkbenchMessageOnMain(@"Contingency Table", @"At least two categorical variables are required.");
        return;
    }
    NSAlert *alert = [[NSAlert alloc] init];
    [alert setMessageText:@"Contingency Table"];
    [alert setInformativeText:@"Choose different row and column variables."];
    [alert addButtonWithTitle:@"Run"];
    [alert addButtonWithTitle:ToNSString(rlispstat::core::AlertCancelButtonTitle())];
    NSView *accessory = [[NSView alloc] initWithFrame:NSMakeRect(0, 0, 350, 76)];
    [accessory addSubview:GLMLabel(@"Row variable:", NSMakeRect(0, 46, 100, 22), 12, NSFontWeightRegular)];
    [accessory addSubview:GLMLabel(@"Column variable:", NSMakeRect(0, 12, 100, 22), 12, NSFontWeightRegular)];
    NSPopUpButton *rowPopup = [[NSPopUpButton alloc] initWithFrame:NSMakeRect(108, 42, 220, 28)];
    NSPopUpButton *columnPopup = [[NSPopUpButton alloc] initWithFrame:NSMakeRect(108, 8, 220, 28)];
    for (const std::string &variable : variables) {
        [rowPopup addItemWithTitle:ToNSString(variable)];
        [columnPopup addItemWithTitle:ToNSString(variable)];
    }
    if (!preferredRow.empty()) [rowPopup selectItemWithTitle:ToNSString(preferredRow)];
    if (!preferredColumn.empty()) [columnPopup selectItemWithTitle:ToNSString(preferredColumn)];
    if ([[rowPopup titleOfSelectedItem] isEqualToString:[columnPopup titleOfSelectedItem]]) {
        [columnPopup selectItemAtIndex:MIN((NSInteger)1, [columnPopup numberOfItems] - 1)];
    }
    [accessory addSubview:rowPopup];
    [accessory addSubview:columnPopup];
    [alert setAccessoryView:accessory];
    while ([alert runModal] == NSAlertFirstButtonReturn) {
        std::string row = std::string([[rowPopup titleOfSelectedItem] UTF8String]);
        std::string column = std::string([[columnPopup titleOfSelectedItem] UTF8String]);
        if (row != column) {
            ShowContingencyTableResultOnMain(df, {row}, column, "");
            return;
        }
        [alert setInformativeText:@"Row variable and column variable must be different."];
    }
}

static void ShowNestedContingencyTableOnMain(PlotModel *model)
{
    DataFrameModel df;
    if (!DataFrameForContextModel(model, df)) {
        ShowWorkbenchMessageOnMain(ToNSString(rlispstat::core::FrequencyTableWindowTitle()), ToNSString(rlispstat::core::DatasetForPlotNotAvailableStatus()));
        return;
    }
    std::vector<std::string> xvars = BarplotXVariablesForModel(model);
    std::string splitVar = model->barplotSplitVariable;
    if (splitVar.empty() && xvars.size() > 1) {
        splitVar = xvars[1];
        xvars.erase(xvars.begin() + 1);
    }
    if (xvars.empty()) return;
    if (df.datasetType == "multiple_imputation") {
        ShowWorkbenchMessageOnMain(ToNSString("Nested Contingency Table"), ToNSString("Nested contingency tables are not supported for multiple imputation datasets."));
        return;
    }
    if (splitVar.empty()) {
        ShowContingencyTableDialogOnMain(model, xvars.front(), "");
        return;
    }
    ShowContingencyTableResultOnMain(df, xvars, splitVar, model ? model->id : "");
}

static void RebuildLinkedNestedTable(const std::string &tableId)
{
    std::string plotId;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        auto it = g_linkedTableSources.find(tableId);
        if (it == g_linkedTableSources.end()) return;
        plotId = it->second;
    }
    PlotModel *model = nullptr;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        BarplotView *view = BarplotViewForPlotUnlocked(plotId);
        if (view) model = view.model;
    }
    if (!model || model->kind != "barplot") return;
    Table1WindowController *controller = nil;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        auto cit = g_table1Controllers.find(tableId);
        if (cit != g_table1Controllers.end()) controller = cit->second;
    }
    if (!controller) return;
    dispatch_async(dispatch_get_main_queue(), ^{
        DataFrameModel df;
        if (!DataFrameForContextModel(model, df)) return;
        std::vector<std::string> xvars = BarplotXVariablesForModel(model);
        std::string splitVar = model->barplotSplitVariable;
        if (splitVar.empty() && xvars.size() > 1) {
            splitVar = xvars[1];
            xvars.erase(xvars.begin() + 1);
        }
        if (xvars.empty()) return;
        std::string displayMode = [controller state]->nestedDisplayMode;
        Table1DisplayState *oldState = [controller state];
        Table1DisplayState newState = rlispstat::core::NestedContingencyTableStateForDataFrame(
            df, tableId, xvars, splitVar, displayMode,
            oldState->dataScopeCaptured ? &oldState->dataScope : nullptr);
        newState.datasetId = df.group;
        newState.linkEnabled = true;
        newState.sourcePlotId = plotId;
        [controller updateState:newState];
    });
}

static void NotifyBarplotLinkedTablesChanged(const std::string &plotId)
{
    std::set<std::string> tableIds;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        auto it = g_linkedTables.find(plotId);
        if (it != g_linkedTables.end()) {
            tableIds = it->second;
        }
    }
    for (const std::string &tid : tableIds) {
        RebuildLinkedNestedTable(tid);
    }
}

static void OpenTable1HistogramOnMain(const std::string &group, const std::string &variable)
{
    DataFrameModel df;
    PlotModel seed;
    bool found = false;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        const DataFrameModel *current = FindDataFrameUnlockedConst(group);
        if (current) {
            df = *current;
            found = true;
        }
    }
    BuildSeedPlotForGroup(group, seed);
    if (!found) {
        ShowWorkbenchMessageOnMain(ToNSString(rlispstat::core::Table1PlotWindowTitle()), ToNSString(rlispstat::core::DatasetNotAvailableStatus()));
        return;
    }
    const DataColumn *col = Table1FindColumn(df, variable);
    if (!col) {
        ShowWorkbenchMessageOnMain(ToNSString(rlispstat::core::Table1PlotWindowTitle()), ToNSString(rlispstat::core::SelectedVariableNotAvailableStatus()));
        return;
    }
    PlotModel *created = new PlotModel();
    created->kind = "histogram";
    created->id = "hist_" + group + "_" + variable + "_" + std::to_string((long long)time(nullptr));
    created->group = group;
    created->xLabel = variable;
    created->title = "Histogram of " + variable;
    created->variables = seed.variables;
    created->variableMeta = seed.variableMeta;
    for (size_t i = 0; i < col->values.size(); ++i) {
        double x = NAN;
        if (ParseDataCellDouble(col->values[i], x)) {
            created->histogramPoints.push_back(HistogramPoint{x, (int)i + 1, 0});
        }
    }
    if (created->histogramPoints.empty()) {
        delete created;
        ShowWorkbenchMessageOnMain(ToNSString(rlispstat::core::Table1PlotWindowTitle()), ToNSString(rlispstat::core::Table1HistogramRequiresNumericStatus()));
        return;
    }
    RebinHistogramByRule(created, "sturges");
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        g_plots[created->id] = created;
        if (g_groupSelections.find(created->group) == g_groupSelections.end()) {
            g_groupSelections[created->group] = std::set<int>();
        }
    }
    AddPlotOnMain(created);
}

static void OpenTable1BarplotOnMain(const std::string &group, const std::string &variable, const std::string &splitVariable)
{
    DataFrameModel df;
    PlotModel seed;
    bool found = false;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        const DataFrameModel *current = FindDataFrameUnlockedConst(group);
        if (current) {
            df = *current;
            found = true;
        }
    }
    BuildSeedPlotForGroup(group, seed);
    if (!found) {
        ShowWorkbenchMessageOnMain(ToNSString(rlispstat::core::Table1PlotWindowTitle()), ToNSString(rlispstat::core::DatasetNotAvailableStatus()));
        return;
    }
    const DataColumn *col = Table1FindColumn(df, variable);
    const DataColumn *splitCol = splitVariable.empty() || splitVariable == variable ? nullptr : Table1FindColumn(df, splitVariable);
    if (!col) {
        ShowWorkbenchMessageOnMain(ToNSString(rlispstat::core::Table1PlotWindowTitle()), ToNSString(rlispstat::core::SelectedVariableNotAvailableStatus()));
        return;
    }
    PlotModel *created = new PlotModel();
    created->kind = "barplot";
    created->id = "barplot_" + group + "_" + variable + "_" + std::to_string((long long)time(nullptr));
    created->group = group;
    created->xLabel = variable;
    created->yLabel = "";
    created->title = splitCol ? ("Bar chart of " + variable + " by " + splitVariable) : ("Bar chart of " + variable);
    created->variables = seed.variables;
    created->variableMeta = seed.variableMeta;
    created->barplotXVariables = std::vector<std::string>{variable};
    created->barplotRowColorDisplay = "hide";
    if (splitCol) {
        created->barplotSplitVariable = splitVariable;
        created->barplotShowConditionalPercent = true;
    }

    rlispstat::core::RebuildBarplotBinsForColumns(*created, std::vector<const DataColumn *>{col}, splitCol);
    NormalizeBarplotVisualState(created);
    if (created->barplotBins.empty()) {
        delete created;
        ShowWorkbenchMessageOnMain(ToNSString(rlispstat::core::Table1PlotWindowTitle()), ToNSString(rlispstat::core::Table1BarplotRequiresValueStatus()));
        return;
    }
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        g_plots[created->id] = created;
        if (g_groupSelections.find(created->group) == g_groupSelections.end()) {
            g_groupSelections[created->group] = std::set<int>();
        }
    }
    AddPlotOnMain(created);
}

static void OpenTable1BoxplotOnMain(const std::string &group, const std::string &variable, const std::string &groupVariable)
{
    DataFrameModel df;
    PlotModel seed;
    bool found = false;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        const DataFrameModel *current = FindDataFrameUnlockedConst(group);
        if (current) {
            df = *current;
            found = true;
        }
    }
    BuildSeedPlotForGroup(group, seed);
    if (!found) {
        ShowWorkbenchMessageOnMain(ToNSString(rlispstat::core::Table1PlotWindowTitle()), ToNSString(rlispstat::core::DatasetNotAvailableStatus()));
        return;
    }
    const DataColumn *yCol = Table1FindColumn(df, variable);
    const DataColumn *xCol = groupVariable.empty() ? nullptr : Table1FindColumn(df, groupVariable);
    if (!yCol) {
        ShowWorkbenchMessageOnMain(ToNSString(rlispstat::core::Table1PlotWindowTitle()), ToNSString(rlispstat::core::SelectedVariableNotAvailableStatus()));
        return;
    }
    PlotModel *created = new PlotModel();
    created->kind = "boxplot";
    created->id = "boxplot_" + group + "_" + variable + "_" + std::to_string((long long)time(nullptr));
    created->group = group;
    created->xLabel = groupVariable;
    created->yLabel = variable;
    created->title = groupVariable.empty() ? ("Boxplot of " + variable) : (variable + " by " + groupVariable);
    created->variables = seed.variables;
    created->variableMeta = seed.variableMeta;
    if (groupVariable.empty()) {
        created->boxplotVariables.push_back(variable);
    }
    for (size_t i = 0; i < yCol->values.size(); ++i) {
        double y = NAN;
        if (!ParseDataCellDouble(yCol->values[i], y)) continue;
        std::string category = xCol ? DisplayValueForCell(*xCol, i) : variable;
        if (DataCellIsMissing(category)) category = "NA";
        created->boxplotPoints.push_back(BoxplotPoint{y, category, (int)i + 1});
    }
    if (created->boxplotPoints.empty()) {
        delete created;
        ShowWorkbenchMessageOnMain(ToNSString(rlispstat::core::Table1PlotWindowTitle()), ToNSString(rlispstat::core::Table1BoxplotRequiresNumericStatus()));
        return;
    }
    EnsureParallelBoxplotState(created);
    if (created->boxplotCategories.empty()) {
        created->boxplotCategories = CategoriesForPlot(*created);
    }
    created->boxplotDefinedCategories = created->boxplotCategories;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        g_plots[created->id] = created;
        if (g_groupSelections.find(created->group) == g_groupSelections.end()) {
            g_groupSelections[created->group] = std::set<int>();
        }
    }
    AddPlotOnMain(created);
}

static void OpenMeanComparisonPairedScatterplotOnMain(const std::string &group,
                                                      const std::string &firstVariable,
                                                      const std::string &secondVariable)
{
    PlotModel seed;
    if (!BuildSeedPlotForGroup(group, seed) ||
        !rlispstat::core::FindNumericVariable(seed, firstVariable) ||
        !rlispstat::core::FindNumericVariable(seed, secondVariable)) {
        ShowWorkbenchMessageOnMain(@"Compare Means", @"The paired variables are no longer available.");
        return;
    }
    PlotModel *created = new PlotModel(seed);
    created->kind = "scatter";
    created->isDatasetSeed = false;
    created->isGLMDiagnostic = false;
    created->id = "paired_scatter_" + group + "_" +
        std::to_string((long long)time(nullptr)) + "_" + std::to_string(std::rand() % 1000000);
    created->xLabel = firstVariable;
    created->yLabel = secondVariable;
    created->title = ScatterplotDefaultTitle(firstVariable, secondVariable);
    created->overlays.clear();
    created->nextOverlayId = 1;
    created->interactionMode = "select";
    created->selectionMode = "replace";
    RebuildPointsForCurrentVariables(created);
    ComputeRanges(created);
    if (created->points.empty()) {
        delete created;
        ShowWorkbenchMessageOnMain(@"Compare Means", @"The paired variables contain no complete numeric observations.");
        return;
    }
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        (void)AttachPlotModelUnlocked(created);
        EnsureGroupModelUnlocked(created->group, created);
    }
    AddPlotOnMain(created);
}

static void OpenMeanComparisonDifferenceHistogramOnMain(const std::string &group,
                                                        const std::string &firstVariable,
                                                        const std::string &secondVariable)
{
    DataFrameModel dataframe;
    PlotModel seed;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        const DataFrameModel *found = FindDataFrameUnlockedConst(group);
        if (found) dataframe = *found;
    }
    BuildSeedPlotForGroup(group, seed);
    const DataColumn *first = FindDataColumnInDataFrame(dataframe, firstVariable);
    const DataColumn *second = FindDataColumnInDataFrame(dataframe, secondVariable);
    if (!first || !second) {
        ShowWorkbenchMessageOnMain(@"Compare Means", @"The paired variables are no longer available.");
        return;
    }
    PlotModel *created = new PlotModel();
    created->kind = "histogram";
    created->id = "paired_difference_hist_" + group + "_" +
        std::to_string((long long)time(nullptr)) + "_" + std::to_string(std::rand() % 1000000);
    created->group = group;
    created->xLabel = firstVariable + " \u2212 " + secondVariable;
    created->title = "Histogram of paired differences: " + created->xLabel;
    created->variables = seed.variables;
    created->variableMeta = seed.variableMeta;
    const std::size_t rowCount = std::min(first->values.size(), second->values.size());
    for (std::size_t row = 0; row < rowCount; ++row) {
        double firstValue = NAN;
        double secondValue = NAN;
        if (!ParseDataCellDouble(first->values[row], firstValue) ||
            !ParseDataCellDouble(second->values[row], secondValue)) continue;
        created->histogramPoints.push_back(HistogramPoint{
            firstValue - secondValue,
            static_cast<int>(row) + 1,
            0
        });
    }
    if (created->histogramPoints.empty()) {
        delete created;
        ShowWorkbenchMessageOnMain(@"Compare Means", @"The paired variables contain no complete numeric observations.");
        return;
    }
    RebinHistogramByRule(created, "sturges");
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        g_plots[created->id] = created;
        if (g_groupSelections.find(created->group) == g_groupSelections.end()) {
            g_groupSelections[created->group] = std::set<int>();
        }
    }
    AddPlotOnMain(created);
}

static void AppendGLMRun(NSMutableAttributedString *text, NSString *s, NSFontWeight weight)
{
    NSMutableParagraphStyle *style = [[NSMutableParagraphStyle alloc] init];
    [style setLineSpacing:4.0];
    NSDictionary *attrs = @{
        NSFontAttributeName: [NSFont systemFontOfSize:12 weight:weight],
        NSForegroundColorAttributeName: [NSColor colorWithCalibratedWhite:0.15 alpha:1.0],
        NSParagraphStyleAttributeName: style
    };
    [text appendAttributedString:[[NSAttributedString alloc] initWithString:s attributes:attrs]];
}

static NSAttributedString *GLMFitAttributedSummary(const GLMFitSummary &fit)
{
    NSMutableAttributedString *out = [[NSMutableAttributedString alloc] init];
    AppendGLMRun(out, ToNSString(rlispstat::core::GLMFitGlobalFitSectionTitle()), NSFontWeightSemibold);
    AppendGLMRun(out, ToNSString(rlispstat::core::GLMFitRSquaredLabel()), NSFontWeightSemibold);
    AppendGLMRun(out, ToNSString(" = " + FormatPercent(fit.r2, 1) + "     "), NSFontWeightRegular);
    AppendGLMRun(out, ToNSString(rlispstat::core::GLMFitAdjustedRSquaredLabel()), NSFontWeightSemibold);
    AppendGLMRun(out, ToNSString(" = " + FormatPercent(fit.adjR2, 1) + "     "), NSFontWeightRegular);
    AppendGLMRun(out, ToNSString(rlispstat::core::GLMFitSValueLabel()), NSFontWeightSemibold);
    AppendGLMRun(out, ToNSString(" = " + FormatDouble(fit.sigma, 3) + "     "), NSFontWeightRegular);
    AppendGLMRun(out, ToNSString(rlispstat::core::GLMFitDFLabel()), NSFontWeightSemibold);
    AppendGLMRun(out, ToNSString(" = " + std::to_string(fit.dfResidual)), NSFontWeightRegular);
    return out;
}

static void AppendRegressionDetailField(NSMutableAttributedString *text, NSString *label, NSString *value, BOOL separator)
{
    NSDictionary *labelAttrs = @{
        NSFontAttributeName: [NSFont systemFontOfSize:12 weight:NSFontWeightSemibold],
        NSForegroundColorAttributeName: [NSColor colorWithCalibratedWhite:0.15 alpha:1.0]
    };
    NSDictionary *valueAttrs = @{
        NSFontAttributeName: [NSFont systemFontOfSize:12 weight:NSFontWeightRegular],
        NSForegroundColorAttributeName: [NSColor colorWithCalibratedWhite:0.15 alpha:1.0]
    };
    [text appendAttributedString:[[NSAttributedString alloc] initWithString:label attributes:labelAttrs]];
    [text appendAttributedString:[[NSAttributedString alloc] initWithString:value attributes:valueAttrs]];
    if (separator) {
        [text appendAttributedString:[[NSAttributedString alloc] initWithString:@"; " attributes:valueAttrs]];
    }
}

static NSString *RegressionDetailValue(double value, int digits)
{
    return ToNSString(FormatDoubleOrDash(value, digits));
}

static NSString *RegressionDetailPercent(double value)
{
    return ToNSString(FormatPercentOrDash(value, 1));
}

static NSString *RegressionDetailP(double p)
{
    std::string formatted = FormatPValue(p);
    if (formatted == "\u2014") return @" = \u2014";
    if (formatted.rfind("<", 0) == 0) return ToNSString(" " + formatted);
    return ToNSString(" = " + formatted);
}

static NSBox *GLMBox(NSRect frame)
{
    NSBox *box = [[NSBox alloc] initWithFrame:frame];
    [box setBoxType:NSBoxCustom];
    [box setBorderColor:[NSColor colorWithCalibratedWhite:0.84 alpha:1.0]];
    [box setFillColor:[NSColor colorWithCalibratedWhite:0.99 alpha:1.0]];
    [box setCornerRadius:8.0];
    return box;
}

struct GeneralizedComparisonLayout {
    CGFloat margin = 14.0;
    CGFloat termWidth = 154.0;
    CGFloat modelWidth = 132.0;
    CGFloat addModelWidth = 106.0;
    CGFloat headerHeight = 56.0;
    CGFloat rowHeight = 24.0;
    CGFloat gapAfterTerms = 10.0;
    CGFloat noteHeight = 28.0;
    int fitRows = 14;

    GeneralizedComparisonLayout(bool showInformationCriteria = false,
                                bool binaryComparison = false)
        : fitRows((int)rlispstat::core::GeneralizedComparisonVisibleFitRows(
              binaryComparison, showInformationCriteria).size()) {}

    CGFloat width(int modelCount) const
    {
        return margin * 2.0 + termWidth + modelWidth * (CGFloat)modelCount + addModelWidth;
    }

    CGFloat height(int termCount) const
    {
        return margin * 2.0 + headerHeight + rowHeight * ((CGFloat)termCount + 1.0) +
               gapAfterTerms + rowHeight * (CGFloat)fitRows + noteHeight;
    }

    NSRect termRect(int row) const
    {
        return NSMakeRect(margin, margin + headerHeight + rowHeight * (CGFloat)row, termWidth, rowHeight);
    }

    NSRect modelHeaderRect(int modelIndex) const
    {
        return NSMakeRect(margin + termWidth + modelWidth * (CGFloat)modelIndex, margin, modelWidth, headerHeight);
    }

    NSRect addModelRect(int modelCount) const
    {
        return NSMakeRect(margin + termWidth + modelWidth * (CGFloat)modelCount, margin, addModelWidth, headerHeight);
    }

    NSRect coefficientRect(int row, int modelIndex) const
    {
        return NSMakeRect(margin + termWidth + modelWidth * (CGFloat)modelIndex,
                          margin + headerHeight + rowHeight * (CGFloat)row,
                          modelWidth, rowHeight);
    }

    CGFloat fitStartY(int termCount) const
    {
        return margin + headerHeight + rowHeight * ((CGFloat)termCount + 1.0) + gapAfterTerms;
    }

    NSRect fitLabelRect(int fitRow, int termCount) const
    {
        return NSMakeRect(margin, fitStartY(termCount) + rowHeight * (CGFloat)fitRow, termWidth, rowHeight);
    }

    NSRect fitValueRect(int fitRow, int termCount, int modelIndex) const
    {
        return NSMakeRect(margin + termWidth + modelWidth * (CGFloat)modelIndex,
                          fitStartY(termCount) + rowHeight * (CGFloat)fitRow,
                          modelWidth, rowHeight);
    }
};

