    return self;
}

- (GeneralizedComparisonState *)state
{
    auto it = g_generalizedComparisons.find(_comparisonId);
    return it == g_generalizedComparisons.end() ? nullptr : &it->second;
}

- (void)show
{
    [self activateDatasetForCommands];
    EnableNotesForWindow(_window, _comparisonId, @"this model comparison");
    [_window makeKeyAndOrderFront:nil];
    [_window orderFrontRegardless];
    [NSApp activateIgnoringOtherApps:YES];
}

- (void)activateDatasetForCommands
{
    GeneralizedComparisonState *state = [self state];
    if (!state) return;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        MarkActiveDatasetGroupUnlocked(state->group);
        EnsureDatasetSeedPlotUnlocked(state->group);
    }
    UpdateActiveDatasetMenuOnMain();
}

- (void)windowDidBecomeKey:(NSNotification *)notification
{
    (void)notification;
    [self activateDatasetForCommands];
}

- (BOOL)isVisible
{
    return [_window isVisible];
}

- (int)selectedTermRow { return _selectedTermRow; }
- (int)selectedModelColumn { return _selectedModelColumn; }

- (void)refresh
{
    GeneralizedComparisonState *state = [self state];
    if (!state) return;
    NSString *windowTitle = state->binaryComparison ? @"Binary Model Comparison"
                                                     : ToNSString(rlispstat::core::GLMGeneralizedModelComparisonTitle());
    [_window setTitle:windowTitle];
    [_titleField setStringValue:windowTitle];
    if (state->autoRefit) {
        RefitGeneralizedComparisonModels(*state, false);
    } else {
        RefreshGeneralizedTermRowsFromFits(*state);
    }
    [_badgeField setStringValue:ToNSString(state->group)];
    [_responsePopup removeAllItems];
    if (state->binaryComparison) {
        for (const std::string &name : VariableNamesForModel(&state->seed)) {
            const DataColumn *column = FindDataColumnForModel(&state->seed, name);
            if (column && rlispstat::core::InspectBinaryResponse(*column).ok) [_responsePopup addItemWithTitle:ToNSString(name)];
        }
    } else {
        for (const NumericVariable &var : state->seed.variables) {
            [_responsePopup addItemWithTitle:ToNSString(var.name)];
        }
    }
    [_responsePopup selectItemWithTitle:ToNSString(state->response)];
    if (state->binaryComparison) {
        [_eventPopup removeAllItems];
        if (state->responseCoding.ok) {
            [_eventPopup addItemWithTitle:ToNSString(state->responseCoding.referenceLabel)];
            [_eventPopup addItemWithTitle:ToNSString(state->responseCoding.eventLabel)];
            [_eventPopup selectItemWithTitle:ToNSString(state->responseCoding.eventLabel)];
        }
        [_referenceField setStringValue:ToNSString("Reference: " + (state->responseCoding.ok ? state->responseCoding.referenceLabel : std::string("—")))];
        [_linkPopup selectItemWithTitle:ToNSString(rlispstat::core::BinaryLinkLabel(state->binaryLink))];
        [_eventLabel setHidden:NO]; [_eventPopup setHidden:NO]; [_referenceField setHidden:NO];
        [_linkLabel setHidden:NO]; [_linkPopup setHidden:NO];
    } else {
        [_eventLabel setHidden:YES]; [_eventPopup setHidden:YES]; [_referenceField setHidden:YES];
        [_linkLabel setHidden:YES]; [_linkPopup setHidden:YES];
    }
    [_scopeStaticLabel setStringValue:ToNSString(rlispstat::core::GLMScopeFieldLabel())];
    if ([_scopePopup numberOfItems] != 3) {
        [_scopePopup removeAllItems];
        [_scopePopup addItemWithTitle:ToNSString(rlispstat::core::ScopeAllDataTitle())];
        [_scopePopup addItemWithTitle:ToNSString(rlispstat::core::ScopeSelectedRowsTitle())];
        [_scopePopup addItemWithTitle:ToNSString(rlispstat::core::ScopeUnselectedRowsTitle())];
    }
    [_scopePopup selectItemAtIndex:(state->scope == "selected" ? 1 : (state->scope == "unselected" ? 2 : 0))];
    [_autoRefitButton setHidden:NO];
    [_autoRefitButton setState:state->autoRefit ? NSControlStateValueOn : NSControlStateValueOff];
    [_responsePopup setEnabled:YES];
    [_scopePopup setEnabled:!state->dataScopeCaptured];
    [_eventPopup setEnabled:state->binaryComparison && state->responseCoding.ok];
    [_linkPopup setEnabled:state->binaryComparison];
    [_autoRefitButton setEnabled:YES];
    size_t selected = SelectionCount(state->group);
    size_t n = state->seed.variables.empty() ? 0 : state->seed.variables.front().values.size();
    [_selectedRowsField setStringValue:ToNSString(rlispstat::core::SelectedRowsStatus(selected, n))];

    GeneralizedComparisonLayout layout(state->showInformationCriteria, state->binaryComparison);
    NSSize wanted = NSMakeSize(layout.width((int)state->models.size()), layout.height((int)state->termRows.size()));
    NSSize contentSize = [[_window contentView] frame].size;
    NSScreen *screen = [_window screen] ?: [NSScreen mainScreen];
    CGFloat maxHeight = screen ? std::max((CGFloat)430.0, [screen visibleFrame].size.height * 0.86) : (CGFloat)780.0;
    CGFloat maxWidth = screen ? std::max((CGFloat)700.0, [screen visibleFrame].size.width * 0.92) : (CGFloat)1400.0;
    CGFloat targetWidth = std::min(maxWidth, std::max((CGFloat)790.0, wanted.width + 24.0));
    CGFloat targetHeight = std::min(maxHeight, std::max((CGFloat)540.0, wanted.height + (state->binaryComparison ? 180.0 : 150.0)));
    targetWidth = std::max(targetWidth, contentSize.width);
    targetHeight = std::max(targetHeight, contentSize.height);
    if (std::fabs(contentSize.height - targetHeight) > 0.5 || std::fabs(contentSize.width - targetWidth) > 0.5) {
        [_window setContentMaxSize:NSMakeSize(10000.0, maxHeight)];
        [_window setContentSize:NSMakeSize(targetWidth, targetHeight)];
        contentSize = [[_window contentView] frame].size;
    }
    CGFloat h = contentSize.height;
    CGFloat w = contentSize.width;
    [_titleField setFrame:NSMakeRect(14, h - 48, 320, 24)];
    [_badgeField setFrame:NSMakeRect(w - 150, h - 46, 130, 20)];
    [_responseStaticLabel setFrame:NSMakeRect(14, h - 82, 70, 22)];
    [_responsePopup setFrame:NSMakeRect(86, h - 86, state->binaryComparison ? 112 : 150, 28)];
    if (state->binaryComparison) {
        [_eventLabel setFrame:NSMakeRect(208, h - 82, 42, 22)];
        [_eventPopup setFrame:NSMakeRect(250, h - 86, 92, 28)];
        [_referenceField setFrame:NSMakeRect(350, h - 82, 122, 22)];
        [_linkLabel setFrame:NSMakeRect(480, h - 82, 34, 22)];
        [_linkPopup setFrame:NSMakeRect(514, h - 86, 92, 28)];
        [_scopeStaticLabel setFrame:NSMakeRect(14, h - 112, 46, 22)];
        [_scopePopup setFrame:NSMakeRect(60, h - 116, 138, 28)];
        [_autoRefitButton setFrame:NSMakeRect(214, h - 112, 94, 22)];
        [_selectedRowsField setFrame:NSMakeRect(w - 170, h - 112, 150, 20)];
    } else {
        [_scopeStaticLabel setFrame:NSMakeRect(254, h - 82, 46, 22)];
        [_scopePopup setFrame:NSMakeRect(300, h - 86, 138, 28)];
        [_autoRefitButton setFrame:NSMakeRect(456, h - 82, 94, 22)];
        [_selectedRowsField setFrame:NSMakeRect(w - 170, h - 82, 150, 20)];
    }
    CGFloat reportTopInset = state->binaryComparison ? 170.0 : 140.0;
    [_scrollView setFrame:NSMakeRect(12, 46, std::max((CGFloat)200.0, w - 24.0), std::max((CGFloat)140.0, h - reportTopInset))];
    [_statusField setFrame:NSMakeRect(14, 16, std::max((CGFloat)200.0, w - 28.0), 20)];
    [_reportView setFrame:NSMakeRect(0, 0, wanted.width, wanted.height)];
    [_reportView setNeedsDisplay:YES];
    if (state->binaryComparison) {
        std::string status = "Status: comparing " + std::to_string(state->models.size()) + " models on " +
            std::to_string(state->commonRows.size()) + " common rows";
        if (!state->responseCoding.ok) status = "Select a binary response variable before fitting the models.";
        else if (state->commonRows.empty()) status = "No common complete rows are available for the model comparison.";
        else for (const GeneralizedComparisonModel &model : state->models) {
            if (!model.fit.ok && !model.fit.status.empty()) {
                status = "Status: " + model.label + ": " + model.fit.status;
                break;
            }
        }
        [_statusField setStringValue:ToNSString(status)];
    } else {
        [_statusField setStringValue:ToNSString(rlispstat::core::GeneralizedComparisonSummaryStatus(state->models.size(), state->termRows.size()))];
    }
    if (state->dataScopeCaptured) {
        NSString *status = [_statusField stringValue] ?: @"";
        [_statusField setStringValue:[status stringByAppendingFormat:@" · %@",
            ToNSString(rlispstat::core::AnalysisScopeWindowSummary(
                state->dataScope, state->dataScope.totalDatasetRows))]];
    }
}

- (void)refitModelColumn:(int)modelColumn
{
    GeneralizedComparisonState *state = [self state];
    if (!state || modelColumn < 0 || (size_t)modelColumn >= state->models.size()) return;
    GeneralizedComparisonModel &model = state->models[(size_t)modelColumn];
    model.modelVersion += 1;
    model.isStale = true;
    if (state->autoRefit && state->binaryComparison) {
        RefitGeneralizedComparisonModels(*state, true);
        RefreshRegressionComparisonDiagnosticsForModelNow(model.id);
    } else if (state->autoRefit) {
        RefitGeneralizedComparisonModel(*state, model);
        RefreshGeneralizedTermRowsFromFits(*state);
        RefreshRegressionComparisonDiagnosticsForModelNow(model.id);
    }
}

- (void)addTerm:(id)sender
{
    (void)sender;
    GeneralizedComparisonState *state = [self state];
    if (!state) return;
    NSMenu *menu = [[NSMenu alloc] initWithTitle:ToNSString(rlispstat::core::GLMAddTermTitle())];
    int active = std::max(0, std::min(state->activeModel, (int)state->models.size() - 1));
    GeneralizedComparisonModel *activeModel = state->models.empty() ? nullptr : &state->models[(size_t)active];
    std::string activeResponse = activeModel && !activeModel->response.empty() ? activeModel->response : state->response;
    for (const std::string &name : VariableNamesForModel(&state->seed)) {
        if (name == activeResponse || (activeModel && rlispstat::core::GeneralizedModelIncludesTerm(*activeModel, name))) continue;
        NSMenuItem *item = [[NSMenuItem alloc] initWithTitle:ToNSString(name) action:@selector(addTermFromMenu:) keyEquivalent:@""];
        [item setTarget:self];
        [item setRepresentedObject:ToNSString(name)];
        [menu addItem:item];
    }
    if ([menu numberOfItems] > 0) {
        [menu addItem:[NSMenuItem separatorItem]];
    }
    std::vector<std::string> interactionBase = activeModel ? activeModel->includedTerms : std::vector<std::string>();
    std::vector<std::vector<std::string>> comparisonTerms;
    for (const GeneralizedComparisonModel &model : state->models) {
        comparisonTerms.push_back(model.includedTerms);
    }
    if (!AddComparisonInteractionMenuItems(menu, self, @selector(addTermFromMenu:), &state->seed,
                                           activeResponse, comparisonTerms, interactionBase)) {
        NSInteger last = [menu numberOfItems] - 1;
        if (last >= 0 && [[menu itemAtIndex:last] isSeparatorItem]) {
            [menu removeItemAtIndex:last];
        }
    }
    if ([[menu itemArray] count] == 0) {
        [_statusField setStringValue:ToNSString(rlispstat::core::ComparisonNoAvailableTermsStatus())];
        return;
    }
    [menu popUpMenuPositioningItem:nil atLocation:NSMakePoint(20, 20) inView:_reportView];
}

- (void)addTermFromMenu:(id)sender
{
    NSString *name = [sender representedObject];
    if (!name) return;
    GeneralizedComparisonState *state = [self state];
    if (!state) return;
    std::string term = [name UTF8String];
    int active = std::max(0, std::min(state->activeModel, (int)state->models.size() - 1));
    GeneralizedComparisonModel &model = state->models[(size_t)active];
    if (AddHierarchicalGeneralizedComparisonTerm(*state, model, term)) {
        [self refitModelColumn:active];
        [self refresh];
    }
}

- (void)addModelColumn:(id)sender
{
    (void)sender;
    GeneralizedComparisonState *state = [self state];
    if (!state) return;
    GeneralizedComparisonModel model;
    if (!state->models.empty()) {
        int active = std::max(0, std::min(state->activeModel, (int)state->models.size() - 1));
        model = state->models[(size_t)active];
        model.label = rlispstat::core::UniqueGeneralizedComparisonCopyLabelForState(*state, model.label);
    } else {
        model.label = rlispstat::core::NextUntitledGeneralizedComparisonLabel(*state);
        model.response = state->response;
        model.family = state->family;
        model.link = state->link;
    }
    model.id = rlispstat::core::NextGeneralizedComparisonModelId(*state);
    model.fit = GeneralizedGLMState();
    model.modelVersion = 0;
    model.fitVersion = 0;
    model.isStale = true;
    state->models.push_back(model);
    state->activeModel = (int)state->models.size() - 1;
    _selectedModelColumn = state->activeModel;
    if (state->binaryComparison) {
        if (state->autoRefit) RefitGeneralizedComparisonModels(*state, true);
        else RefreshGeneralizedTermRowsFromFits(*state);
    } else {
        RefitGeneralizedComparisonModel(*state, state->models.back());
        RefreshGeneralizedTermRowsFromFits(*state);
    }
    [self refresh];
}

- (void)modelHeaderClicked:(int)modelColumn event:(NSEvent *)event
{
    (void)event;
    GeneralizedComparisonState *state = [self state];
    if (!state || modelColumn < 0 || (size_t)modelColumn >= state->models.size()) return;
    state->activeModel = modelColumn;
    _selectedModelColumn = modelColumn;
    _selectedTermRow = -1;
}

- (void)cellClickedAtTermRow:(int)termRow modelColumn:(int)modelColumn event:(NSEvent *)event
{
    GeneralizedComparisonState *state = [self state];
    if (!state || termRow < 0 || (size_t)termRow >= state->termRows.size() ||
        modelColumn < 0 || (size_t)modelColumn >= state->models.size()) return;
    state->activeModel = modelColumn;
    _selectedTermRow = termRow;
    _selectedModelColumn = modelColumn;
    BOOL toggle = ([event clickCount] >= 2 || (([event modifierFlags] & NSEventModifierFlagOption) != 0));
    if (termRow > 0) {
        std::string term = GeneralizedComparisonSourceTerm(*state, state->termRows[(size_t)termRow]);
        GeneralizedComparisonModel &model = state->models[(size_t)modelColumn];
        bool included = rlispstat::core::GeneralizedModelIncludesTerm(model, term);
        if (toggle || !included) {
            [self toggleSelectedTerm:nil];
        }
    }
}

- (void)toggleTermAtRow:(int)termRow modelColumn:(int)modelColumn
{
    GeneralizedComparisonState *state = [self state];
    if (!state || termRow <= 0 || (size_t)termRow >= state->termRows.size() ||
        modelColumn < 0 || (size_t)modelColumn >= state->models.size()) return;
    state->activeModel = modelColumn;
    _selectedTermRow = termRow;
    _selectedModelColumn = modelColumn;
    [self toggleSelectedTerm:nil];
}

- (NSString *)displayForTerm:(const std::string &)term modelColumn:(int)modelColumn
{
    GeneralizedComparisonState *state = [self state];
    if (!state || modelColumn < 0 || (size_t)modelColumn >= state->models.size()) return @"";
    const GeneralizedComparisonModel &model = state->models[(size_t)modelColumn];
    return ToNSString(rlispstat::core::GeneralizedCoefficientDisplay(model.fit.rows, model.fit.ok,
                                                                     model.includedTerms, term));
}

- (NSString *)fitDisplayForRow:(int)fitRow modelColumn:(int)modelColumn
{
    GeneralizedComparisonState *state = [self state];
    if (!state || modelColumn < 0 || (size_t)modelColumn >= state->models.size()) return @"";
    const std::vector<int> visibleRows = rlispstat::core::GeneralizedComparisonVisibleFitRows(
        state->binaryComparison, state->showInformationCriteria);
    if (fitRow < 0 || (size_t)fitRow >= visibleRows.size()) return @"";
    const int rawFitRow = visibleRows[(size_t)fitRow];
    const GeneralizedComparisonModel &model = state->models[(size_t)modelColumn];
    const GeneralizedGLMState &fit = model.fit;
    if (rawFitRow == 14 || rawFitRow == 15) {
        const bool useAIC = rawFitRow == 14;
        double minimum = INFINITY;
        for (const GeneralizedComparisonModel &candidate : state->models) {
            const double value = useAIC ? candidate.fit.aic : candidate.fit.bic;
            if (candidate.fit.ok && std::isfinite(value)) minimum = std::min(minimum, value);
        }
        const double value = useAIC ? fit.aic : fit.bic;
        return fit.ok && std::isfinite(value) && std::isfinite(minimum)
            ? ToNSString(FormatDoubleOrDash(value - minimum, 2)) : @"—";
    }
    if (state->binaryComparison) {
        const NestedModelTestResult test = GeneralizedAdjacentModelTest(*state, modelColumn);
        switch (rawFitRow) {
            case 0: return fit.ok ? ToNSString(std::to_string(fit.n)) : @"—";
            case 1: return fit.ok ? ToNSString(std::to_string(fit.responseCoding.eventCount)) : @"—";
            case 2: return fit.ok ? ToNSString(FormatDoubleOrDash(fit.residualDeviance, 3)) : @"—";
            case 3: return fit.ok ? ToNSString(std::to_string(fit.dfResidual)) : @"—";
            case 4: return fit.ok ? ToNSString(FormatDoubleOrDash(fit.aic, 2)) : @"—";
            case 5: return fit.ok ? ToNSString(FormatDoubleOrDash(fit.bic, 2)) : @"—";
            case 6: return fit.ok ? ToNSString(FormatDoubleOrDash(fit.logLik, 3)) : @"—";
            case 7: return fit.ok ? ToNSString(FormatDoubleOrDash(fit.nagelkerkeR2, 3)) : @"—";
            case 8: return fit.ok ? ToNSString(FormatDoubleOrDash(fit.auc, 3)) : @"—";
            case 9: return fit.ok ? ToNSString(std::to_string(fit.parameterCount)) : @"—";
            case 10: return test.ok ? ToNSString(std::to_string(test.df)) : @"—";
            case 11: return test.ok ? ToNSString(FormatDoubleOrDash(test.delta, 3)) : @"—";
            case 12: return test.ok ? ToNSString(FormatDoubleOrDash(test.statistic, 3)) : @"—";
            case 13: return test.ok ? ToNSString(FormatPValue(test.p)) : @"—";
            default: return @"";
        }
    }
    rlispstat::core::GeneralizedComparisonFitDisplayData display;
    display.ok = fit.ok;
    display.family = model.family;
    display.link = model.link;
    display.n = fit.n;
    display.nullDeviance = fit.nullDeviance;
    display.residualDeviance = fit.residualDeviance;
    display.dfResidual = fit.dfResidual;
    display.aic = fit.aic;
    display.bic = fit.bic;
    display.dispersion = fit.dispersion;
    display.logLik = fit.logLik;
    return ToNSString(rlispstat::core::GeneralizedComparisonFitDisplay(
        display, GeneralizedAdjacentModelTest(*state, modelColumn), rawFitRow));
}

- (NSString *)fitLabelForRow:(int)fitRow
{
    GeneralizedComparisonState *state = [self state];
    if (!state) return @"";
    const std::vector<int> visibleRows = rlispstat::core::GeneralizedComparisonVisibleFitRows(
        state->binaryComparison, state->showInformationCriteria);
    if (fitRow < 0 || (size_t)fitRow >= visibleRows.size()) return @"";
    const int rawFitRow = visibleRows[(size_t)fitRow];
    if (state && state->binaryComparison) {
        static NSString *labels[] = { @"N", @"Events", @"Residual dev.", @"df residual", @"AIC", @"BIC",
            @"logLik", @"Nagelkerke pseudo-R²", @"Apparent AUC", @"Parameters", @"Δdf vs prev",
            @"Δ deviance", @"LR χ² vs prev", @"p vs prev", @"ΔAIC", @"ΔBIC" };
        return rawFitRow >= 0 && rawFitRow < 16 ? labels[rawFitRow] : @"";
    }
    return ToNSString(rlispstat::core::GeneralizedComparisonFitLabel(rawFitRow));
}

- (NSString *)comparisonTableText
{
    GeneralizedComparisonState *state = [self state];
    if (!state) return @"";
    rlispstat::core::ComparisonCopyTable table;
    table.title = state->binaryComparison ? "Binary Model Comparison" : "Generalized Model Comparison";
    table.response = state->response;
    for (const GeneralizedComparisonModel &model : state->models) table.modelLabels.push_back(model.label);
    for (const std::string &term : state->termRows) {
        table.termLabels.push_back(GeneralizedComparisonDisplayLabel(*state, term));
        std::vector<std::string> cells;
        for (size_t m = 0; m < state->models.size(); ++m) {
            cells.push_back([[self displayForTerm:term modelColumn:(int)m] UTF8String]);
        }
        table.termDisplaysByRow.push_back(cells);
    }
    GeneralizedComparisonLayout layout(state->showInformationCriteria, state->binaryComparison);
    for (int r = 0; r < layout.fitRows; ++r) {
        table.fitLabels.push_back([[self fitLabelForRow:r] UTF8String]);
        std::vector<std::string> cells;
        for (size_t m = 0; m < state->models.size(); ++m) {
            cells.push_back([[self fitDisplayForRow:r modelColumn:(int)m] UTF8String]);
        }
        table.fitDisplaysByRow.push_back(cells);
    }
    table.footnote = rlispstat::core::GeneralizedComparisonFootnote();
    return ToNSString(rlispstat::core::ComparisonCopyTableText(table));
}

