{
    GeneralizedComparisonState *state = [self state];
    NSMenuItem *root = [[NSMenuItem alloc] initWithTitle:@"Export" action:nil keyEquivalent:@""];
    NSMenu *menu = [[NSMenu alloc] initWithTitle:@"Export"];
    AddStandardTableVisualExportItems(menu, _reportView,
        state && state->binaryComparison ? @"Binary Model Comparison" : @"Generalized Model Comparison",
        state && state->binaryComparison ? @"binary-model-comparison" : @"generalized-model-comparison",
        [self comparisonTableText]);
    [menu addItem:[NSMenuItem separatorItem]];
    NSMenuItem *copy = [[NSMenuItem alloc] initWithTitle:@"Copy table with headers" action:@selector(copyComparisonTable:) keyEquivalent:@""];
    [copy setTarget:self]; [menu addItem:copy];
    if (state && state->binaryComparison) {
        NSMenuItem *syntax = [[NSMenuItem alloc] initWithTitle:@"Copy R syntax" action:@selector(copyBinaryComparisonRSyntax:) keyEquivalent:@""];
        [syntax setTarget:self]; [menu addItem:syntax];
        NSMenuItem *csv = [[NSMenuItem alloc] initWithTitle:@"Likelihood-ratio comparisons as CSV…" action:@selector(exportBinaryComparisonCSV:) keyEquivalent:@""];
        [csv setTarget:self]; [menu addItem:csv];
        if (state->showInformationCriteria) {
            NSMenuItem *criteria = [[NSMenuItem alloc] initWithTitle:@"Information criteria as CSV…" action:@selector(exportBinaryComparisonCSV:) keyEquivalent:@""];
            [criteria setTarget:self]; [criteria setRepresentedObject:@"information_criteria"]; [menu addItem:criteria];
        }
        NSMenuItem *displayed = [[NSMenuItem alloc] initWithTitle:@"PDF — As displayed…" action:@selector(exportBinaryComparisonPDF:) keyEquivalent:@""];
        NSMenuItem *apa = [[NSMenuItem alloc] initWithTitle:@"PDF — APA 7 style…" action:@selector(exportBinaryComparisonAPA:) keyEquivalent:@""];
        [displayed setTarget:self]; [apa setTarget:self]; [menu addItem:displayed]; [menu addItem:apa];
    }
    [root setSubmenu:menu];
