- (void)copyBinaryComparisonRSyntax:(id)sender
{
    (void)sender;
    GeneralizedComparisonState *state = [self state];
    if (!state || !state->binaryComparison) return;
    auto quoted = [](const std::string &value) {
        std::string out = "\""; for (char ch : value) { if (ch == '\\' || ch == '"') out.push_back('\\'); out.push_back(ch); } return out + "\"";
    };
    std::ostringstream syntax;
    for (std::size_t index = 0; index < state->models.size(); ++index) {
        const auto &model = state->models[index];
        syntax << "model_" << index + 1 << " <- LinkEDA::ls_new_binary_regression(data = " << quoted(state->group)
               << ", response = " << quoted(state->response) << ", terms = ";
        if (model.includedTerms.empty()) syntax << "character()";
        else { syntax << "c("; for (std::size_t t=0;t<model.includedTerms.size();++t){if(t)syntax<<", ";syntax<<quoted(model.includedTerms[t]);} syntax << ")"; }
        syntax << ", link = " << quoted(state->link) << ", event = " << quoted(state->responseCoding.eventValue)
               << ", reference = " << quoted(state->responseCoding.referenceValue) << ")\n";
    }
    NSPasteboard *pasteboard = [NSPasteboard generalPasteboard]; [pasteboard clearContents];
    [pasteboard setString:ToNSString(syntax.str()) forType:NSPasteboardTypeString];
    [_statusField setStringValue:@"Status: R syntax copied."];
}

- (void)exportBinaryComparisonCSV:(id)sender
{
    GeneralizedComparisonState *state = [self state];
    if (!state || !state->binaryComparison) return;
    NSString *kind = [sender representedObject];
    const bool informationCriteria = kind && [kind isEqualToString:@"information_criteria"];
    NSSavePanel *panel = [NSSavePanel savePanel];
    [panel setAllowedFileTypes:@[@"csv"]];
    [panel setNameFieldStringValue:informationCriteria
        ? @"binary_model_information_criteria.csv" : @"binary_model_comparison.csv"];
    if ([panel runModal] != NSModalResponseOK) return;
    auto quoted = [](const std::string &value) {
        std::string out = "\"";
        for (char ch : value) { if (ch == '"') out.push_back('"'); out.push_back(ch); }
        return out + "\"";
    };
    auto number = [](double value) {
        if (!std::isfinite(value)) return std::string();
        std::ostringstream out; out << std::setprecision(17) << value; return out.str();
    };
    std::ostringstream structured;
    if (informationCriteria) {
        structured << "Model,AIC,BIC,Delta_AIC,Delta_BIC\n";
        double minAIC = INFINITY, minBIC = INFINITY;
        for (const auto &model : state->models) {
            if (model.fit.ok && std::isfinite(model.fit.aic)) minAIC = std::min(minAIC, model.fit.aic);
            if (model.fit.ok && std::isfinite(model.fit.bic)) minBIC = std::min(minBIC, model.fit.bic);
        }
        for (const auto &model : state->models) {
            structured << quoted(model.label) << ',' << number(model.fit.aic) << ',' << number(model.fit.bic) << ','
                << number(model.fit.aic - minAIC) << ',' << number(model.fit.bic - minBIC) << "\n";
        }
    } else {
        structured << "Reduced_Model,Full_Model,LR_Chisq,df,p,Delta_Deviance\n";
        for (std::size_t index = 1; index < state->models.size(); ++index) {
            const auto &reduced = state->models[index - 1];
            const auto &full = state->models[index];
            structured << quoted(reduced.label) << ',' << quoted(full.label) << ',';
            if (full.comparisonOk) {
                structured << number(full.comparisonStatistic) << ',' << full.comparisonDf << ','
                    << number(full.comparisonP) << ',' << number(full.comparisonDelta);
            } else {
                structured << ",,,";
            }
            structured << "\n";
        }
    }
    NSString *output = ToNSString(structured.str());
    NSError *error = nil;
    if (![output writeToURL:[panel URL] atomically:YES encoding:NSUTF8StringEncoding error:&error]) {
        ShowWorkbenchMessageOnMain(@"Export comparison", error ? [error localizedDescription] : @"The CSV file could not be written.");
    }
}

