- (void)toggleSelectedTerm:(id)sender
{
    (void)sender;
    GeneralizedComparisonState *state = [self state];
    if (!state || _selectedTermRow <= 0 || (size_t)_selectedTermRow >= state->termRows.size() ||
        _selectedModelColumn < 0 || (size_t)_selectedModelColumn >= state->models.size()) return;
    const std::string term = GeneralizedComparisonSourceTerm(*state, state->termRows[(size_t)_selectedTermRow]);
    GeneralizedComparisonModel &model = state->models[(size_t)_selectedModelColumn];
    auto it = std::find(model.includedTerms.begin(), model.includedTerms.end(), term);
    if (it == model.includedTerms.end()) {
        AddHierarchicalGeneralizedComparisonTerm(*state, model, term);
    } else {
        RemoveModelTermCascade(model.includedTerms, term);
    }
    [self refitModelColumn:_selectedModelColumn];
    [self refresh];
}

- (void)addSelectedTermToAllModels:(id)sender
{
    (void)sender;
    GeneralizedComparisonState *state = [self state];
    if (!state || _selectedTermRow <= 0 || (size_t)_selectedTermRow >= state->termRows.size()) return;
    const std::string term = GeneralizedComparisonSourceTerm(*state, state->termRows[(size_t)_selectedTermRow]);
    for (size_t i = 0; i < state->models.size(); ++i) {
        AddHierarchicalGeneralizedComparisonTerm(*state, state->models[i], term);
        state->models[i].modelVersion += 1;
        state->models[i].isStale = true;
    }
    if (state->autoRefit) RefitGeneralizedComparisonModels(*state, true);
    [self refresh];
}

- (void)removeSelectedTermFromAllModels:(id)sender
{
    (void)sender;
    GeneralizedComparisonState *state = [self state];
    if (!state || _selectedTermRow <= 0 || (size_t)_selectedTermRow >= state->termRows.size()) return;
    const std::string term = GeneralizedComparisonSourceTerm(*state, state->termRows[(size_t)_selectedTermRow]);
    for (size_t i = 0; i < state->models.size(); ++i) {
        RemoveModelTermCascade(state->models[i].includedTerms, term);
        state->models[i].modelVersion += 1;
        state->models[i].isStale = true;
    }
    if (state->autoRefit) RefitGeneralizedComparisonModels(*state, true);
    [self refresh];
}

- (void)showCoefficientDetails:(id)sender
{
    (void)sender;
    GeneralizedComparisonState *state = [self state];
    if (!state || _selectedTermRow < 0 || (size_t)_selectedTermRow >= state->termRows.size() ||
        _selectedModelColumn < 0 || (size_t)_selectedModelColumn >= state->models.size()) return;
    GeneralizedComparisonModel &model = state->models[(size_t)_selectedModelColumn];
    const std::string displayTerm = state->termRows[(size_t)_selectedTermRow];
    const GeneralizedGLMRow *coef = GeneralizedRowForTerm(model.fit.rows, displayTerm);
    if (!coef) {
        [_statusField setStringValue:ToNSString(ComparisonTermNotIncludedStatus())];
        return;
    }
    [_statusField setStringValue:ToNSString(GeneralizedComparisonCoefficientDetailsStatus(*coef))];
}

