- (void)refitAllBinaryModels:(id)sender
{
    (void)sender;
    GeneralizedComparisonState *state = [self state];
    if (!state || !state->binaryComparison) return;
    for (auto &model : state->models) { model.modelVersion += 1; model.isStale = true; }
    RefitGeneralizedComparisonModels(*state, true);
    [self refresh];
}

- (void)duplicateSelectedModel:(id)sender
{
    (void)sender;
    [self addModelColumn:self];
}

- (void)deleteSelectedModel:(id)sender
{
    (void)sender;
    GeneralizedComparisonState *state = [self state];
    if (!state || state->models.size() <= 1 || _selectedModelColumn < 0 ||
        (size_t)_selectedModelColumn >= state->models.size()) return;
    state->models.erase(state->models.begin() + _selectedModelColumn);
    state->activeModel = std::max(0, std::min(_selectedModelColumn, (int)state->models.size() - 1));
    _selectedModelColumn = state->activeModel;
    if (state->binaryComparison) {
        for (auto &model : state->models) { model.modelVersion += 1; model.isStale = true; }
        if (state->autoRefit) RefitGeneralizedComparisonModels(*state, true);
        else RefreshGeneralizedTermRowsFromFits(*state);
    } else {
        RefreshGeneralizedTermRowsFromFits(*state);
    }
    [self refresh];
}

- (void)renameSelectedModel:(id)sender
{
    (void)sender;
    GeneralizedComparisonState *state = [self state];
    if (!state || _selectedModelColumn < 0 || (size_t)_selectedModelColumn >= state->models.size()) return;
    NSAlert *alert = [[NSAlert alloc] init];
    [alert setMessageText:ToNSString(rlispstat::core::GLMRenameModelTitle())];
    NSTextField *field = [[NSTextField alloc] initWithFrame:NSMakeRect(0, 0, 220, 24)];
    [field setStringValue:ToNSString(state->models[(size_t)_selectedModelColumn].label)];
    [alert setAccessoryView:field];
    [alert addButtonWithTitle:ToNSString(rlispstat::core::GLMRenameModelTitle())];
    [alert addButtonWithTitle:ToNSString(rlispstat::core::AlertCancelButtonTitle())];
    if ([alert runModal] == NSAlertFirstButtonReturn) {
        state->models[(size_t)_selectedModelColumn].label = [[field stringValue] UTF8String];
        [self refresh];
    }
}

- (void)openSelectedModelAsGeneralizedGLM:(id)sender
{
    (void)sender;
    GeneralizedComparisonState *state = [self state];
    if (!state || _selectedModelColumn < 0 || (size_t)_selectedModelColumn >= state->models.size()) return;
    GeneralizedComparisonModel &model = state->models[(size_t)_selectedModelColumn];
    GeneralizedGLMState single = model.fit;
    single.id = "gglm_" + model.id + "_" + std::to_string((long long)time(nullptr));
    single.group = state->group;
    single.response = model.response.empty() ? state->response : model.response;
    single.terms = model.includedTerms;
    single.family = model.family;
    single.link = model.link;
    single.scope = state->scope;
    single.seed = state->seed;
    single.hasSeed = true;
    if (!single.ok) RefitGeneralizedGLMState(single);
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        g_generalizedGLMs[single.id] = single;
    }
    ShowGeneralizedGLMOnMain(single.id);
}

