- (NSMenu *)contextMenuForModelColumn:(int)modelColumn
{
    _selectedModelColumn = modelColumn;
    GeneralizedComparisonState *state = [self state];
    if (state) state->activeModel = modelColumn;
    const auto titles = rlispstat::core::DefaultModelContextMenuTitles();
    NSMenu *menu = [[NSMenu alloc] initWithTitle:ToNSString(titles.model)];
    NSMenuItem *informationCriteria = [[NSMenuItem alloc]
        initWithTitle:@"Information criteria"
               action:@selector(toggleInformationCriteria:)
        keyEquivalent:@""];
    [informationCriteria setTarget:self];
    [informationCriteria setState:state && state->showInformationCriteria
        ? NSControlStateValueOn : NSControlStateValueOff];
    [menu addItem:informationCriteria];
    [menu addItem:[NSMenuItem separatorItem]];
    if (state && state->binaryComparison) {
        NSArray *binaryItems = @[
            [[NSMenuItem alloc] initWithTitle:ToNSString(rlispstat::core::ScatterplotSetActiveModelTitle()) action:@selector(modelHeaderClickedMenu:) keyEquivalent:@""],
            [[NSMenuItem alloc] initWithTitle:ToNSString(rlispstat::core::GLMRenameModelTitle()) action:@selector(renameSelectedModel:) keyEquivalent:@""],
            [[NSMenuItem alloc] initWithTitle:ToNSString(rlispstat::core::GLMDuplicateModelTitle()) action:@selector(duplicateSelectedModel:) keyEquivalent:@""],
            [[NSMenuItem alloc] initWithTitle:ToNSString(rlispstat::core::GLMDeleteModelTitle()) action:@selector(deleteSelectedModel:) keyEquivalent:@""],
            [NSMenuItem separatorItem],
            [[NSMenuItem alloc] initWithTitle:@"Refit all models" action:@selector(refitAllBinaryModels:) keyEquivalent:@""],
            [NSMenuItem separatorItem],
            [[NSMenuItem alloc] initWithTitle:@"ROC curve" action:@selector(openROCForSelectedModel:) keyEquivalent:@""],
            [[NSMenuItem alloc] initWithTitle:@"Calibration plot" action:@selector(openCalibrationForSelectedModel:) keyEquivalent:@""],
            [[NSMenuItem alloc] initWithTitle:ToNSString(titles.openAsSingleGeneralizedGLM) action:@selector(openSelectedModelAsGeneralizedGLM:) keyEquivalent:@""],
            [NSMenuItem separatorItem],
            [[NSMenuItem alloc] initWithTitle:@"Compare ROC curves" action:@selector(openBinaryComparisonROCPlot:) keyEquivalent:@""]
        ];
        for (NSMenuItem *item in binaryItems) {
            if ([item action]) [item setTarget:self];
            [menu addItem:item];
        }
        if (state->showInformationCriteria) {
            NSMenuItem *aicPlot = [[NSMenuItem alloc] initWithTitle:@"Compare AIC graph"
                action:@selector(openBinaryComparisonAICPlot:) keyEquivalent:@""];
            NSMenuItem *bicPlot = [[NSMenuItem alloc] initWithTitle:@"Compare BIC graph"
                action:@selector(openBinaryComparisonBICPlot:) keyEquivalent:@""];
            [aicPlot setTarget:self]; [bicPlot setTarget:self];
            [menu addItem:aicPlot]; [menu addItem:bicPlot];
        }
        [menu addItem:[NSMenuItem separatorItem]];
        [menu addItem:[self comparisonExportMenuItem]];
        return menu;
    }
    NSArray *items = @[
        [[NSMenuItem alloc] initWithTitle:ToNSString(rlispstat::core::ScatterplotSetActiveModelTitle()) action:@selector(modelHeaderClickedMenu:) keyEquivalent:@""],
        [[NSMenuItem alloc] initWithTitle:ToNSString(rlispstat::core::GLMRenameModelTitle()) action:@selector(renameSelectedModel:) keyEquivalent:@""],
        [[NSMenuItem alloc] initWithTitle:ToNSString(rlispstat::core::GLMDuplicateModelTitle()) action:@selector(duplicateSelectedModel:) keyEquivalent:@""],
        [[NSMenuItem alloc] initWithTitle:ToNSString(rlispstat::core::GLMDeleteModelTitle()) action:@selector(deleteSelectedModel:) keyEquivalent:@""],
        [NSMenuItem separatorItem],
        [[NSMenuItem alloc] initWithTitle:ToNSString(rlispstat::core::GLMComparisonFamilyMenuItemTitle()) action:@selector(showFamilyMenuForSelectedModel:) keyEquivalent:@""],
        [[NSMenuItem alloc] initWithTitle:ToNSString(rlispstat::core::GLMComparisonLinkMenuItemTitle()) action:@selector(showLinkMenuForSelectedModel:) keyEquivalent:@""],
        [NSMenuItem separatorItem],
        [[NSMenuItem alloc] initWithTitle:ToNSString(rlispstat::core::GLMDiagnosticObservedFittedTitle()) action:@selector(openObservedFittedForSelectedModel:) keyEquivalent:@""],
        [[NSMenuItem alloc] initWithTitle:ToNSString(rlispstat::core::GLMDiagnosticResidualsFittedTitle()) action:@selector(openResidualsFittedForSelectedModel:) keyEquivalent:@""],
        [[NSMenuItem alloc] initWithTitle:ToNSString(rlispstat::core::GLMDiagnosticResidualHistogramTitle()) action:@selector(openResidualHistogramForSelectedModel:) keyEquivalent:@""],
        [[NSMenuItem alloc] initWithTitle:ToNSString(rlispstat::core::GLMDiagnosticNormalQQTitle()) action:@selector(openQQForSelectedModel:) keyEquivalent:@""],
        [[NSMenuItem alloc] initWithTitle:ToNSString(titles.openAsSingleGeneralizedGLM) action:@selector(openSelectedModelAsGeneralizedGLM:) keyEquivalent:@""],
        [NSMenuItem separatorItem]
    ];
    for (NSMenuItem *item in items) {
        if ([item action]) [item setTarget:self];
        [menu addItem:item];
    }
    [menu addItem:[self comparisonExportMenuItem]];
    return menu;
}

