@interface RegressionComparisonView : NSView
@property(nonatomic, assign) RegressionComparisonWindowController *controller;
@end

@implementation RegressionComparisonView
- (NSString *)snapshotTabDelimitedText
{
    return _controller ? [_controller comparisonTableText] : @"";
}
- (BOOL)isFlipped { return YES; }

- (void)drawRect:(NSRect)dirtyRect
{
    (void)dirtyRect;
    [WorkbenchSurfaceColor() setFill];
    NSRectFill([self bounds]);
    if (!_controller) return;

    RegressionComparisonState *state = [_controller state];
    if (!state) return;
    RegressionComparisonLayout layout(state->showInformationCriteria);
    int termCount = (int)state->termRows.size();
    int modelCount = (int)state->models.size();

    NSMutableParagraphStyle *rightStyle = [[NSMutableParagraphStyle alloc] init];
    [rightStyle setAlignment:NSTextAlignmentRight];
    NSMutableParagraphStyle *centerStyle = [[NSMutableParagraphStyle alloc] init];
    [centerStyle setAlignment:NSTextAlignmentCenter];
    NSDictionary *leftAttrs = @{
        NSFontAttributeName: [NSFont systemFontOfSize:12],
        NSForegroundColorAttributeName: [NSColor colorWithCalibratedWhite:0.15 alpha:1.0]
    };
    NSDictionary *labelAttrs = @{
        NSFontAttributeName: [NSFont systemFontOfSize:12 weight:NSFontWeightSemibold],
        NSForegroundColorAttributeName: [NSColor colorWithCalibratedWhite:0.16 alpha:1.0]
    };
    NSDictionary *rightAttrs = @{
        NSFontAttributeName: [NSFont monospacedDigitSystemFontOfSize:12 weight:NSFontWeightRegular],
        NSForegroundColorAttributeName: [NSColor colorWithCalibratedWhite:0.15 alpha:1.0],
        NSParagraphStyleAttributeName: rightStyle
    };
	    NSDictionary *headerAttrs = @{
	        NSFontAttributeName: [NSFont systemFontOfSize:12 weight:NSFontWeightSemibold],
	        NSForegroundColorAttributeName: [NSColor colorWithCalibratedWhite:0.13 alpha:1.0],
	        NSParagraphStyleAttributeName: centerStyle
	    };
	    NSDictionary *centerMutedAttrs = @{
	        NSFontAttributeName: [NSFont systemFontOfSize:12],
	        NSForegroundColorAttributeName: [NSColor colorWithCalibratedWhite:0.56 alpha:1.0],
	        NSParagraphStyleAttributeName: centerStyle
	    };
	    NSDictionary *mutedRightAttrs = @{
	        NSFontAttributeName: [NSFont systemFontOfSize:12],
	        NSForegroundColorAttributeName: [NSColor colorWithCalibratedWhite:0.48 alpha:1.0],
	        NSParagraphStyleAttributeName: rightStyle
	    };

    [[NSColor colorWithCalibratedWhite:0.88 alpha:1.0] setStroke];
    NSBezierPath *rule = [NSBezierPath bezierPath];
    [rule moveToPoint:NSMakePoint(layout.margin, layout.margin + layout.headerHeight - 1.0)];
    [rule lineToPoint:NSMakePoint([self bounds].size.width - layout.margin, layout.margin + layout.headerHeight - 1.0)];
    [rule stroke];

    for (int m = 0; m < modelCount; ++m) {
        NSRect header = NSInsetRect(layout.modelHeaderRect(m), 4.0, 4.0);
        if (m == state->activeModel) {
            [[NSColor colorWithCalibratedWhite:0.94 alpha:1.0] setFill];
            NSRectFill(NSInsetRect(layout.modelHeaderRect(m), 2.0, 3.0));
        }
        NSString *title = ToNSString(state->models[(size_t)m].label.empty()
                                     ? rlispstat::core::NextUntitledRegressionLabel(*state)
                                     : state->models[(size_t)m].label);
        [title drawInRect:header withAttributes:headerAttrs];
    }
    [ToNSString(rlispstat::core::GLMAddModelLabel()) drawInRect:NSInsetRect(layout.addModelRect(modelCount), 4.0, 16.0) withAttributes:headerAttrs];

    for (int r = 0; r < termCount; ++r) {
        NSRect termRect = NSInsetRect(layout.termRect(r), 2.0, 4.0);
        std::string rawTerm = state->termRows[(size_t)r];
        std::string termLabel = RegressionComparisonDisplayLabel(*state, rawTerm);
	        [ToNSString(termLabel) drawInRect:termRect withAttributes:(r == 0 ? labelAttrs : leftAttrs)];
	        for (int m = 0; m < modelCount; ++m) {
	            NSRect cellRect = layout.coefficientRect(r, m);
	            if (r == [_controller selectedTermRow] && m == [_controller selectedModelColumn]) {
	                [[NSColor colorWithCalibratedWhite:0.93 alpha:1.0] setFill];
	                NSRectFill(NSInsetRect(cellRect, 2.0, 2.0));
	            }
	            NSString *value = [_controller displayForTerm:state->termRows[(size_t)r] modelColumn:m];
	            bool showAddGlyph = false;
	            bool showRemoveGlyph = false;
	            bool editableBaseTerm = r > 0 && rawTerm.find('=') == std::string::npos &&
	                (!state->precomputed || state->multipleImputation);
		            if (editableBaseTerm) {
		                const RegressionComparisonModel &model = state->models[(size_t)m];
		                std::string sourceTerm = RegressionComparisonSourceTerm(*state, rawTerm);
		                std::string response = model.response.empty() ? state->response : model.response;
		                bool termExists = ModelTermExistsForModel(&state->seed, sourceTerm, response);
		                bool included = rlispstat::core::ModelIncludesTerm(model, sourceTerm);
		                showAddGlyph = [value isEqualToString:@"\u2014"] && !included && termExists;
		                BOOL isFactorParent = NO;
		                for (const GLMCoefficientRow &row : model.fit.coefficients) {
		                    if (row.sourceTerm == rawTerm && row.term != rawTerm) {
		                        isFactorParent = YES;
		                        break;
		                    }
		                }
		                showRemoveGlyph = included && termExists && !isFactorParent;
		            }
		            if (showAddGlyph) {
	                [ToNSString(rlispstat::core::GLMPlusSignLabel()) drawInRect:NSInsetRect(cellRect, 4.0, 4.0) withAttributes:centerMutedAttrs];
	            } else {
	                NSDictionary *attrs = [value isEqualToString:@"\u2014"] ? mutedRightAttrs : rightAttrs;
	                [value drawInRect:NSInsetRect(cellRect, 4.0, 4.0) withAttributes:attrs];
	                if (showRemoveGlyph) {
	                    NSRect removeRect = NSMakeRect(NSMinX(cellRect) + 4.0, NSMinY(cellRect) + 4.0, 18.0, NSHeight(cellRect) - 8.0);
	                    [@"-" drawInRect:removeRect withAttributes:centerMutedAttrs];
	                }
	            }
	        }
	    }
    int addRow = termCount;
    [ToNSString(rlispstat::core::GLMAddTermLabel()) drawInRect:NSInsetRect(layout.termRect(addRow), 2.0, 4.0) withAttributes:labelAttrs];

    CGFloat sepY = layout.fitStartY(termCount) - 6.0;
    [[NSColor colorWithCalibratedWhite:0.86 alpha:1.0] setStroke];
    NSBezierPath *sep = [NSBezierPath bezierPath];
    [sep moveToPoint:NSMakePoint(layout.margin, sepY)];
    [sep lineToPoint:NSMakePoint([self bounds].size.width - layout.margin, sepY)];
    [sep stroke];

	    const std::vector<int> visibleFitRows = rlispstat::core::RegressionComparisonVisibleFitRows(state->showInformationCriteria);
	    for (int r = 0; r < layout.fitRows; ++r) {
	        const int rawFitRow = visibleFitRows[(size_t)r];
	        [ToNSString(rlispstat::core::RegressionComparisonFitLabel(rawFitRow, state->multipleImputation)) drawInRect:NSInsetRect(layout.fitLabelRect(r, termCount), 2.0, 4.0) withAttributes:labelAttrs];
	        for (int m = 0; m < modelCount; ++m) {
	            NSRect valueRect = layout.fitValueRect(r, termCount, m);
	            if (r == [_controller selectedFitRow] && m == [_controller selectedModelColumn]) {
	                [[NSColor colorWithCalibratedWhite:0.93 alpha:1.0] setFill];
	                NSRectFill(NSInsetRect(valueRect, 2.0, 2.0));
	            }
	            NSString *value = [_controller fitDisplayForRow:r modelColumn:m];
	            [value drawInRect:NSInsetRect(valueRect, 4.0, 4.0) withAttributes:rightAttrs];
	        }
	    }
    NSDictionary *noteAttrs = @{
        NSFontAttributeName: [NSFont systemFontOfSize:11],
        NSForegroundColorAttributeName: [NSColor colorWithCalibratedWhite:0.36 alpha:1.0]
    };
    CGFloat noteY = layout.fitStartY(termCount) + layout.rowHeight * (CGFloat)layout.fitRows + 8.0;
    [ToNSString(rlispstat::core::RegressionComparisonFootnote()) drawAtPoint:NSMakePoint(layout.margin, noteY) withAttributes:noteAttrs];
}

- (NSMenu *)menuForEvent:(NSEvent *)event
{
    NSPoint p = [self convertPoint:[event locationInWindow] fromView:nil];
    RegressionComparisonState *state = [_controller state];
    if (!state) return nil;
    RegressionComparisonLayout layout(state->showInformationCriteria);
    int termCount = (int)state->termRows.size();
    int modelCount = (int)state->models.size();
    for (int m = 0; m < modelCount; ++m) {
        if (NSPointInRect(p, layout.modelHeaderRect(m))) {
            [_controller modelHeaderClicked:m event:event];
            return SnapshotAlbumMenu([_controller contextMenuForModelColumn:m],
                                     @"Regression Model Comparison");
        }
    }
    if (NSPointInRect(p, layout.addModelRect(modelCount))) {
        return SnapshotAlbumMenu([_controller contextMenuForAddModel],
                                 @"Regression Model Comparison");
    }
    if (NSPointInRect(p, layout.termRect(termCount))) {
        return SnapshotAlbumMenu([_controller contextMenuForAddTerm],
                                 @"Regression Model Comparison");
    }
    for (int r = 0; r < termCount; ++r) {
        for (int m = 0; m < modelCount; ++m) {
            if (NSPointInRect(p, layout.coefficientRect(r, m))) {
                [_controller cellClickedAtTermRow:r modelColumn:m event:event];
                return SnapshotAlbumMenu([_controller contextMenuForTermRow:r modelColumn:m],
                                         @"Regression Model Comparison");
            }
        }
    }
    for (int r = 0; r < layout.fitRows; ++r) {
        for (int m = 0; m < modelCount; ++m) {
            if (NSPointInRect(p, layout.fitValueRect(r, termCount, m))) {
                [_controller fitCellClickedAtRow:r modelColumn:m event:event];
                return SnapshotAlbumMenu([_controller contextMenuForFitRow:r modelColumn:m],
                                         @"Regression Model Comparison");
            }
        }
    }
    return SnapshotAlbumMenu([_controller contextMenuForBackground],
                             @"Regression Model Comparison");
}

- (void)mouseDown:(NSEvent *)event
{
    NSPoint p = [self convertPoint:[event locationInWindow] fromView:nil];
    RegressionComparisonState *state = [_controller state];
    if (!state) return;
    RegressionComparisonLayout layout(state->showInformationCriteria);
    int termCount = (int)state->termRows.size();
    int modelCount = (int)state->models.size();
    for (int m = 0; m < modelCount; ++m) {
        if (NSPointInRect(p, layout.modelHeaderRect(m))) {
            [_controller modelHeaderClicked:m event:event];
            [self setNeedsDisplay:YES];
            return;
        }
    }
    if (NSPointInRect(p, layout.addModelRect(modelCount))) {
        [_controller addModelColumn:self];
        return;
    }
    if (NSPointInRect(p, layout.termRect(termCount))) {
        [_controller addTerm:self];
        return;
    }
    for (int r = 0; r < termCount; ++r) {
        for (int m = 0; m < modelCount; ++m) {
            NSRect cellRect = layout.coefficientRect(r, m);
            if (NSPointInRect(p, cellRect)) {
                if (r > 0 && (!state->precomputed || state->multipleImputation)) {
                    std::string rawTerm = state->termRows[(size_t)r];
                    if (rawTerm.find('=') == std::string::npos) {
                        const RegressionComparisonModel &model = state->models[(size_t)m];
                        std::string sourceTerm = RegressionComparisonSourceTerm(*state, rawTerm);
                        std::string response = model.response.empty() ? state->response : model.response;
                        NSRect removeRect = NSMakeRect(NSMinX(cellRect) + 4.0,
                                                       NSMinY(cellRect) + 4.0,
                                                       18.0,
                                                       NSHeight(cellRect) - 8.0);
                        if (rlispstat::core::ModelIncludesTerm(model, sourceTerm) &&
                            ModelTermExistsForModel(&state->seed, sourceTerm, response) &&
                            NSPointInRect(p, removeRect)) {
                            [_controller toggleTermAtRow:r modelColumn:m];
                            [self setNeedsDisplay:YES];
                            return;
                        }
                    }
                }
                [_controller cellClickedAtTermRow:r modelColumn:m event:event];
                [self setNeedsDisplay:YES];
                return;
            }
        }
    }
    for (int r = 0; r < layout.fitRows; ++r) {
        for (int m = 0; m < modelCount; ++m) {
            if (NSPointInRect(p, layout.fitValueRect(r, termCount, m))) {
                [_controller fitCellClickedAtRow:r modelColumn:m event:event];
                [self setNeedsDisplay:YES];
                return;
            }
        }
    }
}
@end

@implementation RegressionComparisonWindowController
- (instancetype)initWithComparisonId:(const std::string &)comparisonId
{
    self = [super init];
    if (self) {
        _comparisonId = comparisonId;
        _selectedTermRow = -1;
        _selectedModelColumn = -1;
        _selectedFitRow = -1;
        _window = [[NSWindow alloc]
            initWithContentRect:NSMakeRect(220, 180, 760, 520)
                      styleMask:(NSWindowStyleMaskTitled | NSWindowStyleMaskClosable |
                                 NSWindowStyleMaskMiniaturizable | NSWindowStyleMaskResizable)
                        backing:NSBackingStoreBuffered
                          defer:NO];
        [_window setTitle:ToNSString(rlispstat::core::RegressionModelComparisonTitle())];
        [_window setDelegate:self];
        [_window setContentMinSize:NSMakeSize(760, 420)];
        [_window setContentMaxSize:NSMakeSize(1800, 1400)];

        NSView *content = [_window contentView];
        [content setWantsLayer:YES];
        [[content layer] setBackgroundColor:[WorkbenchBackgroundColor() CGColor]];
        _titleField = GLMLabel(ToNSString(rlispstat::core::RegressionModelComparisonTitle()), NSMakeRect(14, 472, 280, 24), 17, NSFontWeightSemibold);
        [content addSubview:_titleField];
        _badgeField = GLMRightLabel(@"", NSMakeRect(610, 474, 130, 20), 12, NSFontWeightMedium);
        [content addSubview:_badgeField];
        _responseStaticLabel = GLMLabel(ToNSString(rlispstat::core::GLMResponseFieldLabel()), NSMakeRect(14, 438, 70, 22), 12, NSFontWeightRegular);
        [content addSubview:_responseStaticLabel];
        _responsePopup = [[NSPopUpButton alloc] initWithFrame:NSMakeRect(86, 434, 150, 28)];
        [_responsePopup setTarget:self];
        [_responsePopup setAction:@selector(responseChanged:)];
        [content addSubview:_responsePopup];
        _scopeStaticLabel = GLMLabel(ToNSString(rlispstat::core::GLMScopeFieldLabel()), NSMakeRect(254, 438, 46, 22), 12, NSFontWeightRegular);
        [content addSubview:_scopeStaticLabel];
        _scopePopup = [[NSPopUpButton alloc] initWithFrame:NSMakeRect(300, 434, 138, 28)];
        [_scopePopup addItemWithTitle:ToNSString(rlispstat::core::ScopeAllDataTitle())];
        [_scopePopup addItemWithTitle:ToNSString(rlispstat::core::ScopeSelectedRowsTitle())];
        [_scopePopup addItemWithTitle:ToNSString(rlispstat::core::ScopeUnselectedRowsTitle())];
        [_scopePopup setTarget:self];
        [_scopePopup setAction:@selector(scopeChanged:)];
        [content addSubview:_scopePopup];
        _autoRefitButton = [[NSButton alloc] initWithFrame:NSMakeRect(456, 438, 94, 22)];
        [_autoRefitButton setButtonType:NSButtonTypeSwitch];
        [_autoRefitButton setTitle:ToNSString(rlispstat::core::GLMAutoRefitButtonTitle())];
        [_autoRefitButton setTarget:self];
        [_autoRefitButton setAction:@selector(autoRefitChanged:)];
        [content addSubview:_autoRefitButton];
        _selectedRowsField = GLMRightLabel(@"", NSMakeRect(590, 438, 150, 20), 12, NSFontWeightRegular);
        [content addSubview:_selectedRowsField];

        _scrollView = [[NSScrollView alloc] initWithFrame:NSMakeRect(12, 46, 736, 380)];
        [_scrollView setBorderType:NSNoBorder];
        [_scrollView setDrawsBackground:NO];
        [_scrollView setHasVerticalScroller:YES];
        [_scrollView setHasHorizontalScroller:YES];
        [_scrollView setAutohidesScrollers:YES];
        [content addSubview:_scrollView];
        RegressionComparisonView *view = [[RegressionComparisonView alloc] initWithFrame:NSMakeRect(0, 0, 736, 380)];
        [view setController:self];
        _reportView = view;
        [_scrollView setDocumentView:_reportView];

        _statusField = GLMLabel(@"", NSMakeRect(14, 16, 720, 20), 12, NSFontWeightRegular);
        [content addSubview:_statusField];
        [self refresh];
    }
    return self;
}

- (RegressionComparisonState *)state
{
    auto it = g_regressionComparisons.find(_comparisonId);
    return it == g_regressionComparisons.end() ? nullptr : &it->second;
}

- (void)show
{
    [self activateDatasetForCommands];
    EnableNotesForWindow(_window, _comparisonId, @"this model comparison");
    [_window makeKeyAndOrderFront:nil];
    [_window orderFrontRegardless];
    [NSApp activateIgnoringOtherApps:YES];
}

- (void)activateDatasetForCommands
{
    RegressionComparisonState *state = [self state];
    if (!state) return;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        MarkActiveDatasetGroupUnlocked(state->group);
        EnsureDatasetSeedPlotUnlocked(state->group);
    }
    UpdateActiveDatasetMenuOnMain();
}

- (void)windowDidBecomeKey:(NSNotification *)notification
{
    (void)notification;
    [self activateDatasetForCommands];
}

- (BOOL)isVisible
{
    return [_window isVisible];
}

- (int)selectedTermRow { return _selectedTermRow; }
- (int)selectedModelColumn { return _selectedModelColumn; }
- (int)selectedFitRow { return _selectedFitRow; }

- (NSMenuItem *)comparisonMenuItem:(NSString *)title action:(SEL)action represented:(NSString *)represented
{
    NSMenuItem *item = [[NSMenuItem alloc] initWithTitle:title action:action keyEquivalent:@""];
    [item setTarget:self];
    if (represented) [item setRepresentedObject:represented];
    return item;
}

- (void)copyMenuValue:(id)sender
{
    NSString *value = [sender representedObject];
    if (!value) value = @"";
    NSPasteboard *pasteboard = [NSPasteboard generalPasteboard];
    [pasteboard clearContents];
    [pasteboard setString:value forType:NSPasteboardTypeString];
    [_statusField setStringValue:ToNSString(GLMValueCopiedStatus())];
}

- (void)openDiagnosticFromMenu:(id)sender
{
    NSString *kind = [sender representedObject];
    if (!kind) return;
    if (_selectedModelColumn < 0) _selectedModelColumn = 0;
    OpenRegressionComparisonDiagnosticPlot(_comparisonId, _selectedModelColumn, std::string([kind UTF8String]), true);
}

- (void)refitSelectedModel:(id)sender
{
    (void)sender;
    RegressionComparisonState *state = [self state];
    if (!state) return;
    if (_selectedModelColumn < 0) _selectedModelColumn = std::max(0, state->activeModel);
    if (state->precomputed) {
        if (state->multipleImputation) {
            [self refitPooledMIComparisonWithStatus:ToNSString(rlispstat::core::PooledMIComparisonRefitStatus("", true))];
        } else {
            [_statusField setStringValue:ToNSString(rlispstat::core::PrecomputedComparisonChangeInRStatus("comparison"))];
        }
        return;
    }
    [self refitModelColumn:_selectedModelColumn];
    [self refresh];
    [_statusField setStringValue:ToNSString(rlispstat::core::RegressionComparisonRefittedStatus())];
}

- (void)toggleAutoRefitFromMenu:(id)sender
{
    (void)sender;
    RegressionComparisonState *state = [self state];
    if (!state) return;
    if (state->precomputed) {
        [_statusField setStringValue:ToNSString(rlispstat::core::PooledOrPrecomputedRefitLayerStatus())];
        return;
    }
    state->autoRefit = !state->autoRefit;
    if (state->autoRefit) RefitRegressionComparisonModels(*state, false);
    [self refresh];
}

- (void)showRowsUsedExcluded:(id)sender
{
    (void)sender;
    RegressionComparisonState *state = [self state];
    if (!state) return;
    if (_selectedModelColumn < 0) _selectedModelColumn = std::max(0, state->activeModel);
    if (_selectedModelColumn < 0 || (size_t)_selectedModelColumn >= state->models.size()) return;
    const RegressionComparisonModel &model = state->models[(size_t)_selectedModelColumn];
    if (!model.fit.ok) {
        [_statusField setStringValue:ToNSString(GLMStatusMessage(model.fit.warning))];
        return;
    }
    ShowWorkbenchMessageOnMain(ToNSString(rlispstat::core::RowsUsedExcludedWindowTitle()),
                               ToNSString(rlispstat::core::RowsUsedExcludedText(model.fit.rowsUsed,
                                                                                 model.fit.rowsExcluded,
                                                                                 model.label)));
}

- (void)showSelectedFitDetails:(id)sender
{
    (void)sender;
    RegressionComparisonState *state = [self state];
    if (!state || _selectedFitRow < 0 ||
        _selectedModelColumn < 0 || (size_t)_selectedModelColumn >= state->models.size()) return;
    const RegressionComparisonModel &model = state->models[(size_t)_selectedModelColumn];
    if (!model.fit.ok) {
        [_statusField setStringValue:ToNSString(GLMStatusMessage(model.fit.warning))];
        return;
    }
    const std::vector<int> visibleRows = rlispstat::core::RegressionComparisonVisibleFitRows(
        state->showInformationCriteria);
    if ((size_t)_selectedFitRow >= visibleRows.size()) return;
    const int rawFitRow = visibleRows[(size_t)_selectedFitRow];
    if (rlispstat::core::RegressionComparisonFitRowIsModelTest(rawFitRow)) {
        if (_selectedModelColumn <= 0) {
            [_statusField setStringValue:ToNSString(rlispstat::core::RegressionComparisonNoPreviousModelStatus())];
            return;
        }
        NestedModelTestResult test = RegressionAdjacentModelTest(*state, _selectedModelColumn);
        if (!test.ok) {
            [_statusField setStringValue:ToNSString(rlispstat::core::RegressionComparisonUnavailableStatus())];
            return;
        }
        const RegressionComparisonModel &previous = state->models[(size_t)_selectedModelColumn - 1];
        [_statusField setStringValue:ToNSString(rlispstat::core::RegressionComparisonModelTestStatus(
            model.label, previous.label, test, state->multipleImputation))];
        return;
    }
    std::string label = rlispstat::core::RegressionComparisonFitLabel(rawFitRow, state->multipleImputation);
    NSString *value = [self fitDisplayForRow:_selectedFitRow modelColumn:_selectedModelColumn];
    [_statusField setStringValue:ToNSString(RegressionComparisonFitValueStatus(model.label, label,
                                                                                std::string([value UTF8String])))];
}

- (NSMenu *)contextMenuForAddTerm
{
    const auto titles = rlispstat::core::DefaultModelContextMenuTitles();
    NSMenu *menu = [[NSMenu alloc] initWithTitle:ToNSString(titles.addTerm)];
    [menu addItem:[self comparisonMenuItem:ToNSString(titles.addTermAction) action:@selector(addTerm:) represented:nil]];
    return menu;
}

- (NSMenu *)contextMenuForAddModel
{
    const auto titles = rlispstat::core::DefaultModelContextMenuTitles();
    NSMenu *menu = [[NSMenu alloc] initWithTitle:ToNSString(titles.addModel)];
    [menu addItem:[self comparisonMenuItem:ToNSString(titles.addModelFromActiveModel) action:@selector(addModelColumn:) represented:nil]];
    [menu addItem:[self comparisonExportMenuItem]];
    return menu;
}

- (NSMenu *)contextMenuForBackground
{
    RegressionComparisonState *state = [self state];
    const auto titles = rlispstat::core::DefaultModelContextMenuTitles();
    NSMenu *menu = [[NSMenu alloc] initWithTitle:ToNSString(titles.modelComparison)];
    [menu addItem:[self comparisonMenuItem:ToNSString(titles.addTermAction) action:@selector(addTerm:) represented:nil]];
    [menu addItem:[self comparisonMenuItem:ToNSString(titles.addModelFromActiveModel) action:@selector(addModelColumn:) represented:nil]];
    [menu addItem:[NSMenuItem separatorItem]];
    [menu addItem:[self comparisonMenuItem:ToNSString(titles.refitActiveModel) action:@selector(refitSelectedModel:) represented:nil]];
    [menu addItem:[self comparisonMenuItem:ToNSString(rlispstat::core::AutoRefitMenuTitle(state && state->autoRefit))
                                    action:@selector(toggleAutoRefitFromMenu:) represented:nil]];
    NSMenuItem *informationCriteria = [self comparisonMenuItem:@"Information criteria"
        action:@selector(toggleInformationCriteria:) represented:nil];
    [informationCriteria setState:state && state->showInformationCriteria
        ? NSControlStateValueOn : NSControlStateValueOff];
    [menu addItem:informationCriteria];
    [menu addItem:[NSMenuItem separatorItem]];
    [menu addItem:[self comparisonExportMenuItem]];
    return menu;
}

- (NSMenu *)contextMenuForFitRow:(int)fitRow modelColumn:(int)modelColumn
{
    _selectedTermRow = -1;
    _selectedFitRow = fitRow;
    _selectedModelColumn = modelColumn;
    NSString *value = [self fitDisplayForRow:fitRow modelColumn:modelColumn];
    const auto titles = rlispstat::core::DefaultModelContextMenuTitles();
    NSMenu *menu = [[NSMenu alloc] initWithTitle:ToNSString(titles.modelFit)];
    [menu addItem:[self comparisonMenuItem:ToNSString(titles.copyValue) action:@selector(copyMenuValue:) represented:value]];
    [menu addItem:[self comparisonMenuItem:ToNSString(titles.showStatisticDetails) action:@selector(showSelectedFitDetails:) represented:nil]];
    [menu addItem:[NSMenuItem separatorItem]];
    NSMenuItem *diagnosticsItem = [[NSMenuItem alloc] initWithTitle:ToNSString(titles.openDiagnostics) action:nil keyEquivalent:@""];
    NSMenu *diagMenu = [[NSMenu alloc] initWithTitle:ToNSString(titles.openDiagnostics)];
    AddModelDiagnosticPlotMenuItems(diagMenu, self, @selector(openDiagnosticFromMenu:), false);
    [menu setSubmenu:diagMenu forItem:diagnosticsItem];
    [menu addItem:diagnosticsItem];
    [menu addItem:[self comparisonMenuItem:ToNSString(titles.openSingleGLM) action:@selector(openSelectedModelAsGLM:) represented:nil]];
    [menu addItem:[self comparisonMenuItem:ToNSString(titles.rowsUsedExcluded) action:@selector(showRowsUsedExcluded:) represented:nil]];
    [menu addItem:[NSMenuItem separatorItem]];
    [menu addItem:[self comparisonMenuItem:ToNSString(titles.refitActiveModel) action:@selector(refitSelectedModel:) represented:nil]];
    [menu addItem:[self comparisonExportMenuItem]];
    return menu;
}

- (void)refresh
{
    RegressionComparisonState *state = [self state];
    if (!state) return;
    if (!state->precomputed && state->autoRefit) {
        RefitRegressionComparisonModels(*state, false);
    }
    std::string title = state->title.empty() ? "Regression Model Comparison" : state->title;
    [_titleField setStringValue:ToNSString(title)];
    [_window setTitle:ToNSString(title)];
    [_badgeField setStringValue:ToNSString(state->multipleImputation && state->imputationCount > 0
        ? "m = " + std::to_string(state->imputationCount)
        : state->group)];
    [_responsePopup removeAllItems];
    for (const NumericVariable &var : state->seed.variables) {
        [_responsePopup addItemWithTitle:ToNSString(var.name)];
    }
    [_responsePopup selectItemWithTitle:ToNSString(state->response)];
    [_scopePopup selectItemAtIndex:(state->scope == "selected" ? 1 : (state->scope == "unselected" ? 2 : 0))];
    [_autoRefitButton setState:state->autoRefit ? NSControlStateValueOn : NSControlStateValueOff];
    [_responsePopup setEnabled:(!state->precomputed || state->multipleImputation)];
    [_scopePopup setEnabled:(!state->dataScopeCaptured &&
        (!state->precomputed || state->multipleImputation))];
    [_autoRefitButton setEnabled:!state->precomputed];
    size_t selected = SelectionCount(state->group);
    size_t n = state->seed.variables.empty() ? 0 : state->seed.variables.front().values.size();
    [_selectedRowsField setStringValue:ToNSString(rlispstat::core::SelectedRowsStatus(selected, n))];

    RegressionComparisonLayout layout(state->showInformationCriteria);
    NSSize wanted = NSMakeSize(layout.width((int)state->models.size()), layout.height((int)state->termRows.size()));
    NSSize contentSize = [[_window contentView] frame].size;
    NSScreen *screen = [_window screen] ?: [NSScreen mainScreen];
    CGFloat maxHeight = screen ? std::max((CGFloat)420.0, [screen visibleFrame].size.height * 0.86) : (CGFloat)760.0;
    CGFloat targetHeight = std::min(maxHeight, std::max((CGFloat)520.0, wanted.height + 140.0));
    if (std::fabs(contentSize.height - targetHeight) > 0.5) {
        [_window setContentMaxSize:NSMakeSize(10000.0, maxHeight)];
        [_window setContentSize:NSMakeSize(contentSize.width, targetHeight)];
        contentSize = [[_window contentView] frame].size;
    }
    CGFloat h = contentSize.height;
    CGFloat w = contentSize.width;
    [_titleField setFrame:NSMakeRect(14, h - 48, 280, 24)];
    [_badgeField setFrame:NSMakeRect(w - 150, h - 46, 130, 20)];
    [_responseStaticLabel setFrame:NSMakeRect(14, h - 82, 70, 22)];
    [_responsePopup setFrame:NSMakeRect(86, h - 86, 150, 28)];
    [_scopeStaticLabel setFrame:NSMakeRect(254, h - 82, 46, 22)];
    [_scopePopup setFrame:NSMakeRect(300, h - 86, 138, 28)];
    [_autoRefitButton setFrame:NSMakeRect(456, h - 82, 94, 22)];
    [_selectedRowsField setFrame:NSMakeRect(w - 170, h - 82, 150, 20)];
    [_scrollView setFrame:NSMakeRect(12, 46, std::max((CGFloat)200.0, w - 24.0), std::max((CGFloat)140.0, h - 140.0))];
    [_statusField setFrame:NSMakeRect(14, 16, std::max((CGFloat)200.0, w - 28.0), 20)];
    [_reportView setFrame:NSMakeRect(0, 0, wanted.width, wanted.height)];
    [_reportView setNeedsDisplay:YES];
    std::string status = rlispstat::core::RegressionComparisonSummaryStatus(
        state->models.size(), state->termRows.size(),
        state->precomputed || state->multipleImputation, state->note);
    if (state->dataScopeCaptured) {
        status += " · " + rlispstat::core::AnalysisScopeWindowSummary(
            state->dataScope, state->dataScope.totalDatasetRows);
    }
    [_statusField setStringValue:ToNSString(status)];
}

- (void)refitPooledMIComparisonWithStatus:(NSString *)status
{
    RegressionComparisonState *state = [self state];
    if (!state || !state->multipleImputation) return;
    DataFrameModel df;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        const DataFrameModel *found = FindDataFrameUnlockedConst(state->group);
        if (found) df = *found;
    }
    if (df.group.empty()) {
        [_statusField setStringValue:ToNSString(GLMImputedDatasetUnavailableStatus())];
        return;
    }
    std::string comparisonId = state->id;
    std::string response = state->response;
    std::string scope = state->scope;
    std::string modelSpec = rlispstat::core::EncodePooledRegressionComparisonModelSpec(*state);
    [_statusField setStringValue:status ?: ToNSString(rlispstat::core::PooledMIComparisonRefitStatus())];
    std::thread worker([df, comparisonId, response, scope, modelSpec]() {
        std::string message;
        bool ok = RunRBackedMultipleImputationAnalysis(
            df, "regcmp", comparisonId,
            std::vector<std::string>(), "", response, std::vector<std::string>(), scope, &message, modelSpec);
        if (!ok) ShowWorkbenchMessageOnMain(ToNSString(rlispstat::core::RegressionModelComparisonTitle()), ToNSString(message));
    });
    worker.detach();
}

- (void)refitModelColumn:(int)modelColumn
{
    RegressionComparisonState *state = [self state];
    if (!state || modelColumn < 0 || (size_t)modelColumn >= state->models.size()) return;
    if (state->precomputed) {
        if (state->multipleImputation) {
            [self refitPooledMIComparisonWithStatus:ToNSString(rlispstat::core::PooledMIComparisonRefitStatus())];
        } else {
            [_statusField setStringValue:ToNSString(rlispstat::core::PrecomputedComparisonChangeInRStatus("model"))];
        }
        return;
    }
    RegressionComparisonModel &model = state->models[(size_t)modelColumn];
    model.modelVersion += 1;
    model.isStale = true;
    if (state->autoRefit) {
        RefitRegressionComparisonModel(*state, model);
        RefreshRegressionComparisonDiagnosticsForModelNow(model.id);
    }
}

- (void)addTerm:(id)sender
{
    RegressionComparisonState *state = [self state];
    if (!state) return;
    if (state->precomputed && !state->multipleImputation) {
        [_statusField setStringValue:ToNSString(rlispstat::core::PrecomputedComparisonChangeInRStatus("comparison"))];
        return;
    }
    NSMenu *menu = [[NSMenu alloc] initWithTitle:ToNSString(rlispstat::core::GLMAddTermTitle())];
    int active = std::max(0, std::min(state->activeModel, (int)state->models.size() - 1));
    RegressionComparisonModel *activeModel = state->models.empty() ? nullptr : &state->models[(size_t)active];
    std::string activeResponse = activeModel && !activeModel->response.empty() ? activeModel->response : state->response;
    for (const std::string &name : VariableNamesForModel(&state->seed)) {
        if (name == activeResponse || (activeModel && rlispstat::core::ModelIncludesTerm(*activeModel, name))) continue;
        NSMenuItem *item = [[NSMenuItem alloc] initWithTitle:ToNSString(name) action:@selector(addTermFromMenu:) keyEquivalent:@""];
        [item setTarget:self];
        [item setRepresentedObject:ToNSString(name)];
        [menu addItem:item];
    }
    if ([menu numberOfItems] > 0) {
        [menu addItem:[NSMenuItem separatorItem]];
    }
    std::vector<std::string> interactionBase = activeModel ? activeModel->includedTerms : std::vector<std::string>();
    std::vector<std::vector<std::string>> comparisonTerms;
    for (const RegressionComparisonModel &model : state->models) {
        comparisonTerms.push_back(model.includedTerms);
    }
    if (!AddComparisonInteractionMenuItems(menu, self, @selector(addTermFromMenu:), &state->seed,
                                           activeResponse, comparisonTerms, interactionBase)) {
        NSInteger last = [menu numberOfItems] - 1;
        if (last >= 0 && [[menu itemAtIndex:last] isSeparatorItem]) {
            [menu removeItemAtIndex:last];
        }
    }
    if ([[menu itemArray] count] == 0) {
        [_statusField setStringValue:ToNSString(rlispstat::core::ComparisonNoAvailableTermsStatus())];
        return;
    }
    [menu popUpMenuPositioningItem:nil atLocation:NSMakePoint(20, 20) inView:_reportView];
}

- (void)addTermFromMenu:(id)sender
{
    NSString *name = [sender representedObject];
    if (!name) return;
    RegressionComparisonState *state = [self state];
    if (!state) return;
    if (state->precomputed && !state->multipleImputation) {
        [_statusField setStringValue:ToNSString(rlispstat::core::PrecomputedComparisonChangeInRStatus("comparison"))];
        return;
    }
    std::string term = [name UTF8String];
    int active = std::max(0, std::min(state->activeModel, (int)state->models.size() - 1));
    RegressionComparisonModel &model = state->models[(size_t)active];
    if (AddHierarchicalRegressionComparisonTerm(*state, model, term)) {
        if (state->precomputed && state->multipleImputation) {
            [self refitPooledMIComparisonWithStatus:ToNSString(rlispstat::core::PooledMIComparisonRefitStatus("after adding " + term))];
        } else {
            [self refitModelColumn:active];
            [self refresh];
        }
    }
}

	- (void)addModelColumn:(id)sender
	{
	    RegressionComparisonState *state = [self state];
	    if (!state) return;
	    if (state->precomputed && !state->multipleImputation) {
	        [_statusField setStringValue:ToNSString(rlispstat::core::PrecomputedComparisonChangeInRStatus("comparison"))];
	        return;
	    }
	    int source = std::max(0, std::min(state->activeModel, (int)state->models.size() - 1));
	    RegressionComparisonModel model;
	    model.id = rlispstat::core::NextRegressionModelId(*state);
    model.label = state->models.empty()
        ? rlispstat::core::NextUntitledRegressionLabel(*state)
        : rlispstat::core::UniqueRegressionCopyLabel(*state, state->models[(size_t)source].label);
	    if (!state->models.empty()) model.includedTerms = state->models[(size_t)source].includedTerms;
	    model.response = state->models.empty() ? state->response : state->models[(size_t)source].response;
	    state->models.push_back(model);
	    state->activeModel = (int)state->models.size() - 1;
	    _selectedModelColumn = state->activeModel;
	    _selectedTermRow = -1;
	    _selectedFitRow = -1;
	    if (state->precomputed && state->multipleImputation) {
	        [self refitPooledMIComparisonWithStatus:ToNSString(rlispstat::core::PooledMIComparisonRefitStatus("after adding a model"))];
	    } else {
	        RefitRegressionComparisonModel(*state, state->models.back());
	        [self refresh];
	    }
	}

- (void)modelHeaderClicked:(int)modelColumn event:(NSEvent *)event
{
    (void)event;
    RegressionComparisonState *state = [self state];
    if (!state || modelColumn < 0 || (size_t)modelColumn >= state->models.size()) return;
    state->activeModel = modelColumn;
    _selectedModelColumn = modelColumn;
    _selectedTermRow = -1;
    _selectedFitRow = -1;
}

- (void)toggleTermAtRow:(int)termRow modelColumn:(int)modelColumn
{
    RegressionComparisonState *state = [self state];
    if (!state || termRow <= 0 || (size_t)termRow >= state->termRows.size() ||
        modelColumn < 0 || (size_t)modelColumn >= state->models.size()) return;
    state->activeModel = modelColumn;
    _selectedTermRow = termRow;
    _selectedModelColumn = modelColumn;
    _selectedFitRow = -1;
    [self toggleSelectedTerm:nil];
}

	- (void)cellClickedAtTermRow:(int)termRow modelColumn:(int)modelColumn event:(NSEvent *)event
	{
	    RegressionComparisonState *state = [self state];
	    if (!state || termRow < 0 || (size_t)termRow >= state->termRows.size() ||
	        modelColumn < 0 || (size_t)modelColumn >= state->models.size()) return;
	    state->activeModel = modelColumn;
	    _selectedTermRow = termRow;
	    _selectedModelColumn = modelColumn;
	    _selectedFitRow = -1;
	    BOOL toggle = [event clickCount] >= 2 || (([event modifierFlags] & NSEventModifierFlagOption) != 0);
	    BOOL canEdit = (!state->precomputed || state->multipleImputation);
	    if (termRow > 0) {
	        std::string term = RegressionComparisonSourceTerm(*state, state->termRows[(size_t)termRow]);
	        RegressionComparisonModel &model = state->models[(size_t)modelColumn];
	        bool included = rlispstat::core::ModelIncludesTerm(model, term);
	        if (toggle && canEdit) {
	            [self toggleSelectedTerm:nil];
	        } else if (toggle && state->precomputed) {
	            [_statusField setStringValue:ToNSString(rlispstat::core::PooledMIComparisonChangeInRStatus())];
	        } else if (!included && canEdit) {
	            [self toggleSelectedTerm:nil];
	        } else {
	            [self showCoefficientDetails:nil];
	        }
	    }
	}

	- (void)fitCellClickedAtRow:(int)fitRow modelColumn:(int)modelColumn event:(NSEvent *)event
	{
	    (void)event;
	    RegressionComparisonState *state = [self state];
	    if (!state || modelColumn < 0 || (size_t)modelColumn >= state->models.size()) return;
	    state->activeModel = modelColumn;
	    _selectedModelColumn = modelColumn;
	    _selectedTermRow = -1;
	    _selectedFitRow = fitRow;
	    [self showSelectedFitDetails:nil];
	}

- (NSString *)displayForTerm:(const std::string &)term modelColumn:(int)modelColumn
{
    RegressionComparisonState *state = [self state];
    if (!state || modelColumn < 0 || (size_t)modelColumn >= state->models.size()) return @"";
    const RegressionComparisonModel &model = state->models[(size_t)modelColumn];
    BOOL isFactorParent = NO;
    if (term != "(Intercept)" && term.find('=') == std::string::npos) {
        for (const GLMCoefficientRow &row : model.fit.coefficients) {
            if (row.sourceTerm == term && row.term != term) {
                isFactorParent = YES;
                break;
            }
        }
    }
    if (isFactorParent) {
        if (!rlispstat::core::TermListContainsEquivalentModelTerm(model.includedTerms, term)) {
            return @"\U00002014";
        }
        return @"";
    }
    return ToNSString(rlispstat::core::RegressionCoefficientDisplay(model.fit, model.includedTerms, term));
}

- (NSString *)fitDisplayForRow:(int)fitRow modelColumn:(int)modelColumn
{
    RegressionComparisonState *state = [self state];
    if (!state || modelColumn < 0 || (size_t)modelColumn >= state->models.size()) return @"";
    const std::vector<int> visibleRows = rlispstat::core::RegressionComparisonVisibleFitRows(
        state->showInformationCriteria);
    if (fitRow < 0 || (size_t)fitRow >= visibleRows.size()) return @"";
    const int rawFitRow = visibleRows[(size_t)fitRow];
    const RegressionComparisonModel &model = state->models[(size_t)modelColumn];
    const GLMFitSummary &fit = state->models[(size_t)modelColumn].fit;
    if (rawFitRow >= 13 && rawFitRow <= 15) {
        const GLMFitSummary *previous = modelColumn > 0
            ? &state->models[(size_t)modelColumn - 1].fit : nullptr;
        return ToNSString(rlispstat::core::RegressionComparisonChangeDisplay(fit, previous, rawFitRow));
    }
    if (rawFitRow == 16 || rawFitRow == 17) {
        const bool useAIC = rawFitRow == 16;
        double minimum = INFINITY;
        for (const RegressionComparisonModel &candidate : state->models) {
            const double value = useAIC ? candidate.fit.aic : candidate.fit.bic;
            if (candidate.fit.ok && std::isfinite(value)) minimum = std::min(minimum, value);
        }
        const double value = useAIC ? fit.aic : fit.bic;
        return fit.ok && std::isfinite(value) && std::isfinite(minimum)
            ? ToNSString(FormatDoubleOrDash(value - minimum, 2)) : @"—";
    }
    return ToNSString(rlispstat::core::RegressionComparisonFitDisplay(
        fit, RegressionAdjacentModelTest(*state, modelColumn), rawFitRow));
}

- (NSString *)comparisonTableText
{
    RegressionComparisonState *state = [self state];
    if (!state) return @"";
    rlispstat::core::ComparisonCopyTable table;
    table.title = "Regression Model Comparison";
    table.response = state->response;
    for (const RegressionComparisonModel &model : state->models) {
        table.modelLabels.push_back(model.label);
        table.modelResponses.push_back(model.response.empty() ? state->response : model.response);
    }
    for (const std::string &term : state->termRows) {
        table.termLabels.push_back(RegressionComparisonDisplayLabel(*state, term));
        std::vector<std::string> cells;
        for (size_t m = 0; m < state->models.size(); ++m) {
            cells.push_back([[self displayForTerm:term modelColumn:(int)m] UTF8String]);
        }
        table.termDisplaysByRow.push_back(cells);
    }
    RegressionComparisonLayout layout(state->showInformationCriteria);
    for (int r = 0; r < layout.fitRows; ++r) {
        const std::vector<int> visibleRows = rlispstat::core::RegressionComparisonVisibleFitRows(
            state->showInformationCriteria);
        table.fitLabels.push_back(rlispstat::core::RegressionComparisonFitLabel(
            visibleRows[(size_t)r], state->multipleImputation));
        std::vector<std::string> cells;
        for (size_t m = 0; m < state->models.size(); ++m) {
            cells.push_back([[self fitDisplayForRow:r modelColumn:(int)m] UTF8String]);
        }
        table.fitDisplaysByRow.push_back(cells);
    }
    table.footnote = rlispstat::core::RegressionComparisonFootnote();
    return ToNSString(rlispstat::core::ComparisonCopyTableText(table));
}

- (NSMenuItem *)comparisonExportMenuItem
{
    RegressionComparisonState *state = [self state];
    NSMenuItem *root = [[NSMenuItem alloc] initWithTitle:@"Export" action:nil keyEquivalent:@""];
    NSMenu *menu = [[NSMenu alloc] initWithTitle:@"Export"];
    AddStandardTableVisualExportItems(menu, _reportView, @"Regression Model Comparison",
        state ? ToNSString(state->id.empty() ? "regression-model-comparison" : state->id) : @"regression-model-comparison",
        [self comparisonTableText]);
    [menu addItem:[NSMenuItem separatorItem]];
    NSMenuItem *copy = [[NSMenuItem alloc] initWithTitle:@"Copy table with headers" action:@selector(copyComparisonTable:) keyEquivalent:@""];
    [copy setTarget:self]; [menu addItem:copy];
