- (void)deleteSelectedModel:(id)sender
{
    (void)sender;
	    RegressionComparisonState *state = [self state];
	    if (!state || state->models.size() <= 1 || _selectedModelColumn < 0 ||
	        (size_t)_selectedModelColumn >= state->models.size()) return;
	    if (state->precomputed && !state->multipleImputation) {
	        [_statusField setStringValue:ToNSString(rlispstat::core::PrecomputedComparisonChangeInRStatus("comparison"))];
	        return;
	    }
	    state->models.erase(state->models.begin() + _selectedModelColumn);
	    state->activeModel = std::max(0, std::min(_selectedModelColumn, (int)state->models.size() - 1));
	    _selectedModelColumn = state->activeModel;
	    _selectedTermRow = -1;
	    _selectedFitRow = -1;
	    if (state->precomputed && state->multipleImputation) {
	        [self refitPooledMIComparisonWithStatus:ToNSString(rlispstat::core::PooledMIComparisonRefitStatus("after deleting a model"))];
	    } else {
	        [self refresh];
	    }
}

