- (void)openSelectedModelAsGLM:(id)sender
{
    (void)sender;
    RegressionComparisonState *state = [self state];
    if (!state || _selectedModelColumn < 0 || (size_t)_selectedModelColumn >= state->models.size()) return;
    RegressionComparisonModel &model = state->models[(size_t)_selectedModelColumn];
    if (state->precomputed && !model.fit.ok) {
        [_statusField setStringValue:ToNSString(GLMStatusMessage(model.fit.warning))];
        return;
    }
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        GroupModelState &glm = EnsureGroupModelUnlocked(state->group, &state->seed);
        glm.dependent = model.response.empty() ? state->response : model.response;
        glm.terms = model.includedTerms;
        glm.termTypes = state->termTypes;
        glm.scope = state->scope;
        if (state->precomputed) {
            PopulateMissingStandardizedBetas(model.fit, state->seed, glm.dependent);
            glm.precomputed = true;
            glm.multipleImputation = state->multipleImputation;
            glm.imputationCount = state->imputationCount;
            glm.title = model.label.empty() ? "General Linear Model" : ("General Linear Model - " + model.label);
            glm.note = state->note.empty()
                ? "Pooled/precomputed linear model opened from model comparison."
                : state->note;
            glm.modelVersion += 1;
            glm.fitVersion += 1;
            glm.diagnosticsVersion += 1;
            glm.isStale = false;
            glm.diagnostics = model.fit.diagnostics;
            glm.rowsUsed = model.fit.rowsUsed;
            glm.rowsExcluded = model.fit.rowsExcluded;
            g_precomputedLinearModelFits[state->group] = model.fit;
        } else {
            rlispstat::core::MarkGroupModelChanged(glm);
        }
    }
    ShowGLMOnMain(&state->seed);
    [_statusField setStringValue:ToNSString(RegressionComparisonOpenedSingleModelStatus(model.label))];
}

