- (NSInteger)coefficientRowCount
{
    GLMFitSummary fit = [self currentFit];
    if (fit.ok) {
        return (NSInteger)fit.coefficients.size() + 1; // coefficients plus add-term row
    }
    std::lock_guard<std::mutex> lock(g_mutex);
    GroupModelState &state = EnsureGroupModelUnlocked(_model->group, _model);
    return (NSInteger)state.terms.size() + 2;
}

- (NSString *)coefficientColumnIdentifier:(NSInteger)column
{
    static NSString *ids[] = { @"term", @"type", @"estimate", @"beta", @"stderr", @"stat", @"p", @"partial" };
    return (column >= 0 && column < 8) ? ids[column] : @"";
}

- (NSString *)coefficientValueForRow:(NSInteger)row column:(NSInteger)column
{
    NSString *identifier = [self coefficientColumnIdentifier:column];
    std::string dependent;
    std::vector<std::string> terms;
    std::map<std::string, std::string> termTypes;
    std::string scope;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        GroupModelState &state = EnsureGroupModelUnlocked(_model->group, _model);
        dependent = state.dependent.empty() ? _model->yLabel : state.dependent;
        terms = state.terms;
        termTypes = state.termTypes;
        scope = state.scope == "compare_selected_all" ? "all" : state.scope;
    }
    GLMFitSummary fit = [self currentFit];
    bool fitRows = fit.ok;
    bool isAdd = fitRows ? row == (NSInteger)fit.coefficients.size() : row == (NSInteger)terms.size() + 1;
    bool isIntercept = row == 0 && !isAdd;
    GLMCoefficientRow coef;
    bool hasCoef = fitRows && row >= 0 && row < (NSInteger)fit.coefficients.size();
    if (hasCoef) coef = fit.coefficients[(size_t)row];
    bool parentRow = hasCoef && (coef.rowType == "factor_parent" || coef.rowType == "term_parent");
    bool referenceRow = hasCoef && coef.rowType == "reference";
    bool interactionChildRow = hasCoef &&
        rlispstat::core::ModelTermTypeIsInteraction(coef.termType) &&
        coef.rowType == "coefficient" &&
        !coef.sourceTerm.empty() &&
        coef.sourceTerm != coef.term;
    NSInteger termIndex = row - 1;
    std::string term = hasCoef ? (coef.displayLabel.empty() ? coef.term : coef.displayLabel) : (isIntercept ? "(Intercept)" : (isAdd ? "+ Add term" :
        ((termIndex >= 0 && (size_t)termIndex < terms.size()) ? terms[(size_t)termIndex] : "")));
    if ([identifier isEqualToString:@"term"]) {
        return ToNSString(term);
    }
    if ([identifier isEqualToString:@"type"]) {
        if (isIntercept) return @"-";
        if (isAdd || term.empty()) return @"";
        if (hasCoef && (coef.rowType == "reference" || coef.rowType == "factor_level" || interactionChildRow)) return @"";
        return ToNSString(rlispstat::core::ModelTermTypeDisplayName(hasCoef ? coef.termType : rlispstat::core::ModelTermDisplayType(_model, term, termTypes)));
    }
    if ([identifier isEqualToString:@"estimate"]) {
        if (parentRow) return @"";
        return (hasCoef && !referenceRow) ? ToNSString(FormatDouble(coef.estimate, 4)) : @"\U00002014";
    }
    if ([identifier isEqualToString:@"beta"]) {
        if (parentRow) return @"";
        return (hasCoef && !referenceRow && std::isfinite(coef.standardizedBeta)) ? ToNSString(FormatDouble(coef.standardizedBeta, 3)) : @"\U00002014";
    }
    if ([identifier isEqualToString:@"stderr"]) {
        if (parentRow) return @"";
        return (hasCoef && !referenceRow) ? ToNSString(FormatDouble(coef.stdError, 4)) : @"\U00002014";
    }
    if ([identifier isEqualToString:@"stat"]) {
        if (parentRow) return @"";
        return (hasCoef && !referenceRow) ? ToNSString(FormatDouble(coef.tValue, 3)) : @"\U00002014";
    }
    if ([identifier isEqualToString:@"p"]) {
        if (parentRow) return @"";
        return (hasCoef && !referenceRow) ? ToNSString(FormatPValue(coef.pValue)) : @"\U00002014";
    }
    if ([identifier isEqualToString:@"partial"]) {
        if (parentRow) return @"";
        return (hasCoef && !referenceRow && std::isfinite(coef.partialR2)) ? ToNSString(FormatDouble(coef.partialR2, 3)) : @"\U00002014";
    }
    return @"";
}

- (GLMFitSummary)currentFit
{
    std::string dependent;
    std::vector<std::string> terms;
    std::map<std::string, std::string> termTypes;
    std::string scope;
    std::string group;
    std::string signature;
    bool shouldQueueRFit = false;
    bool hasCachedFit = false;
    GLMFitSummary cachedFit;
    MainRLinearGLMTask task;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        GroupModelState &state = EnsureGroupModelUnlocked(_model->group, _model);
        if (state.precomputed) {
            auto fitIt = g_precomputedLinearModelFits.find(_model->group);
            if (fitIt != g_precomputedLinearModelFits.end()) {
                return fitIt->second;
            }
        }
        group = state.group.empty() ? _model->group : state.group;
        dependent = state.dependent.empty() ? _model->yLabel : state.dependent;
        terms = state.terms;
        termTypes = state.termTypes;
        scope = state.scope == "compare_selected_all" ? "all" : state.scope;
        signature = rlispstat::core::LinearGLMFitSignature(dependent, terms, termTypes, scope);
        auto fitIt = g_precomputedLinearModelFits.find(group);
        if (fitIt != g_precomputedLinearModelFits.end() && fitIt->second.ok) {
            cachedFit = fitIt->second;
            hasCachedFit = true;
        }
        if (!state.isStale && fitIt != g_precomputedLinearModelFits.end() &&
            state.lastRFitSignature == signature) {
            return fitIt->second;
        }
        if (state.rFitPending && state.lastRFitSignature == signature) {
            return hasCachedFit
                ? cachedFit
                : PendingLinearGLMFitSummary("Fitting linear model in the main R session...");
        }
        state.rFitPending = true;
        state.lastRFitSignature = signature;
        task.group = group;
        task.dependent = dependent;
        task.scope = ScopeForCapturedAnalysisScope(state.dataScope, state.dataScopeCaptured, scope);
        task.terms = terms;
        task.termTypes = termTypes;
        task.rows = RowsForCapturedAnalysisScope(state.dataScope, state.dataScopeCaptured);
        shouldQueueRFit = true;
    }
    if (shouldQueueRFit) {
        QueueLinearGLMMainRTask(task);
    }
    return hasCachedFit
        ? cachedFit
        : PendingLinearGLMFitSummary("Fitting linear model in the main R session...");
}

- (BOOL)usesPooledGlobalWald
{
    std::lock_guard<std::mutex> lock(g_mutex);
    GroupModelState &state = EnsureGroupModelUnlocked(_model->group, _model);
    return state.multipleImputation;
}

- (NSString *)globalModelStatisticLabel
{
    return [self usesPooledGlobalWald] ? ToNSString(rlispstat::core::GLMD1WaldLabel()) : ToNSString(rlispstat::core::GLMAnovaFRatioLabel());
}

- (void)openInteractionReportForTerm:(const std::string &)term
{
    if (term.empty()) return;
    std::vector<std::string> terms;
    std::map<std::string, std::string> termTypes;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        GroupModelState &state = EnsureGroupModelUnlocked(_model->group, _model);
        terms = state.terms;
        termTypes = state.termTypes;
    }
    GLMFitSummary fit = [self currentFit];
    GLMInteractionReport report = BuildGLMInteractionReportPortableMac(_model, term, terms, termTypes, fit);
    ShowGLMInteractionReportWindowOnMain("Interaction: " + term, GLMInteractionReportText(report));
    if (report.ok) {
        [_statusField setStringValue:ToNSString(GLMInteractionReportOpenedStatus(term))];
    } else {
        [_statusField setStringValue:ToNSString(GLMStatusMessage(report.message))];
    }
}

- (void)openInteractionPlotForTerm:(const std::string &)term
{
    if (term.empty()) return;
    std::string plotId = OpenGLMInteractionPlotForTerm(_model, term, true);
    if (!plotId.empty()) {
        [_statusField setStringValue:ToNSString(GLMInteractionPlotOpenedStatus(term))];
    }
}

- (void)showInteractionReport:(id)sender
{
    std::string term;
    NSString *represented = [sender respondsToSelector:@selector(representedObject)] ? [sender representedObject] : nil;
    if (represented) term = [represented UTF8String];
    if (term.empty()) term = [self selectedTerm];
    [self openInteractionReportForTerm:term];
}

- (void)showInteractionPlot:(id)sender
{
    std::string term;
    NSString *represented = [sender respondsToSelector:@selector(representedObject)] ? [sender representedObject] : nil;
    if (represented) term = [represented UTF8String];
    if (term.empty()) term = [self selectedTerm];
    [self openInteractionPlotForTerm:term];
}

- (std::string)sourceTermForCoefficientRow:(NSInteger)row
{
    GLMFitSummary fit = [self currentFit];
    if (fit.ok && row > 0 && row < (NSInteger)fit.coefficients.size()) {
        return fit.coefficients[(size_t)row].sourceTerm;
    }
    std::lock_guard<std::mutex> lock(g_mutex);
    GroupModelState &state = EnsureGroupModelUnlocked(_model->group, _model);
    NSInteger termRow = row - 1;
    if (termRow >= 0 && (size_t)termRow < state.terms.size()) {
        return state.terms[(size_t)termRow];
    }
    return "";
}

- (void)dependentChanged:(id)sender
{
    NSString *name = [_dependentPopup titleOfSelectedItem];
    if (!name) {
        return;
    }
    std::string newDependent = [name UTF8String];
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        GroupModelState &state = EnsureGroupModelUnlocked(_model->group, _model);
        if (state.precomputed) {
            if (!state.multipleImputation) {
                [_statusField setStringValue:ToNSString(GLMPrecomputedTableRefitStatus("change the response"))];
                return;
            }
        }
    }
    bool refitPooledMI = false;
    DataFrameModel df;
    std::vector<std::string> terms;
    std::string scope = "all";
    std::string oldDependent;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        GroupModelState &state = EnsureGroupModelUnlocked(_model->group, _model);
        if (state.precomputed && state.multipleImputation) {
            refitPooledMI = true;
            oldDependent = state.dependent.empty() ? _model->yLabel : state.dependent;
            terms = FilterModelTermsForResponse(_model, state.terms, newDependent);
            if (terms.empty() && oldDependent != newDependent &&
                ModelTermExistsForModel(_model, oldDependent, newDependent)) {
                terms.push_back(oldDependent);
            }
            scope = state.scope == "compare_selected_all" ? "all" : state.scope;
            const DataFrameModel *found = FindDataFrameUnlockedConst(_model->group);
            if (found) {
                df = *found;
            }
        }
    }
    if (refitPooledMI) {
        if (df.group.empty()) {
            [_statusField setStringValue:ToNSString(GLMImputedDatasetUnavailableStatus())];
            return;
        }
        [_statusField setStringValue:ToNSString(GLMRefittingPooledMIResponseStatus(newDependent))];
        std::thread worker([df, newDependent, terms, scope]() {
            std::string message;
            bool ok = RunRBackedMultipleImputationAnalysis(
                df, "glm",
                "glm_" + df.group + "_" + std::to_string((long long)time(nullptr)),
                std::vector<std::string>(), "", newDependent, terms, scope, &message);
            if (!ok) ShowWorkbenchMessageOnMain(ToNSString(rlispstat::core::GLMGeneralLinearModelTitle()), ToNSString(message));
        });
        worker.detach();
        return;
    }
    ApplyVariableAction(_model->group, newDependent, "dependent");
    [self refresh];
}

- (void)addPredictor:(id)sender
{
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        GroupModelState &state = EnsureGroupModelUnlocked(_model->group, _model);
        if (state.precomputed && !state.multipleImputation) {
            [_statusField setStringValue:ToNSString(GLMPrecomputedTableRefitStatus("add predictors"))];
            return;
        }
    }
    NSMenu *menu = [[NSMenu alloc] initWithTitle:ToNSString(rlispstat::core::ScatterplotAddIndependentVariableTitle())];
    std::string dependent;
    std::vector<std::string> terms;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        GroupModelState &state = EnsureGroupModelUnlocked(_model->group, _model);
        dependent = state.dependent.empty() ? _model->yLabel : state.dependent;
        terms = state.terms;
    }
    for (const std::string &name : VariableNamesForModel(_model)) {
        if (name == dependent || std::find(terms.begin(), terms.end(), name) != terms.end()) {
            continue;
        }
        NSMenuItem *item = [[NSMenuItem alloc] initWithTitle:ToNSString(name) action:@selector(addPredictorFromMenu:) keyEquivalent:@""];
        [item setTarget:self];
        [item setRepresentedObject:ToNSString(name)];
        [menu addItem:item];
    }
    if ([menu numberOfItems] > 0) {
        [menu addItem:[NSMenuItem separatorItem]];
    }
    if (!AddInteractionMenuItems(menu, self, @selector(addPredictorFromMenu:), _model, dependent, terms)) {
        NSInteger last = [menu numberOfItems] - 1;
        if (last >= 0 && [[menu itemAtIndex:last] isSeparatorItem]) {
            [menu removeItemAtIndex:last];
        }
    }
    if ([[menu itemArray] count] == 0) {
        [_statusField setStringValue:ToNSString(GLMNoAvailablePredictorsStatus())];
        return;
    }
    NSView *view = [sender isKindOfClass:[NSView class]] ? (NSView *)sender : _coefView;
    NSPoint point = [view isEqual:_coefView] ? NSMakePoint(10, [_coefView bounds].size.height - 4) : [(NSButton *)sender frame].origin;
    if (![view isEqual:_coefView]) {
        point.y += [(NSButton *)sender frame].size.height;
        view = [(NSButton *)sender superview];
    }
    [menu popUpMenuPositioningItem:nil atLocation:point inView:view];
}

- (void)addPredictorFromMenu:(id)sender
{
    NSString *name = [sender representedObject];
    if (!name) {
        return;
    }
    std::string term = [name UTF8String];
    bool refitPooledMI = false;
    DataFrameModel df;
    std::string dependent;
    std::vector<std::string> terms;
    std::string scope = "all";
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        GroupModelState &state = EnsureGroupModelUnlocked(_model->group, _model);
        if (state.precomputed && state.multipleImputation) {
            refitPooledMI = true;
            dependent = state.dependent.empty() ? _model->yLabel : state.dependent;
            terms = state.terms;
            AddHierarchicalTermsToVector(_model, dependent, terms, term);
            scope = state.scope == "compare_selected_all" ? "all" : state.scope;
            const DataFrameModel *found = FindDataFrameUnlockedConst(_model->group);
            if (found) df = *found;
        }
    }
    if (refitPooledMI) {
        if (df.group.empty()) {
            [_statusField setStringValue:ToNSString(GLMImputedDatasetUnavailableStatus())];
            return;
        }
        [_statusField setStringValue:ToNSString(GLMRefittingPooledMITermStatus("adding", term))];
        std::thread worker([df, dependent, terms, scope]() {
            std::string message;
            bool ok = RunRBackedMultipleImputationAnalysis(
                df, "glm",
                "glm_" + df.group + "_" + std::to_string((long long)time(nullptr)),
                std::vector<std::string>(), "", dependent, terms, scope, &message);
            if (!ok) ShowWorkbenchMessageOnMain(ToNSString(rlispstat::core::GLMGeneralLinearModelTitle()), ToNSString(message));
        });
        worker.detach();
        return;
    }
    ApplyVariableAction(_model->group, term, "predictor");
    [self refresh];
}

- (void)changeSelectedModelRow:(id)sender
{
    NSInteger row = _selectedCoefRow;
    if (row < 0) {
        return;
    }
    if (row == [self coefficientRowCount] - 1) {
        [self addPredictor:_coefView];
        return;
    }
    if (row == 0) {
        return;
    }
    [self replacePredictorAtTableRow:row];
}

- (void)dependentFromMenu:(id)sender
{
    NSString *name = [sender representedObject];
    if (!name) return;
    ApplyVariableAction(_model->group, [name UTF8String], "dependent");
    [self refresh];
}

- (void)replacePredictorAtTableRow:(NSInteger)row
{
    std::string oldTerm = [self sourceTermForCoefficientRow:row];
    if (oldTerm.empty()) return;
    NSInteger termIndex = -1;
    std::string dependent;
    std::vector<std::string> terms;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        GroupModelState &state = EnsureGroupModelUnlocked(_model->group, _model);
        dependent = state.dependent.empty() ? _model->yLabel : state.dependent;
        terms = state.terms;
    }
    for (size_t i = 0; i < terms.size(); ++i) {
        if (terms[i] == oldTerm) {
            termIndex = (NSInteger)i;
            break;
        }
    }
    if (termIndex < 0 || (size_t)termIndex >= terms.size()) return;
    NSMenu *menu = [[NSMenu alloc] initWithTitle:ToNSString(rlispstat::core::ScatterplotReplacePredictorTitle())];
    for (const std::string &name : VariableNamesForModel(_model)) {
        if (name == dependent) continue;
        bool duplicate = false;
        for (size_t i = 0; i < terms.size(); ++i) {
            if ((NSInteger)i != termIndex && terms[i] == name) {
                duplicate = true;
                break;
            }
        }
        if (duplicate) continue;
        NSMenuItem *item = [[NSMenuItem alloc] initWithTitle:ToNSString(name) action:@selector(replacePredictorFromMenu:) keyEquivalent:@""];
        [item setTarget:self];
        [item setRepresentedObject:@[ @(termIndex), ToNSString(name) ]];
        [menu addItem:item];
    }
    if ([[menu itemArray] count] == 0) {
        [_statusField setStringValue:ToNSString(GLMNoAvailableReplacementStatus())];
        return;
    }
    GLMReportLayout layout;
    NSRect rowRect = NSMakeRect(0, row * layout.rowHeight, [_coefView bounds].size.width, layout.rowHeight);
    [menu popUpMenuPositioningItem:nil atLocation:NSMakePoint(NSMinX(rowRect) + 10, NSMaxY(rowRect)) inView:_coefView];
}

- (void)replacePredictorFromMenu:(id)sender
{
    NSArray *payload = [sender representedObject];
    if (![payload isKindOfClass:[NSArray class]] || [payload count] < 2) return;
    NSInteger termIndex = [[payload objectAtIndex:0] integerValue];
    NSString *name = [payload objectAtIndex:1];
    if (!name) return;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        GroupModelState &state = EnsureGroupModelUnlocked(_model->group, _model);
        if (termIndex >= 0 && (size_t)termIndex < state.terms.size()) {
            state.terms[(size_t)termIndex] = [name UTF8String];
            rlispstat::core::MarkGroupModelChanged(state);
        }
    }
    [self refresh];
    PublishSpreadPlotMessage("GLM_PREDICTOR_REPLACED", _model->group, "glm:" + _model->group, "glm:" + _model->group);
}

- (void)showTypeMenuForTableRow:(NSInteger)row
{
    if (row <= 0 || row == [self coefficientRowCount] - 1) return;
    std::string term = [self sourceTermForCoefficientRow:row];
    if (term.empty()) return;
    std::string type;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        GroupModelState &state = EnsureGroupModelUnlocked(_model->group, _model);
        type = rlispstat::core::ModelTermDisplayType(_model, term, state.termTypes);
    }
    if (rlispstat::core::ModelTermTypeIsInteraction(type)) {
        [_statusField setStringValue:ToNSString(GLMInteractionComponentTypeStatus(term))];
        return;
    }
    NSMenu *menu = [[NSMenu alloc] initWithTitle:ToNSString(rlispstat::core::PredictorTypeMenuTitle())];
    AddModelTermTypeMenuItems(menu, self, @selector(typeMenuSelected:), type);
    GLMReportLayout layout;
    NSRect rowRect = NSMakeRect(0, row * layout.rowHeight, [_coefView bounds].size.width, layout.rowHeight);
    [menu popUpMenuPositioningItem:nil atLocation:NSMakePoint(layout.coefX[1], NSMaxY(rowRect)) inView:_coefView];
}

- (void)typeMenuSelected:(id)sender
{
    NSString *mode = [sender representedObject];
    std::string term = [self sourceTermForCoefficientRow:_selectedCoefRow];
    if (term.empty()) return;
    if (IsInteractionTerm(term)) {
        [_statusField setStringValue:ToNSString(GLMInteractionComponentTypeStatus(term))];
        return;
    }
    std::string type = (mode && [mode isEqualToString:@"factor"]) ? "factor" : "numeric";
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        GroupModelState &state = EnsureGroupModelUnlocked(_model->group, _model);
        state.termTypes[term] = type;
        rlispstat::core::MarkGroupModelChanged(state);
    }
    RefreshGLMDiagnosticPlotsSynchronouslyOnMain(_model->group, true);
    PublishSpreadPlotMessage("GLM_TERM_TYPE_CHANGED", _model->group, "glm:" + _model->group, "glm:" + _model->group);
    [self refresh];
    [_statusField setStringValue:ToNSString(GLMTermTypeChangedStatus(term, type))];
}

- (void)changeSelectedType:(id)sender
{
    (void)sender;
    NSInteger row = _selectedCoefRow;
    if (row > 0) {
        [self showTypeMenuForTableRow:row];
    }
}

