- (NSString *)snapshotTableText
{
    if (!_model) return @"";
    std::string dependent;
    std::string scope;
    std::string note;
    bool hasCapturedScope = false;
    std::string scopeSummary;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        GroupModelState &state = EnsureGroupModelUnlocked(_model->group, _model);
        dependent = state.dependent.empty() ? _model->yLabel : state.dependent;
        scope = state.scope == "compare_selected_all" ? "all" : state.scope;
        note = state.note;
        hasCapturedScope = state.dataScopeCaptured;
        if (hasCapturedScope) {
            scopeSummary = rlispstat::core::AnalysisScopeWindowSummary(
                state.dataScope, state.dataScope.totalDatasetRows);
        }
    }
    GLMFitSummary fit = [self currentFit];
    if (!fit.ok) return ToNSString(fit.warning);

    std::ostringstream out;
    out << "Response variable\t" << dependent << "\n";
    out << "Scope\t" << (scopeSummary.empty() ? scope : scopeSummary) << "\n";
    out << "Selected rows\t" << SelectionCount(_model->group) << " / "
        << _model->points.size() << "\n\n";
    out << "Global fit\n";
    out << "R²\t" << FormatPercent(fit.r2, 1)
        << "\tAdjusted R²\t" << FormatPercent(fit.adjR2, 1)
        << "\ts\t" << FormatDouble(fit.sigma, 3)
        << "\tdf\t" << fit.dfResidual << "\n\n";
    out << "Source\tSum of Squares\tdf\tMean Square\t"
        << ([[self globalModelStatisticLabel] UTF8String]) << "\tp\n";
    out << "Regression\t" << FormatDouble(fit.ssRegression, 4) << "\t"
        << fit.dfModel << "\t" << FormatDouble(fit.msRegression, 4) << "\t"
        << FormatDouble(fit.globalF, 3) << "\t" << FormatPValue(fit.globalP) << "\n";
    out << "Residual\t" << FormatDouble(fit.ssResidual, 4) << "\t"
        << fit.dfResidual << "\t" << FormatDouble(fit.msResidual, 4) << "\t\t\n\n";
    out << "Terms\n";
    out << "Variable\tType\tb\tβ\tSE\tt\tp\tPartial R²\n";
    const NSInteger rowCount = [self coefficientRowCount] - 1;
    for (NSInteger row = 0; row < rowCount; ++row) {
        for (NSInteger column = 0; column < 8; ++column) {
            if (column) out << '\t';
            NSString *value = [self coefficientValueForRow:row column:column] ?: @"";
            out << [value UTF8String];
        }
        out << '\n';
    }
    out << "\nStatus\t";
    if (!note.empty()) out << note;
    else out << GLMFittedStatus(fit.n, fit.excluded, scope);
    if (!scopeSummary.empty()) out << " · " << scopeSummary;
    out << "\n\n* p < .05; ** p < .01; *** p < .001";
    return ToNSString(out.str());
}

