- (NSMenu *)statisticContextMenuForTableRow:(NSInteger)row column:(NSInteger)column
{
    const auto titles = rlispstat::core::DefaultModelContextMenuTitles();
    NSMenu *menu = [[NSMenu alloc] initWithTitle:ToNSString(titles.statistic)];
    NSMenuItem *copy = [[NSMenuItem alloc] initWithTitle:ToNSString(titles.copyValue) action:@selector(copyMenuValue:) keyEquivalent:@""];
    [copy setTarget:self];
    [copy setRepresentedObject:[self valueForTableRow:row column:column]];
    [menu addItem:copy];
    [menu addItem:[self regressionExportMenuItem]];
    [menu addItem:[[NSMenuItem alloc] initWithTitle:ToNSString(titles.explainStatistic) action:@selector(termActionPlanned:) keyEquivalent:@""]];
    [menu addItem:[[NSMenuItem alloc] initWithTitle:ToNSString(titles.openRelevantDiagnosticPlot) action:@selector(openObservedFitted:) keyEquivalent:@""]];
    for (NSMenuItem *item in [menu itemArray]) {
        if ([item action] && ![item target]) [item setTarget:self];
    }
    return menu;
}

- (NSMenu *)predictorContextMenuForTableRow:(NSInteger)row
{
    const auto titles = rlispstat::core::DefaultModelContextMenuTitles();
    NSMenu *menu = [[NSMenu alloc] initWithTitle:ToNSString(titles.predictor)];
    std::string baseTerm = [self sourceTermForCoefficientRow:row];
    if (IsInteractionTerm(baseTerm)) {
        NSMenuItem *interpret = [[NSMenuItem alloc] initWithTitle:ToNSString(titles.interpretInteraction) action:@selector(showInteractionReport:) keyEquivalent:@""];
        [interpret setRepresentedObject:ToNSString(baseTerm)];
        [menu addItem:interpret];
        NSMenuItem *plot = [[NSMenuItem alloc] initWithTitle:ToNSString(titles.interactionPlot) action:@selector(showInteractionPlot:) keyEquivalent:@""];
        [plot setRepresentedObject:ToNSString(baseTerm)];
        [menu addItem:plot];
        [menu addItem:[NSMenuItem separatorItem]];
    }
    [menu addItem:[[NSMenuItem alloc] initWithTitle:ToNSString(titles.partialRegressionPlot) action:@selector(openResidualsFitted:) keyEquivalent:@""]];

    // Pairwise comparisons are a domain operation.  AppKit only asks the
    // portable GLM model whether this exact row identifies a currently fitted
    // simple categorical main effect, and uses that answer to enable the menu.
    std::string dependent;
    std::vector<std::string> terms;
    std::map<std::string, std::string> termTypes;
    DataFrameModel dataframe;
    bool hasDataframe = false;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        GroupModelState &state = EnsureGroupModelUnlocked(_model->group, _model);
        dependent = state.dependent.empty() ? _model->yLabel : state.dependent;
        terms = state.terms;
        termTypes = state.termTypes;
        if (const DataFrameModel *found = FindDataFrameUnlockedConst(_model->group)) {
            dataframe = *found;
            hasDataframe = true;
        }
    }
    rlispstat::core::GLMPairwiseComparisonRequest pairwiseRequest;
    pairwiseRequest.term = baseTerm;
    rlispstat::core::GLMPairwiseComparisonEligibility pairwiseEligibility =
        rlispstat::core::EvaluateGLMPairwiseComparisonEligibility(
            *_model, hasDataframe ? &dataframe : nullptr, dependent, terms, termTypes,
            [self currentFit], pairwiseRequest);
    if (pairwiseEligibility.eligible ||
        (std::find(terms.begin(), terms.end(), baseTerm) != terms.end() &&
         !IsInteractionTerm(baseTerm) && baseTerm != "(Intercept)")) {
        NSMenuItem *pairwise = [[NSMenuItem alloc] initWithTitle:@"Comparaciones por pares…"
                                                         action:@selector(openPairwiseComparisons:)
                                                  keyEquivalent:@""];
        [pairwise setRepresentedObject:ToNSString(baseTerm)];
        [pairwise setEnabled:pairwiseEligibility.eligible];
        [menu addItem:pairwise];
    }

    NSMenuItem *dropCoefficient = [[NSMenuItem alloc] initWithTitle:ToNSString(titles.dropCoefficient) action:@selector(removeSelectedTerm:) keyEquivalent:@""];
    [dropCoefficient setRepresentedObject:ToNSString(baseTerm)];
    [menu addItem:dropCoefficient];
    [menu addItem:[NSMenuItem separatorItem]];
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        GroupModelState &state = EnsureGroupModelUnlocked(_model->group, _model);
        dependent = state.dependent.empty() ? _model->yLabel : state.dependent;
        terms = state.terms;
    }
    if (!AddInteractionMenuItems(menu, self, @selector(addPredictorFromMenu:), _model, dependent, terms, baseTerm)) {
        NSMenuItem *disabled = [[NSMenuItem alloc] initWithTitle:ToNSString(titles.noAvailableInteractions) action:nil keyEquivalent:@""];
        [disabled setEnabled:NO];
        [menu addItem:disabled];
    }
    [menu addItem:[[NSMenuItem alloc] initWithTitle:ToNSString(titles.addPolynomialTerm) action:@selector(termActionPlanned:) keyEquivalent:@""]];
    [menu addItem:[[NSMenuItem alloc] initWithTitle:ToNSString(titles.changeVariable) action:@selector(changeSelectedModelRow:) keyEquivalent:@""]];
    [menu addItem:[[NSMenuItem alloc] initWithTitle:ToNSString(titles.changeType) action:@selector(changeSelectedType:) keyEquivalent:@""]];
    NSMenuItem *removePredictor = [[NSMenuItem alloc] initWithTitle:ToNSString(titles.removePredictor) action:@selector(removeSelectedTerm:) keyEquivalent:@""];
    [removePredictor setRepresentedObject:ToNSString(baseTerm)];
    [menu addItem:removePredictor];
    for (NSMenuItem *item in [menu itemArray]) {
        if ([item action]) [item setTarget:self];
    }
    (void)row;
    return menu;
}

- (void)openPairwiseComparisons:(id)sender
{
    NSString *represented = [sender respondsToSelector:@selector(representedObject)]
        ? [sender representedObject] : nil;
    const std::string term = represented ? [represented UTF8String] : [self selectedTerm];
    if (term.empty()) return;
    std::string dependent;
    std::vector<std::string> terms;
    std::map<std::string, std::string> termTypes;
    DataFrameModel dataframe;
    bool hasDataframe = false;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        GroupModelState &state = EnsureGroupModelUnlocked(_model->group, _model);
        dependent = state.dependent.empty() ? _model->yLabel : state.dependent;
        terms = state.terms;
        termTypes = state.termTypes;
        if (const DataFrameModel *found = FindDataFrameUnlockedConst(_model->group)) {
            dataframe = *found;
            hasDataframe = true;
        }
    }
    rlispstat::core::GLMPairwiseComparisonRequest request;
    request.term = term;
    GLMFitSummary fit = [self currentFit];
    rlispstat::core::GLMPairwiseComparisonEligibility eligibility =
        rlispstat::core::EvaluateGLMPairwiseComparisonEligibility(
            *_model, hasDataframe ? &dataframe : nullptr, dependent, terms, termTypes, fit, request);
    if (!eligibility.eligible) {
        [_statusField setStringValue:ToNSString(GLMStatusMessage(eligibility.message))];
        return;
    }
    rlispstat::core::GLMPairwiseComparisonResult result;
    result.term = term;
    result.levels = eligibility.levels;
    std::string message;
    if (!hasDataframe || !RunRBackedGLMPairwiseComparisons(
            dataframe, _model, dependent, terms, termTypes, fit, request, &result, &message)) {
        [_statusField setStringValue:ToNSString(GLMStatusMessage(message))];
        return;
    }
    GLMPairwiseComparisonPlotLink plotLink = BuildGLMPairwiseComparisonPlotLink(
        _model->group, dataframe, dependent, term, fit.rowsUsed, result);
    ShowGLMPairwiseResultsWindowOnMain(term, result, plotLink);
    [_statusField setStringValue:ToNSString("Comparaciones por pares calculadas para " + term + ".")];
}

- (NSMenu *)contextMenuForCoefficientRow:(NSInteger)row column:(NSInteger)column
{
    _selectedCoefRow = row;
    _selectedCoefColumn = column;
    if (row < 0 || row == [self coefficientRowCount] - 1) {
        return nil;
    }
    NSMenu *result = nil;
    if (column >= 0 && column < 8) {
        NSString *identifier = [self coefficientColumnIdentifier:column];
        if (![identifier isEqualToString:@"term"] && ![identifier isEqualToString:@"type"]) {
            result = [self statisticContextMenuForTableRow:row column:column];
        }
    }
    if (!result) result = row > 0 ? [self predictorContextMenuForTableRow:row]
                                  : [self statisticContextMenuForTableRow:row column:column];
    return result;
}

- (void)showStatisticMenuForTableRow:(NSInteger)row column:(NSInteger)column
{
    if (row == [self coefficientRowCount] - 1) return;
    NSMenu *menu = [self statisticContextMenuForTableRow:row column:column];
    GLMReportLayout layout;
    NSRect rowRect = NSMakeRect(0, row * layout.rowHeight, [_coefView bounds].size.width, layout.rowHeight);
    [menu popUpMenuPositioningItem:nil atLocation:NSMakePoint(NSMidX(rowRect), NSMaxY(rowRect)) inView:_coefView];
}

- (void)coefficientCellClickedAtRow:(NSInteger)row column:(NSInteger)column
{
    if (row < 0) return;
    _selectedCoefRow = row;
    _selectedCoefColumn = column;
    BOOL isAddRow = row == [self coefficientRowCount] - 1;
    NSString *identifier = [self coefficientColumnIdentifier:column];
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        GroupModelState &state = EnsureGroupModelUnlocked(_model->group, _model);
        if (state.precomputed) {
            if (!(state.multipleImputation && isAddRow) &&
                (isAddRow ||
                [identifier isEqualToString:@"term"] ||
                [identifier isEqualToString:@"type"])) {
                [_statusField setStringValue:ToNSString(GLMPooledTableChangeInRStatus())];
                return;
            }
        }
    }
    if (isAddRow) {
        [self addPredictor:_coefView];
        return;
    }
    if (column < 0) return;
    if ([identifier isEqualToString:@"term"] && row > 0) {
        std::string term = [self sourceTermForCoefficientRow:row];
        if (IsInteractionTerm(term)) {
            [self openInteractionReportForTerm:term];
            [self openInteractionPlotForTerm:term];
        } else {
            [self replacePredictorAtTableRow:row];
        }
    } else if ([identifier isEqualToString:@"type"] && row > 0) {
        [self showTypeMenuForTableRow:row];
    } else if (![identifier isEqualToString:@"term"] && ![identifier isEqualToString:@"type"]) {
        [self showStatisticMenuForTableRow:row column:column];
    }
}

- (void)scopeChanged:(id)sender
{
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        GroupModelState &state = EnsureGroupModelUnlocked(_model->group, _model);
        if (state.precomputed) {
            [_statusField setStringValue:ToNSString(GLMPooledMIScopeRefitStatus())];
            [self refresh];
            return;
        }
    }
    NSInteger index = [_scopePopup indexOfSelectedItem];
    if (index == 1) {
        _scope = "selected";
    } else if (index == 2) {
        _scope = "unselected";
    } else if (index == 3) {
        _scope = "compare_selected_all";
    } else {
        _scope = "all";
    }
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        GroupModelState &state = EnsureGroupModelUnlocked(_model->group, _model);
        state.scope = _scope;
        rlispstat::core::MarkGroupModelChanged(state);
    }
    [self refresh];
    PublishSpreadPlotMessage("GLM_SCOPE_CHANGED", _model->group, "glm:" + _model->group, "glm:" + _model->group);
}

- (std::string)selectedTerm
{
    return [self sourceTermForCoefficientRow:_selectedCoefRow];
}

- (void)removeSelectedTerm:(id)sender
{
    std::string term = [self selectedTerm];
    if (sender && [sender respondsToSelector:@selector(representedObject)]) {
        id represented = [sender representedObject];
        if ([represented isKindOfClass:[NSString class]] && [(NSString *)represented length] > 0) {
            term = [(NSString *)represented UTF8String];
        }
    }
    if (term.empty()) {
        [_statusField setStringValue:ToNSString(GLMSelectPredictorToRemoveStatus())];
        return;
    }
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        GroupModelState &state = EnsureGroupModelUnlocked(_model->group, _model);
        if (state.precomputed && !state.multipleImputation) {
            [_statusField setStringValue:ToNSString(GLMPrecomputedTableRefitStatus("remove predictors"))];
            return;
        }
    }
    bool refitPooledMI = false;
    DataFrameModel df;
    std::string dependent;
    std::vector<std::string> terms;
    std::string scope = "all";
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        GroupModelState &state = EnsureGroupModelUnlocked(_model->group, _model);
        if (state.precomputed && state.multipleImputation && !term.empty()) {
            refitPooledMI = true;
            dependent = state.dependent.empty() ? _model->yLabel : state.dependent;
            terms = state.terms;
            terms.erase(std::remove_if(terms.begin(), terms.end(), [&](const std::string &candidate) {
                return ModelTermShouldBeRemoved(candidate, term);
            }), terms.end());
            scope = state.scope == "compare_selected_all" ? "all" : state.scope;
            const DataFrameModel *found = FindDataFrameUnlockedConst(_model->group);
            if (found) df = *found;
        }
    }
    if (refitPooledMI) {
        if (df.group.empty()) {
            [_statusField setStringValue:ToNSString(GLMImputedDatasetUnavailableStatus())];
            return;
        }
        [_statusField setStringValue:ToNSString(GLMRefittingPooledMITermStatus("removing", term))];
        std::thread worker([df, dependent, terms, scope]() {
            std::string message;
            bool ok = RunRBackedMultipleImputationAnalysis(
                df, "glm",
                "glm_" + df.group + "_" + std::to_string((long long)time(nullptr)),
                std::vector<std::string>(), "", dependent, terms, scope, &message);
            if (!ok) ShowWorkbenchMessageOnMain(ToNSString(rlispstat::core::GLMGeneralLinearModelTitle()), ToNSString(message));
        });
        worker.detach();
        return;
    }
    if (!term.empty()) {
        RemoveModelTerm(_model->group, term);
    }
}

