        return;
    }
    [self activateDatasetForCommands];
    EnableNotesForWindow(_window, _model ? _model->id : "", @"this model result");
    [_window orderFront:nil];
    [NSApp activateIgnoringOtherApps:YES];
    [self refresh];
}

- (void)activateDatasetForCommands
{
    if (!_model) {
        return;
    }
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        MarkActiveDatasetGroupUnlocked(_model->group);
        EnsureDatasetSeedPlotUnlocked(_model->group);
    }
    UpdateActiveDatasetMenuOnMain();
}

