static void ShowNewCorrelationMatrixOnMain(PlotModel *model)
{
    model = ActiveDatasetCommandModel(model);
    if (!model) {
        ShowWorkbenchMessageOnMain(ToNSString(rlispstat::core::CorrelationWindowTitle()), ToNSString(NoActiveDatasetImportOrRegisterStatus()));
        return;
    }
    std::vector<std::string> numeric = rlispstat::core::NumericVariableNames(model);
    if (numeric.empty()) {
        ShowWorkbenchMessageOnMain(ToNSString(rlispstat::core::CorrelationWindowTitle()), ToNSString(rlispstat::core::ActiveDatasetNoNumericVariablesStatus()));
        return;
    }
    bool multipleImputation = GroupIsMultipleImputation(model->group);
    CorrelationMatrixState state;
    state.id = "corr_" + model->group + "_" + std::to_string((long long)time(nullptr));
    state.group = model->group;
    state.title = multipleImputation ? "Pearson Correlation Matrix - Multiple Imputation"
                                     : "Pearson Correlation Matrix";
    state.method = "pearson";
    state.missingMode = "pairwise";
    state.showP = true;
    state.showPValue = false;
    state.showN = false;
    state.multipleImputation = multipleImputation;
    size_t count = std::min((size_t)4, numeric.size());
    state.variables.assign(numeric.begin(), numeric.begin() + count);
    state.seed = *model;
    state.hasSeed = true;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        CaptureActiveAnalysisScopeUnlocked(state.group, state.dataScope, state.dataScopeCaptured);
    }
    RefitCorrelationMatrixState(state);
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        g_correlationMatrices[state.id] = state;
    }
    ShowCorrelationMatrixOnMain(state.id);
}

static void ShowCorrelationMatrixForVariablesOnMain(PlotModel *model,
                                                    const std::vector<std::string> &variables,
                                                    const std::string &title)
{
    model = ActiveDatasetCommandModel(model);
    if (!model) {
        ShowWorkbenchMessageOnMain(ToNSString(rlispstat::core::CorrelationWindowTitle()), ToNSString(NoActiveDatasetImportOrRegisterStatus()));
        return;
    }
    bool multipleImputation = GroupIsMultipleImputation(model->group);
    CorrelationMatrixState state;
    state.id = "corr_" + model->group + "_" + std::to_string((long long)time(nullptr));
    state.group = model->group;
    state.title = !title.empty()
        ? title
        : (multipleImputation ? "Pearson Correlation Matrix - Multiple Imputation" : "Pearson Correlation Matrix");
    state.method = "pearson";
    state.missingMode = "pairwise";
    state.showP = true;
    state.showPValue = false;
    state.showN = true;
    state.multipleImputation = multipleImputation;
    state.seed = *model;
    state.hasSeed = true;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        CaptureActiveAnalysisScopeUnlocked(state.group, state.dataScope, state.dataScopeCaptured);
    }
    for (const std::string &name : variables) {
        if (name.empty() || !FindVariable(model, name)) continue;
        if (std::find(state.variables.begin(), state.variables.end(), name) == state.variables.end()) {
            state.variables.push_back(name);
        }
    }
    if (state.variables.size() < 2) {
        ShowWorkbenchMessageOnMain(ToNSString(rlispstat::core::CorrelationWindowTitle()), ToNSString(rlispstat::core::CorrelationMatrixNeedsTwoNumericStatus()));
        return;
    }
    RefitCorrelationMatrixState(state);
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        g_correlationMatrices[state.id] = state;
    }
    ShowCorrelationMatrixOnMain(state.id);
}

