static void ShowGeneralizedGLMOnMain(const std::string &modelId)
{
    std::string modelIdCopy = modelId;
    void (^showBlock)(void) = ^{
      GeneralizedGLMWindowController *controller = nil;
      {
          std::lock_guard<std::mutex> lock(g_mutex);
          auto stateIt = g_generalizedGLMs.find(modelIdCopy);
          if (stateIt == g_generalizedGLMs.end()) {
              return;
          }
          auto it = g_generalizedGLMControllers.find(modelIdCopy);
          if (it != g_generalizedGLMControllers.end()) {
              controller = it->second;
          }
      }
      if (!controller) {
          controller = [[GeneralizedGLMWindowController alloc] initWithModelId:modelIdCopy];
          std::lock_guard<std::mutex> lock(g_mutex);
          g_generalizedGLMControllers[modelIdCopy] = controller;
      }
      [controller show];
    };
    if ([NSThread isMainThread]) {
        showBlock();
    } else {
        dispatch_sync(dispatch_get_main_queue(), showBlock);
    }
}

static void RefreshGeneralizedGLMOnMain(const std::string &modelId)
{
    std::string modelIdCopy = modelId;
    void (^refreshBlock)(void) = ^{
      GeneralizedGLMWindowController *controller = nil;
      {
          std::lock_guard<std::mutex> lock(g_mutex);
          auto it = g_generalizedGLMControllers.find(modelIdCopy);
          if (it != g_generalizedGLMControllers.end()) {
              controller = it->second;
          }
      }
      if (controller) {
          [controller refresh];
      } else {
          ShowGeneralizedGLMOnMain(modelIdCopy);
      }
    };
    if ([NSThread isMainThread]) {
        refreshBlock();
    } else {
        dispatch_sync(dispatch_get_main_queue(), refreshBlock);
    }
}

