static void ShowNewGeneralizedGLMOnMain(PlotModel *model)
{
    model = ActiveDatasetCommandModel(model);
    if (!model) {
        ShowWorkbenchMessageOnMain(ToNSString(rlispstat::core::GLMWindowTitle()), ToNSString(NoActiveDatasetImportOrRegisterStatus()));
        return;
    }
    std::vector<std::string> numeric = rlispstat::core::NumericVariableNames(model);
    if (numeric.empty()) {
        ShowWorkbenchMessageOnMain(ToNSString(rlispstat::core::GLMWindowTitle()), ToNSString(rlispstat::core::GLMNoNumericResponseVariablesStatus()));
        return;
    }
    if (GroupIsMultipleImputation(model->group)) {
        DataFrameModel df;
        bool found = false;
        {
            std::lock_guard<std::mutex> lock(g_mutex);
            const DataFrameModel *current = FindDataFrameUnlockedConst(model->group);
            if (current) {
                df = *current;
                found = true;
            }
        }
        if (!found) {
            ShowWorkbenchMessageOnMain(ToNSString(rlispstat::core::GLMWindowTitle()), ToNSString(rlispstat::core::GLMImputedDatasetNotAvailableStatus()));
            return;
        }
        std::string response = !model->yLabel.empty() && FindVariable(model, model->yLabel) ? model->yLabel : numeric.front();
        std::vector<std::string> terms;
        if (!model->xLabel.empty() && model->xLabel != response && FindVariable(model, model->xLabel)) {
            terms.push_back(model->xLabel);
        }
        if (terms.empty()) {
            for (const std::string &candidate : VariableNamesForModel(model)) {
                if (candidate != response) {
                    terms.push_back(candidate);
                    break;
                }
            }
        }
        if (terms.empty()) {
            ShowWorkbenchMessageOnMain(ToNSString(rlispstat::core::GLMWindowTitle()), ToNSString(rlispstat::core::GLMAddPredictorBeforeTableStatus()));
            return;
        }
        std::string family = DefaultGeneralizedFamilyForResponse(*model, response);
        std::string link = DefaultGeneralizedLink(family);
        std::string modelSpec = ProtocolSafeValue(family) + "|" + ProtocolSafeValue(link);
        std::thread worker([df, response, terms, modelSpec]() {
            std::string message;
            bool ok = RunRBackedMultipleImputationAnalysis(
                df, "gglm",
                "gglm_" + df.group + "_" + std::to_string((long long)time(nullptr)),
                std::vector<std::string>(), "", response, terms, "all", &message, modelSpec);
            if (!ok) ShowWorkbenchMessageOnMain(ToNSString(rlispstat::core::GLMWindowTitle()), ToNSString(message));
        });
        worker.detach();
        return;
    }
    GeneralizedGLMState state;
    state.id = "gglm_" + model->group + "_" + std::to_string((long long)time(nullptr));
    state.group = model->group;
    state.seed = *model;
    state.hasSeed = true;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        CaptureActiveAnalysisScopeUnlocked(state.group, state.dataScope, state.dataScopeCaptured);
    }
    state.scope = ScopeForCapturedAnalysisScope(state.dataScope, state.dataScopeCaptured, state.scope);
    state.response = !model->yLabel.empty() && FindVariable(model, model->yLabel) ? model->yLabel : numeric.front();
    state.family = DefaultGeneralizedFamilyForResponse(*model, state.response);
    state.link = DefaultGeneralizedLink(state.family);
    for (const std::string &candidate : VariableNamesForModel(model)) {
        if (candidate != state.response) {
            state.terms.push_back(candidate);
            break;
        }
    }
    state.modelVersion = 1;
    state.status = "Fitting generalized linear model in the main R session...";
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        g_generalizedGLMs[state.id] = state;
    }
    ShowGeneralizedGLMOnMain(state.id);
    QueueGeneralizedGLMMainRTask(state);
}

static void ShowNewBinaryRegressionOnMain(PlotModel *model)
{
    model = ActiveDatasetCommandModel(model);
    if (!model) {
        ShowWorkbenchMessageOnMain(@"Binary Regression", ToNSString(NoActiveDatasetImportOrRegisterStatus()));
        return;
    }
    if (GroupIsMultipleImputation(model->group)) {
        ShowWorkbenchMessageOnMain(@"Binary Regression", @"Binary Regression is not yet available for multiple-imputation datasets.");
        return;
    }
    std::vector<std::pair<std::string, rlispstat::core::BinaryResponseCoding>> eligible;
    for (const std::string &name : VariableNamesForModel(model)) {
        const DataColumn *column = FindDataColumnForModel(model, name);
        if (!column) continue;
        rlispstat::core::BinaryResponseCoding coding = rlispstat::core::InspectBinaryResponse(*column);
        if (coding.ok) eligible.push_back({name, coding});
    }
    if (eligible.empty()) {
        ShowWorkbenchMessageOnMain(@"Binary Regression", @"No variable has exactly two observed non-missing values.");
        return;
    }
    std::size_t chosen = 0;
    for (std::size_t index = 0; index < eligible.size(); ++index) {
        if (eligible[index].first == model->yLabel) { chosen = index; break; }
    }
    GeneralizedGLMState state;
    state.id = "binary_" + model->group + "_" + std::to_string((long long)time(nullptr)) +
        "_" + std::to_string((long long)g_generalizedGLMs.size() + 1);
    state.group = model->group;
    state.seed = *model;
    state.hasSeed = true;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        CaptureActiveAnalysisScopeUnlocked(state.group, state.dataScope, state.dataScopeCaptured);
    }
    state.scope = ScopeForCapturedAnalysisScope(state.dataScope, state.dataScopeCaptured, state.scope);
    state.title = "Binary Regression";
    state.binaryRegression = true;
    state.family = "binomial";
    state.binaryLink = rlispstat::core::BinaryLink::Logit;
    state.link = rlispstat::core::BinaryLinkId(state.binaryLink);
    state.response = eligible[chosen].first;
    state.responseCoding = eligible[chosen].second;
    for (const std::string &candidate : VariableNamesForModel(model)) {
        if (candidate != state.response) {
            state.terms.push_back(candidate);
            break;
        }
    }
    state.modelVersion = 1;
    state.status = "Fitting binary regression in the main R session...";
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        g_generalizedGLMs[state.id] = state;
    }
    ShowGeneralizedGLMOnMain(state.id);
    QueueGeneralizedGLMMainRTask(state);
}

static bool CalculateBinaryLikelihoodRatioInR(const GeneralizedGLMState &left,
                                               const GeneralizedGLMState &right,
                                               GeneralizedComparisonModel &target)
{
    std::string reason;
    if (!rlispstat::core::BinaryModelsCompatibleForLikelihoodRatioTest(left, right, &reason)) return false;
    const GeneralizedGLMState *reduced = &left;
    const GeneralizedGLMState *full = &right;
    if (right.dfResidual > left.dfResidual) { reduced = &right; full = &left; }
    if (!std::isfinite(reduced->residualDeviance) || !std::isfinite(full->residualDeviance)) return false;
    const std::string scriptPath = TempPath("rlispstat_binary_lrt", ".R");
    {
        std::ofstream script(scriptPath);
        script << "args <- commandArgs(TRUE)\n"
                  "reduced_deviance <- as.numeric(args[[1]])\n"
                  "full_deviance <- as.numeric(args[[2]])\n"
                  "reduced_df <- as.integer(args[[3]])\n"
                  "full_df <- as.integer(args[[4]])\n"
                  "statistic <- reduced_deviance - full_deviance\n"
                  "df <- reduced_df - full_df\n"
                  "if (!is.finite(statistic) || statistic < -1e-8 || df <= 0L) quit(status=2L)\n"
                  "statistic <- max(0, statistic)\n"
                  "p <- stats::pchisq(statistic, df, lower.tail=FALSE)\n"
                  "cat(sprintf('%.17g\\t%d\\t%.17g\\n', statistic, df, p))\n";
        if (!script) { unlink(scriptPath.c_str()); return false; }
    }
    std::string command = ShellQuoteSingle(g_rscriptPath) + " --vanilla " + ShellQuoteSingle(scriptPath) +
        " " + ShellQuoteSingle(std::to_string(reduced->residualDeviance)) +
        " " + ShellQuoteSingle(std::to_string(full->residualDeviance)) +
        " " + ShellQuoteSingle(std::to_string(reduced->dfResidual)) +
        " " + ShellQuoteSingle(std::to_string(full->dfResidual)) + " 2>&1";
    FILE *pipe = popen(command.c_str(), "r");
    if (!pipe) { unlink(scriptPath.c_str()); return false; }
    char buffer[256] = {0};
    std::string output;
    while (fgets(buffer, sizeof(buffer), pipe)) output += buffer;
    int rc = pclose(pipe);
    unlink(scriptPath.c_str());
    std::istringstream parsed(output);
    double delta = NAN;
    int df = 0;
    double p = NAN;
    parsed >> delta >> df >> p;
    if (rc != 0 || !std::isfinite(delta) || df <= 0 || !std::isfinite(p)) return false;
    target.comparisonOk = true;
    target.comparisonCalculatedInR = true;
    target.comparisonDf = df;
    target.comparisonDelta = std::max(0.0, delta);
    target.comparisonStatistic = target.comparisonDelta;
    target.comparisonP = p;
    return true;
}

static void ShowNewGeneralizedComparisonOnMain(PlotModel *model)
{
    model = ActiveDatasetCommandModel(model);
    if (!model) {
        ShowWorkbenchMessageOnMain(ToNSString(rlispstat::core::GLMGeneralizedModelComparisonTitle()), ToNSString(NoActiveDatasetImportOrRegisterStatus()));
        return;
    }
    if (GroupIsMultipleImputation(model->group)) {
        ShowWorkbenchMessageOnMain(ToNSString(rlispstat::core::GLMGeneralizedModelComparisonTitle()),
                                   ToNSString(rlispstat::core::GLMComparisonRequiresPooledTestStatus()));
        return;
    }
    std::vector<std::string> numeric = rlispstat::core::NumericVariableNames(model);
    if (numeric.empty()) {
        ShowWorkbenchMessageOnMain(ToNSString(rlispstat::core::GLMGeneralizedModelComparisonTitle()), ToNSString(rlispstat::core::GLMNoNumericResponseVariablesStatus()));
        return;
    }
    GeneralizedComparisonState state;
    state.id = "gglmcmp_" + model->group + "_" + std::to_string((long long)time(nullptr));
    state.group = model->group;
    state.seed = *model;
    state.hasSeed = true;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        CaptureActiveAnalysisScopeUnlocked(state.group, state.dataScope, state.dataScopeCaptured);
    }
    state.scope = ScopeForCapturedAnalysisScope(state.dataScope, state.dataScopeCaptured, state.scope);
    state.response = !model->yLabel.empty() && FindVariable(model, model->yLabel) ? model->yLabel : numeric.front();
    state.family = DefaultGeneralizedFamilyForResponse(*model, state.response);
    state.link = DefaultGeneralizedLink(state.family);
    state.termRows.push_back("(Intercept)");

    GeneralizedComparisonModel nullModel;
    nullModel.id = state.id + ":model:1";
    nullModel.label = "Null";
    nullModel.response = state.response;
    nullModel.family = state.family;
    nullModel.link = state.link;
    state.models.push_back(nullModel);

    GeneralizedComparisonModel modelOne;
    modelOne.id = state.id + ":model:2";
    modelOne.label = "Model 1";
    modelOne.response = state.response;
    modelOne.family = state.family;
    modelOne.link = state.link;
    for (const std::string &candidate : VariableNamesForModel(model)) {
        if (candidate != state.response) {
            modelOne.includedTerms.push_back(candidate);
            AddGeneralizedComparisonTermRow(state, candidate);
            break;
        }
    }
    state.models.push_back(modelOne);
    state.activeModel = state.models.size() > 1 ? 1 : 0;
    RefitGeneralizedComparisonModels(state, true);
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        g_generalizedComparisons[state.id] = state;
    }
    ShowGeneralizedComparisonOnMain(state.id);
}

static void ShowNewBinaryRegressionComparisonOnMain(PlotModel *model)
{
    model = ActiveDatasetCommandModel(model);
    if (!model) {
        ShowWorkbenchMessageOnMain(@"Compare Binary Regression Models", ToNSString(NoActiveDatasetImportOrRegisterStatus()));
        return;
    }
    GeneralizedComparisonState state;
    state.id = "binarycmp_" + model->group + "_" + std::to_string((long long)time(nullptr)) +
        "_" + std::to_string((long long)g_generalizedComparisons.size() + 1);
    state.group = model->group;
    state.family = "binomial";
    state.binaryLink = rlispstat::core::BinaryLink::Logit;
    state.link = rlispstat::core::BinaryLinkId(state.binaryLink);
    state.scope = "all";
    state.binaryComparison = true;
    state.autoRefit = true;
    state.seed = *model;
    state.hasSeed = true;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        CaptureActiveAnalysisScopeUnlocked(state.group, state.dataScope, state.dataScopeCaptured);
    }
    state.scope = ScopeForCapturedAnalysisScope(state.dataScope, state.dataScopeCaptured, state.scope);
    state.termRows.push_back("(Intercept)");
    for (const std::string &name : VariableNamesForModel(model)) {
        const DataColumn *column = FindDataColumnForModel(model, name);
        if (!column) continue;
        rlispstat::core::BinaryResponseCoding coding = rlispstat::core::InspectBinaryResponse(*column);
        if (coding.ok) {
            state.response = name;
            state.responseCoding = coding;
            break;
        }
    }
    GeneralizedComparisonModel reduced;
    reduced.id = state.id + ":model:1";
    reduced.label = "Model 1";
    reduced.response = state.response;
    reduced.family = "binomial";
    reduced.link = state.link;
    state.models.push_back(reduced);

    GeneralizedComparisonModel full = reduced;
    full.id = state.id + ":model:2";
    full.label = "Model 2";
    for (const std::string &candidate : VariableNamesForModel(model)) {
        if (candidate != state.response) {
            full.includedTerms.push_back(candidate);
            AddGeneralizedComparisonTermRow(state, candidate);
            break;
        }
    }
    state.models.push_back(full);
    state.activeModel = 1;
    RefitGeneralizedComparisonModels(state, true);
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        g_generalizedComparisons[state.id] = state;
    }
    ShowGeneralizedComparisonOnMain(state.id);
}

static bool RunNativeMixedModelReport(const NativeMixedModelState &state, std::string *report, std::string *message)
{
    QueueMixedModelMainRTask(state);
    if (report) {
        *report = "Fitting mixed model in the main R session...";
    }
    if (message) {
        message->clear();
    }
    return true;
}

static void ShowNewNativeMixedModelOnMain(PlotModel *model, bool generalized)
{
    model = ActiveDatasetCommandModel(model);
    NSString *title = generalized ? ToNSString(rlispstat::core::MixedModelGeneralizedWindowTitle()) : ToNSString(rlispstat::core::MixedModelLinearWindowTitle());
    if (!model) {
        ShowWorkbenchMessageOnMain(title, ToNSString(NoActiveDatasetImportOrRegisterStatus()));
        return;
    }
    DataFrameModel df;
    bool found = false;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        const DataFrameModel *current = FindDataFrameUnlockedConst(model->group);
        if (current) {
            df = *current;
            found = true;
        }
    }
    if (!found) {
        ShowWorkbenchMessageOnMain(title, ToNSString(ActiveDatasetUnavailableStatus()));
        return;
    }

    MixedModelInitialStateResult initial = BuildInitialMixedModelState(
        df, model->group, generalized, static_cast<long long>(time(nullptr)));
    if (!initial.ok) {
        ShowWorkbenchMessageOnMain(title, ToNSString(initial.message));
        return;
    }
    NativeMixedModelState state = initial.state;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        CaptureActiveAnalysisScopeUnlocked(state.group, state.dataScope, state.dataScopeCaptured);
    }

    std::string report;
    std::string message;
    if (!RunNativeMixedModelReport(state, &report, &message)) {
        ShowWorkbenchMessageOnMain(title, ToNSString(message));
        return;
    }
    state.reportText = report;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        g_nativeMixedModels[state.id] = state;
    }
    ShowMixedModelTextOnMain(state.id, state.group, state.modelType, report);
}

static void RefreshRegressionComparisonWindowsOnMain(const std::string &group, bool selectionChanged)
{
    std::string groupCopy = group;
    dispatch_async(dispatch_get_main_queue(), ^{
      std::vector<RegressionComparisonWindowController *> controllers;
      for (const auto &entry : g_regressionComparisonControllers) {
          RegressionComparisonWindowController *controller = entry.second;
          RegressionComparisonState *state = [controller state];
          if (state && state->group == groupCopy) {
              if (selectionChanged && state->scope != "all" && !state->dataScopeCaptured) {
                  for (RegressionComparisonModel &model : state->models) {
                      model.modelVersion += 1;
                      model.isStale = true;
                  }
              }
              controllers.push_back(controller);
          }
      }
      for (RegressionComparisonWindowController *controller : controllers) {
          [controller refresh];
      }
    });
}

static void RefreshGeneralizedComparisonWindowsOnMain(const std::string &group, bool selectionChanged)
{
    std::string groupCopy = group;
    dispatch_async(dispatch_get_main_queue(), ^{
      std::vector<GeneralizedComparisonWindowController *> controllers;
      for (const auto &entry : g_generalizedComparisonControllers) {
          GeneralizedComparisonWindowController *controller = entry.second;
          GeneralizedComparisonState *state = [controller state];
          if (state && state->group == groupCopy) {
              if (selectionChanged && state->scope != "all" && !state->dataScopeCaptured) {
                  for (GeneralizedComparisonModel &model : state->models) {
                      model.modelVersion += 1;
                      model.isStale = true;
                  }
              }
              controllers.push_back(controller);
          }
      }
      for (GeneralizedComparisonWindowController *controller : controllers) {
          [controller refresh];
      }
    });
}

static void ShowVariablesWindowOnMain(const std::string &group)
{
    std::string groupCopy = group;
    dispatch_async(dispatch_get_main_queue(), ^{
      VariablesWindowController *controller = nil;
      bool hasDataset = false;
      {
          std::lock_guard<std::mutex> lock(g_mutex);
          hasDataset = DatasetExistsUnlocked(groupCopy) || FirstPlotForGroupUnlocked(groupCopy) != nullptr;
          if (hasDataset) {
              EnsureDatasetSeedPlotUnlocked(groupCopy);
          }
          auto it = g_variableControllers.find(groupCopy);
          if (it != g_variableControllers.end()) {
              controller = it->second;
          }
      }
      if (!hasDataset) {
          ShowWorkbenchMessageOnMain(ToNSString(VariableViewTitle()), ToNSString(DatasetNotRegisteredStatus(groupCopy)));
          return;
      }
      if (!controller) {
          controller = [[VariablesWindowController alloc] initWithGroup:groupCopy];
          std::lock_guard<std::mutex> lock(g_mutex);
          g_variableControllers[groupCopy] = controller;
      }
      [controller show];
    });
}

static void ShowDataSheetOnMain(const std::string &group)
{
    std::string groupCopy = group;
