          if (!DatasetExistsUnlocked(groupCopy)) {
              ShowWorkbenchMessageOnMain(ToNSString(DataSheetOpenTitle()), ToNSString(DataSheetBackendPayloadUnavailableStatus()));
              return;
          }
          auto it = g_dataSheetControllers.find(groupCopy);
