          std::lock_guard<std::mutex> lock(g_mutex);
          g_dataSheetControllers[groupCopy] = controller;
      }
      [controller show];
    });
}

static void RevealDataSheetRowOnMain(const std::string &group, int row)
{
    ShowDataSheetOnMain(group);
    const std::string groupCopy = group;
    dispatch_async(dispatch_get_main_queue(), ^{
      DataSheetWindowController *controller = nil;
      {
          std::lock_guard<std::mutex> lock(g_mutex);
          auto found = g_dataSheetControllers.find(groupCopy);
          if (found != g_dataSheetControllers.end()) controller = found->second;
