static void RefreshDataDeskWindowsOnMain(const std::string &group)
{
    std::string groupCopy = group;
    dispatch_async(dispatch_get_main_queue(), ^{
      VariablesWindowController *vars = nil;
      DataSheetWindowController *sheet = nil;
      std::vector<DataSheetWindowController *> detailSheets;
      std::vector<GLMWindowController *> models;
      std::vector<DimensionalityWindowController *> dimensionality;
      {
          std::lock_guard<std::mutex> lock(g_mutex);
          auto vit = g_variableControllers.find(groupCopy);
          if (vit != g_variableControllers.end()) {
              vars = vit->second;
          }
          auto sit = g_dataSheetControllers.find(groupCopy);
          if (sit != g_dataSheetControllers.end()) {
              sheet = sit->second;
          }
          detailSheets = g_detailDataSheetControllers;
          for (const auto &entry : g_glmControllers) {
              if (entry.first == groupCopy) {
                  models.push_back(entry.second);
              }
          }
          for (const auto &entry : g_dimensionalityControllers) {
              auto stateIt = g_dimensionalityModels.find(entry.first);
              if (stateIt != g_dimensionalityModels.end() && stateIt->second.group == groupCopy) {
                  dimensionality.push_back(entry.second);
              }
          }
      }
      if (vars) {
          [vars refresh];
      }
      if (sheet) {
          [sheet refresh];
      }
      for (DataSheetWindowController *detailSheet : detailSheets) {
          [detailSheet refresh];
      }
      for (GLMWindowController *controller : models) {
          [controller refresh];
      }
      for (DimensionalityWindowController *controller : dimensionality) {
          [controller refresh];
      }
      UpdateAnalysisScopeStatusOnMain();
    });
}

