        ShowNewLinkedHistogramDialogOnMain(ActiveDatasetCommandModel(model));
        return;
    case CommandAction::NewBarChart:
        ShowNewLinkedBarplotDialogOnMain(ActiveDatasetCommandModel(model));
        return;
    case CommandAction::BarplotSetX: {
