    case CommandAction::BarplotSplitBy: {
        if (!model || model->kind != "barplot" || request.args.empty()) return;
        rlispstat::core::BarplotSplitState state = rlispstat::core::BarplotStateAfterSplitBy(
            model->barplotXVariables,
            model->xLabel,
            model->barplotSplitVariable,
            model->barplotRowColorDisplay,
            model->barplotShowConditionalPercent,
            request.args[0]);
        if (!state.resetSplitVisualState) return;
        model->barplotSplitVariable = state.splitVariable;
        model->barplotRowColorDisplay = state.rowColorDisplay;
        model->barplotShowConditionalPercent = state.showConditionalPercent;
        ResetBarplotSplitVisualState(model, true);
        rebuildBarplotAndRefresh(ToNSString(rlispstat::core::BarplotWindowTitle()));
        return;
