    case CommandAction::BarplotRowColors: {
        if (!model || model->kind != "barplot" || request.args.empty()) return;
        std::string updated = rlispstat::core::BarplotRowColorDisplayAfterSet(
            request.args[0],
            !model->barplotSplitVariable.empty(),
            model->barplotRowColorDisplay);
        if (updated == model->barplotRowColorDisplay && updated != request.args[0]) return;
        model->barplotRowColorDisplay = updated;
        RedrawPlotOnMain(model->id);
        return;
