    case CommandAction::BarplotSplitStrokeWidth: {
        if (!model || model->kind != "barplot" || request.args.empty()) return;
        std::optional<double> value = rlispstat::core::ParseBarplotSplitStrokeWidthCommandValue(request.args[0]);
        if (!value.has_value()) return;
        model->barplotSplitStrokeWidth = *value;
        RedrawPlotOnMain(model->id);
        return;
    }
    case CommandAction::BarplotSegmentEncoding: {
        if (!model || model->kind != "barplot" || request.args.empty()) return;
        rlispstat::core::BarplotSegmentEncodingState state =
            rlispstat::core::BarplotStateAfterSegmentEncoding(
                model->barplotSegmentEncodingMode,
                model->barplotShowPatterns,
                request.args[0]);
        if (!state.changed) return;
        model->barplotSegmentEncodingMode = state.segmentEncodingMode;
        model->barplotShowPatterns = state.showPatterns;
        RedrawPlotOnMain(model->id);
        return;
