    case CommandAction::BarplotShowPatterns: {
        if (!model || model->kind != "barplot" || request.args.empty()) return;
        model->barplotShowPatterns = rlispstat::core::BarplotShowPatternsAfterCommand(
            model->barplotShowPatterns,
            request.args[0]);
        RedrawPlotOnMain(model->id);
        return;
    }
    case CommandAction::BarplotSelectionDisplay: {
        if (!model || model->kind != "barplot" || request.args.empty()) return;
        std::string updated = rlispstat::core::BarplotSelectionDisplayAfterSet(
            request.args[0],
            model->barplotSelectionDisplay);
        if (updated == model->barplotSelectionDisplay && updated != request.args[0]) return;
        model->barplotSelectionDisplay = updated;
        RedrawPlotOnMain(model->id);
        return;
