    case CommandAction::BarplotMode: {
        if (!model || model->kind != "barplot" || request.args.empty()) return;
        std::string mode = rlispstat::core::BarplotModeAfterSet(request.args[0], model->barplotMode);
        if (mode == model->barplotMode && mode != request.args[0]) return;
        model->barplotMode = mode;
        model->barplotShowConditionalPercent = rlispstat::core::BarplotConditionalPercentForMode(
            mode,
            !model->barplotSplitVariable.empty());
        RedrawPlotOnMain(model->id);
        return;
    }
    case CommandAction::BarplotWidth: {
        if (!model || model->kind != "barplot" || request.args.empty()) return;
        std::string widthMode = rlispstat::core::BarplotWidthModeAfterSet(request.args[0], model->barplotWidthMode);
        if (widthMode == model->barplotWidthMode && widthMode != request.args[0]) return;
        model->barplotWidthMode = widthMode;
        for (BarplotBin &bin : model->barplotBins) {
            bin.widthValue = rlispstat::core::BarplotWidthValueForBin(widthMode, bin.n, bin.percent);
            for (BarplotSegment &segment : bin.segments) {
                segment.barWidthValue = bin.widthValue;
            }
        }
        RedrawPlotOnMain(model->id);
        return;
    }
    case CommandAction::BarplotSegmentSelect: {
        if (!model || model->kind != "barplot") return;
        int barIndex = -1;
        int segmentIndex = -1;
        if (!ParseBarplotSegmentCommandPayload(barplotPayload(), &barIndex, &segmentIndex)) return;
        std::vector<int> segmentRows = rlispstat::core::BarplotRowsForSegmentIndices(
            rlispstat::core::BarplotBinsForModel(model),
            (size_t)barIndex,
            (size_t)segmentIndex);
        if (segmentRows.empty()) return;
        std::set<int> rows(segmentRows.begin(), segmentRows.end());
        int selectionVersion = 0;
        if (MergeSelection(model->group, rows, "replace", &selectionVersion)) {
            PublishSpreadPlotMessage("ROW_SELECTION_CHANGED", model->group, model->id, "", std::vector<int>(rows.begin(), rows.end()), selectionVersion);
        }
        RedrawPlotOnMain(model->id);
        UpdatePanelOnMain();
        return;
    }
    case CommandAction::BarplotSegmentApplyColorToRows: {
        if (!model || model->kind != "barplot") return;
        int barIndex = -1;
        int segmentIndex = -1;
        if (!ParseBarplotSegmentCommandPayload(barplotPayload(), &barIndex, &segmentIndex)) return;
        std::vector<int> segmentRows = rlispstat::core::BarplotRowsForSegmentIndices(
            rlispstat::core::BarplotBinsForModel(model),
            (size_t)barIndex,
            (size_t)segmentIndex);
        if (segmentRows.empty()) return;
        ApplyColorToRows(model->group, segmentRows, SelectedColorForGroup(model->group));
        return;
    }
    case CommandAction::BarplotSegmentSetColor: {
        if (!model || model->kind != "barplot") return;
        int barIndex = -1;
        int segmentIndex = -1;
        std::string colorName;
        if (!ParseBarplotSegmentCommandPayload(barplotPayload(), &barIndex, &segmentIndex, &colorName)) return;
        CGFloat r = 0.0, g = 0.0, b = 0.0;
        if (!rlispstat::core::FindPaletteColor(colorName) && !ParseHexRGB(colorName, &r, &g, &b)) return;
        std::optional<rlispstat::core::BarplotSegmentReference> reference =
            BarplotCoreSegmentReferenceForIndices(model, barIndex, segmentIndex);
        if (!reference.has_value()) return;
        rlispstat::core::BarplotVisualState state = BarplotVisualStateForModel(model);
        if (!rlispstat::core::SetBarplotSegmentColorOverride(state, *reference, colorName)) return;
        ApplyNormalizedBarplotVisualState(model, state);
        RedrawPlotOnMain(model->id);
        return;
    }
    case CommandAction::BarplotLevelSetColor: {
        if (!model || model->kind != "barplot" || request.args.size() < 2) return;
        std::string level = DecodeCommandField(request.args[0]);
        std::string colorName = request.args[1];
        CGFloat r = 0.0, g = 0.0, b = 0.0;
        if (!rlispstat::core::FindPaletteColor(colorName) && !ParseHexRGB(colorName, &r, &g, &b)) return;
        rlispstat::core::BarplotVisualState state = BarplotVisualStateForModel(model);
        if (!rlispstat::core::SetBarplotLevelColorOverride(state, level, colorName)) return;
        ApplyNormalizedBarplotVisualState(model, state);
        RedrawPlotOnMain(model->id);
        return;
    }
    case CommandAction::BarplotSegmentSetAlpha: {
        if (!model || model->kind != "barplot") return;
        int barIndex = -1;
        int segmentIndex = -1;
        std::string alphaText;
        if (!ParseBarplotSegmentCommandPayload(barplotPayload(), &barIndex, &segmentIndex, &alphaText)) return;
        std::optional<double> alpha = rlispstat::core::ParseBarplotSegmentAlphaCommandValue(alphaText);
        if (!alpha.has_value()) return;
        std::optional<rlispstat::core::BarplotSegmentReference> reference =
            BarplotCoreSegmentReferenceForIndices(model, barIndex, segmentIndex);
        if (!reference.has_value()) return;
        rlispstat::core::BarplotVisualState state = BarplotVisualStateForModel(model);
        if (!rlispstat::core::SetBarplotSegmentAlphaOverride(state, *reference, *alpha)) return;
        ApplyNormalizedBarplotVisualState(model, state);
        RedrawPlotOnMain(model->id);
        return;
    }
    case CommandAction::BarplotLevelSetPattern: {
        if (!model || model->kind != "barplot" || request.args.size() < 2) return;
        std::string level = DecodeCommandField(request.args[0]);
        std::string pattern = request.args[1];
        rlispstat::core::BarplotVisualState state = BarplotVisualStateForModel(model);
        if (!rlispstat::core::SetBarplotLevelPatternOverride(state, level, pattern)) return;
        ApplyNormalizedBarplotVisualState(model, state);
        RedrawPlotOnMain(model->id);
        return;
    }
    case CommandAction::BarplotSegmentSetPattern: {
        if (!model || model->kind != "barplot") return;
        int barIndex = -1;
        int segmentIndex = -1;
        std::string pattern;
        if (!ParseBarplotSegmentCommandPayload(barplotPayload(), &barIndex, &segmentIndex, &pattern)) return;
        std::optional<rlispstat::core::BarplotSegmentReference> reference =
            BarplotCoreSegmentReferenceForIndices(model, barIndex, segmentIndex);
        if (!reference.has_value()) return;
        rlispstat::core::BarplotVisualState state = BarplotVisualStateForModel(model);
        if (!rlispstat::core::SetBarplotSegmentPatternOverride(state, *reference, pattern)) return;
        ApplyNormalizedBarplotVisualState(model, state);
        RedrawPlotOnMain(model->id);
        return;
