    case CommandAction::BarplotSegmentResetColor: {
        if (!model || model->kind != "barplot") return;
        int barIndex = -1;
        int segmentIndex = -1;
        if (!ParseBarplotSegmentCommandPayload(barplotPayload(), &barIndex, &segmentIndex)) return;
        std::optional<rlispstat::core::BarplotSegmentReference> reference =
            BarplotCoreSegmentReferenceForIndices(model, barIndex, segmentIndex);
        if (!reference.has_value()) return;
        rlispstat::core::BarplotVisualState state = BarplotVisualStateForModel(model);
        if (!rlispstat::core::ResetBarplotSegmentColorOverride(state, *reference)) return;
        ApplyNormalizedBarplotVisualState(model, state);
        RedrawPlotOnMain(model->id);
        return;
    }
    case CommandAction::BarplotLevelResetColor: {
        if (!model || model->kind != "barplot" || request.args.empty()) return;
        std::string level = DecodeCommandField(request.args[0]);
        rlispstat::core::BarplotVisualState state = BarplotVisualStateForModel(model);
        if (!rlispstat::core::ResetBarplotLevelColorOverride(state, level)) return;
        ApplyNormalizedBarplotVisualState(model, state);
        RedrawPlotOnMain(model->id);
        return;
