    case CommandAction::BarplotSegmentDetails: {
        if (!model || model->kind != "barplot") return;
        int barIndex = -1;
        int segmentIndex = -1;
        if (!ParseBarplotSegmentCommandPayload(barplotPayload(), &barIndex, &segmentIndex)) return;
        std::vector<rlispstat::core::BarplotBinSummary> bins = rlispstat::core::BarplotBinsForModel(model);
        std::optional<rlispstat::core::BarplotSegmentReference> reference =
            (barIndex >= 0 && segmentIndex >= 0)
                ? rlispstat::core::BarplotSegmentReferenceForIndices(
                    bins,
                    (std::size_t)barIndex,
                    (std::size_t)segmentIndex)
                : std::nullopt;
        if (!reference.has_value()) return;
        std::set<int> selection;
        std::map<int, std::string> rowColors;
        {
            std::lock_guard<std::mutex> lock(g_mutex);
            auto sit = g_groupSelections.find(model->group);
            if (sit != g_groupSelections.end()) selection = sit->second;
            auto cit = g_groupPointColors.find(model->group);
            if (cit != g_groupPointColors.end()) rowColors = cit->second;
        }
        std::vector<std::string> splitLevels = BarplotSplitLevels(model);
        size_t levelIndex = rlispstat::core::BarplotLevelIndex(splitLevels, reference->segment.level);
        std::optional<BarplotSegmentVisualStyle> style = ResolveBarplotSegmentVisual(
            model,
            reference->category,
            reference->segment.level,
            levelIndex);
        std::string details = rlispstat::core::BarplotSegmentTooltipText(
            model->xLabel,
            model->barplotSplitVariable,
            model->barplotWidthMode,
            bins[reference->barIndex],
            model->barplotTotalN,
            reference->segment,
            style,
            rowColors,
            selection,
            BarplotPaletteOrder(),
            model->barplotRowColorDisplay != "hide");
        ShowWorkbenchMessageOnMain(ToNSString(rlispstat::core::BoxplotSegmentDetailsWindowTitle()), ToNSString(details));
        return;
    }
    case CommandAction::ContextCorrelationXY:
        if (model) {
            ShowCorrelationMatrixForVariablesOnMain(model, {model->xLabel, model->yLabel},
                                                    "Correlation: " + model->yLabel + " with " + model->xLabel);
        }
        return;
    case CommandAction::ContextDescriptivesXY:
        if (model) {
            ShowTable1ForVariablesOnMain(model, {model->xLabel, model->yLabel}, "",
                                         "Descriptive statistics: " + model->xLabel + " and " + model->yLabel);
        }
        return;
    case CommandAction::ContextLinearModelXY:
        if (model) {
            std::string group = model->group;
            std::string x = model->xLabel;
            std::string y = model->yLabel;
            bool changed = false;
            {
                std::lock_guard<std::mutex> lock(g_mutex);
                PlotModel *seed = FirstPlotForGroupUnlocked(group);
                if (seed && FindVariable(seed, x) && FindVariable(seed, y) && x != y) {
                    GroupModelState &state = EnsureGroupModelUnlocked(group, seed);
                    state.dependent = y;
                    state.terms.clear();
                    state.terms.push_back(x);
                    rlispstat::core::MarkGroupModelChanged(state);
                    changed = true;
                }
            }
            if (changed) {
                PublishSpreadPlotMessage("GLM_SPEC_CHANGED", group, "glm:" + group, "glm:" + group);
                ShowGLMOnMain(model);
            } else {
                ShowWorkbenchMessageOnMain(ToNSString(rlispstat::core::GLMGeneralLinearModelTitle()), ToNSString(rlispstat::core::ScatterplotNoValidXYStatus()));
            }
        }
        return;
    case CommandAction::ContextHistogramFrequency:
        if (model) ShowFrequencyTableForVariableOnMain(model, model->xLabel);
        return;
    case CommandAction::ContextHistogramDescriptives:
        if (model) {
            ShowTable1ForVariablesOnMain(model, {model->xLabel}, "",
                                         "Descriptive statistics: " + model->xLabel);
        }
        return;
    case CommandAction::ContextBarchartTable:
        if (model) {
            std::vector<std::string> xvars = BarplotXVariablesForModel(model);
            std::string groupVar = model->barplotSplitVariable;
            if (groupVar.empty() && xvars.size() > 1) {
                groupVar = xvars[1];
            }
            if (!groupVar.empty() && !xvars.empty()) {
                DataFrameModel df;
                if (DataFrameForContextModel(model, df)) {
                    ShowContingencyTableResultOnMain(df, {xvars.front()}, groupVar, model->id);
                }
            } else if (!xvars.empty()) {
                ShowContingencyTableDialogOnMain(model, xvars.front(), "");
            }
        }
        return;
    case CommandAction::ContextBarchartNestedTable:
        if (model) ShowNestedContingencyTableOnMain(model);
        return;
    case CommandAction::ContextBoxplotDescriptives:
        if (model) {
            std::vector<std::string> vars = model->boxplotVariables;
            if (vars.empty() && !model->yLabel.empty()) vars.push_back(model->yLabel);
            std::string groupVar = BoxplotUsesVariableAxes(model) ? "" : model->xLabel;
            ShowTable1ForVariablesOnMain(model, vars, groupVar,
                                         groupVar.empty() ? "Descriptive statistics: boxplot variables"
                                                          : "Descriptive statistics by " + groupVar);
        }
        return;
    case CommandAction::AnalyzeContingencyTable:
        ShowContingencyTableDialogOnMain(ActiveDatasetCommandModel(model));
        return;
    case CommandAction::OpenCorrelationMatrix:
        ShowNewCorrelationMatrixOnMain(model);
        return;
    case CommandAction::OpenDimensionality:
        ShowNewDimensionalityOnMain(model);
        return;
    case CommandAction::OpenDendrogram:
        ShowNewQuickClusterOnMain(model);
        return;
    case CommandAction::OpenTable1:
        ShowNewTable1OnMain(model);
        return;
    case CommandAction::AnalyzeOneSampleT:
    case CommandAction::AnalyzeIndependentT:
    case CommandAction::AnalyzePairedT:
    case CommandAction::AnalyzeOneWayAnova: {
        if (request.action == CommandAction::AnalyzeOneSampleT) {
            ShowEditableCompareMeansOnMain(model, "one_sample_t");
        } else if (request.action == CommandAction::AnalyzeIndependentT) {
            ShowEditableCompareMeansOnMain(model, "independent_t");
        } else if (request.action == CommandAction::AnalyzePairedT) {
            ShowEditableCompareMeansOnMain(model, "paired_t");
        } else if (request.action == CommandAction::AnalyzeOneWayAnova) {
            ShowEditableCompareMeansOnMain(model, "oneway_anova");
        }
        return;
    }
    case CommandAction::AnalyzeMissingDataImputation:
        ShowMissingDataImputationDialogOnMain(ActiveDatasetCommandModel(model));
        return;
    case CommandAction::OpenGLM:
        ShowGLMOnMain(ActiveDatasetCommandModel(model));
        return;
    case CommandAction::OpenLinearModelTrellis:
        ShowNewLinearModelTrellisDialogOnMain(ActiveDatasetCommandModel(model));
        return;
    case CommandAction::OpenGeneralizedGLM:
        ShowNewGeneralizedGLMOnMain(model);
        return;
    case CommandAction::OpenBinaryRegression:
        ShowNewBinaryRegressionOnMain(model);
        return;
    case CommandAction::OpenGeneralizedComparison:
        ShowNewGeneralizedComparisonOnMain(model);
        return;
    case CommandAction::OpenBinaryRegressionComparison:
        ShowNewBinaryRegressionComparisonOnMain(model);
        return;
    case CommandAction::AnalyzeLinearMixedModel:
        ShowNewNativeMixedModelOnMain(model, false);
        return;
    case CommandAction::AnalyzeGeneralizedMixedModel:
        ShowNewNativeMixedModelOnMain(model, true);
        return;
    case CommandAction::OpenRegressionComparison: {
        model = ActiveDatasetCommandModel(model);
        if (!model) return;
        if (GroupIsMultipleImputation(model->group)) {
            DataFrameModel df;
            bool found = false;
            {
                std::lock_guard<std::mutex> lock(g_mutex);
                const DataFrameModel *current = FindDataFrameUnlockedConst(model->group);
                if (current) {
                    df = *current;
                    found = true;
                }
            }
            if (!found) {
                ShowWorkbenchMessageOnMain(ToNSString(rlispstat::core::RegressionModelComparisonTitle()), ToNSString(ActiveDatasetUnavailableStatus()));
                return;
            }
            std::string response = model->yLabel;
            std::vector<std::string> terms;
            if (!model->xLabel.empty() && model->xLabel != response && FindVariable(model, model->xLabel)) {
                terms.push_back(model->xLabel);
            }
            std::thread worker([df, response, terms]() {
                std::string message;
                bool ok = RunRBackedMultipleImputationAnalysis(
                    df, "regcmp",
                    "regcmp_" + df.group + "_" + std::to_string((long long)time(nullptr)),
                    std::vector<std::string>(), "", response, terms, "all", &message);
                if (!ok) ShowWorkbenchMessageOnMain(ToNSString(rlispstat::core::RegressionModelComparisonTitle()), ToNSString(message));
            });
            worker.detach();
            return;
        }
        RegressionComparisonState state;
        state.id = "regcmp_" + model->group + "_" + std::to_string((long long)time(nullptr));
        state.group = model->group;
        state.response = model->yLabel;
        state.scope = "all";
        state.autoRefit = true;
        state.seed = *model;
        state.hasSeed = true;
        {
            std::lock_guard<std::mutex> lock(g_mutex);
            CaptureActiveAnalysisScopeUnlocked(state.group, state.dataScope, state.dataScopeCaptured);
        }
        state.scope = ScopeForCapturedAnalysisScope(state.dataScope, state.dataScopeCaptured, state.scope);
        state.termRows.push_back("(Intercept)");
        RegressionComparisonModel column;
        column.id = state.id + ":model:1";
        column.label = "Untitled 1";
        column.response = state.response;
        if (!model->xLabel.empty() && model->xLabel != state.response && FindVariable(model, model->xLabel)) {
            column.includedTerms.push_back(model->xLabel);
            rlispstat::core::AddRegressionTermRow(state, model->xLabel);
        }
        state.models.push_back(column);
        RefitRegressionComparisonModels(state, true);
        g_regressionComparisons[state.id] = state;
        ShowRegressionComparisonOnMain(state.id);
        return;
    }
    case CommandAction::SetSelectedColor: {
        std::string color = request.args.empty() ? "" : request.args[0];
        if (color.empty()) return;
        PlotModel *target = ActiveDatasetCommandModel(model);
        if (target) {
            ApplyColorToGroupSelection(target->group, color);
        } else if (model) {
            ApplyColorToGroupSelection(model, color);
        } else {
            std::string group;
            {
                std::lock_guard<std::mutex> lock(g_mutex);
                group = ActiveDatasetGroupUnlocked();
            }
            ApplyColorToGroupSelection(group, color);
        }
        return;
    }
