        if (target) {
            ResetColorForGroupSelection(target->group);
        } else if (model) {
            ResetColorForGroupSelection(model);
        } else {
            std::string group;
            {
                std::lock_guard<std::mutex> lock(g_mutex);
                group = ActiveDatasetGroupUnlocked();
            }
            ResetColorForGroupSelection(group);
        }
