                if (!error.empty()) ShowWorkbenchMessageOnMain(@"Trellis Plot", ToNSString(error));
                return;
            }
            break;
        }
        model->boxplotCategories = rlispstat::core::OrderedBoxplotCategories(
            model->boxplotDefinedCategories,
            BoxplotCasesForModel(*model),
            model->boxplotGroupOrder);
