    case CommandAction::BoxplotClearSplitViolin:
        if (!model) return;
        model->boxplotSplitViolin = false;
        break;
    case CommandAction::BoxplotConfigureSplitViolin: {
        if (!model) return;
        NSAlert *alert = [[NSAlert alloc] init];
        [alert setMessageText:ToNSString(rlispstat::core::BoxplotSplitViolinDialogTitle())];
        [alert setInformativeText:ToNSString(rlispstat::core::BoxplotSplitViolinInfoText())];
        [alert addButtonWithTitle:ToNSString(rlispstat::core::AlertApplyButtonTitle())];
        [alert addButtonWithTitle:ToNSString(rlispstat::core::AlertCancelButtonTitle())];
        NSView *accessory = [[NSView alloc] initWithFrame:NSMakeRect(0, 0, 320, 104)];
        NSTextField *altLabel = GLMLabel(ToNSString(rlispstat::core::BoxplotAlternativeFieldLabel()), NSMakeRect(0, 76, 86, 22), 12, NSFontWeightRegular);
        [accessory addSubview:altLabel];
        NSPopUpButton *altPopup = [[NSPopUpButton alloc] initWithFrame:NSMakeRect(92, 72, 140, 28)];
        [altPopup addItemWithTitle:ToNSString(rlispstat::core::BoxplotLessOptionLabel())];
        [altPopup addItemWithTitle:ToNSString(rlispstat::core::BoxplotGreaterOptionLabel())];
        [altPopup addItemWithTitle:ToNSString(rlispstat::core::BoxplotTwoSidedOptionLabel())];
        [altPopup selectItemWithTitle:ToNSString(model->boxplotSplitAlternative)];
        [accessory addSubview:altPopup];
        [accessory addSubview:GLMLabel(ToNSString(rlispstat::core::BoxplotThresholdLowerFieldLabel()), NSMakeRect(0, 44, 112, 22), 12, NSFontWeightRegular)];
        NSTextField *lowerField = [[NSTextField alloc] initWithFrame:NSMakeRect(118, 42, 120, 24)];
        if (std::isfinite(model->boxplotSplitLower)) {
            [lowerField setStringValue:[NSString stringWithFormat:@"%.6g", model->boxplotSplitLower]];
        } else {
            [lowerField setStringValue:@"0"];
        }
        [accessory addSubview:lowerField];
        [accessory addSubview:GLMLabel(ToNSString(rlispstat::core::BoxplotUpperFieldLabel()), NSMakeRect(0, 12, 112, 22), 12, NSFontWeightRegular)];
        NSTextField *upperField = [[NSTextField alloc] initWithFrame:NSMakeRect(118, 10, 120, 24)];
        if (std::isfinite(model->boxplotSplitUpper)) {
            [upperField setStringValue:[NSString stringWithFormat:@"%.6g", model->boxplotSplitUpper]];
        }
        [accessory addSubview:upperField];
        [alert setAccessoryView:accessory];
        if ([alert runModal] == NSAlertFirstButtonReturn) {
            std::string alternative = [[altPopup titleOfSelectedItem] UTF8String];
            std::string lowerText = [[lowerField stringValue] UTF8String];
            std::string upperText = [[upperField stringValue] UTF8String];
            double lower = std::strtod(lowerText.c_str(), nullptr);
            double upper = upperText.empty() ? NAN : std::strtod(upperText.c_str(), nullptr);
            if (!std::isfinite(lower)) lower = 0.0;
            if (alternative == "two.sided") {
                if (!std::isfinite(upper)) {
                    upper = std::fabs(lower);
                    lower = -upper;
                }
                if (lower > upper) std::swap(lower, upper);
            } else {
                upper = lower;
            }
            model->boxplotSplitAlternative = alternative;
            model->boxplotSplitLower = lower;
            model->boxplotSplitUpper = upper;
            model->boxplotSplitViolin = true;
            model->boxplotShowViolin = true;
        }
        break;
    }
    case CommandAction::BoxplotConfigureH0: {
