        [alert addButtonWithTitle:ToNSString(rlispstat::core::AlertApplyButtonTitle())];
        [alert addButtonWithTitle:ToNSString(rlispstat::core::AlertCancelButtonTitle())];
        NSView *accessory = [[NSView alloc] initWithFrame:NSMakeRect(0, 0, 330, 106)];
        [accessory addSubview:GLMLabel(ToNSString(rlispstat::core::BoxplotH0FieldLabel()), NSMakeRect(0, 76, 80, 22), 12, NSFontWeightRegular)];
        NSTextField *h0Field = [[NSTextField alloc] initWithFrame:NSMakeRect(96, 74, 100, 24)];
        [h0Field setStringValue:[NSString stringWithFormat:@"%.6g", model->boxplotH0]];
        [accessory addSubview:h0Field];
        [accessory addSubview:GLMLabel(ToNSString(rlispstat::core::BoxplotAlternativeFieldLabel()), NSMakeRect(0, 44, 86, 22), 12, NSFontWeightRegular)];
        NSPopUpButton *altPopup = [[NSPopUpButton alloc] initWithFrame:NSMakeRect(96, 40, 140, 28)];
        [altPopup addItemWithTitle:ToNSString(rlispstat::core::BoxplotTwoSidedOptionLabel())];
        [altPopup addItemWithTitle:ToNSString(rlispstat::core::BoxplotLessOptionLabel())];
        [altPopup addItemWithTitle:ToNSString(rlispstat::core::BoxplotGreaterOptionLabel())];
        [altPopup selectItemWithTitle:ToNSString(model->boxplotH0Alternative)];
        [accessory addSubview:altPopup];
        [accessory addSubview:GLMLabel(ToNSString(rlispstat::core::BoxplotDrawsFieldLabel()), NSMakeRect(0, 12, 80, 22), 12, NSFontWeightRegular)];
        NSTextField *drawsField = [[NSTextField alloc] initWithFrame:NSMakeRect(96, 10, 100, 24)];
        [drawsField setStringValue:[NSString stringWithFormat:@"%d", model->boxplotH0Draws]];
        [accessory addSubview:drawsField];
        [alert setAccessoryView:accessory];
        if ([alert runModal] == NSAlertFirstButtonReturn) {
            double h0 = std::strtod([[h0Field stringValue] UTF8String], nullptr);
            int draws = std::atoi([[drawsField stringValue] UTF8String]);
            if (!std::isfinite(h0)) h0 = 0.0;
            model->boxplotH0 = h0;
            model->boxplotH0Alternative = [[altPopup titleOfSelectedItem] UTF8String];
            model->boxplotH0Draws = std::max(100, std::min(200000, draws));
            std::string message;
            if (!RebuildBoxplotH0Simulation(model, &message)) {
                ClearBoxplotH0Simulation(model);
                ShowWorkbenchMessageOnMain(ToNSString(rlispstat::core::BoxplotH0SimulationWindowTitle()), ToNSString(message));
                return;
            }
        }
        break;
    }
