- (NSRect)plotRect
{
    NSRect b = [self bounds];
    CGFloat left = 88.0;
    if (self.model && self.model->kind == "time_series" &&
        self.model->timeSeriesIdentification == "start_labels") {
        NSDictionary *attributes = @{
            NSFontAttributeName: [NSFont systemFontOfSize:10 weight:NSFontWeightMedium]
        };
        CGFloat widest = 0.0;
        for (const InteractionPlotLine &line : self.model->interactionPlotLines) {
            widest = std::max(widest, [ToNSString(line.label) sizeWithAttributes:attributes].width);
        }
        const CGFloat maximumLeft = std::max((CGFloat)88.0, b.size.width - 280.0);
        left = std::min(maximumLeft, std::max((CGFloat)88.0, widest + 24.0));
    }
    return NSMakeRect(left, 42, std::max(10.0, b.size.width - left - 40.0),
                      std::max(10.0, b.size.height - 112));
}

- (NSPoint)screenPointForPoint:(const DataPoint &)p
{
    NSRect r = [self plotRect];
    rlispstat::core::Point point = rlispstat::core::DataToScreen(
        {p.x, p.y},
        {self.model->xmin, self.model->xmax, self.model->ymin, self.model->ymax},
        rlispstat::platform::macos::ToCoreRect(r),
        true
    );
    return rlispstat::platform::macos::ToNSPoint(point);
}

- (NSPoint)dataPointForScreenPoint:(NSPoint)sp
{
    NSRect r = [self plotRect];
    rlispstat::core::Point point = rlispstat::core::ScreenToData(
        rlispstat::platform::macos::ToCorePoint(sp),
        {self.model->xmin, self.model->xmax, self.model->ymin, self.model->ymax},
        rlispstat::platform::macos::ToCoreRect(r),
        true
    );
    return rlispstat::platform::macos::ToNSPoint(point);
}

- (NSString *)rocTooltipTextForPoint:(NSPoint)point
{
    if (!self.model || self.model->glmDiagnosticKind != "roc_curve") return nil;
    const rlispstat::core::ROCThresholdLink *nearest = nullptr;
    double nearestDistance = std::numeric_limits<double>::infinity();
    for (const rlispstat::core::ROCThresholdLink &threshold : self.model->rocThresholds) {
        NSPoint marker = [self screenPointForPoint:threshold.point];
        const double dx = marker.x - point.x;
        const double dy = marker.y - point.y;
        const double distance = std::sqrt(dx * dx + dy * dy);
        if (distance < nearestDistance) { nearestDistance = distance; nearest = &threshold; }
    }
    if (!nearest || nearestDistance > 10.0) return nil;
    return [NSString stringWithFormat:@"Threshold %@\nSensitivity %@ · Specificity %@\nTP %d · FP %d · TN %d · FN %d\n%lu observation%@ cross%@ here",
        SafeNSStringFromUTF8(FormatDoubleOrDash(nearest->threshold, 6)),
        SafeNSStringFromUTF8(FormatDoubleOrDash(nearest->point.y, 4)),
        SafeNSStringFromUTF8(FormatDoubleOrDash(1.0 - nearest->point.x, 4)),
        nearest->truePositive, nearest->falsePositive, nearest->trueNegative, nearest->falseNegative,
        (unsigned long)nearest->crossingRows.size(), nearest->crossingRows.size() == 1 ? @"" : @"s",
        nearest->crossingRows.size() == 1 ? @"es" : @""];
}

- (NSString *)trellisScatterplotTooltipTextForPoint:(NSPoint)point
{
    if (!self.model || self.model->kind != "trellis_scatterplot") return nil;
    const rlispstat::core::TrellisScatterplotLayout layout = [self trellisScatterplotLayout];
    const rlispstat::core::TrellisDerivedMetadata metadata =
        rlispstat::core::DeriveTrellisMetadata(*self.model);
    const std::optional<rlispstat::core::TrellisCaseGeometry> hit =
        rlispstat::core::HitTrellisScatterplotCase(
            layout, rlispstat::platform::macos::ToCorePoint(point), 9.0);
    if (hit && hit->panelIndex < layout.panels.size()) {
        NSMutableString *text = [NSMutableString stringWithFormat:@"Row %d", hit->caseId];
        if (self.model->trellisSpecification.plotType == TrellisPlotType::Scatter) {
            [text appendFormat:@"\n%@: %@\n%@: %@",
                ToNSString(metadata.xVariableId), ToNSString(rlispstat::core::FormatModelNumber(hit->dataPoint.x)),
                ToNSString(metadata.yVariableId), ToNSString(rlispstat::core::FormatModelNumber(hit->dataPoint.y))];
        } else if (self.model->trellisSpecification.plotType == TrellisPlotType::Boxplot) {
            [text appendFormat:@"\n%@: %@", ToNSString(metadata.yVariableId),
                ToNSString(rlispstat::core::FormatModelNumber(hit->dataPoint.y))];
        }
        const rlispstat::core::TrellisPanelLayout &panel = layout.panels[hit->panelIndex];
        for (std::size_t index = 0; index < metadata.conditioningVariableIds.size() &&
             index < panel.conditionValues.size(); ++index) {
            [text appendFormat:@"\n%@: %@", ToNSString(metadata.conditioningVariableIds[index]),
                                              ToNSString(panel.conditionValues[index])];
        }
        return text;
    }
    if (self.model->trellisSpecification.plotType == TrellisPlotType::Bar &&
        !self.model->trellisSpecification.splitVariableId.empty()) {
        const auto plans = rlispstat::core::BuildTrellisPanelRenderPlans(*self.model, layout, {}, {});
        const rlispstat::core::Point corePoint = rlispstat::platform::macos::ToCorePoint(point);
        for (const auto &plan : plans) {
            for (std::size_t barIndex = 0; barIndex < plan.barplotSegments.size(); ++barIndex) {
                for (const auto &segment : plan.barplotSegments[barIndex]) {
                    if (!rlispstat::core::PointInRect(corePoint, segment.rect)) continue;
                    const std::string category = barIndex < plan.barplotBins.size()
                        ? plan.barplotBins[barIndex].category : "";
                    std::string level;
                    if (barIndex < plan.barplotBins.size() &&
                        segment.segmentIndex < plan.barplotBins[barIndex].segments.size()) {
                        level = plan.barplotBins[barIndex].segments[segment.segmentIndex].level;
                    }
                    return [NSString stringWithFormat:@"%@: %@\n%@: %@\nN: %lu",
                        ToNSString(metadata.xVariableId), ToNSString(category),
                        ToNSString(self.model->trellisSpecification.splitVariableId), ToNSString(level),
                        (unsigned long)segment.rows.size()];
                }
            }
        }
    }
    const std::optional<rlispstat::core::TrellisAggregateGeometry> aggregate =
        rlispstat::core::HitTrellisAggregate(layout, rlispstat::platform::macos::ToCorePoint(point));
    if (!aggregate || aggregate->panelIndex >= layout.panels.size()) return nil;
    NSMutableString *text = [NSMutableString stringWithFormat:@"%@: %@",
        ToNSString(metadata.xVariableId), ToNSString(aggregate->label)];
    if (aggregate->kind == rlispstat::core::TrellisAggregateKind::Box) {
        [text appendFormat:@"\nN: %lu\nMedian: %@\nQ1: %@\nQ3: %@",
            (unsigned long)aggregate->caseIds.size(),
            ToNSString(rlispstat::core::FormatModelNumber(aggregate->median)),
            ToNSString(rlispstat::core::FormatModelNumber(aggregate->lower)),
            ToNSString(rlispstat::core::FormatModelNumber(aggregate->upper))];
    } else {
        [text appendFormat:@"\n%@: %@\nN: %lu", ToNSString(metadata.yAxisLabel),
            ToNSString(rlispstat::core::FormatModelNumber(aggregate->value)),
            (unsigned long)aggregate->caseIds.size()];
    }
    const rlispstat::core::TrellisPanelLayout &panel = layout.panels[aggregate->panelIndex];
    for (std::size_t index = 0; index < metadata.conditioningVariableIds.size() &&
         index < panel.conditionValues.size(); ++index) {
        [text appendFormat:@"\n%@: %@", ToNSString(metadata.conditioningVariableIds[index]),
                                          ToNSString(panel.conditionValues[index])];
    }
    return text;
}

- (NSInteger)rocThresholdIndexAtPoint:(NSPoint)point maximumDistance:(double)maximumDistance
{
    if (!self.model || self.model->glmDiagnosticKind != "roc_curve") return -1;
    NSInteger nearestIndex = -1;
    double nearestDistance = std::numeric_limits<double>::infinity();
    for (std::size_t index = 0; index < self.model->rocThresholds.size(); ++index) {
        NSPoint marker = [self screenPointForPoint:self.model->rocThresholds[index].point];
        const double distance = std::hypot(marker.x - point.x, marker.y - point.y);
        if (distance < nearestDistance) { nearestDistance = distance; nearestIndex = (NSInteger)index; }
    }
    return nearestDistance <= maximumDistance ? nearestIndex : -1;
}

- (void)selectROCRowsFromMenu:(id)sender
{
    if (!self.model || self.rocContextThresholdIndex < 0 ||
        (std::size_t)self.rocContextThresholdIndex >= self.model->rocThresholds.size()) return;
    const rlispstat::core::ROCThresholdLink &threshold =
        self.model->rocThresholds[(std::size_t)self.rocContextThresholdIndex];
    NSString *kind = [sender representedObject];
    std::set<int> rows;
    if ([kind isEqualToString:@"false_positive"]) {
        rows.insert(threshold.falsePositiveRows.begin(), threshold.falsePositiveRows.end());
    } else if ([kind isEqualToString:@"false_negative"]) {
        rows.insert(threshold.falseNegativeRows.begin(), threshold.falseNegativeRows.end());
    } else if ([kind isEqualToString:@"misclassified"]) {
        rows.insert(threshold.falsePositiveRows.begin(), threshold.falsePositiveRows.end());
        rows.insert(threshold.falseNegativeRows.begin(), threshold.falseNegativeRows.end());
    } else {
        rows.insert(threshold.crossingRows.begin(), threshold.crossingRows.end());
    }
    int selectionVersion = 0;
    if (MergeSelection(self.model->group, rows, "replace", &selectionVersion)) {
        PublishSpreadPlotMessage("ROW_SELECTION_CHANGED", self.model->group, self.model->id, "",
            std::vector<int>(rows.begin(), rows.end()), selectionVersion);
    }
    [self setNeedsDisplay:YES];
    UpdatePanelOnMain();
}

- (void)updateTrackingAreas
{
    [super updateTrackingAreas];
    if (self.toolTipTag != 0) [self removeToolTip:self.toolTipTag];
    self.toolTipTag = [self addToolTipRect:[self bounds] owner:self userData:NULL];
}

- (NSString *)view:(NSView *)view stringForToolTip:(NSToolTipTag)tag point:(NSPoint)point userData:(void *)data
{
    (void)view; (void)tag; (void)data;
    if (self.model && self.model->kind == "trellis_scatterplot") {
        return [self trellisScatterplotTooltipTextForPoint:point];
    }
    return [self rocTooltipTextForPoint:point];
}

- (void)drawImputationGlyphInRect:(NSRect)glyphRect axisMask:(int)axisMask colorName:(const std::string &)colorName explicitColor:(BOOL)explicitColor selected:(BOOL)selected hasSelection:(BOOL)hasSelection
{
    if (NSIsEmptyRect(glyphRect)) {
        return;
    }
    const BOOL twoAxisGlyph = axisMask == 3;
    NSBezierPath *path = nil;
    if (twoAxisGlyph) {
        path = [NSBezierPath bezierPathWithOvalInRect:glyphRect];
    } else {
        CGFloat radius = std::min(glyphRect.size.width, glyphRect.size.height) / 2.0;
        path = [NSBezierPath bezierPathWithRoundedRect:glyphRect xRadius:radius yRadius:radius];
    }

    CGFloat dim = hasSelection && !selected ? 0.62 : 1.0;
    CGFloat centerAlpha = (selected ? 0.62 : 0.38) * dim;
    CGFloat midAlpha = (selected ? 0.26 : 0.17) * dim;
    CGFloat edgeAlpha = (selected ? 0.02 : 0.01) * dim;
    PlotThemeStyle theme = CurrentPlotThemeStyle();
    NSColor *baseColor = theme.coordinatedMarks && !explicitColor
        ? (selected ? theme.selectedMarkFill : theme.markFill)
        : ColorForName(colorName, 1.0);
    NSColor *centerColor = [baseColor colorWithAlphaComponent:centerAlpha];
    NSColor *midColor = [baseColor colorWithAlphaComponent:midAlpha];
    NSColor *edgeColor = [baseColor colorWithAlphaComponent:edgeAlpha];

    [NSGraphicsContext saveGraphicsState];
    [path addClip];
    if (twoAxisGlyph) {
        NSGradient *gradient = [[NSGradient alloc] initWithColorsAndLocations:
            centerColor, (CGFloat)0.0,
            midColor, (CGFloat)0.48,
            edgeColor, (CGFloat)1.0,
            nil];
        [gradient drawInBezierPath:path relativeCenterPosition:NSZeroPoint];
    } else {
        NSGradient *gradient = [[NSGradient alloc] initWithColorsAndLocations:
            edgeColor, (CGFloat)0.0,
            centerColor, (CGFloat)0.50,
            edgeColor, (CGFloat)1.0,
            nil];
        [gradient drawInBezierPath:path angle:(axisMask == 1 ? 0.0 : 90.0)];
    }
    [NSGraphicsContext restoreGraphicsState];
    if (theme.coordinatedMarks) {
        [(selected ? theme.selectedMarkStroke : theme.markStroke) setStroke];
        [path setLineWidth:selected ? (CGFloat)theme.selectedMarkStrokeWidth : 0.8];
        [path stroke];
    }
}

- (NSRect)scatterMatrixPlotRect
{
    NSRect b = [self bounds];
    return rlispstat::platform::macos::ToNSRect(
        rlispstat::core::ScatterMatrixPlotRectForBounds(b.size.width, b.size.height));
}

- (BOOL)scatterMatrixCellAtPoint:(NSPoint)point row:(NSInteger *)rowOut column:(NSInteger *)columnOut rect:(NSRect *)rectOut
{
    std::vector<std::string> vars = ScatterMatrixVariablesForModel(self.model);
    size_t n = vars.size();
    if (n < 2) return NO;
    rlispstat::core::ScatterMatrixLayout layout{
        rlispstat::platform::macos::ToCoreRect([self scatterMatrixPlotRect]),
        n
    };
    std::optional<rlispstat::core::ScatterMatrixCell> cell =
        rlispstat::core::ScatterMatrixCellAtPoint(layout, rlispstat::platform::macos::ToCorePoint(point));
    if (!cell.has_value()) return NO;
    if (rowOut) *rowOut = (NSInteger)cell->row;
    if (columnOut) *columnOut = (NSInteger)cell->column;
    if (rectOut) *rectOut = rlispstat::platform::macos::ToNSRect(cell->rect);
    return YES;
}

- (NSInteger)scatterMatrixVariableIndexAtPoint:(NSPoint)point
{
    if (!self.model || self.model->kind != "scatter_matrix") return NSNotFound;
    std::vector<std::string> variables = ScatterMatrixVariablesForModel(self.model);
    if (variables.size() < 2) return NSNotFound;
    rlispstat::core::ScatterMatrixLayout layout{
        rlispstat::platform::macos::ToCoreRect([self scatterMatrixPlotRect]),
        variables.size()
    };
    rlispstat::core::ScatterMatrixRenderPlan renderPlan =
        rlispstat::core::BuildScatterMatrixRenderPlan(variables, self.model->title, layout);
    for (std::size_t index = 0; index < renderPlan.diagonalLabels.size(); ++index) {
        NSRect labelRect = rlispstat::platform::macos::ToNSRect(
            renderPlan.diagonalLabels[index].rect);
        if (NSPointInRect(point, NSInsetRect(labelRect, -3.0, -3.0))) {
            return static_cast<NSInteger>(index);
        }
    }
    return NSNotFound;
}

- (NSMenu *)scatterMatrixVariableMenuForIndex:(NSInteger)variableIndex
{
    NSMenu *menu = [[NSMenu alloc] initWithTitle:@"Variables"];
    if (!self.model || self.model->kind != "scatter_matrix" || variableIndex < 0)
        return SnapshotAlbumMenu(menu, @"Scatterplot Matrix");
    if (!g_commandTarget) {
        g_commandTarget = [[CommandTarget alloc] init];
    }
    std::vector<std::string> current = ScatterMatrixVariablesForModel(self.model);
    std::size_t index = static_cast<std::size_t>(variableIndex);
    if (index >= current.size()) return SnapshotAlbumMenu(menu, @"Scatterplot Matrix");
    std::vector<std::string> replacements =
        rlispstat::core::ScatterMatrixVariablesAvailableForReplacement(
            current,
            index,
            rlispstat::core::NumericVariableNames(self.model));
    for (const std::string &name : replacements) {
        std::string command = std::string("SCATTER_MATRIX_REPLACE_VARIABLE|") +
            std::to_string(index) + "|" + name;
        [menu addItem:[self menuItem:ToNSString(name) command:ToNSString(command)]];
    }
    if (replacements.empty()) {
        NSMenuItem *empty = [[NSMenuItem alloc] initWithTitle:@"No other numeric variables"
                                                     action:nil
                                              keyEquivalent:@""];
        [empty setEnabled:NO];
        [menu addItem:empty];
    }
    return SnapshotAlbumMenu(menu, @"Scatterplot Matrix");
}

- (void)showScatterMatrixVariableMenuForIndex:(NSInteger)variableIndex atPoint:(NSPoint)point
{
    NSMenu *menu = [self scatterMatrixVariableMenuForIndex:variableIndex];
    [menu popUpMenuPositioningItem:nil atLocation:point inView:self];
}

- (void)drawScatterMatrix
{
    PlotThemeStyle theme = CurrentPlotThemeStyle();
    std::vector<std::string> vars = ScatterMatrixVariablesForModel(self.model);
    NSRect pr = [self scatterMatrixPlotRect];
    rlispstat::core::ScatterMatrixLayout layout{
        rlispstat::platform::macos::ToCoreRect(pr),
        vars.size()
    };
    rlispstat::core::ScatterMatrixRenderPlan renderPlan =
        rlispstat::core::BuildScatterMatrixRenderPlan(vars, self.model->title, layout);
    pr = rlispstat::platform::macos::ToNSRect(renderPlan.panelRect);
    [theme.panel setFill];
    NSRectFill(pr);

    NSDictionary *titleAttrs = @{
        NSFontAttributeName: [NSFont systemFontOfSize:15 weight:NSFontWeightSemibold],
        NSForegroundColorAttributeName: theme.text
    };
    if (renderPlan.showTitle) {
        NSMutableParagraphStyle *titleStyle = [[NSMutableParagraphStyle alloc] init];
        [titleStyle setAlignment:NSTextAlignmentCenter];
        [titleStyle setLineBreakMode:NSLineBreakByTruncatingTail];
        NSMutableDictionary *centeredTitleAttrs = [titleAttrs mutableCopy];
        [centeredTitleAttrs setObject:titleStyle forKey:NSParagraphStyleAttributeName];
        [ToNSString(renderPlan.title.text) drawInRect:rlispstat::platform::macos::ToNSRect(renderPlan.title.rect)
                                       withAttributes:centeredTitleAttrs];
    }

    if (renderPlan.showEmptyMessage) {
        NSDictionary *messageAttrs = @{
            NSFontAttributeName: [NSFont systemFontOfSize:13 weight:NSFontWeightMedium],
            NSForegroundColorAttributeName: theme.mutedText
        };
        [ToNSString(renderPlan.emptyMessage.text) drawAtPoint:rlispstat::platform::macos::ToNSPoint(
            rlispstat::core::Point{renderPlan.emptyMessage.rect.x, renderPlan.emptyMessage.rect.y})
                                                withAttributes:messageAttrs];
        return;
    }

    size_t n = vars.size();
    std::vector<rlispstat::core::ScatterMatrixVariableSeries> series =
        ScatterMatrixVariableSeriesForModel(self.model, vars);
    std::vector<rlispstat::core::CaseId> visibleCaseIds =
        ScatterMatrixVisibleCaseIdsForModel(self.model);
    std::vector<rlispstat::core::ScatterMatrixCaseGeometry> pointGeometry =
        rlispstat::core::BuildScatterMatrixCaseGeometry(
            series,
            visibleCaseIds,
            layout,
            5.0);

    std::set<int> selection;
    if ((self.model && rlispstat::core::PlotLinksToDataRows(*self.model))) {
        std::lock_guard<std::mutex> lock(g_mutex);
        auto it = g_groupSelections.find(self.model->group);
        if (it != g_groupSelections.end()) {
            selection = it->second;
        }
    }
    std::map<int, std::string> rowColors;
    for (int caseId : visibleCaseIds) {
        std::string rowColor = RowColorForPlot(self.model, caseId);
        if (!rowColor.empty()) {
            rowColors[caseId] = rowColor;
        }
    }
    std::map<int, std::string> rowLabels;
    if (self.model->labelDisplayMode == "all" || self.model->labelDisplayMode == "selected") {
        rowLabels = RowLabelsForPlot(self.model);
    }
    std::vector<rlispstat::core::ScatterMatrixPointDrawItem> pointDrawPlan =
        rlispstat::core::BuildScatterMatrixPointDrawPlan(
            pointGeometry,
            selection,
            rowColors,
            rowLabels,
            self.model->labelDisplayMode,
            n);

    NSDictionary *diagAttrs = @{
        NSFontAttributeName: [NSFont systemFontOfSize:12 weight:NSFontWeightSemibold],
        NSForegroundColorAttributeName: theme.text
    };
    NSDictionary *pointLabelAttrs = @{
        NSFontAttributeName: [NSFont systemFontOfSize:8 weight:NSFontWeightMedium],
        NSForegroundColorAttributeName: theme.text
    };

    NSGraphicsContext *ctx = [NSGraphicsContext currentContext];
    for (const rlispstat::core::ScatterMatrixCellRenderItem &cellItem : renderPlan.cells) {
        NSRect cell = rlispstat::platform::macos::ToNSRect(cellItem.rect);
        [theme.panel setFill];
        NSRectFill(cell);
        [theme.majorGrid setStroke];
        NSBezierPath *frame = [NSBezierPath bezierPathWithRect:cell];
        [frame setLineWidth:0.6];
        [frame stroke];

        if (cellItem.diagonal) {
            if (cellItem.row < renderPlan.diagonalLabels.size()) {
                const rlispstat::core::ScatterMatrixTextRect &label = renderPlan.diagonalLabels[cellItem.row];
                NSMutableParagraphStyle *center = [[NSMutableParagraphStyle alloc] init];
                [center setAlignment:NSTextAlignmentCenter];
                [center setLineBreakMode:NSLineBreakByTruncatingMiddle];
                NSMutableDictionary *attrs = [diagAttrs mutableCopy];
                [attrs setObject:center forKey:NSParagraphStyleAttributeName];
                [ToNSString(label.text) drawInRect:rlispstat::platform::macos::ToNSRect(label.rect)
                                    withAttributes:attrs];
            }
            continue;
        }

        [ctx saveGraphicsState];
        [[NSBezierPath bezierPathWithRect:NSInsetRect(cell, 1.0, 1.0)] addClip];
        for (const rlispstat::core::ScatterMatrixPointDrawItem &pointItem : pointDrawPlan) {
            if (pointItem.row != cellItem.row || pointItem.column != cellItem.column) continue;
            NSPoint sp = rlispstat::platform::macos::ToNSPoint(pointItem.point);
            CGFloat radius = (CGFloat)pointItem.radius;
            if (theme.coordinatedMarks && pointItem.selected) radius *= (CGFloat)theme.selectedMarkScale;
            if (pointItem.hasHalo) {
                CGFloat haloRadius = (CGFloat)pointItem.haloRadius;
                NSColor *haloColor = theme.coordinatedMarks && !pointItem.hasExplicitColor
                    ? theme.selectedMarkFill : ColorForName(pointItem.colorName, (CGFloat)pointItem.haloAlpha);
                [[haloColor colorWithAlphaComponent:(CGFloat)pointItem.haloAlpha] setFill];
                [[NSBezierPath bezierPathWithOvalInRect:NSMakeRect(sp.x - haloRadius, sp.y - haloRadius,
                                                                    haloRadius * 2.0, haloRadius * 2.0)] fill];
            }
            if (theme.coordinatedMarks && !pointItem.hasExplicitColor) {
                [(pointItem.selected ? theme.selectedMarkFill :
                    (theme.hollowUnselectedMarks ? theme.panel : theme.markFill)) setFill];
            } else if (!pointItem.colorName.empty()) {
                [ColorForName(pointItem.colorName, (CGFloat)pointItem.alpha) setFill];
            } else {
                [[NSColor colorWithCalibratedRed:0.070 green:0.080 blue:0.085 alpha:(CGFloat)pointItem.alpha] setFill];
            }
            NSBezierPath *dot = PlotThemeMarkPath(theme, sp, radius, pointItem.selected);
            [dot fill];
            if (theme.coordinatedMarks) {
                NSColor *stroke = pointItem.selected ? theme.selectedMarkStroke :
                    (pointItem.hasExplicitColor ? ColorForName(pointItem.colorName, 0.90) : theme.markStroke);
                [stroke setStroke];
                [dot setLineWidth:pointItem.selected ? (CGFloat)theme.selectedMarkStrokeWidth : 1.0];
                [dot stroke];
            }

            if (pointItem.showLabel) {
                [ToNSString(pointItem.label) drawAtPoint:NSMakePoint(sp.x + 4.0, sp.y - 9.0)
                                          withAttributes:pointLabelAttrs];
            }
        }
        if (!self.model->overlays.empty()) {
            const rlispstat::core::ScatterMatrixVariableSeries &xVar = series[cellItem.column];
            const rlispstat::core::ScatterMatrixVariableSeries &yVar = series[cellItem.row];
            rlispstat::core::ScatterMatrixNumericRange xRange =
                rlispstat::core::ScatterMatrixRangeForValues(xVar.values);
            rlispstat::core::ScatterMatrixNumericRange yRange =
                rlispstat::core::ScatterMatrixRangeForValues(yVar.values);
            if (xRange.minimum < xRange.maximum && yRange.minimum < yRange.maximum) {
                rlispstat::core::Rect innerCell = rlispstat::core::ScatterMatrixInnerCellRect(
                    layout, cellItem.row, cellItem.column, 5.0);
                rlispstat::core::DataViewport vp{
                    xRange.minimum, xRange.maximum,
                    yRange.minimum, yRange.maximum
                };
                auto drawLine = [&](const std::vector<rlispstat::core::ScatterplotPointValue> &pts,
                                    const std::string &colorName, double alpha, double lineWidth,
                                    bool dashed, bool useDefaultDarkColor) {
                    rlispstat::core::SimpleLinearFitResult fit = rlispstat::core::FitSimpleLinearModel(pts);
                    if (!fit.ok) return;
                    rlispstat::core::Point startData{xRange.minimum, fit.intercept + fit.slope * xRange.minimum};
                    rlispstat::core::Point endData{xRange.maximum, fit.intercept + fit.slope * xRange.maximum};
                    rlispstat::core::Point startScreen = rlispstat::core::DataToScreen(startData, vp, innerCell, true);
                    rlispstat::core::Point endScreen = rlispstat::core::DataToScreen(endData, vp, innerCell, true);
                    if (!std::isfinite(startScreen.x) || !std::isfinite(startScreen.y) ||
                        !std::isfinite(endScreen.x) || !std::isfinite(endScreen.y)) return;
                    NSBezierPath *line = [NSBezierPath bezierPath];
                    [line moveToPoint:rlispstat::platform::macos::ToNSPoint(startScreen)];
                    [line lineToPoint:rlispstat::platform::macos::ToNSPoint(endScreen)];
                    [line setLineWidth:(CGFloat)lineWidth];
                    if (dashed) {
                        CGFloat dash[] = {7.0, 4.0};
                        [line setLineDash:dash count:2 phase:0.0];
                    }
                    if (useDefaultDarkColor) {
                        [[NSColor colorWithCalibratedRed:0.070 green:0.080 blue:0.085 alpha:(CGFloat)alpha] setStroke];
                    } else {
                        [ColorForName(colorName, (CGFloat)alpha) setStroke];
                    }
                    [line stroke];
                };
                std::vector<rlispstat::core::ScatterplotPointValue> pts;
                pts.reserve(visibleCaseIds.size());
                for (rlispstat::core::CaseId caseId : visibleCaseIds) {
                    if (caseId <= 0) continue;
                    std::size_t idx = static_cast<std::size_t>(caseId) - 1;
                    if (idx >= xVar.values.size() || idx >= yVar.values.size()) continue;
                    double xv = xVar.values[idx];
                    double yv = yVar.values[idx];
                    if (!std::isfinite(xv) || !std::isfinite(yv)) continue;
                    pts.push_back({caseId, xv, yv});
                }
                if (pts.size() < 2) {}
                for (const rlispstat::core::Overlay &overlay : self.model->overlays) {
                    if (overlay.type != "lm" || !overlay.visible) continue;
                    if (overlay.source == "color") {
                        std::map<std::string, std::vector<rlispstat::core::ScatterplotPointValue>> ptsByColor;
                        for (const rlispstat::core::ScatterplotPointValue &pt : pts) {
                            auto it = rowColors.find(pt.caseId);
                            std::string cn = (it != rowColors.end() && !it->second.empty()) ? it->second : "black";
                            ptsByColor[cn].push_back(pt);
                        }
                        for (const auto &entry : ptsByColor) {
                            drawLine(entry.second, entry.first, 0.98, 2.4, false, false);
                        }
                    } else if (overlay.source == "all") {
                        drawLine(pts, "", 0.90, 2.0, true, true);
                    } else if (overlay.source == "selected") {
                        std::vector<rlispstat::core::ScatterplotPointValue> sel;
                        sel.reserve(pts.size());
                        for (const rlispstat::core::ScatterplotPointValue &pt : pts) {
                            if (selection.find(pt.caseId) != selection.end()) {
                                sel.push_back(pt);
                            }
                        }
                        if (sel.size() >= 2) {
                            drawLine(sel, "gray", 0.95, 2.6, false, false);
                        }
                    }
                }
            }
        }
        [ctx restoreGraphicsState];
    }

    if (self.dragging) {
        NSRect rr = rlispstat::platform::macos::ToNSRect(
            rlispstat::core::BrushRectForGesture(
                rlispstat::platform::macos::ToCorePoint(self.dragStart),
                rlispstat::platform::macos::ToCorePoint(self.dragCurrent),
                self.model->interactionMode == "brush",
                self.model->brushWidth,
                self.model->brushHeight));
        [[NSColor colorWithCalibratedRed:0.125 green:0.445 blue:0.705 alpha:0.16] setFill];
        NSRectFillUsingOperation(rr, NSCompositingOperationSourceOver);
        [[NSColor colorWithCalibratedRed:0.050 green:0.310 blue:0.520 alpha:0.95] setStroke];
        NSFrameRect(rr);
    }
}

- (NSRect)xAxisLabelRect
{
    if (self.model && self.model->kind == "trellis_scatterplot") {
        return NSMakeRect(NSMidX([self bounds]) - 90.0, NSHeight([self bounds]) - 31.0, 180.0, 24.0);
    }
    NSRect pr = [self plotRect];
    return NSMakeRect(pr.origin.x + pr.size.width / 2 - 70,
                      pr.origin.y + pr.size.height + 24,
                      140,
                      22);
}

- (NSRect)yAxisLabelHitRect
{
    if (self.model && self.model->kind == "trellis_scatterplot") {
        return NSMakeRect(2.0, NSMidY([self bounds]) - 90.0, 36.0, 180.0);
    }
    NSRect pr = [self plotRect];
    return NSMakeRect(4,
                      pr.origin.y + pr.size.height / 2 - 80,
                      34,
                      160);
}

- (void)showVariableMenuForAxis:(NSString *)axis atPoint:(NSPoint)point
{
    if (!g_commandTarget) {
        g_commandTarget = [[CommandTarget alloc] init];
    }
    bool isX = [axis isEqualToString:@"x"];
    if (self.model->kind == "pca_biplot" && !self.model->dimensionalityModelId.empty()) {
        auto stateIt = g_dimensionalityModels.find(self.model->dimensionalityModelId);
        if (stateIt != g_dimensionalityModels.end()) {
            const DimensionalityState &state = stateIt->second;
            NSMenu *menu = [[NSMenu alloc] initWithTitle:ToNSString(DimensionalityBiplotDimensionsMenuTitle())];
            for (const DimensionalityComponent &component : state.components) {
                std::string label = DimensionalityComponentMenuLabel(
                    state.method, component.index, component.variance);
                NSString *command = [NSString stringWithFormat:@"%@|%d",
                                     isX ? @"PCA_BIPLOT_SET_X" : @"PCA_BIPLOT_SET_Y",
                                     component.index];
                NSMenuItem *item = [[NSMenuItem alloc] initWithTitle:ToNSString(label) action:@selector(runCommand:) keyEquivalent:@""];
                [item setTarget:g_commandTarget];
                [item setRepresentedObject:command];
                if ((isX && component.index == self.model->biplotXComponent) ||
                    (!isX && component.index == self.model->biplotYComponent)) {
                    [item setState:NSControlStateValueOn];
                }
                [menu addItem:item];
            }
            [menu popUpMenuPositioningItem:nil atLocation:point inView:self];
            return;
        }
    }
    const rlispstat::core::PlotContextMenuTitles contextTitles = rlispstat::core::DefaultPlotContextMenuTitles();
    NSMenu *menu = [[NSMenu alloc] initWithTitle:ToNSString(contextTitles.variables)];
    for (const NumericVariable &var : self.model->variables) {
        NSString *title = ToNSString(var.name);
        NSString *command = [NSString stringWithFormat:@"%@|%@",
                             isX ? @"CHANGE_X_VARIABLE" : @"CHANGE_Y_VARIABLE",
                             title];
        NSMenuItem *item = [[NSMenuItem alloc] initWithTitle:title action:@selector(runCommand:) keyEquivalent:@""];
        [item setTarget:g_commandTarget];
        [item setRepresentedObject:command];
        if ((isX && var.name == self.model->xLabel) || (!isX && var.name == self.model->yLabel)) {
            [item setState:NSControlStateValueOn];
        }
        if (self.model->kind == "trellis_scatterplot" &&
            ((isX && var.name == self.model->yLabel) || (!isX && var.name == self.model->xLabel))) {
            [item setEnabled:NO];
        }
        [menu addItem:item];
    }
    [menu popUpMenuPositioningItem:nil atLocation:point inView:self];
}

- (NSInteger)screeComponentAtPoint:(NSPoint)point
{
    if (!self.model || self.model->kind != "pca_scree") return 0;
    std::vector<rlispstat::core::IndexedScreenPoint> candidates;
    std::vector<rlispstat::core::DimensionalityScreePoint> observed;
    observed.reserve(self.model->points.size());
    for (const DataPoint &p : self.model->points) {
        int component = (int)std::lround(p.x);
        observed.push_back(rlispstat::core::DimensionalityScreePoint{
            component,
            p.x,
            p.y,
            p.row
        });
    }
    rlispstat::core::DimensionalityScreeRenderPlan renderPlan =
        rlispstat::core::BuildDimensionalityScreeRenderPlan(
            observed,
            {},
            rlispstat::core::DataViewport{self.model->xmin, self.model->xmax, self.model->ymin, self.model->ymax},
            rlispstat::platform::macos::ToCoreRect([self plotRect]));
    candidates.reserve(renderPlan.observedPoints.size());
    for (const rlispstat::core::DimensionalityScreeRenderPoint &item : renderPlan.observedPoints) {
        candidates.push_back(rlispstat::core::IndexedScreenPoint{item.component, item.point});
    }
    return (NSInteger)rlispstat::core::HitNearestIndexedPoint(
        rlispstat::platform::macos::ToCorePoint(point), candidates, 9.0);
}

- (std::string)biplotLoadingVariableAtPoint:(NSPoint)point
{
    if (!self.model || self.model->kind != "pca_biplot") return "";
    std::vector<rlispstat::core::DimensionalityBiplotLoadingVector> loadings;
    loadings.reserve(self.model->biplotLoadings.size());
    for (const BiplotLoading &loading : self.model->biplotLoadings) {
        loadings.push_back(rlispstat::core::DimensionalityBiplotLoadingVector{
            loading.variable,
            loading.x,
            loading.y
        });
    }
    rlispstat::core::DimensionalityBiplotRenderPlan renderPlan =
        rlispstat::core::BuildDimensionalityBiplotRenderPlan(
            loadings,
            rlispstat::core::DataViewport{self.model->xmin, self.model->xmax, self.model->ymin, self.model->ymax},
            rlispstat::platform::macos::ToCoreRect([self plotRect]));
    std::vector<rlispstat::core::LabeledScreenSegment> targets;
    targets.reserve(renderPlan.loadings.size());
    NSDictionary *labelAttrs = @{
        NSFontAttributeName: [NSFont systemFontOfSize:10 weight:NSFontWeightSemibold]
    };
    for (const rlispstat::core::DimensionalityBiplotLoadingRenderItem &loading : renderPlan.loadings) {
        NSPoint labelAnchor = rlispstat::platform::macos::ToNSPoint(loading.labelAnchor);
        NSString *label = ToNSString(loading.variable);
        NSSize labelSize = [label sizeWithAttributes:labelAttrs];
        NSRect labelRect = NSInsetRect(NSMakeRect(labelAnchor.x, labelAnchor.y,
                                                  labelSize.width, labelSize.height),
                                       -5.0, -4.0);
        targets.push_back(rlispstat::core::LabeledScreenSegment{
            loading.variable,
            loading.start,
            loading.end,
            rlispstat::platform::macos::ToCoreRect(labelRect),
            true
        });
    }
    return rlispstat::core::HitNearestLabeledSegment(
        rlispstat::platform::macos::ToCorePoint(point), targets, 10.0);
}

- (rlispstat::core::TrellisScatterplotLayout)trellisScatterplotLayout
{
    return rlispstat::core::BuildTrellisScatterplotLayout(
        *self.model,
        rlispstat::platform::macos::ToCoreRect([self bounds]));
}

- (void)clearTrellisDataTableViews
{
    NSNotificationCenter *notifications = [NSNotificationCenter defaultCenter];
    for (NSScrollView *scroll in self.trellisTableScrollViews) {
        [notifications removeObserver:self name:NSViewBoundsDidChangeNotification
                               object:[scroll contentView]];
        [scroll removeFromSuperview];
    }
    for (id adapter in self.trellisTableAdapters) {
        TrellisPanelTableAdapter *panelAdapter = (TrellisPanelTableAdapter *)adapter;
        [notifications removeObserver:self name:NSTableViewColumnDidResizeNotification
                               object:panelAdapter.tableView];
    }
    [self.trellisTableScrollViews removeAllObjects];
    [self.trellisTableAdapters removeAllObjects];
    self.trellisTableSignature = @"";
    [self.trellisTableHorizontalScroller setHidden:YES];
    [self.trellisTableVerticalScroller setHidden:YES];
}

- (void)trellisTableColumnDidResize:(NSNotification *)notification
{
    if (self.synchronizingTrellisTableScroll || !self.model) return;
    NSTableView *source = (NSTableView *)[notification object];
    NSDictionary *info = [notification userInfo];
    NSTableColumn *column = info[@"NSTableColumn"];
    if (!column) {
        NSNumber *index = info[@"NSTableColumnIndex"];
        if (index && [index integerValue] >= 0 &&
            [index integerValue] < (NSInteger)[[source tableColumns] count]) {
            column = [[source tableColumns] objectAtIndex:(NSUInteger)[index integerValue]];
        }
    }
    if (!column) return;
    const std::string identifier([[column identifier] UTF8String]);
    const CGFloat width = [column width];
    self.model->trellisSpecification.dataTable.columnWidths[identifier] = width;
    self.synchronizingTrellisTableScroll = YES;
    for (TrellisPanelTableAdapter *adapter in self.trellisTableAdapters) {
        for (NSTableColumn *candidate in [adapter.tableView tableColumns]) {
            if ([[candidate identifier] isEqualToString:[column identifier]]) [candidate setWidth:width];
        }
    }
    self.synchronizingTrellisTableScroll = NO;
    [self syncTrellisDataTableViews];
}

- (void)refreshTrellisDataTableScrollIndicators
{
    if (!self.model || self.model->trellisSpecification.plotType != TrellisPlotType::DataTable)
        return;
    const TrellisDataTableSpecification &spec = self.model->trellisSpecification.dataTable;
    CGFloat maximumHorizontal = 0.0;
    CGFloat maximumClipWidth = 1.0;
    std::size_t maximumRows = 0;
    std::size_t visibleRows = std::numeric_limits<std::size_t>::max();
    for (std::size_t index = 0; index < [self.trellisTableAdapters count]; ++index) {
        TrellisPanelTableAdapter *adapter = [self.trellisTableAdapters objectAtIndex:index];
        NSScrollView *scroll = [self.trellisTableScrollViews objectAtIndex:index];
        const std::size_t rows = [adapter originalRows].size();
        const std::size_t visible = (std::size_t)std::max<CGFloat>(1.0,
            std::floor(NSHeight([[scroll contentView] bounds]) / 24.0));
        const std::size_t first = spec.verticalScrollMode ==
            TrellisDataTableVerticalScrollMode::Shared ? spec.firstVisibleRow :
            (std::size_t)std::max<CGFloat>(0.0,
                std::floor([[scroll contentView] bounds].origin.y / 24.0));
        NSTextField *rangeLabel = (NSTextField *)[scroll viewWithTag:83002];
        if (rows == 0) {
            [rangeLabel setStringValue:@""];
        } else if (first >= rows) {
            [rangeLabel setStringValue:ToNSString("N = " + std::to_string(rows) +
                " · End of subgroup")];
        } else {
            [rangeLabel setStringValue:ToNSString("Rows " + std::to_string(first + 1) +
                "–" + std::to_string(std::min(rows, first + visible)) +
                " of " + std::to_string(rows))];
        }
        const CGFloat clipWidth = NSWidth([[scroll contentView] bounds]);
        maximumClipWidth = std::max(maximumClipWidth, clipWidth);
        maximumHorizontal = std::max(maximumHorizontal,
            NSWidth([adapter.tableView frame]) - clipWidth);
        maximumRows = std::max(maximumRows, rows);
        visibleRows = std::min(visibleRows, visible);
    }
    if (visibleRows == std::numeric_limits<std::size_t>::max()) visibleRows = 1;
    const std::size_t maximumFirst = maximumRows > visibleRows ? maximumRows - visibleRows : 0;
    [self.trellisTableHorizontalScroller setHidden:maximumHorizontal <= 0.5];
    [self.trellisTableHorizontalScroller setKnobProportion:maximumHorizontal <= 0.5 ? 1.0 :
        std::max(0.08, maximumClipWidth / (maximumClipWidth + maximumHorizontal))];
    [self.trellisTableHorizontalScroller setDoubleValue:maximumHorizontal <= 0.5 ? 0.0 :
        std::min(1.0, spec.horizontalOffset / maximumHorizontal)];
    const BOOL shared = spec.verticalScrollMode == TrellisDataTableVerticalScrollMode::Shared;
    [self.trellisTableVerticalScroller setHidden:!shared || maximumFirst == 0];
    [self.trellisTableVerticalScroller setKnobProportion:maximumRows == 0 ? 1.0 :
        std::min(1.0, (double)visibleRows / (double)maximumRows)];
    [self.trellisTableVerticalScroller setDoubleValue:maximumFirst == 0 ? 0.0 :
        std::min(1.0, (double)spec.firstVisibleRow / (double)maximumFirst)];
}

- (void)trellisTableClipBoundsChanged:(NSNotification *)notification
{
    if (self.synchronizingTrellisTableScroll || !self.model ||
        self.model->trellisSpecification.plotType != TrellisPlotType::DataTable) return;
    NSClipView *source = (NSClipView *)[notification object];
    const NSPoint origin = [source bounds].origin;
    TrellisDataTableSpecification &table = self.model->trellisSpecification.dataTable;
    table.horizontalOffset = origin.x;
    const std::size_t firstRow =
        (std::size_t)std::max<CGFloat>(0.0, std::floor(origin.y / 24.0));
    for (std::size_t index = 0; index < [self.trellisTableScrollViews count]; ++index) {
        NSScrollView *scroll = [self.trellisTableScrollViews objectAtIndex:index];
        if ([scroll contentView] != source) continue;
        TrellisPanelTableAdapter *adapter = [self.trellisTableAdapters objectAtIndex:index];
        table.firstVisibleRowsByPanel[std::string([adapter.tableView.panelLevelId UTF8String])] = firstRow;
        break;
    }
    if (table.verticalScrollMode == TrellisDataTableVerticalScrollMode::Shared) {
        table.firstVisibleRow = firstRow;
    }
    self.synchronizingTrellisTableScroll = YES;
    for (NSScrollView *scroll in self.trellisTableScrollViews) {
        NSClipView *clip = [scroll contentView];
        NSPoint next = [clip bounds].origin;
        next.x = origin.x;
        if (table.verticalScrollMode == TrellisDataTableVerticalScrollMode::Shared) {
            next.y = origin.y;
        }
        [clip scrollToPoint:next];
        [scroll reflectScrolledClipView:clip];
    }
    self.synchronizingTrellisTableScroll = NO;
    [self refreshTrellisDataTableScrollIndicators];
}

- (void)trellisSharedTableScrollerChanged:(id)sender
{
    if (!self.model || self.model->trellisSpecification.plotType != TrellisPlotType::DataTable) return;
    TrellisDataTableSpecification &spec = self.model->trellisSpecification.dataTable;
    if (sender == self.trellisTableHorizontalScroller) {
        CGFloat maximum = 0.0;
        for (NSScrollView *scroll in self.trellisTableScrollViews) {
            maximum = std::max(maximum, NSWidth([[scroll documentView] frame]) -
                NSWidth([[scroll contentView] bounds]));
        }
        spec.horizontalOffset = maximum * [self.trellisTableHorizontalScroller doubleValue];
    } else {
        std::size_t maximumRows = 0;
        std::size_t visibleRows = std::numeric_limits<std::size_t>::max();
        for (TrellisPanelTableAdapter *adapter in self.trellisTableAdapters) {
            maximumRows = std::max(maximumRows, [adapter originalRows].size());
            visibleRows = std::min(visibleRows, (std::size_t)std::max<CGFloat>(1.0,
                std::floor(NSHeight([[adapter.tableView enclosingScrollView] contentView].bounds) / 24.0)));
        }
        if (visibleRows == std::numeric_limits<std::size_t>::max()) visibleRows = 1;
        const std::size_t maximumFirst = maximumRows > visibleRows ? maximumRows - visibleRows : 0;
        spec.firstVisibleRow = (std::size_t)std::llround(
            (double)maximumFirst * [self.trellisTableVerticalScroller doubleValue]);
    }
    self.synchronizingTrellisTableScroll = YES;
    for (NSScrollView *scroll in self.trellisTableScrollViews) {
        NSClipView *clip = [scroll contentView];
        NSPoint origin = [clip bounds].origin;
        origin.x = spec.horizontalOffset;
        if (spec.verticalScrollMode == TrellisDataTableVerticalScrollMode::Shared) {
            origin.y = (CGFloat)spec.firstVisibleRow * 24.0;
        }
        [clip scrollToPoint:origin];
        [scroll reflectScrolledClipView:clip];
    }
    self.synchronizingTrellisTableScroll = NO;
    [self refreshTrellisDataTableScrollIndicators];
}

- (void)syncTrellisDataTableViews
{
    if (!self.model || self.model->kind != "trellis_scatterplot" ||
        !self.model->trellisSpecificationInitialized ||
        self.model->trellisSpecification.plotType != TrellisPlotType::DataTable) {
        if ([self.trellisTableScrollViews count] > 0) [self clearTrellisDataTableViews];
        return;
    }
    DataFrameModel dataFrame;
    std::set<int> selection;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        const DataFrameModel *found = FindDataFrameUnlockedConst(self.model->group);
        if (!found) { [self clearTrellisDataTableViews]; return; }
        dataFrame = *found;
        auto selected = g_groupSelections.find(self.model->group);
        if (selected != g_groupSelections.end()) selection = selected->second;
    }
    rlispstat::core::InitializeTrellisDataTableSpecification(*self.model, dataFrame);
    TrellisDataTableSpecification &tableSpec = self.model->trellisSpecification.dataTable;
    const rlispstat::core::TrellisScatterplotLayout layout = [self trellisScatterplotLayout];
    std::ostringstream signature;
    signature << tableSpec.showOriginalRowIds << '|';
    for (const std::string &variable : tableSpec.displayedVariableIds) signature << variable << '\x1f';
    signature << '|';
    for (const auto &panel : layout.panels) signature << panel.levelId << '\x1e';
    NSString *nextSignature = ToNSString(signature.str());
    const BOOL recreate = ![self.trellisTableSignature isEqualToString:nextSignature] ||
        [self.trellisTableScrollViews count] != layout.panels.size();
    if (recreate) {
        [self clearTrellisDataTableViews];
        self.trellisTableSignature = nextSignature;
        for (std::size_t index = 0; index < layout.panels.size(); ++index) {
            const auto &panel = layout.panels[index];
            NSScrollView *scroll = [[NSScrollView alloc] initWithFrame:
                NSInsetRect(rlispstat::platform::macos::ToNSRect(panel.plotRect), 1.0, 1.0)];
            [scroll setBorderType:NSBezelBorder];
            [scroll setHasHorizontalScroller:NO];
            [scroll setHasVerticalScroller:NO];
            [scroll setDrawsBackground:YES];
            [scroll setBackgroundColor:WorkbenchSurfaceColor()];
            TrellisPanelTableAdapter *adapter = [[TrellisPanelTableAdapter alloc]
                initWithGroup:self.model->group owner:self];
            TrellisPanelTableView *table = [[TrellisPanelTableView alloc]
                initWithFrame:[[scroll contentView] bounds]];
            table.trellisOwner = self;
            table.panelLevelId = ToNSString(panel.levelId);
            table.panelAdapter = adapter;
            adapter.tableView = table;
            [table setDelegate:adapter];
            [table setDataSource:adapter];
            ConfigureSharedDataSheetTable(table, true);
            if (tableSpec.showOriginalRowIds) {
                NSTableColumn *rowColumn = [[NSTableColumn alloc] initWithIdentifier:@"_row"];
                [[rowColumn headerCell] setStringValue:@"Row"];
                const auto width = tableSpec.columnWidths.find("_row");
                [rowColumn setWidth:width == tableSpec.columnWidths.end() ? 56.0 : width->second];
                [[rowColumn dataCell] setAlignment:NSTextAlignmentRight];
                [table addTableColumn:rowColumn];
            }
            for (const std::string &variable : tableSpec.displayedVariableIds) {
                const DataColumn *dataColumn = FindDataColumnInDataFrame(dataFrame, variable);
                if (!dataColumn) continue;
                NSTableColumn *column = [[NSTableColumn alloc] initWithIdentifier:ToNSString(variable)];
                [[column headerCell] setStringValue:ToNSString(variable)];
                [column setSortDescriptorPrototype:[[NSSortDescriptor alloc]
                    initWithKey:ToNSString(variable) ascending:YES
                    selector:@selector(localizedStandardCompare:)]];
                const auto width = tableSpec.columnWidths.find(variable);
                [column setWidth:width == tableSpec.columnWidths.end()
                    ? std::max(90.0, std::min(180.0, 18.0 + (double)variable.size() * 8.0))
                    : width->second];
                if (NormalizeVariableType(dataColumn->type) == "numeric" &&
                    DataColumnAllowsNumeric(*dataColumn)) {
                    [[column dataCell] setAlignment:NSTextAlignmentRight];
                }
                [table addTableColumn:column];
            }
            [scroll setDocumentView:table];
            [[scroll contentView] setPostsBoundsChangedNotifications:YES];
            [[NSNotificationCenter defaultCenter] addObserver:self
                selector:@selector(trellisTableClipBoundsChanged:)
                name:NSViewBoundsDidChangeNotification object:[scroll contentView]];
            [[NSNotificationCenter defaultCenter] addObserver:self
                selector:@selector(trellisTableColumnDidResize:)
                name:NSTableViewColumnDidResizeNotification object:table];
            NSTextField *emptyLabel = GLMLabel(@"No observations", NSMakeRect(8, 38, 180, 20),
                                                10, NSFontWeightRegular);
            [emptyLabel setTag:83001];
            [emptyLabel setTextColor:[NSColor secondaryLabelColor]];
            [emptyLabel setAutoresizingMask:NSViewMaxXMargin | NSViewMaxYMargin];
            [scroll addSubview:emptyLabel];
            NSTextField *rangeLabel = GLMLabel(@"", NSMakeRect(6, 4, 190, 17),
                                                9, NSFontWeightRegular);
            [rangeLabel setTag:83002];
            [rangeLabel setTextColor:[NSColor secondaryLabelColor]];
            [rangeLabel setDrawsBackground:YES];
            [rangeLabel setBackgroundColor:[WorkbenchSurfaceColor() colorWithAlphaComponent:0.88]];
            [rangeLabel setAutoresizingMask:NSViewMaxXMargin | NSViewMinYMargin];
            [scroll addSubview:rangeLabel];
            [self addSubview:scroll positioned:NSWindowAbove relativeTo:self.smoothSpanControl];
            [self.trellisTableScrollViews addObject:scroll];
            [self.trellisTableAdapters addObject:adapter];
        }
    }
    for (std::size_t index = 0; index < layout.panels.size() &&
         index < [self.trellisTableScrollViews count]; ++index) {
        NSScrollView *scroll = [self.trellisTableScrollViews objectAtIndex:index];
        [scroll setFrame:NSInsetRect(
            rlispstat::platform::macos::ToNSRect(layout.panels[index].plotRect), 1.0, 1.0)];
        TrellisPanelTableAdapter *adapter = [self.trellisTableAdapters objectAtIndex:index];
        const std::vector<int> panelRows = rlispstat::core::TrellisPanelOriginalRows(
            *self.model, layout.panels[index].levelId);
        const std::vector<int> ordered = rlispstat::core::OrderedTrellisDataTableRows(
            tableSpec, dataFrame, panelRows, selection);
        [adapter updateDataFrame:dataFrame rows:ordered variables:tableSpec.displayedVariableIds];
        NSMutableArray<NSSortDescriptor *> *sortDescriptors = [NSMutableArray array];
        if (tableSpec.sort.variableId &&
            (tableSpec.sort.order == TrellisDataTableRowOrder::VariableAscending ||
             tableSpec.sort.order == TrellisDataTableRowOrder::VariableDescending)) {
            [sortDescriptors addObject:[[NSSortDescriptor alloc]
                initWithKey:ToNSString(*tableSpec.sort.variableId)
                ascending:tableSpec.sort.order == TrellisDataTableRowOrder::VariableAscending
                selector:@selector(localizedStandardCompare:)]];
        }
        self.synchronizingTrellisTableScroll = YES;
        [adapter.tableView setSortDescriptors:sortDescriptors];
        CGFloat documentWidth = 0.0;
        for (NSTableColumn *column in [adapter.tableView tableColumns]) {
            documentWidth += [column width];
        }
        const NSSize clipSize = [[scroll contentView] bounds].size;
        const CGFloat documentHeight = std::max<CGFloat>(clipSize.height,
            (CGFloat)ordered.size() * ([adapter.tableView rowHeight] +
                [adapter.tableView intercellSpacing].height));
        [adapter.tableView setFrameSize:NSMakeSize(
            std::max(clipSize.width, documentWidth), documentHeight)];
        self.synchronizingTrellisTableScroll = NO;
        [adapter syncSelection:selection];
        NSView *emptyLabel = [scroll viewWithTag:83001];
        [emptyLabel setHidden:!ordered.empty()];
        NSTextField *rangeLabel = (NSTextField *)[scroll viewWithTag:83002];
        if (ordered.empty()) {
            [rangeLabel setStringValue:@""];
        } else {
            const std::size_t logicalFirst = tableSpec.verticalScrollMode ==
                TrellisDataTableVerticalScrollMode::Shared ? tableSpec.firstVisibleRow :
                (std::size_t)std::max<CGFloat>(0.0, std::floor([[scroll contentView] bounds].origin.y / 24.0));
            const std::size_t visible = (std::size_t)std::max<CGFloat>(1.0,
                std::floor(NSHeight([[scroll contentView] bounds]) / 24.0));
            if (logicalFirst >= ordered.size()) {
                [rangeLabel setStringValue:ToNSString("N = " + std::to_string(ordered.size()) +
                    " · End of subgroup")];
            } else {
                [rangeLabel setStringValue:ToNSString("Rows " + std::to_string(logicalFirst + 1) +
                    "–" + std::to_string(std::min(ordered.size(), logicalFirst + visible)) +
                    " of " + std::to_string(ordered.size()))];
            }
        }
        NSClipView *clip = [scroll contentView];
        NSPoint origin = [clip bounds].origin;
        origin.x = tableSpec.horizontalOffset;
        if (tableSpec.verticalScrollMode == TrellisDataTableVerticalScrollMode::Shared) {
            origin.y = (CGFloat)tableSpec.firstVisibleRow * 24.0;
        } else {
            const auto saved = tableSpec.firstVisibleRowsByPanel.find(layout.panels[index].levelId);
            if (saved != tableSpec.firstVisibleRowsByPanel.end()) origin.y = (CGFloat)saved->second * 24.0;
        }
        self.synchronizingTrellisTableScroll = YES;
        [clip scrollToPoint:origin];
        [scroll reflectScrolledClipView:clip];
        self.synchronizingTrellisTableScroll = NO;
    }
    if (!layout.panels.empty()) {
        NSRect matrix = rlispstat::platform::macos::ToNSRect(layout.panelsBoundingRect);
        const CGFloat scrollerThickness = 13.0;
        NSRect horizontalFrame = NSMakeRect(NSMinX(matrix),
            std::min(NSHeight([self bounds]) - scrollerThickness, NSMaxY(matrix) + 2.0),
            NSWidth(matrix), scrollerThickness);
        NSRect verticalFrame = NSMakeRect(
            std::min(NSWidth([self bounds]) - scrollerThickness, NSMaxX(matrix) + 2.0),
            NSMinY(matrix), scrollerThickness, NSHeight(matrix));
        [self.trellisTableHorizontalScroller setFrame:horizontalFrame];
        [self.trellisTableVerticalScroller setFrame:verticalFrame];
        CGFloat maximumHorizontal = 0.0;
        std::size_t maximumRows = 0;
        std::size_t visibleRows = std::numeric_limits<std::size_t>::max();
        for (TrellisPanelTableAdapter *adapter in self.trellisTableAdapters) {
            NSScrollView *scroll = [adapter.tableView enclosingScrollView];
            maximumHorizontal = std::max(maximumHorizontal,
                NSWidth([adapter.tableView frame]) - NSWidth([[scroll contentView] bounds]));
            maximumRows = std::max(maximumRows, [adapter originalRows].size());
            visibleRows = std::min(visibleRows, (std::size_t)std::max<CGFloat>(1.0,
                std::floor(NSHeight([[scroll contentView] bounds]) / 24.0)));
        }
        if (visibleRows == std::numeric_limits<std::size_t>::max()) visibleRows = 1;
        const std::size_t maximumFirst = maximumRows > visibleRows ? maximumRows - visibleRows : 0;
        [self.trellisTableHorizontalScroller setHidden:maximumHorizontal <= 0.5];
        [self.trellisTableHorizontalScroller setKnobProportion:maximumHorizontal <= 0.5 ? 1.0 :
            std::max(0.08, 1.0 - maximumHorizontal /
                (maximumHorizontal + std::max<CGFloat>(1.0, NSWidth(matrix))))];
        [self.trellisTableHorizontalScroller setDoubleValue:maximumHorizontal <= 0.5 ? 0.0 :
            std::min(1.0, tableSpec.horizontalOffset / maximumHorizontal)];
        const BOOL sharedVertical = tableSpec.verticalScrollMode ==
            TrellisDataTableVerticalScrollMode::Shared;
        [self.trellisTableVerticalScroller setHidden:!sharedVertical || maximumFirst == 0];
        [self.trellisTableVerticalScroller setKnobProportion:maximumRows == 0 ? 1.0 :
            std::min(1.0, (double)visibleRows / (double)maximumRows)];
        [self.trellisTableVerticalScroller setDoubleValue:maximumFirst == 0 ? 0.0 :
            std::min(1.0, (double)tableSpec.firstVisibleRow / (double)maximumFirst)];
    }
}

- (void)trellisDataTableSelectionChanged:(id)sender
{
    if (self.updatingTrellisTableSelection || !self.model) return;
    TrellisPanelTableAdapter *adapter = (TrellisPanelTableAdapter *)sender;
    std::set<int> rows;
    NSIndexSet *indexes = [adapter.tableView selectedRowIndexes];
    for (NSUInteger index = [indexes firstIndex]; index != NSNotFound;
         index = [indexes indexGreaterThanIndex:index]) {
        const NSInteger original = [adapter originalRowAtVisualRow:(NSInteger)index];
        if (original > 0) rows.insert((int)original);
    }
    const NSEventModifierFlags modifiers = [[NSApp currentEvent] modifierFlags];
    if ((modifiers & NSEventModifierFlagCommand) ||
        (modifiers & NSEventModifierFlagShift)) {
        std::set<int> global;
        {
            std::lock_guard<std::mutex> lock(g_mutex);
            auto found = g_groupSelections.find(self.model->group);
            if (found != g_groupSelections.end()) global = found->second;
        }
        for (int panelRow : [adapter originalRows]) global.erase(panelRow);
        global.insert(rows.begin(), rows.end());
        rows = std::move(global);
    }
    int version = 0;
    bool changed = false;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        changed = SetGroupSelectionUnlocked(self.model->group, rows, &version);
    }
    if (changed) NotifyPortableSelectionChanged(self.model->group, rows, version, true);
    [self syncTrellisDataTableViews];
    UpdatePanelOnMain();
}

- (void)drawTrellisScatterplot
{
    [self syncTrellisDataTableViews];
    PlotThemeStyle theme = CurrentPlotThemeStyle();
    const rlispstat::core::TrellisScatterplotLayout layout = [self trellisScatterplotLayout];
    const rlispstat::core::TrellisDerivedMetadata metadata =
        rlispstat::core::DeriveTrellisMetadata(*self.model);
    NSDictionary *titleAttrs = @{
        NSFontAttributeName: [NSFont systemFontOfSize:15 weight:NSFontWeightSemibold],
        NSForegroundColorAttributeName: theme.text
    };
    NSDictionary *panelAttrs = @{
        NSFontAttributeName: [NSFont systemFontOfSize:11 weight:NSFontWeightSemibold],
        NSForegroundColorAttributeName: theme.text
    };
    NSDictionary *tickAttrs = @{
        NSFontAttributeName: [NSFont systemFontOfSize:9.5],
        NSForegroundColorAttributeName: theme.mutedText
    };
    NSDictionary *axisAttrs = @{
        NSFontAttributeName: [NSFont systemFontOfSize:12 weight:NSFontWeightMedium],
        NSForegroundColorAttributeName: theme.text
    };
    std::set<int> tableSelection;
    if (self.model->trellisSpecification.plotType == TrellisPlotType::DataTable &&
        self.model->trellisSpecification.dataTable.showSelectionCounts) {
        std::lock_guard<std::mutex> lock(g_mutex);
        auto selected = g_groupSelections.find(self.model->group);
        if (selected != g_groupSelections.end()) tableSelection = selected->second;
    }
    if (!metadata.internalTitle.empty()) {
        NSMutableParagraphStyle *style = [[NSMutableParagraphStyle alloc] init];
        [style setAlignment:NSTextAlignmentCenter];
        NSMutableDictionary *attrs = [titleAttrs mutableCopy];
        [attrs setObject:style forKey:NSParagraphStyleAttributeName];
        std::string displayTitle = metadata.internalTitle;
        if (self.model->trellisSpecification.plotType == TrellisPlotType::DataTable &&
            self.model->trellisSpecification.dataTable.showSelectionCounts) {
            std::set<int> visibleRows;
            for (const DataPoint &point : self.model->points) visibleRows.insert(point.row);
            std::size_t selectedRows = 0;
            for (int row : tableSelection) if (visibleRows.find(row) != visibleRows.end()) ++selectedRows;
            displayTitle += " — " + std::to_string(visibleRows.size()) + " rows, " +
                std::to_string(selectedRows) + " selected";
        }
        [ToNSString(displayTitle) drawInRect:rlispstat::platform::macos::ToNSRect(layout.titleRect)
                                    withAttributes:attrs];
    }
    for (const rlispstat::core::TrellisPanelLayout &panel : layout.panels) {
        const NSRect frame = rlispstat::platform::macos::ToNSRect(panel.frame);
        const NSRect plot = rlispstat::platform::macos::ToNSRect(panel.plotRect);
        [theme.panel setFill];
        NSRectFill(frame);
        [[theme.majorGrid colorWithAlphaComponent:0.24] setFill];
        NSRectFill(rlispstat::platform::macos::ToNSRect(panel.headerRect));
        if (theme.showPanelBorder) {
            [theme.axis setStroke];
            NSFrameRect(plot);
        }
        std::string stripText = panel.columnStripLabel;
        if (!panel.label.empty() && panel.label != panel.columnStripLabel) {
            stripText = stripText.empty() ? panel.label : panel.label + " · " + stripText;
        }
        if (self.model->trellisSpecification.plotType == TrellisPlotType::DataTable &&
            self.model->trellisSpecification.dataTable.showSelectionCounts) {
            const std::vector<int> rows = rlispstat::core::TrellisPanelOriginalRows(
                *self.model, panel.levelId);
            const std::size_t selectedCount = std::count_if(rows.begin(), rows.end(),
                [&](int row) { return tableSelection.find(row) != tableSelection.end(); });
            stripText += " (" + std::to_string(rows.size()) + " rows, " +
                std::to_string(selectedCount) + " selected)";
        }
        if (!stripText.empty()) {
            const NSRect headerRect = rlispstat::platform::macos::ToNSRect(panel.headerRect);
            NSMutableParagraphStyle *stripStyle = [[NSMutableParagraphStyle alloc] init];
            [stripStyle setAlignment:NSTextAlignmentCenter];
            [stripStyle setLineBreakMode:NSLineBreakByTruncatingMiddle];
            NSMutableDictionary *stripAttrs = [panelAttrs mutableCopy];
            [stripAttrs setObject:stripStyle forKey:NSParagraphStyleAttributeName];
            [ToNSString(stripText) drawInRect:NSMakeRect(NSMinX(headerRect) + 5, NSMinY(headerRect) + 3,
                                                            std::max<CGFloat>(10, NSWidth(headerRect) - 10), 17)
                                      withAttributes:stripAttrs];
        }
        if (!panel.rowStripLabel.empty() && rlispstat::core::IsValidRect(panel.rowStripRect)) {
            const NSRect rowStrip = rlispstat::platform::macos::ToNSRect(panel.rowStripRect);
            [[theme.majorGrid colorWithAlphaComponent:0.24] setFill];
            NSRectFill(rowStrip);
            NSString *text = ToNSString(panel.rowStripLabel);
            NSSize textSize = [text sizeWithAttributes:panelAttrs];
            [NSGraphicsContext saveGraphicsState];
            NSAffineTransform *rotation = [NSAffineTransform transform];
            [rotation translateXBy:NSMidX(rowStrip) - textSize.height / 2.0
                               yBy:NSMidY(rowStrip) + textSize.width / 2.0];
            [rotation rotateByDegrees:-90.0];
            [rotation concat];
            [text drawAtPoint:NSMakePoint(0.0, 0.0) withAttributes:panelAttrs];
            [NSGraphicsContext restoreGraphicsState];
        }
        NSBezierPath *headerSeparator = [NSBezierPath bezierPath];
        [headerSeparator moveToPoint:NSMakePoint(NSMinX(plot), NSMinY(plot))];
        [headerSeparator lineToPoint:NSMakePoint(NSMaxX(plot), NSMinY(plot))];
        [headerSeparator setLineWidth:0.7];
        [theme.axis setStroke];
        [headerSeparator stroke];
        NSBezierPath *grid = [NSBezierPath bezierPath];
        for (const rlispstat::core::TrellisAxisTick &tick : panel.xTicks) {
            [grid moveToPoint:NSMakePoint(tick.position, NSMinY(plot))];
            [grid lineToPoint:NSMakePoint(tick.position, NSMaxY(plot))];
            if (panel.showXTickLabels) {
                NSString *label = ToNSString(tick.label);
                NSSize size = [label sizeWithAttributes:tickAttrs];
                [label drawAtPoint:NSMakePoint(tick.position - size.width / 2.0, NSMaxY(plot) + 4.0)
                    withAttributes:tickAttrs];
            }
        }
        for (const rlispstat::core::TrellisAxisTick &tick : panel.yTicks) {
            [grid moveToPoint:NSMakePoint(NSMinX(plot), tick.position)];
            [grid lineToPoint:NSMakePoint(NSMaxX(plot), tick.position)];
            if (panel.showYTickLabels) {
                NSString *label = ToNSString(tick.label);
                NSSize size = [label sizeWithAttributes:tickAttrs];
                const CGFloat labelX = self.model->trellisRowStripsOnLeft
                    ? NSMaxX(plot) + 5.0
                    : NSMinX(plot) - size.width - 5.0;
                [label drawAtPoint:NSMakePoint(labelX,
                                               tick.position - size.height / 2.0)
                    withAttributes:tickAttrs];
            }
        }
        [grid setLineWidth:0.7];
        [theme.majorGrid setStroke];
        [grid stroke];
        NSBezierPath *axes = [NSBezierPath bezierPath];
        [axes moveToPoint:NSMakePoint(NSMinX(plot), NSMaxY(plot))];
        [axes lineToPoint:NSMakePoint(NSMaxX(plot), NSMaxY(plot))];
        const CGFloat yAxisX = self.model->trellisRowStripsOnLeft ? NSMaxX(plot) : NSMinX(plot);
        [axes moveToPoint:NSMakePoint(yAxisX, NSMinY(plot))];
        [axes lineToPoint:NSMakePoint(yAxisX, NSMaxY(plot))];
        [axes setLineWidth:1.0];
        [theme.axis setStroke];
        [axes stroke];
        if (!panel.hasObservations) {
            NSMutableParagraphStyle *emptyStyle = [[NSMutableParagraphStyle alloc] init];
            [emptyStyle setAlignment:NSTextAlignmentCenter];
            NSDictionary *emptyAttrs = @{
                NSFontAttributeName: [NSFont systemFontOfSize:10],
                NSForegroundColorAttributeName: theme.mutedText,
                NSParagraphStyleAttributeName: emptyStyle
            };
            [@"No observations" drawInRect:NSInsetRect(plot, 8.0, NSHeight(plot) / 2.0 - 10.0)
                                withAttributes:emptyAttrs];
        }
    }
    NSString *axis = ToNSString(metadata.xAxisLabel);
    NSSize axisSize = [axis sizeWithAttributes:axisAttrs];
    [axis drawAtPoint:NSMakePoint(layout.xAxisLabelAnchor.x - axisSize.width / 2.0,
                                  layout.xAxisLabelAnchor.y)
        withAttributes:axisAttrs];
    NSString *yAxis = ToNSString(metadata.yAxisLabel);
    NSSize yAxisSize = [yAxis sizeWithAttributes:axisAttrs];
    [NSGraphicsContext saveGraphicsState];
    NSAffineTransform *rotation = [NSAffineTransform transform];
    [rotation translateXBy:layout.yAxisLabelAnchor.x
                       yBy:layout.yAxisLabelAnchor.y + yAxisSize.width / 2.0];
    [rotation rotateByDegrees:-90.0];
    [rotation concat];
    [yAxis drawAtPoint:NSMakePoint(0, 0) withAttributes:axisAttrs];
    [NSGraphicsContext restoreGraphicsState];

    std::set<int> selection;
    std::map<int, std::string> rowColors = RowColorsForPlot(self.model);
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        auto selected = g_groupSelections.find(self.model->group);
        if (selected != g_groupSelections.end()) selection = selected->second;
    }
    std::map<int, std::string> rowLabels;
    if (self.model->labelDisplayMode == "all" || self.model->labelDisplayMode == "selected") {
        rowLabels = RowLabelsForPlot(self.model);
    }
    const std::vector<rlispstat::core::TrellisPanelRenderPlan> panelPlans =
        rlispstat::core::BuildTrellisPanelRenderPlans(
            *self.model, layout, selection, rowColors, rowLabels);
    for (const rlispstat::core::TrellisPanelRenderPlan &plan : panelPlans) {
        NSRect panelPlotRect = rlispstat::platform::macos::ToNSRect(plan.context.plotRect);
        if (self.model->trellisSpecification.plotType == TrellisPlotType::Scatter) {
            DrawScatterplotRenderPlanInPanel(plan.scatterplot, panelPlotRect, theme);
        } else if (self.model->trellisSpecification.plotType == TrellisPlotType::TimeSeries) {
            NSGraphicsContext *context = [NSGraphicsContext currentContext];
            [context saveGraphicsState];
            [[NSBezierPath bezierPathWithRect:panelPlotRect] addClip];
            for (const rlispstat::core::TrellisTimeSeriesLine &series : plan.timeSeriesLines) {
                bool includesSelection = false;
                for (int row : series.caseIds) {
                    if (selection.find(row) != selection.end()) { includesSelection = true; break; }
                }
                const CGFloat alpha = !selection.empty() && !includesSelection ? 0.26 : 0.96;
                NSColor *color = self.model->trellisSpecification.groupingVariableId.empty()
                    ? [theme.geomStroke colorWithAlphaComponent:alpha]
                    : ColorForNameOrHex(series.colorKey, alpha);
                NSBezierPath *line = [NSBezierPath bezierPath];
                for (std::size_t pointIndex = 0; pointIndex < series.points.size(); ++pointIndex) {
                    NSPoint point = rlispstat::platform::macos::ToNSPoint(series.points[pointIndex]);
                    if (pointIndex == 0) [line moveToPoint:point]; else [line lineToPoint:point];
                }
                [line setLineWidth:2.2];
                [line setLineCapStyle:NSLineCapStyleRound];
                [line setLineJoinStyle:NSLineJoinStyleRound];
                [color setStroke];
                [line stroke];
            }
            [context restoreGraphicsState];
            DrawScatterplotRenderPlanInPanel(plan.scatterplot, panelPlotRect, theme);
            NSDictionary *seriesAttrs = @{
                NSFontAttributeName: [NSFont systemFontOfSize:9 weight:NSFontWeightMedium],
                NSForegroundColorAttributeName: theme.text
            };
            for (const rlispstat::core::TimeSeriesLegendItem &item : plan.timeSeriesLegend) {
                if (item.seriesIndex >= plan.timeSeriesLines.size()) continue;
                const auto &series = plan.timeSeriesLines[item.seriesIndex];
                NSColor *color = ColorForNameOrHex(series.colorKey, 0.96);
                NSBezierPath *sample = [NSBezierPath bezierPath];
                [sample moveToPoint:rlispstat::platform::macos::ToNSPoint(item.sampleStart)];
                [sample lineToPoint:rlispstat::platform::macos::ToNSPoint(item.sampleEnd)];
                [sample setLineWidth:2.2]; [color setStroke]; [sample stroke];
                [ToNSString(series.label)
                    drawAtPoint:NSMakePoint(item.labelAnchor.x, item.labelAnchor.y - 9.0)
                    withAttributes:seriesAttrs];
            }
            for (const rlispstat::core::TimeSeriesDirectLabel &label : plan.timeSeriesDirectLabels) {
                NSColor *color = ColorForNameOrHex(label.colorKey, 0.96);
                NSBezierPath *leader = [NSBezierPath bezierPath];
                [leader moveToPoint:rlispstat::platform::macos::ToNSPoint(label.seriesAnchor)];
                [leader lineToPoint:rlispstat::platform::macos::ToNSPoint(label.leaderEnd)];
                [leader setLineWidth:0.9]; [color setStroke]; [leader stroke];
                NSDictionary *labelAttrs = @{
                    NSFontAttributeName: [NSFont systemFontOfSize:9 weight:NSFontWeightMedium],
                    NSForegroundColorAttributeName: color
                };
                NSString *text = ToNSString(label.label);
                const CGFloat textWidth = [text sizeWithAttributes:labelAttrs].width;
                [text drawAtPoint:NSMakePoint(label.labelAnchor.x - textWidth,
                                              label.labelAnchor.y - 7.0)
                    withAttributes:labelAttrs];
            }
        } else if (self.model->trellisSpecification.plotType == TrellisPlotType::Histogram) {
            DrawHistogramRenderPlanInPanel(plan.histogram, panelPlotRect, theme,
                                           self.model->group, selection);
        } else if (self.model->trellisSpecification.plotType == TrellisPlotType::Boxplot) {
            DrawBoxplotRenderPlanInPanel(plan, self.model, theme, rowColors);
        } else if (self.model->trellisSpecification.plotType == TrellisPlotType::Bar) {
            NSGraphicsContext *context = [NSGraphicsContext currentContext];
            [context saveGraphicsState];
            [[NSBezierPath bezierPathWithRect:panelPlotRect] addClip];
            const std::vector<rlispstat::core::Rect> coreRects =
                rlispstat::core::BarplotBarRects(plan.barplotLayout);
            for (std::size_t index = 0; index < coreRects.size() && index < plan.barplotBins.size(); ++index) {
                NSRect barRect = NSIntersectionRect(
                    rlispstat::platform::macos::ToNSRect(coreRects[index]), panelPlotRect);
                [(self.model->trellisSpecification.splitVariableId.empty()
                    ? theme.panel : theme.geomFill) setFill];
                NSRectFillUsingOperation(barRect, NSCompositingOperationSourceOver);
                if (index < plan.barplotSegments.size() && !plan.barplotSegments[index].empty()) {
                    for (const rlispstat::core::BarplotSegmentDrawItem &segment : plan.barplotSegments[index]) {
                        NSRect segmentRect = NSIntersectionRect(
                            rlispstat::platform::macos::ToNSRect(segment.rect), panelPlotRect);
                        DrawBarplotSegmentLayers(segmentRect, self.model, segment.style,
                            segment.levelIndex, false, true, segment.drawBottomEdge);
                        const std::map<int, std::string> *selectionRowColors = &rowColors;
                        std::map<int, std::string> segmentRowColors;
                        if (!segment.useRowColorIdentityLayer && !segment.style.colorKey.empty()) {
                            for (int row : segment.rows) segmentRowColors[row] = segment.style.colorKey;
                            selectionRowColors = &segmentRowColors;
                        }
                        DrawBarplotSelectionLayer(segmentRect, segment.rows, selection,
                                                  *selectionRowColors, self.model);
                        DrawBarplotSegmentBorder(segmentRect, self.model, true, segment.drawBottomEdge);
                    }
                } else {
                    DrawBarplotRowColorIdentityLayer(barRect, plan.barplotBins[index].rows, rowColors, 1.0);
                    DrawBarplotSelectionLayer(barRect, plan.barplotBins[index].rows, selection, rowColors, self.model);
                    DrawBarplotSegmentBorder(barRect, self.model, true, true);
                }
            }
            [context restoreGraphicsState];
        }
        if (self.model->trellisSpecification.plotType == TrellisPlotType::Scatter &&
            self.model->trellisSpecification.connectObservations) {
            NSGraphicsContext *context = [NSGraphicsContext currentContext];
            [context saveGraphicsState];
            [[NSBezierPath bezierPathWithRect:panelPlotRect] addClip];
            std::vector<rlispstat::core::TrellisCaseGeometry> panelCases;
            for (const auto &entry : layout.cases) {
                if (entry.panelIndex == plan.panelIndex) panelCases.push_back(entry);
            }
            std::stable_sort(panelCases.begin(), panelCases.end(), [](const auto &left, const auto &right) {
                if (left.dataPoint.x != right.dataPoint.x) return left.dataPoint.x < right.dataPoint.x;
                return left.caseId < right.caseId;
            });
            NSBezierPath *line = [NSBezierPath bezierPath];
            for (std::size_t index = 0; index < panelCases.size(); ++index) {
                NSPoint point = rlispstat::platform::macos::ToNSPoint(panelCases[index].screenPoint);
                if (index == 0) [line moveToPoint:point]; else [line lineToPoint:point];
            }
            [theme.markStroke setStroke]; [line setLineWidth:1.0]; [line stroke];
            [context restoreGraphicsState];
        }
    }
    if (self.dragging) {
        NSRect brush = rlispstat::platform::macos::ToNSRect(
            rlispstat::core::BrushRectForGesture(
                rlispstat::platform::macos::ToCorePoint(self.dragStart),
                rlispstat::platform::macos::ToCorePoint(self.dragCurrent),
                self.model->interactionMode == "brush",
                self.model->brushWidth,
                self.model->brushHeight));
        const std::optional<std::size_t> activePanel =
            rlispstat::core::TrellisPanelIndexAtPoint(
                layout, rlispstat::platform::macos::ToCorePoint(self.dragStart));
        if (activePanel) {
            brush = NSIntersectionRect(
                brush,
                rlispstat::platform::macos::ToNSRect(layout.panels[*activePanel].plotRect));
        } else {
            brush = NSZeroRect;
        }
        if (!NSIsEmptyRect(brush)) {
            [[theme.accent colorWithAlphaComponent:0.16] setFill];
            NSRectFillUsingOperation(brush, NSCompositingOperationSourceOver);
            [[theme.accent colorWithAlphaComponent:0.95] setStroke];
            NSFrameRect(brush);
        }
    }
}

- (void)drawRect:(NSRect)dirtyRect
{
    (void)dirtyRect;
    PlotThemeOverrideScope snapshotTheme(self.snapshotThemeName);
    [self syncSmoothSpanControl];
    PlotThemeStyle theme = CurrentPlotThemeStyle();
    [theme.background setFill];
    NSRectFill([self bounds]);

    if (self.model->kind == "scatter_matrix") {
        [self drawScatterMatrix];
        return;
    }
    if (self.model->kind == "trellis_scatterplot") {
        [self drawTrellisScatterplot];
        return;
    }

    NSRect pr = [self plotRect];
    [theme.panel setFill];
    NSRectFill(pr);

    NSBezierPath *minorGrid = [NSBezierPath bezierPath];
    [minorGrid setLineWidth:0.5];
    NSBezierPath *majorGrid = [NSBezierPath bezierPath];
    [majorGrid setLineWidth:1.0];
    const int majorTicks = 5;
    const bool temporalXAxis = self.model->kind == "time_series" &&
        self.model->timeSeriesTimeType != "numeric";
    const std::vector<rlispstat::core::TimeSeriesAxisTick> temporalTicks = temporalXAxis
        ? rlispstat::core::BuildTimeSeriesAxisTicks(
              self.model->xmin, self.model->xmax, self.model->timeSeriesTimeType, majorTicks + 1)
        : std::vector<rlispstat::core::TimeSeriesAxisTick>();
    for (int i = 0; i <= majorTicks; ++i) {
        double tx = pr.origin.x + pr.size.width * i / majorTicks;
        double ty = pr.origin.y + pr.size.height * i / majorTicks;
        if (!temporalXAxis) {
            [majorGrid moveToPoint:NSMakePoint(tx, pr.origin.y)];
            [majorGrid lineToPoint:NSMakePoint(tx, pr.origin.y + pr.size.height)];
        }
        [majorGrid moveToPoint:NSMakePoint(pr.origin.x, ty)];
        [majorGrid lineToPoint:NSMakePoint(pr.origin.x + pr.size.width, ty)];
        if (i < majorTicks) {
            double mx = pr.origin.x + pr.size.width * (i + 0.5) / majorTicks;
            double my = pr.origin.y + pr.size.height * (i + 0.5) / majorTicks;
            if (!temporalXAxis) {
                [minorGrid moveToPoint:NSMakePoint(mx, pr.origin.y)];
                [minorGrid lineToPoint:NSMakePoint(mx, pr.origin.y + pr.size.height)];
            }
            [minorGrid moveToPoint:NSMakePoint(pr.origin.x, my)];
            [minorGrid lineToPoint:NSMakePoint(pr.origin.x + pr.size.width, my)];
        }
    }
    if (temporalXAxis && self.model->xmax != self.model->xmin) {
        for (const rlispstat::core::TimeSeriesAxisTick &tick : temporalTicks) {
            const double tx = pr.origin.x +
                (tick.value - self.model->xmin) / (self.model->xmax - self.model->xmin) * pr.size.width;
            [majorGrid moveToPoint:NSMakePoint(tx, pr.origin.y)];
            [majorGrid lineToPoint:NSMakePoint(tx, pr.origin.y + pr.size.height)];
        }
    }
    if (theme.showMinorGrid) {
        [theme.minorGrid setStroke];
        [minorGrid stroke];
    }
    [theme.majorGrid setStroke];
    [majorGrid stroke];

    [theme.axis setStroke];
    NSBezierPath *axes = [NSBezierPath bezierPath];
    [axes setLineWidth:1.2];
    [axes moveToPoint:NSMakePoint(pr.origin.x, pr.origin.y + pr.size.height)];
    [axes lineToPoint:NSMakePoint(pr.origin.x + pr.size.width, pr.origin.y + pr.size.height)];
    [axes moveToPoint:NSMakePoint(pr.origin.x, pr.origin.y)];
    [axes lineToPoint:NSMakePoint(pr.origin.x, pr.origin.y + pr.size.height)];
    [axes stroke];

    NSDictionary *labelAttrs = @{
        NSFontAttributeName: [NSFont systemFontOfSize:12 weight:NSFontWeightMedium],
        NSForegroundColorAttributeName: theme.text
    };
    NSDictionary *tickAttrs = @{
        NSFontAttributeName: [NSFont systemFontOfSize:10],
        NSForegroundColorAttributeName: theme.mutedText
    };
    NSDictionary *titleAttrs = @{
        NSFontAttributeName: [NSFont systemFontOfSize:15 weight:NSFontWeightSemibold],
        NSForegroundColorAttributeName: theme.text
    };
    if (!self.model->title.empty()) {
        NSMutableParagraphStyle *titleStyle = [[NSMutableParagraphStyle alloc] init];
        [titleStyle setAlignment:NSTextAlignmentCenter];
        [titleStyle setLineBreakMode:NSLineBreakByTruncatingTail];
        NSMutableDictionary *centeredTitleAttrs = [titleAttrs mutableCopy];
        [centeredTitleAttrs setObject:titleStyle forKey:NSParagraphStyleAttributeName];
        [ToNSString(self.model->title) drawInRect:NSMakeRect(pr.origin.x, 10, pr.size.width, 22)
                                   withAttributes:centeredTitleAttrs];
    }
    if (self.model->interactionXTicks.empty()) {
        for (int i = 0; i <= majorTicks; ++i) {
            double yv = self.model->ymin + (self.model->ymax - self.model->ymin) * i / majorTicks;
            double ty = pr.origin.y + pr.size.height - pr.size.height * i / majorTicks;
            NSString *yTick = [NSString stringWithFormat:@"%.2g", yv];
            NSSize yTickSize = [yTick sizeWithAttributes:tickAttrs];
            [yTick drawAtPoint:NSMakePoint(pr.origin.x - yTickSize.width - 6.0, ty - yTickSize.height / 2.0)
                withAttributes:tickAttrs];
        }
        if (temporalXAxis && self.model->xmax != self.model->xmin) {
            for (const rlispstat::core::TimeSeriesAxisTick &tick : temporalTicks) {
                const double tx = pr.origin.x +
                    (tick.value - self.model->xmin) / (self.model->xmax - self.model->xmin) * pr.size.width;
                NSString *xTick = ToNSString(tick.label);
                NSSize xTickSize = [xTick sizeWithAttributes:tickAttrs];
                [xTick drawAtPoint:NSMakePoint(tx - xTickSize.width / 2.0,
                                               pr.origin.y + pr.size.height + 6)
                    withAttributes:tickAttrs];
            }
        } else {
            for (int i = 0; i <= majorTicks; ++i) {
                const double xv = self.model->xmin +
                    (self.model->xmax - self.model->xmin) * i / majorTicks;
                const double tx = pr.origin.x + pr.size.width * i / majorTicks;
                NSString *xTick = [NSString stringWithFormat:@"%.2g", xv];
                NSSize xTickSize = [xTick sizeWithAttributes:tickAttrs];
                [xTick drawAtPoint:NSMakePoint(tx - xTickSize.width / 2.0,
                                               pr.origin.y + pr.size.height + 6)
                    withAttributes:tickAttrs];
            }
        }
    } else {
        for (int i = 0; i <= majorTicks; ++i) {
            double yv = self.model->ymin + (self.model->ymax - self.model->ymin) * i / majorTicks;
            double ty = pr.origin.y + pr.size.height - pr.size.height * i / majorTicks;
            NSString *yTick = [NSString stringWithFormat:@"%.2g", yv];
            NSSize yTickSize = [yTick sizeWithAttributes:tickAttrs];
            [yTick drawAtPoint:NSMakePoint(pr.origin.x - yTickSize.width - 6.0, ty - yTickSize.height / 2.0)
                withAttributes:tickAttrs];
        }
        for (const auto &tick : self.model->interactionXTicks) {
            double tx = pr.origin.x + (tick.first - self.model->xmin) / (self.model->xmax - self.model->xmin) * pr.size.width;
            NSString *xTick = ToNSString(tick.second);
            NSSize tickSize = [xTick sizeWithAttributes:tickAttrs];
            [xTick drawAtPoint:NSMakePoint(tx - tickSize.width / 2.0, pr.origin.y + pr.size.height + 6)
                withAttributes:tickAttrs];
        }
    }
    NSString *xLabel = ToNSString(self.model->xLabel);
    NSSize xSize = [xLabel sizeWithAttributes:labelAttrs];
    NSRect xRect = [self xAxisLabelRect];
    [xLabel drawAtPoint:NSMakePoint(xRect.origin.x + (xRect.size.width - xSize.width) / 2,
                                    xRect.origin.y + 2)
                                 withAttributes:labelAttrs];

    NSString *yLabel = ToNSString(self.model->yLabel);
    NSSize ySize = [yLabel sizeWithAttributes:labelAttrs];
    NSGraphicsContext *ctx = [NSGraphicsContext currentContext];
    [ctx saveGraphicsState];
    NSAffineTransform *transform = [NSAffineTransform transform];
    [transform translateXBy:18 yBy:pr.origin.y + pr.size.height / 2 + ySize.width / 2];
    [transform rotateByDegrees:-90.0];
    [transform concat];
    [yLabel drawAtPoint:NSMakePoint(0, -ySize.height / 2)
         withAttributes:labelAttrs];
    [ctx restoreGraphicsState];

    std::set<int> selection;
    if ((self.model && rlispstat::core::PlotLinksToDataRows(*self.model))) {
        std::lock_guard<std::mutex> lock(g_mutex);
        auto it = g_groupSelections.find(self.model->group);
        if (it != g_groupSelections.end()) {
            selection = it->second;
        }
    }
    int focusedDimensionalityComponent = 0;
    std::string focusedDimensionalityVariable;
    if (!self.model->dimensionalityModelId.empty()) {
        std::lock_guard<std::mutex> lock(g_mutex);
        auto stateIt = g_dimensionalityModels.find(self.model->dimensionalityModelId);
        if (stateIt != g_dimensionalityModels.end()) {
            focusedDimensionalityComponent = stateIt->second.focusedComponent;
            focusedDimensionalityVariable = stateIt->second.focusedVariable;
        }
    }
    rlispstat::core::DimensionalityScreeRenderPlan screeRenderPlan;
    if (self.model->kind == "pca_scree") {
        std::vector<rlispstat::core::DimensionalityScreePoint> observed;
        std::vector<rlispstat::core::DimensionalityScreePoint> parallel;
        observed.reserve(self.model->points.size());
        parallel.reserve(self.model->screeParallelPoints.size());
        for (const DataPoint &p : self.model->points) {
            observed.push_back(rlispstat::core::DimensionalityScreePoint{
                (int)std::lround(p.x),
                p.x,
                p.y,
                p.row
            });
        }
        for (const DataPoint &p : self.model->screeParallelPoints) {
            parallel.push_back(rlispstat::core::DimensionalityScreePoint{
                (int)std::lround(p.x),
                p.x,
                p.y,
                p.row
            });
        }
        screeRenderPlan = rlispstat::core::BuildDimensionalityScreeRenderPlan(
            observed,
            parallel,
            rlispstat::core::DataViewport{self.model->xmin, self.model->xmax, self.model->ymin, self.model->ymax},
            rlispstat::platform::macos::ToCoreRect(pr),
            focusedDimensionalityComponent);
    }
    rlispstat::core::DimensionalityBiplotRenderPlan biplotRenderPlan;
    if (self.model->kind == "pca_biplot" && !self.model->biplotLoadings.empty()) {
        std::vector<rlispstat::core::DimensionalityBiplotLoadingVector> loadings;
        loadings.reserve(self.model->biplotLoadings.size());
        for (const BiplotLoading &loading : self.model->biplotLoadings) {
            loadings.push_back(rlispstat::core::DimensionalityBiplotLoadingVector{
                loading.variable,
                loading.x,
                loading.y
            });
        }
        biplotRenderPlan = rlispstat::core::BuildDimensionalityBiplotRenderPlan(
            loadings,
            rlispstat::core::DataViewport{self.model->xmin, self.model->xmax, self.model->ymin, self.model->ymax},
            rlispstat::platform::macos::ToCoreRect(pr),
            focusedDimensionalityVariable);
    }

    [ctx saveGraphicsState];
    NSBezierPath *clipPath = [NSBezierPath bezierPathWithRect:pr];
    [clipPath addClip];
    if (self.model->glmDiagnosticKind == "roc_curve" && self.model->rocStepPoints.size() >= 2) {
        NSBezierPath *chance = [NSBezierPath bezierPath];
        [chance moveToPoint:[self screenPointForPoint:DataPoint{0.0, 0.0, 0}]];
        [chance lineToPoint:[self screenPointForPoint:DataPoint{1.0, 1.0, 0}]];
        CGFloat chanceDash[] = {5.0, 4.0};
        [chance setLineDash:chanceDash count:2 phase:0.0];
        [chance setLineWidth:1.0];
        [(theme.coordinatedMarks ? theme.reference : [NSColor colorWithCalibratedWhite:0.48 alpha:0.75]) setStroke];
        [chance stroke];
        NSBezierPath *roc = [NSBezierPath bezierPath];
        for (std::size_t index = 0; index < self.model->rocStepPoints.size(); ++index) {
            NSPoint point = [self screenPointForPoint:self.model->rocStepPoints[index]];
            if (index == 0) [roc moveToPoint:point]; else [roc lineToPoint:point];
        }
        [roc setLineWidth:2.4];
        [(theme.coordinatedMarks ? theme.geomStroke :
            [NSColor colorWithCalibratedRed:0.070 green:0.080 blue:0.085 alpha:0.92]) setStroke];
        [roc stroke];
    }
    if (self.model->kind == "pca_scree" && screeRenderPlan.observedLine.size() >= 2) {
        if (screeRenderPlan.parallelLine.size() >= 2) {
            NSBezierPath *parallelLine = [NSBezierPath bezierPath];
            for (std::size_t i = 0; i < screeRenderPlan.parallelLine.size(); ++i) {
                NSPoint sp = rlispstat::platform::macos::ToNSPoint(screeRenderPlan.parallelLine[i]);
                if (i == 0) {
                    [parallelLine moveToPoint:sp];
                } else {
                    [parallelLine lineToPoint:sp];
                }
            }
            CGFloat dash[] = {6.0, 4.0};
            [parallelLine setLineDash:dash count:2 phase:0.0];
            [parallelLine setLineWidth:2.0];
            [(theme.coordinatedMarks ? theme.auxiliary :
                [NSColor colorWithCalibratedRed:0.835 green:0.369 blue:0.000 alpha:0.90]) setStroke];
            [parallelLine stroke];
        }
        NSBezierPath *line = [NSBezierPath bezierPath];
        for (std::size_t i = 0; i < screeRenderPlan.observedLine.size(); ++i) {
            NSPoint sp = rlispstat::platform::macos::ToNSPoint(screeRenderPlan.observedLine[i]);
            if (i == 0) {
                [line moveToPoint:sp];
            } else {
                [line lineToPoint:sp];
            }
        }
        [line setLineWidth:2.0];
        [(theme.coordinatedMarks ? theme.geomStroke :
            [NSColor colorWithCalibratedRed:0.000 green:0.447 blue:0.698 alpha:0.88]) setStroke];
        [line stroke];
        NSDictionary *legendAttrs = @{
            NSFontAttributeName: [NSFont systemFontOfSize:10 weight:NSFontWeightMedium],
            NSForegroundColorAttributeName: theme.text
        };
        [ToNSString(rlispstat::core::BoxplotObservedLabel()) drawAtPoint:NSMakePoint(pr.origin.x + pr.size.width - 122.0, pr.origin.y + 10.0)
                  withAttributes:legendAttrs];
        [ToNSString(rlispstat::core::BoxplotParallelLabel()) drawAtPoint:NSMakePoint(pr.origin.x + pr.size.width - 122.0, pr.origin.y + 26.0)
                  withAttributes:legendAttrs];
    }
    if ((self.model->kind == "glm_interaction" || self.model->kind == "time_series") &&
        !self.model->interactionPlotLines.empty()) {
        const bool timeSeries = self.model->kind == "time_series";
        const bool groupedTimeSeries = timeSeries && !self.model->timeSeriesGroupVariable.empty();
        const bool showLegend = !timeSeries ||
            (groupedTimeSeries && self.model->timeSeriesIdentification == "legend");
        NSDictionary *legendAttrs = @{
            NSFontAttributeName: [NSFont systemFontOfSize:10 weight:NSFontWeightMedium],
            NSForegroundColorAttributeName: theme.text
        };
        for (size_t lineIndex = 0; lineIndex < self.model->interactionPlotLines.size(); ++lineIndex) {
            const InteractionPlotLine &series = self.model->interactionPlotLines[lineIndex];
            if (series.points.empty()) continue;
            bool includesSelectedPoint = false;
            for (const DataPoint &point : series.points) {
                if (selection.find(point.row) != selection.end()) {
                    includesSelectedPoint = true;
                    break;
                }
            }
            const CGFloat alpha = timeSeries && !selection.empty() && !includesSelectedPoint ? 0.26 : 0.96;
            NSColor *seriesColor = timeSeries && self.model->timeSeriesGroupVariable.empty()
                ? [theme.geomStroke colorWithAlphaComponent:alpha]
                : ColorForNameOrHex(series.colorKey, alpha);
            NSBezierPath *line = [NSBezierPath bezierPath];
            bool started = false;
            for (const DataPoint &p : series.points) {
                NSPoint sp = [self screenPointForPoint:p];
                if (!started) {
                    [line moveToPoint:sp];
                    started = true;
                } else {
                    [line lineToPoint:sp];
                }
            }
            [line setLineWidth:2.2];
            [line setLineCapStyle:NSLineCapStyleRound];
            [line setLineJoinStyle:NSLineJoinStyleRound];
            [seriesColor setStroke];
            [line stroke];
            if (!timeSeries) {
                [seriesColor setFill];
                for (const DataPoint &p : series.points) {
                    NSPoint sp = [self screenPointForPoint:p];
                    [[NSBezierPath bezierPathWithOvalInRect:NSMakeRect(sp.x - 2.3, sp.y - 2.3, 4.6, 4.6)] fill];
                }
            }
        }
        auto seriesColorAtIndex = [&](std::size_t lineIndex) -> NSColor * {
            const InteractionPlotLine &series = self.model->interactionPlotLines[lineIndex];
            bool includesSelectedPoint = false;
            for (const DataPoint &point : series.points) {
                if (selection.find(point.row) != selection.end()) {
                    includesSelectedPoint = true;
                    break;
                }
            }
            const CGFloat alpha = timeSeries && !selection.empty() && !includesSelectedPoint ? 0.26 : 0.96;
            return timeSeries && self.model->timeSeriesGroupVariable.empty()
                ? [theme.geomStroke colorWithAlphaComponent:alpha]
                : ColorForNameOrHex(series.colorKey, alpha);
        };
        if (showLegend) {
            const rlispstat::core::Rect coreRect{
                pr.origin.x, pr.origin.y, pr.size.width, pr.size.height};
            const std::vector<rlispstat::core::TimeSeriesLegendItem> items =
                rlispstat::core::BuildTimeSeriesLegendLayout(
                    self.model->interactionPlotLines.size(), coreRect,
                    timeSeries ? self.model->timeSeriesLegendPosition : "top_right");
            for (const rlispstat::core::TimeSeriesLegendItem &item : items) {
                NSColor *seriesColor = seriesColorAtIndex(item.seriesIndex);
                NSBezierPath *sample = [NSBezierPath bezierPath];
                [sample moveToPoint:NSMakePoint(item.sampleStart.x, item.sampleStart.y)];
                [sample lineToPoint:NSMakePoint(item.sampleEnd.x, item.sampleEnd.y)];
                [sample setLineWidth:2.2];
                [seriesColor setStroke];
                [sample stroke];
                [ToNSString(self.model->interactionPlotLines[item.seriesIndex].label)
                    drawAtPoint:NSMakePoint(item.labelAnchor.x, item.labelAnchor.y - 10.0)
                    withAttributes:legendAttrs];
            }
        } else if (groupedTimeSeries && self.model->timeSeriesIdentification == "start_labels") {
            const rlispstat::core::DataViewport viewport{
                self.model->xmin, self.model->xmax, self.model->ymin, self.model->ymax};
            const rlispstat::core::Rect coreRect{
                pr.origin.x, pr.origin.y, pr.size.width, pr.size.height};
            const std::vector<rlispstat::core::TimeSeriesDirectLabel> labels =
                rlispstat::core::BuildTimeSeriesDirectLabels(
                    self.model->interactionPlotLines, viewport, coreRect);
            for (const rlispstat::core::TimeSeriesDirectLabel &label : labels) {
                NSColor *seriesColor = seriesColorAtIndex(label.seriesIndex);
                NSBezierPath *leader = [NSBezierPath bezierPath];
                [leader moveToPoint:NSMakePoint(label.seriesAnchor.x, label.seriesAnchor.y)];
                [leader lineToPoint:NSMakePoint(label.leaderEnd.x, label.leaderEnd.y)];
                [leader setLineWidth:0.9];
                [seriesColor setStroke];
                [leader stroke];
                NSDictionary *directLabelAttrs = @{
                    NSFontAttributeName: [NSFont systemFontOfSize:10 weight:NSFontWeightMedium],
                    NSForegroundColorAttributeName: seriesColor
                };
                NSString *text = ToNSString(label.label);
                const CGFloat textWidth = [text sizeWithAttributes:directLabelAttrs].width;
                [text drawAtPoint:NSMakePoint(label.labelAnchor.x - textWidth,
                                              label.labelAnchor.y - 7.0)
                    withAttributes:directLabelAttrs];
            }
        }
    }
    std::vector<rlispstat::core::ScatterplotPointValue> scatterPoints;
    scatterPoints.reserve(self.model->points.size());
    for (const DataPoint &p : self.model->points) {
        scatterPoints.push_back(rlispstat::core::ScatterplotPointValue{p.row, p.x, p.y});
    }
    std::vector<rlispstat::core::ScatterplotOverlaySpec> overlaySpecs;
    overlaySpecs.reserve(self.model->overlays.size());
    for (const Overlay &overlay : self.model->overlays) {
        overlaySpecs.push_back(rlispstat::core::ScatterplotOverlaySpec{
            overlay.type,
            overlay.source,
            overlay.visible
        });
    }
    std::map<int, std::string> overlayRowColors = RowColorsForPlot(self.model);
    std::map<int, std::string> rowLabels;
    if (self.model->labelDisplayMode == "all" || self.model->labelDisplayMode == "selected") {
        rowLabels = RowLabelsForPlot(self.model);
    }
    const BOOL hasSelection = !selection.empty();
    DataFrameModel imputationDf;
    bool drawImputationGlyphs = false;
    if (self.model->kind == "scatter") {
        std::lock_guard<std::mutex> lock(g_mutex);
        const DataFrameModel *df = FindDataFrameUnlockedConst(self.model->group);
        if (df && DataFrameShowsAllImputations(*df)) {
            imputationDf = *df;
            drawImputationGlyphs = true;
        }
    }
    const DataColumn *imputationXCol = drawImputationGlyphs ? FindDataColumnInDataFrame(imputationDf, self.model->xLabel) : nullptr;
    const DataColumn *imputationYCol = drawImputationGlyphs ? FindDataColumnInDataFrame(imputationDf, self.model->yLabel) : nullptr;
    drawImputationGlyphs = drawImputationGlyphs && imputationXCol && imputationYCol;

    rlispstat::core::ScatterplotRenderInput scatterRenderInput;
    scatterRenderInput.points = scatterPoints;
    scatterRenderInput.viewport = rlispstat::core::DataViewport{self.model->xmin, self.model->xmax, self.model->ymin, self.model->ymax};
    scatterRenderInput.plotRect = rlispstat::platform::macos::ToCoreRect(pr);
    scatterRenderInput.selectedRows = selection;
    scatterRenderInput.rowColors = overlayRowColors;
    scatterRenderInput.rowLabels = rowLabels;
    scatterRenderInput.labelDisplayMode = self.model->labelDisplayMode;
    scatterRenderInput.overlays = overlaySpecs;
    scatterRenderInput.selectedColorName = SelectedColorForGroup(self.model->group);
    scatterRenderInput.imputationDataFrame = drawImputationGlyphs ? &imputationDf : nullptr;
    scatterRenderInput.xColumn = imputationXCol;
    scatterRenderInput.yColumn = imputationYCol;
    scatterRenderInput.imputationUncertaintyMode = self.model->scatterImputationUncertainty;
    scatterRenderInput.skipNonCaseRows = self.model->kind == "glm_interaction";
    scatterRenderInput.smoothCurves = self.model->smoothCurves;
    rlispstat::core::ScatterplotRenderPlan scatterRenderPlan =
        rlispstat::core::BuildScatterplotRenderPlan(scatterRenderInput);

    for (const rlispstat::core::ScatterplotOverlayDrawItem &overlayLine : scatterRenderPlan.overlayLines) {
        NSPoint p1 = rlispstat::platform::macos::ToNSPoint(overlayLine.start);
        NSPoint p2 = rlispstat::platform::macos::ToNSPoint(overlayLine.end);
        NSBezierPath *line = [NSBezierPath bezierPath];
        [line moveToPoint:p1];
        [line lineToPoint:p2];
        if (overlayLine.dashed) {
            CGFloat dash[] = {7.0, 4.0};
            [line setLineDash:dash count:2 phase:0.0];
        }
        [line setLineWidth:(CGFloat)overlayLine.lineWidth];
        if (overlayLine.useDefaultDarkColor) {
            [(theme.coordinatedMarks ? theme.smooth :
                [NSColor colorWithCalibratedRed:0.070 green:0.080 blue:0.085 alpha:(CGFloat)overlayLine.alpha]) setStroke];
        } else {
            [ColorForName(overlayLine.colorName, (CGFloat)overlayLine.alpha) setStroke];
        }
        [line stroke];
    }
    for (const rlispstat::core::ScatterplotSmoothCurveDrawItem &smoothCurve : scatterRenderPlan.smoothCurves) {
        if (smoothCurve.points.size() < 2) continue;
        NSBezierPath *path = [NSBezierPath bezierPath];
        NSPoint sp = rlispstat::platform::macos::ToNSPoint(smoothCurve.points[0]);
        [path moveToPoint:sp];
        for (size_t pi = 1; pi < smoothCurve.points.size(); ++pi) {
            sp = rlispstat::platform::macos::ToNSPoint(smoothCurve.points[pi]);
            [path lineToPoint:sp];
        }
        if (smoothCurve.dashed) {
            CGFloat dash[] = {8.0, 5.0};
            [path setLineDash:dash count:2 phase:0.0];
        }
        [path setLineWidth:(CGFloat)smoothCurve.lineWidth];
        if (smoothCurve.colorName.empty()) {
            [(theme.coordinatedMarks ? theme.smooth :
                [NSColor colorWithCalibratedRed:0.070 green:0.080 blue:0.085 alpha:(CGFloat)smoothCurve.alpha]) setStroke];
        } else {
            [ColorForName(smoothCurve.colorName, (CGFloat)smoothCurve.alpha) setStroke];
        }
        [path stroke];
    }
    if (!biplotRenderPlan.loadings.empty()) {
        NSDictionary *loadingAttrs = @{
            NSFontAttributeName: [NSFont systemFontOfSize:10 weight:NSFontWeightSemibold],
            NSForegroundColorAttributeName: (theme.coordinatedMarks ? theme.auxiliary :
                [NSColor colorWithCalibratedRed:0.760 green:0.260 blue:0.050 alpha:0.98])
        };
        NSDictionary *focusedLoadingAttrs = @{
            NSFontAttributeName: [NSFont systemFontOfSize:11 weight:NSFontWeightBold],
            NSForegroundColorAttributeName: (theme.coordinatedMarks ? theme.selectedMarkFill :
                [NSColor colorWithCalibratedRed:0.000 green:0.300 blue:0.520 alpha:1.0])
        };
        for (const rlispstat::core::DimensionalityBiplotLoadingRenderItem &loading : biplotRenderPlan.loadings) {
            NSPoint start = rlispstat::platform::macos::ToNSPoint(loading.start);
            NSPoint end = rlispstat::platform::macos::ToNSPoint(loading.end);
            NSBezierPath *arrow = [NSBezierPath bezierPath];
            [arrow moveToPoint:start];
            [arrow lineToPoint:end];
            [arrow setLineWidth:loading.focused ? 3.0 : 1.6];
            NSColor *arrowColor = loading.focused
                ? (theme.coordinatedMarks ? theme.selectedMarkFill : [NSColor colorWithCalibratedRed:0.000 green:0.447 blue:0.698 alpha:0.98])
                : (theme.coordinatedMarks ? theme.auxiliary : [NSColor colorWithCalibratedRed:0.835 green:0.369 blue:0.000 alpha:0.88]);
            [arrowColor setStroke];
            [arrow stroke];
            NSBezierPath *headPath = [NSBezierPath bezierPath];
            [headPath moveToPoint:end];
            [headPath lineToPoint:rlispstat::platform::macos::ToNSPoint(loading.arrowHeadA)];
            [headPath moveToPoint:end];
            [headPath lineToPoint:rlispstat::platform::macos::ToNSPoint(loading.arrowHeadB)];
            [headPath setLineWidth:loading.focused ? 3.0 : 1.6];
            [headPath stroke];
            NSString *label = ToNSString(loading.variable);
            NSPoint labelAnchor = rlispstat::platform::macos::ToNSPoint(loading.labelAnchor);
            if (loading.focused) {
                NSSize labelSize = [label sizeWithAttributes:focusedLoadingAttrs];
                NSRect labelBg = NSMakeRect(labelAnchor.x - 3.0, labelAnchor.y - 3.0, labelSize.width + 8.0, labelSize.height + 6.0);
                [[(theme.coordinatedMarks ? theme.selectedMarkFill :
                    [NSColor colorWithCalibratedRed:0.000 green:0.447 blue:0.698 alpha:1.0]) colorWithAlphaComponent:0.10] setFill];
                [[NSBezierPath bezierPathWithRoundedRect:labelBg xRadius:4.0 yRadius:4.0] fill];
            }
            [label drawAtPoint:labelAnchor
                withAttributes:(loading.focused ? focusedLoadingAttrs : loadingAttrs)];
        }
    }
    [ctx restoreGraphicsState];

    if (self.model->kind == "pca_scree") {
        for (const rlispstat::core::DimensionalityScreeRenderPoint &screePoint : screeRenderPlan.observedPoints) {
            NSPoint sp = rlispstat::platform::macos::ToNSPoint(screePoint.point);
            if (screePoint.focused) {
                [[(theme.coordinatedMarks ? theme.selectedMarkFill :
                    [NSColor colorWithCalibratedRed:0.902 green:0.624 blue:0.000 alpha:1.0]) colorWithAlphaComponent:0.24] setFill];
                [[NSBezierPath bezierPathWithOvalInRect:NSMakeRect(sp.x - 8.5, sp.y - 8.5, 17.0, 17.0)] fill];
                [(theme.coordinatedMarks ? theme.selectedMarkStroke :
                    [NSColor colorWithCalibratedRed:0.000 green:0.447 blue:0.698 alpha:0.98]) setStroke];
                NSBezierPath *ring = [NSBezierPath bezierPathWithOvalInRect:NSMakeRect(sp.x - 6.2, sp.y - 6.2, 12.4, 12.4)];
                [ring setLineWidth:2.0];
                [ring stroke];
            }
            [(theme.coordinatedMarks
                ? (screePoint.focused ? theme.selectedMarkFill : theme.markFill)
                : [NSColor colorWithCalibratedRed:0.000 green:0.447 blue:0.698 alpha:(screePoint.focused ? 1.0 : 0.82)]) setFill];
            [[NSBezierPath bezierPathWithOvalInRect:NSMakeRect(sp.x - 3.4, sp.y - 3.4, 6.8, 6.8)] fill];
        }
    } else {
        for (const rlispstat::core::ScatterplotPointDrawItem &pointItem : scatterRenderPlan.points) {
            if (pointItem.hasImputationGlyph) {
                [self drawImputationGlyphInRect:rlispstat::platform::macos::ToNSRect(pointItem.imputationGlyph.rect)
                                        axisMask:pointItem.imputationGlyph.axisMask
                                       colorName:pointItem.colorName
                                   explicitColor:pointItem.hasExplicitColor
                                        selected:pointItem.selected
                                    hasSelection:hasSelection];
                continue;
            }
            NSPoint sp = rlispstat::platform::macos::ToNSPoint(pointItem.point);
            CGFloat radius = (CGFloat)pointItem.radius;
            if (theme.coordinatedMarks && pointItem.selected) radius *= (CGFloat)theme.selectedMarkScale;
            if (pointItem.hasHalo) {
                NSColor *haloColor = theme.coordinatedMarks && !pointItem.hasExplicitColor
                    ? theme.selectedMarkFill : ColorForName(pointItem.colorName, 1.0);
                [[haloColor colorWithAlphaComponent:(CGFloat)pointItem.haloAlpha] setFill];
                CGFloat haloRadius = (CGFloat)pointItem.haloRadius;
                NSBezierPath *halo = [NSBezierPath bezierPathWithOvalInRect:NSMakeRect(sp.x - haloRadius, sp.y - haloRadius,
                                                                                       haloRadius * 2.0, haloRadius * 2.0)];
                [halo fill];
            }
            if (theme.coordinatedMarks && !pointItem.hasExplicitColor) {
                [(pointItem.selected ? theme.selectedMarkFill :
                    (theme.hollowUnselectedMarks ? theme.panel : theme.markFill)) setFill];
            } else if (!pointItem.colorName.empty()) {
                [ColorForName(pointItem.colorName, (CGFloat)pointItem.fillAlpha) setFill];
            } else {
                [[NSColor colorWithCalibratedRed:0.070 green:0.080 blue:0.085 alpha:(CGFloat)pointItem.fillAlpha] setFill];
            }
            NSBezierPath *dot = PlotThemeMarkPath(theme, sp, radius, pointItem.selected);
            [dot fill];

            if (theme.coordinatedMarks) {
                NSColor *stroke = pointItem.selected ? theme.selectedMarkStroke :
                    (pointItem.hasExplicitColor ? ColorForName(pointItem.colorName, (CGFloat)pointItem.strokeAlpha) : theme.markStroke);
                [stroke setStroke];
            } else if (!pointItem.colorName.empty()) {
                [ColorForName(pointItem.colorName, (CGFloat)pointItem.strokeAlpha) setStroke];
            } else {
                [[NSColor colorWithCalibratedRed:0.020 green:0.025 blue:0.028 alpha:(CGFloat)pointItem.strokeAlpha] setStroke];
            }
            [dot setLineWidth:(theme.coordinatedMarks && pointItem.selected)
                ? (CGFloat)theme.selectedMarkStrokeWidth : (CGFloat)pointItem.strokeWidth];
            [dot stroke];
        }

        if (self.model->glmDiagnosticKind == "roc_curve") {
            for (const rlispstat::core::ROCThresholdLink &threshold : self.model->rocThresholds) {
                bool intersectsSelection = false;
                for (int row : threshold.crossingRows) {
                    if (selection.find(row) != selection.end()) { intersectsSelection = true; break; }
                }
                if (!intersectsSelection) continue;
                NSPoint sp = [self screenPointForPoint:threshold.point];
                NSBezierPath *marker = [NSBezierPath bezierPathWithOvalInRect:NSMakeRect(sp.x - 6.0, sp.y - 6.0, 12.0, 12.0)];
                [(theme.coordinatedMarks ? theme.selectedMarkFill : [NSColor colorWithCalibratedWhite:0.15 alpha:1.0]) setStroke];
                [marker setLineWidth:2.2];
                [marker stroke];
                NSBezierPath *outer = [NSBezierPath bezierPathWithOvalInRect:NSMakeRect(sp.x - 8.0, sp.y - 8.0, 16.0, 16.0)];
                [(theme.coordinatedMarks ? theme.selectedMarkStroke : [NSColor colorWithCalibratedWhite:0.62 alpha:0.85]) setStroke];
                [outer setLineWidth:1.0];
                [outer stroke];
            }
        }

        NSDictionary *pointLabelAttrs = @{
            NSFontAttributeName: [NSFont systemFontOfSize:11 weight:NSFontWeightMedium],
            NSForegroundColorAttributeName: theme.text
        };
        for (const rlispstat::core::ScatterplotPointDrawItem &pointItem : scatterRenderPlan.points) {
            if (!pointItem.showLabel) {
                continue;
            }
            NSPoint sp = rlispstat::platform::macos::ToNSPoint(pointItem.labelAnchor);
            NSString *text = ToNSString(pointItem.label);
            NSSize size = [text sizeWithAttributes:pointLabelAttrs];
            CGFloat x = std::min(std::max(sp.x + 6.0, pr.origin.x + 2.0),
                                 pr.origin.x + pr.size.width - size.width - 6.0);
            CGFloat y = std::min(std::max(sp.y - size.height - 4.0, pr.origin.y + 2.0),
                                 pr.origin.y + pr.size.height - size.height - 4.0);
            NSRect bg = NSInsetRect(NSMakeRect(x - 3.0, y - 2.0, size.width + 6.0, size.height + 4.0), 0, 0);
            [[theme.panel colorWithAlphaComponent:0.88] setFill];
            [[NSBezierPath bezierPathWithRoundedRect:bg xRadius:3.0 yRadius:3.0] fill];
            [text drawAtPoint:NSMakePoint(x, y) withAttributes:pointLabelAttrs];
        }
    }

    if (self.dragging) {
        NSRect rr = rlispstat::platform::macos::ToNSRect(
            rlispstat::core::BrushRectForGesture(
                rlispstat::platform::macos::ToCorePoint(self.dragStart),
                rlispstat::platform::macos::ToCorePoint(self.dragCurrent),
                self.model->interactionMode == "brush",
                self.model->brushWidth,
                self.model->brushHeight));
        [[theme.accent colorWithAlphaComponent:0.16] setFill];
        NSRectFillUsingOperation(rr, NSCompositingOperationSourceOver);
        [[theme.accent colorWithAlphaComponent:0.95] setStroke];
        NSFrameRect(rr);
    }

}

- (void)mouseDown:(NSEvent *)event
{
    SetActivePlotOnMain(self.model);
    [[self window] makeFirstResponder:self];
    NSPoint click = [self convertPoint:[event locationInWindow] fromView:nil];
    if (self.model->kind == "trellis_scatterplot") {
        const rlispstat::core::TrellisScatterplotLayout layout = [self trellisScatterplotLayout];
        const std::vector<std::size_t> conditions =
            rlispstat::core::TrellisConditioningVariableIndicesAtPoint(
                *self.model, layout, rlispstat::platform::macos::ToCorePoint(click));
        if (!conditions.empty()) {
            NSMenu *conditionMenu = [self trellisConditionVariableMenuForIndices:conditions];
            if (conditionMenu) {
                [NSMenu popUpContextMenu:conditionMenu withEvent:event forView:self];
                return;
            }
        }
    }
    if (self.model->kind == "scatter_matrix") {
        NSInteger variableIndex = [self scatterMatrixVariableIndexAtPoint:click];
        if (variableIndex != NSNotFound) {
            [self showScatterMatrixVariableMenuForIndex:variableIndex atPoint:click];
            return;
        }
    }
    if (self.model->kind == "pca_scree") {
        NSInteger component = [self screeComponentAtPoint:click];
        if (component > 0) {
            SetDimensionalityFocusedComponentOnMain(self.model->dimensionalityModelId, (int)component, true);
        } else {
            ClearDimensionalityFocusOnMain(self.model->dimensionalityModelId);
        }
        [self setNeedsDisplay:YES];
        return;
    }
    if (self.model->kind != "scatter_matrix" && self.model->kind != "pca_scree" &&
        NSPointInRect(click, [self xAxisLabelRect])) {
        [self showVariableMenuForAxis:@"x" atPoint:click];
        return;
    }
    if (self.model->kind != "scatter_matrix" && self.model->kind != "pca_scree" &&
        NSPointInRect(click, [self yAxisLabelHitRect])) {
        [self showVariableMenuForAxis:@"y" atPoint:click];
        return;
    }
    if (self.model->kind == "pca_biplot") {
        std::string loadingVariable = [self biplotLoadingVariableAtPoint:click];
        if (!loadingVariable.empty()) {
            SetDimensionalityFocusedVariableOnMain(self.model->dimensionalityModelId, loadingVariable, true);
            [self setNeedsDisplay:YES];
            return;
        }
    }
    if (!(self.model && rlispstat::core::PlotLinksToDataRows(*self.model))) {
        [self setNeedsDisplay:YES];
        return;
    }
    self.dragging = YES;
    self.dragStart = click;
    self.dragCurrent = self.dragStart;
    [self setNeedsDisplay:YES];

    while (self.dragging) {
        NSEvent *trackingEvent = [[self window] nextEventMatchingMask:(NSEventMaskLeftMouseDragged | NSEventMaskLeftMouseUp)
                                                            untilDate:[NSDate distantFuture]
                                                               inMode:NSEventTrackingRunLoopMode
                                                              dequeue:YES];
        if (!trackingEvent) {
            break;
        }
        if ([trackingEvent type] == NSEventTypeLeftMouseDragged) {
            [self mouseDragged:trackingEvent];
        } else if ([trackingEvent type] == NSEventTypeLeftMouseUp) {
            [self finishDragWithEvent:trackingEvent];
            break;
        }
    }
}

- (void)mouseDragged:(NSEvent *)event
{
    self.dragCurrent = [self convertPoint:[event locationInWindow] fromView:nil];
    [self setNeedsDisplay:YES];
}

- (void)mouseUp:(NSEvent *)event
{
    [self finishDragWithEvent:event];
}

- (void)finishScatterMatrixDragWithEvent:(NSEvent *)event
{
    self.dragCurrent = [self convertPoint:[event locationInWindow] fromView:nil];
    if (!self.dragging) {
        [self setNeedsDisplay:YES];
        return;
    }
    self.dragging = NO;
    if (self.model->interactionMode == "none" || self.model->interactionMode == "pan") {
        [self setNeedsDisplay:YES];
        return;
    }
    if (self.model->interactionMode == "zoom") {
        [self setNeedsDisplay:YES];
        UpdatePanelOnMain();
        return;
    }

    std::string mode = EffectiveSelectionMode(self.model, [event modifierFlags]);
    rlispstat::core::Rect brush = rlispstat::core::BrushRectForGesture(
        rlispstat::platform::macos::ToCorePoint(self.dragStart),
        rlispstat::platform::macos::ToCorePoint(self.dragCurrent),
        self.model->interactionMode == "brush",
        self.model->brushWidth,
        self.model->brushHeight);

    std::vector<std::string> vars = ScatterMatrixVariablesForModel(self.model);
    size_t n = vars.size();
    std::set<int> selected;
    if (n >= 2) {
        NSRect pr = [self scatterMatrixPlotRect];
        rlispstat::core::ScatterMatrixLayout layout{
            rlispstat::platform::macos::ToCoreRect(pr),
            n
        };
        std::vector<rlispstat::core::ScatterMatrixCaseGeometry> hitGeometry =
            rlispstat::core::BuildScatterMatrixCaseGeometry(
                ScatterMatrixVariableSeriesForModel(self.model, vars),
                ScatterMatrixVisibleCaseIdsForModel(self.model),
                layout,
                5.0);
        const bool dragBrush = rlispstat::core::RectMeetsMinimumSize(brush, 3.0, 3.0);
        selected = rlispstat::core::SelectScatterMatrixCasesForGesture(
            hitGeometry,
            layout,
            brush,
            rlispstat::platform::macos::ToCorePoint(self.dragCurrent),
            dragBrush,
            8.0
        );
    }

    int selectionVersion = 0;
    if (MergeSelection(self.model->group, selected, mode, &selectionVersion)) {
        PublishSpreadPlotMessage("ROW_SELECTION_CHANGED", self.model->group, self.model->id, "", std::vector<int>(selected.begin(), selected.end()), selectionVersion);
    }
    [self setNeedsDisplay:YES];
    UpdatePanelOnMain();
}

- (void)finishDragWithEvent:(NSEvent *)event
{
    if (self.model->kind == "scatter_matrix") {
        [self finishScatterMatrixDragWithEvent:event];
        return;
    }
    if (self.model->kind == "trellis_scatterplot") {
        self.dragCurrent = [self convertPoint:[event locationInWindow] fromView:nil];
        if (!self.dragging) { [self setNeedsDisplay:YES]; return; }
        self.dragging = NO;
        if (self.model->interactionMode == "none" || self.model->interactionMode == "pan") {
            [self setNeedsDisplay:YES];
            return;
        }
        const std::string mode = EffectiveSelectionMode(self.model, [event modifierFlags]);
        const rlispstat::core::Rect brush = rlispstat::core::BrushRectForGesture(
            rlispstat::platform::macos::ToCorePoint(self.dragStart),
            rlispstat::platform::macos::ToCorePoint(self.dragCurrent),
            self.model->interactionMode == "brush",
            self.model->brushWidth,
            self.model->brushHeight);
        const bool dragBrush = rlispstat::core::RectMeetsMinimumSize(brush, 3.0, 3.0);
        const rlispstat::core::Point gesturePoint = rlispstat::platform::macos::ToCorePoint(
            dragBrush ? self.dragStart : self.dragCurrent);
        const rlispstat::core::TrellisScatterplotLayout trellisLayout = [self trellisScatterplotLayout];
        std::set<int> selected;
        if (!dragBrush && self.model->trellisSpecification.plotType == TrellisPlotType::Bar &&
            !self.model->trellisSpecification.splitVariableId.empty()) {
            const auto plans = rlispstat::core::BuildTrellisPanelRenderPlans(
                *self.model, trellisLayout, {}, {});
            bool hitSegment = false;
            for (auto plan = plans.rbegin(); plan != plans.rend() && !hitSegment; ++plan) {
                for (auto segments = plan->barplotSegments.rbegin();
                     segments != plan->barplotSegments.rend() && !hitSegment; ++segments) {
                    for (auto segment = segments->rbegin(); segment != segments->rend(); ++segment) {
                        if (rlispstat::core::PointInRect(gesturePoint, segment->rect)) {
                            selected.insert(segment->rows.begin(), segment->rows.end());
                            hitSegment = true;
                            break;
                        }
                    }
                }
            }
        }
        if (selected.empty()) {
            selected = rlispstat::core::SelectTrellisScatterplotCasesForGesture(
                trellisLayout, brush, gesturePoint, dragBrush, 8.0, 2.0);
        }
        int selectionVersion = 0;
        if (MergeSelection(self.model->group, selected, mode, &selectionVersion)) {
            PublishSpreadPlotMessage("ROW_SELECTION_CHANGED", self.model->group, self.model->id, "",
                std::vector<int>(selected.begin(), selected.end()), selectionVersion);
        }
        [self setNeedsDisplay:YES];
        UpdatePanelOnMain();
        return;
    }
    if (!(self.model && rlispstat::core::PlotLinksToDataRows(*self.model))) {
        self.dragging = NO;
        [self setNeedsDisplay:YES];
        return;
    }
    self.dragCurrent = [self convertPoint:[event locationInWindow] fromView:nil];
    if (!self.dragging) {
        [self setNeedsDisplay:YES];
        return;
    }
    self.dragging = NO;
    if (self.model->interactionMode == "none" || self.model->interactionMode == "pan") {
        [self setNeedsDisplay:YES];
        return;
    }
    std::string mode = EffectiveSelectionMode(self.model, [event modifierFlags]);

    rlispstat::core::Rect coreBrush = rlispstat::core::BrushRectForGesture(
        rlispstat::platform::macos::ToCorePoint(self.dragStart),
        rlispstat::platform::macos::ToCorePoint(self.dragCurrent),
        self.model->interactionMode == "brush",
        self.model->brushWidth,
        self.model->brushHeight);
    NSRect brush = rlispstat::platform::macos::ToNSRect(coreBrush);

    if (self.model->interactionMode == "zoom") {
        if (rlispstat::core::RectMeetsMinimumSize(coreBrush, 8.0, 8.0)) {
            NSPoint p1 = [self dataPointForScreenPoint:NSMakePoint(brush.origin.x, brush.origin.y + brush.size.height)];
            NSPoint p2 = [self dataPointForScreenPoint:NSMakePoint(brush.origin.x + brush.size.width, brush.origin.y)];
            self.model->xmin = std::min(p1.x, p2.x);
            self.model->xmax = std::max(p1.x, p2.x);
            self.model->ymin = std::min(p1.y, p2.y);
            self.model->ymax = std::max(p1.y, p2.y);
        }
        UpdateWindowTitleOnMain(self.model);
        [self setNeedsDisplay:YES];
        UpdatePanelOnMain();
        return;
    }

    if (self.model->glmDiagnosticKind == "roc_curve" && !self.model->rocThresholds.empty()) {
        const bool dragBrush = rlispstat::core::RectMeetsMinimumSize(coreBrush, 3.0, 3.0);
        std::set<int> selected;
        double nearestDistance = std::numeric_limits<double>::infinity();
        const rlispstat::core::ROCThresholdLink *nearest = nullptr;
        for (const rlispstat::core::ROCThresholdLink &threshold : self.model->rocThresholds) {
            NSPoint point = [self screenPointForPoint:threshold.point];
            if (dragBrush && NSPointInRect(point, brush)) {
                selected.insert(threshold.crossingRows.begin(), threshold.crossingRows.end());
                continue;
            }
            if (!dragBrush) {
                const double dx = point.x - self.dragCurrent.x;
                const double dy = point.y - self.dragCurrent.y;
                const double distance = std::sqrt(dx * dx + dy * dy);
                if (distance < nearestDistance) {
                    nearestDistance = distance;
                    nearest = &threshold;
                }
            }
        }
        if (!dragBrush && nearest && nearestDistance <= 8.0) {
            selected.insert(nearest->crossingRows.begin(), nearest->crossingRows.end());
        }
        int selectionVersion = 0;
        if (MergeSelection(self.model->group, selected, mode, &selectionVersion)) {
            PublishSpreadPlotMessage("ROW_SELECTION_CHANGED", self.model->group, self.model->id, "",
                std::vector<int>(selected.begin(), selected.end()), selectionVersion);
        }
        [self setNeedsDisplay:YES];
        UpdatePanelOnMain();
        return;
    }

    DataFrameModel imputationDf;
    bool useImputationGlyphHits = false;
    if (self.model->kind == "scatter") {
        std::lock_guard<std::mutex> lock(g_mutex);
        const DataFrameModel *df = FindDataFrameUnlockedConst(self.model->group);
        if (df && DataFrameShowsAllImputations(*df)) {
            imputationDf = *df;
            useImputationGlyphHits = true;
        }
    }
    const DataColumn *imputationXCol = useImputationGlyphHits ? FindDataColumnInDataFrame(imputationDf, self.model->xLabel) : nullptr;
    const DataColumn *imputationYCol = useImputationGlyphHits ? FindDataColumnInDataFrame(imputationDf, self.model->yLabel) : nullptr;
    useImputationGlyphHits = useImputationGlyphHits && imputationXCol && imputationYCol;

    std::vector<rlispstat::core::ScatterplotPointValue> hitPoints;
    hitPoints.reserve(self.model->points.size());
    for (const DataPoint &p : self.model->points) {
        hitPoints.push_back(rlispstat::core::ScatterplotPointValue{p.row, p.x, p.y});
    }
    std::vector<rlispstat::core::ScatterplotCaseGeometry> hitGeometry =
        rlispstat::core::BuildScatterplotCaseGeometry(
            hitPoints,
            rlispstat::core::DataViewport{self.model->xmin, self.model->xmax, self.model->ymin, self.model->ymax},
            rlispstat::platform::macos::ToCoreRect([self plotRect]),
            useImputationGlyphHits ? &imputationDf : nullptr,
            imputationXCol,
            imputationYCol,
            self.model->scatterImputationUncertainty);
    const bool dragBrush = rlispstat::core::RectMeetsMinimumSize(coreBrush, 3.0, 3.0);
    std::set<int> selected = rlispstat::core::SelectCasesForGesture(
        hitGeometry,
        coreBrush,
        rlispstat::platform::macos::ToCorePoint(self.dragCurrent),
        dragBrush,
        8.0,
        2.0
    );

    int selectionVersion = 0;
    if (MergeSelection(self.model->group, selected, mode, &selectionVersion)) {
        PublishSpreadPlotMessage("ROW_SELECTION_CHANGED", self.model->group, self.model->id, "", std::vector<int>(selected.begin(), selected.end()), selectionVersion);
    }
    [self setNeedsDisplay:YES];
    UpdatePanelOnMain();
}

- (void)refreshSelection
{
    [self setNeedsDisplay:YES];
}

- (void)rightMouseDown:(NSEvent *)event
{
    SetActivePlotOnMain(self.model);
    [[self window] makeFirstResponder:self];
    NSMenu *menu = [self menuForEvent:event];
    [NSMenu popUpContextMenu:menu withEvent:event forView:self];
}

- (NSMenuItem *)menuItem:(NSString *)title command:(NSString *)command
{
    NSMenuItem *item = [[NSMenuItem alloc] initWithTitle:title action:@selector(runCommand:) keyEquivalent:@""];
    [item setTarget:g_commandTarget];
    [item setRepresentedObject:command];
    return item;
}

- (NSMenuItem *)menuItemForOption:(const rlispstat::core::ScatterplotMenuOption &)option
{
    NSMenuItem *item = nil;
    if (option.command.empty()) {
        item = [[NSMenuItem alloc] initWithTitle:ToNSString(option.title) action:nil keyEquivalent:@""];
    } else {
        item = [self menuItem:ToNSString(option.title) command:ToNSString(option.command)];
    }
    [item setEnabled:option.enabled];
    [item setState:option.checked ? NSControlStateValueOn : NSControlStateValueOff];
    return item;
}

- (NSMenu *)scatterMatrixMenuForEvent:(NSEvent *)event
{
    SetActivePlotOnMain(self.model);
    if (event) {
        NSPoint click = [self convertPoint:[event locationInWindow] fromView:nil];
        NSInteger variableIndex = [self scatterMatrixVariableIndexAtPoint:click];
        if (variableIndex != NSNotFound) {
            return [self scatterMatrixVariableMenuForIndex:variableIndex];
        }
    }
    if (!g_commandTarget) {
        g_commandTarget = [[CommandTarget alloc] init];
    }
    const rlispstat::core::PlotContextMenuTitles contextTitles = rlispstat::core::DefaultPlotContextMenuTitles();
    NSMenu *menu = [[NSMenu alloc] initWithTitle:ToNSString(contextTitles.root)];
    std::vector<std::string> current = ScatterMatrixVariablesForModel(self.model);
    rlispstat::core::ScatterMatrixVariableMenuState menuState =
        rlispstat::core::BuildScatterMatrixVariableMenuState(
            current,
            rlispstat::core::NumericVariableNames(self.model));

    NSMenuItem *variables = [[NSMenuItem alloc] initWithTitle:ToNSString(menuState.variablesTitle) action:nil keyEquivalent:@""];
    NSMenu *variablesMenu = [[NSMenu alloc] initWithTitle:ToNSString(menuState.variablesTitle)];

    NSMenuItem *addItem = [[NSMenuItem alloc] initWithTitle:ToNSString(menuState.addVariableTitle) action:nil keyEquivalent:@""];
    NSMenu *addMenu = [[NSMenu alloc] initWithTitle:ToNSString(menuState.addVariableTitle)];
    NSInteger addCount = 0;
    for (const std::string &name : menuState.addVariables) {
        [addMenu addItem:[self menuItem:ToNSString(name)
                                command:ToNSString(std::string("SCATTER_MATRIX_ADD_VARIABLE|") + name)]];
        ++addCount;
    }
    if (addCount == 0) {
        NSMenuItem *empty = [[NSMenuItem alloc] initWithTitle:ToNSString(menuState.noAvailableVariablesTitle) action:nil keyEquivalent:@""];
        [empty setEnabled:NO];
        [addMenu addItem:empty];
    }
    [variablesMenu setSubmenu:addMenu forItem:addItem];
    [variablesMenu addItem:addItem];

    NSMenuItem *removeItem = [[NSMenuItem alloc] initWithTitle:ToNSString(menuState.removeVariableTitle) action:nil keyEquivalent:@""];
    NSMenu *removeMenu = [[NSMenu alloc] initWithTitle:ToNSString(menuState.removeVariableTitle)];
    if (!menuState.canRemoveVariables) {
        NSMenuItem *empty = [[NSMenuItem alloc] initWithTitle:ToNSString(menuState.keepAtLeastTwoVariablesTitle) action:nil keyEquivalent:@""];
        [empty setEnabled:NO];
        [removeMenu addItem:empty];
    } else {
        for (const std::string &name : menuState.removeVariables) {
            [removeMenu addItem:[self menuItem:ToNSString(name)
                                      command:ToNSString(std::string("SCATTER_MATRIX_REMOVE_VARIABLE|") + name)]];
        }
    }
    [variablesMenu setSubmenu:removeMenu forItem:removeItem];
    [variablesMenu addItem:removeItem];
    [variablesMenu addItem:[NSMenuItem separatorItem]];
