static void WakeFifoServerForShutdown()
{
    if (g_controlFifoPath.empty()) return;
    // ServerLoopFifo may be blocked in open(O_RDONLY) while it waits for the
    // next command.  A zero-byte writer wakes that open/read cycle so the loop
    // can observe g_running == false, unlink the FIFO, and only then terminate
    // AppKit.  Leaving the FIFO behind makes R mistake a dying backend for a
    // reusable one and can block the next LinkEDA() call forever.
    int fd = open(g_controlFifoPath.c_str(), O_WRONLY | O_NONBLOCK);
    if (fd >= 0) close(fd);
}

static void ClosePlotOnMain(const std::string &plotId)
{
    std::string plotIdCopy = plotId;
    dispatch_async(dispatch_get_main_queue(), ^{
      std::lock_guard<std::mutex> lock(g_mutex);
      for (ScatterView *view : g_views) {
          if (view.model && view.model->id == plotIdCopy) {
              [[view window] close];
          }
      }
      for (BoxplotView *view : g_boxplotViews) {
          if (view.model && view.model->id == plotIdCopy) {
              [[view window] close];
          }
      }
      for (HistogramView *view : g_histogramViews) {
          if (view.model && view.model->id == plotIdCopy) {
              [[view window] close];
          }
      }
      for (BarplotView *view : g_barplotViews) {
          if (view.model && view.model->id == plotIdCopy) {
              [[view window] close];
          }
      }
      g_views.erase(
          std::remove_if(g_views.begin(), g_views.end(), [&](ScatterView *view) {
              return view.model && view.model->id == plotIdCopy;
          }),
          g_views.end()
      );
      g_boxplotViews.erase(
          std::remove_if(g_boxplotViews.begin(), g_boxplotViews.end(), [&](BoxplotView *view) {
              return view.model && view.model->id == plotIdCopy;
          }),
          g_boxplotViews.end()
      );
      g_histogramViews.erase(
          std::remove_if(g_histogramViews.begin(), g_histogramViews.end(), [&](HistogramView *view) {
              return view.model && view.model->id == plotIdCopy;
          }),
          g_histogramViews.end()
      );
      g_barplotViews.erase(
          std::remove_if(g_barplotViews.begin(), g_barplotViews.end(), [&](BarplotView *view) {
              return view.model && view.model->id == plotIdCopy;
          }),
          g_barplotViews.end()
      );
      auto linked = g_linkedTables.find(plotIdCopy);
      if (linked != g_linkedTables.end()) {
          for (const std::string &tid : linked->second) {
              g_linkedTableSources.erase(tid);
              auto cit = g_table1Controllers.find(tid);
              if (cit != g_table1Controllers.end()) {
                  Table1DisplayState *st = [cit->second state];
                  if (st) {
                      st->linkEnabled = false;
                      st->sourcePlotId.clear();
                  }
                  NSWindow *w = [cit->second getWindow];
                  if (w) [w setTitle:ToNSString(rlispstat::core::Table1WindowTitle() + " (unlinked)")];
              }
          }
          g_linkedTables.erase(linked);
      }
    });
}

static void HandleDatasetRegisteredOnMac(const std::string &group, bool showDataSheet)
{
    std::vector<std::string> dimensionalityToRefresh;
    std::vector<std::string> plotsToRedraw;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        MacCommandDispatcher().applicationState().ensureSelectionGroup(group);
        SetActiveDatasetUnlocked(group);
        DataFrameModel *df = FindDataFrameUnlocked(group);
        if (df) {
            plotsToRedraw = RebuildPlotsForDataFrameUnlocked(group, *df);
        }
        for (auto &entry : g_dendrograms) {
            DendrogramState &state = entry.second;
            if (state.group != group) continue;
            if (BuildSeedPlotForGroupUnlocked(group, state.seed)) {
                state.hasSeed = true;
                std::vector<std::string> numeric = rlispstat::core::NumericVariableNames(&state.seed);
                std::vector<std::string> kept;
                for (const std::string &name : state.variables) {
                    if (std::find(numeric.begin(), numeric.end(), name) != numeric.end()) kept.push_back(name);
                }
                state.variables = kept;
                RefitDendrogramState(state);
            }
        }
        for (auto &entry : g_dimensionalityModels) {
            DimensionalityState &state = entry.second;
            if (state.group != group) continue;
            if (BuildSeedPlotForGroupUnlocked(group, state.seed)) {
                state.hasSeed = true;
                std::vector<std::string> numeric = rlispstat::core::NumericVariableNames(&state.seed);
                std::vector<std::string> kept;
                for (const std::string &name : state.variables) {
                    if (std::find(numeric.begin(), numeric.end(), name) != numeric.end()) kept.push_back(name);
                }
                state.variables = kept;
                if (state.variables.size() >= 2) {
                    RefitDimensionalityState(state);
                } else {
                    state.status = "At least two numeric variables are required.";
                    state.components.clear();
                    state.loadings.clear();
                    state.scores.clear();
                }
                dimensionalityToRefresh.push_back(state.id);
            }
        }
    }
    for (const std::string &modelId : dimensionalityToRefresh) {
        RefreshOpenDimensionalityPlots(modelId);
    }
    for (const std::string &plotId : plotsToRedraw) {
        RedrawPlotOnMain(plotId);
    }
    RedrawGroupViewsSynchronouslyOnMain(group, true);
    RefreshDendrogramWindowsOnMain(group);
    RefreshDataDeskWindowsOnMain(group);
    RefreshRegressionComparisonWindowsOnMain(group, false);
    UpdateActiveDatasetMenuOnMain();
    if (showDataSheet) {
        CloseWelcomeOnMain();
        ShowDataSheetOnMain(group);
    }
}

static CommandDispatcher &MacCommandDispatcher()
{
    static CommandDispatcher dispatcher(CommandDispatcherServices{
        SessionControllerServices{
            [](const SessionPlot &plot) {
                PlotModel *model = new PlotModel();
                model->id = plot.id;
                model->group = plot.group;
                model->xLabel = plot.xLabel;
                model->yLabel = plot.yLabel;
                model->points.reserve(plot.points.size());
                for (const auto &point : plot.points) {
                    model->points.push_back({point.x, point.y, point.row});
                }
                ComputeRanges(model);
                {
                    std::lock_guard<std::mutex> lock(g_mutex);
                    (void)AttachPlotModelUnlocked(model);
                    MarkActiveDatasetGroupUnlocked(model->group);
                    EnsureGroupModelUnlocked(model->group, model);
                }
                AddPlotOnMain(model);
                return std::string();
            },
            [](const std::string &group, std::set<int> &rows) {
                std::lock_guard<std::mutex> lock(g_mutex);
                auto it = g_groupSelections.find(group);
                if (it == g_groupSelections.end()) {
                    return false;
                }
                rows = it->second;
                return true;
            },
            [](const std::string &group) {
                bool found = false;
                {
                    std::lock_guard<std::mutex> lock(g_mutex);
                    auto it = g_groupSelections.find(group);
                    if (it != g_groupSelections.end()) {
                        it->second.clear();
                        if (RequestSmoothRecomputeForGroupUnlocked(
                                group, rlispstat::core::SmoothCurveScope::Selection)) {
                            NotifyMainRTaskAvailable();
                        }
                        found = true;
                    }
                }
                if (!found) {
                    return std::string("ERR no active plot/group");
                }
                RedrawGroupOnMain(group);
                return std::string();
            },
            {}
        },
        CommandQueryServices{
            []() {
                std::vector<PlotModel> plots;
                std::lock_guard<std::mutex> lock(g_mutex);
                plots.reserve(g_plots.size());
                for (const auto &entry : g_plots) {
                    plots.push_back(*entry.second);
                }
                return plots;
            },
            [](const std::string &plotId, PlotModel &plot, std::size_t &selected) {
                std::lock_guard<std::mutex> lock(g_mutex);
                auto it = g_plots.find(plotId);
                if (it == g_plots.end()) return false;
                plot = *it->second;
                auto selection = g_groupSelections.find(plot.group);
                selected = selection == g_groupSelections.end() ? 0 : selection->second.size();
                return true;
            },
            [](const std::string &plotId, PlotModel &plot) {
                std::lock_guard<std::mutex> lock(g_mutex);
                auto it = g_plots.find(plotId);
                if (it == g_plots.end()) return false;
                plot = *it->second;
                return true;
            },
            []() {
                std::vector<rlispstat::core::GroupSelectionSummary> summaries;
                std::lock_guard<std::mutex> lock(g_mutex);
                summaries.reserve(g_groupSelections.size());
                for (const auto &entry : g_groupSelections) {
                    std::size_t plotCount = std::count_if(
                        g_plots.begin(), g_plots.end(),
                        [&](const auto &plotEntry) { return plotEntry.second->group == entry.first; });
                    summaries.push_back({entry.first, plotCount, entry.second.size()});
                }
                return summaries;
            },
            [](const std::string &group, std::size_t &selected, std::vector<std::string> &plotIds) {
                std::lock_guard<std::mutex> lock(g_mutex);
                auto selection = g_groupSelections.find(group);
                if (selection == g_groupSelections.end()) return false;
                selected = selection->second.size();
                for (const auto &entry : g_plots) {
                    if (entry.second->group == group) plotIds.push_back(entry.second->id);
                }
                return true;
            },
            [](const std::string &plotId, std::vector<std::pair<int, std::string>> &colors) {
                std::lock_guard<std::mutex> lock(g_mutex);
                auto plot = g_plots.find(plotId);
                if (plot == g_plots.end()) return false;
                auto entries = g_groupPointColors.find(plot->second->group);
                if (entries == g_groupPointColors.end()) return true;
                for (const auto &entry : entries->second) colors.push_back(entry);
                return true;
            },
            [](const std::string &group, std::vector<rlispstat::core::CommandVariableInfo> &variables) {
                std::lock_guard<std::mutex> lock(g_mutex);
                PlotModel *plot = FirstPlotForGroupUnlocked(group);
                if (!plot) return false;
                std::vector<VariableMeta> metadata = plot->variableMeta;
                if (metadata.empty()) {
                    for (const NumericVariable &variable : plot->variables) {
                        metadata.push_back(VariableMeta{variable.name, "numeric"});
                    }
                }
                EnsureGroupModelUnlocked(group, plot);
                variables.reserve(metadata.size());
                for (const VariableMeta &variable : metadata) {
                    variables.push_back({variable.name, variable.type,
                                         VariableRoleForPlot(plot, variable.name)});
                }
                return true;
            },
            [](const std::string &group, PlotModel &plot) {
                std::lock_guard<std::mutex> lock(g_mutex);
                PlotModel *source = FirstPlotForGroupUnlocked(group);
                if (!source) return false;
                plot = *source;
                return true;
            },
            [](const std::string &group, PlotModel &plot) {
                return BuildSeedPlotForGroup(group, plot);
            },
            [](const std::string &group) {
                return GroupIsMultipleImputation(group);
            },
            [](const std::string &group) {
                return "gglm_" + group + "_" + std::to_string((long long)time(nullptr));
            },
            [](PlotModel &plot) {
                PlotModel *active = ActivePlot();
                if (!active) return false;
                plot = *active;
                return true;
            }
        },
        CommandUiServices{
            [](const std::string &plotId, const std::string &path, const std::string &format) {
                return SavePlotViewToPathOnMain(plotId, ToNSString(path), format);
            },
