        rlispstat::core::CommandSelectionServices{
            [](const std::string &group, std::set<int> &rows) {
                std::lock_guard<std::mutex> lock(g_mutex);
                bool found = false;
                for (const auto &entry : g_plots) {
                    if (entry.second->group == group) {
                        found = true;
                        for (const DataPoint &point : entry.second->points) {
                            if (point.row > 0) rows.insert(point.row);
                        }
                    }
                }
                return found;
            },
            [](const std::string &group, const std::set<int> &rows,
               int selectionVersion, bool redraw) {
                NotifyPortableSelectionChanged(group, rows, selectionVersion, redraw);
            },
            [](const std::string &group, const std::vector<int> &rows,
               bool updatePanel, bool recompute) {
                if (recompute) {
                    std::lock_guard<std::mutex> lock(g_mutex);
                    RequestColorSmoothRecomputeForGroupUnlocked(group);
                }
                PublishSpreadPlotMessage("ROW_COLORS_CHANGED", group, "backend", "", rows);
                RedrawGroupViewsSynchronouslyOnMain(group, true);
                if (updatePanel) {
                    UpdatePanelOnMain();
                }
            },
            [](const std::string &plotId, std::string &interaction, std::string &selection) {
                std::lock_guard<std::mutex> lock(g_mutex);
                auto it = g_plots.find(plotId);
                if (it == g_plots.end()) return false;
                interaction = it->second->interactionMode;
                selection = it->second->selectionMode;
                return true;
            },
            [](const std::string &plotId, const std::string &mode) {
                std::lock_guard<std::mutex> lock(g_mutex);
                auto it = g_plots.find(plotId);
                if (it == g_plots.end()) return false;
                PlotModel *plot = it->second;
                if ((mode == "select" || mode == "brush" || mode == "identify" || mode == "label") &&
                    !rlispstat::core::PlotLinksToDataRows(*plot)) {
                    return true;
                }
                plot->interactionMode = mode;
                return true;
            },
            [](const std::string &plotId, const std::string &mode) {
                std::lock_guard<std::mutex> lock(g_mutex);
                auto it = g_plots.find(plotId);
                if (it == g_plots.end()) return false;
                it->second->selectionMode = mode;
                return true;
            },
            [](const std::string &plotId, const std::string &source) {
                std::lock_guard<std::mutex> lock(g_mutex);
                auto it = g_plots.find(plotId);
                if (it == g_plots.end()) return false;
                PlotModel *plot = it->second;
                if (!rlispstat::core::PlotLinksToDataRows(*plot)) return true;
                if (source == "both") {
                    AddOverlaySource(plot, "all");
                    AddOverlaySource(plot, "selected");
                } else {
                    AddOverlaySource(plot, source);
                }
                return true;
            },
            [](const std::string &plotId) {
                std::lock_guard<std::mutex> lock(g_mutex);
                auto it = g_plots.find(plotId);
                if (it == g_plots.end()) return false;
                it->second->overlays.clear();
                return true;
            },
            [](const std::string &plotId, rlispstat::core::SmoothCurveScope scope,
               const std::vector<rlispstat::core::SmoothCurveData> &curves) {
                std::lock_guard<std::mutex> lock(g_mutex);
                auto it = g_plots.find(plotId);
                if (it == g_plots.end()) return false;
                std::vector<rlispstat::core::SmoothCurveData> &existing = it->second->smoothCurves;
                existing.erase(std::remove_if(existing.begin(), existing.end(),
                    [&](const rlispstat::core::SmoothCurveData &curve) {
                        return curve.scope == scope;
                    }), existing.end());
                existing.insert(existing.end(), curves.begin(), curves.end());
                return true;
            },
            [](const std::string &plotId, bool changeX, const std::string &variable) {
                PlotModel *plot = nullptr;
                {
                    std::lock_guard<std::mutex> lock(g_mutex);
                    auto it = g_plots.find(plotId);
                    if (it == g_plots.end()) return false;
                    plot = it->second;
                }
                DispatchCommand(plot, std::string(changeX ? "CHANGE_X_VARIABLE|" :
                    "CHANGE_Y_VARIABLE|") + variable);
                return true;
            },
            [](const std::string &plotId, const std::function<void(PlotModel &)> &mutation) {
                std::lock_guard<std::mutex> lock(g_mutex);
                auto it = g_plots.find(plotId);
                if (it == g_plots.end() || it->second->kind != "histogram") return false;
                mutation(*it->second);
                return true;
            },
            [](const std::string &plotId, const rlispstat::core::CommandBoxplotMutation &mutation,
               std::string &message) {
                std::lock_guard<std::mutex> lock(g_mutex);
                auto it = g_plots.find(plotId);
                if (it == g_plots.end() || it->second->kind != "boxplot") return false;
                return mutation(*it->second, message);
            },
            [](const std::string &correlationId) {
                {
                    std::lock_guard<std::mutex> lock(g_mutex);
                    auto it = g_correlationMatrices.find(correlationId);
                    if (it == g_correlationMatrices.end()) return false;
                    RefitCorrelationMatrixState(it->second);
                }
                ShowCorrelationMatrixOnMain(correlationId);
                return true;
            },
            [](const std::string &dimensionalityId) {
                {
                    std::lock_guard<std::mutex> lock(g_mutex);
                    auto it = g_dimensionalityModels.find(dimensionalityId);
                    if (it == g_dimensionalityModels.end()) return false;
                    RefitDimensionalityState(it->second);
                }
                ShowDimensionalityOnMain(dimensionalityId);
                return true;
            },
            [](const std::string &dendrogramId) {
                {
                    std::lock_guard<std::mutex> lock(g_mutex);
                    auto it = g_dendrograms.find(dendrogramId);
                    if (it == g_dendrograms.end()) return false;
                    RefitDendrogramState(it->second);
                }
                ShowDendrogramOnMain(dendrogramId);
                return true;
            },
            [](const std::string &plotId, rlispstat::core::SmoothCurveScope scope) {
                std::lock_guard<std::mutex> lock(g_mutex);
                auto it = g_plots.find(plotId);
                if (it == g_plots.end()) return false;
                ToggleSmoothCurvesForScope(it->second, scope);
                return true;
            },
            [](const std::string &plotId, const std::string &panelId,
               rlispstat::core::SmoothCurveScope scope,
               const std::vector<rlispstat::core::SmoothCurveData> &curves) {
                std::lock_guard<std::mutex> lock(g_mutex);
                auto it = g_plots.find(plotId);
                if (it == g_plots.end() || it->second->kind != "trellis_scatterplot") return false;
                std::vector<rlispstat::core::SmoothCurveData> &existing =
                    it->second->trellisPanelSmoothCurves[panelId];
                existing.erase(std::remove_if(existing.begin(), existing.end(),
                    [&](const rlispstat::core::SmoothCurveData &curve) {
                        return curve.scope == scope;
                    }), existing.end());
                existing.insert(existing.end(), curves.begin(), curves.end());
                return true;
            }
        }
    });
    return dispatcher;
}

static void HandleClient(int client)
{
    CommandDispatcher &dispatcher = MacCommandDispatcher();
    std::string reply = dispatcher.dispatchSession(
        [client](std::string &line) { return ReadLine(client, line); });
    bool closeRequested = dispatcher.sessionClosed();
    if (!reply.empty()) {
        WriteReply(client, reply);
    }
    if (closeRequested) {
        g_running = false;
        if (g_serverFd >= 0) {
            close(g_serverFd);
            g_serverFd = -1;
        }
        TerminateApplicationOnMain();
    }
    close(client);
}

using rlispstat::platform::macos::WriteReplyToFifo;

static bool ParseDataFramePayload(const std::vector<std::string> &lines, size_t &cursor,
                                  const std::string &group, std::string &error)
{
    DataFrameModel df;
    bool parsed = false;
    if (!rlispstat::core::ParseDataFramePayload(lines, cursor, group, df, &parsed, error)) {
        return false;
    }
    if (!parsed) {
        return true;
    }
    std::lock_guard<std::mutex> lock(g_mutex);
    MacCommandDispatcher().applicationState().registerDataset(df);
    return true;
}

static std::string HandleCommandLines(const std::vector<std::string> &lines)
{
    return MacCommandDispatcher().dispatch(lines);
}

static std::string HandleCommandRequest(const CommandRequest &request,
                                        const std::vector<std::string> &lines)
{
    auto tryHandleNormalizedCommand = [](const CommandRequest &request) -> std::optional<std::string> {
        if (request.name == "WELCOME_LAUNCH") {
            if (request.args.size() < 3) return std::string("ERR malformed Welcome launch request");
            rlispstat::core::LaunchRequest launch;
            launch.environment = request.args[0] == "from_existing_r"
                ? rlispstat::core::LaunchEnvironment::FromExistingRSession
                : rlispstat::core::LaunchEnvironment::StandaloneApplication;
            g_applicationVersion = request.args[1];
            if (request.args[2] == "file" && request.args.size() > 3) {
                launch.initialFile = request.args[3];
            } else if (request.args[2] == "r_object") {
                launch.hasInitialRObject = true;
            } else if (request.args[2] == "request") {
                launch.hasConcreteOpenRequest = true;
            }
            const auto decision = rlispstat::core::DecideLaunch(launch);
            if (decision.shouldShowWelcome) ShowWelcomeOnMain();
            return std::string("OK");
        }
        if (request.name == "WELCOME_INITIAL_OPEN_ERROR") {
            if (request.args.size() < 2) return std::string("ERR malformed initial-open error");
            const std::string message = request.args[1];
            dispatch_async(dispatch_get_main_queue(), ^{
              NSAlert *alert = [[NSAlert alloc] init];
              [alert setMessageText:@"LinkEDA could not open the requested data."];
              [alert setInformativeText:ToNSString(message)];
              [alert addButtonWithTitle:@"Open another data source\u2026"];
              [alert addButtonWithTitle:@"Quit"];
              NSModalResponse result = [alert runModal];
              if (result == NSAlertFirstButtonReturn) ShowWelcomeOnMain();
              else DispatchCommand(nullptr, "FILE_CLOSE_WORKBENCH");
            });
            return std::string("OK");
        }
        if (request.name == "WELCOME_RECENT_NOTE") {
            if (request.args.empty()) return std::string("ERR missing recent path");
            NoteWelcomeRecentPathOnMain(request.args[0]);
            return std::string("OK");
        }
        if (request.name == "WELCOME_ACTION_RESULT") {
            if (request.args.size() < 4) return std::string("ERR malformed Welcome action result");
            const bool ok = request.args[1] == "ok";
            if (!ok) {
                ShowWorkbenchMessageOnMain(@"Welcome to LinkEDA", ToNSString(request.args[3]));
            }
            dispatch_async(dispatch_get_main_queue(), ^{
              if (g_welcomeController) [g_welcomeController refresh];
            });
            return std::string("OK");
        }
        if (request.name == "OPEN_R_EDIT_SESSION") {
            if (request.args.size() < 2) return std::string("ERR malformed R edit session");
            const std::string requestId = request.args[0];
            const std::string group = request.args[1];
            {
                std::lock_guard<std::mutex> lock(g_mutex);
                if (!DatasetExistsUnlocked(group)) return std::string("ERR dataset is not registered");
                auto existing = g_rEditSessionsByGroup.find(group);
                if (existing != g_rEditSessionsByGroup.end() &&
                    existing->second.requestId != requestId) {
                    return std::string("ERR this dataset is already being returned to another R call");
                }
                g_rEditSessionsByGroup[group] = {requestId, group};
                MarkActiveDatasetGroupUnlocked(group);
            }
            ShowDataSheetOnMain(group);
            UpdateActiveDatasetMenuOnMain();
            return std::string("OK");
        }
        if (request.name == "CLOSE_R_EDIT_SESSION") {
            if (request.args.empty()) return std::string("ERR malformed R edit session close");
            std::lock_guard<std::mutex> lock(g_mutex);
            for (auto it = g_rEditSessionsByGroup.begin(); it != g_rEditSessionsByGroup.end();) {
                if (it->second.requestId == request.args[0]) it = g_rEditSessionsByGroup.erase(it);
                else ++it;
            }
            return std::string("OK");
        }
        if (request.name == "OPEN_R_DATA_CHOOSER" ||
            request.name == "OPEN_R_DATA_CHOOSER_V2") {
            if (request.args.size() < 3) return std::string("ERR malformed R data chooser");
            const std::string requestId = request.args[0];
            const std::string environmentLabel = request.args[1];
            const long count = std::strtol(request.args[2].c_str(), nullptr, 10);
            const std::size_t fields = request.name == "OPEN_R_DATA_CHOOSER_V2" ? 4 : 3;
            if (count < 0 || request.args.size() < 3 + static_cast<std::size_t>(count) * fields) {
                return std::string("ERR malformed R data chooser entries");
            }
            std::vector<NativeRDataFrameChoice> choices;
            std::size_t cursor = 3;
            for (long index = 0; index < count; ++index) {
                choices.push_back({request.args[cursor],
                    std::atoi(request.args[cursor + 1].c_str()),
                    std::atoi(request.args[cursor + 2].c_str()),
                    fields == 4 ? request.args[cursor + 3] : "data.frame"});
                cursor += fields;
            }
            if (choices.empty()) return std::string("ERR no data frames are available");
            ShowRDataFrameChooserOnMain(requestId, environmentLabel, choices);
            return std::string("OK");
        }
        if (request.name == "R_DATA_ASSIGN_RESULT") {
            if (request.args.size() < 4) return std::string("ERR malformed R data assignment result");
            const bool ok = request.args[1] == "ok";
            ShowWorkbenchMessageOnMain(ok ? @"Data returned to R" : @"Return data to R",
                ToNSString(request.args[3]));
            return std::string("OK");
        }
        if (request.name == "IMPORT_DATA_RESULT") {
            if (request.args.size() < 2) return std::string("ERR malformed import result");
            const bool ok = request.args[0] == "ok";
            if (ok && request.args.size() >= 3 && !request.args[2].empty()) {
                NoteWelcomeRecentPathOnMain(request.args[2]);
                CloseWelcomeOnMain();
            } else if (!ok) {
                dispatch_async(dispatch_get_main_queue(), ^{
                  if (g_welcomeController) [g_welcomeController refresh];
                });
            }
            ShowWorkbenchMessageOnMain(
                ToNSString(ok ? NativeImportDialogTitle() : NativeImportFailedTitle()),
                ToNSString(request.args[1]));
            return std::string("OK");
        }
        if (request.name == "PLOT_EXPORT_RESULT") {
            if (request.args.size() < 5) return std::string("ERR malformed plot export result");
            const std::string requestId = request.args[0];
            std::optional<rlispstat::core::WindowNoteExportContent> exportNote;
            {
                std::lock_guard<std::mutex> lock(g_mutex);
                if (g_pendingPlotExportRequestIds.erase(requestId) == 0) {
                    return std::string("ERR unknown plot export request");
                }
                auto foundNote = g_pendingPlotExportNotes.find(requestId);
                if (foundNote != g_pendingPlotExportNotes.end()) {
                    exportNote = foundNote->second;
                    g_pendingPlotExportNotes.erase(foundNote);
                }
            }
            const bool ok = request.args[1] == "ok";
            const std::string operation = request.args[2];
            const std::string path = request.args[3];
            const std::string message = request.args[4];
            dispatch_async(dispatch_get_main_queue(), ^{
              NSString *nativePath = ToNSString(path);
              if (!ok) {
                  ShowWorkbenchMessageOnMain(@"Export", ToNSString(message));
                  return;
              }
              if (exportNote.has_value()) {
                  NSError *readError = nil;
                  NSString *svgSource = [NSString stringWithContentsOfFile:nativePath
                                                                   encoding:NSUTF8StringEncoding
                                                                      error:&readError];
                  if (!svgSource) {
                      ShowWorkbenchMessageOnMain(@"Export", @"The generated SVG could not be read to append Notes.");
                      if (operation == "copy") {
                          [[NSFileManager defaultManager] removeItemAtPath:nativePath error:nil];
                      }
                      return;
                  }
                  const std::string composed = rlispstat::core::ComposeSvgDocumentWithWindowNote(
                      std::string([svgSource UTF8String]), *exportNote);
                  NSError *writeError = nil;
                  if (![ToNSString(composed) writeToFile:nativePath
                                               atomically:YES
                                                 encoding:NSUTF8StringEncoding
                                                    error:&writeError]) {
                      ShowWorkbenchMessageOnMain(@"Export", @"Notes could not be appended to the SVG.");
                      if (operation == "copy") {
                          [[NSFileManager defaultManager] removeItemAtPath:nativePath error:nil];
                      }
                      return;
                  }
              }
              if (operation == "copy") {
                  NSData *data = [NSData dataWithContentsOfFile:nativePath];
                  if (!data) {
                      ShowWorkbenchMessageOnMain(@"Copy Plot", @"The generated SVG could not be read.");
                  } else {
                      NSPasteboard *pasteboard = [NSPasteboard generalPasteboard];
                      [pasteboard clearContents];
                      BOOL copied = [pasteboard setData:data forType:@"public.svg-image"];
                      if (copied) {
                          NSString *source = [[NSString alloc] initWithData:data encoding:NSUTF8StringEncoding];
                          if (source) [pasteboard setString:source forType:NSPasteboardTypeString];
                      } else {
                          ShowWorkbenchMessageOnMain(@"Copy Plot", @"The SVG could not be placed on the clipboard.");
                      }
                  }
                  [[NSFileManager defaultManager] removeItemAtPath:nativePath error:nil];
              }
            });
            return std::string("OK");
        }
        if (request.name == "WORKBENCH_MESSAGE") {
            if (request.args.size() < 2) return std::string("ERR malformed workbench message");
            ShowWorkbenchMessageOnMain(ToNSString(request.args[0]), ToNSString(request.args[1]));
            dispatch_async(dispatch_get_main_queue(), ^{
              if (g_welcomeController) [g_welcomeController refresh];
            });
            return std::string("OK");
        }
        switch (request.action) {
        case CommandAction::SetTrellisScatterplotX:
        case CommandAction::SetTrellisScatterplotY:
        case CommandAction::SetTrellisScatterplotCondition: {
            if (request.args.size() < 2) return std::string("ERR malformed trellis-scatterplot variable command");
            PlotModel *target = nullptr;
            {
                std::lock_guard<std::mutex> lock(g_mutex);
                auto found = g_plots.find(request.args[0]);
                if (found != g_plots.end()) target = found->second;
            }
            if (!target || target->kind != "trellis_scatterplot") return std::string("ERR no trellis scatterplot");
            std::string command = request.name + "|" + request.args[1];
            if (request.action == CommandAction::SetTrellisScatterplotCondition &&
                request.args.size() >= 3) command += "|" + request.args[2];
            DispatchCommand(target, command);
            return std::string("OK");
        }
        case CommandAction::SetTrellisScatterplotLayout:
        case CommandAction::SetTrellisScatterplotOrder: {
            if (request.args.size() < 2) return std::string("ERR malformed trellis-scatterplot display command");
            PlotModel *target = nullptr;
            {
                std::lock_guard<std::mutex> lock(g_mutex);
                auto found = g_plots.find(request.args[0]);
                if (found != g_plots.end()) target = found->second;
            }
            if (!target || target->kind != "trellis_scatterplot") return std::string("ERR no trellis scatterplot");
            DispatchCommand(target, request.name + "|" + request.args[1]);
            return std::string("OK");
        }
        case CommandAction::SetTrellisPlotType:
        case CommandAction::SetTrellisPlotTypeWithX:
        case CommandAction::AddTrellisConditionCategorical:
        case CommandAction::AddTrellisConditionEqualWidth:
        case CommandAction::AddTrellisConditionEqualCount:
        case CommandAction::RemoveTrellisCondition:
        case CommandAction::MoveTrellisConditionEarlier:
        case CommandAction::MoveTrellisConditionLater:
        case CommandAction::ConfigureTrellisConditionEqualWidth:
        case CommandAction::ConfigureTrellisConditionEqualCount:
        case CommandAction::ConfigureTrellisConditionBins:
        case CommandAction::SetTrellisConditionDimensionRows:
        case CommandAction::SetTrellisConditionDimensionColumns:
        case CommandAction::SetTrellisConditionDimensionNested:
        case CommandAction::SwapTrellisRowsAndColumns:
        case CommandAction::SetTrellisSplitVariable:
        case CommandAction::SetTrellisScaleMode:
        case CommandAction::SetTrellisBarMeasure:
        case CommandAction::SetTrellisHistogramMeasure:
        case CommandAction::SetTrellisHistogramBins:
        case CommandAction::ToggleTrellisConnectObservations: {
            if (request.args.empty()) return std::string("ERR malformed trellis command");
            PlotModel *target = nullptr;
            {
                std::lock_guard<std::mutex> lock(g_mutex);
                auto found = g_plots.find(request.args[0]);
                if (found != g_plots.end()) target = found->second;
            }
            if (!target || target->kind != "trellis_scatterplot") return std::string("ERR no trellis plot");
            std::string command = request.name;
            for (std::size_t index = 1; index < request.args.size(); ++index) {
                command += "|" + request.args[index];
            }
            DispatchCommand(target, command);
            return std::string("OK");
        }
        case CommandAction::SetTimeSeriesGroup: {
            if (request.args.size() < 2) return std::string("ERR malformed time-series grouping command");
            PlotModel *target = nullptr;
            {
                std::lock_guard<std::mutex> lock(g_mutex);
                auto found = g_plots.find(request.args[0]);
                if (found != g_plots.end()) target = found->second;
            }
            if (!target || target->kind != "time_series") return std::string("ERR no time-series plot");
            DispatchCommand(target, "TIME_SERIES_SET_GROUP|" + request.args[1]);
            return std::string("OK");
        }
        case CommandAction::SetTimeSeriesIdentification:
        case CommandAction::SetTimeSeriesLegendPosition: {
            if (request.args.size() < 2) return std::string("ERR malformed time-series display command");
            PlotModel *target = nullptr;
            {
                std::lock_guard<std::mutex> lock(g_mutex);
                auto found = g_plots.find(request.args[0]);
                if (found != g_plots.end()) target = found->second;
            }
            if (!target || target->kind != "time_series") return std::string("ERR no time-series plot");
            DispatchCommand(target, request.name + "|" + request.args[1]);
            return std::string("OK");
        }
        case CommandAction::Table1OpenStructured: {
            if (request.args.size() < 8) {
                return std::string("ERR malformed TABLE1_OPEN_STRUCTURED command");
            }
            Table1DisplayState state;
            size_t cursor = 0;
            state.id = request.args[cursor++];
            state.datasetId = request.args[cursor++];
            state.title = request.args[cursor++];
            state.groupVariable = request.args[cursor++];
            long varCount = std::strtol(request.args[cursor++].c_str(), nullptr, 10);
            if (varCount < 0 || cursor + (size_t)varCount > request.args.size()) return std::string("ERR invalid Table 1 variable count");
            for (long i = 0; i < varCount; ++i) state.variables.push_back(request.args[cursor++]);
            if (cursor >= request.args.size()) return std::string("ERR malformed Table 1 type payload");
            long typeCount = std::strtol(request.args[cursor++].c_str(), nullptr, 10);
            if (typeCount < 0 || cursor + (size_t)typeCount * 2 > request.args.size()) return std::string("ERR invalid Table 1 type count");
            for (long i = 0; i < typeCount; ++i) {
                std::string variable = request.args[cursor++];
                std::string type = request.args[cursor++];
                state.variableTypes[variable] = type;
            }
            if (cursor >= request.args.size()) return std::string("ERR malformed Table 1 column payload");
            long columnCount = std::strtol(request.args[cursor++].c_str(), nullptr, 10);
            if (columnCount < 0 || cursor + (size_t)columnCount > request.args.size()) return std::string("ERR invalid Table 1 column count");
            for (long i = 0; i < columnCount; ++i) state.columns.push_back(request.args[cursor++]);
            if (cursor >= request.args.size()) return std::string("ERR malformed Table 1 row payload");
            long rowCount = std::strtol(request.args[cursor++].c_str(), nullptr, 10);
            if (rowCount < 0) return std::string("ERR invalid Table 1 row count");
            for (long i = 0; i < rowCount; ++i) {
                if (cursor + 9 > request.args.size()) return std::string("ERR malformed Table 1 row");
                Table1DisplayRow row;
                row.rowIndex = std::atoi(request.args[cursor++].c_str());
                row.rowType = request.args[cursor++];
                row.variable = request.args[cursor++];
                row.level = request.args[cursor++];
                row.label = request.args[cursor++];
                row.p = request.args[cursor++];
                row.test = request.args[cursor++];
                row.detail = request.args[cursor++];
                long valueCount = std::strtol(request.args[cursor++].c_str(), nullptr, 10);
                if (valueCount < 0 || cursor + (size_t)valueCount > request.args.size()) return std::string("ERR invalid Table 1 row value count");
                for (long vi = 0; vi < valueCount; ++vi) row.values.push_back(request.args[cursor++]);
                if (!row.p.empty()) state.showP = true;
                if (!row.test.empty()) state.showTest = true;
                state.rows.push_back(row);
            }
            if (cursor >= request.args.size()) return std::string("ERR malformed Table 1 footnote payload");
            long noteCount = std::strtol(request.args[cursor++].c_str(), nullptr, 10);
            if (noteCount < 0 || cursor + (size_t)noteCount > request.args.size()) return std::string("ERR invalid Table 1 footnote count");
            for (long i = 0; i < noteCount; ++i) state.footnotes.push_back(request.args[cursor++]);
            if (cursor + 3 < request.args.size()) {
                const std::string scopeKind = request.args[cursor++];
                const std::string scopeDescription = request.args[cursor++];
                const long totalRows = std::max<long>(0, std::strtol(request.args[cursor++].c_str(), nullptr, 10));
                const long scopeRowCount = std::strtol(request.args[cursor++].c_str(), nullptr, 10);
                if (scopeRowCount < 0 || cursor + (size_t)scopeRowCount > request.args.size()) {
                    return std::string("ERR invalid Table 1 analysis-scope row count");
                }
                std::vector<int> scopeRows;
                for (long i = 0; i < scopeRowCount; ++i) {
                    scopeRows.push_back(std::atoi(request.args[cursor++].c_str()));
                }
                state.dataScope = scopeKind == "explicit"
                    ? rlispstat::core::ExplicitAnalysisScope(
                          state.datasetId, scopeRows,
                          rlispstat::core::AnalysisScopeSourceKind::OtherExplicitSubset,
                          scopeDescription, (size_t)totalRows)
                    : rlispstat::core::AllObservationsAnalysisScope(
                          state.datasetId, (size_t)totalRows);
                state.dataScopeCaptured = true;
            }
            if (state.columns.empty()) state.columns.push_back("Overall");
            ShowTable1StateOnMain(state);
            return "OK\t" + state.id;
        }
        case CommandAction::Table1OpenText: {
            if (request.args.size() < 3) {
                return std::string("ERR malformed TABLE1_OPEN command");
            }
            std::string tableId = request.args[0];
            std::string group = request.args[1];
            long lineCount = std::strtol(request.args[2].c_str(), nullptr, 10);
            if (lineCount < 0 || request.args.size() < 3 + (size_t)lineCount) {
                return std::string("ERR invalid Table 1 payload");
            }
            std::ostringstream text;
            for (long i = 0; i < lineCount; ++i) {
                if (i > 0) text << "\n";
                text << request.args[3 + (size_t)i];
            }
            ShowTable1TextOnMain(tableId, group, text.str());
            return "OK\t" + tableId;
        }
        default:
            break;
        }
        return std::nullopt;
    };

    if (auto handled = tryHandleNormalizedCommand(request)) {
        return *handled;
    }

    const std::string &cmd = request.name;
    if (rlispstat::core::IsNativeUiDispatchCommandName(cmd)) {
        DispatchCommand(ActivePlot(), cmd);
        return "OK";
    }
    return "ERR unknown command";
}

static std::string AppendMainRTasks(const std::string &reply)
{
    if (!MainRReplyAcceptsTaskAppend(reply)) {
        return reply;
    }
    MainRTaskBatch batch;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        for (auto &plotEntry : g_plots) {
            for (auto &curve : plotEntry.second->smoothCurves) {
                if (!curve.ok && !curve.message.empty()) {
                    PlotModel *plot = plotEntry.second;
                    if (plot->kind == "trellis_scatterplot" &&
                        plot->trellisSpecificationInitialized &&
                        plot->trellisSpecification.plotType == TrellisPlotType::Scatter) {
                        std::map<std::string, std::string> splitColors;
                        const std::vector<std::string> splitLevels =
                            rlispstat::core::OrderedUniqueBarplotLevels(plot->trellisPointSplitValues);
                        const std::vector<std::string> palette = rlispstat::core::BarplotPaletteOrder();
                        for (std::size_t splitIndex = 0; splitIndex < splitLevels.size(); ++splitIndex) {
                            if (!palette.empty()) splitColors[splitLevels[splitIndex]] =
                                palette[splitIndex % palette.size()];
                        }
                        for (const std::string &panelId : plot->trellisPanelLevels) {
                            std::vector<int> rows;
                            std::vector<std::string> colorKeys;
                            for (std::size_t index = 0; index < plot->points.size(); ++index) {
                                if (index < plot->trellisPointPanels.size() &&
                                    plot->trellisPointPanels[index] == panelId) {
                                    rows.push_back(plot->points[index].row);
                                    if (!plot->trellisSpecification.splitVariableId.empty() &&
                                        index < plot->trellisPointSplitValues.size()) {
                                        colorKeys.push_back(splitColors[plot->trellisPointSplitValues[index]]);
                                    }
                                }
                            }
                            if (!rows.empty()) {
                                batch.trellisSmoothTasks.push_back({
                                    plotEntry.first, plot->group, panelId, curve.scope,
                                    plot->trellisSpecification.xVariableId,
                                    plot->trellisSpecification.yVariableId,
                                    plot->smoothSpan, std::move(rows), std::move(colorKeys)
                                });
                            }
                        }
                    } else {
                        batch.smoothTasks.push_back({
                            plotEntry.first,
                            plot->group,
                            curve.scope,
                            plot->xLabel,
                            plot->yLabel,
                            plot->smoothSpan
                        });
                    }
                    curve.message.clear();
                }
            }
        }
        batch.compareMeansTasks = g_pendingCompareMeansTasks;
        batch.linearGLMTasks = g_pendingLinearGLMTasks;
        batch.modelTrellisTasks = g_pendingModelTrellisTasks;
        batch.regressionComparisonTasks = g_pendingRegressionComparisonTasks;
        batch.generalizedGLMTasks = g_pendingGeneralizedGLMTasks;
        batch.mixedModelTasks = g_pendingMixedModelTasks;
        batch.dimensionalityTasks = g_pendingDimensionalityTasks;
        batch.trellisPanelAnalysisTasks = g_pendingTrellisPanelAnalysisTasks;
        batch.importDataTasks = g_pendingImportDataTasks;
        batch.dataReturnTasks = g_pendingDataReturnTasks;
        batch.dataChoiceTasks = g_pendingDataChoiceTasks;
        batch.dataBrowseTasks = g_pendingDataBrowseTasks;
        batch.welcomeActionTasks = g_pendingWelcomeActionTasks;
        batch.dataAssignTasks = g_pendingDataAssignTasks;
        batch.plotExportTasks = g_pendingPlotExportTasks;
        g_pendingCompareMeansTasks.clear();
        g_pendingLinearGLMTasks.clear();
        g_pendingModelTrellisTasks.clear();
        g_pendingRegressionComparisonTasks.clear();
        g_pendingGeneralizedGLMTasks.clear();
        g_pendingMixedModelTasks.clear();
        g_pendingDimensionalityTasks.clear();
        g_pendingTrellisPanelAnalysisTasks.clear();
        g_pendingImportDataTasks.clear();
        g_pendingDataReturnTasks.clear();
        g_pendingDataChoiceTasks.clear();
        g_pendingDataBrowseTasks.clear();
        g_pendingWelcomeActionTasks.clear();
        g_pendingDataAssignTasks.clear();
        g_pendingPlotExportTasks.clear();
    }
    return AppendMainRTaskMessages(reply, batch);
}

static void ServerLoopFifo(const std::string &path)
{
    unlink(path.c_str());
    if (mkfifo(path.c_str(), 0600) != 0) {
        std::fprintf(stderr, "mkfifo failed for %s: %s\n", path.c_str(), std::strerror(errno));
        std::exit(2);
    }

    while (g_running) {
        int fd = open(path.c_str(), O_RDONLY);
        if (fd < 0) {
            if (g_running) {
                std::fprintf(stderr, "open fifo failed: %s\n", std::strerror(errno));
            }
            continue;
        }

        std::string text;
        char buffer[8192];
        ssize_t nread;
        while ((nread = read(fd, buffer, sizeof(buffer))) > 0) {
            text.append(buffer, buffer + nread);
        }
        close(fd);

        std::vector<std::string> lines = SplitLines(text);
        if (lines.empty() || lines[0].rfind("REPLY ", 0) != 0) {
            continue;
        }
        std::string replyPath = lines[0].substr(6);
        std::vector<std::string> command(lines.begin() + 1, lines.end());
        std::string reply = HandleCommandLines(command);
        reply = AppendMainRTasks(reply);
        WriteReplyToFifo(replyPath, reply);
    }

    unlink(path.c_str());
    // In the FIFO build the command reply must be fully written and the FIFO
    // removed before AppKit exits.  This ordering keeps the calling R session
    // responsive when LinkEDA is reopened immediately after choosing Quit.
    TerminateApplicationOnMain();
}

static void ServerLoop(int port)
{
    g_serverFd = socket(AF_INET, SOCK_STREAM, 0);
    if (g_serverFd < 0) {
        std::fprintf(stderr, "socket failed: %s\n", std::strerror(errno));
        std::exit(2);
    }

    int yes = 1;
    setsockopt(g_serverFd, SOL_SOCKET, SO_REUSEADDR, &yes, sizeof(yes));

    sockaddr_in addr;
    std::memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = htonl(INADDR_LOOPBACK);
    addr.sin_port = htons((uint16_t)port);

    if (bind(g_serverFd, (sockaddr *)&addr, sizeof(addr)) < 0) {
        std::fprintf(stderr, "bind failed on port %d: %s\n", port, std::strerror(errno));
        std::exit(2);
    }
    if (listen(g_serverFd, 16) < 0) {
        std::fprintf(stderr, "listen failed: %s\n", std::strerror(errno));
        std::exit(2);
    }

    while (g_running) {
        int client = accept(g_serverFd, nullptr, nullptr);
        if (client < 0) {
            if (g_running) {
                std::fprintf(stderr, "accept failed: %s\n", std::strerror(errno));
            }
            continue;
        }
        HandleClient(client);
    }
}

int rlispstat::platform::macos::RunBackend(int argc, char **argv)
{
    if (argc > 0 && argv != nullptr && argv[0] != nullptr) {
        @autoreleasepool {
            NSString *executablePath = [NSString stringWithUTF8String:argv[0]];
            if (![executablePath isAbsolutePath]) {
                executablePath = [[[NSFileManager defaultManager] currentDirectoryPath]
                    stringByAppendingPathComponent:executablePath];
            }
            executablePath = [executablePath stringByStandardizingPath];
            NSString *packageRoot = [[executablePath stringByDeletingLastPathComponent]
                stringByDeletingLastPathComponent];
            g_applicationRootPath = [packageRoot fileSystemRepresentation];
            NSString *iconPath = [packageRoot stringByAppendingPathComponent:@"assets/LinkEDA.png"];
            g_applicationIconPath = [iconPath fileSystemRepresentation];
            NSString *descriptionPath = [packageRoot stringByAppendingPathComponent:@"DESCRIPTION"];
            NSString *description = [NSString stringWithContentsOfFile:descriptionPath
                encoding:NSUTF8StringEncoding error:nil];
            for (NSString *line in [description componentsSeparatedByCharactersInSet:
                     [NSCharacterSet newlineCharacterSet]]) {
                if ([line hasPrefix:@"Version:"]) {
                    NSString *version = [[line substringFromIndex:[@"Version:" length]]
                        stringByTrimmingCharactersInSet:[NSCharacterSet whitespaceCharacterSet]];
                    g_applicationVersion = [version UTF8String];
                    break;
                }
            }
        }
    }

    BackendPlatformServices services;
    services.configure = [](const BackendLaunchOptions &options) {
        g_rscriptPath = options.rscriptPath;
        g_mainRNotifyPath = options.notifyFifoPath;
    };
    services.initializeApplication = []() {
        [[NSProcessInfo processInfo] setProcessName:@"LinkEDA"];
        [NSWindow setAllowsAutomaticWindowTabbing:YES];
        [NSApplication sharedApplication];
        [NSApp setActivationPolicy:NSApplicationActivationPolicyRegular];
        if (!g_applicationIconPath.empty()) {
            NSImage *icon = [[NSImage alloc] initWithContentsOfFile:ToNSString(g_applicationIconPath)];
            if (icon != nil) {
                [NSApp setApplicationIconImage:icon];
                [icon release];
            }
        }
        InstallApplicationMenuBar();
        [NSApp activateIgnoringOtherApps:YES];
        ShowWelcomeOnMain();
    };
    services.startCommandServer = [](const BackendLaunchOptions &options) {
        g_controlFifoPath = options.fifoPath;
        std::thread server([options]() {
            if (!options.fifoPath.empty()) {
                ServerLoopFifo(options.fifoPath);
            } else {
                ServerLoop(options.port);
            }
        });
        server.detach();
        if (options.parentPid > 0) {
            const long parentPid = options.parentPid;
            std::thread monitor([parentPid]() {
                while (g_running) {
                    if (kill((pid_t)parentPid, 0) != 0 && errno == ESRCH) {
                        g_running = false;
                        if (g_serverFd >= 0) {
                            close(g_serverFd);
                            g_serverFd = -1;
                        }
                        dispatch_async(dispatch_get_main_queue(), ^{
                            [NSApp terminate:nil];
                        });
                        break;
                    }
                    usleep(250000);
                }
            });
            monitor.detach();
        }
    };
    services.runEventLoop = []() {
        [NSApp run];
    };
    services.stopCommandServer = []() {
        g_running = false;
        if (g_serverFd >= 0) {
            close(g_serverFd);
        }
    };
    return rlispstat::core::RunBackendApplication(argc, argv, services);
}
